      SUBROUTINE NSTOUT
C     =================
C
C     Diagnostic print of the input flags and parameters
c
      use accura
      use basics
      use atomic
      use alipar
      use iterat
      use modelq
      use odfpar


      implicit none

      integer :: ichc

      if(lchc) ichc=1
      write(6,602)
