     *             CHMAX ,ILDER ,IBPOPE,CHMAXT,NLAMT
      write(6,603) INTRPL,ICHANG,
     *             INHE  ,INRE  ,INPC  ,INSE  ,INMP  ,
     *             INDL  ,NDRE  ,TAUDIV,IDLST ,NRETC ,
     *             ICONV ,IPRESS,ITEMP ,
     *             IOPADD,IRSCT ,IOPHMI,IOPH2P,
     *             IACC  ,IACD  ,KSNG  ,ITEK  ,ORELAX,
     *             IWINBL,
