     *         9872.,10620.,11590.,12410.,13260.,14420.,15162.,
     *         65660.,69137.4/
      data u26/63.737,130.563,247.22,442.,605.,799.,1008.,1218.38,
     *         1884.,2114.,2341.,2668.,2912.,3163.,3686.,3946.82,
     *         10180.,10985.,11850.,12708.,13620.,14510.,15797.,
     *         16500.,71203.,74829.6/
      data u28/61.6,146.542,283.8,443.,613.5,870.,1070.,1310.,1560.,
     *         1812.,2589.,2840.,3100.,3470.,3740.,4020.,4606.,
     *         4896.2,12430.,13290.,14160.,15280.,16220.,17190.,
     *         18510.,19351.,82984.,86909.4/
C
C
C     ATOINI serves as an auxiliary procedure for START
C     Input of basic parameters for individual chemical species
C
C     An element (hydrogen through zinc) can be considered in one of
C     the three following options:
C     1. explicitly - some of energy levels of some of its ionization
C                     states are considered explicitly, ie. their
C                     populations are determined by solving statistical
C                     equilibrium
C     2. implicitly - the atom is assumed not to contribute to
C                     opacity; but is allowed to contribute to the
C                     total number of particles and to the total charge;
C                     the latter is evaluated assuming LTE ionization
C                     balance, ie. by solving a set of Saha equations
C     3. not considered at all
C
C     Input:
C     NATOMS -  the highest atomic number of an element that is
C               considered (explicitly or non-explicitly)
C            <  0 - then NATOMS=-NATOMS, and all Opacity Project
C                   species are treated as with MODPF>0, i.e.
C                   their partition functions are evaluated from
C                   the Opacity Project ionization fractions
C
C     For each element from 1 (hydrogen) to NATOMS, the following
C     parameters:
C
C     MA     =  0  - if the element is not considered (option 3)
C            =  1  - if the element is non-explicit (option 2)
C            =  2  - if the element is explicit (option 1)
C     ABN    -  if ABN=0, solar abundance is assumed (given above;
C                         abundance here is assumed as relative
C                         to hydrogen by number
C               if ABN>0, non-solar abundance ABN is assumed; in an
C                         arbitrary scale
C               if ABN<0, non-solar abundance ABN is assumed;
C                         (-ABN times the solar value)
C               if ABN>1.e6, depth-dpendent abundance (additional input)
C
c
      iabset=0
      read(ibuff,'(a80)') dum
      read(dum,*,iostat=kstat) natoms,iabset
      if(kstat.ne.0) READ(dum,*) NATOMS
      if(natoms.eq.0) then
         do id=1,nd
            ytot(id)=1.11
            wmy(id)=1.41
            wmm(id)=2.17e-24
         end do
         iatref=0
         return
      end if
c
      do i=1,matom
         iadop(i)=0
         if(iabset.eq.1) then
            d(2,i)=10.**(abun1(i)-12.)
          else if(iabset.ne.2) then
            d(2,i)=10.**(abun0(i)-12.)
         end if
      end do
c
      WRITE(6,*)
      WRITE(6,*) ' CHEMICAL ELEMENTS INCLUDED'
      WRITE(6,*) ' --------------------------'
      WRITE(6,*)
      write(6,*) '  ELEMENT   MAX.ION      ABUNDANCE'
      WRITE(6,*)

      IAT=0
      IREFA=0
      IFOPPF=0
      IF(NATOMS.LT.0) THEN
         NATOMS=-NATOMS
         IFOPPF=2
      END IF
C
      natms=natoms
      if(ifmol.gt.0) natms=92
      write(*,*) 'natoms',natoms
      DO I=1,NATMS
         LGR(I)=.TRUE.
         LRM(I)=.TRUE.
         IATEX(I)=-1
         if(i.le.natoms) then
            READ(IBUFF,*) MA,ABN,MODPF0
          else
            ma=1
            abn=0.
            modpf0=0
         end if
         IF(MA.EQ.0) CYCLE
         TYPAT(I)=DYP(I)
         AMAS(I)=D(1,I)
         ABND(I)=D(2,I)
c        write(*,*) 'atoms',i,typat(i),ma
         IF(MA.EQ.0.or.i.gt.natoms) then
            abnd(i)=d(2,i)*1.e-10
            enev(i,1)=xio(1,i)
            enev(i,2)=xio(2,i)
            amas(i)=d(1,i)
            DO ID=1,ND
               ABNDD(I,ID)=ABND(I)
            END DO
            CYCLE
         end if
         IONIZ(I)=int(D(3,I))
         MODPF(I)=MODPF0
C
C        increase the standard highest ionization for Teff larger
C        than 50000 K for N, O, Ne, and Fe
C
         IF(TEFF.GT.5.e4) THEN
            SELECT CASE (I)
               CASE(7) 
                  IONIZ(I)=6
               CASE(8) 
                  IONIZ(I)=7
               CASE(10) 
                  IONIZ(I)=9
               CASE(26) 
                  IONIZ(I)=9
            END SELECT
         END IF
         IF(TEFF.GT.1.E6) IONIZ(I)=I+1      
c        write(*,*) 'atom2',i,ioniz(i),modpf(i)
C
         DO J=1,8
            ENEV(I,J)=xio(J,I)
         END DO
c        write(*,*) 'enev',(enev(i,j),j=1,ioniz(i))
c
         if(i.ge.9.and.i.le.30) then
            do j=9,17
               enev(i,j)=xio2(j-8,i-8)
            end do
         end if
         if(i.ge.18.and.i.le.30) then
            do j=18,26
               enev(i,j)=xio3(j-17,i-17)
            end do
         end if
c
         LGR(I)=.FALSE.
         IF(MODPF(I).GT.0) IFOPPF=1
         IF(IFOPPF.EQ.2.and.idat(i).gt.0) MODPF(I)=1
         if(modpf(i).gt.0) then
            if(idat(i).eq.0) modpf(i)=0
            if(modpf(i).gt.0) then
               ioniz(i)=i+1
               if(i.ge.10) then
                  do j=9,i
                     enev(i,j)=uu(j,idat(i))*0.1239529d0
                  end do
               end if
            end if
         end if
         IF(ABN.GT.0) ABND(I)=ABN
         IF(ABN.LT.0) ABND(I)=ABS(ABN)*D(2,I)
c        IF(ION.NE.0) IONIZ(I)=ION
         IF(ABN.GT.1.E16) THEN
            READ(IBUFF,*) (ABNDD(I,ID),ID=1,ND)
          ELSE
            DO ID=1,ND
               ABNDD(I,ID)=ABND(I)
            END DO
         END IF
c     write(*,"('atom  ',a,3i3,1pe10.2)") typat(i),i,ma,ioniz(i),abnd(i)
         IF(MA.EQ.1) THEN
            LRM(I)=.FALSE.
            IATEX(I)=0
          ELSE
            IAT=IAT+1
            IIFIX(IAT)=0
            IF(MA.LE.-2) IIFIX(IAT)=1
            IATEX(I)=IAT
c          write(*,*) 'i,iatex',i,iatex(i),iat
            IF(IAT.EQ.IATREF) THEN
               IREFA=I
               DO ID=1,ND
                  ABNREF(ID)=ABNDD(I,ID)
               END DO
            END IF
C
C           store parameters for explicit atoms
C
            AMASS(IAT)=AMAS(I)*HMASS
            NUMAT(IAT)=I
            if(iabs(ma).eq.3) iadop(i)=1
         END IF
      END DO
C
C     renormalize abundances to have the standard element abundance
C     equal to unity
C
      if(abnref(1).eq.0.or.ioptab.gt.0) then
         do id=1,nd
            abnref(id)=1.
         end do
      end if
c
      DO I=1,NATOMS
         IAT=IATEX(I)
         IF(IAT.LT.0) CYCLE
         DO ID=1,ND
            ABNDD(I,ID)=ABNDD(I,ID)/ABNREF(ID)
            YTOT(ID)=YTOT(ID)+ABNDD(I,ID)
            WMY(ID)=WMY(ID)+ABNDD(I,ID)*AMAS(I)
         END DO
         ABNR=ABND(I)/D(2,I)
         IF(IAT.EQ.0) THEN
            WRITE(6,'(I4,3X,A5,I3,1P2E14.2)') 
     *      I,TYPAT(I),IONIZ(I),ABND(I),ABNR
          ELSE
            DO ID=1,ND
               ABUND(IAT,ID)=ABNDD(I,ID)
            END DO
            WRITE(6,"(I4,3X,A5,I3,1P2E14.2,3X,'EXPLICIT: IAT=',I3)") 
     *      I,TYPAT(I),IONIZ(I),ABND(I),ABNR,IAT
         END IF
      END DO

      DO ID=1,ND
         WMM(ID)=WMY(ID)*HMASS/YTOT(ID)
      END DO

      write(6,"(/' YTOT WMY WMM ',1P3e15.5/)") ytot(1),wmy(1),wmm(1)
c
c     initialization of the Opacity Project ionization fractions
c     (if required)
c
CCC   if(ifoppf.gt.0) call opfrac(0,0,t,ane,pf,fra)
c
      RETURN
C
      END SUBROUTINE ATOINI


! ***********************************************************************


      SUBROUTINE RDATA(ION)
C     =====================
C
      use accura
      use alipar
      use atomic
      use basics
      use iterat
      use modelq
      use odfpar
      use hydodf
      use hyglin

      implicit none

      INTEGER, INTENT(IN) :: ION
      CHARACTER(LEN=1)   :: A
      CHARACTER(len=100) :: DUM
      LOGICAL            :: LIJP,LOD34,LCMP

      INTEGER   :: I,IE,N0I,NKI,IQ,IDUM1,IFFR0,IFIT,IFRQ1,IHI,IHYDP0,II0
      INTEGER   :: IIP,JJP,II,JJ,MODE,IFANCY,ICOLIS,IFRQ0,NCOL,J20
      INTEGER   :: IOS,KSTAT,IIC,ILLIM,INDXPA,INTM,IT0,ITYPE,NI1
      INTEGER   :: JCORR,JJ0,JJCX,JJTR,K1,K2,K3,K4,NCTEMP,NF,NFIT
      INTEGER   :: IMER,ITR,IC,IP,IL
      REAL(DP)  :: OSC,CPARAM,GH,DUM1,FR0INP,GAMRL,SUF,X1,X2,X3,XITR
      REAL(DP)  :: X,E,E0,XMAX,FR0PCI,ALAM,SIG0C,XJ,XQ,ZZ,XJJ,XJTR,XII
      integer, save :: itrprev=0
c
      ihydp0=0
      IUNIT=21
      OPEN(IUNIT,FILE=FIDATA(ION),STATUS='OLD')
C
C     read the first record - a label for the energy level input
C
      READ(IUNIT,"(A1)") A
C
C   -----------------------------------------------------
C   input parameters for explicit energy levels
C   -----------------------------------------------------
C
      DO IL=1,NLEVS(ION)
         I=IL+NFIRST(ION)-1
         IE=IEL(I)
         N0I=NFIRST(IE)
         NKI=NNEXT(IE)
         IQ=I-N0I+1
         X=IQ*IQ
         READ(IUNIT,*)
     *   ENION(I),G(I),NQUANT(I),TYPLEV(I),ifwop(i),FRODF(I),IMODL(I)
         E=ABS(ENION(I))
         E0=E
         IF(E.EQ.0.) E0=EH*IZ(IE)*IZ(IE)/X 
         IF(E.GT.1.e-7.AND.E.LT.1.e2) E0=1.6018e-12*E
         IF(E.GT.100..AND.E.LT.1.e7) E0=1.9857e-16*E
         IF(E.GT.1.e7) E0=H*E
         IF(ENION(I).GE.0.) THEN
            ENION(I)=E0
          ELSE
            ENION(I)=-E0
         END IF
         IF(G(I).EQ.0.) G(I)=TWO*X
         IF(NQUANT(I).EQ.0) NQUANT(I)=IQ
         iltlev(i)=0
         if(nquant(i).lt.0) then
            iltlev(i)=1
            nquant(i)=iabs(nquant(i))
         end if
         if(ispodf.eq.0 .and. ifwop(i).ge.2) ifwop(i)=0
         if(nodiss.gt.0) IFWOP=0
         if(ifwop(i).lt.0) then
            enion(i)=0.
            NMER=NMER+1
            IMER=NMER
            IMRG(I)=IMER
            IIMER(IMER)=I
         endif
         LBPFX = LBPFX .AND. IMODL(I).EQ.0 .AND. IIFIX(IATM(I)).EQ.0
         if(imodl(i).gt.100) then
            iguide(i)=imodl(i)-100+NFIRST(ION)-1
            imodl(i)=6
         end if
c        if(ion.GE.28) write(*,"('ionle',6i5,1p2e10.3)") 
c    *   il,i,nquant(i),iltlev(i),imrg(i),imodl(i),enion(i),g(i)
      END DO
c
C ----------------------------------------------------------------------
C
C   skip lines if more levels than needed, and skip the continuum
C   transition label
C
      DO
         READ(IUNIT,'(a1)') A
         IF(A.EQ.'*') EXIT
      END DO
         II0=NFIRST(ION)-1
         ILLIM=NLLIM(ION)+II0
         JCORR=0
         JJCX=0
c     END DO
C
C   -----------------------------------------------------
C   input parameters for continuum transitions
C   -----------------------------------------------------
C
      CONTLOOP : DO
      READ(IUNIT,'(A100)',IOSTAT=IOS) DUM
         IF(IOS.NE.0) EXIT CONTLOOP
         READ(DUM,*,IOSTAT=KSTAT) II,JJ,MODE,
     *        IFANCY,ICOLIS,
     *        IFRQ0,IFRQ1,OSC,CPARAM,NCOL
         IF (KSTAT.NE.0) THEN
            READ(DUM,*,IOSTAT=IOS) II,JJ,MODE,
     *        IFANCY,ICOLIS,
     *        IFRQ0,IFRQ1,OSC,CPARAM
            NCOL=0
         END IF
         IFFR0=0
         IF(IABS(MODE).GT.100) THEN
            IF(MODE.GT.0) MODE=MODE-100
            IF(MODE.LT.0) MODE=MODE+100
            IFFR0=1
            READ(IUNIT,*) FR0INP
            IF(FR0INP.LT.1.E10) FR0INP=2.997925e18/FR0INP
         END IF
         NTRANS=NTRANS+1
         ITR=NTRANS
C
         IF(JJ.LT.1000) THEN
            IF(II.EQ.1 .OR. JJCX.EQ.1) JCORR=NLEVS(ION)+1-JJ
            II=II+II0
            JJ=JJ+II0+JCORR
          ELSE
            II=II+II0
            JJCX=1
         END IF
         ILOW(ITR)=II
         IUP(ITR)=JJ
         INDEXP(ITR)=MODE
         OSC0(ITR)=OSC
         ICOL(ITR)=ICOLIS
         CPAR(ITR)=CPARAM
         LALI(ITR)=.FALSE.
         LEXP(ITR)=.FALSE.

         FR0PCI=ZERO
         IF(IABS(MODE).EQ.5 .OR. IABS(MODE).EQ.15) THEN
            READ(IUNIT,*) FR0PCI
            if(ion.eq.ielh) then
               if(ii.eq.1.and.cutlym.ne.0) fr0pci=cutlym
               if(ii.eq.2.and.cutbal.ne.0) fr0pci=cutbal
            end if
            IF(FR0PCI.LT.1.E10) FR0PCI=2.997925e18/FR0PCI
         END IF
         FR0PC(ITR)=FR0PCI

         NTRANC=NTRANC+1
         IC=NTRANC
         if(ifancy.eq.15) then
            ibf(ic)=ifancy
            itrbf(ic)=itr
            call rdatax(itr,ic,IUNIT)
            CYCLE CONTLOOP
         end if
         IF(ITRA(II,JJ).EQ.0) THEN
            ITRA(II,JJ)=ITR
c          write(*,*) 'ii,jj,itra(ii,jj)',ii,jj,itra(ii,jj)
          ELSE
            ICOL(ITR)=99
         END IF
         IE=IEL(II)
         N0I=NFIRST(IE)
         NKI=NNEXT(IE)
         LINE(ITR)=.FALSE.
         IFC0(ITR)=IFRQ0
         IFC1(ITR)=IFRQ1
         FR0(ITR)=(ENION(II)-ENION(JJ)+ENION(NKI))/H
         IF(IFFR0.EQ.1) FR0(ITR)=FR0INP
C
C      -----------------------------------------------------
C      Additional input parameters for continuum transitions
C      -----------------------------------------------------
C
C        Only for IFANCY = 2, 3, or 4
C        S0, ALF, BET, GAM  - parameters for evaluation the
C            photoionization cross-section
C
         IF(IFANCY.GE.2.AND.IFANCY.LE.4) THEN
            READ(IUNIT,*) S0CS(IC),ALFCS(IC),BETCS(IC),GAMCS(IC)
          ELSE IF(IFANCY.EQ.6) THEN
            READ(IUNIT,*) (CTOP(IFIT,IC),IFIT=1,6)
         END IF
C
C      -----------------------------------------------------
C      Additional input parameters for continuum transitions -TOPBASE DATA
C      -----------------------------------------------------
C
C        Only for IFANCY > 100 there are IFANCY-100 fit points
C
C        XTOP(MFIT,MCROSS) -  x = alog10(nu/nu0) of a fit point
C        CTOP(MFIT,MCROSS) -  sigma = alog10(sigma/10^-18) of a fit point
C
C        there are IFANCY-100 fit points
C
         IF(IFANCY.GT.100) THEN
            NFIT=IFANCY-100
            IF(NFIT.GT.MFIT) CALL QUIT('nfit.gt.mfit',nfit,mfit)
            READ(IUNIT,*) (XTOP(IFIT,IC),IFIT=1,NFIT)
            READ(IUNIT,*) (CTOP(IFIT,IC),IFIT=1,NFIT)
         END IF
C
C      -----------------------------------------------
C      Additional input parameters for continuum transitions -COLLISIONAL DATA
C      ----------------------------------------------
         IF (NCOL.NE.0) THEN
            DUM1=0
            DO IIC=1,NCOL
               READ(IUNIT,*) ITYPE, NCTEMP
CCC             IF (ITYPE.GT.MXTCOL) CALL QUIT('itype.gt.mxtcol',ITYPE,MXTCOL)
               READ(IUNIT,*) (CTEMP(ITYPE,IFIT,ITR),IFIT=1,NCTEMP)
               READ(IUNIT,*) (CRATE(ITYPE,IFIT,ITR),IFIT=1,NCTEMP)
               DUM1=DUM1+2**(ITYPE-1)
               idum1=ifix(real(dum1))
            END DO
            IF (ICOL(ITR).EQ.99) CYCLE
            IF (MOD(DUM1,TWO).EQ.1.and.ICOL(ITR).lt.10) THEN
c           IN ORDER TO KEEP THE INFO FOR ELECTRON COLLISIONS FROM ICOL
               ICOL(ITR)=1000*iDUM1
            ELSE
               IF (ICOL(ITR).LT.0) THEN
                  ICOL(ITR)=-1000*iDUM1+ICOL(ITR)-1
               ELSE
                  ICOL(ITR)=1000*iDUM1+ICOL(ITR)+1
               ENDIF
            END IF
c
         END IF
C
         IBF(IC)=IFANCY
         if(ifancy.gt.49.and.ifancy.lt.100) lasv=.true.
         ITRA(JJ,II)=IC
         ITRBF(IC)=ITR
         ITRCON(ITR)=IC
         IF(FR0(ITR).GT.0.) THEN
            ALAM=2.997925e18/FR0(ITR)
          ELSE
            ALAM=0.
         END IF
C
         if(icolis.eq.0.and.ifancy.le.1.and.osc.eq.0.) then
            zz=iz(iel(ii))
            xq=nquant(ii)
            sig0c=1.
            if(fr0(itr).gt.0..and.xq.gt.0.)
     *      sig0c=2.815e-20*zz*zz/(fr0(itr)*1.e-16)**3/xq**5
            if(zz.gt.1.9) sig0c=sig0c*2.
            if(zz.gt.2.9) sig0c=sig0c*1.5
            osc0(itr)=sig0c
         end if

c        if(ion.ge.26) write(*,"('ionbf'7i5,1p2e10.2)") 
c    *   itr,ilow(itr),iup(itr),icol(itr),itrcon(itr),ic,ncol,
c    *   fr0(itr),alam

C
         IF(II.GE.NLAST(ION)) EXIT CONTLOOP
      END DO CONTLOOP 

      ALLOOP: DO
         READ(IUNIT,'(a1)',iostat=ios) A
         IF(IOS.NE.0) EXIT ALLOOP
         IF(A.EQ.'*') EXIT ALLOOP
      END DO ALLOOP
c     if(ion.eq.28) stop
C
C  -----------------------------------------------------------
C  Input parameters for line transitions
C  -----------------------------------------------------------
C
      IIP=0
      JJP=0
c     NHOD=0
      LINELOOP: DO
CC       READ(IUNIT,'(A100)',IOSTAT=IOS) DUM
CC     write(*,*) 'ios',ios
CC     write(*,*) dum
CC       IF(IOS.NE.0) EXIT LINELOOP
CC       READ(DUM,*,IOSTAT=KSTAT) II,JJ,MODE,IFANCY,ICOLIS,
CC   *        IFRQ0,IFRQ1,OSC,CPARAM,NCOL
CC       IF (KSTAT.NE.0) THEN
c           READ(IUNIT,*,IOSTAT=IOS) II,JJ,MODE,IFANCY,
CC          READ(DUM,*,IOSTAT=IOS) II,JJ,MODE,IFANCY,
CC   *           ICOLIS,IFRQ0,IFRQ1,OSC,CPARAM
CC        write(*,*) 'read-dum',ii,jj,mode,ifancy,icolis
            READ(IUNIT,*,IOSTAT=IOS) II,JJ,MODE,IFANCY,
     *           ICOLIS,IFRQ0,IFRQ1,OSC,CPARAM
            IF(IOS.NE.0) EXIT LINELOOP
            NCOL=0
c        END IF
c
         IF(ISPODF.GE.1) THEN
            INDXPA=IABS(MODE)
            LIJP=II.EQ.IIP .AND. JJ.EQ.JJP
            LOD34=INDXPA.EQ.3 .OR. INDXPA.EQ.4
            IF(LIJP .AND. LOD34) CYCLE LINELOOP
            IIP=II
            JJP=JJ
         END IF

         IFFR0=0
         IF(IABS(MODE).GT.100) THEN
            IF(MODE.GT.0) MODE=MODE-100
            IF(MODE.LT.0) MODE=MODE+100
            IFFR0=1
            READ(IUNIT,*) FR0INP
            IF(FR0INP.LT.1.E10) FR0INP=2.997925e18/FR0INP
         END IF
c         write(*,*) 'jj,nlevs(ion)',jj,nlevs(ion),mode
         IF(JJ.GT.NLEVS(ION)) THEN
            IF(IABS(MODE).EQ.2) THEN
               READ(IUNIT,*) K1,K2,K3,X1,X2,X3,K4
               CYCLE LINELOOP
            END IF
            IF(IABS(MODE).EQ.1) READ(IUNIT,*) LCMP
            IF(IABS(IFANCY).EQ.1) READ(IUNIT,*) GAMRL
            CYCLE LINELOOP
         END IF

         NTRANS=NTRANS+1
         ITR=NTRANS

         II=II+II0
         JJ=JJ+II0
!       write(*,*) 'lin',itr,ii,jj,mode,nquant(ii),nquant(jj),ifancy
         ILOW(ITR)=II
         IUP(ITR)=JJ
         IF(ENION(II).LT.ENION(JJ)) THEN
            ILOW(ITR)=JJ
            IUP(ITR)=II
         END IF
         ICOL(ITR)=ICOLIS
         INDEXP(ITR)=MODE
         OSC0(ITR)=OSC
         CPAR(ITR)=CPARAM
         LALI(ITR)=.FALSE.
         LEXP(ITR)=.FALSE.
         IFC0(ITR)=IFRQ0
         IFC1(ITR)=IFRQ1
         ITRCON(ITR)=0
c          write(*,*) 'ii,jj,itra(ii,jj)',ii,jj,itra(ii,jj)
         IF(ITRA(II,JJ).EQ.0) THEN
            ITRA(II,JJ)=ITR
c          write(*,*) 'ii,jj,itra(ii,jj)',ii,jj,itra(ii,jj)
          ELSE
            ICOL(ITR)=99
         END IF
         IE=IEL(II)
         N0I=NFIRST(IE)
         NKI=NNEXT(IE)
         LINE(ITR)=.TRUE.
         IFR0(ITR)=IFRQ0
         IFR1(ITR)=IFRQ1
         FR0(ITR)=(ENION(II)-ENION(JJ))/H
         IF(IFFR0.EQ.1) FR0(ITR)=FR0INP
c        if(ion.ge.27) write(*,"('lin',7i6,1pe12.4,i9)") 
c    *   itr,ii,jj,ifr0(itr),ifr1(itr),
c    *   itrcon(itr),ncol,fr0(itr),itrbf(385)
c
c        the case of several collisional processes
c
         IF (NCOL.NE.0) THEN
            DUM1=0
            DO IIC=1,NCOL
               READ(IUNIT,*) ITYPE, NCTEMP
CCC         IF (ITYPE.GT.MXTCOL) CALL QUIT('itype.gt.mxtcol',ITYPE,MXTCOL)
               READ(IUNIT,*) (CTEMP(ITYPE,IFIT,ITR),IFIT=1,NCTEMP)
               READ(IUNIT,*) (CRATE(ITYPE,IFIT,ITR),IFIT=1,NCTEMP)
               DUM1=DUM1+2**(ITYPE-1)
               idum1=ifix(real(dum1))
            END DO
            IF (MOD(DUM1,TWO).EQ.1) THEN
               ICOL(ITR)=1000*iDUM1
            ELSE
               IF (ICOL(ITR).LT.0) THEN
                  ICOL(ITR)=-1000*iDUM1+ICOL(ITR)-1
               ELSE
                  ICOL(ITR)=1000*iDUM1+ICOL(ITR)+1
               END IF
            END IF
         END IF
c
c     set up hydrogenic oscillator strength if none was specified
c
         IF(OSC.EQ.0..and.nquant(ii).le.20.and.nquant(jj).le.20) THEN
            IF(MODE.NE.3.AND.MODE.NE.4) THEN
               GH=TWO*NQUANT(II)*NQUANT(II)
               OSC0(ITR)=OSH(NQUANT(II),NQUANT(JJ))*G(II)/GH
            ENDIF
            IF(ifwop(jj).lt.0) THEN
               OSC0(ITR)=0.
               JJ0=NQUANT(JJ-1)
               J20=MIN(20,NLMX)
               IF(J20.GE.JJ0) THEN
                  DO JJTR=JJ0,J20
                     OSC0(ITR)=OSC0(ITR)+OSH(NQUANT(II),JJTR)
                  END DO
               END IF
               IF(NLMX.GT.20) THEN
                  XII=NQUANT(II)*NQUANT(II)
                  SUF=0.
                  DO JJTR=21,NLMX
                     XJ=JJTR
                     XJJ=XJ*XJ
                     XJTR=XJ/(XJJ-XII)
                     SUF=SUF+XJTR*XJTR*XJTR
                  END DO
                  XITR=(400.-XII)/20.
                  OSC0(ITR)=OSC0(ITR)+OSH(NQUANT(II),20)*SUF*XITR**3
               END IF
            END IF
         END IF
C
         IF(FR0(ITR).GT.0.) THEN
            ALAM=2.997925e18/FR0(ITR)
          ELSE
            ALAM=0.
         END IF
         IF(MODE.EQ.0) CYCLE LINELOOP
c
c     the case of a "merged superline" transition (trans. to a merged level)
c
c         if(ion.eq.1) write(*,*) 'mode',itr,i,jj,mode
         IF(IABS(MODE).EQ.2) THEN
            NHOD=NHOD+1
           write(*,*) 'nhod',ii,jj,nhod
            if(ifwop(jj).ge.0) CALL QUIT('ifwop(jj).ge.0',ifwop(jj),jj)
            READ(IUNIT,*) (KDO(IHI,NHOD),IHI=1,3),
     *                    (XDO(IHI,NHOD),IHI=1,3), KDO(4,NHOD)
            NFHOD=NFHOD+KDO(1,NHOD)+KDO(2,NHOD)+KDO(3,NHOD)+
     *                  KDO(4,NHOD)-2
            write(*,*) 'nfhod',
     *      nfhod,kdo(1,nhod),kdo(2,nhod),kdo(3,nhod),kdo(4,nhod)
C
C     again, change status of treatment of lines if required
C
            IF(II.LT.ILLIM.OR.FR0(ITR).LE.FRLMIN.OR.FR0(ITR).GE.FRLMAX)
     *         THEN
               INDEXP(ITR)=0
               CYCLE LINELOOP
            END IF
            JNDODF(ITR)=NHOD
            IF(II.LT.NLAST(ION)) CYCLE LINELOOP
         END IF
C
C     change the status of treatment of superlines,
C     if specified in the "offset-setting" record, or
C     because of too loo or too high frequency
C
         IF(IABS(MODE).EQ.3.OR.IABS(MODE).EQ.4) THEN
            IF(II.LT.ILLIM.OR.FR0(ITR).LE.FRLMIN.OR.
     *      FR0(ITR).GE.FRLMAX) INDEXP(ITR)=0
            CYCLE LINELOOP 
         END IF
C
C  -----------------------------------------------------------
C  Additional input parameters for "clasical" line transitions
C   (i.e. those not represented by ODF's - ie ABS(MODE)=1)
C  -----------------------------------------------------------
C
         READ(IUNIT,*) LCOMP(ITR),INTMOD(ITR),NF,XMAX,TSTD
         IPROF(ITR)=IFANCY
         IPROF0(ITR)=IFANCY
         IF(IABS(IPROF(ITR)).EQ.1) THEN
            NVOIGT=NVOIGT+1
            IP=NVOIGT
            if(ip.gt.mvoigt) CALL QUIT('nvoigt.gt.mvoig0',ip,mvoig0)
            ITRA(JJ,II)=IP
         END IF
         if(ion.eq.ielh) then
            if(ihydpr.eq.1) then
               if(nquant(ii).le.4.and.nquant(jj).lt.20) iprof(itr)=3
             else if(ihydpr.eq.2) then
               if(nquant(ii).le.2.and.nquant(jj).le.10) iprof(itr)=4
            end if
            if(ihyddk.gt.0) then
               if(nquant(ii).eq.1.and.nquant(jj).le.3) iprof(itr)=5
            end if
            iprof0(itr)=iprof(itr)
            if(iprof(itr).eq.3) ihydp0=1
            if(iprof(itr).eq.4) ihydp0=2
            if(iprof(itr).eq.5) ihydp0=3
         end if

C
C     if Voigt profile is assumed (ie. if IPROF = 1), an additional
C     input record is required which specifies an evaluation of the
C     relevant damping parameter - see procedure DOPGAM)
C
         IF(IABS(IPROF(ITR)).EQ.1) THEN
            READ(IUNIT,*) GAMAR(IP),STARK1(IP),STARK2(IP),STARK3(IP),
     *                    VDWH(IP)
            IF(GAMAR(IP).GT.0..AND.GAMAR(IP).LT.10.)
     *      GAMAR(IP)=EXP(2.3025851*GAMAR(IP))
c           IF(STARK1(IP).LT.0.) STARK1(IP)=EXP(2.3025851*STARK1(IP))
         END IF
c
c     set the profile coefficient for lines to IPROF=1 (Voigt) profile
c     if it was not set before, and for IOPTAB=1
c
         IF(IOPTAB.GT.0.AND.IPROF(ITR).EQ.1) THEN
            if(nf.lt.25) nf=25
            if(xmax.lt.4000.) xmax=4000.
         END IF
C
c     when using opacity table, extend the frequency range of non-H lines,
c     and seet them to evaluting the profile as Voigt
c
         IF(IOPTAB.GT.0.AND.ISPODF.EQ.0.AND.IPROF(ITR).EQ.0.
     *      AND.ION.NE.IELH) THEN
            IPROF(ITR)=1
            NVOIGT=NVOIGT+1
            IP=NVOIGT
            if(ip.gt.mvoigt) CALL QUIT('nvoigt.gt.mvoig0',ip,mvoig0)
            ITRA(JJ,II)=IP
            GAMAR(IP)=0.
            STARK1(IP)=0.
            VDWH(IP)=1.
            LCOMP=.TRUE.
            INTMOD(ITR)=3
            if(ii.eq.ii0+1) then
               if(nf.lt.25) nf=25
               if(xmax.lt.4000.) xmax=4000.
             else if(ii.le.ii0+3) then
               if(nf.lt.21) nf=21
               if(xmax.lt.1000.) xmax=2000.
             else if(ii.le.ii0+5) then
               if(nf.lt.17) nf=17
               if(xmax.lt.300.) xmax=600.
             else if(ii.le.ii0+10) then
               if(nf.lt.13) nf=13
               if(xmax.lt.100.) xmax=200.
             else
               if(nf.lt.9) nf=9
               if(xmax.lt.30.) xmax=60.
            end if
         END IF
C
C     change the status of treatment of lines, in virtue of:
C     a) too low frequency (FRLMIN); or
C     b) if specified in the "offset-setting" record
C
         IF(II.LT.ILLIM.OR.FR0(ITR).LE.FRLMIN.OR.FR0(ITR).GE.FRLMAX)
     *       THEN
            INDEXP(ITR)=0
            CYCLE LINELOOP   
         END IF
C
         IF(TSTD.EQ.ZERO) TSTD=0.75*TEFF
         IF(XMAX.EQ.ZERO) XMAX=4.55
         if(xmax.gt.ZERO) then
            IF(TEFF.GE.1.e6.and.iz(iel(ii)).le.2) XMAX=XMAX*0.1
            xmax=-xmax
            nf=2*nf-1
         end if
         INTM=INTMOD(ITR)
         IF(INTM.NE.0) THEN
            IFR0(ITR)=NLASTE+1
            IFR1(ITR)=NLASTE+NF
            NLASTE=IFR1(ITR)
         END IF
         NFREQL=MAX(NFREQL,NF)
!        CALL DOPGAM(ITR,1,TSTD,DOP,AGAM)
         CALL LINSET(ITR,XMAX)
         CALL IJALIS(ITR,IFRQ0,IFRQ1)
!      write(31,"('lin',7i6,1pe12.4)") itr,ii,jj,nf,ifr0(itr),ifr1(itr),
!    *   iprof(itr),fr0(itr)
!      write(31,*) '   ',lcomp(itr)
c     if(ion.ge.27) write(*,*) 'itrbf(385)',itr,itrbf(385)
         IF(II.GE.NLAST(ION)) EXIT LINELOOP
      END DO LINELOOP
C
C  -----------------------------------------------------------
C  Additional input parameters for iron-peak superlevels:
C   Energy bands  (only read in sampling mode!)
C  -----------------------------------------------------------
C
      IF(ISPODF.EQ.1 .AND. INODF1(ION).GT.0) THEN
         READ(IUNIT,*,IOSTAT=IOS) NEVKU(ION)
         IF(IOS.EQ.0) THEN
            DO I=1,NEVKU(ION)
               READ(IUNIT,*) XEV(I,ION)
            END DO
          ELSE
            CALL QUIT(' Missing data for iron superlevels',0,0)
         END IF
         READ(IUNIT,*,IOSTAT=IOS) NODKU(ION)
         IF(IOS.EQ.0) THEN
            DO I=1,NODKU(ION)
               READ(IUNIT,*,IOSTAT=IOS) XOD(I,ION)
               IF(IOS.NE.0) EXIT
            END DO
          ELSE
            CALL QUIT(' Missing data for iron superlevels',0,0)
         END IF
         IF(NEVKU(ION).GT.MLEVEL)
     *   CALL QUIT('NEVKU(ION).GT.MLEVEL',NEVKU(ION),MLEVEL)
         IF(NODKU(ION).GT.MLEVEL)
     *   CALL QUIT('NODKU(ION).GT.MLEVEL',NODKU(ION),MLEVEL)
      END IF
C
      CLOSE(IUNIT)
c      write(*,*) 'ion itr',ion,itr,mtran0,'nfirst',nfirst(ion)
c
c     initialization of Lemke/Tremblay/Koester hydrogen line
C     broadening tables, if required
c
c     if(ion.ge.27) write(*,*) 'itrbf(385)',itr,itrbf(385)
      if(ion.eq.ielh) then
         if(ihydp0.eq.1) ihydpr=21
         if(ihydpr.eq.2) ihydpr=22
         if(ihydpr.eq.3) ihydpr=23
         if(ihydp0.gt.0.and.ihydp0.le.3) then
            call lemini
            call xenini
         end if
         if(ihyddk.gt.0) call dkini
!      write(*,*) 'ihydp0,ihydpr,ihyddk',ihydp0,ihydpr,ihyddk
      end if

      it0=itr-itrprev
!     write(*,*) 'ION,ITR,IT0',ion,itr,it0,nlevs(ion)*(nlevs(ion)+1)/2
      itrprev=itr
c
c     determining whether there is a metastable level for this ion
c
      ni1=nfirst(ion)
c     write(*,*) 'itra',itra(ni1,ni1+1)
      if(indexp(itra(ni1,ni1+1)).eq.0.and.
     *  enion(ni1+1).gt.eh) then
        ifmeta(ion)=1
       else
        ifmeta(ion)=0
      end if
c      write(*,*) 'end rdata',nfirst(ion),ni1,ifmeta(ion)
c
c      write(*,*) 'nhod end res',ion,nhod
c     CALL LEVSET
c      write(*,*) 'nhod end2 res',ion,nhod
C
      RETURN
      END SUBROUTINE RDATA


!******************************************************


      SUBROUTINE LEVSET
C     =================
C
C     sets up level parameters IIEXP and IIFOR which control the
C     treatment of levels
C
      use accura
      use atomic
      use basics
      use modelq

      implicit none

      INTEGER :: I,IAT,II,IIE,IIF,IGRP,INEW,ID,IM
      LOGICAL :: LML

      if(ioptab.lt.0) return
C
C     1. case - treatment of levels determined by IMODL
C
      IF(IFLEV.EQ.0) THEN
         DO I=1,NLEVEL
            IIEXP(I)=0
            IIFOR(I)=0
         END DO
         IIE=0
         IIF=0
         ATOMS: DO IAT=1,NATOM
            IGRP=0
            IF(IIFIX(IAT).EQ.1) CYCLE ATOMS   
            DO I=N0A(IAT),NKA(IAT)
               INEW=1
               IF(IMODL(I).EQ.0) THEN
                  IIE=IIE+1
                  IIF=IIF+1
                  IIEXP(I)=IIE
                  IIFOR(I)=IIF
                  INDLEV(IIEXP(I))=I
c                write(*,"('imodl=0',7i5)") i,imodl(i),iie,iif,iiexp(i),
c    *           iifor(i),indlev(iiexp(I))
                ELSE IF(IMODL(I).GT.0) THEN
                  IIF=IIF+1
                  IIFOR(I)=IIF
                  IF(ILTLEV(I).GE.1) THEN
                     IIE=IIE+1
                     IIEXP(I)=IIE
                  END IF
                  IF(I.EQ.NFIRST(IEL(I)).OR.I.EQ.NNEXT(IEL(I))) THEN
                     IIE=IIE+1
                     IIEXP(I)=IIE
                  END IF
                ELSE IF(IMODL(I).LT.-100) THEN
                  IF(I.GT.1) THEN
                     IF(IMODL(I).EQ.IMODL(I-1)) INEW=0
                  END IF
                  IIEXP(I)=-IIE
                  IF(INEW.EQ.1) THEN
                     IIE=IIE+1
                     IIEXP(I)=-IIE
                     IM=NFIRST(IEL(I))
                     LML=.TRUE.
                     DO WHILE (IM.LT.I-1 .AND. LML)
                        IF(IMODL(I).EQ.IMODL(IM)) THEN
                           IIEXP(I)=IIEXP(IM)
                           IIE=IIE-1
                           LML=.FALSE.
                        END IF
                        IM=IM+1
                     END DO
                  END IF
                  IGRP=1
                  IIF=IIF+1
                  IIFOR(I)=IIF
c                 write(*,*) 'imodl-100',i,imodl(i),inew,iie,iif,igrp
                ELSE IF(IMODL(I).LT.-200) THEN
                  IF(I.GT.1) THEN
                     IF(IMODL(I).EQ.IMODL(I-1)) INEW=0
                  END IF
                  IF(INEW.EQ.1) IIE=IIE+1
                  IF(INEW.EQ.1) IIF=IIF+1
                  IIEXP(I)=-IIE
                  IIFOR(I)=-IIF
                  IGRP=1
                ELSE
                  IGRP=0
               END IF
            END DO
            IF(IGRP.EQ.1) THEN
               DO I=N0A(IAT),NKA(IAT)
                  IF(IIEXP(I).GT.0) IIEXP(I)=-IIEXP(I)
                  IF(IMODL(I).EQ.0) IMODL(I)=7
               END DO
            END IF
         END DO ATOMS

         NLVEXP=IABS(IIE)
         MLVEXP=NLVEXP+1
         NLVFOR=IABS(IIF)
         DO I=1,NLEVEL
            IF(IMODL(I).EQ.1.OR.IMODL(I).EQ.3) THEN
               IIEXP(I)=0
             ELSE IF(IMODL(I).EQ.4.OR.IMODL(I).EQ.5) THEN
               IIEXP(I)=0
             ELSE IF(IMODL(I).EQ.-1.OR.IMODL(I).EQ.-3) THEN
               IIEXP(I)=0
               IIFOR(I)=0
             ELSE IF(IMODL(I).EQ.6) THEN
               IIEXP(I)=0
             ELSE IF(IMODL(I).EQ.-5.OR.IMODL(I).EQ.-6) THEN
               IIEXP(I)=0
               IIFOR(I)=0
             ELSE IF(IMODL(I).LT.-100) THEN
               IMODL(I)=7
             ELSE IF(IMODL(I).LT.-200) THEN
                IMODL(I)=-7
            END IF
            DO ID=1,ND
               ILTREF(I,ID)=NNEXT(IEL(I))
            END DO
         END DO
         if(nlvexp.gt.0) return
         IF(IGRP.EQ.1) THEN
            DO I=N0A(IAT),NKA(IAT)
               IMODL(I)=7
            END DO
         END IF
         if(nlvexp.gt.0) return
C
C     2. case - treatment of levels automatic - all levels with ILK=0
C               in updated LTE mode
C
       ELSE
         IIF=0
         DO I=1,NLEVEL
            IF(IIFIX(IATM(I)).EQ.1) CYCLE    
            IMODL(I)=5
            IF(I.EQ.NFIRST(IEL(I)).OR.I.EQ.NNEXT(IEL(I))) THEN
               IIF=IIF+1
               IIFOR(I)=IIF
            END IF
c           write(*,*) 'levset i,iig,iifor',i,iif,iifor(i)
         END DO
         NLVEXP=IIF
         MLVEXP=NLVEXP+1
         NLVFOR=IIF
         DO I=1,NLEVEL
            IF(I.NE.NFIRST(IEL(I)).AND.I.NE.NNEXT(IEL(I)))
     *      IIFOR(I)=0
         END DO
         DO I=1,NLEVEL
            IIEXP(I)=IIFOR(I)
            IF(IIEXP(I).GT.0) INDLEV(IIEXP(I))=I
            DO ID=1,ND
               ILTREF(I,ID)=NNEXT(IEL(I))
            END DO
         END DO
         if(.not.lte) then
            do i=1,nlevel
               iifor(i)=i
            end do
           nlvfor=nlevel
         end if
c
      END IF
C
C     initialize b-factors
C
      DO I=1,NLEVEL
         DO ID=1,ND
            BFAC(I,ID)=UN
         END DO
      END DO
C
      do ii=1,nlvexp
         indlev(ii)=0
         do id=1,nd
            igzero(ii,id)=0
         end do
      end do
      do i=1,nlevel
         do id=1,nd
            ipzero(i,id)=0
         end do
         if(iabs(imodl(i)).le.6) then
            IF(IIEXP(I).GT.0) INDLEV(IIEXP(I))=I
         end if
      end do
C
       write(*,*) 'nlvexp end levset',nlvexp
      RETURN
      END SUBROUTINE LEVSET

C     **************************************************


      SUBROUTINE LINSET(ITR,XMAX)
C     ===========================
C
C     Set up frequency points and weights for a line
C     Auxiliary procedure for START
C
C     Input:
C      ITR    -  index of the transition
C      INMOD  -  mode of evaluating frequency points in the line
C             =  0  - means that frequency points and weights have
C                     already been read;
C             ne 0  - frequency points and weights will be evaluated:
C             the meaning of the individual values:
C             =  1  - equidistant frequencies, trapezoidal integration
C             =  2  - equidistant frequencies, Simpson integration
C             =  3  - modified Simpson integration, i.e. a series of
C                     3-point Simpson integrations with each subsequent
C                     integration interval doubled, until the whole
C                     integartion area is covered
C             =  4  - frequencies (in units of standard x) and weights
C                     (for integration over x) are read;
C
C      XMAX   >  0  - means that the line is assumed symmetric around the
C                     center, frequency points are set up between x=0 and
C                     x=XMAX, where x is frequency difference from the
C                     line center in units of the standard Doppler width
C             <  0  - frequency points are set between x=XMAX and x=-XMAX
C
C     Output
C      FREQ   -  array of frequencies
C                Note that LINSET calculates values of frequencies only
C                for frequency points between IFR0(ITR) and IFR1(ITR).
C      W      -  corresponding integration weights
C      PROF   -  corresponding values of absorption profile (if depth-independent)
C
      use accura
      use atomic
      use basics
      use modelq

      implicit none 

      INTEGER, PARAMETER   :: MFRLIN=100
      REAL(DP), INTENT(IN) :: XMAX
      INTEGER,INTENT(IN)   :: ITR
      REAL(DP), PARAMETER  :: BOL2=2.76108e-16, CIN=UN/2.997925e10,
     *                        OS0=0.02654, PISQ1=UN/1.77245385090551_dp

      REAL(DP)             :: X(MFRLIN),W0(MFRLIN)
      REAL(DP) :: X0,HH,TWI,TWN,TWA,DOP,S,SUM
      INTEGER  :: I,IJ0,IJ1,INMOD,N,M,MM,M2,INMOD0,IP,IP0
C
      IF(ITR.EQ.0) RETURN
      INMOD=INTMOD(ITR)
      INMOD0=MOD(IABS(INMOD),10)
      IJ0=IFR0(ITR)
      IJ1=IFR1(ITR)
      N=IJ1-IJ0+1
      IF(N.GT.MFRLIN) WRITE(*,*) 'increase MFRLIN in LINSET TO BE >',n
      X0=0.
      IF(XMAX.LT.0) X0=XMAX
      M=(N-1)/2
      X(1)=0.
      W0(1)=UN
      IF(N.LE.1) RETURN

      IF(INMOD0.LE.1) THEN
C
C     Trapezoidal integration
C
         HH=ABS(X0+XMAX)/(N-1)
         DO I=1,N
            X(I)=X0+(I-1)*HH
         END DO
         DO I=1,N
            W0(I)=HH
         END DO
         W0(1)=HALF*HH
         W0(N)=HALF*HH
C
C        Ordinary Simpson integration
C
      ELSE IF(INMOD0.EQ.2) THEN
         HH=ABS(X0+XMAX)/(N-1)
         DO I=1,N
            X(I)=X0+(I-1)*HH
         END DO
         HH=HH/3.D0
         IF(MOD(N,2).NE.1)
     *   CALL QUIT('even number of points in Simpson - LINSET',n,n)
         DO I=1,M
            W0(2*I)=4.D0*HH
            W0(2*I+1)=2.D0*HH
         END DO
         W0(1)=HH
         W0(N)=HH
       ELSE IF(INMOD0.EQ.3) THEN
C
C      Modified Simpson integration - a set of 3-point Simpson
C      integrations with continuosly increasing distance between the
C      integration points (schematically, distances between points are
C      h,h,2h,2h,4h,4h, etc.)
C
         TWI=UN
         MM=M
         IF(MOD(N,2).NE.1)
     *   CALL QUIT('even number of points in MSimpson - LINSET',n,n)
         IF(XMAX.LT.0) MM=M/2
         DO I=1,MM
            TWI=TWI*TWO
            X(2*I+1)= TWI-UN
            X(2*I)=TWI-UN-TWI/4.D0
            W0(2*I)=2.D0*TWI
            W0(2*I+1)=1.5D0*TWI
         END DO
         TWN=TWI-UN
         TWA=ABS(XMAX)/TWN
         HH=TWA/6.0
         DO I=1,MM
            X(2*I+1)=X(2*I+1)*TWA
            X(2*I)=X(2*I)*TWA
            W0(2*I)=W0(2*I)*HH
            W0(2*I+1)=W0(2*I+1)*HH
         END DO
         W0(1)=HH
         W0(N)=TWI*HH*HALF
         X(1)=0.
         IF(M.NE.MM) THEN
            IF(MOD(N,4).NE.1)
     *      CALL QUIT('conflict in MSimpson - LINSET',n,m)
            DO I=1,M
               X(M+1+I)=X(I+1)
               W0(M+1+I)=W0(I+1)
            END DO
            M2=2*(M+1)
            DO I=1,M
               X(I)=-X(M2-I)
               W0(I)=W0(M2-I)
            END DO
            X(M+1)=0.
            W0(M+1)=TWO*HH
         END IF
      END IF
C
C     For all types of integration:
C     set up arrays  FR,WW
C
      IP0=IPROF(ITR)
      IP=IABS(IP0)
      DOP=FR0(ITR)*CIN*SQRT(BOL2/AMASS(IATM(IUP(ITR)))*TSTD+VTB**2)
      DO I=1,N
         FREQ(I+IJ0-1)=FR0(ITR)-DOP*X(I)
         W(I+IJ0-1)=DOP*W0(I)
      END DO
C
C     set up array PROF (for depth-independent profiles)
C
      IF(IPROF(ITR).EQ.0) THEN
         S=OSC0(ITR)*OS0*PISQ1/DOP
         DO I=1,N
            PROF(I+IJ0-1)=EXP(-X(I)**2)*S
!     write(*,"(3i8,1p4e12.4)") itr,i,i+ij0-1,x(i),dop,s,prof(i+ij0-1)
         END DO
      END IF
C
C     for IPROF(ITR) ge 0  -  endpoint(s) of the line profile are forced to
C                             have zero cross-section
C
      IF(IP0.GE.0) THEN
         IF(XMAX.LT.0.) THEN
            PROF(IJ0)=0.
            PROF(IJ1)=0.
          ELSE
            PROF(IJ1)=0.
         END IF
      END IF
C
C     Recalculation of quadrature weights in order to enforce exact
C     normalization of the integral (absorption profile * weights)
C
      IF(INMOD0.LE.1) THEN
         SUM=0.
         DO I=1,N
            SUM=SUM+PROF(I+IJ0-1)*W(I+IJ0-1)
         END DO
         IF(SUM.GT.0.) THEN
            SUM=S/SUM
            DO I=1,N
               W(I+IJ0-1)=W(I+IJ0-1)*SUM
            END DO
         END IF
      END IF
C
C     reset the switch INTMOD
C
      IF(IPROF(ITR).GE.0) THEN
         IF(XMAX.LT.0.) THEN
            INTMOD(ITR)=-2
          ELSE
            INTMOD(ITR)=-1
         END IF
       ELSE
         IF(XMAX.LT.0.) THEN
            INTMOD(ITR)=2
          ELSE
            INTMOD(ITR)=1
         END IF
      END IF
      IF(ABS(INMOD).GE.10) INTMOD(ITR)=0
C
      RETURN
      END SUBROUTINE LINSET
C     
C
C     ****************************************************************
C
C
      SUBROUTINE LINSPL(ITR)
C     ======================
C
C     Set up depth-independent profile for a line
C     Analog to LINSET used in sampling mode
C
C     Input:
C      ITR    -  index of the transition
C
      use accura
      use atomic
      use basics
      use modelq
   
      implicit none 

      INTEGER, INTENT(IN) :: ITR
      REAL(DP), PARAMETER :: BOL2=2.76108e-16, CIN=UN/2.997925e10,
     *                        OS0=0.02654, PISQ1=UN/1.77245385090551_dp
      REAL(DP)            :: DOP,S,V
      INTEGER             :: IJ0,IJ1,N,KJ0,KJ1,IP0,I
C
      IJ0=IFR0(ITR)
      IJ1=IFR1(ITR)
      N=IJ1-IJ0+1
      KJ0=KFR0(ITR)
      KJ1=KFR1(ITR)
C
C     line profile
C
      DOP=FR0(ITR)*CIN*SQRT(BOL2/AMASS(IATM(IUP(ITR)))*TSTD+VTB**2)
      S=OSC0(ITR)*OS0*PISQ1/DOP
      IP0=IPROF(ITR)
      DO I=1,N
         V=(FREQ(IJ0+I-1)-FR0(ITR))/DOP
         PROF(KJ0+I-1)=EXP(-V**2)*S
      END DO
C
C     for IPROF(ITR) ge 0  -  endpoint(s) of the line profile are forced to
C                             have zero cross-section
C
      IF(IP0.GE.0) THEN
         PROF(KJ0)=0.
         PROF(KJ1)=0.
      END IF
      RETURN
      END SUBROUTINE LINSPL

C
C    *****************************************************
C


      SUBROUTINE IJALIS(ITR,IFRQ0,IFRQ1)
C     ==================================
C
C     auxiliary routine - sets up the necessary flags for ALI treatment
C      of individual transitions (in the fully hybrid CL/ALI scheme)
C
C     Output:
C
C     IJALI(IJ) = 0 - frequency point IJ is an explicit point
C               = 1 - frequency point IJ is an ALI point
C
C     LEXP(ITR) = T - at least one point within transition ITR is explicit
C     LEXP(ITR) = F - no point within transition ITR is explicit
C     LALI(ITR) = T - at least one point within transition ITR is ALI
C     LALI(ITR) = F - no point within transition ITR is ALI
C
      use accura
      use atomic
      use basics

      implicit none

      integer, INTENT(IN)    :: ITR
      integer, INTENT(INOUT) :: IFRQ0,IFRQ1
      integer                :: INDXP,I0,I1,NF,IJ,I
C
c     NFRECL=NFREQ
c     if(nfrecl.ge.nfreq) return
      INDXP=INDEXP(ITR)
      I0=IFR0(ITR)
      I1=IFR1(ITR)
      NF=I1-I0+1
      DO IJ=I0,I1
         IF(INDXP.GT.0) THEN
            IJALI(IJ)=0
          ELSE IF(INDXP.LT.0) THEN
            IJALI(IJ)=1
         END IF
      END DO
C
C     primarily explicit transitions
C
      IF(INDXP.GT.0) THEN
         LEXP(ITR)=.TRUE.
         LALI(ITR)=.FALSE.
         IF(IFRQ0.GT.0.and.iadop(iatm(ilow(itr))).eq.0) THEN
            LALI(ITR)=.TRUE.
            IF(IFRQ1.EQ.0.OR.IFRQ1.GT.NF) IFRQ1=NF
            DO I=IFRQ0,IFRQ1
                IJALI(I0+I-1)=1
            END DO
          ELSE IF(IFRQ0.LT.0) THEN
            LALI(ITR)=.TRUE.
CC          READ(57,*) (IJALI(IJ),IJ=I0,I1)
         END IF
         IF(IFRQ0.EQ.1.AND.IFRQ1.EQ.NF) LEXP(ITR)=.FALSE.
       ELSE IF(INDXP.LT.0) THEN
C
C      primarily ALI transitions
C
         LALI(ITR)=.TRUE.
         LEXP(ITR)=.FALSE.
         IF(IFRQ0.GT.0.and.iadop(iatm(ilow(itr))).eq.0) THEN
            LEXP(ITR)=.TRUE.
            IF(IFRQ1.EQ.0.OR.IFRQ1.GT.NF) IFRQ1=NF
            DO I=IFRQ0,IFRQ1
                IJALI(I0+I-1)=0
            END DO
          ELSE IF(IFRQ0.LT.0) THEN
            LEXP(ITR)=.TRUE.
CC          READ(57,*) (IJALI(IJ),IJ=I0,I1)
         END IF
         IF(IFRQ0.EQ.1.AND.IFRQ1.EQ.NF) LALI(ITR)=.FALSE.
      END IF
      IF(NFFIX.GT.0) THEN
         DO IJ=I0,I1
            IJALI(IJ)=1
         END DO
         LALI(ITR)=.TRUE.
         LEXP(ITR)=.FALSE.
      END IF
      RETURN
      END SUBROUTINE IJALIS


!********************************************************


      SUBROUTINE INIFRE
C     =================
c
c     basic setup of continuum frequencies
c
      use accura
      use basics
      use modelq
      use atomic
      use optabl

      implicit none

      INTEGER   :: NJREAD,IJ
      REAL(DP)  :: FR

      NJREAD=NFREAD
      IF(NJREAD.LE.0) THEN
         frmin = FRCMIN
         frmax = FRCMAX
         NFREQ=-NJREAD
         if(ifrset.ge.0) then
            nfreq=ifrset
            frmin=frtab(numfreq)
            frmax=frtab(1)
         end if
         if(ifrset.lt.0) nfreqc=-ifrset
         nfreqc=nfreq
         if(nfreq.eq.1) then
            freq(1)=frmin
            w(1)=1.
            ijali(1)=1
          else
            do ij=1,nfreq
               fr=log(frmin)+(log(frmax)-log(frmin))*(ij-1)/(nfreq-1)
               freq(nfreq-ij+1)=exp(fr)
               ijali(ij)=1
            end do
         end if
C
C        setting simple quadrature weights - trapezoidal integration
C
         if(nfreq.gt.1) then
            w(1)=0.5*(freq(1)-freq(2))
            w(nfreq)=0.5*(freq(nfreq-1)-freq(nfreq))
            do ij=2,nfreq-1
               w(ij)=0.5*(freq(ij-1)-freq(ij+1))
            end do
         end if
       ELSE
         NFREQC=NJREAD
      END IF
    
      write(*,*) 'inifre njread,nfread,nfreqc',njread,nfread,nfreqc

c     stop
C     ------------------------------------------------------
C     setup continuum frequencies (if they are not read)
C     ------------------------------------------------------
C
!     if(nfreq.gt.mfreq0) CALL QUIT('nfreq.gt.mfreq',nfreq,mfreq0)
!     if(nfreqc.gt.mfreq0) CALL QUIT('nfreqc.gt.mfreqc',nfreqc,mfreqc)
       write(*,*) 'nfreq,mfreq0,ispodf',nfreq,mfreq0,ispodf,nfread
      IF(NFREAD.GT.0.AND.ISPODF.EQ.0) THEN
         IF(IOPTAB.EQ.0) THEN
            CALL INIFRC(0)
          ELSE IF(IOPTAB.GT.0) THEN
            CALL INIFRT
         END IF
      END IF
      IF(ISPODF.GE.1) CALL INIFRS
      IF(FRLMAX.LE.0.) FRLMAX=FREQ(1)
      MFREQC=NFREQC
      write(*,*) 'inifre end nfreqc,mfreqc',nfreqc,mfreqc
C
      RETURN
      END SUBROUTINE INIFRE


!********************************************************



      SUBROUTINE INIFRC(IALIEX)
C     =========================
C
C     Setup continuum frequencies, including frequencies around
C     ionization limits
C          IALIEX=0 :  setup frequencies, all ALI
C          IALIEX=1 :  change IJALI for explicit frequencies
C
      use accura
      use atomic
      use basics
      use modelq
      use odfpar

      implicit none

      INTEGER, INTENT(IN) :: IALIEX
      REAL(DP), PARAMETER   :: THIRD=UN/3., FTH=4./3.,
     *                         TENLG = 2.302585093
      REAL(DP)              :: FRLEV(MLEVEL)
      INTEGER               :: IENS(MLEVEL)
      REAL(DP), allocatable :: freqco(:),wco(:),wchco(:)

      integer, allocatable  :: ijxco(:)

      REAL(DP) :: DIVEND,DNX,XEND,D121,HAEND,FRCLST,FRC0,DF0,FR01,FRTL
      REAL(DP) :: DFEDG,SUMWC
      INTEGER  :: IJ,IT,IJFL0,NEND,NJC,IL0,ILN,ITR0,NEND1,IF1,ITR
      INTEGER  :: MODE,IL,ILS,NEND2,IJFLS,IJL0
C
      MFREQC=NFTAIL+4*NLEVEL+abs(NFREAD)

      ALLOCATE (FREQCO(MFREQC),WCO(MFREQC),WCHCO(MFREQC))
      ALLOCATE (IJXCO(MFREQC))

      if(ioptab.lt.0) return
C
      write(*,*) 'MFREQC at begin of  INIFRC',mfreqc
      dfedg=0.000001
      if(icompt.gt.0) dfedg=0.01
      DFEDG=0.01
      IF(IALIEX.EQ.1) THEN
C
        if(nffix.lt.0) then
           do ij=1,nfreqc
              ijali(ij)=0
           end do
           return
        end if
c
        IF(NFFIX.EQ.2) RETURN
        DO IT=1,NTRANS
           IF(LINE(IT)) CYCLE
           IF(IFC1(IT).EQ.0) CYCLE
           if(iadop(iatm(ilow(it))).gt.0) cycle
           IJFL0=IJFL(ILOW(IT))+1
           IF(IFC1(IT).LT.100) THEN
              DO IJ=IFC0(IT),IFC1(IT)
                 IJFLS=IJFL0-IJ
                 IF(IJFLS.GE.1) THEN
                    IJALI(IJFLS)=0
                    IJX(IJFLS)=1
                 END IF
              END DO
            ELSE
              DO IJ=IJFL0,1,-1
                 IJALI(IJ)=0
                 IJX(IJ)=1
              END DO
           END IF
        END DO
C
        IF(ICOMPT.GT.0.AND.FRLCOM.GT.0) THEN
           DO IJ=1,NFREQ
             IF(FREQ(IJ).GT.FRLCOM) THEN
                IJALI(IJ)=0
                IJX(IJ)=1
             END IF
           END DO
        END IF
        RETURN
      END IF
C
      NEND=NFTAIL
      DIVEND=DFTAIL
      NJC=NFREQC/5
      DNX=UN-UN/FLOAT(NJC)
      CALL INDEXX(NLEVEL,ENION,IENS)
      DO IL=1,NLEVEL
         ILS=IENS(NLEVEL-IL+1)
         FRLEV(IL)=ENION(ILS)/H
         IJFL(IL)=0
c      write(*,"('frl',2i5,1p2e15.5)") il,ils,enion(il)/h,frlev(il)
      END DO
      IF(FRCMAX.LE.0.) THEN
         FREQCO(1)=8.e11*TEFF
       ELSE
         FREQCO(1)=FRCMAX
      END IF
c     write(*,"('inifrc',3i5,1p4e11.3)") 
c    * nfreqc,nend,njc,dnx,divend,frcmax,freqco(1)
      IL0=1
      IF(FREQCO(1).LT.CFRMAX*FRLEV(IL0) .AND. CFRMAX.GT.UN) THEN
         FREQCO(1)=CFRMAX*FRLEV(IL0)
       ELSE
         DO WHILE (FREQCO(1).LT.FRLEV(IL0) .AND. IL0.LT.NLEVEL)
            ILS=IENS(NLEVEL-IL0+1)
            ILN=NNEXT(IEL(ILS))
            ITR0=ITRA(ILS,ILN)
            INDEXP(ITR0)=0
            IFR0(ITR0)=0
            IFR1(ITR0)=0
            IF(FRLEV(IL0).GT.0.) 
     *       WRITE(10,"(' Edge at frequency larger than FRCMAX',I5,
     *       E12.4,3I7)") IL0,FRLEV(IL0),ILS,ILN,ITR0
            IL0=IL0+1
         END DO
      END IF
c      write(*,*)
C
      if(nftail.le.0) then
         if(nftail.eq.-1.or.dftail.eq.0.) then
            NEND1=NFREQC
            FREQCO(NEND1)=FRCMIN
            IJXCO(1)=1
            IJXCO(NEND1)=1
            XEND=UN/FLOAT(NEND1-1)
            D121=(FREQCO(1)/FREQCO(NEND1))**XEND
            DO IJ=2,NEND1-1
               FREQCO(IJ)=FREQCO(IJ-1)/D121
               IJXCO(IJ)=2
            END DO
            D121=THIRD*(FREQCO(1)-FREQCO(2))
            DO IJ=2,NEND1-1,2
               WCO(IJ)=4.*D121
               WCO(IJ-1)=WCO(IJ-1)+D121
               WCO(IJ+1)=WCO(IJ+1)+D121
               WCHCO(IJ)=0.
            END DO
          else
c
            NEND1=-NFTAIL
            FREQCO(NEND1)=DFTAIL*FREQCO(1)
            IJXCO(1)=1
            IJXCO(NEND1)=1
            XEND=UN/FLOAT(NEND1-1)
            D121=(FREQCO(1)/FREQCO(NEND1))**XEND
            DO IJ=2,NEND1-1
               FREQCO(IJ)=FREQCO(IJ-1)/D121
               IJXCO(IJ)=2
            END DO
            D121=THIRD*(FREQCO(1)-FREQCO(2))
            DO IJ=2,NEND1-1,2
               WCO(IJ)=4.*D121
               WCO(IJ-1)=WCO(IJ-1)+D121
               WCO(IJ+1)=WCO(IJ+1)+D121
               WCHCO(IJ)=0.
            END DO
C
            NEND2=NFREQC
            IJXCO(NEND1)=1
            IJXCO(NEND1+1)=1
            XEND=UN/FLOAT(NEND2-NEND1)
            d121=(freqco(nend1)/frcmin)**xend
            DO IJ=NEND1+1,NEND2
               freqco(ij)=freqco(ij-1)/d121
               IJXCO(IJ)=2
            END DO
            D121=THIRD*(FREQCO(NEND1)-FREQCO(NEND1+1))
            DO IJ=NEND1+1,NEND2-1,2
               WCO(IJ)=4.*D121
               WCO(IJ-1)=WCO(IJ-1)+D121
               WCO(IJ+1)=WCO(IJ+1)+D121
               WCHCO(IJ)=0.
            END DO
         end if
C
       else
C
         NEND=NFTAIL
         DIVEND=DFTAIL
         NJC=NFREQC/5
         DNX=UN-UN/FLOAT(NJC)
         NFREQC=NEND+1

         FREQCO(NEND)=(un+dfedg)*FRLEV(il0)
         FREQCO(NEND+1)=(un-dfedg)*FRLEV(il0)
         NEND1=NEND/2+1
         XEND=UN/FLOAT(NEND1-1)
         FREQCO(NEND1)=FREQCO(1)-(UN-DIVEND)*(FREQCO(1)-FREQCO(NEND))
         IJXCO(NEND+1)=1
c      write(*,"('high',4i5,1p4e15.5/)") nend,nend1,nfreqc,njc,freqco(1)
c    *            ,freqco(nend1),freqco(nend),freqco(nend+1)
C
C     high-frequency tail of the spectrum - a two-part Simpson integration
C
C     1st part - from the highest frequency FRCMAX to a division freq.
C
       ij=1
c      write(*,"('ij',i5,1pe15.5,0pf15.3)") ij,freqco(ij),cas/freqco(ij)
         IJXCO(1)=1
         IJXCO(NEND1)=1
         D121=XEND*(FREQCO(1)-FREQCO(NEND1))
c      write(*,*) 'd121 - high to 1st',d121
         if(icompt.gt.0) d121=(freqco(1)/freqco(nend1))**xend
c      write(*,"('ij',i5,1pe15.5,0pf15.3)") ij,freqco(ij),cas/freqco(ij)
         DO IJ=2,NEND1-1
            FREQCO(IJ)=FREQCO(IJ-1)-D121
            if(icompt.gt.0) freqco(ij)=freqco(ij-1)/d121
            IJXCO(IJ)=2
c      write(*,"('ij',i5,1pe15.5,0pf15.3)") ij,freqco(ij),cas/freqco(ij)
         END DO
       ij=nend1
c      write(*,"('ij',i5,1pe15.5,0pf15.3)") ij,freqco(ij),cas/freqco(ij)

         D121=THIRD*(FREQCO(1)-FREQCO(2))
         DO IJ=2,NEND1-1,2
            WCO(IJ)=4.*D121
            WCO(IJ-1)=WCO(IJ-1)+D121
            WCO(IJ+1)=WCO(IJ+1)+D121
            WCHCO(IJ)=0.
         END DO
C
C     2nd part - from the division freq to the first discontinuity
C
c      write(*,*) 'nend,nend1 - div to 1st',nend,nend1
         if(nend1.lt.nend) then
            IJXCO(NEND)=1
            IJXCO(NEND+1)=1
            D121=XEND*(FREQCO(NEND1)-FREQCO(NEND))
c      write(*,"('d121',1pe15.5)") d121
            if(icompt.gt.0) d121=(freqco(nend1)/freqco(nend))**xend
c      write(*,"('d121',1pe15.5)") d121
            DO IJ=NEND1+1,NEND-1
               FREQCO(IJ)=FREQCO(IJ-1)-D121
               if(icompt.gt.0) freqco(ij)=freqco(ij-1)/d121
c      write(*,"('ij',i5,1pe15.5,0pf15.3)") ij,freqco(ij),cas/freqco(ij)
               IJXCO(IJ)=2
            END DO
            D121=THIRD*(FREQCO(NEND1)-FREQCO(NEND1+1))
            DO IJ=NEND1+1,NEND-1,2
               WCO(IJ)=4.*D121
               WCO(IJ-1)=WCO(IJ-1)+D121
               WCO(IJ+1)=WCO(IJ+1)+D121
               WCHCO(IJ)=0.
            END DO
        ij=nend
c      write(*,"('ij',i5,1pe15.5,0pf15.3)") ij,freqco(ij),cas/freqco(ij)

         end if
C
C     the 1st discontinuity - the one with the highest frequency
C
         HAEND=HALF*(FREQCO(NEND)-FREQCO(NEND+1))
         XEND=UN/FLOAT(NEND-1)
         WCO(NEND)=WCO(NEND)+HAEND
         WCO(NEND+1)=WCO(NEND+1)+HAEND
         WCHCO(1)=0.
         WCHCO(NEND)=HAEND
         ILS=IENS(NLEVEL)
         IJFL(ILS)=NEND
         IL0=NLEVEL
         IF(FRCMIN.LE.0.) FRCMIN=1.e12
         FRCLST=FRLEV(IL0)
         DO WHILE(FRCLST.LT.FRCMIN)
            IF(FRLEV(IL0).GT.0.) 
     *       WRITE(10,
     *       "(' Edge at frequency smaller than 1.e12',i5,e12.4)")
     *       IL0,FRLEV(IL0)
            IL0=IL0-1
            FRCLST=FRLEV(IL0)
         END DO
         IL0=2
C
c        write(*,"('frc0',i5,1p4e11.3)") 
c    *   nfreqc,freqco(nfreqc),dnx,DNX*FREQCO(NFREQC),frclst
         OUTER: DO
         FRC0=DNX*FREQCO(NFREQC)
c        write(*,"('frc0',i5,1p4e11.3)") 
c    *   nfreqc,freqco(nfreqc),dnx,DNX*FREQCO(NFREQC),frclst
         IF(FRC0.LT.FRCLST) THEN
            NFREQC=NFREQC+2
            FREQCO(NFREQC-1)=(un+dfedg)*FRCLST
            FREQCO(NFREQC)=(un-dfedg)*FRCLST
            ij=nfreqc-1
c           write(*,"('ij',i5,1pe15.5,0pf15.3)") 
c    *      ij,freqco(ij),cas/freqco(ij)
            ij=nfreqc
c           write(*,"('ij',i5,1pe15.5,0pf15.3)") 
c    *      ij,freqco(ij),cas/freqco(ij)
            FREQCO(NFREQC-1)=(un+dfedg)*FRCLST
            FREQCO(NFREQC)=(un-dfedg)*FRCLST
            IJXCO(NFREQC-1)=1
            IJXCO(NFREQC)=1
            WCO(NFREQC)=WCO(NFREQC)+
     *                  HALF*(FREQCO(NFREQC-1)-FREQCO(NFREQC))
            WCO(NFREQC-1)=WCO(NFREQC-1)+
     *                    HALF*(FREQCO(NFREQC-2)-FREQCO(NFREQC))
            WCO(NFREQC-2)=WCO(NFREQC-2)+
     *                    HALF*(FREQCO(NFREQC-2)-FREQCO(NFREQC-1))
            WCHCO(NFREQC-1)=HALF*(FREQCO(NFREQC-1)-FREQCO(NFREQC))
            WCHCO(NFREQC-2)=HALF*(FREQCO(NFREQC-2)-FREQCO(NFREQC-1))
            ILS=IENS(NLEVEL-IL0+1)
            IJFL(ILS)=NFREQC-1
            IF(IL0.LT.NLEVEL) THEN
               DO IL=IL0+1,NLEVEL
                  ILS=IENS(NLEVEL-IL+1)
                  IJFL(ILS)=NFREQC-1
                  IF(FRLEV(IL).LT.FRCMIN) IJFL(ILS)=0
               END DO
            END IF
            D121=XEND*(FREQCO(NFREQC)-FRCMIN)
c           write(*,*) 'd121 - ils', nfreqc+1,nfreqc+nend-1,d121
            DO IJ=NFREQC+1,NFREQC+NEND-1
               FREQCO(IJ)=FREQCO(IJ-1)-D121
c              write(*,"('ij',i5,1pe15.5,0pf15.3)") 
c    *         ij,freqco(ij),cas/freqco(ij)
               IJXCO(IJ)=2
               WCHCO(IJ)=0.
            END DO
            IJXCO(NFREQC+NEND-1)=1
            DO IJ=NFREQC+1,NFREQC+NEND-2,2
               WCO(IJ)=FTH*D121
               WCO(IJ-1)=WCO(IJ-1)+THIRD*D121
               WCO(IJ+1)=WCO(IJ+1)+THIRD*D121
            END DO
            WCHCO(NFREQC)=THIRD*D121
            NFREQC=NFREQC+NEND-1
            EXIT OUTER
         END IF
         DF0=FRLEV(IL0)+0.1*(FREQCO(NFREQC)-FRC0)
         FRTL=(un+dfedg)*FRLEV(IL0)
c        write(*,"('frtl',i5,1p4e11.3)") il0,frlev(il0),frc0,df0,frtl
         IF(FRC0.GT.DF0) THEN
            NFREQC=NFREQC+1
            FREQCO(NFREQC)=FRC0
            IJXCO(NFREQC)=2
c           write(*,"('ij',i5,1pe15.5,0pf15.3)")
c    *      nfreqc,freqco(nfreqc),cas/freqco(nfreqc)
            WCO(NFREQC)=WCO(NFREQC)+
     *                  HALF*(FREQCO(NFREQC-1)-FREQCO(NFREQC))
            WCO(NFREQC-1)=WCO(NFREQC-1)+
     *                    HALF*(FREQCO(NFREQC-1)-FREQCO(NFREQC))
            WCHCO(NFREQC-1)=HALF*(FREQCO(NFREQC-1)-FREQCO(NFREQC))
          ELSE IF(FRTL.LT.FREQCO(NFREQC)) THEN
            NFREQC=NFREQC+2
            FREQCO(NFREQC-1)=FRTL
c           write(*,"('ij',i5,1pe15.5,0pf15.3)")
c    *      nfreqc-1,freqco(nfreqc-1),cas/freqco(nfreqc-1)
            FREQCO(NFREQC)=(un-dfedg)*FRLEV(IL0)
c           write(*,"('ij',i5,1pe15.5,0pf15.3)")
c    *      nfreqc,freqco(nfreqc),cas/freqco(nfreqc)
            IJXCO(NFREQC-1)=1
            IJXCO(NFREQC)=1
            WCO(NFREQC)=WCO(NFREQC)+
     *                  HALF*(FREQCO(NFREQC-1)-FREQCO(NFREQC))
            WCO(NFREQC-1)=WCO(NFREQC-1)+
     *                    HALF*(FREQCO(NFREQC-2)-FREQCO(NFREQC))
            WCO(NFREQC-2)=WCO(NFREQC-2)+
     *                    HALF*(FREQCO(NFREQC-2)-FREQCO(NFREQC-1))
            WCHCO(NFREQC-1)=HALF*(FREQCO(NFREQC-1)-FREQCO(NFREQC))
            WCHCO(NFREQC-2)=HALF*(FREQCO(NFREQC-2)-FREQCO(NFREQC-1))
            ILS=IENS(NLEVEL-IL0+1)
            IJFL(ILS)=NFREQC-1
            IL0=IL0+1
          ELSE
            ILS=IENS(NLEVEL-IL0+1)
            IJFL(ILS)=NFREQC-1
            IL0=IL0+1
         END IF
         END DO OUTER
      end if
C
      SUMWC=0.
      IF(NFREAD.GT.0) THEN
         DO IJ=NFREQ,1,-1
            FREQ(IJ+NFREQC)=FREQ(IJ)
            W(IJ+NFREQC)=W(IJ)
            PROF(IJ+NFREQC)=PROF(IJ)
            ijl0=ijali(ij+nfreqc)
            IJALI(IJ+NFREQC)=IJALI(IJ)
         END DO
         DO IJ=1,NFREQC
            FREQ(IJ)=FREQCO(IJ)
            W(IJ)=WCO(IJ)
            WCH(IJ)=WCHCO(IJ)
            IJALI(IJ)=1
            IJX(IJ)=IJXCO(IJ)
            PROF(IJ)=0.
         END DO
         DO ITR=1,NTRANS
            IF(.NOT.LINE(ITR).OR.INDEXP(ITR).EQ.0) CYCLE
            IF(IFR0(ITR).GT.0) IFR0(ITR)=IFR0(ITR)+NFREQC
            IF(IFR1(ITR).GT.0) IFR1(ITR)=IFR1(ITR)+NFREQC
         END DO
         NFREQ=NFREQ+NFREQC
c
c        store MFREQ and MFREQC for future allocations
c
         MFREQ=NFREQ+NFHOD
         MFREQC=NFREQC
         MFREQP=MFREQ
         IF(IOPTAB.LT.0) MFREQP=1
         write(*,"(/'NFREQ, MFREQ  in inifrc(0)',i8)") NFREQ,MFREQ
         write(*,"('NFREQC,MFREQC in inifrc(0)',i8/)") NFREQC
      END IF
C
C     determination of the first (IFR0) and the last (IFR1) frequency
C     for each explicit continuum - only if they were not already read
C
      DO ITR=1,NTRANS
         IF(LINE(ITR)) CYCLE
         IF(IFR0(ITR).LE.0) IFR0(ITR)=1
         IF(IFR1(ITR).GT.0) EXIT
         IF1=0
         FR01=FR0(ITR)
         MODE=INDEXP(ITR)
         IF(IABS(MODE).EQ.5.OR.IABS(MODE).EQ.15) FR01=FR0PC(ITR)
         DO IJ=1,NFREQC
            IF(FREQ(IJ).GE.FR01) IF1=IJ
         END DO
         IFR1(ITR)=IF1
c      write(*,"('itr,ifr0,ifr1-inifrc',3i5)") itr,ifr0(itr),ifr1(itr)
      END DO    

      if(nfrecl.gt.nfreq) nfrecl=nfreq
c     nfreqe=nfrecl
c     do ij=1,nfreqe
c        ijali(ij)=0
c     end do
       write(*,*) 'nfreqe in inifrc',nfreqe
c
      RETURN
      END SUBROUTINE INIFRC

C
C    ****************************************************************
C

      SUBROUTINE INIFRS
C     =================
C
C     Setup frequencies in opacity sampling mode
C
      use accura
      use atomic
      use basics
      use modelq
      use odfpar

      implicit none

      REAL(DP),PARAMETER    :: THIRD=UN/3.,FTH=4./3.
      real(DP), ALLOCATABLE :: FRL0(:),FRL1(:),FRLC(:)
      INTEGER,ALLOCATABLE   :: IKC(:),ITKC(:),ITJNU(:)
      REAL(DP)              :: FRLEV(MLEVEL)
      INTEGER               :: IENS(MLEVEL),ITRL(MLEVEL)
      REAL(DP)              :: FLNU(2*MATOM+3),DLNU(2*MATOM+3)
      INTEGER               :: ILNU(2*MATOM+3)
      REAL(DP)              :: XMASS(30) 

      REAL(DP) :: CDOP,D0,D1,D121
      REAL(DP) :: XEND,XFRA,XFRB,XFR,XPNU,FRLV0,XBL,AL,FR02H,XFS0
      INTEGER  :: NNU,NLIC,ITR,IAT,ILV0,ITC,IL,ILS,ILN,ITR0,NFTA1
      INTEGER  :: IJ,KJ,NEND1,IKNU,NFS,IB0,IB1,NUB,IL0
      INTEGER  :: IT,INDXPA,IO,MODW,IDN,NEND,NF,NFLX,NPPX
      LOGICAL  :: LFRS3

      DATA XMASS/ 1.008, 4.003, 6.941, 9.012,10.810,12.011,14.007,
     *           16.000,18.918,20.179,22.990,24.305,26.982,28.086,
     *           30.974,32.060,35.453,39.948,39.098,40.080,44.956,
     *           47.900,50.941,51.996,54.938,55.847,58.933,58.700,
     *           63.546,65.380/

      ALLOCATE (FRL0(MTRANS),FRL1(MTRANS),FRLC(5*MTRANS))
      ALLOCATE (IJTC(MTRANS))
      ALLOCATE (IKC(5*MTRANS),ITKC(5*MTRANS),ITJNU(5*MTRANS))
C
      IF(TSNU.EQ.0.) TSNU=TEFF
      IF(VTNU.EQ.0.) VTNU=VTB
      IF(VTNU.LT.1.e4) VTNU=VTNU*1.e5
      FRS1=CNU1*1.e11*TSNU
      FRS2=3.28805e15/CNU2/CNU2
      FRS3=3.28805e15/CNU3/CNU3
      lfrs3=ddnu2.gt.ddnu
c      write(*,"('inifrs begin',1p5e10.2)") tsnu,vtnu,frs1,frs2,frs3
c      write(*,*) 'inifrs begin',tsnu,vtnu,frs1,frs2,frs3
C
c      write(*,*) 'natom',natom
      DO IAT=1,NATOM
         CDOP=TWO*BOLK/AMASS(IAT)
         DLNU(IAT)=0.375/2.997925e10*SQRT(CDOP*TSNU+VTNU*VTNU)
         DLNU(IAT+NATOM)=20.*DLNU(IAT)
         FLNU(IAT)=LOG(FRS1)
         FLNU(IAT+NATOM)=LOG(FRS1)
c      write(*,"(i3,1p5e10.2)") iat,cdop,tsnu,vtnu,dlnu(iat),flnu(iat)
c      write(*,*) iat,cdop,tsnu,vtnu,dlnu(iat),flnu(iat)
      END DO
C
      XPNU=24.
      CDOP=TWO*BOLK/XMASS(1)/HMASS
      DLNU(2*NATOM+1)=50./2.997925e10*SQRT(CDOP*TSNU+VTNU*VTNU)
      DLNU(2*NATOM+2)=5.*DLNU(2*NATOM+1)
      FLNU(2*NATOM+1)=LOG(FRS2)
      FLNU(2*NATOM+2)=LOG(FRCMIN)
      NNU=2*NATOM+3
      IF(ISPODF.EQ.1 .AND. DDNU.GT.0.) THEN
         CDOP=TWO*BOLK/AMASS(NATOM)
         IF(IELNU.GT.0) CDOP=TWO*BOLK/XMASS(IELNU)/HMASS
         DLNU(NNU)=DDNU/2.997925e10*SQRT(CDOP*TSNU+VTNU*VTNU)
         FLNU(NNU)=LOG(FRS2)
c      write(*,"('cdon',1p4e10.2)") cdop,tsnu,vtnu,dlnu(nnu)
       ELSE
         DLNU(NNU)=DLNU(2*NATOM+2)
         FLNU(NNU)=LOG(FRS1)
      END IF
c      write(*,*) 'nnu',nnu
c      write(*,*) 'dlnu',(dlnu(i),i=1,nnu)
      CALL INDEXX(NNU,DLNU,ILNU)
c      write(*,*) 'nnu',nnu
c      write(*,*) 'dlnu',(dlnu(i),i=1,nnu)
c      write(*,*) 'ilnu',(ilnu(i),i=1,nnu)
C
C     Store line and continua frequencies
C
      NLIC=0
      DO ITR=1,NTRANS
         IJTC(ITR)=0
         INDXPA=IABS(INDEXP(ITR))
         IF(INDXPA.EQ.0) CYCLE
         IF(INDXPA.EQ.3 .OR. INDXPA.EQ.4) CYCLE
         IF(FR0(ITR).EQ.0.) CYCLE
         IF(LINE(ITR)) THEN
            ILV0=ILOW(ITR)
            IAT=IATM(ILV0)
            ITC=ITRA(ILV0,NNEXT(IEL(ILV0)))
            IF(ITC.EQ.0) ITC=ITRA(ILV0,NNEXT(IEL(ILV0))+1)
            IF(INDXPA.NE.2) THEN
               FRLC(NLIC+1)=FR0(ITR)
               ITKC(NLIC+1)=ITR
               IJTC(ITR)=NLIC+1
               ITJNU(NLIC+1)=IAT
               FRLC(NLIC+2)=FREQ(IFR0(ITR))
               FRL0(ITR)=FRLC(NLIC+2)
               ITKC(NLIC+2)=ITR
c        write(*,*) 'frlc',itr,nlic,indxpa,frl0(itr)
               IF(ITC.GT.0 .AND. FREQ(IFR0(ITR)).GT.FR0(ITC) .AND.
     *         FR0(ITC).GT.FR0(ITR)) FRLC(NLIC+2)=0.999999*FR0(ITC)
               ITJNU(NLIC+2)=IAT
               FRLC(NLIC+3)=FREQ(IFR1(ITR))
               FRL1(ITR)=FRLC(NLIC+3)
               ITKC(NLIC+3)=ITR
               ITJNU(NLIC+3)=2*NATOM+1
               NLIC=NLIC+3
               D0=LOG(FRL0(ITR))-LOG(FRL1(ITR))
               IF(D0.GT.XPNU*DLNU(IAT)) THEN
                  ITJNU(NLIC-1)=IAT+NATOM
                  FRLC(NLIC+1)=EXP(LOG(FR0(ITR))+XPNU*DLNU(IAT))
                  ITKC(NLIC+1)=ITR
                  ITJNU(NLIC+1)=IAT
                  FRLC(NLIC+2)=EXP(LOG(FR0(ITR))-XPNU*DLNU(IAT))
                  ITKC(NLIC+2)=ITR
                  ITJNU(NLIC+2)=IAT+NATOM
                  NLIC=NLIC+2
               END IF
             ELSE
               FRLC(NLIC+1)=0.999999*FR0(ITC)
               FRL0(ITR)=FRLC(NLIC+1)
               ITKC(NLIC+1)=ITR
               ITJNU(NLIC+1)=IAT
               FRLC(NLIC+2)=FREQ(IFR1(ITR-1))
               FRL1(ITR)=FRLC(NLIC+2)
               ITKC(NLIC+2)=ITR
               ITJNU(NLIC+2)=2*NATOM+1
               NLIC=NLIC+2
            END IF
          ELSE
            NLIC=NLIC+1
            FRLC(NLIC)=FR0(ITR)
            ITKC(NLIC)=ITR
            IJTC(ITR)=NLIC
            ITJNU(NLIC)=0
         END IF
      END DO
       write(*,*) 'nlic',nlic
C
      IKC(1)=1
      IF(NLIC.GT.1) CALL INDEXX(NLIC,FRLC,IKC)
       write(*,*) 'MFREQ,MFREQ) in INIFRS',mfreq,MFREQ0
      DO IJ=1,MFREQ0
         FREQ(IJ)=0.
         W(IJ)=0.
         WCH(IJ)=0.
         NLINES(IJ)=0
      END DO
       write(*,*) 'nlic2',nlic
C
C     Sort continuum limits
C
      CALL INDEXX(NLEVEL,ENION,IENS)
c      write(*,"(20i6)") (iens(i),i=1,nlevel)
      DO IL=1,NLEVEL
         ILS=IENS(NLEVEL-IL+1)
         FRLEV(IL)=ENION(ILS)/H
         ITRL(IL)=ITRA(ILS,NNEXT(IEL(ILS)))
      END DO
      IF(FRCMAX.LT.1.01*FRLEV(1) .AND. FRCMAX.GT.0.) THEN
         ILS=IENS(NLEVEL)
         ILN=NNEXT(IEL(ILS))
         ITR0=ITRA(ILS,ILN)
         WRITE(10,"(1PE12.4,3I7)") FRLEV(1),ILS,ILN,ITR0
         CALL QUIT(' Edge at frequency larger than FRCMAX; ii,itr:',
     *            ils,itr0)
      END IF
C
C     Highest frequency tail
C
      IF(FRCMAX.LE.0.) FRCMAX=FRLEV(1)*CFRMAX
      IF(FRS1.GT.FRCMAX) THEN
         FRCMAX=FRS1
         NFTAIL=0
      END IF
      IF(NFTAIL.GT.0) THEN
         NFTA1=NFTAIL/2+1
         FREQ(1)=FRCMAX
         NEND=0
         IL=1
         KJ=1
         DO WHILE(FRLEV(IL).GT.FRS1)
            NEND1=NEND+NFTA1
            NEND=NEND+NFTAIL
            ITR=ITRL(IL)
            IFR0(ITR)=1
            IFR1(ITR)=NEND
            FREQ(NEND)=1.000001_dp*FRLEV(IL)
            FREQ(NEND+1)=0.999999_dp*FRLEV(IL)
            FREQ(NEND1)=FREQ(KJ)-(UN-DFTAIL)*(FREQ(KJ)-FREQ(NEND))
            XEND=UN/FLOAT(NFTA1-1)
            D121=XEND*(FREQ(KJ)-FREQ(NEND1))
            DO IJ=KJ+1,NEND1-1
               FREQ(IJ)=FREQ(IJ-1)-D121
            END DO
            D121=THIRD*(FREQ(KJ)-FREQ(KJ+1))
            DO IJ=KJ+1,NEND1-1,2
               W(IJ)=4.*D121
               W(IJ-1)=W(IJ-1)+D121
               W(IJ+1)=W(IJ+1)+D121
c            write(*,"('high1',i7,1p3e16.8)") ij,freq(ij),d121,w(ij)
            END DO
            D121=XEND*(FREQ(NEND1)-FREQ(NEND))
            DO IJ=NEND1+1,NEND-1
               FREQ(IJ)=FREQ(IJ-1)-D121
            END DO
            D121=THIRD*(FREQ(NEND1)-FREQ(NEND1+1))
            DO IJ=NEND1+1,NEND-1,2
               W(IJ)=4.*D121
               W(IJ-1)=W(IJ-1)+D121
               W(IJ+1)=W(IJ+1)+D121
c            write(*,"('high2',i7,1p3e16.8)") ij,freq(ij),d121,w(ij)
            END DO
            D121=HALF*(FREQ(NEND)-FREQ(NEND+1))
            W(NEND)=W(NEND)+D121
            W(NEND+1)=W(NEND+1)+D121
            IL=IL+1
            KJ=NEND+1
         END DO
         NEND1=NEND+NFTA1
         NEND=NEND+NFTAIL
         FREQ(NEND)=FRS1
         FREQ(NEND1)=FREQ(KJ)-(UN-DFTAIL)*(FREQ(KJ)-FREQ(NEND))
         XEND=UN/FLOAT(NFTA1-1)
         D121=XEND*(FREQ(KJ)-FREQ(NEND1))
         DO IJ=KJ+1,NEND1-1
            FREQ(IJ)=FREQ(IJ-1)-D121
         END DO
         D121=THIRD*(FREQ(KJ)-FREQ(KJ+1))
         DO IJ=KJ+1,NEND1-1,2
            W(IJ)=4.*D121
            W(IJ-1)=W(IJ-1)+D121
            W(IJ+1)=W(IJ+1)+D121
c            write(*,"('high3',i7,1p3e16.8)") ij,freq(ij),d121,w(ij)
         END DO
         D121=XEND*(FREQ(NEND1)-FREQ(NEND))
         DO IJ=NEND1+1,NEND-1
            FREQ(IJ)=FREQ(IJ-1)-D121
         END DO
         D121=THIRD*(FREQ(NEND1)-FREQ(NEND1+1))
         DO IJ=NEND1+1,NEND-1,2
            W(IJ)=4.*D121
            W(IJ-1)=W(IJ-1)+D121
            W(IJ+1)=W(IJ+1)+D121
c            write(*,"('high4',i7,1p3e16.8)") ij,freq(ij),d121,w(ij)
         END DO
       ELSE
         FREQ(1)=FRS1
         NEND=1
      END IF
      NFREQC=NEND
       write(*,*) 'nend',nend
      DO IJ=1,NFREQC
         IFREQB(IJ)=IJ
      END DO
      NFRS1=NFREQC
C
C     Setup frequency points
C
      DO IT=1,NTRANS
         IFR0(IT)=0
         IFR1(IT)=0
      END DO
C
      IL=NLIC
      DO WHILE(FRLC(IKC(IL)).GT.FRS1)
         IL=IL-1
      END DO
      NFREQ=NEND
      XFRA=LOG(FRS1)
      DO WHILE(IL.GT.0)
        if(freq(nfreq).lt.frs3 .and. lfrs3) then
           dlnu(nnu)=ddnu2/ddnu*dlnu(nnu)
           call indexx(nnu,dlnu,ilnu)
           lfrs3=.false.
        endif
         ITR=ITKC(IKC(IL))
         NFS=0
         XFRB=LOG(FRLC(IKC(IL)))
         IF(XFRA.GT.XFRB) THEN
            IKNU=ITJNU(IKC(IL))
            IDN=1
            DO WHILE(FLNU(ILNU(IDN)).GE.XFRA .AND. IDN.LT.NNU)
               IDN=IDN+1
            END DO
            DXNU=DLNU(ILNU(IDN))
            IF(IKNU.EQ.0) XFRB=LOG(1.000001*FRLC(IKC(IL)))
            NFS=INT((XFRA-XFRB)/DXNU)+1
            XFS0=(XFRA-XFRB)/FLOAT(NFS)
            DO IJ=NFREQ+1,NFREQ+NFS
               XFR=LOG(FREQ(IJ-1))-XFS0
               FREQ(IJ)=EXP(XFR)
            END DO
            NFREQ=NFREQ+NFS
            IF(LOG(FR0(ITR)).EQ.XFRB) IJTC(ITR)=NFREQ
            IF(IKNU.EQ.0) THEN
               IFR0(ITR)=1
               IFR1(ITR)=NFREQ
               NFREQ=NFREQ+1
               FREQ(NFREQ)=0.999999*FRLC(IKC(IL))
               XFRB=LOG(FREQ(NFREQ))
             ELSE IF(IKNU.LE.2*NATOM) THEN
               IF(IFR0(ITR).EQ.0) THEN
                  IFR0(ITR)=NFREQ
                  D0=LOG(FR0(ITR))
                  IF(FLNU(IKNU).GT.D0) FLNU(IKNU)=D0
                  IF(IABS(INDEXP(ITR)).EQ.2) THEN
                     D0=LOG(FR0(ITR-1))
                     IF(FLNU(IKNU).GT.D0) FLNU(IKNU)=D0
                  END IF
                ELSE
                  IFR1(ITR)=NFREQ
                  IF(IKNU.LE.NATOM) THEN
                     IAT=IATM(ILOW(ITR))
                     D0=LOG(FR0(ITR))-XPNU*DLNU(IAT)
                     D1=LOG(FRL1(ITR))
                     IF(D1.GT.D0) D0=D1
                     IF(FLNU(IKNU).GT.D0) FLNU(IKNU)=D0
                   ELSE
                     D0=LOG(FRL1(ITR))
                     IF(FLNU(IKNU).GT.D0) FLNU(IKNU)=D0
                  END IF
               END IF
             ELSE
               IF(IFR0(ITR).EQ.0) THEN
                  IFR0(ITR)=NFREQ
                ELSE
                  IFR1(ITR)=NFREQ
               END IF
            END IF
          ELSE IF(XFRA.EQ.XFRB) THEN
            IKNU=ITJNU(IKC(IL))
            IF(IKNU.EQ.0) THEN
               FREQ(NFREQ)=1.000001_dp*FRLC(IKC(IL))
               FREQ(NFREQ+1)=0.999999_dp*FRLC(IKC(IL))
               IFR0(ITR)=1
               IFR1(ITR)=NFREQ
               NFREQ=NFREQ+1
               XFRB=LOG(FREQ(NFREQ))
             ELSE IF(IKNU.LE.2*NATOM) THEN
               IF(IFR0(ITR).EQ.0) THEN
                  IFR0(ITR)=NFREQ
                  D0=LOG(FR0(ITR))
                  IF(FLNU(IKNU).GT.D0) FLNU(IKNU)=D0
                  IF(IABS(INDEXP(ITR)).EQ.2) THEN
                     D0=LOG(FR0(ITR-1))
                     IF(FLNU(IKNU).GT.D0) FLNU(IKNU)=D0
                  END IF
                ELSE
                  IFR1(ITR)=NFREQ
                  IF(IKNU.LE.NATOM) THEN
                     IAT=IATM(ILOW(ITR))
                     D0=LOG(FR0(ITR))-XPNU*DLNU(IAT)
                     D1=LOG(FRL1(ITR))
                     IF(D1.GT.D0) D0=D1
                     IF(FLNU(IKNU).GT.D0) FLNU(IKNU)=D0
                   ELSE
                     D0=LOG(FRL1(ITR))
                     IF(FLNU(IKNU).GT.D0) FLNU(IKNU)=D0
                  END IF
                  IF(LOG(FR0(ITR)).EQ.XFRB) IJTC(ITR)=NFREQ
               END IF
             ELSE
               IF(IFR0(ITR).EQ.0) THEN
                  IFR0(ITR)=NFREQ
                ELSE
                  IFR1(ITR)=NFREQ
                  IF(LOG(FR0(ITR)).EQ.XFRB) IJTC(ITR)=NFREQ
               END IF
            END IF
         END IF
         IL=IL-1
         XFRA=XFRB
         IF(XPNU.EQ.24. .AND. FREQ(NFREQ).LT.FRS2) THEN
            XPNU=HALF*XPNU
            DO IAT=1,NATOM
               DLNU(IAT)=TWO*DLNU(IAT)
               DLNU(IAT+NATOM)=TWO*DLNU(IAT+NATOM)
            END DO
         END IF
      END DO
c      write(*,*) 'before xfrb',xfra,xfrb
C
      XFRB=LOG(FRCMIN)
      IF(XFRA.GT.XFRB) THEN
         DXNU=DLNU(NNU-1)
         NFS=INT((XFRA-XFRB)/DXNU)+1
         XFS0=(XFRA-XFRB)/FLOAT(NFS)
         DO IJ=NFREQ+1,NFREQ+NFS
            XFR=LOG(FREQ(IJ-1))-XFS0
            FREQ(IJ)=EXP(XFR)
         END DO
         NFREQ=NFREQ+NFS
c      write(*,*) 'nfreg',nfreq,nfs,xfra,xfrb
      END IF
      FREQ(NFREQ)=FRCMIN
      DO ITR=1,NTRANS
c      write(*,*) 'itr',itr,ifr0(itr),ifr1(itr)
         IF(LINEXP(ITR)) CYCLE
         DO IJ=IFR0(ITR),IFR1(ITR)
            NLINES(IJ)=NLINES(IJ)+1
         END DO
      END DO
c      write(*,*) 'after nlines'
c      write(*,"(20i6)") (nlines(ij),ij=1,nfreq,10)
C
C     Choose continuum frequency points in the global set
C
      FRLEV(NLEVEL+1)=FRCMIN
      IL=1
      DO WHILE(FRLEV(IL).GT.FRS1)
         IL=IL+1
      END DO
      IB0=NFRS1
      NUB=2*NATOM+1
      XFRA=LOG(FRS1)
      DO WHILE(IL.LE.NLEVEL+1)
c        IF(FRLEV(IL).LT.FRCMIN) GO TO 490
c        IF(IL.GT.1 .AND. IL.LE.NLEVEL) THEN
c           IF(FRLEV(IL).GE.FRLEV(IL-1)) GO TO 490
c        END IF
         IF((FRLEV(IL).LT.FRCMIN).OR.
     *     (IL.GT.1 .AND. IL.LE.NLEVEL.AND. 
     *      FRLEV(IL).GE.FRLEV(IL-1))) THEN
            IL=IL+1
            IF(FRLEV(IL).LT.FRS2) NUB=2*NATOM+2
            CYCLE
         END IF
         IF(IL.LE.NLEVEL) ITR=ITRL(IL)
         FRLV0=FRLEV(IL)
         IB1=IB0
         DO WHILE(FREQ(IB1).GT.FRLV0)
            IB1=IB1+1
            XFRB=LOG(FREQ(IB1))
            IF(IFREQB(NFREQC).LT.IB1) THEN
               IF(NLINES(IB1).EQ.0 .AND. ISPODF.GT.1) THEN
                  NFREQC=NFREQC+1
                  IFREQB(NFREQC)=IB1
                  XFRA=XFRB
                ELSE IF((XFRA-XFRB).GT.DLNU(NUB)) THEN
                  NFREQC=NFREQC+1
                  IFREQB(NFREQC)=IB1
                  XFRA=XFRB
               END IF
            END IF
         END DO
         IF(IL.LE.NLEVEL) THEN
            IFR0(ITR)=1
            IFR1(ITR)=IB1-1
            IJTC(ITR)=IFR1(ITR)
         END IF
         IF(IFREQB(NFREQC).LT.(IB1-1)) THEN
            NFREQC=NFREQC+1
           IFREQB(NFREQC)=IB1-1
         END IF
         IF(IFREQB(NFREQC).LT.IB1) THEN
            NFREQC=NFREQC+1
            IFREQB(NFREQC)=IB1
         END IF
         XFRA=LOG(FREQ(IB1))
         IB0=IB1
         IL=IL+1
         IF(FRLEV(IL).LT.FRS2) NUB=2*NATOM+2
      END DO
C
      IF(IFREQB(NFREQC).LT.NFREQ) THEN
         NFREQC=NFREQC+1
         IFREQB(NFREQC)=NFREQ
      END IF
      write(*,*) 'INIFRS nfreqc',nfreqc
      MFREQC=NFREQC
C
      NFREQL=0
      XBL=LOG(FRS1)
      NFLX=0
      DO IT=1,NTRANS
         IF(LINEXP(IT)) CYCLE
         IF(FR0(IT).LT.FRCMIN) CYCLE
         INDXPA=ABS(INDEXP(IT))
         IF(INDXPA.GT.2 .AND. INDXPA.LE.4) CYCLE
         IL0=ILOW(IT)
         ITC=ITRA(IL0,NNEXT(IEL(IL0)))
         IF(ITC.EQ.0) ITC=ITRA(IL0,NNEXT(IEL(IL0))+1)
         IF(IFR1(IT).GT.IFR1(ITC). AND.
     *      IFR0(IT).LE.IFR1(ITC) .AND. ITC.GT.0) IFR0(IT)=IFR1(ITC)+1
         NF=IFR1(IT)-IFR0(IT)+1
         KFR0(IT)=NFREQL+1
         KFR1(IT)=NFREQL+NF
         NFREQL=NFREQL+NF
         IF(INDXPA.EQ.2) THEN
            FR02H=HALF*(FREQ(IFR0(IT))+FREQ(IFR1(IT)))
            IJTC(IT)=IFR1(IT)
            DO WHILE(FR02H.GT.FREQ(IJTC(IT)) .AND. IJTC(IT).GT.1)
               IJTC(IT)=IJTC(IT)-1
            END DO
         END IF

         al=2.997926e18/fr0(it)
         io=iel(il0)
         write(42,"(i7,a6,2i7,3i5,f12.3,3i7,2x,3i7)")
     *     it,typion(io),il0,iup(it),iatm(il0),
     *     il0-nfirst(io)+1,iup(it)-nfirst(io)+1,al,
     *     ifr0(it),ifr1(it),nf,kfr0(it),kfr1(it),nfreql
!        IF(NF.GT.MFREQL) THEN
!           WRITE(10,*) IL0,IT,NF
!           CALL QUIT('Too many frequencies in a line - nf.gt.mfreql',
!    *               nf,mfreql)
!        END IF
         IF(NF.GT.NFLX) NFLX=NF
         MFREQP=KFR1(IT)
CC       IF(KFR1(IT).GT.MFREQP)
CC   *      CALL QUIT('Too many cross-sections to store in PRFLIN',
CC   *                kfr1(it),mfreqp)
      END DO
      
      MFREQL=NFLX+1
C
      DO IT=1,NTRANS
         MODW=IABS(INDEXP(IT))
         IF(MODW.EQ.5 .OR. MODW.EQ.15) THEN
            IJTC(IT)=IFR1(IT)
            FRLV0=FR0PC(IT)
            IB1=NFRS1
            DO WHILE(FREQ(IB1).GT.FRLV0)
               IB1=IB1+1
            END DO
            IFR0(IT)=1
            IFR1(IT)=IB1-1
         END IF
      END DO
c      write(*,*) 'before weights',nfreq,mfreq0,nfrs1
C
C     Weights
C
c     write(*,*) 'nfrs1',nfrs1
c     do ij=1,2000
c        write(*,"(i6,1p2e16.8)") ij,freq(ij),w(ij)
c     end do

      DO IJ=NFRS1+1,NFREQ
         D121=HALF*(FREQ(IJ-1)-FREQ(IJ))
c      if(ij.le.nfrs1+1000) write(*,"(i7,1p4e16.8)") 
c    * ij,freq(ij),d121,w(ij-1),w(ij)
         W(IJ-1)=W(IJ-1)+D121
         W(IJ)=W(IJ)+D121
c      if(ij.le.nfrs1+1000) write(*,"(i7,1p4e16.8)") 
c    * ij,freq(ij),d121,w(ij-1),w(ij)
      END DO
C
      DO IJ=1,NFREQ
         IJALI(IJ)=1
         IJX(IJ)=1
         JIK(IJ)=IJ
      END DO
      NPPX=NFREQ
C
      write(10,*) nfreq,nfreqc,nfreql,nflx
      IF(NFREQ.GT.MFREQ0) THEN
         WRITE(10,"(' Number of frequencies:',I10)") NFREQ
         CALL QUIT('nfreq.gt.mfreq0',nfreq,mfreq0)
      END IF
C
      
      DEALLOCATE (FRL0,FRL1,FRLC)
      DEALLOCATE (IKC,ITKC,ITJNU)

      MFREQ=NFREQ+NFHOD
      write(*,*) 'MFREQ, NFREQ in INIFRS',mfreq,nfreq

      RETURN
      END SUBROUTINE INIFRS
C
C *******************************************************************
C

      SUBROUTINE INIFRT
C     =================
C
      use accura
      use atomic
      use basics
      use modelq
      use optabl
C
      implicit none

      REAL(DP),PARAMETER    :: THIRD=UN/3.,FTH=4./3.
      REAL(DP)              :: FRLEV(MLEVEL)
      INTEGER               :: IENS(MLEVEL)
      REAL(DP), allocatable :: freqco(:),wco(:),wchco(:)
      integer, allocatable  :: ijxco(:)
      REAL(DP) :: DFEDG,DNX,XEND,D121,HAEND,FRCLST,FRC0
      REAL(DP) :: FR,FR01,DIVEND,DF0,FRTL
      INTEGER  :: NEND,NJC,IL,ILS,ILN,IL0,ITR0,NEND1,IJ,NEND2,NFR,ITR
      INTEGER  :: IF1,MODE,NFRTAB

      ALLOCATE (FREQCO(MFREQC),WCO(MFREQC),WCHCO(MFREQC))
      ALLOCATE (IJXCO(MFREQC))
C
      DFEDG=0.01
      NEND=NFTAIL
      DIVEND=DFTAIL
      NJC=NFREQC/5
      DNX=UN-UN/FLOAT(NJC)
      CALL INDEXX(NLEVEL,ENION,IENS)
      DO IL=1,NLEVEL
         ILS=IENS(NLEVEL-IL+1)
         FRLEV(IL)=ENION(ILS)/H
         IJFL(IL)=0
      END DO
C
      IF(FRCMAX.LE.0.) THEN
         FREQCO(1)=8.E11*TEFF
       ELSE
         FREQCO(1)=FRCMAX
      END IF
C
      IL0=1
      IF(FREQCO(1).LT.CFRMAX*FRLEV(IL0) .AND. CFRMAX.GT.UN) THEN
         FREQCO(1)=CFRMAX*FRLEV(IL0)
       ELSE
         DO WHILE (FREQCO(1).LT.FRLEV(IL0) .AND. IL0.LT.NLEVEL)
            ILS=IENS(NLEVEL-IL0+1)
            ILN=NNEXT(IEL(ILS))
            ITR0=ITRA(ILS,ILN)
            INDEXP(ITR0)=0
            IFR0(ITR0)=0
            IFR1(ITR0)=0
            IF(FRLEV(IL0).GT.0.) 
     *      WRITE(10,"(' Edge at frequency larger than FRCMAX',I5,
     *      E12.4,3I7)") IL0,FRLEV(IL0),ILS,ILN,ITR0
            IL0=IL0+1
         END DO
      END IF
C
      NFREQC=NEND+1
      FREQCO(NEND)=(un+dfedg)*FRLEV(il0)
      FREQCO(NEND+1)=(un-dfedg)*FRLEV(il0)
      NEND1=NEND/2+1
      XEND=UN/FLOAT(NEND1-1)
      FREQCO(NEND1)=FREQCO(1)-(UN-DIVEND)*(FREQCO(1)-FREQCO(NEND))
      IJXCO(NEND+1)=1
C
C     high-frequency tail of the spectrum - a two-part Simpson integration
C
C     1st part - from the highest frequency FRCMAX to a division freq.
C
      IJXCO(1)=1
      IJXCO(NEND1)=1
      D121=XEND*(FREQCO(1)-FREQCO(NEND1))
      if(icompt.gt.0) d121=(freqco(1)/freqco(nend1))**xend
      DO IJ=2,NEND1-1
         FREQCO(IJ)=FREQCO(IJ-1)-D121
         if(icompt.gt.0) freqco(ij)=freqco(ij-1)/d121
         IJXCO(IJ)=2
      END DO
      D121=THIRD*(FREQCO(1)-FREQCO(2))
      DO IJ=2,NEND1-1,2
         WCO(IJ)=4.*D121
         WCO(IJ-1)=WCO(IJ-1)+D121
         WCO(IJ+1)=WCO(IJ+1)+D121
         WCHCO(IJ)=0.
      END DO
C
C     2nd part - from the division freq to the first discontinuity
C
      if(nend1.lt.nend) then
          IJXCO(NEND)=1
          IJXCO(NEND+1)=1
          D121=XEND*(FREQCO(NEND1)-FREQCO(NEND))
          if(icompt.gt.0) d121=(freqco(nend1)/freqco(nend))**xend
          DO IJ=NEND1+1,NEND-1
             FREQCO(IJ)=FREQCO(IJ-1)-D121
             if(icompt.gt.0) freqco(ij)=freqco(ij-1)/d121
             IJXCO(IJ)=2
          END DO
          D121=THIRD*(FREQCO(NEND1)-FREQCO(NEND1+1))
          DO IJ=NEND1+1,NEND-1,2
             WCO(IJ)=4.*D121
             WCO(IJ-1)=WCO(IJ-1)+D121
             WCO(IJ+1)=WCO(IJ+1)+D121
             WCHCO(IJ)=0.
          END DO
      end if
C
C     the 1st discontinuity - the one with the highest frequency
C
      HAEND=HALF*(FREQCO(NEND)-FREQCO(NEND+1))
      XEND=UN/FLOAT(NEND-1)
      WCO(NEND)=WCO(NEND)+HAEND
      WCO(NEND+1)=WCO(NEND+1)+HAEND
      WCHCO(1)=0.
      WCHCO(NEND)=HAEND
      ILS=IENS(NLEVEL)
      IJFL(ILS)=NEND
      IL0=NLEVEL
      IF(FRCMIN.LE.0.) FRCMIN=1.e12
      FRCLST=FRLEV(IL0)
      DO WHILE(FRCLST.LT.FRCMIN)
         IF(FRLEV(IL0).GT.0.) 
     *   WRITE(10,"(' Edge at frequency smaller than 1.e12',
     *   i5,e12.4)") IL0,FRLEV(IL0)
         IL0=IL0-1
         FRCLST=FRLEV(IL0)
      END DO
      IL0=2
C
      OUTER: DO
      FRC0=DNX*FREQCO(NFREQC)
      IF(FRC0.LT.FRCLST) THEN
         NFREQC=NFREQC+2
         FREQCO(NFREQC-1)=(un+dfedg)*FRCLST
         FREQCO(NFREQC)=(un-dfedg)*FRCLST
         IJXCO(NFREQC-1)=1
         IJXCO(NFREQC)=1
         WCO(NFREQC)=WCO(NFREQC)+HALF*(FREQCO(NFREQC-1)-FREQCO(NFREQC))
         WCO(NFREQC-1)=WCO(NFREQC-1)+
     *                 HALF*(FREQCO(NFREQC-2)-FREQCO(NFREQC))
         WCO(NFREQC-2)=WCO(NFREQC-2)+
     *                 HALF*(FREQCO(NFREQC-2)-FREQCO(NFREQC-1))
         WCHCO(NFREQC-1)=HALF*(FREQCO(NFREQC-1)-FREQCO(NFREQC))
         WCHCO(NFREQC-2)=HALF*(FREQCO(NFREQC-2)-FREQCO(NFREQC-1))
         ILS=IENS(NLEVEL-IL0+1)
         IJFL(ILS)=NFREQC-1
         IF(IL0.LT.NLEVEL) THEN
            DO IL=IL0+1,NLEVEL
               ILS=IENS(NLEVEL-IL+1)
               IJFL(ILS)=NFREQC-1
               IF(FRLEV(IL).LT.FRCMIN) IJFL(ILS)=0
            END DO
         END IF
         D121=XEND*(FREQCO(NFREQC)-FRCMIN)
         DO IJ=NFREQC+1,NFREQC+NEND-1
            FREQCO(IJ)=FREQCO(IJ-1)-D121
            IJXCO(IJ)=2
            WCHCO(IJ)=0.
         END DO
         IJXCO(NFREQC+NEND-1)=1
         DO IJ=NFREQC+1,NFREQC+NEND-2,2
            WCO(IJ)=FTH*D121
            WCO(IJ-1)=WCO(IJ-1)+THIRD*D121
            WCO(IJ+1)=WCO(IJ+1)+THIRD*D121
         END DO
         WCHCO(NFREQC)=THIRD*D121
         NFREQC=NFREQC+NEND-1
         EXIT OUTER
      END IF
      DF0=FRLEV(IL0)+0.1*(FREQCO(NFREQC)-FRC0)
      FRTL=(UN+DFEDG)*FRLEV(IL0)
      IF(FRC0.GT.DF0) THEN
         NFREQC=NFREQC+1
         FREQCO(NFREQC)=FRC0
         IJXCO(NFREQC)=2
         WCO(NFREQC)=WCO(NFREQC)+HALF*(FREQCO(NFREQC-1)-FREQCO(NFREQC))
         WCO(NFREQC-1)=WCO(NFREQC-1)+
     *                 HALF*(FREQCO(NFREQC-1)-FREQCO(NFREQC))
         WCHCO(NFREQC-1)=HALF*(FREQCO(NFREQC-1)-FREQCO(NFREQC))
       ELSE IF(FRTL.LT.FREQCO(NFREQC)) THEN
         NFREQC=NFREQC+2
         FREQCO(NFREQC-1)=FRTL
         FREQCO(NFREQC)=(un-dfedg)*FRLEV(IL0)
         IJXCO(NFREQC-1)=1
         IJXCO(NFREQC)=1
         WCO(NFREQC)=WCO(NFREQC)+HALF*(FREQCO(NFREQC-1)-FREQCO(NFREQC))
         WCO(NFREQC-1)=WCO(NFREQC-1)+
     *                 HALF*(FREQCO(NFREQC-2)-FREQCO(NFREQC))
         WCO(NFREQC-2)=WCO(NFREQC-2)+
     *                 HALF*(FREQCO(NFREQC-2)-FREQCO(NFREQC-1))
         WCHCO(NFREQC-1)=HALF*(FREQCO(NFREQC-1)-FREQCO(NFREQC))
         WCHCO(NFREQC-2)=HALF*(FREQCO(NFREQC-2)-FREQCO(NFREQC-1))
         ILS=IENS(NLEVEL-IL0+1)
         IJFL(ILS)=NFREQC-1
         IL0=IL0+1
       ELSE
         ILS=IENS(NLEVEL-IL0+1)
         IJFL(ILS)=NFREQC-1
         IL0=IL0+1
      END IF
      END DO OUTER
c     end if
C
      nend2=nfreqc
      IF(IFRSET.EQ.0) THEN
         DO IJ=1,NUMFREQ
            FREQCO(IJ+NEND2)=FRTAB(IJ)
         END DO
         NFR=NUMFREQ+NEND2
       ELSE IF(IFRSET.GT.0) THEN
         NFRTAB=IFRSET
         DO IJ=1,NFRTAB
            FR=LOG(FRTAB(NUMFREQ))+
     *         LOG(FRTAB(1)/FRTAB(NUMFREQ))*(IJ-1)/(NFRTAB-1)
            FREQCO(NEND2+NFRTAB-IJ+1)=EXP(FR)
            NFR=NFRTAB+NEND2
         END DO
      END IF
C
      IF(FRTAB(NUMFREQ).GT.FRCMIN) THEN
         DO IJ=1,NEND
            FR=LOG(FRCMIN)+(LOG((UN-DFEDG)*FRTAB(NUMFREQ)/FRCMIN)*
     *         (IJ-1)/(NEND-1))
            FREQCO(NFR+NEND-IJ+1)=EXP(FR)
         END DO
         NFR=NFR+NEND
      END IF
      NFREQC=NFR
C
      WCO(1)=HALF*(FREQCO(1)-FREQCO(2))
      WCO(NFR)=HALF*(FREQCO(NFR-1)-FREQCO(NFR))
      DO IJ=2,NFR-1
         WCO(IJ)=HALF*(FREQCO(IJ-1)-FREQCO(IJ+1))
      END DO
C
      DO IJ=NFREQ,1,-1
         FREQ(IJ+NFREQC)=FREQ(IJ)
         W(IJ+NFREQC)=W(IJ)
         PROF(IJ+NFREQC)=PROF(IJ)
         IJALI(IJ+NFREQC)=IJALI(IJ)
      END DO
      DO IJ=1,NFREQC
         FREQ(IJ)=FREQCO(IJ)
         W(IJ)=WCO(IJ)
         IJALI(IJ)=1
         IJX(IJ)=1
         PROF(IJ)=0.
      END DO
      DO ITR=1,NTRANS
         IF(.NOT.LINE(ITR).OR.INDEXP(ITR).EQ.0) CYCLE
         IF(IFR0(ITR).GT.0) IFR0(ITR)=IFR0(ITR)+NFREQC
         IF(IFR1(ITR).GT.0) IFR1(ITR)=IFR1(ITR)+NFREQC
      END DO
      NFREQ=NFREQ+NFREQC

      MFREQ=NFREQ+NFHOD
      MFREQP=MFREQ
      MFREQC=NFREQC

      write(*,"(/a,3i6/)") 'INIFRT: NFREQ,NHOD,MFREQ',NFREQ,NHOD,MFREQ

C
C     determination of the first (IFR0) and the last (IFR1) frequency
C     for each explicit continuum - only if they were not already read
C
      DO ITR=1,NTRANS
         IF(LINE(ITR)) CYCLE
            IF(IFR0(ITR).LE.0) IFR0(ITR)=1
            IF(IFR1(ITR).GT.0) CYCLE
            IF1=0
            FR01=FR0(ITR)
            MODE=INDEXP(ITR)
            IF(IABS(MODE).EQ.5.OR.IABS(MODE).EQ.15) FR01=FR0PC(ITR)
            DO IJ=1,NFREQC
               IF(FREQ(IJ).GE.FR01) IF1=IJ
            END DO
            IFR1(ITR)=IF1
      END DO
      RETURN
      END SUBROUTINE INIFRT
C
C
C ********************************************************************
C
C
      SUBROUTINE INDEXX(N,ARRIN,INDX)
C     ===============================
C
C     Sorting routine
C
      use accura 
      implicit none

      REAL(DP), INTENT(IN)  :: ARRIN(N)
      INTEGER,INTENT(OUT)   :: INDX(N)
      INTEGER               :: I,J,N,M,IR,INDXT
      REAL(DP)              :: QQ

      DO J=1,N
         INDX(J)=J
      END DO
      M=N/2+1
      IR=N
      OUTER: DO
      IF(M.GT.1)THEN
         M=M-1
         INDXT=INDX(M)
         QQ=ARRIN(INDXT)
       ELSE
         INDXT=INDX(IR)
         QQ=ARRIN(INDXT)
         INDX(IR)=INDX(1)
         IR=IR-1
         IF(IR.EQ.1)THEN
            INDX(1)=INDXT
            RETURN
         END IF
      END IF
      I=M
      J=M+M
      DO WHILE(J.LE.IR)
         IF(J.LT.IR)THEN
            IF(ARRIN(INDX(J)).LT.ARRIN(INDX(J+1)))J=J+1
         END IF
         IF(QQ.LT.ARRIN(INDX(J))) THEN
            INDX(I)=INDX(J)
            I=J
            J=J+J
          ELSE
            J=IR+1
         END IF
      END DO
      INDX(I)=INDXT
      END DO OUTER

      END SUBROUTINE INDEXX
