      subroutine quit(text,i1,i2)
c
c     stops the program and writes a text
c
      implicit none
      character*(*)  :: text
      integer, intent(in) :: i1,i2
      write(6,"(1x,a,2x,2i10)") text,i1,i2
      write(10,"(1x,a,2x,2i10)") text,i1,i2
      stop
      end subroutine quit

