      SUBROUTINE TABINI
C     =================
C
C     Initialization and reading of the opacity table for thermal processe
C     and Rayleigh scattering
c     raytab: scattering opacities in cm^2/gm at 5.0872638e14 Hz (sodium D)
c     (NOTE: Quantities in rayleigh.tab are in log_e)
C
c     tempvec: array of temperatures
c     rhomat: array of densities (gm/cm^3)
c     nu:     array of frequencies
c     table:  absorptive opacities in cm^2/gm
c     (NOTE:  Quantities in absorption.tab are in log_e)
C
      use accura
      use atomic
      use basics
      use modelq
      use optabl

      implicit none
      REAL(DP), ALLOCATABLE :: tempve0(:),RHOVE0(:,:),ELECG0(:,:)
      REAL(DP), ALLOCATABLE :: rhov(:)
      INTEGER,  ALLOCATABLE :: INDT(:),INDR(:),NDEN(:)
      REAL,ALLOCATABLE      :: absopa0(:,:)

      CHARACTER(LEN=4) TYPA(matom)
      CHARACTER(LEN=80) optable,opta
      CHARACTER(len=100) :: DUM
      REAL(DP) :: FRTA
      INTEGER  :: ISTEPT,ISTEPR,ISTEPF,KST,NUMFRE0,NUMTEM0,NUMRH0
      INTEGER  :: IAT,IT,I,J,K,K0,NRMAX,IR,IJ,NUMR,NDEN0,IOS
c
      istept=1
      istepr=1
      istepf=1
c
      optable='./data/absopac.dat'
      read(15,*,iostat=kst) opta,ibinop
      if(kst.eq.0) optable=opta

      if(ibinop.eq.0) then
         open(53,file=optable,status='old')
       else
         open(53,file=optable,form='unformatted',status='old')
      end if
c
      read(15,*,iostat=kst) istept,istepr,istepf
c
      write(6,"(/' '
     *       /' OPACITY TABLE:  READ FROM THE FILE ',a70/' IBINOP=',i2/
     *        ' --------------'/)") optable,ibinop
      if(istept.gt.1.or.istepr.gt.1.or.istepf.gt.1) then
         write(6,*) ' BUT ONLY SELECTED DATA USED'
         write(*,"(a,3i4)") 'steps in T,rho,nu"',istept,istepr,istepf
         write(6,*)
      end if
c
c     reading the opacity table in the old mode
c
      if(ioptab.lt.0.and.iopold.gt.0) then
         if(ibinop.eq.0) then
            read(53,*) numfre0,numtem0,numrh0
            ALLOCATE (tempve0(numtem0),rhove0(numtem0,numrh0))
            read(53,*)
            read(53,*) (tempve0(i),i=1,numtem0)
            read(53,*)
            read(53,*) (rhove0(1,j),j=1,numrh0)
          else
            read(53) numfre0,numtem0,numrh0
            ALLOCATE (tempve0(numtem0),rhove0(numtem0,numrh0))
            read(53) (tempve0(i),i=1,numtem0)
            read(53) (rhove0(1,j),j=1,numrh0)
         end if
c
c     reading the opacity table in the new  mode
c
      else
         ioh2mt=0
         ih2h2t=0
         ih2het=0
         ioh2ht=0
         iohhet=0
         if(ibinop.eq.0) then
            read(53,*)
            read(53,*)
            do iat=1,matom
               read(53,'(a100)') dum
               read(dum,*,iostat=kst) typa(iat),abunt(iat),abuno(iat)
               if(kst.ne.0) exit
            end do
            if(kst.eq.0) read(53,*)
            read(53,*)
            read(53,*) ifmolt,tmolit
            read(53,*)
            read(53,*)
            read(53,'(a100)') dum
            read(dum,*,iostat=kst) iophmt,ioph2t,iophet,iopcht,iopoht,
     *              ioh2mt,ih2h2t,ih2het,ioh2ht,iohhet
            if(kst.ne.0) read(dum,*) iophmt,ioph2t,iophet,iopcht,iopoht
            read(53,*)
            read(53,*)
            read(53,*) numfre0,numtem0,numrh0
            ALLOCATE (tempve0(numtem0),rhove0(numtem0,numrh0))
            ALLOCATE (nden(numtem0))
            ALLOCATE (rhov(numrh0))
            ALLOCATE (elecg0(numtem0,numrh0))
            if(numrh0.gt.0) then
               read(53,*)
               read(53,*) (tempve0(i),i=1,numtem0)
               read(53,*)
               read(53,*) (rhov(j),j=1,numrh0)
               nden(1)=numrh0
               do j=1,numrh0
                  do i=1,numtem0
                     rhove0(i,j)=rhov(j)
                  end do
               end do
               do i=1,numtem0
                  nden(i)=nden(1)
               end do
               read(53,*)
               read(53,*) ((elecg0(i,j),j=1,numrh0),i=1,numtem0)
             else
               read(53,*) (nden(i),i=1,numtem0)
               read(53,*)
               read(53,*) (tempve0(i),i=1,numtem0)
               read(53,*)
               do i=1,numtem0
                  read(53,*) (rhove0(i,j),j=1,nden(i))
               end do
               read(53,*)
               do i=1,numtem0
                  read(53,*) (elecg0(i,j),j=1,nden(i))
               end do
            end if
          else
            do iat=1,92
               read(53) typa(iat),abunt(iat),abuno(iat)
            end do
            read(53) ifmolt,tmolit
            read(53) iophmt,ioph2t,iophet,iopcht,iopoht,
     *               ioh2mt,ih2h2t,ih2het,ioh2ht,iohhet
            read(53) numfre0,numtem0,numrh0
            ALLOCATE (tempve0(numtem0),rhove0(numtem0,numrh0))
            ALLOCATE (nden(numtem0))
            ALLOCATE (rhov(numrh0))
            ALLOCATE (elecg0(numtem0,numrh0))
            if(numrh0.gt.0) then
               read(53) (tempve0(i),i=1,numtem0)
               read(53) (rhov(j),j=1,numrh0)
               read(53) ((elecg0(i,j),j=1,numrh0),i=1,numtem0)
               nden(1)=numrh0
               do j=1,numrh0
                  do i=1,numtem0
                     rhove0(i,j)=rhov(j)
                  end do
               end do
               do i=1,numtem0
                  nden(i)=nden(1)
               end do
             else
               read(53) (nden(i),i=1,numtem0)
               read(53) (tempve0(i),i=1,numtem0)
               do i=1,numtem0
                  read(53) (rhove0(i,j),j=1,nden(i))
               end do
               do i=1,numtem0
                  read(53) (elecg0(i,j),j=1,nden(i))
               end do
            end if
         end if
c
      end if
c
C     select only a part of tabular data (if required)
C
      ALLOCATE(TEMPVEC(NUMTEM0),RHOVEC(NUMTEM0,NUMRH0))
      ALLOCATE (RHOMAT(NUMTEM0,NUMRH0),ELECGR(NUMTEM0,NUMRH0))
      ALLOCATE (ABSOPA0(NUMTEM0,NUMRH0))
      ALLOCATE (INDT(NUMTEM0),INDR(NUMRH0),NUMRH(NUMTEM0))

      j=0
      nrmax=0.
!     write(*,*) 'isteps',istept,istepr
      do it=1,numtem0,istept
         j=j+1
!        write(*,*) 'it,j',it,j
         tempvec(j)=tempve0(it)
!        write(*,*) 'tempv',tempvec(j),tempve0(it)
         indt(j)=it
!        write(*,*) 'indt',indt(j)
         k=0.
         numr=nden(it)
         nrmax=max(nrmax,numr)
         do ir=1,numr,istepr
            k=k+1
!           write(*,*) 'numr',ir,j,k
            rhomat(j,k)=rhove0(it,ir)
            indr(k)=ir
            elecgr(j,k)=elecg0(it,ir)
         end do
         numrh(j)=k
      end do
      numtemp=j
      if(numrh0.gt.0) numrho=k
      MTABT=NUMTEMP
      MTABR=NRMAX
!      write(*,*) 'numm',numtemp,numrho,mtabt,mtabr
      ij=0
      do k=1,numfre0
         if(mod(k,istepf).eq.0) ij=ij+1
      end do
      numfreq=ij
      MFREQ=numfreq
      MFREQC=numfreq
      MFRTAB=NUMFREQ
c
      write(6,"(' original number of frequencies, temperatures',
     *       ' densities:  ',3i7/)") numfre0,numtem0,numrh0
C
      if(istept.gt.1.or.istepr.gt.1.or.istepf.gt.1)
     * write(6,"(' modified number of frequencies, temperatures',
     *       ' densities:  ',3i7/)") numfreq,numtemp,numrho
C
      write(*,*) 'temperatures:'
      write(6,"(10F9.1)") (exp(tempvec(i)),i=1,numtemp)
      write(*,*) 'densities:'
      do i=1,numtemp
         numr=numrh(i)
         write(6,"('for T=',f9.1,(1p10e10.2))") 
     *         exp(tempvec(i)),(exp(rhomat(i,j)),j=1,numr)
      end do
c
c     check the consistency (or a lack thereof) the parameters of
c     the opacity table
c
      if(ioptab.gt.0.or.iopold.eq.0) call chctab
c
      RTAB1 = rhomat(1,1)
      RTAB2 = rhomat(1,numrho)
      TTAB1 = tempvec(1)
      TTAB2 = tempvec(numtemp)
c
      ALLOCATE (ABSOPAC(NUMTEMP,NUMRHO,NUMFRE0))
      ALLOCATE (FRTAB(NUMFRE0),FRLT(NUMFRE0))

      if(ibinop.eq.0) then
         ij=0
         nden0=numrh0
         do k=1,numfre0
            read(53,*)
            read(53,*)
            read(53,*) frta
            if(numrh0.gt.0) then
               do j = 1, numrh0
                  read(53,*) (absopa0(i,j),i=1,numtem0)
               end do
             else
               do i=1,numtem0
                  nden0=nden(i)
                  read(53,*) (absopa0(i,j),j=1,nden0)
               end do
            end if
            if(mod(k,istepf).eq.0.and.frta.lt.frtlim) then
               ij=ij+1
c              write(*,*) 'ij,k,frta',ij,k,frta
               frtab(ij)=frta
               frlt(ij)=log10(frta)
               do i=1,numtemp
                  numr=numrh(i)
                  do j=1,numr
                     absopac(i,j,ij)=absopa0(indt(i),indr(j))
                  end do
               end do
            end if
         end do
         numfreq=ij
         close(53)
       else
         ij=0
         do k=1,numfre0
            read(53) frta
            if(numrh0.gt.0) then
               do j = 1, numrh0
                  read(53) (absopa0(i,j),i=1,numtem0)
               end do
             else
               do i=1,numtem0
                  nden0=nden(i)
                  read(53,iostat=ios) (absopa0(i,j),j=1,nden0)
                  if(ios.ne.0) cycle
               end do
            end if
            if(mod(k,istepf).eq.0.and.frta.lt.frtlim) then
               ij=ij+1
               frtab(ij)=frta
               frlt(ij)=log10(frta)
               do i=1,numtemp
                  numr=numrh(i)
                  do j=1,numr
                     absopac(i,j,ij)=absopa0(indt(i),indr(j))
                  end do
               end do
            end if
         end do
         numfreq=ij
c
         K0=1
         DO K=1,NUMFREQ
            IF(FRTAB(K).GT.2.997925E13)  K0=K
         END DO
         DO K=1,NFREQ
            IF(FRTAB(K).LE.2.997925E13) THEN
               do i=1,numtemp
                  numr=numrh(i)
                  do j=1,numr
                     absopac(i,j,k)=absopac(i,j,k0)
                  end do
               end do
            END IF
         END DO
         close(53)
      end if
c
      write(*,"(/'final nfreq, lim.freqs',i7,1p2e13.5/)") numfreq,
     *   frtab(1),frtab(numfreq)
      frtabm=max(frtab(1),frtab(numfreq))

      IF(IOPTAB.LT.0) THEN
         NFREQ=NUMFREQ	
         IF(IFRSET.GT.0) NFREQ=IFRSET
         MFREQ=NFREQ
         MFREQC=NFREQ
         MFREQP=1
         MFREQL=1
         MFREX=1
         ALLOCATE (FREQ(MFREQ),W(MFREQ))
         ALLOCATE (IJALI(MFREQ),JIK(MFREQ),IJX(MFREQ)) 
      END IF

      DEALLOCATE (ABSOPA0,TEMPVE0,RHOVE0,ELECG0,RHOV,NDEN)
      RETURN
      END SUBROUTINE TABINI

C
C     **************************************************************
c

      SUBROUTINE TABINT
C     =================
C
      use accura
      use atomic
      use basics
      use modelq
      use optabl

      implicit none

      real(dp), allocatable :: absort(:)
      real(dp) :: fr1,fr2,xint,rc,opac
      integer  :: ij,jl,ju,jm,j,it,ir,k
C
      IF(IOPTAB.LT.0.AND.IFRSET.EQ.0) THEN
c
C     if frequencies are exactly tabular
c
         nfreq=numfreq
         nfreqc=numfreq
         do ij=1,nfreq
            freq(ij)=frtab(ij)
            ijfr(ij)=ij
            jik(ij)=ij
            ijali(ij)=1
            ijx(ij)=1
         end do
         w(1)=half*(frtab(1)-frtab(2))
         w(nfreq)=half*(frtab(nfreq-1)-frtab(nfreq))
         do ij=2,nfreq-1
            w(ij)=half*(frtab(ij-1)-frtab(ij+1))
         end do
C
       ELSE
C
C      if frequencies are already set
c
c      set up interpolation coefficients for frequency interpolation
c      by bisection
c
         fr1=frtab(1)
         fr2=frtab(numfreq)
         ALLOCATE (ABSORT(MFRTAB))
         ALLOCATE (YINR(MFREQ),JINT(MFREQ))

          write(*,*) 'tabint',numfreq,fr1,fr2
          write(*,*) 'tabinf',nfreq,freq(1),freq(nfreq)

         write(*,*) 'shape yinr,jint',shape(yinr),shape(jint)
         write(*,*) 'shape freq, nfreq',shape(freq),nfreq
         do ij=1,nfreq
            xint=freq(ij)
            jl=0
            ju=numfreq+1
            do
               if(ju-jl.le.1) exit
               jm=(ju+jl)/2
               if((fr2.gt.fr1).eqv.(xint.gt.frtab(jm))) then
                  jl=jm
                else
                  ju=jm
               end if
            end do
            j=jl
            if(j.eq.numfreq) j=j-1
            if(j.eq.0) j=j+1
            jint(ij)=j
            yinr(ij)=un/log10(frtab(j+1)/frtab(j))
         end do
c
         write(*,*) 'shape absort',shape(absort)
         write(*,*) 'shape absopac',shape(absopac)
         write(*,*) 'num',numtemp,numrho,numfreq,nfreq
         do it=1,numtemp
            numrho=numrh(it)
            do ir=1,numrho
               do k=1,numfreq
                  absort(k)=absopac(it,ir,k)
               end do
               do ij=1,nfreq
                  j=jint(ij)
                  rc=(absort(j+1)-absort(j))*yinr(ij)
                  opac=rc*log10(freq(ij)/frtab(j))+absort(j)
                  absopac(it,ir,ij)=real(opac)
               end do
            end do
         end do
c
c        reset tabular opacities to zero out of range of FREQ
c
         do ij=1,nfreq
            if(freq(ij).lt.fr2*0.99.or.freq(ij).gt.fr1*1.01) then
               do it=1,numtemp
                  numrho=numrh(it)
                  do ir=1,numrho
                     absopac(it,ir,ij)=0.
                  end do
               end do
            end if
         end do
         DEALLOCATE (ABSORT,YINR,JINT)
      END IF
      write(*,*) 'end tabint'
C
      RETURN
      END SUBROUTINE TABINT

