      SUBROUTINE CORRWM
C     =================
C
C     The routine for management of various flags for treating
C     frequency points
C
      use accura
      use atomic
      use basics
      use modelq

      implicit none 

      REAL(DP), PARAMETER :: T15=1.e-15
      REAL(DP) :: FR,A1
      INTEGER :: IJ,ID,IJ0,IJ1,KJ,IJT,ITR,INX
 
      NFREQE=0
      DO IJ=1,NFREQ
         IJEX(IJ)=0
         DO ID=1,ND
            LSKIP(ID,IJ)=.FALSE.
         END DO
         if(ifprad.eq.0) then
            do id=1,nd
               lskip(id,ij)=.true.
            end do
         end if
         IF(IJALI(IJ).NE.0) CYCLE
         NFREQE=NFREQE+1
         IJEX(IJ)=NFREQE
         IJFR(NFREQE)=IJ
      END DO

      MFREX=NFREQE+1
c     write(6,"(/'MFREX = ',i4,'  (determined in corrwm)')") mfrex
c
      if(ifryb.ne.0) then
         nfreqe=0
         do ij=1,nfreq
            ijex(ij)=0
         end do
      end if
C
      IF(IBFINT.LE.0) THEN
         DO IJ=1,NFREQ
            IJBF(IJ)=IJ
            AIJBF(IJ)=UN
         END DO
       ELSE
         IF(ISPODF.EQ.0) THEN
            DO IJ=1,NFREQC
               IJBF(IJ)=IJ
               AIJBF(IJ)=UN
            END DO
            IF(NFREQ.GT.NFREQC) THEN
               DO IJ=NFREQC+1,NFREQ
                  FR=FREQ(IJ)
                  IJ0=1
                  DO IJT=1,NFREQC
                     IF(FREQ(IJT).LE.FR) THEN
                        IJ0=IJT
                        EXIT
                     END IF
                  END DO
                  IJ1=IJ0-1
                  A1=(FR-FREQ(IJ0))/(FREQ(IJ1)-FREQ(IJ0))
                  IJBF(IJ)=IJ1
                  AIJBF(IJ)=A1
               END DO
            END IF
          ELSE
            DO IJ=1,NFREQC-1
               IJ0=IFREQB(IJ)
               IJ1=IFREQB(IJ+1)
               DO KJ=IJ0,IJ1-1
                  IJBF(KJ)=IJ
                  AIJBF(KJ)=(FREQ(KJ)-FREQ(IJ1))/(FREQ(IJ0)-FREQ(IJ1))
               END DO
            END DO
            IJ0=IFREQB(NFREQC)
            IJBF(IJ0)=NFREQC
            AIJBF(IJ0)=UN
         END IF
      END IF
C
c     if(nfreqe.gt.mfrex) CALL QUIT('nfreqe.gt.mfrex',nfreqe,mfrex)
C
      DO ITR=1,NTRANS
         IF(.NOT.LINE(ITR)) CYCLE
C
C        first set up array LSKIP(ID,IJ), which has values
C        TRUE - if the radiation at frequency point IJ does not contribute
C               radiation pressure (ie. this point belongs to a transition
C               for which the user required the radiation pressure to be
C               skipped - IABS(INDEXP) chosen as 9 or 19)
C        FALSE - normal calculation of radiation pressure
C
         INX=IABS(INDEXP(ITR))
         IF(INX.EQ.9.OR.INX.GE.19) THEN
            DO IJ=IFR0(ITR),IFR1(ITR)
               DO ID=1,ND
                  LSKIP(ID,IJ)=.TRUE.
               END DO
            END DO
         END IF
      END DO
C
      IF(NFREQE.GT.0) WRITE(6,"(//' FREQUENCY POINTS AND WEIGHTS'
     *            ' - EXPLICIT'/
     *            ' ---------------------------------------'//
     * '       IJE','       IJ'7X,'FREQ',13X,'WEIGHT'/)")
      DO IJ=1,NFREQ
         W0E(IJ)=W(IJ)*PI4H/FREQ(IJ)
         BNUE(IJ)=BN*(FREQ(IJ)*T15)**3
         IF(IJALI(IJ).NE.0.or.ifryb.gt.0) CYCLE
         WRITE(6,"(2I8,1P2e17.8)") IJEX(IJ),IJ,FREQ(IJ),W(IJ)
      END DO
C
      DO IJ=1,NFREQ
         WC(IJ)=W(IJ)
         IF(IJALI(IJ).LE.0) WC(IJ)=0.
CCCCCCCCCCCCCCCCCCCCCCCCCCCC
         lskip(id,ij)=.false.
CCCCCCCCCCCCCCCCCCCCCCCCCCCC
      END DO

      RETURN
      END SUBROUTINE CORRWM

C
C     ********************************************************************
C


      SUBROUTINE TRAINI
C     =================
C
C     initialization of depth-independent quantities
C     for evaluation of opacities
C
      use accura
      use atomic
      use basics
      use modelq
      use odfpar

      implicit none

      integer :: itr,ibft,ii,modw,ncdw,ij
c
c      write(*,*) 'mtrans,mmcdw,mfreq',mtrans,mmcdw,mfreq
c     ALLOCATE (MCDW(MTRANS),ITRCDW(MMCDW))
c     ALLOCATE (IJLIN(MFREQ))
      do itr=1,ntrans
         idiel(itr)=0
      end do
C
C     bound-free transitions
C
c      write(*,*) 'ntranc,mbf,mmcdv',ntranc,mbf,mmcdw
      NCDW=0
      DO IBFT=1,NTRANC
         ITR=ITRBF(IBFT)
         ii=ilow(itr)
         if(ilk(iup(itr)).ne.0.and.nfirst(iel(ii)).eq.ii.
     *      and.IFDIEL.NE.0) idiel(itr)=1
         MODW=IABS(INDEXP(ITR))
         MCDW(ITR)=0
c      write(*,*) 'ibft,itr,ibf,modw,ncdw',ibft,itr,ibf(ibft),modw,ncdw
         IF(MODW.NE.5.AND.MODW.NE.15.and.ibf(ibft).ne.16) CYCLE
         NCDW=NCDW+1
c      write(*,*) 'ibft,itr,ibf,modw,ncdw',ibft,itr,ibf(ibft),modw,ncdw
         MCDW(ITR)=NCDW
         ITRCDW(NCDW)=ITR
c      if(ibft.ge.ntranc-1) write(*,*) 'itrcdw',itr,mcdw(itr),ncdw,itrcdw(ncdw)
      END DO
c     write(*,*) 'ISPODF',ispodf
c     stop
      IF(ISPODF.GE.1) RETURN
C
C     bound-bound transitions
C
c     DO IJ=1,NFREQ
c        NLINES(IJ)=0
c     END DO
C
c      write(*,*) 'ntrans',ntrans
      DO ITR=1,NTRANS
         IF(LINEXP(ITR)) CYCLE
c        write(*,*) 'ifr01',itr,ifr0(itr),ifr1(itr)
         DO IJ=IFR0(ITR),IFR1(ITR)
            IJLIN(IJ)=ITR
         END DO
      END DO
      RETURN
      END SUBROUTINE TRAINI
C
C     ********************************************************************
C


      SUBROUTINE INPMOD
C     =================
C
C     Read an initial model atmosphere from unit 8
C     File 8 contains:
C      1. NDPTH -  number of depth points in which the initial model is
C                  given (if not equal to ND, routine interpolates
C                  automatically to the set DM by linear interpolation
C                  in log(DM)
C         NUMPAR - number of input model parameters in each depth
C                  = 3 for LTE model - ie. N, T, N(electron);
C                  > 3 for NLTE model)
C      2. DEPTH(ID),ID=1,NDPTH - mass-depth points for the input model
C      3. for each depth:
C                 T   - temperature
C                 ANE - electron density
C                 RHO - mass density
C                 level populations - only for NLTE input model
C                       Number of input level populations need not be
C                       equal to NLEVEL; in that case the procedure
C                       CHANGE is called from START to calculate the
C                       remaining level populations
C
C     Note: The output file 7, which is created by this program
C           (procedure OUTPUT) has the same structure as file 8
C           and may thus be used as input to another run of the
C           program
C
C     INTRPL - switch indicating whether (and, if so, how) interpolate
C              the initial model if the depth scales for the input model
C              and the present depth scale are different
C            = 0  -  no interpolation, scale DEPTH replaces DM;
C                    i.e. DEPTH will be used as DM, regardless of which
C                    values of DM were read in subroutine START
C            > 0  -  polynomial interpolation of the (INTRPL-1)th order
C
C            < 0  -  reads different initial models (eg. -1 : Kurucz model)
C
C     If INTRPL > 0, there is an additional input from unit 8, namely
C     new depth scale DM, the one which will be used in the present run
C
      use accura
      use atomic
      use basics
      use modelq
CC    use molec

      implicit none

      REAL(DP), ALLOCATABLE :: 
     *          TEMP0(:),ELEC0(:),DENS0(:),PPL0(:),
     *          DEPTH(:),PPL(:),POPLTE(:),X(:),ZD0(:)
      INTEGER, ALLOCATABLE  :: IIFOR0(:)

      REAL(DP) :: T,AEIN,AN,ANE,ANHN,ENRG,ENTT,WM
      INTEGER  :: NUMLT,NDPTH,NUMPAR,NUMP,ID,I,IP,IPRI
      LOGICAL  :: LCHC0,LTE0

      ALLOCATE 
     *      (TEMP0(MDEPTH),ELEC0(MDEPTH),DENS0(MDEPTH),PPL0(MDEPTH),
     *       DEPTH(MDEPTH),PPL(MDEPTH),POPLTE(MLEVEL),X(MLEVEL+5),
     *       ZD0(MDEPTH))
      ALLOCATE  (iifor0(mlevel))
C
      LCHC0=LCHC
      LCHC=.TRUE.
      LTE0=LTE
      LTE=.TRUE.
      NUMLT=3
      IF(IDISK.EQ.1) NUMLT=4
      IF(IFMOL.GT.0) NUMLT=NUMLT+1
      RRDIL=1.
      TEMPBD=0.
      IF(INTRPL.GE.0) THEN
         READ(8,*) NDPTH,NUMPAR
         ND=NDPTH
         IF(NDPTH.LE.0) CALL QUIT('NDPTH.LE.0 in Unit 8',ndpth,0)
         IF(NDPTH.GT.MDEPTH)
     *      CALL QUIT('NDPTH.GT.MDEPTH in Unit 8',ndpth,mdeptH)
         READ(8,*) (DM(ID),ID=1,ND)
         IDSTD=0
         NUMP=ABS(NUMPAR)
         DO ID=1,NDPTH
            READ(8,*) (X(I),I=1,NUMP)
            do i=1,nump
               if(x(i).lt.0.) x(i)=0.
            end do
            TEMP(ID)=X(1)
            ELEC(ID)=X(2)
            DENS(ID)=X(3)
            TOTN(ID)=DENS(ID)/WMM(ID)+ELEC(ID)
            IP=3
            IF(NUMPAR.LT.0) THEN
               IP=IP+1
               TOTN(ID)=X(IP)
            END IF
            IF(IDISK.EQ.1) THEN
               IP=IP+1
               ZD(ID)=X(IP)
            END IF
            IF(TEMP(ID).LT.TEFF) IDSTD=ID
            t=temp(id)
            if(ifmol.gt.0.and.t.lt.tmolim) then
               ipri=1
               aein=elec(id)
               an=totn(id)
               call moleq(id,t,an,aein,ane,enrg,entt,wm,ipri)
            end if
            IF(NUMP.GT.IP) THEN
               NLEV0=NUMP-IP
               DO I=1,NLEV0
                  POPUL(I,ID)=X(IP+I)
               END DO
            END IF
       if(id.eq.1) then
       write(*,"('num',6i4)") id,numpar,nump,ip,nlev0,nlevel
       write(*,"(1p10e12.4)") (popul(i,id),i=1,nlev0)
       end if
            IF(NUMP.EQ.IP.OR.(NLEV0.NE.NLEVEL.AND.LTE)) THEN
               NLEV0=NLEVEL
               CALL WNSTOR(ID)
               CALL SABOLF(ID)
               DO I=1,NLEV0
                  IIFOR0(I)=I
               END DO
               CALL RATMAL(ID,NLEV0)
               CALL LEVSOL(POPLTE,IIFOR0,NLEV0,1)
               DO I=1,NLEV0
                  POPUL(I,ID)=POPLTE(I)
               END DO

               if(ifmol.le.0.or.t.ge.tmolim) then
                  n0hn=nfirst(ielh)
                  if(n0hn.gt.0) then
                     anato(1,id)=popul(n0hn,id)
                   else
                     anato(1,id)=dens(id)/wmm(id)/ytot(id)
                  end if
                  if(iathe.gt.0) then
                     anato(2,id)=popul(n0a(iathe),id)
                   else
                     anato(2,id)=dens(id)/wmm(id)/ytot(id)*abndd(2,id)
                  end if
               end if
c

            END IF
         END DO
c
         write(*,"(/'INPUT MODEL'/)")
         write(*,"('  ID      DM          T         Ntot       Ne',
     *             '          Np          NH_1'/)") 
         do id=1,nd
            anhn=popul(nfirst(ielh),id)
            anp=popul(nka(iath),id)
            write(6,"(i4,1pe12.3,0pf10.1,1p5e12.3)") 
     *      id,dm(id),temp(id),totn(id),elec(id),anp,anhn
         end do

         ELSTD=ELEC(IDSTD)
c        READ(8,*,IOSTAT=IOS) INTRPL
       ELSE IF(INTRPL.GT.-10) THEN
         CALL KURUCZ(NDPTH)
         NUMPAR=3
         IF(ND.NE.NDPTH .AND. INTRPL.EQ.0)
     *      CALL QUIT('ND.NE.NDPTH in KURUCZ',nd,ndpth)
       ELSE
         CALL INCLDY(NDPTH)
         NUMPAR=3
         IF(ND.NE.NDPTH .AND. INTRPL.EQ.0)
     *      CALL QUIT('ND.NE.NDPTH in INCLDY',nd,ndpth)
      END IF

      LCHC=LCHC0
      LTE=LTE0
C
      IF(IDISK.EQ.1) THEN
         ZND=ZD(ND)
         IF(ZND.GT.0.) IFZ0=-1
      END IF
c
c !!!!! attention - temporary fix
c
      if(idisk.eq.1) zd(nd)=0.
C
c
      if(ioptab.ge.0) return
      IF(IOPTAB.LT.0) RETURN
      do id=1,nd
         ptotal(id)=dm(id)*grav
         an=ptotal(id)/(bolk*temp(id))
         elec(id)=1.e-16*an
         wmm(id)=dens(id)/an
      end do

      DEALLOCATE (TEMP0,ELEC0,DENS0,PPL0)
      DEALLOCATE (DEPTH,PPL,POPLTE,X,ZD0)
      DEALLOCATE (IIFOR0)

      RETURN 
      END SUBROUTINE INPMOD
C
C
C     ****************************************************************
C
C
      SUBROUTINE KURUCZ(NDPTH)
C     ========================
C
C     Read an initial model atmosphere from unit 8
C      in Kurucz ATLAS' format
C
      use accura
      use atomic
      use basics
      use modelq
CC    use molec

      implicit none 
      
      INTEGER, INTENT(OUT)  ::NDPTH
      INTEGER, PARAMETER    :: MINPUT=7
      CHARACTER(LEN=15)     :: KUR
      INTEGER               :: KKFIX0(MLEVEL)
      REAL(DP), ALLOCATABLE :: TEMP0(:),ELEC0(:),DENS0(:),PPL0(:),
     *                         DEPTH(:),PPL(:),POPLTE(:),X(:)

      INTEGER, ALLOCATABLE  :: IIFOR0(:)
      REAL(DP) :: T,AN,AEIN,A1,A2,A3,RHO,RHO0,P,VEL,TEF,TEFFK,GRAVK
      REAL(DP) :: ANE0,TTT,ENR,ENT,ANE,WM
      INTEGER  :: IAT,IEFF,IEFFK,IRAV,IRAVK,NUMPAR,ID,I
      LOGICAL  :: LCHC0,LTE0

      ALLOCATE 
     *      (TEMP0(MDEPTH),ELEC0(MDEPTH),DENS0(MDEPTH),PPL0(MDEPTH),
     *       DEPTH(MDEPTH),PPL(MDEPTH),POPLTE(MLEVEL),X(MINPUT))

      ALLOCATE  (iifor0(mlevel))
C

      do iat=1,natom
         kkfix0(iat)=iifix(iat)
         iifix(iat)=0
      end do
      nlev0=nlevel
      LCHC0=LCHC
      LCHC=.TRUE.
      LTE0=LTE
      LTE=.TRUE.
C
C     normal Kurucz model
C
      IF(IFIXDE.EQ.0) THEN
         READ(8,"(A15,6X,F8.5)") KUR,GRAVK
         READ(KUR,"(4X,F8.0)") TEFFK
C
         IF(KUR(1:4).NE.'TEFF')
     *     CALL QUIT(' Unit 8 is NOT a Kurucz model as expected',0,0)
         IF(ABS(TEFFK-TEFF).GT.50.) then
           ieff=int(teff)
           ieffk=int(teffk)
         END IF
         IF(ABS(GRAVK-LOG10(GRAV)).GT.0.02) then
           irav=int(log10(grav)+0.001)
           iravk=int(gravk)
         END IF
C
         DO WHILE(KUR(1:9).NE.'READ DECK')
            READ(8,"(A15)") KUR
         END DO
         READ(KUR,"(10X,I3)") NDPTH
         NDPTH=NDPTH-1
         NUMPAR=3
         NLEV0=NLEVEL
         READ(8,*) TTT
         IF(NDPTH.gt.mdepth.and.intrpl.eq.0)
     *   CALL QUIT('ndpth.gt.mdepth in KURUCZ',ndpth,mdepth)
         DO ID=1,NDPTH
            READ(8,*) (X(I),I=1,MINPUT)
            DEPTH(ID)=X(1)
            TEMP0(ID)=X(2)
            ELEC0(ID)=X(4)
            AN=X(3)/BOLK/TEMP0(ID)
            DENS0(ID)=WMM(ID)*(AN-ELEC0(ID))
            TEMP(ID)=TEMP0(ID)
            ELEC(ID)=ELEC0(ID)
            DENS(ID)=DENS0(ID)
            ANMA(ID)=DENS(ID)/WMM(ID)
            ANTO(ID)=ANMA(ID)+ELEC(ID)
            TOTN(ID)=ANTO(ID)
            T=TEMP(ID)
            IF(IFMOL.GT.0.AND.T.LT.TMOLIM) THEN
               AN=TOTN(ID)
               AEIN=ELEC(ID)
               CALL MOLEQ(ID,T,AN,AEIN,ANE,ENR,ENT,WM,1)
            END IF
            CALL WNSTOR(ID)
            CALL SABOLF(ID)
            DO I=1,NLEV0
               IIFOR0(I)=I
            END DO
            CALL RATMAT(ID,IIFOR0,-1)
            CALL LEVSOL(POPLTE,IIFOR0,NLEV0,1)
            DO I=1,NLEV0
               POPUL0(I,ID)=POPLTE(I)
            END DO
         END DO
C
         INTRPL=0
c        DO WHILE(KUR(1:5).NE.'BEGIN')
c           READ(8,'(A15)',END=100,ERR=100) KUR
c        END DO
       ELSE
C
C        case of fixed density - input of special Kurucz mopdels
C
         READ(8,"(4X,F8.0,9X,F8.5)") TEF,GRAV
         WRITE(6,"(/' INPUT KURUCZ MODEL FOR TEFF=',F7.0,'   LOG G =',
     *       F7.2//1H ,7X,'MASS',9X,'T',9X,'P',9X,'DENS',9X,'ELEC'//)")
     *       TEF,GRAV
         READ(8,"(/////////////////////10X,I3/)") ND
         ND=ND-1
C
         DO ID=1,ND
            READ(8,*) DM(ID),TEMP(ID),P,ane0,a1,a2,a3,vel,rho
            if(temp(id).lt.tfloor) temp(id)=tfloor
CC          CALL RHONEN(ID,TEMP(ID),RHO,AN,ANE)
            ELEC(ID)=ANE0
CC          ELEC(ID)=ANE
            DENS(ID)=RHO
            TOTN(ID)=DENS(ID)/WMM(ID)+ELEC(ID)
            an=rho/wmm(id)+ane0
            rho0=WMM(ID)*(AN-ELEC(ID))
            WRITE(6,"(1H ,I5,1PE10.3,0PF10.1,1P5D12.3)")
     *           ID,DM(ID),TEMP(ID),P,DENS(ID),ELEC(ID),rho0,an
            CALL WNSTOR(ID)
            CALL SABOLF(ID)
            DO I=1,NLEV0
               IIFOR0(I)=I
            END DO
            CALL RATMAT(ID,IIFOR0,-1)
            CALL LEVSOL(POPLTE,IIFOR0,NLEV0,1)
            DO I=1,NLEV0
               POPUL(I,ID)=POPLTE(I)
            END DO
         END DO
         write(6,"(' nd',i4)") nd
      END IF

C
      do iat=1,natom
         iifix(iat)=kkfix0(iat)
      end do
      LCHC=LCHC0
      LTE=LTE0
      DEALLOCATE (TEMP0,ELEC0,DENS0,PPL0)
      DEALLOCATE (DEPTH,PPL,POPLTE,X)
      DEALLOCATE (IIFOR0)
C
      RETURN
      END SUBROUTINE KURUCZ
C
C
C     ****************************************************************
C
C
      SUBROUTINE INCLDY(NDPTH)
C     ========================
C
C     Read an initial model atmosphere from unit 8
C      in Cloudy's format as provided by Katya Verner
C
      use accura
      use atomic
      use basics
      use modelq

      implicit none

      INTEGER, PARAMETER :: MINPUT=6
      REAL(DP) ::  RS(MDEPTH)
      INTEGER  ::  KKFIX0(MLEVEL)
C
      REAL(DP), ALLOCATABLE :: 
     *          TEMP0(:),ELEC0(:),DENS0(:),PPL0(:),
     *          DEPTH(:),PPL(:),POPLTE(:),X(:)
      INTEGER, ALLOCATABLE  :: IIFOR0(:)

      REAL(DP) :: TSTARY,RSTARY,DDDM,AN
      INTEGER  :: IAT,NDPTH,NUMPAR,ID,I

      ALLOCATE 
     *      (TEMP0(MDEPTH),ELEC0(MDEPTH),DENS0(MDEPTH),PPL0(MDEPTH),
     *       DEPTH(MDEPTH),PPL(MDEPTH),POPLTE(MLEVEL),X(MINPUT))
      ALLOCATE (iifor0(mlevel))
C

      do iat=1,natom
         kkfix0(iat)=iifix(iat)
         iifix(iat)=0
      end do
C
      READ(8,*) NDPTH
      NUMPAR=3
      IF(NDPTH.gt.mdepth.and.intrpl.eq.0)
     *   CALL QUIT('ndpth.gt.mdepth in INCLDY',ndpth,mdepth)
      NLEV0=NLEVEL
      READ(8,*) TSTARY,RSTARY
      IF(RSTARY.LT.1.E6) RSTARY=RSTARY*6.96E10
C
      DO ID=NDPTH,1,-1
         READ(8,*) (X(I),I=1,MINPUT)
         RS(ID)=X(1)
         TEMP0(ID)=X(2)
         ELEC0(ID)=X(4)
         AN=X(3)/BOLK/TEMP0(ID)
         DENS0(ID)=WMM(ID)*X(3)
         TEMP(ID)=TEMP0(ID)
         ELEC(ID)=ELEC0(ID)
         DENS(ID)=DENS0(ID)
         ANMA(ID)=DENS(ID)/WMM(ID)
         ANTO(ID)=ANMA(ID)+ELEC(ID)
      END DO
      DM(1)=0.
      DEPTH(1)=0.
      DO ID=2,NDPTH
         DDDM=(DENS(ID-1)+DENS(ID))*(RS(ID-1)-RS(ID))
      DM(ID)=DM(ID-1)+0.5*DDDM
      DEPTH(ID)=DM(ID)
      END DO
C
      RRDIL=(RSTARY/RS(NDPTH))*(RSTARY/RS(NDPTH))
      TEMPBD=TSTARY
C
      DO ID=1,NDPTH
         CALL WNSTOR(ID)
         CALL SABOLF(ID)
         DO I=1,NLEV0
            IIFOR0(I)=I
         END DO
         CALL RATMAT(ID,IIFOR0,-1)
         CALL LEVSOL(POPLTE,IIFOR0,NLEV0,1)
         DO I=1,NLEV0
            POPUL0(I,ID)=POPLTE(I)
         END DO
      END DO
C
      INTRPL=0
      do iat=1,natom
         iifix(iat)=kkfix0(iat)
      end do
C
      DEALLOCATE (TEMP0,ELEC0,DENS0,PPL0)
      DEALLOCATE (DEPTH,PPL,POPLTE,X)
      DEALLOCATE (IIFOR0)

      RETURN
      END SUBROUTINE INCLDY



!*************************************************************************




      SUBROUTINE IROSET
C     =================
C
C     Initialization of opacity sampling for iron-peak lines
C
C     IOBS = 2 : ALL lines except lines to autoionized levels
C     IOBS = 1 : ALL lines
C     IOBS = 0 : only lines between observed levels
C
      use accura
      use atomic
      use basics
      use modelq
      use odfpar

      implicit none

      REAL(DP), PARAMETER   :: CSIG=0.0149736
      REAL, ALLOCATABLE     :: SIGT(:,:)
      REAL(DP), ALLOCATABLE :: DMLL(:)

      REAL(DP):: DXI,XFRMA,SUMP,GSUPER,FCOL,FRL,D1,D2,VV,W1,W2
      REAL(DP):: PRFK,SXX,VOIGTE,DNU,D0
      INTEGER :: I,ID,IJD,NFTMX,ION,IOBS,IND,N1,NLII,KEVL,KODL
      INTEGER :: ILOK,IL,IU,IUPK,ITR,IFRKU,NFT,NLT,KEVU,KODU,KEV,KOD,IEO
      INTEGER :: IJ,IJL,IJ0,IJ1,KJ,ITRL,INDXPA,JIDC,K
      LOGICAL :: LTE0

!
!     allocate arrays from module odfpar
!
      ALLOCATE (EMKU(MLEVEL,2),YMKU(MLEVEL,2),EU(2*MLEVEL))
      ALLOCATE (EEV(MKULEV),AEV(MKULEV),SEV(MKULEV),WEV(MKULEV))
      ALLOCATE (EOD(MKULEV),AOD(MKULEV),SOD(MKULEV),WOD(MKULEV))
      ALLOCATE (KSEV(MKULEV),KSOD(MKULEV),JEN(2*MLEVEL))
      ALLOCATE (XJID(MDEPTH),JIDI(MDEPTH),JIDR(MDODF)) 
      ALLOCATE (OMES(100,100),EKU(2*MKULEV),GKU(2*MKULEV))
      ALLOCATE (KKU(2*MKULEV))

      ALLOCATE (WAVE(MLINE),VDOP(MLINE,MDODF))
      ALLOCATE (AGAF(MLINE,MDODF),SIG0(MLINE,MDODF))
      ALLOCATE (JTR(MLINE,2))
!
!     allocate temporary arrays
!
      ALLOCATE (SIGT(MDODF,MFREQ),DMLL(MDEPTH))

      JIDR(1)=1
      IF(JIDS.EQ.0) THEN
         JIDR(2)=INT(0.7*ND)
         JIDR(3)=ND
         JIDN=3
         JIDC=2
       ELSE
         I=1
         DO WHILE(JIDR(I).LT.ND)
            I=I+1
            JIDR(I)=JIDR(I-1)+JIDS
            IF(JIDR(I).LE.INT(0.7*ND)) JIDC=JIDR(I)
         END DO
         JIDN=I
         IF(JIDR(I).GT.ND) THEN
            IF(JIDR(I-1).GE.ND-5) JIDN=JIDN-1
            JIDR(JIDN)=ND
         END IF
         IF(JIDN.GT.MDODF)
     &   CALL QUIT(' Too many depths for Fe x-sections',JIDN,MDODF)
      END IF

      DO ID=1,ND
         DMLL(ID)=LOG(DM(ID))
      END DO
      DO I=1,JIDN-1
         DXI=DMLL(JIDR(I+1))-DMLL(JIDR(I))
         DO ID=JIDR(I)+1,JIDR(I+1)
            JIDI(ID)=I
            XJID(ID)=(DMLL(JIDR(I+1))-DMLL(ID))/DXI
         END DO
      END DO
      JIDI(1)=1
      XJID(1)=1.

      XFRMA=LOG(FRS1)
      IJD=INT(9./DDNU)
      IF(IJD.LT.2) IJD=2
      NFTT=0
      NFTMX=0
C
c
c     In the case level population were not read, set them to LTE
c
      sump=0.
      do i=1,nlevel
         sump=sump+popul(i,1)
      end do
      if(sump.le.0.) then
         lte0=lte
         lte=.true.
         do id=1,nd
CC          call steqeq(id,pop,1)
c           if(id.eq.1) write(*,*) 'popul',pop(1),
c    *         (popul(i,id),i=1,nlevel)
         end do
         lte=lte0
      end if
c
c     computing the number of nrede liine cross-sections (MCFE)
c
      CALL IROST0

      NFTT=0
      NFTMX=0
c 
c     loop over ions with line-blanketing data
c
      IONLOOP: DO ION=1,NION
         IND=INODF1(ION)
         IF(IND.LE.0) CYCLE IONLOOP
         IF(NLLIM(ION).GE.NLEVS(ION)) THEN
            DO ID=1,ND
               DO I=NFIRST(ION),NLAST(ION)
                  WOP(I,ID)=UN
               END DO
            END DO
            CYCLE IONLOOP
         END IF
C
C       Set up superlevels and read line data
C
        IOBS=IKOBS(ION)
        CALL LEVCD(ION,IOBS)
        CALL INKUL(ION,IOBS)
c
        write(6,"(/' *** superlines for ',i4,': ',a4,
     *  '   selected internal lines:',i10)") ion,typion(ion),nlinku
!       if(nlinku.gt.mline)
!    *     call quit('too many internal lines',nlinku,mline)
C
C       Assign line to supertransition and compute cross-section
C
        N1=NFIRST(ION)
        NLII=NLAST(ION)-N1+1
        DO IL=1,NLII-1
           KEVL=0
           KODL=0
           IF(JEN(IL).LE.NEVKU(ION)) THEN
              KEVL=JEN(IL)
            ELSE
              KODL=JEN(IL)-NEVKU(ION)
           END IF
           ILOK=N1+IL-1
           DO IU=IL+1,NLII
              IUPK=N1+IU-1
              ITR=ITRA(ILOK,IUPK)
              INDXPA=ABS(INDEXP(ITR))
              W1=0.
              W2=0.
              IFRKU=0
              NFT=0
              NLT=0
              KEVU=0
              KODU=0
              IF(JEN(IU).LE.NEVKU(ION)) THEN
                 KEVU=JEN(IU)
               ELSE
                 KODU=JEN(IU)-NEVKU(ION)
              END IF
c      if(ion.eq.35)  write(*,*) 'iu',iu,itr,kevu,kodu
              IF(KEVL.NE.0) THEN
                 KEV=KEVL
                 KOD=KODU
                 IEO=0
                 GSUPER=YMKU(JEN(IL),1)
               ELSE
                 KEV=KEVU
                 KOD=KODL
                 IEO=1
                 GSUPER=YMKU(JEN(IL)-NEVKU(ION),2)
              END IF
c          if(ion.eq.35) write(43,"(10i7,3f9.1)") ion,il,iu,
c    * nevku(ion),kevl,kodl,jen(il),jen(iu),kevu,kodu,
c    * ymku(jen(il),1),ymku(jen(il),2),gsuper
              DO IJ=1,MFREQ
                 DO I=1,MDODF
                    SIGT(I,IJ)=ZERO
                 END DO
              END DO
              FCOL=0.

              LINELOOP: DO K=1,NLINKU
c        if(ion.eq.35) write(*,"(7i8)")
c    * k,jtr(k,1),jtr(k,2),ksev(jtr(k,1)),kev,ksod(jtr(k,2)),kod
                 IF(KSEV(JTR(K,1)).NE.KEV) CYCLE LINELOOP
                 IF(KSOD(JTR(K,2)).NE.KOD) CYCLE LINELOOP
                 NLT=NLT+1
                 FRL=CAS/WAVE(K)
                 IJL=NINT((XFRMA-LOG(FRL))/DXNU)+NFRS1
                 D0=ABS((FREQ(IJL)-FRL)/(FREQ(IJL)-FREQ(IJL+1)))
c        if(ion.eq.35) write(*,*) '   k,nlt,ijl,fr',k,nlt,ijl,frl
                 IF(D0.GT.HALF) THEN
                    DO WHILE(FRL.GT.FREQ(IJL))
                       IJL=IJL-1
                    END DO
                    DO WHILE(FRL.LT.FREQ(IJL))
                       IJL=IJL+1
                    END DO
                    D1=FRL-FREQ(IJL)
                    D2=FREQ(IJL-1)-FRL
                    IF(D2.LT.D1) IJL=IJL-1
                 END IF
                 IJ0=IJL-IJD
                 IJ1=IJL+IJD
                 IF(IJ0.LT.1) IJ0=1
                 IF(IJ1.GT.NFREQ) IJ1=NFREQ
                 IF(IFRKU.EQ.0) IFRKU=IJ0
                 NFT=IJ1-IFRKU+1
c         if(ion.eq.35) write(*,*) ' nft',ijl,ijd,ij0,ij1,ifrku,nft
                 DO IJ=IJ0,IJ1
                    DNU=FREQ(IJ)-FRL
                    DO I=1,JIDN
                       VV=DNU*DBLE(VDOP(K,I))
c                      PRFK=real(VOIGTE(VV,AGAF(K,I)))/real(GSUPER)
c                      SIGT(I,IJ)=SIGT(I,IJ)+SIG0(K,I)*PRFK
                       CALL VOIGTF(VV,DBLE(AGAF(K,I)),VOIGTE)
                       PRFK=VOIGTE/GSUPER
c                      PRFK=VOIGTE(VV,DBLE(AGAF(K,I)))/GSUPER
                       SIGT(I,IJ)=SIGT(I,IJ)+SIG0(K,I)*real(PRFK)
      if(i.eq.1.and.ion.eq.35) write(42,"(3i5,2i8,1p7e11.3)")
     * ion,il,iu,k,ij,dnu,vdop(k,i),vv,agaf(k,i),voigte,gsuper,
     * sigt(i,ij)
                    END DO
                 END DO
                 FCOL=FCOL+SIG0(K,JIDC)/VDOP(K,JIDC)
              END DO LINELOOP

              OSC0(ITR)=0.
              IF(INDXPA.EQ.3 .OR. INDXPA.EQ.4) OSC0(ITR)=STRLX
              IF(FCOL.GT.0.) OSC0(ITR)=FCOL/GSUPER/CSIG
              IF(NLT.GT.0) THEN
                 W1=CAS/FREQ(IFRKU)
                 W2=CAS/FREQ(IFRKU+NFT-1)
              END IF
              IF(NFT.GT.0) THEN
                 IFR0(ITR)=IFRKU
                 IFR1(ITR)=IFRKU+NFT-1
                 KFR0(ITR)=NFTT+1
                 KFR1(ITR)=NFTT+NFT
                 NFTT=NFTT+NFT
                 itrl=itr
                 DO IJ=IFR0(ITR),IFR1(ITR)
                    KJ=IJ-IFR0(ITR)+KFR0(ITR)
                    DO I=1,JIDN
c                      sxx=log(dble(sigt(i,ij))+1.d-40)
c                      SIGFE(I,KJ)=real(sxx)
                       sxx=log(sigt(i,ij)+1.e-40)
                       SIGFE(I,KJ)=real(sxx)
      if(i.eq.1.and.ion.eq.33) write(42,"(3i5,2i8,1p3e11.3)")
     * ion,il,iu,ij,kj,sigt(i,ij),sxx,sigfe(i,kj)
                    END DO
                 END DO
              END IF
c        write(*,"('lin',2i5,i6,2i7,i8,3i9)")
c    * il,iu,itr,ifr0(itr),ifr1(itr),nftt,kj,kfr0(itr),kfr1(itr)
c             IF(KJ.GT.MCFE)
c    &           CALL QUIT(' Too many Fe cross-sect. to store',
c    &                     KJ,MCFE)
              WRITE(41,"(2I4,2F12.3,3I10,1PE12.3)") 
     *        IL,IU,W1,W2,IFRKU,NFT,NLT,OSC0(ITR)
              IF(NFT.GT.NFTMX) NFTMX=NFT
           END DO
c     write(*,*) 'end loop for ion',ion,typion(ion)
        END DO
!     write(*,*) 'end loop for ion in iroset',ion,typion(ion)
      END DO IONLOOP
c 500 CONTINUE
      WRITE(10,*) ' Max. number of freq. per transition:',NFTMX
      WRITE(10,*) ' Number of iron line cross-sections: ',NFTT
      close(41)
C
      DEALLOCATE (SIGT,DMLL) 
      DEALLOCATE (SIG0,WAVE,AGAF,VDOP)
      DEALLOCATE (JTR)
      CALL IJALI2
      RETURN
      END




!*************************************************************************


      SUBROUTINE IROST0
C     =================
C

      use accura
      use atomic
      use basics
      use modelq
      use odfpar

      implicit none 

      REAL(DP) :: XFRMA,W1,W2,FRL,D0,D1,D2
      INTEGER  :: IJD,NFTMX,ION,IND,IOBS,N1,NLII,IL,KEVL,KODL,ILOK,ITR
      INTEGER  :: IU,IUPK,INDXPA,IFRKU,NFT,NLT,KEVU,KODU,KEV,KOD,IEO
      INTEGER  :: IJL,IJ0,IJ1,K,KJ
c 
c     loop over ions with line-blanketing data
c
      XFRMA=LOG(FRS1)
      IJD=INT(9./DDNU)
      IF(IJD.LT.2) IJD=2
      NFTT=0
      NFTMX=0
      
      IONLOOP: DO ION=1,NION
         IND=INODF1(ION)
         IF(IND.LE.0) CYCLE IONLOOP
         IF(NLLIM(ION).GE.NLEVS(ION)) THEN
            CYCLE IONLOOP
         END IF
C
C       Set up superlevels and read line data
C
        IOBS=IKOBS(ION)
        CALL LEVCD(ION,IOBS)
        CALL INKUL(ION,IOBS)
c
        write(6,"(/' *** superlines for ',i4,': ',a4,
     *  '   selected internal lines:',i10)") ion,typion(ion),nlinku
        if(nlinku.gt.mline)
     *     call quit('too many internal lines',nlinku,mline)
C
C       Assign line to supertransition and compute cross-section
C
        N1=NFIRST(ION)
        NLII=NLAST(ION)-N1+1
        DO IL=1,NLII-1
           KEVL=0
           KODL=0
           IF(JEN(IL).LE.NEVKU(ION)) THEN
              KEVL=JEN(IL)
            ELSE
              KODL=JEN(IL)-NEVKU(ION)
           END IF
           ILOK=N1+IL-1
           DO IU=IL+1,NLII
              IUPK=N1+IU-1
              ITR=ITRA(ILOK,IUPK)
              INDXPA=ABS(INDEXP(ITR))
              W1=0.
              W2=0.
              IFRKU=0
              NFT=0
              NLT=0
              KEVU=0
              KODU=0
              IF(JEN(IU).LE.NEVKU(ION)) THEN
                 KEVU=JEN(IU)
               ELSE
                 KODU=JEN(IU)-NEVKU(ION)
              END IF
              IF(KEVL.NE.0) THEN
                 KEV=KEVL
                 KOD=KODU
                 IEO=0
               ELSE
                 KEV=KEVU
                 KOD=KODL
                 IEO=1
              END IF

              LINELOOP: DO K=1,NLINKU
                 IF(KSEV(JTR(K,1)).NE.KEV) CYCLE LINELOOP
                 IF(KSOD(JTR(K,2)).NE.KOD) CYCLE LINELOOP
                 NLT=NLT+1
                 FRL=CAS/WAVE(K)
                 IJL=NINT((XFRMA-LOG(FRL))/DXNU)+NFRS1
                 D0=ABS((FREQ(IJL)-FRL)/(FREQ(IJL)-FREQ(IJL+1)))
c             write(*,*) '   k,fr',k,nlt,ijl,frl
                 IF(D0.GT.HALF) THEN
                    DO WHILE(FRL.GT.FREQ(IJL))
                       IJL=IJL-1
                    END DO
                    DO WHILE(FRL.LT.FREQ(IJL))
                       IJL=IJL+1
                    END DO
                    D1=FRL-FREQ(IJL)
                    D2=FREQ(IJL-1)-FRL
                    IF(D2.LT.D1) IJL=IJL-1
                 END IF
                 IJ0=IJL-IJD
                 IJ1=IJL+IJD
                 IF(IJ0.LT.1) IJ0=1
                 IF(IJ1.GT.NFREQ) IJ1=NFREQ
                 IF(IFRKU.EQ.0) IFRKU=IJ0
                 NFT=IJ1-IFRKU+1
c         write(*,*) ' nft',ijl,ijd,ij0,ij1
              END DO LINELOOP

              IF(NFT.GT.0) THEN
                 IFR0(ITR)=IFRKU
                 IFR1(ITR)=IFRKU+NFT-1
                 KFR0(ITR)=NFTT+1
                 KFR1(ITR)=NFTT+NFT
                 NFTT=NFTT+NFT
                 KJ=IFR1(ITR)-IFR0(ITR)+KFR0(ITR)
              END IF
c      write(*,"('lin',2i5,i6,2i7,i8,3i9)")
c    * il,iu,itr,ifr0(itr),ifr1(itr),nftt,kj,kfr0(itr),kfr1(itr)
c             WRITE(41,"(2I4,2F12.3,3I10,1PE12.3)")
c    *        IL,IU,W1,W2,IFRKU,NFT,NLT,OSC0(ITR)
              IF(NFT.GT.NFTMX) NFTMX=NFT
           END DO
c     write(*,*) 'end loop for ion in irost0',ion,typion(ion)
        END DO
!     write(*,*) 'end loop for ion in irost0',ion,typion(ion)
      END DO IONLOOP

      write(*,*) 
      write(*,*) 'MCFE=',KJ+NFT
      write(*,*) 
 
      MCFE=KJ+NFT
      ALLOCATE (SIGFE(MDODF,MCFE))

      RETURN
      END SUBROUTINE IROST0
 

!*************************************************************************


      SUBROUTINE LEVCD(ION,IOBS)
C     ==========================
C
C     Mean energy and statistical weights of superlevels.
C     Read atomic data from Kurucz CD-ROM file (gf*.gam)
C
C     Setup collisional strengths between superlevels, using
C      Eissner-Seaton formula for each possible individual
C      transition. Assumes Gamma(T)=0.05, and T=Teff
C      Contributions from allowed transitions will be superseded
C      in routine INKUL.
C
      use accura
      use atomic
      use basics
      use modelq
      use odfpar

      implicit none

      INTEGER, INTENT(IN) :: ION
      INTEGER             :: IOBS

      REAL(DP), PARAMETER :: BOLCM=1.D8/HK/CAS,CCOR=0.09,SIXTH=UN/6.,
     *                       GES=0.05

      REAL(DP), ALLOCATABLE :: GWE(:,:,:),GWB(:,:,:),AA(:)
      REAL(DP)              :: E0FE(10),E0NI(10),E0CR(10)

      REAL(DP) :: ZZ,E0,YJ,E,AR,SR,WR,GEV,EBCM,GWX,XN,GOD,WID
      REAL(DP) :: TK0,U0,ESUP,WSUP,WN
      INTEGER  :: I,J,ID,NEVOD,IWSUP,IAT,K,KSL,IUN1,KI,KJ,II,JJ,JK

      DATA E0FE/63480.,130563.,247220.,442000.,605000.,799000.,
     &            1008000.,1218380.,1884000.,2114000./
      DATA E0NI/61590.,146560.,283700.,443000.,613500.,871000.,
     &            1070000.,1310000.,1560000.,1812000./
      DATA E0CR/54576.,132966.,249700.,396500.,560200.,731020.,
     &            1291900.,1490000.,1688000.,1971000./
!
!     allocate temporeary arrays
!
      ALLOCATE (GWE(MDEPTH,MLEVEL,2),GWB(MDEPTH,MLEVEL,2),AA(MDEPTH))

      IF(IOBS.NE.1 .AND. IOBS.NE.2) IOBS=0
      DO I=1,NEVKU(ION)
         YMKU(I,1)=0.
         EMKU(I,1)=0.
         DO ID=1,ND
            GWE(ID,I,1)=0.
            GWB(ID,I,1)=0.
         END DO
      END DO
      DO I=1,NODKU(ION)
         YMKU(I,2)=0.
         EMKU(I,2)=0.
         DO ID=1,ND
            GWE(ID,I,2)=0.
            GWB(ID,I,2)=0.
         END DO
      END DO
      NEVOD=NEVKU(ION)+NODKU(ION)
      IF(NEVOD.GT.100)
     &   CALL QUIT(' Too many superlevels in a single Fe ion',
     &             NEVKU(ION),NODKU(ION))
      DO I=1,NEVOD
         DO J=1,NEVOD
            OMES(I,J)=0.
         END DO
      END DO
      IWSUP=IFWOP(NFIRST(ION))
      E0=E0FE(IZ(ION))
      IF(IWSUP.GE.2) THEN
         DO ID=1,ND
            TEMP1(ID)=UN/TEMP(ID)
            AA(ID)=CCOR*EXP(SIXTH*LOG(ELEC(ID)))/SQRT(TEMP(ID))
         END DO
         ZZ=IZ(ION)
         IF(IZ(ION).GT.10)
     *   CALL QUIT(' Too high Fe, Ni or Cr ion: ion,iz',ion,iz(ion))
         IAT=IATM(NFIRST(ION))
         E0=E0FE(IZ(ION))
         IF(NUMAT(IAT).EQ.28) E0=E0NI(IZ(ION))
         IF(NUMAT(IAT).EQ.24) E0=E0CR(IZ(ION))
      END IF
C
C     CD-ROM format: Read energy levels
C
c      write(*,*) fiodf1(ion),e0
      IUN1=31
      OPEN(IUN1,FILE=FIODF1(ION),STATUS='OLD')
      READ(IUN1,"(I7,13X,I6,12X,I6)") NLINKU,KEVE,KODD
      IF(KEVE+KODD.GT.15000)
     &   CALL QUIT(' Too many levels in Kurucz file',keve,kodd)

c     write(6,"('iat,ion,nlinku,keve,kodd',2i4,3i10)")
c    *       iat,ion,nlinku,keve,kodd
C
C     Even parity
C
      EVELOOP: DO K=1,KEVE
         KSL=0
         READ(IUN1,"(8X,F4.1,4X,F13.3,18X,3E9.2)") YJ,E,AR,SR,WR
         GEV=(TWO*YJ+UN)
         AEV(K)=AR
         SEV(K)=SR
         WEV(K)=WR
         KSEV(K)=KSL
         IF(E.LT.0.) THEN
            E=-E
            IF(IOBS.EQ.0) THEN
               EEV(K)=E
               CYCLE EVELOOP
            END IF
         END IF
         IF(E.LE.XEV(1,ION)) KSL=1
         DO I=2,NEVKU(ION)
            IF(E.LE.XEV(I,ION) .AND. E.GT.XEV(I-1,ION)) KSL=I
         END DO
         IF(KSL.EQ.0) WRITE(10,*) ' Error with even levels',E,YJ
         KKU(K)=KSL
         GKU(K)=GEV
         EKU(K)=E
         YMKU(KSL,1)=YMKU(KSL,1)+GEV
         EMKU(KSL,1)=EMKU(KSL,1)+GEV*E
c     write(*,"('keve',2i5,1p3e10.2)") k,ksl,e,ymku(ksl,1),emku(ksl,1)
         IF(IWSUP.EQ.2) THEN
            EBCM=E/BOLCM
            DO ID=1,ND
               GWX=GEV*EXP(-EBCM*TEMP1(ID))
               GWB(ID,KSL,1)=GWB(ID,KSL,1)+GWX
               GWE(ID,KSL,1)=GWE(ID,KSL,1)+GWX*E
            END DO
          ELSE IF(IWSUP.EQ.3) THEN
            EBCM=E/BOLCM
            IF(E.LT.E0) THEN
               XN=SQRT(E0/(E0-E))
               DO ID=1,ND
                  WID=WN(XN,AA(ID),ELEC(ID),ZZ)
                  GWX=GEV*WID*EXP(-EBCM*TEMP1(ID))
                  GWB(ID,KSL,1)=GWB(ID,KSL,1)+GWX
                  GWE(ID,KSL,1)=GWE(ID,KSL,1)+GWX*E
               END DO
             ELSE
               DO ID=1,ND
                  WID=UN
                  GWX=GEV*WID*EXP(-EBCM*TEMP1(ID))
                  GWB(ID,KSL,1)=GWB(ID,KSL,1)+GWX
                  GWE(ID,KSL,1)=GWE(ID,KSL,1)+GWX*E
               END DO
            END IF
         END IF
         EEV(K)=E
         KSEV(K)=KSL
      END DO EVELOOP

      DO I=1,NEVKU(ION)
        IF(YMKU(I,1).EQ.0.)
     *     call quit(' No levels in even superlevel',i,i)
        EMKU(I,1)=EMKU(I,1)/YMKU(I,1)
      END DO
C
C     Odd parity
C
      ODDLOOP: DO K=1,KODD
         KSL=0
         READ(IUN1,"(8X,F4.1,4X,F13.3,18X,3E9.2)") YJ,E,AR,SR,WR
         GOD=(TWO*YJ+UN)
         AOD(K)=AR
         SOD(K)=SR
         WOD(K)=WR
         KSOD(K)=KSL
         IF(E.LT.0.) THEN
            E=-E
            IF(IOBS.EQ.0) THEN
               EOD(K)=E
               CYCLE ODDLOOP
            END IF
         END IF
         IF(E.LE.XOD(1,ION)) KSL=1
         DO I=2,NODKU(ION)
            IF(E.LE.XOD(I,ION) .AND. E.GT.XOD(I-1,ION)) KSL=I
         END DO
         IF(KSL.EQ.0) WRITE(10,*) ' Error with odd levels',E,YJ
         KKU(K+KEVE)=KSL+NEVKU(ION)
         GKU(K+KEVE)=GOD
         EKU(K+KEVE)=E
         YMKU(KSL,2)=YMKU(KSL,2)+GOD
         EMKU(KSL,2)=EMKU(KSL,2)+GOD*E
         IF(IWSUP.EQ.2) THEN
            EBCM=E/BOLCM
            DO ID=1,ND
               GWX=GOD*EXP(-EBCM*TEMP1(ID))
               GWB(ID,KSL,2)=GWB(ID,KSL,2)+GWX
               GWE(ID,KSL,2)=GWE(ID,KSL,2)+GWX*E
            END DO
          ELSE IF(IWSUP.EQ.3) THEN
            EBCM=E/BOLCM
            IF(E.LT.E0) THEN
               XN=SQRT(E0/(E0-E))
               DO ID=1,ND
                  WID=WN(XN,AA(ID),ELEC(ID),ZZ)
                  GWX=GOD*WID*EXP(-EBCM*TEMP1(ID))
                  GWB(ID,KSL,2)=GWB(ID,KSL,2)+GWX
                  GWE(ID,KSL,2)=GWE(ID,KSL,2)+GWX*E
               END DO
             ELSE
               DO ID=1,ND
                  WID=UN
                  GWX=GOD*WID*EXP(-EBCM*TEMP1(ID))
                  GWB(ID,KSL,2)=GWB(ID,KSL,2)+GWX
                  GWE(ID,KSL,2)=GWE(ID,KSL,2)+GWX*E
               END DO
            END IF
         END IF
         EOD(K)=E
         KSOD(K)=KSL
      END DO ODDLOOP
      DO I=1,NODKU(ION)
         IF(YMKU(I,2).EQ.0.)
     *   call quit(' No levels in odd superlevel',I,I)
         EMKU(I,2)=EMKU(I,2)/YMKU(I,2)
      END DO
      CLOSE(IUN1)
c     write(6,"('iat,ion,nlinku,keve,kodd',2i4,3i10)")
c    *       iat,ion,nlinku,keve,kodd
C
C     Collisional strengths of transitions between super-levels
C      Eissner-Seaton formula (Gamma=0.05)
C
      GST=8.63E-6*GES/SQRT(TEFF)
      TK0=UN/BOLCM/TEFF
      DO I=1,KEVE+KODD-1
         KI=KKU(I)
         DO J=I+1,KEVE+KODD
            KJ=KKU(J)
            U0=ABS(EKU(I)-EKU(J))*TK0
            OMES(KI,KJ)=OMES(KI,KJ)+GST*EXP(-U0)
            OMES(KJ,KI)=OMES(KI,KJ)
         END DO
      END DO
C
C     Sort superlevel energies
C
      NLEVKU=NEVKU(ION)+NODKU(ION)
      DO I=1,NEVKU(ION)
         EU(I)=EMKU(I,1)
      END DO
      DO I=1,NODKU(ION)
         EU(I+NEVKU(ION))=EMKU(I,2)
      END DO
      CALL INDEXX(NLEVKU,EU,JEN)
c      write(*,*) 'eu',eu
c      write(*,*) 'jen',jen
C
C     Superlevel generalized occupation probabilities
C
c      write(*,*) 'iwsup',iwsup
      IF(IWSUP.GE.2) THEN
         DO I=1,NLEVKU
            II=NFIRST(ION)+I-1
            JJ=JEN(I)
            JK=1
            IF(JJ.GT.NEVKU(ION)) THEN
               JJ=JEN(I)-NEVKU(ION)
               JK=2
            END IF
            DO ID=1,ND
               ESUP=GWE(ID,JJ,JK)/GWB(ID,JJ,JK)
               WSUP=EXP(ESUP/BOLCM*TEMP1(ID))/YMKU(JJ,JK)
               WOP(II,ID)=WSUP*GWB(ID,JJ,JK)
            END DO
c         write(*,*) 'wop',ii,jj,wop(ii,nd)
         END DO
      END IF
c      write(*,*) 'end levcd'
C
      DEALLOCATE (GWE,GWB,AA)
      RETURN
      END SUBROUTINE LEVCD


!*************************************************************************



      SUBROUTINE INKUL(ION,IOBS)
C     ==========================
C
C     Read line list from Kurucz CD-ROM files  (gf*.lin)
C
C     INPUT:  Unit 18
C               WMIN : Min. wavelength (lines at smaller wave are NOT selected)
C               WMAX : Max. wavelength (lines at larger wave are NOT selected)
C               IOBS : Type of selected lines
C
C     OUTPUT:  fill up common/lined/
C     *******
C           -  WAVE     : wavelength in ANGSTROMS
C           -  SIG0     : 0.02654/sqrt(pi)*gf/VDOP (divided by g(super) later)
C           -  VDOP     : Doppler width
C           -  AGAF     : Damping parameter
C
      use accura
      use atomic
      use basics
      use modelq
      use odfpar

      implicit none
      INTEGER, INTENT(IN) :: ION,IOBS

      REAL(DP), PARAMETER :: TEN=10.,TENLG=2.302585093,GES=0.05
      REAL(DP), PARAMETER :: BOL2=2.76108e-16,BOLCM=1.e8/HK/CAS
      REAL(DP), PARAMETER :: CSTK=3.54,PSTK=2./3.,TSTK=UN/6.
      REAL(DP), PARAMETER :: CVDW=3.74,PVDW=0.4,TVDW=0.3
      REAL(DP), PARAMETER :: PI4V=0.25/3.141592654,CSIG=0.0149736
      REAL(DP), PARAMETER :: EXPIA1=-0.57721566,EXPIA2=0.99999193,
     *           EXPIA3=-0.24991055,EXPIA4=0.05519968,
     *           EXPIA5=-0.00976004,EXPIA6=0.00107857,
     *           EXPIB1=0.2677734343,EXPIB2=8.6347608925,
     *           EXPIB3=18.059016973,EXPIB4=8.5733287401,
     *           EXPIC1=3.9584969228,EXPIC2=21.0996530827,
     *           EXPIC3=25.6329561486,EXPIC4=9.5733223454
      REAL(DP) :: E0FE(10),E0NI(10),E0CR(10)
      REAL(DP) :: VT0(MDEPTH),GT0(MDEPTH)

      REAL(DP) :: E0,CDOP,TK35,CVR,TK357,XION,XIONI,XIATI,XIONK
      REAL(DP) :: WMIN,WMAX,WA,GFR,GF,E00,XLSTR,GR,C4,C4P,SMX,GSLOG0
      REAL(DP) :: GS,U0,EXPIU0,GB,C2,GSUP
      INTEGER  :: IAT,K,I,IUN2,III,IOS,JEVR,JODR,IFPLI,ID,KA,KB,K2
      INTEGER  :: K1,II,I1,J,JJ,J1,IT

      DATA E0FE/63480.,130563.,247220.,442000.,605000.,799000.,
     *            1008000.,1218380.,1884000.,2114000./
      DATA E0NI/61590.,146560.,283700.,443000.,613500.,871000.,
     *            1070000.,1310000.,1560000.,1812000./
      DATA E0CR/54576.,132966.,249700.,396500.,560200.,731020.,
     *            1291900.,1490000.,1688000.,1971000./
C
      IAT=IATM(NFIRST(ION))
      E0=E0FE(IZ(ION))
      IF(NUMAT(IAT).EQ.28) E0=E0NI(IZ(ION))
      IF(NUMAT(IAT).EQ.24) E0=E0CR(IZ(ION))
      CDOP=BOL2/AMASS(IAT)
      TK35=UN/BOLCM/TEMP(JIDR(2))
      CVR=19.7363/TEMP(JIDR(2))/SQRT(TEMP(JIDR(2)))
      if(jidn.gt.3) then
         TK35=UN/BOLCM/TEFF
         CVR=19.7363/TEFF/SQRT(TEFF)
      end if
      TK357=TK35*1.E7

      XION=0.
      DO K=1,JIDN
         XIONI=0.
         XIATI=0.
         ID=JIDR(K)
         DO I=NFIRST(ION),NLAST(ION)
            XIONI=XIONI+POPUL(I,ID)
c         if(k.eq.2) write(*,*) 'xioni',id,i,xioni,popul(i,id)
         END DO
         DO I=N0A(IAT),NKA(IAT)
             XIATI=XIATI+POPUL(I,ID)
         END DO
         XIONK=XIONI/XIATI
         IF(XIONK.GT.XION) XION=XIONK
         VT0(ID)=1.E-8/SQRT(CDOP*TEMP(ID)+VTURBS(ID)*VTURBS(ID))
         GT0(ID)=TSTK*LOG10(TEMP(ID))
      END DO
      NLINKU=0
      WMIN=CAS/FRS1/TEN
      WMAX=CAS/FRS2/TEN
      IUN2=32

       iii=0

      OPEN(IUN2,FILE=FIODF2(ION),STATUS='OLD')
      READDO: DO
         READ(IUN2,"(F11.4,F7.3,2I4,I1)",IOSTAT=IOS) WA,GFR,
     *      JEVR,JODR,IFPLI
         IF(IOS.NE.0) EXIT READDO
c       write(*,*) 'kur',wa,gfr,jevr,jodr,ifpli
c         write(*,"('linek',4i9,f10.2,1p3e10.2)")
c    *    nlinku,jevr,jodr,ifpli,wa,gfr,xlstr,strlx
         GF=EXP(TENLG*GFR)
         IF(WA.GE.WMIN.AND.WA.LE.WMAX) THEN
            IF(IOBS.EQ.0 .AND. IFPLI.EQ.1) CYCLE READDO
            IF(IOBS.EQ.2 .AND. EOD(JODR).GT.E0) CYCLE READDO
            IF(IOBS.EQ.2 .AND. EEV(JEVR).GT.E0) CYCLE READDO
            E00=EEV(JEVR)
            IF(EOD(JODR).LT.EEV(JEVR)) E00=EOD(JODR)
            XLSTR=XION*GF*EXP(-E00*TK35)
          iii=iii+1
c         write(*,*) 'xlstr',xlstr,xion,gf,e00,tk35
            if(jidn.gt.3) XLSTR=XION*GF*EXP(-E00*8./E0)
c         if(iii.gt.20) exit readdo

            IF(XLSTR.LT.STRLX) CYCLE READDO
            NLINKU=NLINKU+1
c         write(*,"('lines',4i9,f10.2,1p3e10.2)") 
c    *    nlinku,jevr,jodr,ifpli,wa,gfr,xlstr,strlx
            WAVE(NLINKU)=real(WA*TEN)
            JTR(NLINKU,1)=JEVR
            JTR(NLINKU,2)=JODR
            GR=AEV(JEVR)+AOD(JODR)
            C4=SEV(JEVR)
            C4P=SOD(JODR)
            SMX=DMAX1(ABS(C4P-C4),DMIN1(ABS(C4),ABS(C4P)))
            GSLOG0=CSTK+PSTK*LOG10(SMX)
            DO I=1,JIDN
               ID=JIDR(I)
               VDOP(NLINKU,I)=real(WAVE(NLINKU)*VT0(ID))
               GS=EXP(TENLG*(GSLOG0+GT0(ID)))
               AGAF(NLINKU,I)=real((GR+GS*ELEC(ID))*PI4V*VDOP(NLINKU,I))
               SIG0(NLINKU,I)=real(CSIG*GF*VDOP(NLINKU,I))
            END DO
         END IF
         KA=KKU(JEVR)
         KB=KKU(JODR+KEVE)
         IF(KA.LE.KB) THEN
            K1=KA
            K2=KB
          ELSE
            K1=KB
            K2=KA
         END IF
         IF(K1.EQ.K2) CYCLE READDO
         U0=TK357/WA
         IF(U0.LE.UN) THEN
            EXPIU0=-LOG(U0)+EXPIA1+U0*(EXPIA2+U0*(EXPIA3+U0*(EXPIA4+
     *              U0*(EXPIA5+U0*EXPIA6))))
          ELSE
            EXPIU0=EXP(-U0)*((EXPIB1+U0*(EXPIB2+U0*(EXPIB3+
     *          U0*(EXPIB4+U0))))/(EXPIC1+U0*(EXPIC2+
     *          U0*(EXPIC3+U0*(EXPIC4+U0)))))/U0
         END IF
         GB=0.276*EXP(U0)*EXPIU0
         IF(GB.LT.0.25) GB=0.25
         OMES(K1,K2)=OMES(K1,K2)+(CVR/U0*GF*GB-GST)*EXP(-U0)
c        END IF
      END DO READDO
c
      CLOSE(IUN2)
!     WRITE(6,"(' Ion',2I3,' : ',I9,' Lines included')") 
!    *      NUMAT(IAT),IZ(ION),NLINKU
      WRITE(10,"(' Ion',2I3,' : ',I9,' Lines included')") 
     *      NUMAT(IAT),IZ(ION),NLINKU
C
C     Store collisional excitation strengths
C
      NLEVKU=NEVKU(ION)+NODKU(ION)
      DO I=1,NLEVKU-1
         II=NFIRST(ION)+I-1
         I1=JEN(I)
         IF(I1.LE.NEVKU(ION)) THEN
            GSUP=YMKU(I1,1)
          ELSE
            GSUP=YMKU(I1-NEVKU(ION),2)
         END IF
         DO J=I+1,NLEVKU
            JJ=NFIRST(ION)+J-1
            J1=JEN(J)
            IT=ITRA(II,JJ)
            C2=CPAR(IT)
            OMECOL(II,JJ)=OMES(I1,J1)/GSUP*C2/GES
            OMECOL(JJ,II)=OMECOL(II,JJ)
         END DO
      END DO
c
      RETURN
      END SUBROUTINE INKUL


!*************************************************************************


      SUBROUTINE IJALI2
C     =================
C
C     auxiliary routine - sets up the necessary flags for ALI treatment
C     of individual transitions (in the fully hybrid CL/ALI scheme)
C
C     Version for opacity sampling mode
C
C     Output:
C
C     IJALI(IJ) = 0 - frequency point IJ is an explicit point
C               = 1 - frequency point IJ is an ALI point
C
C     LEXP(ITR) = T - at least one point within transition ITR is explicit
C     LEXP(ITR) = F - no point within transition ITR is explicit
C     LALI(ITR) = T - at least one point within transition ITR is ALI
C     LALI(ITR) = F - no point within transition ITR is ALI
C
      use accura
      use atomic
      use basics
      use modelq
      use odfpar

C
      implicit none

      REAL(DP) :: XFRMA
      INTEGER  :: IT,IJ,NLITOT,NLIMAX,ITR,INDXP,I0,I1,NF,IJL,NFC
    
c     DO IJ=1,NFREQ
c        IJALI(IJ)=1
c        IJX(IJ)=1
c        NLINES(IJ)=0
c     END DO
      IJALI=1
      IJX=1
      NLINES=0
      NLITOT=0
      NLIMAX=0
C
C     Overlapping lines at frequency IJ
C
      DO IT=1,NTRANS
         IF(LINEXP(IT)) CYCLE
         DO IJ=IFR0(IT),IFR1(IT)
            NLINES(IJ)=NLINES(IJ)+1
c           ITRLIN(NLINES(IJ),IJ)=IT
         END DO
      END DO
      DO IJ=1,NFREQ
         NLITOT=NLITOT+NLINES(IJ)
c        IF(NLINES(IJ).GT.MITJ)
c    *   CALL QUIT('Too many overlappins-nlines(ij).gt.mitj',
c    *   nlines(ij),mitj)
         IF(NLINES(IJ).GT.NLIMAX) NLIMAX=NLINES(IJ)
      END DO
      WRITE(10,*) ' Max. number of line overlaps:       ',NLIMAX
      WRITE(10,*) ' Total number of line overlaps:      ',NLITOT
      WRITE(*,*) ' Max. number of line overlaps:       ',NLIMAX
      WRITE(*,*) ' Total number of line overlaps:      ',NLITOT
C 
      MITJ=NLIMAX
      ALLOCATE (ITRLIN(MITJ,MFREQ))
       write(*,*) 'MITJ',mitj

      NLINES=0
      DO IT=1,NTRANS
         IF(LINEXP(IT)) CYCLE
c        write(*,"('ijali2 it',3i7)") it,ifr0(it),ifr1(it)
         DO IJ=IFR0(IT),IFR1(IT)
            NLINES(IJ)=NLINES(IJ)+1
            ITRLIN(NLINES(IJ),IJ)=IT
         END DO
      END DO
c     do ij=1,5000
c        write(*,"(i6,f10.3,i5,10i6)") ij,2.997925e18/freq(ij),
c    *   nlines(ij),
c    *   (itrlin(it,ij),it=1,min(nlines(ij),10))
c     end do
C
C     Switches for ALI and explicit transitions
C
      IF(NFFIX.EQ.2) THEN
         DO ITR=1,NTRANS
            LEXP(ITR)=.FALSE.
            LALI(ITR)=.TRUE.
         END DO
         RETURN
      END IF
C
      XFRMA=LOG10(FRS1)
      DO ITR=1,NTRANS
         INDXP=INDEXP(ITR)
         I0=IFR0(ITR)
         I1=IFR1(ITR)
         NF=I1-I0+1
c       write(*,"('trans-ijali2',7i7,1p3e15.7)") 
c    *   itr,indxp,ilow(itr),iup(itr),i0,i1,nf,
c    *   fr0(itr),freq(i0),freq(i1)
         IF(FR0(ITR).GT.FRS1) CYCLE
         IJL=IJTC(ITR)
C
C        primarily explicit line transitions
C
         IF(LINE(ITR)) THEN
            IF(INDXP.GT.0) THEN
               LEXP(ITR)=.TRUE.
               LALI(ITR)=.FALSE.
               IF(IFC0(ITR).EQ.0) THEN
                  DO IJ=I0,I1
                     IJALI(IJ)=0
                  END DO
                ELSE
                   LALI(ITR)=.TRUE.
                   NFC=IABS(IFC1(ITR)-IFC0(ITR)+1)
                   IF(NFC.EQ.NF) THEN
                      LEXP(ITR)=.FALSE.
                    ELSE
                      NFC=NFC/2
                      DO IJ=I0,IJL-NFC
                         IJALI(IJ)=0
                      END DO
                      DO IJ=IJL+NFC,I1
                         IJALI(IJ)=0
                      END DO
                   END IF
               END IF
             ELSE IF(INDXP.LT.0) THEN
C
C            primarily ALI line transitions
C
               LEXP(ITR)=.FALSE.
               LALI(ITR)=.TRUE.
               IF(IFC0(ITR).NE.0) THEN
                  LEXP(ITR)=.TRUE.
                  NFC=IABS(IFC1(ITR)-IFC0(ITR)+1)
                  IF(NFC.EQ.NF) THEN
                     LALI(ITR)=.FALSE.
                     DO IJ=I0,I1
                        IJALI(IJ)=0
                     END DO
                   ELSE
                     NFC=NFC/2
                     DO IJ=IJL-NFC,IJL+NFC
                        IJALI(IJ)=0
                     END DO
                 END IF
               END IF
            END IF
C
C         continuum transitions
C
          ELSE
            IF(IFC0(ITR).GT.0) THEN
               DO IJ=1,IFC1(ITR)-IFC0(ITR)+1
                  IJALI(IJL-IJ+1)=0
               END DO
            END IF
         END IF
      END DO
C
      RETURN
      END SUBROUTINE IJALI2


!*************************************************************************



      subroutine voigtf(vs,a,voigte)
c     ==============================
c
c  computes a voigt function  h = h(a,v)
c  a=gamma/(4*pi*dnud)   and  v=(nu-nu0)/dnud.  this  is  done after
c  Traving (Landolt-Bernstein, p. 449).
c     
      use accura
      implicit none

      real(dp),intent(in) ::  vs,a
      real(dp),intent(out):: voigte
      REAL(DP), PARAMETER :: UN=1., TWO=2.
      REAL(DP)            :: ak(19),a1(5)
      data ak      /-1.12470432, -0.15516677,  3.28867591, -2.34357915,
     *  0.42139162, -4.48480194,  9.39456063, -6.61487486,  1.98919585,
     * -0.22041650, 0.554153432, 0.278711796,-0.188325687, 0.042991293,
     *-0.003278278, 0.979895023,-0.962846325, 0.532770573,-0.122727278/

      real(DP), parameter :: sqp=1.772453851, sq2=1.414213562

      real(DP)    :: v,v2,ex,quo,h1,h,h1p,h2p,h3p,h4p,pqs,psi
      real(dp)    :: u,u2,a2
      integer :: k,m,i
c
      v = abs(vs)
      u = a + v
      v2 = v*v
      ex=0.
      if(v2.lt.100.) ex = exp(-v2)
      k = 1

      if(a.eq.0.0) then
         h=0.
         if(v2.lt.100.) voigte=exp(-v2)
         return
       else if(a.gt.0.2) then
         if(a.gt.1.4.or.u.gt.3.2) then
            a2 = a*a
            u = sq2*(a2 + v2)
            u2 = un/(u*u)
            voigte = sq2/sqp*a/u*(1. + u2*(3.*v2 - a2) +
     *               u2*u2*(15.*v2*v2 - 30.*v2*a2 + 3.*a2*a2))
            return
          else
            ex=0.
            if(v2.lt.100.)ex = exp(-v2)
            k = 2
         end if
       else if(v.ge.5) then
         voigte=a*(15. + 6.*v2 + 4.*v2*v2)/(4.*v2*v2*v2*sqp)
         return
      end if

      quo=un
      if(v.lt.2.4) then
         m = 6
         if (v.lt.1.3) m = 1
       else
         quo=un/(v2-1.5)
         m=11
      end if
      do i=1,5
         a1(i) = ak(m)
         m = m + 1
      end do
      h1 = quo*(a1(1) + v*(a1(2) + v*(a1(3) + v*(a1(4) + v*a1(5)))))

      if(k.le.1) then
         voigte=h1*a + ex*(un + a*a*(un - two*v2))
         return
      end if
 
      pqs=two/sqp           
      h1p = h1 + pqs*ex
      h2p = pqs*h1p - two*v2*ex
      h3p = (pqs*(un - ex*(un - two*v2)) - two*v2*h1p)/3. + pqs*h2p
      h4p = (two*v2*v2*ex - pqs*h1p)/3. + pqs*h3p
      psi = ak(16) + a*(ak(17) + a*(ak(18) + a*ak(19)))
      voigte=psi*(ex + a*(h1p + a*(h2p + a*(h3p + a*h4p))))
      return

      end subroutine voigtf
C
C
C ********************************************************************
C
C

      SUBROUTINE SRTFRQ
C     =================
C
C     Sort the frequency sets, and assign to each frequency
C     a list of contributing transitions
C     Select final frequency set.
C
      use accura
      use atomic
      use basics
      use modelq

      implicit none 

      REAL(DP), PARAMETER :: SIXTH=UN/6.,FTH=4./3.,V0X=4.e-4,VCX=4.e-3,
     *                       CLI=2.997925E18
      REAL(DP)            :: SX(500)
C     REAL(DP)            :: SGZ(MTRANS)

      REAL(DP) :: DX0,DNUX,SX0,SXX,Z0,Z1,Z2,ZH,T1,T2,T3,X1,X2,X3,X15
      REAL(DP) :: BNZ,T1S,T1ER,T2S,T2ER,T3S,T3ER,Z00,DNUXA,DNUXB,FX1
      REAL(DP) :: PSX0
      INTEGER  :: IT,IJ,JK1,NLIMAX,NPPX,ISX,IJP,NPX,NIXA,NIXB
      INTEGER  :: IJE,KJ0,IK1,IK2,JK2,JK3,IPX,ITRX,ICOUNT
C
      if(ioptab.lt.0) return
      if(ispodf.ge.1) return
C
C     Sort frequencies and assign primary line
C
      CALL INDEXX(NFREQ,FREQ,NLINES)
c      write(*,*) 'after indexx',nfreq
       
      DO IJ=1,NFREQ
         KIJ(NLINES(IJ))=NFREQ-IJ+1
c       write(*,"('srt',i7,f12.3,2x,i7,2x,i7,f12.3)") 
c    *  ij,cli/freq(ij),nfreq-ij+1,nlines(ij),cli/freq(nlines(ij))
      END DO
      ICOUNT=0
      DO IT=1,NTRANS
         IF(.NOT.LINEXP(IT)) THEN
            ICOUNT=ICOUNT+1
            KFR0(IT)=KIJ(IFR0(IT))
            KFR1(IT)=KIJ(IFR1(IT))
            DO IJ=IFR0(IT),IFR1(IT)
               IJLIN(IJ)=IT
            END DO
c           write(*,"('itr',3i7,2f11.3,2i7,2f11.3)") 
c    *   it,ifr0(it),ifr1(it),cli/freq(ifr0(it)),cli/freq(ifr1(it)),
c    *   kfr0(it),kfr1(it),cli/freq(kfr0(it)),cli/freq(kfr1(it))
         END IF
      END DO
!     write(*,*)
!     write(*,*) 'ICOUNT',icount
!     write(*,*)
      DO IJ=1,NFREQ
         JIK(KIJ(IJ))=IJ
c     if(icount.gt.0) write(*,"('kij',i7,f12.3,3i7,f12.3)")
c    * ij,cli/freq(ij),ijlin(ij),nlines(ij),kij(ij),cli/fr0(ijlin(ij))
      END DO
      JK1=JIK(1)
      IF(ICOUNT.GT.0.AND.IJLIN(JK1).NE.0)
     *  CALL QUIT(' Largest freq. is a line freq. - (SRTFRQ)',
     *             JK1,IJLIN(JK1))
      JK1=JIK(NFREQ)
      IF(ICOUNT.GT.0.AND.IJLIN(JK1).NE.0)
     *  CALL QUIT(' Smallest freq. is a line freq. - (SRTFRQ)',
     *             JK1,IJLIN(JK1))
C
C     lines or ODFs associated with each frequency
C

c     do it=1,ntrans
c        if(linexp(it)) cycle
c        write(*,"('tr',5i8)") it,ifr0(it),ifr1(it),kfr0(it),kfr1(it)
c     end do


      NLIMAX=0
      DO IJ=1,NFREQ
         NLINES(IJ)=0
         DO IT=1,NTRANS
            IF(LINEXP(IT)) CYCLE   
            IF(KIJ(IJ).LT.KFR0(IT)) CYCLE
            IF(KIJ(IJ).GT.KFR1(IT)) CYCLE
            IF(IJLIN(IJ).EQ.IT) CYCLE
            NLINES(IJ)=NLINES(IJ)+1
CC          IF(NLINES(IJ).GT.MITJ)
CC   *      CALL QUIT('Too many overlappins-nlines(ij).gt.mitj',
CC   *      nlines(ij),mitj)
c           ITRLIN(NLINES(IJ),IJ)=IT
c           write(6,"('nlines',3i7)") ij,it,nlines(ij)
         END DO
         IF(NLINES(IJ).GT.NLIMAX) NLIMAX=NLINES(IJ)
      END DO
      WRITE(6,611) NLIMAX
  611 FORMAT(/' MAXIMUM NUMBER OF OVERLAPPING TRANSITIONS:  ',I3/)

      MITJ=NLIMAX
      ALLOCATE (ITRLIN(MITJ,MFREQ))
!     write(*,*) 'itrlin',size(itrlin),shape(itrlin)
      
      DO IJ=1,NFREQ
         NLINES(IJ)=0
         DO IT=1,NTRANS
            IF(LINEXP(IT)) CYCLE
            IF(KIJ(IJ).LT.KFR0(IT)) CYCLE
            IF(KIJ(IJ).GT.KFR1(IT)) CYCLE
            IF(IJLIN(IJ).EQ.IT) CYCLE
            NLINES(IJ)=NLINES(IJ)+1
            ITRLIN(NLINES(IJ),IJ)=IT
         END DO
!        write(*,"('nlines',i5,f12.3,2i5,2x,13i4)") ij,cli/freq(ij),
!    &      ijlin(ij),NLINES(IJ),(itrlin(it,ij),it=1,nlines(ij))
      END DO  
C
C     Select final set of frequencies:
C        IJX = 1 : included frequency
C        IJX =-1 : rejected frequency
C        IJX = 0 : used for rates, but no contribution of primary
C                   transition to opacity
C
      NPPX=NFREQ-NFREQC
      TRAN: DO IT=1,NTRANS
         IF(LINEXP(IT)) CYCLE TRAN
         IF(ABS(INDEXP(IT)).NE.3) CYCLE TRAN
         IF(PROF(IFR0(IT)+1).GT.PROF(IFR1(IT)-1)) THEN
           DO IJ=IFR0(IT)+5,IFR1(IT)-1
              IJX(IJ)=-1
              NPPX=NPPX-1
           END DO
         ELSE
           DO IJ=IFR0(IT)+1,IFR1(IT)-5
              IJX(IJ)=-1
              NPPX=NPPX-1
           END DO
         END IF
      END DO TRAN

!      write(*,*) 'end do tran'

      ISX=0
      FRLOOP: DO IJ=1,NFREQ
        ISX=ISX-1
        IF(ISX.GT.0) CYCLE FRLOOP
        IJP=JIK(IJ)
        DX0=0.
        IF(IJX(IJP).EQ.1) CYCLE FRLOOP
        IF(PROF(IJP).EQ.0.) CYCLE FRLOOP
        DX0=V0X*FREQ(IJP)
        DNUX=ABS(FREQ(JIK(IJ-1))-FREQ(IJP))
        IF(DNUX.GT.DX0) THEN
            IJX(IJP)=1
            NPPX=NPPX+1
         ELSE
          NPX=0
          DO WHILE (DNUX.LT.DX0 .AND. IJX(JIK(IJ+NPX)).EQ.-1)
            ITRX=IJLIN(JIK(IJ+NPX))
            PSX0=PROF(IFR0(ITRX+1))
            IF(PSX0.GT.0.) THEN
              SX0=PROF(JIK(IJ+NPX))/PSX0
              SX(NPX+1)=PROF(JIK(IJ+NPX))/PROF(IJP)*SX0
            ELSE
              SX(NPX+1)=0.
            ENDIF
            NPX=NPX+1
            DNUX=ABS(FREQ(JIK(IJ-1))-FREQ(JIK(IJ+NPX)))
          END DO
          IF(NPX.EQ.1) THEN
            IJX(IJP)=1
            NPPX=NPPX+1
           ELSE
            SXX=-1.
            DO IPX=1,NPX
              IF(SX(IPX).GT.SXX) THEN
                SXX=SX(IPX)
                ISX=IPX
              END IF
            END DO
            IJX(JIK(IJ+ISX))=1
            NPPX=NPPX+1
          END IF
        END IF
      END DO FRLOOP
!     write(*,*) 'end do frloop'

      FRLP2: DO IJ=1,NFREQ
        IJP=JIK(IJ)
        IF(IJP.GT.NFREQC) CYCLE FRLP2
        IF(IJX(IJP).EQ.1) THEN
          NPPX=NPPX+1
          CYCLE FRLP2
        END IF
        DX0=VCX*FREQ(IJP)
        NIXA=0
        DO WHILE (IJX(JIK(IJ-NIXA)).NE.1)
           NIXA=NIXA+1
        END DO
        NIXB=0
        DO WHILE (IJX(JIK(IJ+NIXB)).NE.1)
           NIXB=NIXB+1
        END DO
        DNUXA=ABS(FREQ(JIK(IJ-NIXA))-FREQ(IJP))
        DNUXB=ABS(FREQ(JIK(IJ+NIXB))-FREQ(IJP))
        IF(DNUXA.GT.DX0 .AND. DNUXB.GT.DX0) THEN
          IJX(IJP)=1
          NPPX=NPPX+1
        ELSE
          IJX(IJP)=-1
        END IF
      END DO FRLP2

!     write(*,*) 'end do frlp2'
c
c     correction
c
      if(icompt.eq.0) then
         do ij=1,nfreqc
            ijx(ij)=1
         end do
         do ije=1,nfreqe
            ijx(ijfr(ije))=1
         end do
      end if
C
C     weights
C
      FRW: DO IJ=1,NFREQ
         W(IJ)=0.
         KJ0=KIJ(IJ)
         IF(IJX(JIK(KJ0)).EQ.-1) CYCLE FRW
         IF(KJ0.GE.2 .AND. KJ0.LT.NFREQ) THEN
           IK1=KJ0-1
           DO WHILE (IJX(JIK(IK1)).EQ.-1)
             IK1=IK1-1
           END DO
           IK2=KJ0+1
           DO WHILE (IJX(JIK(IK2)).EQ.-1)
             IK2=IK2+1
           END DO
           W(IJ)=HALF*ABS(FREQ(JIK(IK1))-FREQ(JIK(IK2)))
          ELSE IF(KJ0.EQ.1) THEN
           W(IJ)=HALF*ABS(FREQ(JIK(KJ0))-FREQ(JIK(KJ0+1)))
          ELSE IF(KJ0.EQ.NFREQ) THEN
           W(IJ)=HALF*ABS(FREQ(JIK(KJ0-1))-FREQ(JIK(KJ0)))
         END IF
c      if(ij.le.2000) write(*,"('fr1',4i7,1p4e12.4)") ij,kj0,ik1,ik2,
c    * freq(ij),freq(jik(ik1)),freq(jik(ik2)),w(ij)
      END DO FRW
C
C     Correction for Simpson weights
C
      JK1=JIK(1)
      DO IJ=2,NFREQ,2
         JK2=JIK(IJ)
         JK3=JIK(IJ+1)
         IF(IJLIN(JK2).NE.0 .OR. IJLIN(JK3).NE.0) EXIT
         IF(WCH(JK2).NE.0.) EXIT
         W(JK1)=W(JK1)-SIXTH*W(JK2)
         W(JK3)=W(JK3)-SIXTH*W(JK2)
         W(JK2)=W(JK2)*FTH
         JK1=JK3
c      if(ij.le.2000) write(*,"('fr2',4i7,1p4e12.4)") ij,jk1,jk2,jk3,
c    * freq(ij),w(jk1),w(jk2),w(jk3)
      END DO
      JK1=JIK(NFREQ)
      DO IJ=NFREQ-1,3,-2
         JK2=JIK(IJ)
         JK3=JIK(IJ-1)
         IF(IJLIN(JK2).NE.0 .OR. IJLIN(JK3).NE.0) EXIT
         IF(WCH(JK2).NE.0.) EXIT
         W(JK1)=W(JK1)-SIXTH*W(JK2)
         W(JK3)=W(JK3)-SIXTH*W(JK2)
         W(JK2)=W(JK2)*FTH
         JK1=JK3
c      if(ij.le.2000) write(*,"('fr3',4i7,1p4e12.4)") ij,jk1,jk2,jk3,
c    * freq(ij),w(jk1),w(jk2),w(jk3)
      END DO
C
C     check accuracy of weights for integration
C
      Z0=0.
      Z1=0.
      Z2=0.
      ZH=0.
      T1=TEFF
      T2=TWO*TEFF
      T3=HALF*TEFF
      X1=HK/T1
      X2=HK/T2
      X3=HK/T3
      DO IJ=1,NFREQ
         Z0=Z0+W(IJ)
         X15=FREQ(IJ)*1.D-15
         BNZ=BN*X15*X15*X15
         FX1=FREQ(IJ)*X1
         IF(FX1.LE.100.) THEN
            Z1=Z1+W(IJ)*BNZ/(EXP(FREQ(IJ)*X1)-1)
            Z2=Z2+W(IJ)*BNZ/(EXP(FREQ(IJ)*X2)-1)
            ZH=ZH+W(IJ)*BNZ/(EXP(FREQ(IJ)*X3)-1)
         END IF
      END DO
      T1S=SQRT(SQRT(0.25*Z1/SIG4P))
      T1ER=T1S/T1-UN
      T2S=SQRT(SQRT(0.25*Z2/SIG4P))
      T2ER=T2S/T2-UN
      T3S=SQRT(SQRT(0.25*ZH/SIG4P))
      T3ER=T3S/T3-UN
      JK1=JIK(1)
      JK2=JIK(NFREQ)
      Z00=FREQ(JK1)-FREQ(JK2)
      WRITE(6,"(/' ACCURACY OF INTEGRATIONS:',/,
     *   ' Interval:',1p4e16.8,/,
     *   15x,' Planck functions:',9x,0pf12.0,4x,1pe12.4,/,
     *   42x,0pf12.0,4x,1pe12.4,/,42x,0pf12.0,4x,1pe12.4,/)") 
     *  FREQ(JK1),FREQ(JK2),Z00,Z0,T3,T3ER,T1,T1ER,T2,T2ER
      WRITE(6,"(' TOTAL NUMBER OF FREQUENCIES:',I8,/,
     *       ' SELECTED FREQUENCIES:       ',I8)") NFREQ,NPPX
C
      RETURN
      END SUBROUTINE SRTFRQ

! ***********************************************************************



      subroutine rdatax(itr,ic,inunit)
c     ====================================
c
c     for itr, itrx ne 0 - read input data for an individual transition
c     and prepare necessary auxiliary arrays
c
      use accura
      use atomic
      use basics
      use modelq
      use xdata
c
      implicit none

      integer, intent(in)    :: itr,inunit
      integer                :: itrx
      real(dp) :: a(11,5),b(5)

      integer  :: i,j,itx,ie,it,ii,ia,ic,iz1,jj,nfreqb,na,ij
      real(dp) :: sg

      if(itr.gt.0) then
         ntrx=ntrx+1
         if(ntrx.eq.1) then
            allocate (iex(mtrx),itrind(mtrx),izx0(mtrx),izx1(mtrx),
     *                nmaxx(mtrx),izx(mtrx),nshx(mtrx),nax(mtrx),
     *                icx(mtrx))
            allocate (etx(mtrx),ssx(mtrx),dx(mtrx))
            allocate (aphx(11,5,mtrx),bphx(5,mtrx))
         end if
c         
         itrx=ntrx
         ii=ilow(itr)
         ie=iel(ii)
         jj=iup(itr)
         iex(itrx)=ie
         icx(itrx)=ic
         itrind(itrx)=itr
         izx0(itrx)=iz(ie)
         izx1(itrx)=jj-1000
c       write(6,"('itr,ntrx,ie,ii',6i5)") itr,ntrx,ie,ii,jj,inunit
c
c        read inner-shell photoionization data from Omer's tables
c
         read(inunit,*) etx(itrx)
c       write(*,*) 'itrx,etx',itrx,etx(itrx)
         read(inunit,*) nmaxx(itrx),izx(itrx),nshx(itrx)
         read(inunit,*) ssx(itrx)
         read(inunit,*) nax(itrx)
         read(inunit,*) dx(itrx)
         do i=1,nax(itrx)
            read(inunit,*) bphx(i,itrx)
c           write(*,*) i,itrx,bphx(i,itrx)
         end do
         do j=1,nax(itrx)
            do i=1,11
               read(inunit,*) aphx(i,j,itrx)
c              write(*,*) i,j,itrx,aphx(i,j,itrx)
            end do
         end do
       else if(itr.eq.0) then
c
c      for itr=0 - set up array BFCS with actual cross-sections
c
         if(ntrx.gt.0) then
            do itx=1,ntrx
               ie=iex(itx)
               it=itrind(itx)
               ii=ilow(it)
               ia=iatm(ii)
               iz1=izx1(itx)
               ic=icx(itx)
               jj=0
               level: do i=1,nlevel
                  if(iatm(i).eq.ia) then
                     if(iz(iel(i)).eq.iz1) then
                        jj=i
                        exit level
                     end if
                  end if
               end do level

               if(jj.eq.0) then
                  if(iz1.eq.iz(iel(nka(ia)-1))+1) jj=nka(ia)
               end if
               if(jj.eq.0) indexp(it)=0
c
               if(indexp(it).ne.0) then
                  iup(it)=jj
                  fr0(it)=etx(itx)/4.1357e-15
                  line(it)=.false.
                  itrcon(it)=ic
                  if(icol(it).ne.99) then
                     itra(ii,jj)=it
                     itra(jj,ii)=ic
                  end if
c
c                 write(6,"(8i4,1pe12.4,0pf10.2)") itx,it,ii,jj,ia,
c    *                         itra(ii,jj),itra(jj,ii),
c    *                         icol(it),fr0(it),etx(itx)
               end if
            end do
         end if
c
       else
         nfreqb=nfreq
         if(ibfint.gt.0) nfreqb=nfreqc
         if(ntrx.gt.0) then
            do itx=1,ntrx
               it=itrind(itx)
               ic=icx(itx)
               if(indexp(it).ne.0) then
                  na=nax(itx)
                  do i=1,na
                     b(i)=bphx(i,itx)
                  end do
                  do j=1,na
                     do i=1,11
                        a(i,j)=aphx(i,j,itx)
                     end do
                  end do
c
                  do ij=1,nfreqb
                     call bkhsgo(freq(ij),etx(itx),dx(itx),b,na,a,
     *               ssx(itx),nmaxx(itx),izx(itx),nshx(itx),sg)
                     bfcs(ic,ij)=sg
                  end do
                  write(97,"(5i5,1p1e15.5)") itx,it,ic,
     *            ilow(it),iup(it),bfcs(ic,1)
                  write(*,"(5i5,1p1e15.5)") itx,it,ic,
     *            ilow(it),iup(it),bfcs(ic,1)
               end if
            end do
         end if
      end if
c      write(*,*) 'end rdatax of itr',itr
      return
      end

C
C
C     ***************************************************************
C
C
      subroutine bkhsgo(freq,et,d,b,na,a,ss,nmax,iz,nsh,sg)
c     =====================================================
c
c
c subroutine to calculate K and L shell photoionization cross-sections
c       -based on Tim Kallman's bkhsgo subroutine from XSTAR, modified
c        by Omer Blaes 5-7-98.
c       -na.ne.2 bug corrected on 2/24/00 by Omer Blaes
c
c freq is photon frequency in Hz (note that this subroutine immediately
c converts it into eV)
c
c et is threshold energy in eV
c
c iz is the ionization stage of the species being photoionized (1=neutral etc.)
c
c ss is the iz'th element of the array ss(nmax) in Tim's original version
c
c sg is returned as the contribution to the photoionization cross-section
c in cm^2 due to whatever process is being considered.
c
c     this routine does the work in computing cross sections by the
c     method of barfield, et. al.
c
      use accura          

      implicit none
      
      real(dp) ::  b(5),a(11,5)
      real(dp), intent(in) :: freq,et,d,ss
      real(dp),intent(out) :: sg
      integer, intent(in)  :: na,nmax,iz,nsh
c
      real(dp), parameter ::  sigth=1.e-34
      real(dp) :: tmp1,epii,xx,yy,tmp,sgtmp,tmp1o,enelec
      integer  :: jj,nna,kk,kkk,nelec

      tmp1 = 0.
      jj = 1
      epii = 4.1357e-15*freq
      sg=0.
      if ( epii.gt.et ) then
        xx = epii*(1.e-3) - d
        if ( xx.le.0. ) return
        do nna=1,na
          if ( xx.ge.b(nna) ) jj = jj + 1
        enddo
        if ( jj.le.na ) then
        if(xx.lt.0.) xx=0.
          yy = log10(xx)
          tmp = 0.
          do kkk = 1,11
            kk = 12 - kkk
            tmp = a(kk,jj) + yy*tmp
          end do
          if(tmp.lt.-50.) tmp=-50.
          if(tmp.gt.24.) tmp=24.
          sgtmp = 10.**(tmp-24.)
        nelec=nmax+1-iz
        if(nelec.gt.nsh) nelec=nsh
          enelec = float(nelec)
          tmp1o = tmp1
          tmp1=sgtmp*ss
        if(tmp1.lt.sigth*enelec) tmp1=sigth*enelec
          if ( epii.ge.5.e+4 ) then
           if(tmp1.gt.tmp1o) tmp1 = tmp1o
          end if
          sg = sg + tmp1
        endif
      endif
      return
      end subroutine bkhsgo
C    
C    
C ************************************************************************
C    
C    
c

      SUBROUTINE SABOLF(ID)
C     =====================
C
C     Saha-Boltzmann factors (SBF)
C     and "upper sums" - sum of Saha-Boltzmann factors for upper, LTE,
C     levels which are not included explicitly (USUM), and derivatives
C     wrt. temperature (T) and electron density (DUSUMN)
C
C     Input: ID  - depth index
C
      use accura
      use atomic
      use basics
      use modelq

      implicit none

      REAL(DP), PARAMETER :: UH=1.5_dp,CMAX=2.154e4_dp,
     *                       CCON=2.0706e-16_dp
      INTEGER, INTENT(IN) :: ID
      REAL(DP) :: T,SQT,ANE,STANE,XMAX,TK,CON,QZ,CFN,DCH,SSBF,DSSBFT
      REAL(DP) :: E,SUM,XI,XJ,X,FI,SB,XMX,CFE,XX,DSUM,EE
      REAL(DP) :: U,DUT,DUN
      INTEGER  :: ION,IUPS,II,NLST,NL1UP,J,IAT
C
C     DCHI - approximate lowering of ionization potential for neutrals
C      Actual lowering is DCHI*effective charge, and is considered only
C      if IUPSUM(ION).GT.0
C
c
      if(ioptab.lt.0) return
c
      T=TEMP(ID)
      SQT=SQRT(T)
      ANE=ELEC(ID)
      STANE=SQRT(T/ANE)
      XMAX=CMAX*SQRT(STANE)
      TK=BOLK*T
      CON=CCON/T/SQT
C
C     Saha-Boltzmann factors
C
c      write(*,*) 'nion',nion
      IONLOOP: DO ION=1,NION
c      write(*,*) 'ion,iz',ion,iz(ion)
         QZ=IZ(ION)
         CFN=CON/G(NNEXT(ION))
         DCH=0.
         IUPS=IUPSUM(ION)
         SSBF=0.
         DSSBFT=0.
         USUM(ION)=0.
         DUSUMT(ION)=0.
         DUSUMN(ION)=0.
         nlst=nlast(ion)
         if(ifwop(nlst).ge.0) then
             nl1up=nquant(nlst)+1
          else
             nl1up=nquant(nlst)
         end if
c     write(*,*) 'n0,n1',nfirst(ion),nlast(ion)    
         DO II=NFIRST(ION),NLAST(ION)
            if(ifwop(ii).lt.0) then
               E=EH*QZ*QZ/TK
               SUM=0.
c          write(*,*) 'ii',ii,e
               DO J=nl1up,NLMX
                  XJ=J
                  XI=J*J
                  X=E/XI
c               write(*,*) 'j',j,xj,xi,x
                  FI=XI*EXP(X)*WNHINT(J,ID)
                  SUM=SUM+FI
               END DO
               g(ii)=sum*two
c           write(*,*) 'g',g(ii),imrg(ii)
               gmer(imrg(ii),id)=g(ii)
            end if
            X=ENION(II)/TK
            if(x.gt.110.) x=110.
            SB=CFN*G(II)*EXP(X)
            SBF(II)=SB
            SSBF=SSBF+SB
            DSBF(II)=-(UH+ENION(II)/TK)/T
            DSSBFT=DSSBFT+SB*DSBF(II)
c      write(*,*) 'sabolf',ion,ii,id,sbf(ii)
         END DO
C
C     Upper sums
C
         if(ifwop(nlst).ge.0) then
            IF(ION.EQ.IELHM) THEN
               USUM(ION)=0.
               DUSUMT(ION)=0.
               DUSUMN(ION)=0.
               CYCLE IONLOOP
            END IF
            if(ion.ge.0) CYCLE IONLOOP
            IF(IUPS.EQ.0) THEN
C
C     1. More exact approach - using (exact) partition functions
C
               IAT=NUMAT(IATM(NFIRST(ION)))
               XMX=XMAX*SQRT(QZ)
               CALL PARTF(IAT,IZ(ION),T,ANE,XMX,U,DUT,DUN)
               EE=ENION(NFIRST(ION))/TK
               IF(EE.GT.110.) EE=110.
               CFE=CFN*EXP(EE)
               USUM(ION)=CFE*U-SSBF
               DUSUMT(ION)=CFE*(DUT-U/T*(UH+EE))-DSSBFT
               DUSUMN(ION)=CFE*DUN
               xx=(ssbf-sbf(nfirst(ion)))/sbf(nfirst(ion))
               IF(USUM(ION).LT.0.or.ee.ge.109.or.xx.lt.1.e-7) THEN
                   USUM(ION)=0.
                   DUSUMT(ION)=0.
                   DUSUMN(ION)=0.
               END IF
C
C     2. Approximate approach - summation over fixed number of upper
C        levels, assumed hydrogenic (ie. their ionization energy and
C        statistical weight hydrogenic)
C
             ELSE IF(IUPS.GT.0) THEN
               SUM=0.
               DSUM=0.
               E=EH*QZ*QZ/TK
               DO J=NQUANT(NLAST(ION))+1,IUPS
                  XI=J*J
                  X=E/XI
                  FI=XI*EXP(X)
                  SUM=SUM+FI
                  DSUM=DSUM-FI*(UH+X)/T
               END DO
               USUM(ION)=SUM*CON*TWO
               DUSUMT(ION)=DSUM*CON*TWO
               DUSUMN(ION)=0.
C
c        3. occupation probability form
c
             ELSE
               SUM=0.
               DSUM=0.
               E=EH*QZ*QZ/TK
               DO J=NQUANT(NLAST(ION))+1,NLMX
                  XJ=J
                  XI=J*J
                  X=E/XI
                  FI=XI*EXP(X)*WNHINT(J,ID)
                  SUM=SUM+FI
                  DSUM=DSUM-FI*(UH+X)/T
               END DO
                  USUM(ION)=SUM*CON*TWO
               DUSUMT(ION)=DSUM*CON*TWO
               DUSUMN(ION)=0.
            END IF
         end if
      END DO IONLOOP
      RETURN
      END SUBROUTINE SABOLF
C
C
C     ****************************************************************
C
C
C

      SUBROUTINE WNSTOR(ID)
C     =====================
C
C     Stores occupation probabilities for hydrogen levels
C     in common WNCOM for further use
C
      use accura
      use atomic
      use basics
      use modelq
CC    use molec

      implicit none 

      REAL(DP), PARAMETER :: 
     *          SIXTH=UN/6._dp,CCOR=0.09_dp,a0=5.29e-9_dp,
     *          p1=0.1402_dp,p2=0.1285_dp,p3=un,p4=3.15_dp,p5=4._dp,
     *          tkn=3.01_dp,ckn=5.33333333_dp,cb0=8.59e14_dp,
     *          f23=-two/3._dp
      INTEGER, INTENT(IN) :: ID
      REAL(DP) :: CB,ANE,AH,A,Z,X,C1,C2,BETA,XN,XN1,XKN,F
      REAL(DP) :: WNEUT,BETA0,WN
      INTEGER  :: I,II,IE,NQ,ILLLL

      if(ioptab.lt.0) return
C
      cb=cb0*bergfc
      ANE=ELEC(ID)
      if(ielh.gt.0) then
         ah=popul(nfirst(ielh),id)
       else
         ah=anato(1,id)
      end if
      aneut=ah
      A=CCOR*EXP(SIXTH*LOG(ANE))/SQRT(TEMP(ID))
      z=un
      x=exp(p4*log(un+p3*a))
      c1=p1*(x+p5*(z-un)*a*a*a)
      c2=p2*x
      beta0=cb*z*z*z*exp(f23*log(ane))
      DO I=1,NLMX
         XN=I
         if(xn.le.tkn) then
            xkn=un
         else
            xn1=un/(xn+un)
            xkn=ckn*xn*xn1*xn1
         end if
         beta=beta0*xkn*xi2(i)*xi2(i)
         f=(c1*beta*beta*beta)/(un+c2*beta*sqrt(beta))
         wneut=exp(-4.189_dp*aneut*(a0*(un+xn*xn))**3)
         WNHINT(I,ID)=f/(un+f)*wneut
      END DO
C
C     array WOP - occupation probabilities for explicit levels
C       (if ifwop>1, occ. probabilities have been initialized
C          for iron-peak elements and are not updated)
C
      do ii=1,nlevel

        if(ifwop(ii).le.0) then
          wop(ii,id)=un

        else if(ifwop(ii).eq.1) then
          ie=iel(ii)
          nq=nquant(ii)
          if(iz(ie).eq.1) then
            wop(ii,id)=wnhint(nq,id)
          else
            z=iz(ie)
            xn=nq
            wop(ii,id)=wn(xn,a,ane,z)
          end if
        end if
        if(ifwop(ii).gt.1.and.lte) wop(ii,id)=un
        illll=0
        if(lte) illll=1
      end do

      RETURN
      END SUBROUTINE WNSTOR
C
C
C     ****************************************************************
C
C
C
      real(dp) function wn(xn,a,ane,z)
c     ===============================
c
c     evaluation of the occupation probablities for a hydrogenic ion
c     using eqs (4.26), and (4.39) of Hummer,Mihalas Ap.J. 331, 794, 1988.
c     approximate evaluation of Q(beta) - Hummer
c
c     Input: xn  - real number corresponding to quantum number n
c            a   - correlation parameter
c            ane - electron density
c            z   - ionic charge
c
      use accura
      use basics
      implicit none

      real(dp), parameter :: 
     *          p1=0.1402_dp,p2=0.1285_dp,p3=un,p4=3.15_dp,p5=4._dp,
     *          tkn=3.01_dp,ckn=5.33333333_dp,cb0=8.59e14_dp,
     *          f23=-two/3._dp,a0=5.29e-9_dp

      real(dp), intent(in) :: xn,a,ane,z
      real(dp) :: cb,xn1,xkn,beta,x,c1,c2,f,wneut
   
c
      cb=cb0*bergfc
c
c     evaluation of k(n)
c
      if(xn.le.tkn) then
         xkn=un
       else
         xn1=un/(xn+un)
         xkn=ckn*xn*xn1*xn1
      end if
c
c     evaluation of beta
c
      beta=cb*z*z*z*xkn/(xn*xn*xn*xn)*exp(f23*log(ane))
c
c     approximate expression for Q(beta)
c
      x=exp(p4*log(un+p3*a))
      c1=p1*(x+p5*(z-un)*a*a*a)
      c2=p2*x
      f=(c1*beta*beta*beta)/(un+c2*beta*sqrt(beta))
      wn=f/(un+f)
      wneut=exp(-4.189*aneut*(a0*(un+xn*xn))**3)
      wn=wn*wneut
c     write(6,"('wn',1p9e10.2)") xn,ane,aneut,f/(un+f),wneut,wn
      return
      end function wn
C
C
C     ****************************************************************
C
C
C

      SUBROUTINE DWNFR(MODE,N,FRE,A,ANE,Z,FR,DW)
C     ==========================================
C
C     Auxiliary routine to compute set of dissolved fractions
C     for all frequencies
C      MODE=0  ->  DW=1
C      MODE>0  ->  DW=1-w
C

      use accura
      use atomic
      use basics
      use modelq

      implicit none

      real(dp), parameter :: 
     *          p1=0.1402_dp,p2=0.1285_dp,p3=un,p4=3.15_dp,p5=4._dp,
     *          tkn=3.01_dp,ckn=5.33333333_dp,cb0=8.59e14_dp,
     *          f23=-two/3._dp,a0=5.29e-9_dp,
     *          frh=3.28805e15_dp,sqfrh=5.734152e7_dp

      integer, intent(in) :: n,mode
      real(dp),intent(in) :: fre,a,ane,z

      REAL(DP) :: FR(N),DW(N)
      real(dp) :: cb,xn,xn1,xkn,beta,x,c1,c2,f
      integer  :: ij
C
      cb=cb0*bergfc
      IF(MODE.EQ.0) THEN
         DO IJ=1,N
            DW(IJ)=UN
         END DO
       ELSE
         DO IJ=1,N
            IF(FR(IJ).LT.FRE) THEN
               XN=SQFRH*Z/SQRT(FRE-FR(IJ))
               if(xn.le.tkn) then
                  xkn=un
               else
                  xn1=un/(xn+un)
                  xkn=ckn*xn*xn1*xn1
               end if
               beta=cb*z*z*z*xkn/(xn*xn*xn*xn)*exp(f23*log(ane))
               x=exp(p4*log(un+p3*a))
               c1=p1*(x+p5*(z-un)*a*a*a)
               c2=p2*x
               f=(c1*beta*beta*beta)/(un+c2*beta*sqrt(beta))
               DW(IJ)=UN-f/(un+f)*exp(-4.189*aneut*(a0*(un+xn*xn))**3)
             ELSE
               DW(IJ)=UN
            END IF
         END DO
      END IF
      RETURN
      END
C
C
C     ****************************************************************
C
C
C

      SUBROUTINE RTEANG
C     =================
C
C     initialization of the angle quadrature points for the radiative
C     transfer equation
C
      use accura
      use alipar
      use basics
      use modelq

      implicit none

      INTEGER, PARAMETER :: NMU3=3, NMU5=5
      REAL(DP) ::  AMU0(MMU),WTMU0(MMU)
      REAL(DP) :: X,XJ,XH,X0,X1
      INTEGER  :: I,I4,I5
C
C     If irradiation is neglected, the angular quadrature is a standard
C     NMU-point Gaussian quadrature
C
      X=WANGLE*HALF
      XJ=0.
      XH=0.
      IF(X.LE.0.) THEN
         call gauleg(zero,un,amu0,wtmu0,nmu,mmu)
         do i=1,nmu
            amu(i)=amu0(i)
            wtmu(i)=wtmu0(i)
            fmu(i)=0.
         end do
       ELSE
C
C     Here, allowance is made for irradiation by central star.
C     First, establish angular integration that takes into account
C     angles with mu < 0; instead of the standard 3-point integration
C     over angles, we have now a more general NMU5-point integration
C
         X0=HALF-X
         X1=HALF+X
         call gauleg(-un,un,amu0,wtmu0,nmu3,mmu)
         DO I=1,NMU3
            AMU(I)=X0*AMU0(I)+X1
            WTMU(I)=X0*WTMU0(I)
            FMU(I)=0.
         END DO
         NMU=NMU5
         i4=nmu3+1
         i5=nmu3+2
         AMU(i4)=X*(UN+0.577350269189626_DP)
         AMU(i5)=X*(UN-0.577350269189626_DP)
         DO I=NMU3+1,NMU5
            WTMU(I)=X
            FMU(I)=ASIN(SQRT((WANGLE**2-AMU(I)**2)/(UN-AMU(I)**2)))/
     *             3.141592653589793_DP
            XJ=XJ+WTMU(I)*FMU(I)
            XH=XH+WTMU(I)*AMU(I)*FMU(I)
         END DO
      END IF
C
      RETURN
      END SUBROUTINE RTEANG
C
C
C     ****************************************************************
C
C
C

      SUBROUTINE GAULEG(X1,X2,X,W,N,M)
C     ================================
C
C     set up angle points
C
      use accura
      implicit none

      REAL(DP) ::  X(M),W(M)
      REAL(DP), PARAMETER :: EPS=3.e-14,half=0.5_dp,pi=3.141592654_dp,
     *            quart=0.25_dp, un=1.0_dp, two=2.0_dp
      REAL(DP), INTENT(IN) :: X1,X2
      INTEGER, INTENT(IN)  :: N,M
      REAL(DP) :: XM,XL,P1,P2,P3,PP,Z,Z1
      INTEGER  :: N2,I,J
c
      N2=(N+1)/2
      XM=HALF*(X2+X1)
      XL=HALF*(X2-X1)
      DO I=1,N2
         Z=COS(PI*(I-quart)/(N+half))
         EVA: DO
            P1=1.D0
            P2=0.D0
            DO J=1,N
               P3=P2
               P2=P1
               P1=((TWO*J-UN)*Z*P2-(J-UN)*P3)/J
            END DO
            PP=N*(Z*P1-P2)/(Z*Z-un)
            Z1=Z
            Z=Z1-P1/PP
            IF(ABS(Z-Z1).LE.EPS) EXIT EVA
         END DO EVA
         X(I)=XM-XL*Z
         X(N+1-I)=XM+XL*Z
         W(I)=TWO*XL/((UN-Z*Z)*PP*PP)
         W(N+1-I)=W(I)
      END DO
      RETURN
      END SUBROUTINE GAULEG
C
C
C     ****************************************************************
C
C
C

      SUBROUTINE RATMAL(ID,NLEV)
C     ==========================
C
C     LTE RATE MATRIX  (SAHA-BOLTZMANN EQS.)
C
      use accura
      use atomic
      use basics
      use modelq

      implicit none 

      INTEGER, INTENT(IN)   :: ID,NLEV

      REAL(DP) :: ANE
      INTEGER  :: I,J,IAT,N0I,N1I,NKI,NREFI,N,IL
C
      ANE=ELEC(ID)
      DO I=1,NLEV
         BESE(I)=0.
         DO J=1,NLEV
            ESEMAT(J,I)=0.
         END DO
      END DO
C
      DO IAT=1,NATOM
         N0I=N0A(IAT)
         NKI=NKA(IAT)
         N1I=NKI-1
         NREFI=NKI
         DO I=N0I,N1I
            ESEMAT(I,I)=1.
            N=NNEXT(IEL(I))
            ESEMAT(I,N)=-ANE*SBF(I)*WOP(I,ID)
         END DO
         DO I=N0I,NKI
            IL=ILK(I)
            ESEMAT(NREFI,I)=UN
            IF(IL.NE.0) ESEMAT(NREFI,I)=1.+ANE*USUM(IL)
         END DO
         BESE(NREFI)=DENS(ID)/WMM(ID)/YTOT(ID)*ABUND(IAT,ID)
      END DO
C
      RETURN
      END SUBROUTINE RATMAL

!
!****************************************************************************
!

      REAL(DP) FUNCTION SIGK(FR,ITR,MODE)
C     ===================================
C
C     Photoionization cross-sections
C
C     Input: FR  -  frequency
C            ITR -  index of the transition
C            MODE-  =0 - cross-section equal to zero longward of edge
C                   >0 - cross-section non-zero (extrapolated) longward
C                        of edge
C
      use accura
      use atomic
      use basics
      implicit none

      REAL(DP), PARAMETER :: SIH0=2.815e29, E10=2.3025851
      REAL(DP) :: XFIT(MFIT) , ! local array containing x     for OP data
     *            SFIT(MFIT)   ! local array containing sigma for OP data
      REAL(DP), INTENT(IN) :: FR
      INTEGER, INTENT(IN)  :: ITR,MODE
      REAL(DP) :: SIGSP,CH,FRD,FR0L,GAU0,CORG,FREL,FR00,XL,SL,XL2,XL3
      REAL(DP) :: SIGM,FR1,FRDEC,X
      REAL(DP) :: SBFHMI,GAUNT,VERNER,GNTK,SBFHE1,TOPBAS,YLINTP
      INTEGER  :: IC,IB,II,IQ,IE,IQ5,NFIT,IFIT
C
      SIGK=0.
      IF(INDEXP(ITR).EQ.0) RETURN
      IF(MODE.EQ.0.AND.FR.LT.FR0(ITR)) RETURN
C
C     IC is the index of the given transition in the special numbering
C        of continua (given by ITRCON(ITR)
C     IBF(IC) is the switch controlling the mode of evaluation of the
C        cross-section:
C      = 0  hydrogenic cross-section, with Gaunt factor set to 1
C      = 1  hydrogenic cross-section with exact Gaunt factor
C      = 2  Peach-type expression (see function PEACH)
C      = 3  Henry-type expression (see function HENRY)
C      = 4  Butler fit formula (polynomial fits to the OP results);
C      = 5  Verner fit formula (OP results & HDS calculations at high
C              energies); ONLY for GROUND states;
C      = 6  DETAIL's fit formula from Klaus Werner
C              (similar to Butler's fit but up to 5th order)
C      = 7  hydrogenic cross-section with Gaunt factor after Werner
C      = 9  Opacity project fits (routine TOPBAS - interpolations)
C      > 100 - cross-sections extracted form TOPBASE, for several points
C           In this case, IBF-100 is the number of points
C      < 0  non-standard, user supplied expression (user should update
C           subroutine SPSIGK)
C
C      for H- : for any IBF > 0  - standard expression
C
C      for He I:
C       for IBF = 11 or = 13  -  Opacity Project cross section
C                Seaton-Ferney's cubic fits, Hummer's procedure (HEPHOT)
C           IBF = 11  means that the multiplicity S=1 (singlet)
C           IBF = 13  means that the multiplicity S=3 (triplet)
C       for IBF = 10  - cross section, based on Opacity Project, but
C                       appropriately averaged for an averaged level
C                       (see explanation in SBFHE1)
C
C       for IBF = 21 or 23  Koester's fit (A&A 149, 423)
C
C           IBF = 21  means that the multiplicity S=1 (singlet)
C           IBF = 23  means that the multiplicity S=3 (triplet)
C
      IC=ITRCON(ITR)
      IB=IBF(IC)
      II=ILOW(ITR)
      IQ=NQUANT(II)
      IE=IEL(ILOW(ITR))
c
c     special cases
c
      IF(IB.LT.0) THEN 
         CALL SPSIGK(IB,FR,SIGSP)
         SIGK=SIGSP
         RETURN
      END IF
      IF(IE.EQ.IELHM) THEN
         SIGK=SBFHMI(FR)
         RETURN 
      END IF
      IF(IE.EQ.IELHE1.AND.IB.GE.10.AND.IB.LE.23) THEN
         SIGK=SBFHE1(II,IB,FR,G(II))
         RETURN
      END IF
c
c     standard cases
c
      CH=IZ(IE)*IZ(IE)
      IQ5=IQ*IQ*IQ*IQ*IQ
C
      SELECT CASE(IB)
      CASE(0)
C
C        hydrogenic expression (for IBF = 0)
C
         SIGK=SIH0/FR/FR/FR*CH*CH/IQ5
C
C        exact hydrogenic - with Gaunt factor (for IBF=1)
C
       CASE(1)
         SIGK=SIH0/FR/FR/FR*CH*CH/IQ5
         frd=fr0(itr)
         fr0l=0.95*frd
         if(fr.ge.frd) then
            if(fr.lt.10.*frd)  sigk=sigk*gaunt(iq,fr/ch)
          else if(fr.ge.fr0l) then
            gau0=gaunt(iq,frd/ch)
            sigk=sigk*gau0
            corg=(fr-fr0l)/(frd-fr0l)*(gau0-1.)+1.
            sigk=sigk*corg
         end if
c      if(ii.eq.3) write(*,"('g3',1p6e12.4)") fr,frd,fr0l,gau0,corg,sigk
       CASE(2)
C
C        Peach-type formula (for IBF=2)
C
         FREL=FR0(ITR)/FR
         IF(GAMCS(IC).GT.0) THEN
            IF(GAMCS(IC).LT.1.E6) THEN
              FR00=2.997925E18/GAMCS(IC)
            ELSE
              FR00=GAMCS(IC)
            END IF
            IF(FR.LT.FR00) RETURN
         FREL=FR00/FR
         END IF
         if(frel.gt.0.)
     *   SIGK=PEACH(FREL,S0CS(IC),ALFCS(IC),BETCS(IC))
       CASE(3)
C
C        Henry-type formula (for IBF=3)
C
         FREL=FR0(ITR)/FR
         if(frel.gt.0.)
     *   SIGK=HENRY(FREL,S0CS(IC),ALFCS(IC),BETCS(IC),GAMCS(IC))
C
C        Butler expression
C
       CASE(4)
         FREL=FR0(ITR)/FR
         XL=LOG(FREL)
         SL=S0CS(IC)+XL*(ALFCS(IC)+XL*BETCS(IC))
         SIGK=EXP(SL)
C
C        Verner expression
C
       CASE(5)
         SIGK=VERNER(FR,ITR)
C
C        DETAIL expression
C
       CASE(6)
         FREL=FR0(ITR)/FR
         XL=LOG(FREL)
         XL2=XL*XL
         XL3=XL2*XL
         SL=CTOP(1,IC)+XL*CTOP(2,IC)+XL2*CTOP(3,IC)+XL3*CTOP(4,IC)
         SL=SL+XL2*XL2*CTOP(5,IC)+XL3*XL2*CTOP(6,IC)
         SIGK=EXP(SL)
C
C     exact hydrogenic - with Gaunt factor from K Werner (for IBF=7)
C
       CASE(7)
         IQ5=IQ*IQ*IQ*IQ*IQ
         SIGK=SIH0/(FR*FR*FR)*CH*CH/IQ5*GNTK(IQ,FR/CH)
C
C     selected Opacity Project data (for IBF=9)
C     (c.-s. evaluated by routine TOPBAS which needs an input file RBF.DAT)
C
       CASE(9)
         SIGK=TOPBAS(FR,FR0(ITR),TYPLEV(II))
C
C     hydrogenic expression for the pseudocontinuum
C
       CASE(16)
         SIGK=SIH0/FR/FR/FR*CH*CH/IQ5
         IF(FR.GT.FR0(itr)) SIGK=0.
       END SELECT
C
C     other Opacity Project data (for IBF>100)
C     (c.-s. evaluated by interpolating from direct input data)
C
       IF(IB.GT.100) THEN
         NFIT=IB-100
         X = LOG10(FR/FR0(ITR))
         SIGM=0.
         IF(X.GE.XTOP(1,IC)) THEN
           DO IFIT = 1,NFIT
              XFIT(IFIT) = XTOP(IFIT,IC)
              SFIT(IFIT) = CTOP(IFIT,IC)
           END DO
           SIGM  = YLINTP (X,XFIT,SFIT,NFIT,MFIT)
           SIGM  = 1.e-18*EXP(E10*SIGM)
          else
           sigm  = 1.e-18*exp(e10*sfit(1))
         ENDIF
         SIGK=SIGM
      END IF
      n0hn=nfirst(ielh)
c      if(ii.eq.3) write(*,*) ii,iatm(ii),iath,n0hn,ib,itr,fr,fr0(itr)
      if(iatm(ii).eq.iath.and.ii.ge.n0hn+2.
     *   and.ib.le.1.and.fr.lt.fr0(itr)) then
         fr1=fr0pc(ii)
         frdec=min(fr1*1.25,fr0(itr))
         if(fr.gt.fr1.and.fr.lt.frdec)
     *      sigk=sigk*(fr-fr1)/(frdec-fr1)
c      if(ii.eq.3) write(*,*) fr1,frdec,(fr-fr1)/(frdec-fr1),sigk
      end if
c
      RETURN

      CONTAINS
         REAL(DP) FUNCTION PEACH(X,S,A,B)
            REAL(DP), INTENT(IN) :: X,S,A,B
            PEACH  =A*X**S*(B+X*(1.-B))*1.e-18
         END FUNCTION PEACH
         REAL(DP) FUNCTION HENRY(X,S,A,B,C)
            REAL(DP), INTENT(IN) :: S,X,A,B,C
            HENRY=A*X**S*(C+X*(B-2.*C+X*(1.+C-B)))*1.e-18
         END FUNCTION HENRY

      END FUNCTION SIGK

C
C     ***************************************************************
C

      SUBROUTINE SIGAVE
C     =================
C
C     Read bound-free cross-sections for averaged levels
C     from the unit INSA (given by IFANCY), with increasing frequencies
C     It assumes that all continuum transitions for a given ion are
C     given in a successive order in the data
C
      use accura
      use atomic
      use basics
      use modelq
      use odfpar

      implicit none

      REAL(DP), ALLOCATABLE :: FRINSG(:),CRIN(:)
      INTEGER, ALLOCATABLE  :: JKF(:)
      REAL(DP),PARAMETER :: HCCM=H*2.997925e10,TX=2.30258509299405,
     *                      BAM=1.e-18
      REAL(DP) :: XIFE(8)
      REAL(DP) :: ECMR,GDUM,DE,FR,XF1,XF2,YS1,YS2,XXF,YYF,EXTX
      INTEGER  :: NFREQB,ITR,IC,INSA,IE,NL1,NL2,IOS,INL,NFIS,JI,JK
      INTEGER  :: IJ,I,IERR,IK,IZRR,NLRR

      ALLOCATE (FRINSG(MFREQ),CRIN(MFREQ))
      ALLOCATE (JKF(MFREQ))
C
      DATA XIFE/63480.,130563.,247220.,442000.,605000.,799000.,
     *          1008000.,1218380./
C
      NFREQB=NFREQ
      IF(IBFINT.GT.0) NFREQB=NFREQC

      ITR=0
      ITRLOOP: DO
         ITR=ITR+1 
         IF(ITR.GT.NTRANS) RETURN
         IC=ITRA(IUP(ITR),ILOW(ITR))
         INSA=IBF(IC)
         IF(INSA.LT.50 .OR. INSA.GT.100) CYCLE ITRLOOP
         IE=IEL(ILOW(ITR))
         ITR=ITR-1
         NL1=NFIRST(IE)
         NL2=NLAST(IE)
          write(6,"('insa',5i6,a40)") itr,insa,ie,nl1,nl2,fibfcs(ie)
         IF(FIBFCS(IE).NE.' ') THEN
            INSA=INBFCS(IE)
            OPEN(INSA,FILE=FIBFCS(IE),STATUS='OLD')
         END IF
         READ(INSA,*,IOSTAT=IOS) IERR,IZRR,NLRR
         IF(IOS.NE.0) THEN
            CALL QUIT
     *      ('error in data for bf-cs of averaged levels - itr,ie:',
     *       itr,ie)
            EXIT ITRLOOP
         END IF

         ILOOP: DO I=NL1,NL2
           ITR=ITR+1
           IF(INDEXP(ITR).EQ.0) CYCLE ILOOP
           IC=ITRA(IUP(ITR),ILOW(ITR))
           READ(INSA,*,IOSTAT=IOS) INL,ECMR,GDUM,NFIS
           IF(IOS.NE.0) EXIT ITRLOOP
           IF(IERR.EQ.26) THEN
              ECMR=XIFE(IZRR)-ECMR
              DE=ABS((ENION(ILOW(ITR))-HCCM*ECMR)/ENION(ILOW(ITR)))
              IF(DE.GT.2.e-2) WRITE(*,*) INSA,IE,ITR,I
           END IF
           DO IJ=1,NFIS
             JI=NFIS-IJ+1
             READ(INSA,*,IOSTAT=IOS) FRINSG(JI),CRIN(JI)
             IF(IOS.NE.0) THEN
                CALL QUIT
     *('error in data for bf-cs of averaged levels - itr,ie:',
     *          itr,ie)
                EXIT ITRLOOP
             END IF 
           END DO
           DO IJ=1,NFREQB
              JK=NFIS
              FR=FREQ(IJ)
              IF(ISPODF.GE.1) FR=FREQ(IFREQB(IJ))
              IKLOOP: DO IK=1,NFIS
                 IF(FR.GT.FRINSG(IK)) THEN
                    JK=IK
                    EXIT IKLOOP
                 END IF
             END DO IKLOOP
             IF(JK.EQ.1) JK=2
             JKF(IJ)=JK
           END DO
           DO IJ=1,NFREQB
              JK=JKF(IJ)
              FR=FREQ(IJ)
              IF(ISPODF.GE.1) FR=FREQ(IFREQB(IJ))
              IF(CRIN(JK-1).EQ.0. .OR. CRIN(JK).EQ.0.) THEN
                 BFCS(IC,IJ)=CRIN(JK)+(FR-FRINSG(JK))/
     *           (FRINSG(JK-1)-FRINSG(JK))*(CRIN(JK-1)-CRIN(JK))
               ELSE
                 XF1=LOG10(FRINSG(JK-1))
                 XF2=LOG10(FRINSG(JK))
                 YS1=LOG10(CRIN(JK-1))
                 YS2=LOG10(CRIN(JK))
                 XXF=LOG10(FR)
                 YYF=(XXF-XF2)/(XF1-XF2)*(YS1-YS2)+YS2
                 EXTX=EXP(TX*YYF)
                 BFCS(IC,IJ)=EXTX
              END IF
              BFCS(IC,IJ)=BAM*BFCS(IC,IJ)
           END DO
         END DO ILOOP
      END DO ITRLOOP

      RETURN
      END SUBROUTINE SIGAVE

C
C     ***************************************************************
C


      REAL(DP) FUNCTION SBFHE1(II,IB,FR,GG)
C     =====================================
C
C     Calculates photoionization cross sections of neutral helium
C     from states with n = 1, 2, 3, 4.
C
C     The levels are either non-averaged (l,s) states, or some
C     averaged levels.
C     The program allows only two standard possibilities of
C     constructing averaged levels:
C     i)  all states within given principal quantum number n (>1) are
C         lumped together
C     ii) all siglet states for given n, and all triplet states for
C         given n are lumped together separately (there are thus two
C         explicit levels for a given n)
C
C     The cross sections are calculated using appropriate averages
C     of the Opacity Project cross sections, calculated by procedure
C     HEPHOT
C
C     For IB=21 or IB=23, Koester (1985, AA 149, 423) fits
C
C     Input parameters:
C      II    - index of the lower level (in the numbering of explicit
C              levels)
C      IB    - photoionization switch IBF for the given transition
C            = 10        -  means that the given transition is from an
C                           averaged level
C            = 11 or 21  -  the given transition is from non-averaged
C                           singlet state
C            = 13 or 23  -  the given transition is from non-averaged
C                           triplet state
C      FR    - frequency
C
      use accura
      use atomic
      use basics
      implicit none

      INTEGER, INTENT(IN) :: II,IB
      REAL(DP),INTENT(IN) :: FR,GG
      INTEGER  :: NI,IGI,IS,IL
C
      NI=NQUANT(II)
      IGI=INT(G(II)+0.01)
      IS=IB-10
      IF(IB.GT.20) IS=IB-20
      sbfhe1=0.
C
C     ----------------------------------------------------------------
C     IB=11 or 13  - photoionization from an non-averaged (l,s) level
C     ----------------------------------------------------------------
C
      IF(IS.EQ.1.OR.IS.EQ.3) THEN
         IL=(IGI/IS-1)/2
       IF(IB.LT.20) THEN
           SBFHE1=HEPHOT(IS,IL,NI,FR)
       ELSE
         SBFHE1=CKOEST(IS,IL,NI,FR,GG)
       ENDIF
      END IF
C
C     ----------------------------------------------------------------
C     IS=10 - photoionization from an averaged level
C     ----------------------------------------------------------------
C
      IF(IS.EQ.0) THEN
         IF(NI.EQ.2) THEN
C
C ********    photoionization from an averaged level with n=2
C
            IF(IGI.EQ.4) THEN
C
C      a) lower level is an averaged singlet state
C
               SBFHE1=(HEPHOT(1,0,2,FR)+3.*HEPHOT(1,1,2,FR))/9.
            ELSE IF(IGI.EQ.12) THEN
C
C      b) lower level is an averaged triplet state
C
               SBFHE1=(HEPHOT(3,0,2,FR)+3.*HEPHOT(3,1,2,FR))/9.
            ELSE IF(IGI.EQ.16) THEN
C
C      c) lower level is an average of both singlet and triplet states
C
               SBFHE1=(HEPHOT(1,0,2,FR)+3.*(HEPHOT(1,1,2,FR)+
     *                HEPHOT(3,0,2,FR))+9.*HEPHOT(3,1,2,FR))/16.
            ELSE
               CALL QUIT('inconsistent sbfhe1',ni,igi)
            END IF
C
C
C ********    photoionization from an averaged level with n=3
C
         ELSE IF(NI.EQ.3) THEN
            IF(IGI.EQ.9) THEN
C
C      a) lower level is an averaged singlet state
C
               SBFHE1=(HEPHOT(1,0,3,FR)+3.*HEPHOT(1,1,3,FR)+
     *                5.D0*HEPHOT(1,2,3,FR))/9.
            ELSE IF(IGI.EQ.27) THEN
C
C      b) lower level is an averaged triplet state
C
               SBFHE1=(HEPHOT(3,0,3,FR)+3.*HEPHOT(3,1,3,FR)+
     *                5.*HEPHOT(3,2,3,FR))/9.
            ELSE IF(IGI.EQ.36) THEN
C
C      c) lower level is an average of both singlet and triplet states
C
               SBFHE1=(HEPHOT(1,0,3,FR)+3.*HEPHOT(1,1,3,FR)+
     *                5.*HEPHOT(1,2,3,FR)+
     *                3.*HEPHOT(3,0,3,FR)+9.*HEPHOT(3,1,3,FR)+
     *                15.*HEPHOT(3,2,3,FR))/36.
            ELSE
               CALL QUIT('inconsistent sbfhe1',ni,igi)
            END IF
         ELSE IF(NI.EQ.4) THEN
C
C ********    photoionization from an averaged level with n=4
C
            IF(IGI.EQ.16) THEN
C
C      a) lower level is an averaged singlet state
C
               SBFHE1=(HEPHOT(1,0,4,FR)+3.*HEPHOT(1,1,4,FR)+
     *                 5.*HEPHOT(1,2,4,FR)+
     *                 7.*HEPHOT(1,3,4,FR))/16.
            ELSE IF(IGI.EQ.48) THEN
C
C      b) lower level is an averaged triplet state
C
               SBFHE1=(HEPHOT(3,0,4,FR)+3.*HEPHOT(3,1,4,FR)+
     *                 5.*HEPHOT(3,2,4,FR)+
     *                 7.*HEPHOT(3,3,4,FR))/16.
            ELSE IF(IGI.EQ.64) THEN
C
C      c) lower level is an average of both singlet and triplet states
C
               SBFHE1=(HEPHOT(1,0,4,FR)+3.*HEPHOT(1,1,4,FR)+
     *                 5.*HEPHOT(1,2,4,FR)+
     *                 7.*HEPHOT(1,3,4,FR)+
     *                 3.*HEPHOT(3,0,4,FR)+
     *                 9.*HEPHOT(3,1,4,FR)+
     *                 15.*HEPHOT(3,2,4,FR)+
     *                 21.*HEPHOT(3,3,4,FR))/64.
            ELSE
               CALL QUIT('inconsistent sbfhe1',ni,igi)
            END IF
         ELSE
            CALL QUIT('inconsistent sbfhe1',ni,igi)
         END IF
      END IF
      RETURN

      CONTAINS


      REAL(DP) FUNCTION HEPHOT(S,L,N,FR)
C     ====================================
C
C           EVALUATES HE I PHOTOIONIZATION CROSS SECTION USING SEATON
C           FERNLEY'S CUBIC FITS TO THE OPACITY PROJECT CROSS SECTIONS
C           UP TO SOME ENERGY "EFITM" IN THE RESONANCE-FREE ZONE.  BEYOND
C           THIS ENERGY LINEAR FITS TO LOG SIGMA IN LOG (E/E0) ARE USED.
C           THIS EXTRAPOLATION SHOULD BE USED UP TO THE BEGINNING OF THE
C           RESONANCE ZONE "XMAX", BUT AT PRESENT IT IS USED THROUGH IT.
C           BY CHANGING A FEW LINES THAT ARE PRESENTLY COMMENTED OUT,
C           FOR ENERGIES IN THE RESONANCE ZONE A VALUE OF 1/100 OF THE
C           THRESHOLD CROSS SECTION IS USED -- THIS IS PURELY AD HOC AND
C           ONLY A TEMPORARY MEASURE.  OBVIOUSLY ANY OTHER VALUE OR FUNCTIONAL
C           FORM CAN BE INSERTED HERE.
C
C           CALLING SEQUENCE INCLUDES:
C                S = MULTIPLICITY, EITHER 1 OR 3
C                L = ANGULAR MOMENTUM, 0, 1, OR 2;
C                    for L > 2 - hydrogenic expresion
C                FR = FREQUENCY
C
C           DGH JUNE 1988 JILA,  modified by I.H.
C
      use accura
      implicit none

      REAL(DP), INTENT(IN) :: FR
      INTEGER, INTENT(IN)  :: S,L,N
      REAL(DP), PARAMETER :: TENM18=1.e-18, FRH=3.28805e15, TWO=2.0_dp,
     *           TENLG=2.302585093, PHOT0=2.815e29
      REAL(DP)            :: COEF(4,53),
     *                       FL0(53),A(53),B(53),XFITM(53)
      INTEGER :: IST(3,2),N0(3,2)

      REAL(DP) :: FL,X,P,GN
      INTEGER  :: I,K,LL,SS,J,NSL0
C
      DATA IST/1,36,20,11,45,28/
      DATA N0/1,2,3,2,2,3/
C
      DATA FL0/
     . 2.521e-01,-5.381e-01,-9.139e-01,-1.175e+00,-1.375e+00,-1.537e+00,
     .-1.674e+00,-1.792e+00,-1.896e+00,-1.989e+00,-4.555e-01,-8.622e-01,
     .-1.137e+00,-1.345e+00,-1.512e+00,-1.653e+00,-1.774e+00,-1.880e+00,
     .-1.974e+00,-9.538e-01,-1.204e+00,-1.398e+00,-1.556e+00,-1.690e+00,
     .-1.806e+00,-1.909e+00,-2.000e+00,-9.537e-01,-1.204e+00,-1.398e+00,
     .-1.556e+00,-1.690e+00,-1.806e+00,-1.909e+00,-2.000e+00,-6.065e-01,
     .-9.578e-01,-1.207e+00,-1.400e+00,-1.558e+00,-1.692e+00,-1.808e+00,
     .-1.910e+00,-2.002e+00,-5.749e-01,-9.352e-01,-1.190e+00,-1.386e+00,
     .-1.547e+00,-1.682e+00,-1.799e+00,-1.902e+00,-1.995e+00/
C
      DATA XFITM/
     . 3.262e-01, 6.135e-01, 9.233e-01, 8.438e-01, 1.020e+00, 1.169e+00,
     . 1.298e+00, 1.411e+00, 1.512e+00, 1.602e+00, 7.228e-01, 1.076e+00,
     . 1.206e+00, 1.404e+00, 1.481e+00, 1.464e+00, 1.581e+00, 1.685e+00,
     . 1.777e+00, 9.586e-01, 1.187e+00, 1.371e+00, 1.524e+00, 1.740e+00,
     . 1.854e+00, 1.955e+00, 2.046e+00, 9.585e-01, 1.041e+00, 1.371e+00,
     . 1.608e+00, 1.739e+00, 1.768e+00, 1.869e+00, 1.803e+00, 7.360e-01,
