      SUBROUTINE SPSIGK(IB,FR,SIGSP)
C     ==============================
C
C     Non-standard evaluation of the photoionization cross-sections
C     Basically user-suppled procedure; here are some examples
C
      use accura
      implicit none 

      REAL(DP),INTENT(IN)  :: FR
      REAL(DP),INTENT(OUT) :: SIGSP
      INTEGER, INTENT(IN)  :: IB
      REAL(DP), PARAMETER :: C1=3.,C2=9.,C3=1.6e1,T15=1.e-15,
     * A1=6.45105e-18,A2=3.02e-19,A3=9.9847e-18,A4=1.1763673e-17,
     * A5=3.63662e-19,A6=-2.783e2,A7=1.488e1,A8=-2.311e-1,
     * E1=3.5,E2=3.6,E3=1.91,E4=2.9,E5=3.3
      REAL(DP)            :: X,XX

      SIGSP=0.
C
C     Special formula for the He I ground state
C
      IF(IB.EQ.-201) SIGSP=7.3e-18*EXP(1.373-2.311e-16*FR)
C
C     Special formula for the averaged <n=2> level of He I
C
      IF(IB.EQ.-202) THEN
         X=FR*T15
         XX=LOG(FR)
         SIGSP=(C1*(A1/X**E1+A2/X**E2)+A3/X**E3+C2*(A4/X**E4+A5/X**E5)+
     *          C1*EXP(A6+XX*(A7+XX*A8)))/C3
      END IF
C
C     Carbon ground configuration levels 2p2 1D and 1S - outdated
C
!     IF(IB.EQ.-602.OR.IB.EQ.-603) THEN
!        CALL CARBON(IB,FR,SG)
!        SIGSP=SG
!     END IF
C
C     Hidalgo (Ap.J. 153, 981, 1968) photoionization data - outdated
C
!     IF(IB.LE.-101.AND.IB.GE.-137) SIGSP=HIDALG(IB,FR)
C
C     Reilman and Manson (Ap.J. Suppl. 40, 815, 1979) photoionization data
C     outdated
C
!     IF(IB.LE.-301.AND.IB.GE.-337) SIGSP=REIMAN(IB,FR)
      RETURN
      END SUBROUTINE SPSIGK


C
C     ***************************************************************
C
      REAL(DP) FUNCTION GNTK(I,FR)
C     ============================
C
C     Hydrogenic bound-free Gaunt factor for the principal quantum
C     number I and frequency FR (from Klaus Werner)
C
      use accura
      implicit none

      integer, intent(in) :: i
      real(dp),intent(in) :: fr
      real(dp)            :: y
      GNTK=1.
      Y=1./FR
      IF(I.EQ.1) THEN
         GNTK=0.9916+Y*(2.71852e13-Y*2.26846e30)
       ELSE IF(I.EQ.2) THEN
         GNTK=1.1050-Y*(2.37490e14-Y*4.07677e28)
       ELSE IF(I.EQ.3) THEN
         GNTK=1.1010-Y*(0.98632e14-Y*1.03540e28)
      END IF
      END FUNCTION GNTK
C
C
C
C     ******************************************************************
C
C
      REAL(DP) FUNCTION YLINTP(XINT,X,Y,N,NTOT)
C     =========================================
C
C     linear interpolation routine. Determines YINT = Y(XINT) from
C     grid Y(X) with N points and dimension NTOT.
C
      use accura
      implicit none 

      INTEGER, INTENT(IN)  :: N,NTOT
      REAL(DP), INTENT(IN) :: X(NTOT),Y(NTOT),XINT
      INTEGER              :: JU,JL,JM,J
      REAL(DP)             :: RC
C
C     bisection (see Numerical Recipes par 3.4 page 90)
      JL = 0
      JU = N+1
      DO WHILE (JU-JL.GT.1)
         JM = (JU+JL)/2
         IF ((X(N).GT.X(1)).EQV.(XINT.GT.X(JM))) THEN
            JL = JM
         ELSE
            JU = JM
         END IF
      END DO
      J = JL
      IF (J.EQ.N) J = J-1
      IF (J.EQ.0) J = J+1
CM42 version: enable extrapolation
C
      RC         = (Y(J+1)-Y(J))/(X(J+1)-X(J))
      YLINTP = RC*(XINT-X(J))+Y(J)
C
      RETURN
      END FUNCTION YLINTP
