C
C
      REAL(DP) FUNCTION TOPBAS(FREQ,FREQ0,TYPLV)
C     ==========================================
C
C     Procedure calculates the photo-ionisation cross section SIGMA in
C     [cm^2] at frequency FREQ. FREQ0 is the threshold frequency from
C     level I of ion KI. Threshold cross-sections will be of the order
C     of the numerical value of 10^-18.
C     Opacity-Project (OP) interpolation fit formula
C
      use accura
      use topbase
      implicit none

      REAL(DP), PARAMETER :: E10=2.3025851
      CHARACTER(LEN=10)   :: TYPLV
      REAL(DP), INTENT(IN) :: FREQ,FREQ0 
      REAL(DP) :: X,SIGM,YLINTP
      INTEGER  :: IOP,IFIT 
CC    ALLOCATE (XFIT(MOP) ,! local array containing x     for OP data
CC   +          SFIT(MOP)) ! local array containing sigma for OP data
C
      TOPBAS=0.
C
C     Read OP data if not yet done
C
      IF (.NOT.LOPREA) CALL OPDATA
      X = LOG10(FREQ/FREQ0)
      DO IOP = 1,NTOTOP
         IF (IDLVOP(IOP).NE.TYPLV) CYCLE
C        level has been detected in OP-data file
         IF (NOP(IOP).LE.0) THEN
C           Level is not found ,or no data for this level, in RBF.DAT
            WRITE(6,"('SIGMA OP DATA NOT AVAILABLE FOR LEVEL ',A10)")
     *               TYPLV
            EXIT
         END IF
         DO IFIT = 1,NOP(IOP)
            XFIT(IFIT) = XOP(IFIT,IOP)
            SFIT(IFIT) = SOP(IFIT,IOP)
         END DO
         SIGM  = YLINTP(X,XFIT,SFIT,NOP(IOP),MOP)
         SIGM  = 1.e-18*EXP(E10*SIGM)
         TOPBAS=SIGM
      END DO
      RETURN
      END FUNCTION TOPBAS
C
C
C     ****************************************************************
C
C

      SUBROUTINE OPDATA
C     =================
C
C     Procedure reads photo-ionization cross sections fit coefficients
C     based on Opacity-Project (OP) data from file RBF.DAT
C     Data, as stored, requires linear interpolation.
C
C     Meaning of global variables:
C        NTOTOP    = total number of levels in Opacity Project data
C        IDLVOP() = level identifyer of current level
C        NOP()     = number of fit points for current level
C        XOP(,)    = x     = alog10(nu/nu0)       of fit point
C        SOP(,)    = sigma = alog10(sigma/10^-18) of fit point
C
      use accura
      use topbase
      implicit none

      CHARACTER(LEN=4) ::  IONID
      INTEGER          :: IREAD,IOP,IEOP,NEOP,IIOP,NIOP,ILOP,IS,
     *                    IATOM_OP,IELEC_OP,NLEVEL_OP,INDEX

CC    ALLOCATE (SOP(MOP,MMAXOP) ,! sigma = alog10(sigma/10^-18) of fit point
CC   +          XOP(MOP,MMAXOP)) ! x = alog10(nu/nu0) of fit point
CC    ALLOCATE (NOP(MMAXOP))     ! number of fit points for current level
C
      OPEN (UNIT=40,FILE='RBF.DAT',STATUS='OLD')
C     Skip header
      DO IREAD = 1, 21
         READ (40,*)
      END DO
      IOP = 0
C         = initialize sequential level index op Opacity Project data
C     Read number of elements in file
      READ (40,*) NEOP
      DO IEOP = 1, NEOP
C        Skip element name header
         DO IREAD = 1, 3
            READ (40,*)
         END DO
C        Read number of ionization stages of current element in  file
         READ (40,*) NIOP
         DO IIOP = 1, NIOP
C           Read ion identifyer, atomic & electron number, # of levels
C           for current ion
            READ (40,*) IONID, IATOM_OP, IELEC_OP, NLEVEL_OP
            DO ILOP = 1, NLEVEL_OP
C              Increase sequential level index of Opacity Project data
               IOP = IOP+1
C              Read level identifyer and number of sigma fit points
               READ (40,*) IDLVOP(IOP), NOP(IOP)
C              Read normalized log10 frequency and log10 cross section values
               DO IS = 1, NOP(IOP)
                  READ (40,*) INDEX, XOP(IS,IOP), SOP(IS,IOP)
               END DO
            END DO
         END DO
      END DO
      NTOTOP  = IOP
C             = total number of levels in Opacity Project data
      LOPREA  = .TRUE.
C             = set flag as data has been read in
C
      RETURN
      END SUBROUTINE OPDATA

C
C     ****************************************************************
C
C

      SUBROUTINE OPADD0(IJ)
C     ======================
C
C     setting cross secxtion for ondividual addiaopnal opacity sources
c
      use accura
      use atomic
      use basics
      use modelq
      
      implicit none
C
      REAL(DP), PARAMETER :: FRRAY =  2.463e15_dp,
     *                       FRAYHe=  5.150e15_dp,
     *                       FRAYH2=  2.922e15_dp,
     *                       CLS   =  2.997925e18_dp,
     *                       CR0   =  5.799e-13_dp,
     *                       CR1   =  1.422e-6_dp,
     *                       CR2   =  2.784_dp

      REAL(DP) :: FR,FRM,X,X2,CS,SBFHMI,AL
      INTEGER, INTENT(IN) :: IJ
      INTEGER  :: IT
      LOGICAL  :: LPRI
C
      FR=FREQ(IJ)
      AL=2.997925E18/FR
      IF(ISPODF.GE.1) FR=FREQ(IFREQB(IJ))
      if(teff.gt.50000.) iophem=0

      lpri=jik(ij).eq.660
      lpri=al.gt.1520..and.al.lt.1530.
      lpri=.false.
c
      IT=NCON
      if(ij.eq.1) write(*,*) 'opadd0 it,mcross',it,mcross,mfreqc
C
C     -----------------------
C     HI  Rayleigh scattering
C     -----------------------
C
      IF(IRSCT.NE.0) THEN
         IT=IT+1
         if(it.gt.mcross)
     *      CALL QUIT('it.gt.mcross in opadd',it,mcross)
         FRM=MIN(FR,FRRAY)
         X=(CLS/FRM)**2
         BFCS(IT,IJ)=(CR0+(CR1+CR2/X)/X)/X/X
         if(lpri) write(*,*) 'Hraysc it',it,bfcs(it,ij)
      END IF
C
C     -----------------------
C     He I  Rayleigh scattering
C     -----------------------
C
      IF(IRSCHE.NE.0) THEN
         IT=IT+1
         if(it.gt.mcross)
     *      CALL QUIT('it.gt.mcross in opadd',it,mcross)
         X=(CLS/MIN(FR,FRAYHe))**2
         CS=5.484E-14_dp/X/X*(1.+(2.44E5_dp+5.94E10_dp/
     *      (X-2.90E5_dp))/X)**2
         if(fr.gt.8.e14_dp) cs=0.
         BFCS(IT,IJ)=CS
         if(lpri) write(*,*) 'Heraysc it',it,bfcs(it,ij)
      END IF
C
C   -----------------------
C   H2  Rayleigh scattering
C   -----------------------
C
      IF(IRSCH2.NE.0.AND.IFMOL.GT.0) THEN
         IT=IT+1
         if(it.gt.mcross)
     *      CALL QUIT('it.gt.mcross in opadd',it,mcross)
         X=(CLS/MIN(FR,FRAYH2))**2
         X2=UN/X/X
         CS=(8.14E-13_dp+1.28E-6_dp/X+1.61_dp*X2)*X2
         BFCS(IT,IJ)=CS
         if(lpri) write(*,*) 'H2raysc it',it,bfcs(it,ij)
      END IF
C
C     ----------------------------
C     H-  bound-free and free-free
C     ----------------------------
C
      IF(IOPHMI.GT.0) THEN
         IT=IT+1
         if(it.gt.mcross)
     *      CALL QUIT('it.gt.mcross in opadd',it,mcross)
         BFCS(IT,IJ)=SBFHMI(FR)
         if(lpri) write(*,*) 'H- it',it,bfcs(it,ij)
      END IF
C
C     -----------------------------
C     H2+  bound-free and free-free
C     -----------------------------
C
      IF(IOPH2P.GT.0) THEN
         IT=IT+1
         if(it+1.gt.mcross)
     *      CALL QUIT('it.gt.mcross in opadd',it,mcross)
         X=FR*1.e-15
         BFCS(IT,IJ)=(-7.342e-3_dp+(-2.409_dp+(1.028_dp+(-0.423_dp+
     *        (0.1224_dp-1.351e-2_dp*X)*X)*X)*X)*X)*1.602e-12_dp/BOLK
         if(ij.eq.1165) write(*,*) 'H2P it',it,BFCS(IT,IJ)
         IT=IT+1
         X=LOG(FR)
         CS=-3.0233e3_dp+(3.7797e2_dp+(-1.82496e1_dp+(0.39207_dp-
     *        3.1672e-3_dp*X)*X)*X)*X
         BFCS(IT,IJ)=cs
         if(lpri) write(*,*) 'H2P it',it,bfcs(it,ij)
      END IF
C
C     -----------------------------
C     He-  free-free
C     -----------------------------
C
      IF(IOPHEM.GT.0) THEN
         IT=IT+1
         if(it+2.gt.mcross)
     *      CALL QUIT('it.gt.mcross in opadd',it,mcross)
         BFCS(IT,IJ)=3.397e-46_dp+(-5.216e-31_dp+7.039e-15_dp/FR)/FR
         BFCS(IT+1,IJ)=-4.116e-42_dp+(1.067e-26_dp+8.135e-11_dp/FR)/FR
         BFCS(IT+2,IJ)=5.081e-37_dp+(-8.724e-23_dp-5.659e-8_dp/FR)/FR
         if(lpri) then
          write(*,*) 'He-ff it',it,bfcs(it,ij)
          write(*,*) 'He-ff it',it+1,bfcs(it+1,ij)
          write(*,*) 'He-ff it',it+2,bfcs(it+2,ij)
         end if
      END IF
C
      RETURN
      END SUBROUTINE OPADD0
C
C     ****************************************************************
C
C

      SUBROUTINE OPAHST
C     =================
C
C     Auxiliary routine for START
C     sets up necessary parameters for routines OPAHYL and OPHYL1, i.e.
C     for opacity and emissivity in higher hydrogen lines
C     Also sets up Stark parameters for OPAHYL
C
      use accura
      use basics
      use hydodf
      implicit none

      INTEGER  :: ILOW,IOS,ISET,IU1,IL1,IM1,IP1,IUP1,IZZH,I1,I2,J,I
      
      ALLOCATE (M1FILE(NLMX,MHOD),M2FILE(NLMX,MHOD))

C
      ALLIM1=1450.
      ABLIM1=6650.
      ABLIM2=5000.
      ABLIM3=6500.
C
C     Lyman lines
C
      ILOW=1
      IF(IABS(IOPHL1).EQ.1) IOPHL2=IOPHL2*2
      DO I=1,4
         M1FILE(I,ILOW)=MAX(I,IABS(IOPHL1))
         M2FILE(I,ILOW)=I+1
      END DO
      DO I=5,NLMX
         M1FILE(I,ILOW)=MAX(I-1,IABS(IOPHL1))
         M2FILE(I,ILOW)=MIN(I+3,NLMX)
      END DO
      M1FILE(NLMX,ILOW)=NLMX+1
      M2FILE(NLMX,ILOW)=NLMX
C
      IF(IABS(IOPHL1).GT.100) THEN
         IOPHL1=MOD(IOPHL1,100)
         ISET=0
         IU1=0
         DO WHILE (IU1.LT.NLMX)
            READ(IBUFF,*,IOSTAT=IOS) IL1,IU1,IM1,IP1
            IF(IOS.EQ.0) THEN
               EXIT
             ELSE
               ISET=ISET+1
               IF(IL1.LE.0.AND.ISET.EQ.1) THEN
                  IL1=1
                  IU1=4
                  IM1=0
                  IP1=1
               END IF
               IF(IL1.LE.0.AND.ISET.EQ.2) THEN
                  IL1=5
                  IU1=NLMX
                  IM1=1
                  IP1=3
               END IF
               IUP1=MIN(IU1,NLMX)
               DO I=IL1,IUP1
                  M1FILE(I,ILOW)=MAX(I-IM1,IABS(IOPHL1))
                  M2FILE(I,ILOW)=MIN(I+IP1,NLMX)
               END DO
            END IF
         END DO
         READ(IBUFF,*,IOSTAT=IOS) ALLIM1
         IF(IOS.EQ.0.AND.ALLIM1.LE.0) ALLIM1=1450.
      END IF
      M1FILE(NLMX,ILOW)=NLMX+1
      M2FILE(NLMX,ILOW)=NLMX
C
C     Balmer lines
C
      ILOW=2
      IF(IABS(IOPHL2).EQ.1) IOPHL2=IOPHL2*3
      IF(IABS(IOPHL2).EQ.2) IOPHL2=IOPHL2*3/2
      DO I=1,6
         M1FILE(I,ILOW)=MAX(I,IABS(IOPHL2))
         M2FILE(I,ILOW)=I+1
      END DO
      DO I=7,NLMX
         M1FILE(I,ILOW)=MAX(I-1,IABS(IOPHL2))
         M2FILE(I,ILOW)=MIN(I+3,NLMX)
      END DO
      IF(IABS(IOPHL2).GT.100) THEN
         IOPHL2=MOD(IOPHL2,100)
         ISET=0
         IU1=0
         DO WHILE(IU1.LT.NLMX)
            READ(IBUFF,*,IOSTAT=IOS) IL1,IU1,IM1,IP1
            IF(IOS.NE.0) THEN
               EXIT
             ELSE
               ISET=ISET+1
               IF(IL1.LE.0.AND.ISET.EQ.1) THEN
                  IL1=1
                  IU1=6
                  IM1=0
                  IP1=1
               END IF
               IF(IL1.LE.0.AND.ISET.EQ.2) THEN
                  IL1=7
                  IU1=NLMX
                  IM1=1
                  IP1=3
               END IF
               IUP1=MIN(IU1,NLMX)
               DO I=IL1,IUP1
                  M1FILE(I,ILOW)=MAX(I-IM1,IABS(IOPHL2))
                  M2FILE(I,ILOW)=MIN(I+IP1,NLMX)
               END DO
            END IF                  
            READ(IBUFF,*,IOSTAT=IOS) ABLIM1,ABLIM2,ABLIM3
            IF(IOS.EQ.0) THEN
               IF(ABLIM1.LE.0) ABLIM1=6650.
               IF(ABLIM2.LE.0) ABLIM2=5000.
               IF(ABLIM3.LE.0) ABLIM3=6500.
            END IF
         END DO
      END IF
      M1FILE(NLMX,ILOW)=NLMX+1
      M2FILE(NLMX,ILOW)=NLMX
c
C    -------------------
C    Stark paramereters
C    -------------------
C
      izzh=1
      IF(IOPHL1.NE.0) THEN
         I=1
         I1=MAX(2,IABS(IOPHL1))
         DO J=I1,NLMX
            CALL STARK0(I,J,izzh,XKIJ(I,J),WL0(I,J),FIJ(I,J))
         END DO
      END IF
      IF(IOPHL2.NE.0) THEN
         I=2
         I2=MAX(3,IABS(IOPHL2))
         DO J=I2,NLMX
            CALL STARK0(I,J,izzh,XKIJ(I,J),WL0(I,J),FIJ(I,J))
         END DO
      END IF
      RETURN
      END SUBROUTINE OPAHST

C
C     ****************************************************************
C
C

      SUBROUTINE STARK0(I,J,IZZ,XKIJ,WL0,FIJ)
C     =======================================
C
C     Auxiliary procedure for evaluating the approximate Stark profile
C     of hydrogen lines - sets up necessary frequency independent
C     parameters
C
C     Input:  I     - principal quantum number of the lower level
C             J     - principal quantum number of the upper level
C             IZZ   - ionic charge (IZZ=1 for hydrogen, etc.)
C     Output: XKIJ  - coefficients K(i,j) for the Hotzmark profile;
C                     exact up to j=6, asymptotic for higher j
C             WL0   - wavelength of the line i-j
C             FIJ   - Stark f-value for the line i-j
C
      use accura
      implicit none

      REAL(DP),PARAMETER :: RYD1=911.763811,RYD2=911.495745/4.,
     *                      CXKIJ=5.5E-5,WI1=911.753578,WI2=227.837832,
     *                      UN=1.,TEN=10.,TWEN=20.,HUND=100.
      REAL(DP) ::  FSTARK(10,4),XKIJT(5,4)
      REAL(DP), INTENT(OUT) :: XKIJ,WL0,FIJ
      INTEGER,INTENT(IN)    :: I,J,IZZ
      REAL(DP)              :: ZZ,CFIJ
      INTEGER               :: II,JJ,JMIN

      DATA XKIJT/3.56e-4,5.23e-4,1.09e-3,1.49e-3,2.25e-3,.0125,.0177,
     * .028,.0348,.0493,.124,.171,.223,.261,.342,.683,.866,1.02,1.19,
     * 1.46/
      DATA FSTARK/.1387,.0791,.02126,.01394,.00642,4.814e-3,2.779e-3,
     * 2.216e-3,1.443e-3,1.201e-3,.3921,.1193,.03766,.02209,.01139,
     * 8.036e-3,5.007e-3,3.85e-3,2.658e-3,2.151e-3,.6103,.1506,.04931,
     * .02768,.01485,.01023,6.588e-3,4.996e-3,3.524e-3,2.838e-3,.8163,
     * .1788,.05985,.03189,.01762,.01196,7.825e-3,5.882e-3,4.233e-3,
     * 3.375e-3/
C
      II=I*I
      JJ=J*J
      JMIN=J-I
      IF(JMIN.LE.5) THEN
         XKIJ=XKIJT(JMIN,I)
      ELSE
         XKIJ=CXKIJ*(II*JJ)*(II*JJ)/(JJ-II)
      END IF
C
C     proper scaling with Z
C
      zz=float(izz)
      xkij=xkij/ZZ**5
c
      IF(JMIN.LE.10) THEN
         FIJ=FSTARK(JMIN,I)
      ELSE
         CFIJ=((TWEN*I+HUND)*J/(I+TEN)/(JJ-II))
         FIJ=FSTARK(10,I)*CFIJ*CFIJ*CFIJ
      END IF

      WL0=WI1
      IF(IZZ.EQ.2) WL0=WI2
      if(izz.gt.2) wl0=wi1/float(izz)**2
      WL0=WL0/(UN/FLOAT(II)-UN/FLOAT(JJ))
      RETURN
      END

C
C    *****************************************************************
C
C
      SUBROUTINE ITERINI
C     ==================
C
      use accura
      use basics
      use iterat
      use atomic

      implicit none

      INTEGER  :: NNGG,IKT,I,ION,N0G,NKE,NKG,N0,IJ,ITL
C
C --------------------------------------------------------------------
C Parameters specifying the overall organization and structure of the
C global matrices of complete linearization
C --------------------------------------------------------------------
C
      if(hmix0.gt.0..and.iconv.eq.0) iconv=1
      IF(HMIX0.GT.0.and.inpc.gt.0.and.inse.gt.0) THEN
         INDL  = 3
         INPC  = 4
         INSE  = 5
         INZD  = 0
      END IF
c
      if(ifryb.gt.0) then
         inhe=0
         inre=1
         indl=0
         inpc=0
         inmp=0
         inse=0
         inzd=0
         do ij=1,nfreq
            ijali(ij)=0
         end do
      end if
c
      nn=nfreqe
      if(inhe.gt.0) nn=nn+1
      if(inre.gt.0) nn=nn+1
      if(inpc.gt.0) nn=nn+1
      if(inmp.gt.0) nn=nn+1
      if(indl.gt.0) nn=nn+1
      if(inzd.gt.0) nn=nn+1
      nngg=nn
      if(inse.gt.0) nn=nn+NLVEXP
      LCHMAT=.FALSE.

      MTOT=NN
      write(*,*) 'MTOT =',mtot

      ALLOCATE (ISNG(MTOT))
c
C     change LCHC and IRSPLT in case that INPC=0
C
      IF(INPC.EQ.0) THEN
         IRSPLT=1
         LCHC=.TRUE.
      END IF
C
C --------------------------------------------------------------------
C Acceleration parameters
C --------------------------------------------------------------------
C
C     if ITEK > 0, full iteration after Ng accelerations
C             < 0, only first ITEK iterations are full iterations;
C              KANT=0  - signifies a full complete linearization iteration;
C              KANT=1  - a Kantorovich iteration
C
      write(*,*) 'itek,niter',itek,niter
      DO IKT=1,NITER
         KANT(IKT)=0
      END DO
      IF(ORELAX.EQ.0.) ORELAX=UN
      IACC0=IACC-3
      LAC2=.FALSE.
      LRES2=.TRUE.
      IF(ITEK.GT.0) THEN
         DO IKT=ITEK+1,NITER
            KANT(IKT)=1
         END DO
         DO IKT=IACC,18,IACD
             KANT(IKT)=0
         END DO
       ELSE IF(ITEK.LT.0) THEN
         ITEK=ABS(ITEK)
         DO IKT=ITEK+1,NITER
            KANT(IKT)=1
         END DO
      END IF
C
      DO ITL=1,NITER+1
          NITLAM(ITL)=0
      END DO
      IF(NLAMBD.LT.0) THEN
         NLAMBD=-NLAMBD
         IF(LTE) NLAMBD=1
         DO ITL=1,12
            NITLAM(ITL)=NLAMBD
         END DO
         DO ITL=13,NITER+1
            NITLAM(ITL)=2
         END DO
       ELSE IF(NLAMBD.GT.0) THEN
         IF(LTE) NLAMBD=1
          DO ITL=1,NITER+1
             NITLAM(ITL)=NLAMBD
!            write(*,*) 'itl,nitlam',itl,nitlam(itl)
         END DO
      END IF
C
      write(*,*) 'ksng,nn',ksng,nn
      write(*,*) 'nfreqe,inhe,inre,inpc,inmp,indl',
     * nfreqe,inhe,inre,inpc,inmp,indl
      IF(KSNG.EQ.0) THEN
         DO I=1,NN
           ISNG(I)=1     
         END DO
       ELSE
         DO I=1,NN
           ISNG(I)=0 
         END DO
      END IF
      IF(KSNG.EQ.1) THEN
         DO I=1,NFREQE
            ISNG(I)=1     
         END DO
         IF(INSE.GT.0) THEN
            DO ION=1,NION
               N0=NFIRST(ION)
               N0G=NNGG+ABS(IIEXP(N0))
               ISNG(N0G)=1     
               NKE=NNEXT(ION)
               NKG=NNGG+ABS(IIEXP(NKE))
               ISNG(NKG)=1     
            END DO
         END IF
      END IF
      IF(INHE.GT.0) ISNG(NFREQE+INHE)=1     
      IF(INRE.GT.0) ISNG(NFREQE+INRE)=1     
      IF(INPC.GT.0) ISNG(NFREQE+INPC)=1     
      IF(INMP.GT.0) ISNG(NFREQE+INMP)=1     
      IF(INDL.GT.0) ISNG(NFREQE+INDL)=1     

c     write(*,*) 'ISNG',isng

      RETURN
      END SUBROUTINE  ITERINI
C
C
C    *****************************************************************
C
C
      SUBROUTINE IRRAD
!     ================
!
      use accura
      use basics
      use modelq

      implicit none

      REAL(DP), ALLOCATABLE :: FST(:),EXTRD0(:)
      REAL(DP) :: EXTOT0
      INTEGER  :: IJ,IMU,NFREQ0

      ALLOCATE (EXTRAD(MFREQ),HEXTRD(MFREQ),EXTINT(MFREQ,MMU))
      ALLOCATE (FST(MFREQ),EXTRD0(MFREQ))
C
C ------------------------------------
C External irradiation intensity
C ------------------------------------
C
      if(wdil.le.0..and.adist.gt.0.)
     *   wdil=4.*(rstar/adist)**2
      EXTOT=0.

      IF(TRAD.EQ.0) THEN
         DO IJ=1,NFREQ
            EXTRAD(IJ)=0.
            HEXTRD(IJ)=0.
         END DO
       ELSE IF(TRAD.GT.0) THEN
         DO IJ=1,NFREQ
            EXTRAD(IJ)=BNUE(IJ)/(EXP(HK*FREQ(IJ)/TRAD)-UN)*WDIL
            EXTOT=EXTOT+W(IJ)*EXTRAD(IJ)
         END DO
       ELSE
         open(48,file='stellarspectrum.dat',status='old')
         nfreq0=-ifix(real(trad))
         DO IJ=NFREQ0,1,-1
            read(48,*) fst(ij), EXTRD0(IJ)
         end do
         close(48)
         call interp(fst,extrd0,freq,extrad,nfreq0,nfreq,2,0,0)
         DO IJ=1,NFREQ
            EXTRAD(IJ)=EXTRAD(IJ)*WDIL
            EXTOT=EXTOT+W(IJ)*EXTRAD(IJ)
         END DO
      END IF
      DO IJ=1,NFREQ
         DO IMU=1,NMU
            EXTINT(IJ,IMU)=EXTRAD(IJ)
         END DO
         HEXTRD(IJ)=HALF*EXTRAD(IJ)
      END DO
      TSTAR=TRAD
      EXTOT=EXTOT/SIG4P/4.
      EXTOT0=WDIL*TRAD*TRAD*TRAD*TRAD
      write(6,"(/' EXTERNAL IRRADIATION - EXTOT0,EXTOT: ',1p2e12.3/)")
     *      extot0,extot

      DEALLOCATE (FST,EXTRD0)
      RETURN
      END SUBROUTINE IRRAD
C
C
C     ****************************************************************
C
C
      SUBROUTINE PRDINI
c     =================
c
c     initialization of PRD
c
      use accura
      use atomic
      use basics
C     use modelq
C     use pfrpar

      implicit none
c
      INTEGER  :: ITR,II,JJ,IAT,ITRP,ID

      IF(IFPRD.LE.0) RETURN

      ALLOCATE (DOPTR(MTRPRD,MDEPTH),COHER(MTRPRD,MDEPTH),
     *         PJBAR(MTRPRD,MDEPTH),RJBAR(MTRPRD,MDEPTH))
      ALLOCATE (IPRD(MTRANS),ITRTOT(MTRPRD))

      ntrprd=0
      do itr=1,ntrans
         iprd(itr)=0
         if(ifprd.gt.0.and.line(itr).and.indexp(itr).ne.0) then
         ii=ilow(itr)
         jj=iup(itr)
         iat=iatm(ii)
c
c        select Lyman alpha for PRD
c
         if(iat.eq.iath.and.ii.eq.nfirst(ielh).and.
     *      fr0(itr).lt.2.5e15) then
            ntrprd=ntrprd+1
            iprd(itr)=ntrprd
            itrtot(ntrprd)=itr
         end if
c
c        select Mg I resonance line for PRD
c
         if(numat(iat).eq.12.and.iz(iel(ii)).eq.1.and.
     *      ii.eq.nfirst(iel(ii)).and.fr0(itr).lt.1.06e15) then
            ntrprd=ntrprd+1
            iprd(itr)=ntrprd
            itrtot(ntrprd)=itr
         end if
c
c        select Mg II resonance lines for PRD
c
         if(numat(iat).eq.12.and.iz(iel(ii)).eq.2.and.
     *      ii.eq.nfirst(iel(ii)).and.fr0(itr).lt.1.08e15) then
            ntrprd=ntrprd+1
            iprd(itr)=ntrprd
            itrtot(ntrprd)=itr
         end if
         end if
      end do
c
      do itrp=1,ntrprd
         do id=1,nd
            pjbar(itrp,id)=0.
         end do
      end do
      return
      end

C
C
C     ****************************************************************
C
C
C

      SUBROUTINE RESOLV
C     =================
C
C     Control procedure for the formal solution, i.e. all calculations
C     between two consecutive iterations of complete linearization
C
      use accura
      use alipar
      use array1
      use atomic
      use basics
      use iterat
      use modelq

      implicit none 

      REAL(DP) :: PGR(MLVEXP)
      INTEGER  :: IJ,ID,ICONRF,I,II,III
C
C     Initialization - procedure INILAM:
C
      ifratp=0
      ilam=0
      write(*,*) 'before inilam'
      CALL INILAM
!     write(*,*) 'after inilam'
      if(ioptab.lt.0.or.ioptab.gt.0) call rayset
!     write(*,*) 'after rayset'
      if(ifprd.gt.0) call prd(0)
!     write(*,*) 'after prd'
!     write(*,*) 'shape nitlam',shape(nitlam)
CC    NLAMBD=NITLAM(ITER)

c     IF(NLAMBD.LE.0) GO TO 80
      IF(LFIN.AND.NITER.GT.0) NLAMBD=1
      LAC2P=.FALSE.
      IACC0P=IACPP-3
C
C     solution of the transfer equation with Compton scattering
C
      if(icompt.ne.0.and.iter.eq.1) then
         CALL OPAINI(1)
         ilam=0
         do ij=1,nfreq
            call opacf1(ij)
            call rtefr1(ij)
         end do
CC       CALL RTECOM
      end if
C
      IF(ITER.LE.1.and.ioptab.eq.0) CALL LINSEL
!      write(*,*) 'after linsel'

c      id=2
c      write(6,"('/POPUL before lambda',i4,1p6e12.4)")
c    * ilam,elec(id),dens(id),wmm(id),popul(1,id),popul(17,id),pgs(id)

C
C     Set of NLAMBD procedures, called overall "lambda" iterations
C     (not to be confused with ordinary lambda iterations)
C     Each "lambda" iteration contains:
C

!     write(*,*) 'NTRANS',ntrans

      do i=1,ntrans
!        write(*,*) 'i',i
!        write(*,*) 'line(i)',line(i)
!        write(*,*) 'indexp(i)',indexp(i)
!        write(*,*) 'ifr0,ifr1',ifr0(i),ifr1(i)
         if(.not.line(i).or.indexp(i).eq.0) cycle
c        write(41,"(4i5,2i6,3f12.3)") i,ilow(i),iup(i),iprof(i), 
c    *   ifr0(i),ifr1(i),
c    *   cas/fr0(i),cas/freq(ifr0(i)),cas/freq(ifr1(i))

!        write(*,*) 'ilow',ilow(i)
!        write(*,*) 'iup',iup(i)
!        write(*,*) 'iprof',iprof(i)
!        write(*,*) 'fr0',fr0(i)
!        write(*,*) 'freq0',freq(ifr0(i))
!        write(*,*) 'freq1',freq(ifr1(i))

!        write(6,"(4i5,2i6,3f12.3)") i,ilow(i),iup(i),iprof(i), 
!    *   ifr0(i),ifr1(i),
!    *   cas/fr0(i),cas/freq(ifr0(i)),cas/freq(ifr1(i))
      end do

!     do ij=1,nfreq
!        write(40,"(i9,f15.3,2i6,2x,1p4e12.4)") 
!    *   ij,cas/freq(ij),nlines(ij),ijlin(ij),
!    *   prflin(1,ij),prflin(10,ij),prflin(40,ij),prflin(70,ij)
!     end do

      DO ILAM=1,NLAMBD
!        write(*,*) 'ilam',ilam
         CALL OPAINI(1)
!        write(*,*) 'after opaini in ilam',ilam
CC       if(icompt.ne.0.and.ilam.gt.1) CALL RTECOM
C
C        Radiative rates in all transitions, in all depths
C
         IF(IFPREC.EQ.0) THEN
            CALL RATES1(0)
          ELSE
            CALL RATSP1
         END IF
!        write(*,*) 'after ratsp1i in ilam',ilam
c        write(6,"(1p20e9.1)") (rru(i,1),i=1,ntrans,1)
c        write(6,"(1p20e9.1)") (rrd(i,1),i=1,ntrans,1)
c        write(6,"(1p20e9.1)") (colrat(i,1),i=1,ntrans,1)
c        write(6,"(1p20e9.1)") (coltar(i,1),i=1,ntrans,1)
c
CC       call prd(0)
C
C ****** evaluation of the new populations,
C        using all the previously calculated radiative rates
C
          ifratp=0
          if(ilam.eq.nlambd) ifratp=1
         DO ID=1,ND
c           write(*,*) 'ilam,id',ilam,id
c           CALL STEQEQ(ID,POP,0)
            CALL STEQEQ(ID,POP,1)
c          write(*,*) 'after steqeq in id',id
c          if(id.eq.39) write(6,"(1p10e12.3)") (pop(i),i=1,nlevel)
            CALL NEWPOP(ID,POP)
CC          IF(.NOT.LCHC.and.iter.lt.ielcor) CALL ELCOR(ID)
c          if(id.eq.2) write(6,"('/POPUL in lambda',i4,1p6e12.4)")
c    * ilam,elec(id),dens(id),wmm(id),popul(1,id),popul(17,id),pgs(id)
         END DO
!        write(*,*) 'after newpop in ilam',ilam
C
CC       if(iprind.eq.2) call output
C
C ****** acceleration of convergence (if required)
C
         IF(IACPP.GT.0) THEN
CC          CALL ACCELP
         END IF
C
C        mesh refinement, if needed
C
CC       if(iter.le.4) CALL MREFIN
CC       nnewd.gt.0.and.(iter.le.4.or.mod(iter,5).eq.1)) CALL MREFIN
C
      END DO
       ifratp=0
C
!     write(*,*) 'elec5',elec(1),elec(nd)
      IF(ITER.EQ.1.OR.LFIN) CALL ROSSTD(0)
C
      CALL OUTPUT
!      write(*,*) 'after output'

c     stop

C
C     in case of convection is considered: call pzeval to evaluate pressures
C     and the logarithmic gradient of the total pressure
C
      if(iter.le.nitzer) call pzert
C
      if((iheso6.ne.0.or.HMIX0.GT.0.).and.init.eq.1) CALL PZEVAL
      write(*,*) 'elec7',elec(1),elec(nd)

      call radpre

CC    if(iter.le.1) call qqexpl
CC    CALL TIMING(1,ITER)
c
c     call prnt

      write(*,*) 'HMIX0',hmix0

      if(hmix0.eq.0.) then
         write(6,"(/'**  CONVECTIVE FLUX: RESOLV; GLOBAL ITERATION =',
     *   I3/)") iter-1
         call conout(1,ipconf)
       else if(hmix0.gt.0.) then
         call conref
         IF(ipconf.gt.0.or.(ipconf.eq.0.and.lfin)) then
            WRITE(6,"(/'* CONVECTIVE FLUX: RESOLV; GLOBAL ITERATION =',
     *      I3/)") ITER-1
            CALL CONOUT(1,1)
         END IF
      end if

       id=2
c      write(6,"('/POPUL after conrefs',i4,1p5e12.4)")
c    * ilam,elec(id),dens(id),wmm(id),popul(1,id),popul(17,id)


C
C     evaluate necessary ALI aprameters
C
C
CCCCCCCCCCCCCCCCCC test change
c
         if(irbefa.eq.0) then
           CALL OPAINI(0)
         else
           CALL OPAINI(1)
           call rates1(0)
        end if

c       write(*,*) 'after irbefa, rates',irbefa,iter
c       write(*,*) 'KANT(TER),lfin',kant(iter),iter,lfin

       id=2
c      write(6,"('/POPUL before alist',i4,1p5e12.4)")
c    * ilam,elec(id),dens(id),wmm(id),popul(1,id),popul(17,id)

CC      if(icompt.ne.0.and.ilam.gt.1) CALL RTECOM
        IF(KANT(ITER).EQ.1.OR.LFIN) THEN
           CALL ALISK2
         ELSE
           IF(IRDER.EQ.0) THEN
              CALL ALIST1
            ELSE
              CALL ALIST2
           END IF
        END IF
c       write(*,*) 'after alist2'
c
C     if IFPOPR=2 - evaluate new populations
C
CCCCCCCCCCCCCCCCCC test change
c
      if(ifpopr.eq.2) then
         DO ID=1,ND
            CALL STEQEQ(ID,POP,1)
            IF(.NOT.LCHC.and.iter.lt.ielcor) CALL ELCOR(ID)
         END DO
      END IF
C
      if(ihecor.ge.-2.and.izscal.eq.0) then
      if(inzd.gt.0.or.(idisk.eq.1.and.ifryb.gt.0)) then
         if(iheso6.eq.0) then
            CALL PZEVLD
          else
            CALL HESOL6
         end if
      end if
      end if
      if(izscal.eq.1) call dmeval
c
      if(ifryb.gt.0) then
         call rybheq
         if(nconrf.ge.0) call radfl
      end if
c
c     if convection is considered, call once again
c     the refinement procedure CONREF
c
c     write(*,*) 'hmix0',hmix0,iconre,iter,iconrs
      if(hmix0.gt.0..and.iconre.gt.0.and.iter.le.iconre.and.
     *   iter.ge.iconrs) then
         do iconrf=1,nconrf
            write(*,*) '*****************  conref No.',iconrf
            write(*,*)
            call conref
!          write(*,*) 'after conref'
            call radfl
!          write(*,*) 'after radfl'
         end do
      end if

C
C     Output of condensed model atmosphere to file 7
C     This file can serve as input of initial model atmosphere for
C     another run of the program.
C
      if(hmix0.ge.0..and.idisk.gt.0) call conoup
c
c      write(*,*) 'before output'
       CALL OUTPUT
c      write(*,*) 'after output'
C
C     Output of computed model atmosphere - standard output file
C
!     write(*,*) 'before if(lfin)',lfin
      IF(LFIN) THEN
CC       IF(.NOT.LTE) CALL PRINC
         CALL OUTPRI
!        write(*,*) 'after outpri',icompt,niter,lfin
CC       IF(ICOOLP.NE.0.OR.IPOPAC.NE.0) CALL COOLRT
CC       CALL RECHCK
CC       CALL HECHCK
CC       CALL KECHCK
CC       IF(ICHCKP.NE.0) CALL CHCKSE
CC       IF(INTENS.GT.0) CALL RTEINT
         if(icompt.gt.0) then
CC          call rtecmu
            call opaini(0)
            do ij=1,nfreq
               call opacf1(ij)
CC             call taufr1(ij)
            end do
         end if
         if(niter.gt.0) RETURN
c      else
c        CALL RECHCK
c        CALL HECHCK
c        CALL KECHCK
      END IF
C
C     The final part - to store previously calculated
C     mean intensities  - RADEX(IJ,ID),
C     and other model parameters (total number density, temperature,
C     electron density, and populations) for
C     further use in procedure SOLVE (actual complete linearization)
C
!      write(*,"(/'before psy0 - nfreqe,in',7i8)") nfreqe,nlvexp,inhe,
!    * inre,inpc,inse,nn

      IF(LFIN) RETURN
!     write(*,*) 'elec1',elec(1),elec(nd)

      IF(IFRYB.NE.0) THEN
         DO ID=1,ND
            PSY0(1,ID)=TEMP(ID)
            TOTN(ID)=DENS(ID)/WMM(ID)+ELEC(ID)
         END DO
         RETURN
      END IF

      IF(NFREQE.GT.0) THEN
         DO IJ=1,NFREQE
            DO ID=1,ND
               PSY0(IJ,ID)=RADEX(IJ,ID)
            END DO
         END DO
      END IF
      DO ID=1,ND
         DO II=1,NLVEXP
            PSY0(NFREQE+INSE+II-1,ID)=0.
            PGR(II)=0.
         END DO
         DO I=1,NLEVEL
            II=IABS(IIEXP(I))
            IF(II.GT.0) PGR(II)=PGR(II)+POPUL(I,ID)
         END DO
         DO III=1,NLVEXZ
            PSY0(NFREQE+INSE+III-1,ID)=PGR(INDLGZ(III))
         END DO
         TOTN(ID)=DENS(ID)/WMM(ID)+ELEC(ID)
         IF(INRE.NE.0) PSY0(NFREQE+INRE,ID)=TEMP(ID)
         IF(INPC.NE.0) PSY0(NFREQE+INPC,ID)=ELEC(ID)
         IF(INHE.NE.0) PSY0(NFREQE+INHE,ID)=TOTN(ID)
         IF(INZD.NE.0) PSY0(NFREQE+INZD,ID)=ZD(ID)
         IF(INMP.NE.0) PSY0(NFREQE+INMP,ID)=DENS(ID)/WMM(ID)
         IF(INDL.NE.0) PSY0(NFREQE+INDL,ID)=DELTA(ID)
      END DO
C
      IF(INIT.EQ.1.AND.NATOM.GT.0.AND..NOT.LFIN) THEN
         WRITE(6,"(//' REFERENCE LEVEL INDICES AS FUNCTIONS OF DEPTH'/,
     *          'ITER =',i4)") ITER

         DO ID=1,ND
            WRITE(6,"(' ID=',I3,2X,15I4)") ID,(NREFS(I,ID),I=1,NATOM)
         END DO
      END IF
C
      RETURN
      END

!*************************************************************************


      SUBROUTINE INILAM
C     =================
C
C     Auxiliary procedure for RESOLV
C     initialization of model parameters for further use in RESOLV
C
      use accura
      use alipar
      use atomic
      use basics
      use iterat
      use modelq
      
      implicit none

      REAL(DP) :: DENS0(MDEPTH),SBW(MLEVEL),XE(MDEPTH),ANTC(MDEPTH)
      REAL(DP) :: AMUV0,AMUV1,CH,AOLD,DPLP,DPLM,PTUR,PTURM,PRAD
      INTEGER  :: I,ION,IL,ID,IJ,IMOR,II,III
C
      IF(INIT.EQ.1) THEN
C
C     Before first iteration of complete linearization, ie. just after
C     initialization of basic parameters and reading the initial model
C     atmosphere - i.e. if INIT=1:
C     only evaluation of collisional rates for all transitions, at all
C     depths
C
         anerel=0.5
         if(teff.lt.8000.) anerel=0.01
         CALL TDPINI
         write(*,*) 'after tdpini'
         IF(IDISK.EQ.1) THEN
            AMUV0=DMVISC**(ZETA0+UN)
            AMUV1=UN-AMUV0
            DMTOT=DM(ND)
            EDISC=SIG4P*TEFF**4/DMTOT
         END IF
         DO ID=1,ND
            CALL WNSTOR(ID)
c           write(*,*) 'after wnstor',id
C           cycle
            FCOOL(ID)=0.
            FPRD(ID)=0.
            call sabolf(id)
c           write(*,*) 'after sabolf',id,sbf(1),sbf(2)
C           cycle
c
c           intialize b-factors
c
            DO I=1,NLEVEL
               BFAC(I,ID)=UN
               SBW(I)=ELEC(ID)*SBF(I)*WOP(I,ID)
c              if(mod(i,50).eq.1) write(*,*) 'sbw',id,i,sbw(i)
            END DO
c           cycle
            IF(.NOT.LTE.AND.IPSLTE.EQ.0 .and. id.lt.idlte) THEN
               DO ION=1,NION
                  DO I=NFIRST(ION),NLAST(ION)
                     IF(POPUL(NNEXT(ION),ID).GT.0..and.iltlev(i).eq.0)
     *               BFAC(I,ID)=POPUL(I,ID)/
     *               (POPUL(NNEXT(ION),ID)*SBW(I))
c                    if(mod(i,50).eq.1) write(*,*) 'bfac',id,i,ion,bfac(i,id)
                  END DO
               END DO
            END IF
c
c           fully fixed part of the total charge
c
            qfix(id)=0.
            do i=1,nlevel
               if(imodl(i).lt.0.or.iifix(iatm(i)).gt.0) then
                  ch=iz(iel(i))-1
                  il=ilk(i)
                  if(il.gt.0) ch=iz(il)+(iz(il)-1)*usum(il)*elec(id)
                  qfix(id)=qfix(id)+ch*popul(i,id)
               end if
            end do
c
c           collisional rates
c
            IF(.NOT.LTE) THEN
               CALL COLIS(ID,TEMP(ID))
               DO I=1,NTRANS
                  COLRAT(I,ID)=COL(I)
                  COLTAR(I,ID)=CLOC(I)
               END DO
            END IF
         END DO
          write(*,*) 'before odfmer'
         CALL ODFMER
          write(*,*) 'after odfmer'
C
c        initialize viscosity parameters for disks
c
CC       IF(IDISK.EQ.1) CALL VISINI
c
c        dielectronic recombination
c
         if(ifdiel.gt.0) call dietot
C
C        in case of ISPLIN>4 - (i.e. the DFE solver for transfer equation)
C        evaluate Planck function for the first estimate of RAD for
C        the electron scattering source function
C
         IF(ISPLIN.GE.5) THEN
            DO ID=1,ND
               DO IJ=1,NFREQ
                  RAD(IJ,ID)=BNUE(IJ)/(EXP(HKT1(ID)*FREQ(IJ))-UN)
               END DO
            END DO
         END IF
         write(*,*) 'end inilam'
         RETURN
      END IF
C
C     ==================================================================
C     Immediately after a completed iteration of complete linearization:
C     ==================================================================
C
      PRAD=0.
      DO ID=1,ND
C
C        save some old quantities
C
         AOLD=DENS(ID)/WMM(ID)+ELEC(ID)
         XE(ID)=UN-ELEC(ID)/AOLD
C
C     Depth by depth:
C        set up individual arrays of model parameters, namely:
C        temperature - TEMP (if temperature is one of variables,
C                      ie. if radiative equilibrium equation is solved)
C
         IF(INRE.NE.0) TEMP(ID)=PSY0(NFREQE+INRE,ID)
C
C        electron density - ELEC (if ELEC is one of variables, ie. if
C                       particle conservation equation is solved)
C
         IF(INPC.NE.0) ELEC(ID)=PSY0(NFREQE+INPC,ID)
C
C        density - DENS, calculated by means of total particle number
C                  density and electron density (if total particle
C                  number density is one of variables, ie. if hydrostatic
C                  equilibrium equation is solved - INHE.GT.0)
C
         IF(INHE.NE.0) TOTN(ID)=PSY0(NFREQE+INHE,ID)
C
         IF(IFIXDE.EQ.0) THEN
            DENS0(ID)=DENS(ID)
            IF(INHE.NE.0) THEN
               DENS(ID)=WMM(ID)*(PSY0(NFREQE+INHE,ID)-ELEC(ID))
               DPLP=DENS0(ID)*DPSILN
               DPLM=DENS0(ID)/DPSILN
               IF(DENS(ID).GT.DPLP) DENS(ID)=DPLP
               IF(DENS(ID).LT.DPLM) DENS(ID)=DPLM
             ELSE
               if(ioptab.lt.-1) then
                  PGS(ID)=PTOTAL(ID)
CC                DENS(ID)=RHOEOS(TEMP(ID),PGS(ID))
               end if
            END IF
         END IF
C
C        or again density, but calculated by means of the
C        massive particle density,
C        if this is one of variables - INMP.GT.0)
C
         IF(INMP.NE.0) DENS(ID)=WMM(ID)*PSY0(NFREQE+INMP,ID)
C
C        geometrical distance
C
         IF(INZD.GT.0) ZD(ID)=PSY0(NFREQE+INZD,ID)
C
C        the temperature logarithmic gradient delta
C
         IF(INDL.NE.0) DELTA(ID)=PSY0(NFREQE+INDL,ID)
C
         ANMA(ID)=DENS(ID)/WMM(ID)
         ANTO(ID)=ANMA(ID)+ELEC(ID)
      END DO
C
c     avoid oscillations in temperature
c
CC    IF(IOSCOR.NE.0) CALL OSCCOR
C
C     if needed, formal solution of the hydrostatic equilibrium to get
C     new total particle density, and possibly electron density
C
      IF(IHECOR.GE.2) THEN
         ID=1
         PTUR=HALF*VTURB(ID)*VTURB(ID)*DENS(ID)
         ANTC(ID)=(DM(ID)*GRAV-PRD0-PTUR)/BOLK/TEMP(ID)
         IF(ANTC(ID).LE.0) ANTC(ID)=DENS(ID)/WMM(ID)+ELEC(ID)
         DO ID=2,ND
            PTUR=HALF*VTURB(ID)*VTURB(ID)*DENS(ID)
            PTURM=HALF*VTURB(ID-1)*VTURB(ID-1)*DENS(ID-1)
            ANTC(ID)=(GRAV*(DM(ID)-DM(ID-1))+
     *                BOLK*TEMP(ID-1)*ANTC(ID-1)-
     *                PRADT(ID)+PRADT(ID-1)-PTUR+PTURM)/
     *                BOLK/TEMP(ID)
         END DO
         DO ID=1,ND
            ELEC(ID)=(UN-XE(ID))*ANTC(ID)
            DENS(ID)=WMM(ID)*(ANTC(ID)-ELEC(ID))
            ANMA(ID)=DENS(ID)/WMM(ID)
            ANTO(ID)=ANMA(ID)+ELEC(ID)
         END DO
      END IF
C
C     other depth-dependent quantities
C
      do id=1,nd
         PGS(ID)=(DENS(ID)/WMM(ID)+ELEC(ID))*BOLK*TEMP(ID)
      end do
c
      IF(IOPTAB.GE.0) THEN
         DO ID=1,ND
C
C           occupation probabilities
C
            CALL WNSTOR(ID)
C
C     Evaluation of collision rates for the new temperature
C
            IF(.NOT.LTE) THEN
               call sabolf(id)
               CALL COLIS(ID,TEMP(ID))
               DO I=1,NTRANS
                  COLRAT(I,ID)=COL(I)
                  COLTAR(I,ID)=CLOC(I)
               END DO
            END IF
         END DO
      END IF
C
CC    CALL CONCOR
      CALL TDPINI
C------------------------
C
C     new populations
C
C     1. first possibility (useful for pure CL) --
C     new populations, ie. those calculated directly
C     by the complete linearization (as old population + corresponding
C     corrections) are not used.
C     Instead, new populations are calculated from the new radiation
C     field basically by lambda iteration, ie.
C     a) evaluation of new radiative rates for explicit transitions
C
      if(ifpopr.le.0.or.lte.OR.IFRYB.GT.0) then
         IMOR=0
         IF(IFRYB.GT.2) IMOR=1
CC       IF(.NOT.LTE) CALL RATES1(IMOR)
C
C     b) depth by depth evaluation of new populations by solving
C        statistical equilibrium equation with previously evaluated
C        rates, together with constraints - precisely as in RESOLV
C
         DO ID=1,ND
            CALL STEQEQ(ID,POP,1)
CC          IF(.NOT.LCHC.and.iter.lt.ielcor) CALL ELCOR(ID)
         END DO

c           write(*,*) 'popul(44,44) in inlam',popul(44,44)
CC        if(iprind.eq.2) call output
c
C     2. second possibility -- populations from linearization corrections
C
      ELSE
         DO ID=1,ND
            DO I=1,NLEVEL
               if(iifix(iatm(i)).ne.1) then
                  II=IIEXP(I)
                  IF(II.GT.0) THEN
                     III=IINONZ(II)
                     IF(III.GT.0) THEN
                        POPUL(I,ID)=PSY0(NFREQE+INSE+III-1,ID)
                      ELSE
                        POPUL(I,ID)=0.
                     END IF
                   ELSE IF(II.LT.0) THEN
                     III=IINONZ(-II)
                     IF(III.GT.0) THEN
                        POPUL(I,ID)=PSY0(NFREQE+INSE+III-1,ID)*
     *                              SBPSI(I,ID)
                      ELSE
                        POPUL(I,ID)=0.
                     END IF
                   ELSE
                     III=IINONZ(IIEXP(ILTREF(I,ID)))
                     IF(III.GT.0) THEN
                        POPUL(I,ID)=PSY0(NFREQE+INSE+III-1,ID)*
     *                              SBPSI(I,ID)
                      ELSE
                        POPUL(I,ID)=0.
                     END IF
                  END IF
               END IF
            END DO
         END DO
      END IF
      CALL ODFMER
c
c     iprind=1
c     call output
c     iprind=0
c
c     dielectronic recombination
c
CC    if(ifdiel.gt.0) call dietot
C
CC    if(ifryb.gt.0) call rybheq
C
C     solution of the transfer equation with Compton scattering
C
CC    if(icompt.gt.0) then
CC       call opaini(1)
CC       call comset
CC       call rtecom
CC    end if
c
CC    IF(IDISK.EQ.1) call visini
c
c     if(ifryb.eq.0) then
      CALL OPAINI(1)
      DO ID=1,ND
         GRD(ID)=0.
         pra(id)=0.
         pradt(id)=0.
      END DO
      prd0=0.
      DO IJ=1,NFREQ
         CALL OPACF1(IJ)
         CALL RTEFR1(IJ)
         GRD(1)=GRD(1)+W(IJ)*ABSO1(1)*FH(IJ)*RAD1(1)
         DO ID=2,ND
            GRD(ID)=GRD(ID)+(RAD1(ID)*FAK1(ID)-RAD1(ID-1)*FAK1(ID-1))*
     *              W(IJ)
            pra(id)=pra(id)+RAD1(ID)*FAK1(ID)*W(IJ)
         END DO
         pra(1)=pra(1)+RAD1(1)*FAK1(1)*W(IJ)
c    *          -ABSO1(1)*W(IJ)*
c    *          (RAD1(1)*FH(IJ)-HEXTRD(IJ))
      END DO
      GRD(1)=PCK*GRD(1)/DENS(1)
c
      do id=1,nd
         pra(id)=pra(id)*pck
         pradt(id)=pradt(id)*pck
c        pradfc(id)=pra(id)/(2.5213e-15*temp(id)**4)
      end do
C
      if(idisk.lt.0) then
      PGS(1)=DM(1)*(GRAV-GRD(1))
      DO ID=2,ND
         PGS(ID)=PGS(ID-1)-PCK*GRD(ID)+GRAV*(DM(ID)-DM(ID-1))
      END DO
      end if
C
C     mesh refinement, if required
C
CC    if(nnewd.gt.0.and.iter.le.nnewd) CALL MREFIN
c
      RETURN
      END

!*************************************************************************


      SUBROUTINE RTEFR1(IJ)
C     =====================
C
C     Solution of the radiative transfer equation - for one frequency
C     - for the known source function.
C     Determination of the radiation field and variable Eddington
C     factors.
C
C     The numerical method used:
C      for ISPLIN = 0  -  the ordinary Feautrier scheme
C                 = 1  -  the spline collocation method
C                 = 2  -  Hermitian fourth-order method
C                 = 3  -  improved Feautrier scheme
C                         (Rybicki & Hummer 1991, A&A 245, 171.)
C
C     In all cases, the overall matrix system is solved by the standard
C     Gaussian elimination, analogous to that described in SOLVE
C     (auxiliary matrix D is called ALF in SOLVE; auxiliary vector ANU
C     is called BET in SOLVE)
C
C      U0     - derivative of Q0 wrt taumin;
C               for "fixed" frequencies, U0 has the meaning of
C               absorption coefficient * second moment H
C               ( a quantity needed for lower boundary condition of the
C               hydrostatic equilibrium equation, specifically for
C               accounting for an effect of fixed-option transitions)
C
C
      use accura
      use alipar
      use basics
      use iterat
      use modelq
CC    use atomic, only: ijali

      implicit none

      INTEGER, INTENT(IN) :: IJ
      REAL(DP), PARAMETER :: SIXTH=UN/6.,THIRD=UN/3.,TWOTHR=TWO/3.
      REAL(DP) :: AANU(MDEPTH),DDD(MDEPTH),FKK(MDEPTH),
     *            RDD(MDEPTH),ST0(MDEPTH),SS0(MDEPTH),AB0(MDEPTH),
     *            AA(MMU,MMU),BB(MMU,MMU),CC(MMU,MMU),VL(MMU),
     *            FFD(MMU,MMU),FF0D(MMU,MMU),
     *            FFPD(MMU,MMU),ali0(mdepth),ss0c(mdepth),
     *            AAA(MDEPTH),BBB(MDEPTH),CCC(MDEPTH),EEE(MDEPTH),
     *            ZZZ(MDEPTH),ALRH(MDEPTH),ALRM(MDEPTH),ALRP(MDEPTH),
     *            D(MMU,MMU,MDEPTH),ANU(MMU,MDEPTH),scor(mdepth),
     *            rmmu(2*MMU),wmmu(2*MMU),rwmu(2*MMU),
     *            dtau(mdepth),ali(mdepth),alij1(mdepth),
     *            tau(mdepth)
      REAL(DP) :: WW,FR,U0,QQ0,US0,TAUMIN,ALB1,P0,EX,TAMM,VLL
      REAL(DP) :: A,B,C,AI,BI,CI,DTM1,DTP1,DT0,AL,GA,BE,VL0,DIV,S,S1
      REAL(DP) :: FR15,BNU,PLAND,DPLAN,AJ,AH,AK,RMU,FH0,BQ,CQ,SUM
      REAL(DP) :: FFF,FLMIN,RUP,TAUIJ,RDOWN
      INTEGER  :: ISPL,ID,I,J,K,NW,IJI,IJE
C
      WW=W(IJ)
      ISPL=ISPLIN
CC    IF(ISPLIN.GE.5) THEN
CC       ISPLIN=ISPL-5
CC       IF(IJALI(IJ).GT.0) THEN
CC          IF(IRTE.EQ.0) THEN
CC             CALL RTEDF1(IJ)
CC           ELSE
CC             CALL RTEDF2(IJ)
CC          END IF
CC          ISPLIN=ISPL
CC          if(ifprad.eq.0) return
CC          DO ID=1,ND
CC             if(.not.lskip(ID,IJ))
CC   *         PRADT(ID)=PRADT(ID)+RAD1(ID)*FAK1(ID)*W(ij)
CC          END DO
CC          if(.not.lskip(1,IJ))
CC   *         PRD0=PRD0+ABSO1(1)*W(IJ)*(RAD1(1)*FH(IJ)-HEXTRD(IJ))
CC          DO ID=1,ND
CC             PRADA(ID)=PRADA(ID)+RAD1(ID)*FAK1(ID)*WW
CC          END DO
CC          RETURN
CC       END IF
CC    END IF
C
CC    if(icompt.gt.0.and.(iter.gt.1.or.ilam.gt.0)) then
CC       call rtecf1(ij)
CC       return
CC    end if
c
C
      FR=FREQ(IJ)
C
C     total source function
C
      AH=0.
      DO ID=1,ND
         AB0(ID)=ABSO1(ID)
         ST0(ID)=EMIS1(ID)/AB0(ID)
         RAD1(ID)=0.
         ALI1(ID)=0.
      END DO
C
C     non-coherent electron scattering by lambda iteration
C
      IF(NELSC.LE.0) THEN
         DO ID=1,ND
            SS0(ID)=-SCAT1(ID)/AB0(ID)
         END DO
       ELSE
         DO ID=1,ND
            ST0(ID)=ST0(ID)+SCAT1(ID)*EMEL1(ID)*RAD1(ID)/AB0(ID)
            SS0(ID)=0.
         END DO
      END IF
C
C     optical depth scale
C
      tau(1)=absot(1)*dm(1)
      DO ID=1,ND-1
         DT(ID)=HALF*(DM(ID+1)-DM(ID))*(ABSOT(ID+1)+ABSOT(ID))
         tau(id+1)=tau(id)+dt(id)
      END DO
c
      U0=0.
      QQ0=0.
      US0=0.
c     TAUMIN=ABSO1(1)*DEDM1
c     taumin=absot(1)*dm(1)/2.
      taumin=tau(1)
      ALB1=0.
C
C     Allowance for wind blanketing
C
      IF(IWINBL.GT.0) ALB1=TWO*ALBE(IJ)/(UN+ALBE(IJ))
C
C ************** Forward elimination
C
C     Upper boundary condition
C
      ID=1
      DTP1=DT(1)
      P0=0.
      EX=UN
      IF(MOD(ISPLIN,3).EQ.0) THEN
         B=DTP1*HALF
         C=0.
       ELSE
         B=DTP1*THIRD
         C=B*HALF
      END IF
      QQ0=0.
      US0=0.
      DO I=1,NMU
         IF(IDISK.EQ.0.and.iubc.ge.0) THEN
C
C        allowance for non-zero optical depth at the first depth point
C
            TAMM=TAUMIN/AMU(I)
            EX=EXP(-TAMM)
            P0=UN-EX
            QQ0=QQ0+P0*AMU(I)*WTMU(I)
            U0=U0+EX*WTMU(I)
            US0=US0+P0/TAMM*WTMU(I)
         END IF
C
         BI=B/AMU(I)
         CI=C/AMU(I)
         VL(I)=(BI+P0)*ST0(ID)+CI*ST0(ID+1)
CC       IF(IWINBL.LT.0) VL(I)=VL(I)+EXTINT(IJ,I)
         DO J=1,NMU
            BB(I,J)=SS0(ID)*WTMU(J)*(BI+P0)-ALB1*WTMU(J)
            CC(I,J)=-CI*SS0(ID+1)*WTMU(J)
         END DO
         BB(I,I)=BB(I,I)+AMU(I)/DTP1+UN+BI
         CC(I,I)=CC(I,I)+AMU(I)/DTP1-CI
         ANU(I,ID)=0.
c      if(ij.eq.136) WRITE(71,*) 'nmu',nmu,mmu
c      if(ij.eq.136) write(71,*) 'mu1',amu(i),wtmu(i),vl(i),bi,ci,
c    * bb(i,i),cc(i,i)
      END DO
C
c      write(61,"(i8,f12.3,1p9e11.3)") ij,2.997925e18/freq(ij),taumin,
c    * tau(1),absot(1),absot(2),absot(3),st0(1),qq0,u0,us0

      IF(ISPLIN.LE.2) THEN
         CALL MATINV(BB,NMU,MMU)
         DO I=1,NMU
            DO J=1,NMU
               D(I,J,ID)=0.
               DO K=1,NMU
                  D(I,J,ID)=D(I,J,ID)+BB(I,K)*CC(K,J)
               END DO
               ANU(I,1)=ANU(I,1)+BB(I,J)*VL(J)
            END DO
         END DO
       ELSE
         DO I=1,NMU
            DO J=1,NMU
               FF0D(I,J)=BB(I,J)/CC(I,I)
            END DO
            FF0D(I,I)=FF0D(I,I)-UN
         END DO
C
c        CALL MINV3(BB)
         CALL MATINV(BB,NMU,MMU)
         DO I=1,NMU
            ANU(I,ID)=0.
            DO J=1,NMU
               D(I,J,ID)=BB(I,J)*CC(J,J)
               ANU(I,ID)=ANU(I,ID)+BB(I,J)*VL(J)
            END DO
         END DO
      END IF
 
       if(ij.eq.136) write(71,*) 'binv',id,((bb(i,j),i=1,nmu),j=1,nmu)
       if(ij.eq.136) write(71,*) 'anu ',id,(anu(i,id),i=1,nmu)


C
C     Normal depth points  1 < ID < ND
C
      DO ID=2,ND-1
         DTM1=DTP1
         DTP1=DT(ID)
         DT0=TWO/(DTM1+DTP1)
         AL=UN/DTM1*DT0
         GA=UN/DTP1*DT0
         BE=AL+GA
         IF(MOD(ISPLIN,3).EQ.0) THEN
            A=0.
            C=0.
          ELSE IF(ISPLIN.EQ.1) THEN
            A=DTM1*DT0*SIXTH
            C=DTP1*DT0*SIXTH
          ELSE
            A=(UN-HALF*AL*DTP1*DTP1)*SIXTH
            C=(UN-HALF*GA*DTM1*DTM1)*SIXTH
         END IF
         B=UN-A-C
         VL0=A*ST0(ID-1)+B*ST0(ID)+C*ST0(ID+1)
         DO I=1,NMU
            DO J=1,NMU
               AA(I,J)=-A*SS0(ID-1)*WTMU(J)
               CC(I,J)=-C*SS0(ID+1)*WTMU(J)
               BB(I,J)=B*SS0(ID)*WTMU(J)
            END DO
         END DO
         DO I=1,NMU
            VL(I)=VL0
            DIV=AMU(I)*AMU(I)
            AA(I,I)=AA(I,I)+DIV*AL-A
            CC(I,I)=CC(I,I)+DIV*GA-C
            BB(I,I)=BB(I,I)+DIV*BE+B
         END DO
         DO I=1,NMU
            DO J=1,NMU
               VL(I)=VL(I)+AA(I,J)*ANU(J,ID-1)
            END DO
         END DO
         IF(ISPLIN.LE.2) THEN
            DO I=1,NMU
               DO J=1,NMU
                  S=0.
                  DO K=1,NMU
                     S=S+AA(I,K)*D(K,J,ID-1)
                  END DO
                  BB(I,J)=BB(I,J)-S
               END DO
            END DO
C
            CALL MATINV(BB,NMU,MMU)
            DO I=1,NMU
               DO J=1,NMU
                  D(I,J,ID)=0.
                  DO K=1,NMU
                     D(I,J,ID)=D(I,J,ID)+BB(I,K)*CC(K,J)
                  END DO
               END DO
            END DO
         ELSE
            DO I=1,NMU
               BB(I,I)=-AA(I,I)+BB(I,I)-CC(I,I)
               DO J=1,NMU
                  FFPD(I,J)=AA(I,I)*FF0D(I,J)
               END DO
            END DO
            DO I=1,NMU
               DO J=1,NMU
                  S=0.
                  DO K=1,NMU
                     S=S+FFPD(I,K)*D(K,J,ID-1)
                  END DO
                  FFD(I,J)=(BB(I,J)+S)/CC(I,I)
               END DO
            END DO
            DO I=1,NMU
               DO J=1,NMU
                  FF0D(I,J)=FFD(I,J)
               END DO
               FFD(I,I)=FFD(I,I)+UN
            END DO
C
            CALL MATINV(FFD,NMU,MMU)
            DO I=1,NMU
               DO J=1,NMU
                  D(I,J,ID)=FFD(I,J)
                  BB(I,J)=FFD(I,J)/CC(J,J)
               END DO
            END DO
         END IF
         DO I=1,NMU
            ANU(I,ID)=0.
            DO J=1,NMU
               ANU(I,ID)=ANU(I,ID)+BB(I,J)*VL(J)
            END DO
         END DO
      END DO
C
C     Lower boundary condition
C
      ID=ND
      FR15=FR*1.e-15
      BNU=BN*FR15*FR15*FR15
      PLAND=BNU/(EXP(HK*FR/TEMP(ND ))-UN)*RRDIL
      DPLAN=BNU/(EXP(HK*FR/TEMP(ND-1))-UN)*RRDIL
      IF(TEMPBD.GT.0.) THEN
         PLAND=BNU/(EXP(HK*FR/TEMPBD)-UN)*RRDIL
         DPLAN=BNU/(EXP(HK*FR/TEMPBD)-UN)*RRDIL
      END IF
      DPLAN=(PLAND-DPLAN)/DT(ND-1)
C
C     First option:
C     b.c. is different from stellar atmospheres; expresses symmetry
C     at the central plane   I(taumax,-mu,nu)=I(taumax,+mu,nu)
C
      IF(IFZ0.GE.0.AND.IDISK.EQ.1) THEN
         B=DTP1*HALF
         A=0.
         DO I=1,NMU
            BI=B/AMU(I)
            AI=A/AMU(I)
            VL(I)=ST0(ID)*BI+ST0(ID-1)*AI
            DO J=1,NMU
               AA(I,J)=-AI*SS0(ID-1)*WTMU(J)
               BB(I,J)=BI*SS0(ID)*WTMU(J)
            END DO
            AA(I,I)=AA(I,I)+AMU(I)/DTP1-AI
            BB(I,I)=BB(I,I)+AMU(I)/DTP1+BI
         END DO
         DO I=1,NMU
            S1=0.
            DO J=1,NMU
               S=0.
               S1=S1+AA(I,J)*ANU(J,ID-1)
               DO K=1,NMU
                  S=S+AA(I,K)*D(K,J,ID-1)
               END DO
               BB(I,J)=BB(I,J)-S
            END DO
            VL(I)=VL(I)+S1
         END DO
C
C     Second option:
C     b.c. is the same as in stellar atmospheres - the last depth point
C     is not at the central plane
C
       ELSE
         IF(IBC.EQ.0.OR.IBC.EQ.4) THEN
            DO I=1,NMU
               AA(I,I)=AMU(I)/DTP1
               VL(I)=PLAND+AMU(I)*DPLAN+AA(I,I)*ANU(I,ID-1)
               DO J=1,NMU
                  BB(I,J)=-AA(I,I)*D(I,J,ID-1)
               END DO
               BB(I,I)=BB(I,I)+AA(I,I)+UN
            END DO
         ELSE
            DO I=1,NMU
               A=AMU(I)/DTP1
               B=HALF/A
               AA(I,I)=A
               VL(I)=B*ST0(ID)+PLAND+AMU(I)*DPLAN+AA(I,I)*ANU(I,ID-1)
               DO J=1,NMU
                  BB(I,J)=B*SS0(ID)*WTMU(J)-AA(I,I)*D(I,J,ID-1)
               END DO
               BB(I,I)=BB(I,I)+A+B+UN
c              BB(I,I)=BB(I,I)+A+B-UN
            END DO
         END IF
      END IF
C
         CALL MATINV(BB,NMU,MMU)
C
      DO I=1,NMU
         ANU(I,ID)=0.
         DO J=1,NMU
            D(I,J,ID)=0.
            ANU(I,ID)=ANU(I,ID)+BB(I,J)*VL(J)
         END DO
      END DO
C
C ***************** Backsolution
C
      FKK(ND)=THIRD
      AJ=0.
      AH=0.
      AK=0.
      DO I=1,NMU
         RMU=WTMU(I)*ANU(I,ID)
         AJ=AJ+RMU
         AH=AH+RMU*AMU(I)
         AK=AK+RMU*AMU(I)*AMU(I)
      END DO
      RDD(ID)=AJ
      IF(IBC.EQ.0) THEN
         FKK(ND)=THIRD
       ELSE
         FKK(ID)=AK/AJ
         FHD(IJ)=AH/AJ
      END IF
C
      DO ID=ND-1,1,-1
         DO I=1,NMU
            DO J=1,NMU
               ANU(I,ID)=ANU(I,ID)+D(I,J,ID)*ANU(J,ID+1)
            END DO
         END DO
         AJ=0.
         AK=0.
         DO I=1,NMU
            RMU=WTMU(I)*ANU(I,ID)
            AJ=AJ+RMU
            AK=AK+RMU*AMU(I)*AMU(I)
         END DO
C
C         solution of the transfer equation
C         Variables:
C          ANU     - Feautrier intensity
C          RDD     - mean intensity
C          FKK     - Eddington factor f(K) = K/J
C
         FKK(ID)=AK/AJ
         RDD(ID)=AJ
      END DO
C
      if(idisk.eq.1) then
         do id=1,nd
            fak(ij,id)=fkk(id)
         end do
      end if
C
C     the "surface" Eddington factor fH
C
      AH=0.
      DO I=1,NMU
         AH=AH+WTMU(I)*AMU(I)*ANU(I,1)
      END DO
      FH0=AH/AJ
c     FH0=AH/AJ-HALF*ALB1
      FH(IJ)=FH0+ss0(1)*qq0
      q0(ij)=qq0
      uu0(ij)=u0

c     q0(ij)=0.
c     uu0(ij)=0.

      if(ij.eq.136) then
         do id=1,nd
            write(71,637) ij,id,iter,abso1(id),emis1(id),scat1(id),
     *         st0(id),ss0(id),rdd(id),fkk(id),tau(id)
  637 format('rti',i8,2i4,1p8e11.3)
         end do
      end if

C
C ********************
C
C     Again solution of the transfer equation, now with Eddington
C     FKK and FH determined above, to insure strict consistency of the
C     radiation field and Eddington factors
C
      if(ilmcor.eq.2) then
         do id=1,nd
            scor(id)=un/(un+ss0(id))
         end do
      else if(ilmcor.eq.3) then
         do id=1,nd
            ss0c(id)=ss0(id)
            st0(id)=st0(id)-ss0(id)*rdd(id)
            ss0(id)=0.
         end do
      end if
C
C     Upper boundary condition
C
      ID=1
      DTP1=DT(ID)
      IF(MOD(ISPLIN,3).EQ.0) THEN
         B=DTP1*HALF
         C=0.
       ELSE
         B=DTP1*THIRD
         C=B*HALF
      END IF
      BQ=UN/(B+QQ0)
      CQ=C*BQ
      BBB(ID)=(FKK(ID)/DTP1+FH0+B)*BQ+SS0(ID)
      CCC(ID)=(FKK(ID+1)/DTP1)*BQ-CQ*(UN+SS0(ID+1))
      VLL=ST0(ID)+CQ*ST0(ID+1)
c     IF(IWINBL.LT.0) VLL=VLL+HEXTRD(IJ)*BQ
      if(ilmcor.eq.2) then
         bbb(id)=bbb(id)*scor(id)
         ccc(id)=ccc(id)*scor(id)
         vll=vll*scor(id)
      end if
      ZZZ(ID)=UN/BBB(ID)
      AANU(ID)=VLL*ZZZ(ID)
      DDD(ID)=CCC(ID)*ZZZ(ID)
      FFF=BBB(ID)/CCC(ID)-UN
C
C     Normal depth point
C
      DO ID=2,ND-1
         DTM1=DTP1
         DTP1=DT(ID)
         DT0=TWO/(DTP1+DTM1)
         AL=UN/DTM1*DT0
         GA=UN/DTP1*DT0
         IF(MOD(ISPLIN,3).EQ.0) THEN
            A=0.
            C=0.
          ELSE IF(ISPLIN.EQ.1) THEN
            A=DTM1*DT0*SIXTH
            C=DTP1*DT0*SIXTH
          ELSE
            A=(UN-HALF*DTP1*DTP1*AL)*SIXTH
            C=(UN-HALF*DTM1*DTM1*GA)*SIXTH
         END IF
         AAA(ID)=AL*FKK(ID-1)-A*(UN+SS0(ID-1))
         CCC(ID)=GA*FKK(ID+1)-C*(UN+SS0(ID+1))
         BBB(ID)=(AL+GA)*FKK(ID)+(UN-A-C)*(UN+SS0(ID))
         VLL=A*ST0(ID-1)+C*ST0(ID+1)+(UN-A-C)*ST0(ID)
         if(ilmcor.eq.2) then
            aaa(id)=aaa(id)*scor(id)
            bbb(id)=bbb(id)*scor(id)
            ccc(id)=ccc(id)*scor(id)
            vll=vll*scor(id)
         end if
         AANU(ID)=VLL+AAA(ID)*AANU(ID-1)
         IF(ISPLIN.LE.2) THEN
            ZZZ(ID)=UN/(BBB(ID)-AAA(ID)*DDD(ID-1))
            DDD(ID)=CCC(ID)*ZZZ(ID)
            AANU(ID)=AANU(ID)*ZZZ(ID)
          ELSE
            SUM=-AAA(ID)+BBB(ID)-CCC(ID)
            FFF=(SUM+AAA(ID)*FFF*DDD(ID-1))/CCC(ID)
            DDD(ID)=UN/(UN+FFF)
            AANU(ID)=AANU(ID)*DDD(ID)/CCC(ID)
         END IF
      END DO
C
C     Lower boundary condition
C
      ID=ND
c
c     stellar atmospheric
c
      IF(IDISK.EQ.0.OR.IFZ0.LT.0) then
      IF(IBC.EQ.0) THEN
         BBB(ID)=FKK(ID)/DTP1+HALF
         AAA(ID)=FKK(ID-1)/DTP1
         VLL=HALF*PLAND+THIRD*DPLAN
       ELSE IF(IBC.LT.4) THEN
         B=UN/DTP1
         A=TWO*B*B
         BBB(ID)=UN+SS0(ID)+B*TWO*FHD(IJ)+A*FKK(ID)
         AAA(ID)=A*FKK(ID-1)
         VLL=ST0(ID)+B*(PLAND+TWOTHR*DPLAN)
       ELSE
         B=UN/DTP1
         A=TWO*B*B
         BBB(ID)=B+A*FKK(ID)
         AAA(ID)=A*FKK(ID-1)
         VLL=B*(PLAND+TWOTHR*DPLAN)
      END IF
c
c     accretion disk - symmetric boundary
c
      ELSE
         B=TWO/DTP1
         BBB(ID)=FKK(ID)/DTP1*B+UN+SS0(ND)
         AAA(ID)=FKK(ID-1)/DTP1*B
         VLL=ST0(ID)
      END IF
      if(ilmcor.eq.2) then
         aaa(id)=aaa(id)*scor(id)
         bbb(id)=bbb(id)*scor(id)
         vll=vll*scor(id)
      end if
      EEE(ND)=AAA(ID)/BBB(ID)
      ZZZ(ID)=UN/(BBB(ID)-AAA(ID)*DDD(ID-1))
      RAD1(ID)=(VLL+AAA(ID)*AANU(ID-1))*ZZZ(ID)
      FAK1(ID)=FKK(ND)
      ALRH(ID)=ZZZ(ID)
c
C     Backsolution
C
      DO ID=ND-1,1,-1
         EEE(ID)=AAA(ID)/(BBB(ID)-CCC(ID)*EEE(ID+1))
         RAD1(ID)=AANU(ID)+DDD(ID)*RAD1(ID+1)
         FAK1(ID)=FKK(ID)
         ALRH(ID)=ZZZ(ID)/(UN-DDD(ID)*EEE(ID+1))
         ALRM(ID)=0
         ALRP(ID)=0
      END DO
      flmin=(emis1(1)+scat1(1)*rad1(1))/ab0(1)*q0(ij)
c     FLUX(IJ)=FH(IJ)*RAD1(1)-half*hextrd(ij)-flmin
      FLUX(IJ)=FH(IJ)*RAD1(1)-flmin
c
      if(iubc.gt.0) hextrd(ij)=flmin

c ****************************************************
c     al=2.997925e18/freq(ij)
c     if(al.gt.911..and.al.lt.912.) then
c     if(ij.ge.9315.and.ij.le.9320) then
c     if(ij.eq.1304) then
c     if(ijex(ij).gt.0) then
c     if(al.gt.15.155.and.al.lt.15.176) then
c     if(al.gt.1210.44.and.al.lt.1210.46) then
      if(ij.eq.136) then
         do id=1,nd
            write(71,617) ij,id,iter,abso1(id),emis1(id),scat1(id),
     *         st0(id),ss0(id),rad1(id),fak1(id),tau(id)
  617 format('rte',i8,2i4,1p8e11.3)
         end do
      end if

c
c       write(62,610) ij,2.997925e18/freq(ij),dt(1),rad1(1),alrh(1),
c    *   alrh(2),alrh(3),fh(ij)*rad1(1),flux(ij)
c       write(62,610) ij,2.997925e18/freq(ij),dt(1),q0(ij),uu0(ij),
c    *    rdd(1),rad1(1),alrh(1)



c     id=nd
c     write(80,"(2i3,i7,1pe12.5,11e11.3)") iter,id,ij,freq(ij),
c    * tau(id),emis1(id)/abso1(id),scat1(id)/abso1(id),rdd(id),st0(id),
c    * emis1(id)/abso1(id)+rdd(id)*scat1(id)/abso1(id),
c    * rdd(id)*scat1(id)/abso1(id),alrh(id)
cc   *,pland,twothr*dplan,(pland+twothr*dplan)/dtp1
c    *,pland,(pland+twothr*dplan)/dtp1

c     write(83,"(2i3,i7,1pe12.5,11e11.3)") iter,id,ij,freq(ij),
c    * abso1(id),emis1(id),scat1(id),
c    * abso1(id)-scat1(id),
c    * emis1(id)/(abso1(id)-scat1(id))


c     id=nd-1
c     write(81,"(2i3,i7,1pe12.5,11e11.3)") iter,id,ij,freq(ij),
c    * tau(id),emis1(id)/abso1(id),scat1(id)/abso1(id),rdd(id),st0(id),
c    * emis1(id)/abso1(id)+rdd(id)*scat1(id)/abso1(id),
c    * rdd(id)*scat1(id)/abso1(id),alrh(id)

c     id=1
c     write(81,"(2i3,i7,1pe12.5,11e11.3)") iter,id,ij,freq(ij),
c    * tau(id),emis1(id)/abso1(id),scat1(id)/abso1(id),rdd(id),st0(id),
c    * emis1(id)/abso1(id)+rdd(id)*scat1(id)/abso1(id),
c    * rdd(id)*scat1(id)/abso1(id),alrh(id)

      id=1
      write(81,"(2i3,i7,f10.3,1p7e11.3)") 
     * iter,id,ij,2.997925e18/freq(ij),tau(id),
     * abso1(id),emis1(id),scat1(id),st0(id),-ss0(id),rdd(id)
      id=39
      write(82,"(2i3,i7,f10.3,1p7e11.3)") 
     * iter,id,ij,2.997925e18/freq(ij),tau(id),
     * abso1(id),emis1(id),scat1(id),st0(id),-ss0(id),rdd(id)
      id=nd
      write(83,"(2i3,i7,f10.3,1p7e11.3)") 
     *iter,id,ij,2.997925e18/freq(ij),tau(id),
     * abso1(id),emis1(id),scat1(id),st0(id),-ss0(id),rdd(id)


c 681 format(2i3,i7,1pe12.5,11e11.3)
C
C        evaluate approximate Lambda operator
C
C        a) Rybicki-Hummer Lambda^star operator (diagonal)
C           (for JALI = 1)
C
         DO ID=1,ND
            ALIM1(ID)=0.
            ALIP1(ID)=0.
         END DO
         IF(JALI.EQ.1) THEN
           DO ID=1,ND
             ALI1(ID)=ALRH(ID)
           END DO
c
           IF(IBC.EQ.0) THEN
             ali1(nd-1)=rad1(nd-1)/st0(nd-1)
             ali1(nd)=rad1(nd)/st0(nd)
           END IF
C
C        for IFALI>5:
C        tridiagonal Rybicki-Hummer operator (off-diagonal terms)
C
           IF(IFALI.GE.6) THEN
             ALIP1(1)=ALRH(2)*DDD(1)
             DO ID=2,ND-1
                ALIM1(ID)=ALRH(ID-1)*EEE(ID)
                ALIP1(ID)=ALRH(ID+1)*DDD(ID)
             END DO
             ALIM1(ND)=ALRH(ND-1)*EEE(ND)
             IF(IBC.EQ.0) THEN
                ALIM1(nd)=0.
                ALIM1(nd-1)=0.
                ALIP1(nd)=0.
                ALIP1(nd-1)=0.
             END IF
           END IF
c
C        b) diagonal Olson-Kunasz Lambda^star operator,
C           (for JALI = 2)
C
         ELSE IF(JALI.EQ.2) THEN
           DO ID=1,ND-1
             ALI0(ID)=0.
             DO I=1,NMU
               DIV=DT(ID)/AMU(I)
               ALI0(ID)=ALI0(ID)+(UN-EXP(-DIV))/DIV*WTMU(I)
             END DO
           END DO
           DO ID=2,ND-1
             ALI1(ID)=UN-HALF*(ALI0(ID)+ALI0(ID-1))
           END DO
           ALI1(1)=UN-HALF*(ALI0(1)+US0)
           ALI1(ND)=UN-ALI0(ND-1)
           ali1(nd-1)=rad1(nd-1)/st0(nd-1)
           ali1(nd)=rad1(nd)/st0(nd)
       END IF
C
C        correction of Lambda^star for scattering
C
         IF(ILMCOR.EQ.1) THEN
           DO ID=1,ND
             ALI1(ID)=ALI1(ID)*(UN+SS0(ID))
             ALIM1(ID)=ALIM1(ID)*(UN+SS0(ID))
             ALIP1(ID)=ALIP1(ID)*(UN+SS0(ID))
           END DO
           IF(IBC.EQ.4) THEN
             ALI1(ND)= ALI1(ND)/(UN+SS0(ND))
             ALIM1(ND)= ALIM1(ND)/(UN+SS0(ND))
             ALIP1(ND)= ALIP1(ND)/(UN+SS0(ND))
           END IF
         END IF
c
      if(ifalih.gt.0) then
c
c        solution for the individual angles - to get Lambda^star_H
C
         do id=1,nd
            alih1(id)=0.
            alij1(id)=0.
         end do
         nw=nmu
         do i=1,nw
            rmmu(i)=-amu(nw-i+1)
            rmmu(i+nw)=amu(i)
            wmmu(i)=wtmu(nw-i+1)
            wmmu(i+nw)=wtmu(i)
         end do
         do i=1,2*nw
            rwmu(i)=rmmu(i)*wmmu(i)*half
         end do
C
c     --------------------- loop over angles
c
         do i=1,2*nw
            do id=1,nd-1
               dtau(id)=dt(id)/abs(rmmu(i))
            end do
c
c           boundary conditions
c
c           rup=extrad(ij)
            rup=extint(ij,i)
C
C           diffusion approximation for semi-infinite atmospheres
C
            rdown=pland+rmmu(i)*dplan
c
c           solution of the transfer equation
c
CC          call rtesol(dtau,st0,rup,rdown,rmmu(i),ri,ali)
c
            DO ID=1,ND
               alih1(id)=alih1(id)+rwmu(i)*ali(id)
               alij1(id)=alij1(id)+wmmu(i)*ali(id)*half
            END DO
         end do
      end if
C
c     --------------------- end of loop over angles
c
      ISPLIN=ISPL
c
      if(idisk.ne.0) then
        iji=nfreq-kij(ij)+1
        DO ID=1,ND
           rad(iji,id)=rad1(id)
        END DO
      end if
C
C     radiation pressure
C
      if(ifprad.gt.0) then
         if(.not.lskip(1,IJ))
     *   PRD0=PRD0+ABSO1(1)*WW*(RAD1(1)*FH(IJ)-HEXTRD(IJ))
         DO ID=1,ND
            if(.not.lskip(ID,IJ))
     *      PRADT(ID)=PRADT(ID)+RAD1(ID)*FAK1(ID)*WW
            PRADA(ID)=PRADA(ID)+RAD1(ID)*FAK1(ID)*WW
         END DO
      end if
c
      if(chmax.ge.1.91e-3.and.chmax.le.2.03e-3) then
      tauij=taumin
      do id=1,nd
         if(ilmcor.eq.3) ss0(id)=ss0c(id)
         if(id.gt.1) tauij=tauij+dt(id-1)
          write(97,"(2i4,1p6e12.4)") ij,id,tauij,rad1(id),
     *      st0(id)/(un+ss0(id)),st0(id),un+ss0(id),ali1(id)
         end do
      end if

C
C     store quantities for explicit (linearized) frequencies
C
      IF(IJEX(IJ).LE.0) RETURN
      IJE=IJEX(IJ)
      DO ID=1,ND
         RADEX(IJE,ID)=RAD1(ID)
         FAKEX(IJE,ID)=FAK1(ID)
      END DO
c     Q0(IJ)=QQ0
c     UU0(IJ)=U0
      RETURN
      END SUBROUTINE RTEFR1
C
C     ***************************************************
c


      SUBROUTINE DMEVAL
C     =================
C
C     Auxiliary procedure for RESOLV  - for disks
C     recomputation of the m-scale in the case where z-scale is the
C     basic scale
C
      use accura
      use array1
      use atomic
      use basics
      use iterat
      use modelq

      implicit none

      REAL(DP) :: dma(mdepth),dmb(mdepth)
      REAL(DP) :: PGS00,PTURB,GRD0,HG1,HR1,X,F1,FLUXW
      REAL(DP) :: ERFCX
      INTEGER  :: ID,IJ,IJT
C
C     total pressure and gas pressure
C
      DO ID=1,ND
         PTURB=HALF*DENS(ID)*VTURB(ID)*VTURB(ID)
         PGS00=(DENS(ID)/WMM(ID)+ELEC(ID))*BOLK*TEMP(ID)
         PGS(ID)=PGS00
         PTOTAL(ID)=PGS(ID)+PRADT(ID)+PTURB
      END DO
c
C     mass at the first depth point
C
      ID=1
      GRD0=0.
      DO IJ=1,NFREQE
         IJT=IJFR(IJ)
         FLUXW=W(IJT)*FH(IJT)*RADEX(IJ,ID)
         GRD0=GRD0+FLUXW*ABSOEX(IJ,ID)
      END DO
      HG1=SQRT(TWO*PGS(1)/DENS(1)/QGRAV)
      HR1=PCK/QGRAV*(GRD0+FPRD(1))/DENS(1)
      if(iter.eq.1) pgas0=pgs(1)
      X=(ZD(1)-HR1)/HG1
      IF(X.LT.3.) THEN
         IF(X.LT.0.) X=0.
         F1=8.86226925e-1*EXP(X*X)*ERFCX(X)
       ELSE
         F1=HALF*(UN-HALF/X/X)/X
      END IF
C
      DMa(1)=HG1*DENS(1)*F1
      DMb(1)=DMa(1)
c
c     recompute the DM scale
C
      write(6,"(/'   ID          ZD         DM(old)  DMA     DMB'/)")
      DO ID=1,ND
         if(id.gt.1) then
            dmb(id)=dm(id)
            DMA(ID)=DMA(ID-1)-(ZD(ID)-ZD(ID-1))*TWO/
     *             (UN/DENS(ID)+UN/DENS(ID-1))
            DMb(ID)=DMb(ID-1)-(ZD(ID)-ZD(ID-1))*
     *             (DENS(ID)+DENS(ID-1))*half
         end if
         write(6,"(i5,1p4e12.4)") id,zd(id),dm(id),dma(id),dmb(id)
c        DM(ID)=DMB(ID)
         DM(ID)=DMa(ID)
      END DO
      DMTOT=DM(ND)
      EDISC=SIG4P*TEFF**4/DMTOT
      RETURN
      END SUBROUTINE DMEVAL

C
C     ***************************************************
c


      SUBROUTINE MATINV(A,N,NR)
C     =========================
C
C     Matrix inversion
C      by LU decomposition
C
C      A  -  matrix of actual size (N x N) and maximum size (NR x NR)
C            to be inverted;
C      Inversion is accomplished in place and the original matrix is
C      replaced by its inverse
C
      use accura
      implicit none

      INTEGER,INTENT(IN)      :: N,NR
      REAL(DP), INTENT(INOUT) :: A(NR,NR)
      REAL(DP) :: DIV,SUM
      INTEGER  :: I,IM1,J,JM1,K,II,JJ,IP1,JP1,K0
C
      K=NR
      DO I=2,N
         IM1=I-1
         DO J=1,IM1
            JM1=J-1
            DIV=A(J,J)
            SUM=0.
            IF(JM1.GE.1) THEN
               DO K=1,JM1
                  SUM=SUM+A(I,K)*A(K,J)
               END DO
            END IF
            A(I,J)=(A(I,J)-SUM)/DIV
         END DO
         DO J=I,N
            SUM=0.
            DO K=1,IM1
               SUM=SUM+A(I,K)*A(K,J)
            END DO
            A(I,J)=A(I,J)-SUM
         END DO
      END DO
C
      DO II=2,N
         I=N+2-II
         IM1=I-1
         IF(IM1.GE.1) THEN
            DO JJ=1,IM1
               J=I-JJ
               JP1=J+1
               SUM=0.
               IF(JP1.LE.IM1) THEN
                  DO K=JP1,IM1
                     SUM=SUM+A(I,K)*A(K,J)
                  END DO
               END IF
               A(I,J)=-A(I,J)-SUM
            END DO
         END IF
      END DO
C
      DO II=1,N
         I=N+1-II
         DIV=A(I,I)
         IP1=I+1
         IF(IP1.LE.N) THEN
            DO JJ=IP1,N
               J=N+IP1-JJ
               SUM=0.
               DO K=IP1,J
                  SUM=SUM+A(I,K)*A(K,J)
               END DO
               A(I,J)=-SUM/DIV
            END DO
         END IF
         A(I,I)=1.0_dp/A(I,I)
      END DO
C
      DO I=1,N
         DO J=1,I-1
            K0=I
            SUM=0.
               DO K=K0,N
               SUM=SUM+A(I,K)*A(K,J)
            END DO
            A(I,J)=SUM
         END DO
         DO J=I,N
            K0=J
            SUM=A(I,K0)
            IF(K0.LT.N) THEN
               K0=K0+1
               DO K=K0,N
                  SUM=SUM+A(I,K)*A(K,J)
               END DO
            END IF
            A(I,J)=SUM
         END DO
      END DO
C
      RETURN
      END SUBROUTINE MATINV

!*************************************************************************


      SUBROUTINE OUTPUT
C     =================
C
C     Output of computed model atmosphere on file 7
C     This file may be used as input file 8 (initial model atmosphere)
C     for a subsequent run of the program
C
      use accura
      use basics
      use modelq

      implicit none

      INTEGER  :: NUMLT,NUMPAR,ID,I,J

      NUMLT=3
      IF(IDISK.EQ.1) NUMLT=4
      IF(IFMOL.EQ.1) NUMLT=NUMLT+1
      NUMPAR=NLEVEL+NUMLT
      IF(LTE.AND.IPRINP.EQ.0) NUMPAR=NUMLT
      IF(IFMOL.GT.0) NUMPAR=-NUMPAR
C
C     NUMPAR  - number of model parameters in each depth
C             = NUMLT  for LTE model, ie. TEMP - temperature
C                                     ELEC - electron density
C                                     DENS - density
C             = NUMLT+NLEVEL  for NLTE model, ie. the above + populations
C ---------------------------------------------------------------------
C      2. DM(ID),ID=1,ND - mass-depth points for the input model
C ---------------------------------------------------------------------
C      3. for each depth:
C                 T   - temperature
C                 ANE - electron density
C                 RHO - mass density
C                 level populations - only for NLTE input model
C
      IF(IPRIND.EQ.0) THEN
         REWIND 7
         WRITE(7,"(2I5)") ND,NUMPAR
         WRITE(7,"(1P6E15.6)") (DM(ID),ID=1,ND)
         IF(IDISK.EQ.0) THEN
            DO ID=1,ND
               IF(LTE.AND.IPRINP.EQ.0) THEN
                  IF(IFMOL.EQ.0) THEN
                     WRITE(7,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID)
                   ELSE
                     WRITE(7,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *               TOTN(ID)
                  END IF
                ELSE
                  IF(IFMOL.EQ.0) THEN
                     WRITE(7,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *                      (POPUL(J,ID),J=1,NLEVEL)
                   ELSE
                     WRITE(7,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *                      TOTN(ID),(POPUL(J,ID),J=1,NLEVEL)
                  END IF
               END IF
            END DO
         ELSE
            DO ID=1,ND
               IF(LTE.AND.IPRINP.EQ.0) THEN
                  IF(IFMOL.EQ.0) THEN
                     WRITE(7,"(1P5E15.6)") TEMP(ID),ELEC(ID),
     *                      DENS(ID),ZD(ID)
                   ELSE
                     WRITE(7,"(1P5E15.6)") TEMP(ID),ELEC(ID),
     *                         DENS(ID),TOTN(ID),ZD(ID)
                  END IF
                ELSE
                  IF(IFMOL.EQ.0) THEN
                     WRITE(7,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *                      ZD(ID),(POPUL(J,ID),J=1,NLEVEL)
                   ELSE
                     WRITE(7,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *                       TOTN(ID),ZD(ID),(POPUL(J,ID),J=1,NLEVEL)
                  END IF
               END IF
            END DO
         END IF
         CLOSE(7)
      END IF

      IF(IPRIND.GT.0) THEN
         WRITE(77,"(2I5)") ND,NUMPAR
         WRITE(77,"(1P6E15.6)") (DM(I),I=1,ND)
         IF(IDISK.EQ.0) THEN
            IF(LTE) THEN
               DO ID=1,ND
                  WRITE(77,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID)
               END DO
              ELSE
               DO ID=1,ND
                  WRITE(77,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *                  (POPUL(J,ID),J=1,NLEVEL)
               END DO
            END IF
          ELSE
            IF(LTE) THEN
               DO ID=1,ND
                 WRITE(17,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *           ZD(ID)
               END DO
             ELSE
                WRITE(20,"(2I5)") ND,NUMPAR
                WRITE(20,"(1P6E13.6)") (DM(ID),ID=1,ND)
                DO ID=1,ND
                   WRITE(17,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *                  ZD(ID),(POPUL(J,ID),J=1,NLEVEL)
                   WRITE(20,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *                   ZD(ID),(BFAC(J,ID),J=1,NLEVEL)
                END DO
            END IF
         END IF
      END IF
      RETURN
      END SUBROUTINE OUTPUT


!*************************************************************************


      SUBROUTINE OUTPRI
C     =================
C
C     Output on unit 6
C
      use accura
      use array1
      use atomic
      use basics
      use modelq

      implicit none

      real(dp) ::  poplte(mlevel),bfab(mlevel,mdepth)

      REAL(DP) :: FLTT,TOTF,FLAM,GRP,FLEX,WD0C,FLUXW,DTAUM,
     *            AN,P,GR,FLTO,GRV,THT,PGINT,PTINT,GRVL,HMECH,
     *            PTO,ALPT,ALPG,DISIP,FRD
      INTEGER  :: IJ,IJP,IJT,ID,IDLT0,I,NUMP,NUMPAR,J

C
C ************    Print emergent radiation field on unit 13, namely
C
C      FREQ(IJ) - value of frequency
C      FLUX(IJ) - emergent flux, precisely the second moment H(freq)
C                 at the surface, in ergs/cm**2/s/sterad/Hz
C      FH(IJ)   - Eddington factor f(H), ie the ratio H/J, J is the
C                 mean intensity of radiation
C
      WRITE(6,"(/' ************************************'/
     *        ' FINAL RESULTS:'/' '/
     *        ' MODEL QUANTITIES IN',I3,'. ITERATION'/
     *        ' ************************************'/)") ITER-1
      FLTT=SIG4P*TEFF**4
      TOTF=0.
      DO IJ=1,NFREQ
         IJP=IJ
         IF(ispodf.eq.0) IJP=JIK(IJ)
         IF(IJX(IJP).NE.-1) THEN
            TOTF=TOTF+FLUX(IJP)*W(IJP)
         END IF
      END DO
      IF(LFIN) THEN
         TOTF=0.
         DO IJ=1,NFREQ
            IJP=IJ
            IF(ispodf.eq.0) IJP=JIK(IJ)
            IF(IJX(IJP).NE.-1) THEN
               WRITE(13,"(1PE15.8,1PE12.4,0PF7.3)") 
     *         FREQ(IJP),FLUX(IJP),FH(IJP)
               TOTF=TOTF+FLUX(IJP)*W(IJP)
               FLAM=FLUX(IJP)*FREQ(IJP)*FREQ(IJP)/2.997925E18
               write(14,"(f15.4,1PE15.8)") 
     *         2.997925e18/freq(ijp),flam
            END IF
         END DO
         CLOSE(13)
         CLOSE(14)
      END IF

      WRITE(6,"(' TOTAL SURFACE FLUX',1PD15.8)") TOTF
C
C ************    For partial opacity table, print electron
C     densities - actual, and that from opacity table
C
CC    if(ioptab.ne.0)  call eldenc
C
C ************    Print basic model parameters, namely
C
C      ID       - depth index
C      DM(ID)   - mass-depth variable (in g/cm**2)
C      TEMP(ID) - temperature (in K)
C      ELEC(ID) - electron density (cm**-3)
C      AN       - total particle number density (cm**-3)
C      DENS(ID) - mass density (g/cm**3)
C      P        - total gas pressure (cgs)
C      GR       - radiative acceleration (cgs)
C      FLTOT(ID)- total (integrated over frequencies) radiative flux
C
      IF(IDISK.eq.0) THEN
         WRITE(6,"(/' ----------------------'/
     *        ' FINAL MODEL ATMOSPHERE'/
     *        ' ----------------------'/
     *        '  ID    MASS',6X,'TAUROSS',5X,'TEMP',7X,'NE',9X,'DENS',
     *          6X,'P_gas',4X,'LOG(G_rad)',3x,'RAD/TOT',3x,'CON/TOT',
     *          2x,'(RAD+CON)/TOT'/)")
       ELSE
         WRITE(6,"(/' ---------------------'/
     *        ' FINAL DISK RING MODEL'/
     *        ' ---------------------'/
     *'  ID    MASS',4X,'TAUROSS',5X,'TEMP',7X,'NE',7X,'RHO',
     *          7X,'PGAS'5X,
c    *          'CON/TOT   RAD.FLX   DISSIP',2X,'FLX/DISSIP',4X,
     *          'DISSIP   RAD/DIS   CON/DIS',2X,' FLXTOT/DIS',4X,
     *          'Z',7X,'LOG G',2X,'LOG G(RAD)'/)")
      END IF

      DO IJ=1,NFREQE
         IJT=IJFR(IJ)
         CALL OPACF1(IJT)
         DO ID=1,ND
            ABSOEX(IJ,ID)=ABSO1(ID)
         END DO
      END DO
      DO ID=1,ND
C
C     contributions from explicit (linearized) frequencies to the
C     flux and radiation pressure
C
         GRP=0.
         FLEX=0.
         IF(NFREQE.GT.0) THEN
            DO IJ=1,NFREQE
               RAD0(IJ)=RADEX(IJ,ID)
               FK0(IJ)=FAKEX(IJ,ID)
               ABSO0(IJ)=ABSOEX(IJ,ID)
               IJT=IJFR(IJ)
               WD0C=W(IJT)
               IF(ID.EQ.1) THEN
                  FLUXW=FH(IJT)*RAD0(IJ)-HEXTRD(IJT)
                  IF(.NOT.LSKIP(ID,IJT)) GRP=GRP+W(ijt)*FLUXW*ABSO0(IJ)
                  FLEX=FLEX+WD0C*FLUXW
                ELSE
                  RADM(IJ)=RADEX(IJ,ID-1)
                  FKM(IJ)=FAKEX(IJ,ID-1)
                  ABSOM(IJ)=ABSOEX(IJ,ID-1)
                  FRD=FK0(IJ)*RAD0(IJ)-FKM(IJ)*RADM(IJ)
                  IF(.NOT.LSKIP(ID,IJFR(IJ))) GRP=GRP+W(ijt)*FRD
                  DTAUM=(ABSO0(IJ)*DENS1(ID)+ABSOM(IJ)*DENS1(ID-1))*
     *                   DELDM(ID-1)
                  FLEX=FLEX+WD0C*FRD/DTAUM
               END IF
            END DO
         END IF
         GRAD(ID)=GRP+FPRD(ID)
         if(ifryb.gt.0) GRAD(ID)=GRD(ID)
         IF(ID.EQ.1) THEN
            GRAD(ID)=GRAD(ID)/DENS(ID)
          ELSE
            GRAD(ID)=GRAD(ID)/(DM(ID)-DM(ID-1))
         END IF
         FLTOT(ID)=FLEX
C
C        other quantities
C
         AN=DENS(ID)/WMM(ID)+ELEC(ID)
         P=AN*TEMP(ID)*BOLK
         IF(ID.LT.ND.AND.GRAD(ID).GT.0.)
     *      GR=LOG10(GRAD(ID)*4.1916825D-10)
c        FLTO=FLTOT(ID)+FLFIX(ID)+flxc(id)
         flto=flrd(id)+flxc(id)
         ptotal(id)=pgs(id)+pradt(id)
         ptint=0.
         if(idisk.eq.0) then
            WRITE(6,"(1H ,I3,1P2E11.3,0PF10.1,1P6E11.3,3E13.5)") 
     *      ID,DM(ID),TROSS(ID),TEMP(ID),ELEC(ID),DENS(ID),P,GR,
     *      flrd(id)/fltt,flxc(id)/fltt,flto/fltt
            else
            IF(ID.EQ.1) THEN
               GRV=QGRAV*ZD(ID)
               THT=THETAV(ID)
               pgint=pgs(1)/dens(1)*dm(1)
               ptint=ptotal(1)/dens(1)*dm(1)
             ELSE
               GRV=QGRAV*(ZD(ID)+ZD(ID-1))*HALF
               THT=(THETAV(ID)+thetav(id-1))*HALF
               pgint=pgint+(dm(id)-dm(id-1))*(pgs(id)/dens(id)+
     *            pgs(id-1)/dens(id-1))*half
               ptint=ptint+(dm(id)-dm(id-1))*(ptotal(id)/dens(id)+
     *            ptotal(id-1)/dens(id-1))*half
            END IF
            GRVL=0.
            IF(GRV.GT.0.) GRVL=LOG10(GRV)
            HMECH=SIG4P*TEFF**4*(UN-THT)
            WRITE(6,"(i4,1p2e10.2,0pf10.1,1p10e10.2)") 
     *        ID,DM(ID),TROSS(ID),TEMP(ID),ELEC(ID),
     *        dens(id),pgs(id),hmech,
     *        flrd(id)/hmech,flxc(id)/HMECH,flto/hmech,ZD(ID),GRVL,GR
            wbar=wbarm/dm(nd)
            if(p.gt.0.) alpg=omeg32*wbar*dens(id)*viscd(id)/p
            pto=ptotal(id)
            if(pto.gt.0.) alpt=omeg32*wbar*dens(id)*viscd(id)/pto
            disip=viscd(id)*dens(id)*edisc
            write(98,"(i3,1p11d11.4)") 
     *         id,dm(id),zd(id),abrosd(id),temp(id),pgint,
     *         ptotal(id),p,dens(id),disip,alpg,alpt

            if(id.eq.nd) write(98,"(i3,1p11d11.4)") 
     *         id,edisc,viscd(id),dens(id),p,omeg32,wbar
         end if
      END DO
C
      if(idisk.eq.1) then
         if(pgint.gt.0.) alpgav=omeg32*wbar/pgint*dm(nd)
         if(ptint.gt.0.) alptav=omeg32*wbar/ptint*dm(nd)
         write(6,"(//
     *         ' omega*3/2                ',1pe10.2/
     *         ' wbar                     ',1pe10.2/
     *         ' equivalent alpha for Pg  ',1pe10.2/
     *         ' equivalent alpha for Ptot',1pe10.2)") 
     *         omeg32,wbar,alpgav,alptav
      end if
C
      IF(.NOT.LTE) THEN
C
C ************    Print  b-factors on unit 12 and
C                 "absolute" b-factors on unit 22
c       the traditional b-factors are already computed (BFAC),
c       here we compute the absolute ones
c
        LTE=.TRUE.
        idlt0=idlte
        DO ID=1,ND
           CALL WNSTOR(ID)
           CALL SABOLF(ID)
           CALL RATMAL(ID,NLEVEL)
           CALL LEVSOL(POPLTE,IIFOR,NLEVEL,0)
           DO I=1,NLEVEL
              BFAB(I,ID)=1.
              IF(POPLTE(I).GT.0.) BFAB(I,ID)=POPUL(I,ID)/POPLTE(I)
           END DO
        END DO
        LTE=.FALSE.
        idlte=idlt0
C
        NUMP=NLEVEL+3
        IF(IFMOL.GT.0) NUMP=NLEVEL+4
        IF(IDISK.EQ.0) THEN
           NUMPAR=NUMP
           IF(IFMOL.GT.0) NUMPAR=-NUMPAR
           WRITE(12,"(2I5)") ND,NUMPAR
           WRITE(12,"(1P6E15.6)") (DM(ID),ID=1,ND)
           WRITE(22,"(2I5)") ND,NUMPAR
           WRITE(22,"(1P6E13.6)") (DM(ID),ID=1,ND)
           DO ID=1,ND
              IF(IFMOL.EQ.0) THEN
                 WRITE(12,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *                      (BFAC(J,ID),J=1,NLEVEL)
                 WRITE(22,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *                      (BFAB(J,ID),J=1,NLEVEL)
               ELSE
                 WRITE(12,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *                      TOTN(ID),(BFAC(J,ID),J=1,NLEVEL)
                 WRITE(22,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *                      TOTN(ID),(BFAB(J,ID),J=1,NLEVEL)
              END IF
           END DO
        ELSE
           NUMPAR=NUMP+1
           IF(IFMOL.GT.0) NUMPAR=-NUMPAR
           WRITE(12,"(2I5)") ND,NUMPAR
           WRITE(12,"(1P6E15.6)") (DM(ID),ID=1,ND)
           WRITE(22,"(2I5)") ND,NUMPAR
           WRITE(22,"(1P6E13.6)") (DM(ID),ID=1,ND)
           DO ID=1,ND
              IF(IFMOL.EQ.0) THEN
                 WRITE(12,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *                      ZD(ID),(BFAC(J,ID),J=1,NLEVEL)
                 WRITE(22,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *                      ZD(ID),(BFAB(J,ID),J=1,NLEVEL)
               ELSE
                 WRITE(12,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *                      TOTN(ID),ZD(ID),(BFAC(J,ID),J=1,NLEVEL)
                 WRITE(22,"(1P5E15.6)") TEMP(ID),ELEC(ID),DENS(ID),
     *                      TOTN(ID),ZD(ID),(BFAB(J,ID),J=1,NLEVEL)
              END IF
           END DO
        END IF
      END IF
 
      RETURN
      END SUBROUTINE OUTPRI

C
C     **************************************************************************
C

      SUBROUTINE PZERT
C     ================
C
C     driving routine for super-zeroing, i.e. detecting that
C     a given population is small throughout the whole
C     atmosphere, so it is removed completely from linearization
C
      use accura
      use atomic
      use basics
      use modelq

      implicit none

      REAL(DP) :: POPMA(MLEVEL),GZR(MLEVEL)
      INTEGER  :: INDLEZ(MLEVEL)

      REAL(DP) :: POPZRL,POPM,POPREL
      INTEGER  :: IAT,N1,NK,NLNZX,ID,II,I
c
      if(ioptab.lt.0) return
C
C     super-zeroing of the individual levels
C
      POPZRL=1.E5*POPZER
      NLNZX=0
      DO IAT=1,NATOM
         N1=N0A(IAT)
         NK=NKA(IAT)
         DO II=N1,NK
            POPMA(II)=0.
         END DO
c
c        set-up quantity POPMA(II), which is the maximum
C        (over depths) of the relative population of given
C        level II to the total population of the atom.
C
         DO ID=1,ND
            POPM=0.
            DO II=N1,NK
               IF(POPUL(II,ID).GT.POPM) POPM=POPUL(II,ID)
            END DO
            DO II=N1,NK
               POPREL=POPUL(II,ID)/POPM
               IF(POPREL.GT.POPMA(II)) POPMA(II)=POPREL
            END DO
         END DO
C
C        if POPMA(II) is small, level II is super-zeroed
C
         DO II=N1,NK
            IPZERT(II)=0
            IF(POPMA(II).LT.POPZRL) THEN
               IPZERT(II)=1
               DO ID=1,ND
                  IPZERO(II,ID)=1
                  POPUL(II,ID)=0.
               END DO
             ELSE
               IF(IIEXP(II).GT.0) THEN
                  NLNZX=NLNZX+1
                  INDLEZ(NLNZX)=II
               END IF
            END IF
         END DO
      END DO
c
c     now, check whether all populations within a group were
C     super-zeroed. If so, super-zero the whole group
C
      DO II=1,NLVEXP
         GZR(II)=1.
      END DO
      DO I=1,NLEVEL
         II=IABS(IIEXP(I))
         IF(II.NE.0) GZR(II)=GZR(II)*IPZERT(I)
      END DO
      NLVEXZ=0
      DO II=1,NLVEXP
         IF(GZR(II).EQ.0) THEN
            IGZERT(II)=0
            NLVEXZ=NLVEXZ+1
            INDLGZ(NLVEXZ)=II
            IINONZ(II)=NLVEXZ
          ELSE
            IGZERT(II)=1
            IINONZ(II)=0
         END IF
      END DO
      NN=NN0-NLVEXP+NLVEXZ
c
      RETURN
      END SUBROUTINE PZERT


!*************************************************************************


      SUBROUTINE ACCELP
C     =================
C
C     Acceleration of convergence for populations
C     (from Auer 1987, in Numerical Radiative Transfer p. 101)
C
      use accura
      use basics
      use iterat
      use modelq
      use accel

      implicit none

      REAL(DP) :: A1,B1,B2,C1,C2,D0,D1,D2,AB,A,B,WT
      INTEGER  :: IPNG,IPT,IPT0,IPT1,IPT2,ID,IX
C
      IF(NLAMBD.LT.IACPP.OR. ILAM.LT.IACC0P) RETURN
      ipng=1
      if(iacdp.gt.0) ipng=mod((ILAM-IACPP),IACDP)
      if(.not.lac2p) then
      IPT=MOD(ILAM,3)
      IPT0=MOD(IACPP,3)
      IPT1=MOD((IACPP+1),3)
      IPT2=MOD((IACPP+2),3)
      IF(ILAM.EQ.IACC0P) THEN
         DO ID=1,ND
            DO IX=1,NLEVEL
               POPUL3(IX,ID)=POPUL(IX,ID)
            END DO
         END DO
       ELSE IF(IPT.EQ.IPT1) THEN
         DO ID=1,ND
            DO IX=1,NLEVEL
               POPUL2(IX,ID)=POPUL(IX,ID)
            END DO
         END DO
       ELSE IF(IPT.EQ.IPT2) THEN
         DO ID=1,ND
            DO IX=1,NLEVEL
               POPUL1(IX,ID)=POPUL(IX,ID)
            END DO
         END DO
      END IF
      else if (ipng.ne.0) then
         DO ID=1,ND
            DO IX=1,NLEVEL
               POPUL3(IX,ID)=POPUL2(IX,ID)
            END DO
         END DO
         DO ID=1,ND
            DO IX=1,NLEVEL
               POPUL2(IX,ID)=POPUL1(IX,ID)
            END DO
         END DO
         DO ID=1,ND
            DO IX=1,NLEVEL
               POPUL1(IX,ID)=POPUL(IX,ID)
            END DO
         END DO
         RETURN
      end if

      IF(ILAM.LT.IACPP) RETURN
C
      A1=0.
      B1=0.
      B2=0.
      C1=0.
      C2=0.
      DO ID=1,ND
         DO IX=1,NLEVEL
            WT=1.
            IF(POPUL(IX,ID).NE.0.) WT=1./ABS(POPUL(IX,ID))
            D0=POPUL(IX,ID)-POPUL1(IX,ID)
            D1=D0-POPUL1(IX,ID)+POPUL2(IX,ID)
            D2=D0-POPUL2(IX,ID)+POPUL3(IX,ID)
            A1=A1+WT*D1*D1
            B1=B1+WT*D1*D2
            B2=B2+WT*D2*D2
            C1=C1+WT*D0*D1
            C2=C2+WT*D0*D2
         END DO
      END DO
      AB=B2*A1-B1*B1
      IF(AB.EQ.0.) THEN
         WRITE(6,"(' **** ACCELP, ITER=',I4,'   AB = ',F7.3)") ILAM,AB
         WRITE(10,"(' **** ACCELP, ITER=',I4,'   AB = ',F7.3)") ILAM,AB
         IACPP=IACPP+IACDP
         IACC0P=IACPP-3
         RETURN
      ENDIF
      A=(B2*C1-B1*C2)/AB
      B=(A1*C2-B1*C1)/AB
C
      DO ID=1,ND
         DO IX=1,NLEVEL
            POPUL(IX,ID)=(1.-A-B)*POPUL(IX,ID)+A*POPUL1(IX,ID)+
     *                   B*POPUL2(IX,ID)
         END DO
      END DO
      WRITE(6,"(' **** ACCELP, ITER=',I4)") ILAM
      WRITE(10,"(' **** ACCELP, ITER=',I4)") ILAM
      LAC2P=.TRUE.
      RETURN
      END SUBROUTINE ACCELP


!*************************************************************************


      subroutine rechck
c     =================
c
c     check of radiative equilibrium - integral version
c
      use accura
      use atomic
      use basics
      use modelq

      implicit none

      real(dp) :: abt(mdepth),emt(mdepth),re
      integer  :: id,ij
c
      do id=1,nd
         abt(id)=0.
         emt(id)=0.
      end do
c
      do ij=1,nfreq
         call opacf1(ij)
         call rtefr1(ij)
         do id=1,nd
            abt(id)=abt(id)+(abso1(id)-scat1(id))*rad1(id)*w(ij)
            emt(id)=emt(id)+emis1(id)*w(ij)
         end do
      end do
c
      write(17,"(/
     *   ' id     dm         T     int(kappa*J)  int(emis)   rel'/)")
      do id=1,nd
         re=(abt(id)-emt(id))/emt(id)
         write(17,"(i4,1pe11.3,0pf10.1,2x,1p3e13.5)") 
     *   id,dm(id),temp(id),abt(id),emt(id),re
      end do
c
      return
      end subroutine rechck


!*************************************************************************


      SUBROUTINE DMDER
C     ================
C
      use accura
      use atomic
      use basics
      use modelq
      use disaux

      implicit none
      
      INTEGER :: ID

      DO ID=2,ND-1
         DDM(ID)=DM(ID)-DM(ID-1)
         DDP(ID)=DM(ID+1)-DM(ID)
         DD0(ID)=DM(ID+1)-DM(ID-1)
         DDMIN(ID)=DDP(ID)/DD0(ID)
         DDPLU(ID)=DDM(ID)/DD0(ID)
         DDA(ID)=DDMIN(ID)/DDM(ID)
         DDC(ID)=DDPLU(ID)/DDP(ID)
      END DO
C
      DDM(1)=0.
      DDM(ND)=DM(ND)-DM(ND-1)
      DDP(1)=DM(2)-DM(1)
      DDP(ND)=0.
      DDMIN(1)=0.
      DDMIN(ND)=1.
      DDPLU(1)=1.
      DDPLU(ND)=0.
      DDA(1)=0.
      DDA(ND)=UN/DDM(ND)
      DDC(1)=UN/DDP(1)
      DDC(ND)=0.
      DO ID=1,ND
         DDB(ID)=DDA(ID)-DDC(ID)
      END DO
C
      RETURN
      END


