      SUBROUTINE DWNFR0(ID)
C     =====================
C
C     Auxiliary quantities for dissolved fractions
C
      use accura
      use modelq
      use basics

      implicit none

      INTEGER, INTENT(IN) :: ID
      REAL(DP), PARAMETER :: SIXTH=UN/6.,CCOR=0.09,F23=-2/3.
      real(dp), parameter :: p1=0.1402,p2=0.1285,p3=un,p4=3.15,p5=4.
      REAL(DP) :: ANE,ANES,X,A3
      INTEGER  :: IZZ
C
      ANE=ELEC(ID)
      ELEC23(ID)=EXP(F23*LOG(ANE))
      ANES=EXP(SIXTH*LOG(ANE))
      ACOR(ID)=CCOR*ANES/SQT1(ID)
      X=EXP(P4*LOG(UN+P3*ACOR(ID)))
      DWC2(ID)=P2*X
      A3=ACOR(ID)*ACOR(ID)*ACOR(ID)
      DO IZZ=1,MZZ
         Z3(IZZ)=IZZ*IZZ*IZZ
         DWC1(IZZ,ID)=P1*(X+P5*(IZZ-UN)*A3)
      END DO
      RETURN
      END SUBROUTINE DWNFR0

C
C
C ********************************************************************
C
C
      SUBROUTINE DWNFR1(FR,FR0,ID,IZZ,DW1)
C     ====================================
C
C     dissolved fraction for frequency FR
C
      use accura
      use modelq
      use basics

      implicit none 

      REAL(DP), PARAMETER :: TKN=3.01,CKN=5.33333333,CB0=8.59e14
      REAL(DP), PARAMETER :: SQFRH=5.734152e7

      REAL(DP), INTENT(IN)  :: FR,FR0
      REAL(DP), INTENT(OUT) :: DW1
      INTEGER, INTENT(IN)   :: ID,IZZ
      REAL(DP) :: CB,XN,XN1,XKN,BETA,BETA3,BETA32,F
C
      cb=cb0*bergfc
c
      IF(FR.LT.FR0) THEN
         XN=SQFRH*IZZ/SQRT(FR0-FR)
         if(xn.le.tkn) then
            xkn=un
          else
            xn1=un/(xn+un)
            xkn=ckn*xn*xn1*xn1
         end if
         BETA=CB*Z3(IZZ)*XKN/(XN*XN*XN*XN)*ELEC23(ID)
         BETA3=BETA*BETA*BETA
         BETA32=SQRT(BETA3)
         F=(DWC1(IZZ,ID)*BETA3)/(UN+DWC2(ID)*BETA32)
         DW1=UN-F/(UN+F)
       ELSE
         DW1=UN
      END IF
      RETURN
      END SUBROUTINE DWNFR1
C
C
C     ****************************************************************
C
C
      SUBROUTINE SGMER0
C     =================
C
      use accura
      use modelq
      use basics
      use atomic

      implicit none

      REAL(DP), PARAMETER :: FRH=3.28805E15,PH2=2.815e29*2., 
     *                       EHB=157802.77355
      REAL(DP), DIMENSION(NLMX) ::  FREDG,S,SUM,SUD
      REAL(DP) :: CH,EX,EXI,SGEM
      INTEGER  :: IMER,II,IE,II0,ID,I
C
      IMER=0
      DO II=1,NLEVEL
         IF(IFWOP(II).GE.0) CYCLE
         IMER=IMER+1
         IMRG(II)=IMER
         IIMER(IMER)=II
         IE=IEL(II)
         CH=IZ(IE)*IZ(IE)
         FRCH(IMER)=FRH*CH
         SGM0(IMER)=PH2*CH*CH
         II0=NQUANT(II-1)+1
         DO ID=1,ND
            EX=EHB*CH*TEMP1(ID)
            DO I=II0,NLMX
               FREDG(I)=FRCH(IMER)*XI2(I)
               EXI=EXP(EX*XI2(I))
               S(I)=EXI*WNHINT(I,ID)*XI3(I)
               SUM(I)=0.
            END DO
            SUM(NLMX)=S(NLMX)
            SUD(NLMX)=S(NLMX)*XI2(NLMX)
            DO I=NLMX-1,II0,-1
               SUM(I)=SUM(I+1)+S(I)
            END DO
            DO I=1,II0-1
               SUM(I)=SUM(II0)
            END DO
            SGEM=SGM0(IMER)/GMER(IMER,ID)
            DO I=1,NLMX
               SGMSUM(I,IMER,ID)=SUM(I)*SGEM
            END DO
         END DO
      END DO
      RETURN
      END SUBROUTINE SGMER0
C
C
C     ****************************************************************
C
C
      SUBROUTINE SGMER1(FRINV,FR3INV,IMER,ID,SGME1)
C     =============================================
C
C     photoionization cross-section for a merged level
C
      use accura
      use modelq

      implicit none

      REAL(DP), INTENT(IN) :: FRINV,FR3INV
      REAL(DP), INTENT(OUT):: SGME1
      INTEGER, INTENT(IN)  :: ID,IMER
      INTEGER              :: ISU
C
      ISU=INT(SQRT(FRCH(IMER)*FRINV))+1
      SGME1=SGMSUM(ISU,IMER,ID)*FR3INV
      RETURN
      END SUBROUTINE SGMER1
C
C
C     ****************************************************************
C
C
      SUBROUTINE SGMERD(FRINV,FR3INV,IMER,ID,SGME1,DSGME1)
C     ====================================================
C
C     photoionization cross-section for a merged level
C
      use accura
      use modelq

      implicit none

      REAL(DP), INTENT(IN) :: FRINV,FR3INV
      REAL(DP), INTENT(OUT):: SGME1,DSGME1
      INTEGER, INTENT(IN)  :: ID,IMER
      INTEGER              :: ISU

C
      ISU=INT(SQRT(FRCH(IMER)*FRINV))+1
      SGME1=SGMSUM(ISU,IMER,ID)*FR3INV
      DSGME1=-SGMSUD(ISU,IMER,ID)*FR3INV
      RETURN
      END SUBROUTINE SGMERD
