      SUBROUTINE LEVGRP(ID,IICAL,IMODE,POPP)
C     ======================================
C
C     determination of the total population of a the level groups;
C     and of relative populations of the group consituents
C
C     Input:  ID    - depth index
C             IICAL - array of level grouping parameters (IIEXP of IIFOR)
C             IMODE - a mode of input populations:
C                   = 0 - input populations are POPUL(I,ID)
C                   = 1 - input populations are given by the last
C                         formal parameter POP
C             POP   - array of input populations (for IMODE=1 only)
C
      use atomic
      use basics
      use iterat
      use modelq

      implicit none

      INTEGER, INTENT(IN) :: ID,IMODE
      INTEGER, INTENT(IN) :: IICAL(MLEVEL)
      REAL(DP), INTENT(INOUT) ::  POPP(MLEVEL)

      INTEGER  :: I,II,IAT
      REAL(DP) :: POPM
      LOGICAL  :: LKIT

      if(ioptab.lt.0) return
C
      DO I=1,NLVEXP
         POPGRP(I)=0.
         igzero(i,id)=0
      END DO
      IF(IMODE.EQ.0) THEN
          DO I=1,NLEVEL
             POPP(I)=POPUL(I,ID)
         END DO
      END IF
C
C     total population of the group
C
      DO I=1,NLEVEL
         II=IABS(IICAL(I))
         IF(II.NE.0) POPGRP(II)=POPGRP(II)+POPP(I)
      END DO
C
C     ratios of the popultions of the individual group
C     components w.r.t the total group populations
C     this quantity remains fixed during linearization
C
      DO I=1,NLEVEL
         II=IICAL(I)
         IF(II.LT.0) THEN
            IF(POPGRP(-II).GT.0.) THEN
               SBPSI(I,ID)=POPP(I)/POPGRP(-II)
             ELSE
               SBPSI(I,ID)=0.
               IGZERO(-II,ID)=1
            END IF
         END IF
      END DO
C
C     zeroing of the whole group - if the total group population
C     is smaller than POPZER times the total atomic population
C
      IF(ITER.EQ.0) THEN
         LKIT=.TRUE.
       ELSE
         LKIT=KANT(ITER).EQ.0 .AND. ITER.LT.IACC
      ENDIF
      IF(LKIT) THEN
         DO I=1,NLEVEL
            IAT=IATM(I)
            POPM=DENS(ID)/WMM(ID)/YTOT(ID)*ABUND(IAT,ID)
            II=IICAL(I)
            IF(II.LT.0) THEN
               IF(POPGRP(-II)/POPM.LT.POPZER) THEN
                  POPGRP(-II)=0.
                  IGZERO(-II,ID)=1
               END IF
               rpop0(-ii,id)=popgrp(-ii)/popm
             else if(ii.gt.0) then
               rpop0(ii,id)=popgrp(ii)/popm
            END IF
         END DO
      END IF
C
      RETURN
      END SUBROUTINE LEVGRP
C
C
C ************************************************************************
C
C
c
      SUBROUTINE GFREE0(ID)
C     =====================
C
C     depth-dependent quantities for the hydrogenic free-free Gaunt factor
C
      use accura
      use basics
      use modelq

      implicit none

      REAL(DP), PARAMETER :: THET0=5.0404e3,
     *           THET1=1./THET0,
     *           A0=1.0823,
     *           B0=2.98e-2,
     *           C0=6.70e-3,
     *           D0=1.12e-2,
     *           A1=3.9999187e-3,
     *           B1=-7.8622889e-5,
     *           C1=1.070192,
     *           A2=6.4628601e-2,
     *           B2=-6.1953813e-4,
     *           C2=2.6061249e-1,
     *           A3=3.7542343e-2,
     *           B3=1.3983474e-5,
     *           C3=5.7917786e-1,
     *           A4=3.4169006e-1,
     *           B4=1.1852264e-2,
     *           XMIN=0.2,
     *           XMINI=1./XMIN,
     *           THMIN=4.0e-2
 
      INTEGER, INTENT(IN) :: ID
      REAL(DP)            :: T,THET,THT
C
      T=TEMP(ID)
      THET=1./MAX(THET0/T,THMIN)
      GF0(ID)=(A0+B0*THET)
      GF1(ID)=(A1+B1*THET)*THET+C1
      GF2(ID)=(A2+B2*THET)*THET+C2
      GF3(ID)=(A3+B3*THET)*THET+C3
      GF4(ID)=A4+B4*THET
      GF5(ID)=C0+D0*THET
      GF6(ID)=GF0(ID)+GF5(ID)*XMINI
C
C     auxiliary quantities for derivatives
C
      THT=THET0/T
      IF(THT.GE.THMIN) THEN
         THET=THT
         GF0D(ID)=B0*THET1
         GF1D(ID)=(A1+B1*THET*TWO)*THET1
         GF2D(ID)=(A2+B2*THET*TWO)*THET1
         GF3D(ID)=(A3+B3*THET*TWO)*THET1
         GF4D(ID)=B4*THET1
         GF5D(ID)=D0*THET1
         GF6D(ID)=GF0D(ID)+GF5D(ID)*XMINI
       ELSE
         GF0D(ID)=0.
         GF1D(ID)=0.
         GF2D(ID)=0.
         GF3D(ID)=0.
         GF4D(ID)=0.
         GF5D(ID)=0.
         GF6D(ID)=0.
      END IF
      RETURN
      END SUBROUTINE GFREE0
C
C
C     ****************************************************************
C
C

      REAL(DP) FUNCTION GFREE1(ID,X)
C     ==============================
C
C     Hydrogenic free-free Gaunt factor, for depth ID,
C     frequency FR, and charge CH
C
      use accura
      use modelq

      implicit none

      REAL(DP), PARAMETER  :: XMIN=0.2, XMINI=1./XMIN
      REAL(DP), INTENT(IN) :: X
      INTEGER, INTENT(IN)  :: ID
C
      IF(X.LT.1.) THEN
         GFREE1=((GF4(ID)*X-GF3(ID))*X+GF2(ID))*X+GF1(ID)
       ELSE IF(X.LT.XMINI) THEN
         GFREE1=GF0(ID)+GF5(ID)*X
       ELSE
         GFREE1=GF6(ID)
      END IF
      RETURN
      END FUNCTION GFREE1
C
C
C     ****************************************************************
C
      SUBROUTINE GFREED(ID,FR,CH,GFR,GFRD)
C     ====================================
C
C     Hydrogenic free-free Gaunt factor (GFR) and its derivative (GFRD)
C     for depth ID, frequency FR, and charge CH
C
      use accura
      use modelq

      implicit none

      REAL(DP), PARAMETER  :: C14=2.997925e14,
     *                        XMIN=0.2,XMINI=1./XMIN
      REAL(DP), INTENT(IN) :: FR,CH
      REAL(DP), INTENT(OUT):: GFR,GFRD
      REAL(DP)             :: X
      INTEGER, INTENT(IN)  :: ID
C
      X=C14*CH/FR
      IF(X.LT.1.) THEN
         GFR=((GF4(ID)*X-GF3(ID))*X+GF2(ID))*X+GF1(ID)
         GFRD=((GF4D(ID)*X-GF3D(ID))*X+GF2D(ID))*X+GF1D(ID)
       ELSE IF(X.LT.XMINI) THEN
         GFR=GF0(ID)+GF5(ID)*X
         GFRD=GF0D(ID)+GF5D(ID)*X
       ELSE
         GFR=GF6(ID)
         GFRD=GF6D(ID)
      END IF
      RETURN
      END SUBROUTINE GFREED
C
C
C     ****************************************************************
C
C

      REAL(DP) FUNCTION FFCROS(IEL,IFR,T,FR)
C     ----==================================
C
C     Non-standard evaluation of free-free cross section;
C     a user supplied procedure
C
      use accura

      implicit none

      REAL(DP), INTENT(IN) :: T,FR
      REAL(DP)             :: T0,FR0
      INTEGER, INTENT(IN)  :: IEL,IFR
      INTEGER              :: IEL0,IFR0
      FR0=FR
      T0=T
      IEL0=IEL
      IFR0=IFR
      FFCROS=0.
      RETURN
      END FUNCTION FFCROS
C
C
C     ****************************************************************
C
C

      REAL(DP) FUNCTION SFFHMI(POPI,FR,T)
C     ===================================
C  
C     Free-free cross-section for H- (negative hydrogen ion)
C     Taken from Kurucz ATLAS9
C
C     From Bell and Berrington J.Phys.B,vol. 20, 801-806,1987.
C
      use accura
 
      implicit none

      REAL(DP), PARAMETER  :: CONFF=5040.*1.380658E-16, CONTH=5040.
      REAL(DP), PARAMETER  :: HK = 4.79928144D-11
      REAL(DP), SAVE       :: FFLOG(22,11),WFFLOG(22)
      REAL(DP)             :: FFCS(11,22),FFLOG2(22)
      REAL(DP)             :: FFTT(11),THETAFF(11),WAVEK(22)

      REAL(DP), INTENT(IN) :: POPI,FR,T
      REAL(DP)             :: WAVE,WAVELOG,FFTLOG,THETA,FFTH,YLINTP
      INTEGER              :: ISTART,ITHETA,IWAVE
C
      DATA WAVEK/.50,.40,.35,.30,.25,.20,.18,.16,.14,.12,.10,.09,.08,
     * .07,.06,.05,.04,.03,.02,.01,.008,.006/
      DATA THETAFF/
     *  0.5,  0.6, 0.8,  1.0,  1.2,  1.4,  1.6,  1.8,  2.0,  2.8,  3.6/
      DATA FFCS/
     *.0178,.0222,.0308,.0402,.0498,.0596,.0695,.0795,.0896, .131, .172,
     *.0228,.0280,.0388,.0499,.0614,.0732,.0851,.0972, .110, .160, .211,
     *.0277,.0342,.0476,.0615,.0760,.0908, .105, .121, .136, .199, .262,
     *.0364,.0447,.0616,.0789,.0966, .114, .132, .150, .169, .243, .318,
     *.0520,.0633,.0859, .108, .131, .154, .178, .201, .225, .321, .418,
     *.0791,.0959, .129, .161, .194, .227, .260, .293, .327, .463, .602,
     *.0965, .117, .157, .195, .234, .272, .311, .351, .390, .549, .711,
     * .121, .146, .195, .241, .288, .334, .381, .428, .475, .667, .861,
     * .154, .188, .249, .309, .367, .424, .482, .539, .597, .830, 1.07,
     * .208, .250, .332, .409, .484, .557, .630, .702, .774, 1.06, 1.36,
     * .293, .354, .468, .576, .677, .777, .874, .969, 1.06, 1.45, 1.83,
     * .358, .432, .572, .702, .825, .943, 1.06, 1.17, 1.28, 1.73, 2.17,
     * .448, .539, .711, .871, 1.02, 1.16, 1.29, 1.43, 1.57, 2.09, 2.60,
     * .579, .699, .924, 1.13, 1.33, 1.51, 1.69, 1.86, 2.02, 2.67, 3.31,
     * .781, .940, 1.24, 1.52, 1.78, 2.02, 2.26, 2.48, 2.69, 3.52, 4.31,
     * 1.11, 1.34, 1.77, 2.17, 2.53, 2.87, 3.20, 3.51, 3.80, 4.92, 5.97,
     * 1.73, 2.08, 2.74, 3.37, 3.90, 4.50, 5.01, 5.50, 5.95, 7.59, 9.06,
     * 3.04, 3.65, 4.80, 5.86, 6.86, 7.79, 8.67, 9.50, 10.3, 13.2, 15.6,
     * 6.79, 8.16, 10.7, 13.1, 15.3, 17.4, 19.4, 21.2, 23.0, 29.5, 35.0,
     * 27.0, 32.4, 42.6, 51.9, 60.7, 68.9, 76.8, 84.2, 91.4, 117., 140.,
     * 42.3, 50.6, 66.4, 80.8, 94.5, 107., 120., 131., 142., 183., 219.,
     * 75.1, 90.0, 118., 144., 168., 191., 212., 234., 253., 325., 388./
      DATA ISTART/0/
C
      IF(ISTART.EQ.0) THEN
         ISTART=1
         DO IWAVE=1,22
            WFFLOG(IWAVE)=LOG(91.134D0/WAVEK(IWAVE))
            DO ITHETA=1,11
               FFLOG(IWAVE,ITHETA)=LOG(FFCS(ITHETA,IWAVE)*1.E-26)
            END DO
         END DO
      ENDIF
C
      WAVE=2.99792458E17/FR
      WAVELOG=LOG(WAVE)
C
      DO ITHETA=1,11
         DO IWAVE=1,22
            FFLOG2(IWAVE)=FFLOG(IWAVE,ITHETA)
         END DO
         FFTLOG=YLINTP(WAVELOG,WFFLOG,FFLOG2,22,22)
         FFTT(ITHETA)=EXP(FFTLOG)/THETAFF(ITHETA)*CONFF
      END DO
c
      THETA=CONTH/T
      FFTH=YLINTP(THETA,THETAFF,FFTT,11,11)
      SFFHMI=FFTH*POPI/(1.-EXP(-HK*FR/T))

      RETURN
      END FUNCTION SFFHMI
C
C
C     ****************************************************************
C
C
      REAL(DP) FUNCTION CROSS(IBFT,IJ)
C     ================================
C
C     Evaluation of the photoionization cross-section
C     IBF - index ot the b-f transition
C     IJ  - frequency index
C
      use accura
      use modelq
 
      implicit none

      INTEGER, INTENT(IN) :: IBFT,IJ
      INTEGER             :: IJ0
      REAL(DP)            :: A1
C
      IJ0=IJBF(IJ)
      A1=AIJBF(IJ)
      CROSS=A1*BFCS(IBFT,IJ0)+(1.-A1)*BFCS(IBFT,IJ0+1)
c
      RETURN
      END FUNCTION CROSS
C
C
C     ****************************************************************
C
C
      REAL(DP) FUNCTION CROSSD(IBFT,IJ,ID)
C     ====================================
C
C     Evaluation of the photoionization cross-section
C     IBF - index ot the b-f transition
C     IJ  - frequency index
C
      use accura
      use basics
      use atomic
      use modelq

      implicit none

      INTEGER, INTENT(IN) :: IBFT,IJ,ID
      INTEGER             :: IJ0,ITR,I,ION
      REAL(DP)            :: A1
C
      IJ0=IJBF(IJ)
      A1=AIJBF(IJ)
      CROSSD=A1*BFCS(IBFT,IJ0)+(UN-A1)*BFCS(IBFT,IJ0+1)
c
c     contribution from dielectronic recombination
c
      if(ifdiel.eq.0) return
      ITR=ITRBF(IBFT)
      if(idiel(itr).gt.0.and.id.gt.0) then
         i=ilow(itr)
         ion=iel(i)
         if(i.eq.nfirst(ion).and.iup(itr).eq.nnext(ion)) then
            if(freq(ij).ge.fr0(itr).and.freq(ij).le.fr0(itr)*1.1)
     *      crossd=crossd+diesig(ion,id)
         end if
      end if
c
      RETURN
      END FUNCTION CROSSD
C
C
C     ****************************************************************
C
C
      SUBROUTINE DIETOT
C     =================
C
C     modification of the photoionization cross-section
C     for taking into account dielectronic recombination
C
      use accura
      use basics
      use atomic
      use modelq

      implicit none

      REAL(DP) :: T,XPX,DIRT,SIG0
      INTEGER  :: ION,I,IA,ID,IO

      do ion=1,nion
         i=nfirst(ion)
         ia=numat(iatm(i))
         io=iz(ion)
         do id=1,nd
            t=temp(id)
            xpx=dens(id)/wmm(id)/ytot(id)
            call dielrc(ia,io,t,xpx,dirt,sig0)
            diesig(ion,id)=sig0
         end do
      end do
      return
      end subroutine dietot
C
C
C     ****************************************************************
C
C

      subroutine dielrc(iatom,iont,temp,xpx,dirt,sig0)
c     ================================================
c
c Modification of Tim Kallman's XSTAR routine rrrec to calculate dielectronic
c recombination rates (only) to individual ionic species (modified by Omer
c Blaes 5-8-98)
c
c Here temp=temperature in K, xpx is the number density of atomic nuclei in
c cm^{-3} (hydrogen density=xpx/1.1, helium density=xpx*0.1/1.1),
c dirt  =the dielectronic rate in cm^3/s,
c sig0  = the value of sigma_0, the corresponding pseudo-cross-section
c iatom - atomic number (1=H, 2=He, 6=C, etc.)
c iont  - ionization stage (1 for neutrals, 2 for once ionized, etc.)
c
c     this routine computes radiative recombination rates, both rr
c     and dr.  rates are output in units of cm**3/s for each ion
c     stage, where ions are numbered from 1-168:
c       1=HI, 2=HeI, 3=HeII, 4=C I, 5=C II, ..., 9=C VI, 10=N I, ...,
c       16=N VII, 17=O I, ..., 24=O VIII, 25=Ne I, ..., 34=Ne X,
c       35=Mg I, ..., 46=Mg XII, 47=Si I, ..., 60=Si XIV, 61=S I, ...,
c       76=S XVI, 77=Ar I, ..., 94=Ar XVIII, 95=Ca I, ... 114=Ca XX,
c       115=Fe I, ..., 140=Fe XXVI, 141=Ni I, ... 168=Ni XXVIII.
