     *              0.0000, 0.0238, 0.0659, 0.0349, 0.5334,
     *             -0.0036, 0.7519, 1.5252,-0.0838, 0.2769,
     *              0.0000,21.8790,16.2730,-0.7020, 1.1899,
     *              0.0061, 0.2269,32.1419, 1.9939,-0.0646,
     *             -2.8425, 0.2283,40.4072,-3.4956, 1.7558,
     *               5*0./
c
      data uu/109.6787, 27*0.,
     *        198.3108,438.9089,26*0.,
     *        28*0.,
     *        28*0.,
     *        28*0.,
     *        90.82,196.665,386.241,520.178,3162.395,3952.06,
     *        22*0.,
     *        117.225,238.751,382.704,624.866,789.537,4452.758,
     *        5380.089,21*0.,
     *        109.837,283.24,443.086,624.384,918.657,1114.008,
     *        5963.135,7028.393,20*0.,
     *        28*0.,
     *        173.93,330.391,511.8,783.3,1018.,1273.8,1671.792,
     *        1928.462,9645.005,10986.876,18*0.,
     *        28*0.,
     *        61.671,121.268,646.41,881.1,1139.4,1504.3,1814.3,2144.7,
     *        2645.2,2964.4,14210.261,15829.951,16*0.,
     *        28*0.,
     *        65.748,131.838,270.139,364.093,1345.1,1653.9,1988.4,
     *        2445.3,2831.9,3237.8,3839.8,4222.4,19661.693,21560.63,
     *        14*0.,
     *        28*0.,
     *        83.558,188.2,280.9,381.541,586.2,710.184,2265.9,2647.4,
     *        3057.7,3606.1,4071.4,4554.3,5255.9,5703.6,26002.663,
     *        28182.535,12*0.,
     *        28*0.,
     *        127.11,222.848,328.6,482.4,605.1,734.04,1002.73,1157.08,
     *        3407.3,3860.9,4347.,4986.6,5533.8,6095.5,6894.2,7404.4,
     *        33237.173,35699.936,10*0.,
     *        28*0.,
     *        49.306,95.752,410.642,542.6,681.6,877.4,1026.,1187.6,
     *        1520.64,1704.047,4774.,5301.,5861.,6595.,7215.,7860.,
     *        8770.,9338.,41366.,44177.4,8*0.,
     *        28*0.,
     *        28*0.,
     *        28*0.,
     *        28*0.,
     *        28*0.,
     *        63.737,130.563,247.22,442.,605.,799.,1008.,1218.38,
     *        1884.,2114.,2341.,2668.,2912.,3163.,3686.,3946.82,
     *        10180.,10985.,11850.,12708.,13620.,14510.,15797.,
     *        16500.,71203.,74829.,2*0.,
     *        28*0.,
     *        61.6,146.542,283.8,443.,613.5,870.,1070.,1310.,1560.,
     *        1812.,2589.,2840.,3100.,3470.,3740.,4020.,4606.,
     *        4896.2,12430.,13290.,14160.,15280.,16220.,17190.,
     *        18510.,19351.,82984.,86909.4/
c
c Tim Kallman works with temperatures in units of 10^4 K
c
      t=temp/1.e4
      dirt=0.
      ini=inid(iont,iatom)
      if(ini.le.0) return
c
      ekt = t*(0.861707)
      xst = sqrt(t)
      hconst = hfrac*ekt*ergsev
      t3s2=1./(t*xst)
      tmr = 1.e-6*t3s2
      alogt = log10(t)
      kk = 0
      ist=1
      j=ini
      dirt = 0.
c     dr for iron from Arnaud and Raymond
      if(j.ge.115.and.j.le.139 ) then
            kk = kk + 1
            do n = 1,4
               dirt = dirt + dcfe(kk,n)*expo(-defe(kk,n)/ekt)
            end do
            dirt = dirt*tmr
         else
c           aldrovandi and Pequignot rates
c           The reference is Aldrovandi, S. M. V. and P\'equignot, D. (1973)
c           A&A, 25, 137
c
c          ap is the density dependent correction to dr from Raymond
c
            enn = xpx**(0.2)
            ap = 1./(1.+cdd(j)*enn)
            dirt = adi(j)*ap*cc1*expo(-t0(j)/t)
     *                *(1.+bdi(j)*expo(-t1(j)/t))
     *                /(t*sqrt(t))
            dirtemp=0.
c           storey dr rates
            if((j.eq.istorey(ist)-1).and.t.gt.6..and.ist.gt.12) then
              dirtemp=
     *          (1.e-12)*(rstorey(1,ist)/t+rstorey(2,ist)
     *          +t*(rstorey(3,ist)+t*rstorey(4,ist)))*t3s2
     *          *expo(-rstorey(5,ist)/t)
              dirt=dirt+dirtemp
              ist=ist+1
           end if
      end if
c
c     pseudo cross-section
c
      gg=1.
      if(iatom.le.20) then
         gp=gli(iont+1)
       if(gp.le.0) gp=1.
         gg=gp/gli(iont)
       else if(iatom.le.26) then
         gp=gfe(iont+1)
       if(gp.le.0) gp=1.
         gg=gp/gfe(iont)
       else if(iatom.le.28) then
         gp=gni(iont+1)
       if(gp.le.0) gp=1.
         gg=gp/gni(iont)
      end if
      frq0=cons*uu(iont,iatom)
      frq1=1.1*frq0
      delfr=frq1-frq0
      fra=0.5*(frq0+frq1)
      x=1.-expo(-4.79928e-11*delfr/temp)
      sig0=dirt*8.47272e24*gg*sqrt(temp)/fra**2/x
      return
      end subroutine dielrc
C
C ************************************************************************
C
c
      real(dp) function expo(x)
c     =========================
c
      use accura
      implicit none

      real(dp), parameter :: crit=80.
      real(dp)            :: x

      if(x.lt.-crit) x=-crit
      if(x.gt.crit) x=crit
      expo=exp(x)
      return
      end function expo
c
C
C
C ************************************************************************
C
c

      SUBROUTINE DIVSTR(IAH)
C     ======================
C
C     Auxiliary procedure for STARKA - determination of the division
C     point between Doppler and asymptotic Stark profiles
C
C     Input:  BETAD - Doppler width in beta units
C     Output: A     - auxiliary parameter
C                     A=1.5*LOG(BETAD)-1.671
C             DIV   - only for A > 1; division point between Doppler
C                     and asymptotic Stark wing, expressed in units
C                     of betad.
C                     DIV = solution of equation
C                     exp(-(beta/betad)**2)/betad/sqrt(pi)=3*beta**-5/2
C
C     He II: different definition of parameter ADH !
C
      use accura
      use modelq

      implicit none

      REAL(DP), PARAMETER :: UNQ=1.25,UNH=1.5,TWH=2.5,FO=4.,FI=5.,
     *                       CA=1.671,BL=5.821,AL=1.26,CX=0.28,DX=1.e-4,
     *                       CA2=0.978,XA2=0.69314718
      INTEGER, INTENT(IN) :: IAH
      REAL(DP)            :: X,XN,X2
      INTEGER             :: I

C
      ADH=UNH*LOG(BETAD)-CA
      IF(IAH.EQ.2) ADH=ADH+XA2
      IF(BETAD.LT.BL) RETURN
      IF(ADH.GE.AL) THEN
         X=SQRT(ADH)*(1.+UNQ*LOG(ADH)/(FO*ADH-FI))
      ELSE
         X=SQRT(CX+ADH)
      ENDIF
      DO I=1,5
         X2=X*X
         XN=X*(1.-(X2-TWH*LOG(X)-ADH)/(2.*X2-TWH))
         IF(ABS(XN-X).LE.DX) EXIT
         X=XN
      END DO
      DIVH=X
      RETURN
      END SUBROUTINE DIVSTR
C
C
C ************************************************************************
C
c

      SUBROUTINE DOPGAM(ITR,ID,T,DOP,AGAM)
C     ====================================
C
C     Doppler width and the Voigt damping parameter for the line ITR
C
C     Input:
C      ITR   - index of transition
C      ID    - depth index
C      T     - temperature
C     Output:
C      DOP   - Doppler width
C      AGAM  - total damping parameter (in units of Doppler widths;
C              ie. = gam/4pi/DOP, where gam is the "physical" damping
C              parameter expresed in circular frequencies)
C
C     Damping parameter is calculated only for transitions with
C     |IPROF(ITR)| = 1 (ie. those for which either Voigt or some non-
C     standard profile is assumed)
C     Determination of AGAM:
C     is controlled by input parameters transmitted by COMMON/VOIPAR:
C
C      GAMAR(IP)        - for > 0  - has the meaning of natural damping
C                                    parameter (=Einstein coefficient for
C                                    spontaneous emission)
C                             = 0  - classical natural damping assumed
C                             < 0  - damping is given by a non-standard,
C                                    user supplied procedure GAMSP
C      STARK1(IP)       -     = 0  - Stark broadening neglected
C                             < 0  - scaled classical expression
C                                    (ie gam = -STARK1 * classical Stark)
C                             > 0  - Stark broadening given by
C                                    n(el)*[STARK1*T**STARK2 + STARK3]
C      STRAK2, STARK3   -   see above
C      VDWH(IP)         -   .le.0  - Van der Waals broadening neglected
C                             > 0  - scaled classical expression
C
C      the corresponding index IP is given by ITRA(IUP(ITR),ILOW(ITR))
C
      use accura
      use atomic
      use basics
      use modelq

      implicit none

      REAL(DP), PARAMETER  :: BOL2=2.76108e-16, CIN=UN/2.997925e10,
     *                        R02=2.5,R12=45.,OP4=0.4,VW0=4.5E-9
      REAL(DP), INTENT(IN) :: T
      INTEGER, INTENT(IN)  :: ITR,ID
      REAL(DP), INTENT(OUT):: DOP,AGAM
 
      REAL(DP) :: FR,AM,ANE,Z,ANFF,AH,AHE,VDWC,R2,GW0
      INTEGER  :: J,IAT,IE,IP

      J=IUP(ITR)
      IAT=IATM(J)
      FR=FR0(ITR)
      IE=IEL(J)
      AM=BOL2/AMASS(IAT)*T
      AGAM=0.
C
C     Doppler width
C
      DOP=FR*CIN*SQRT(AM+VTURBS(ID)*VTURBS(ID))
C
C     -----------------
C     damping parameter - only for IPROF = 1
C
!     IF(IABS(IPROF0(ITR)).NE.1) RETURN
      IF(IABS(IPROF(ITR)).NE.1) RETURN
      IP=ITRA(J,ILOW(ITR))
      ANE=ELEC(ID)
C
C     Natural (radiation) broadening
C
      If(GAMAR(IP).GT.0.) THEN
         AGAM=GAMAR(IP)
       ELSE IF (GAMAR(IP).GE.-1.1) THEN
         AGAM=2.47342D-22*FR*FR
CC     ELSE
C
C        Non-standard expression - for the total damping parameter,
C        not only for radiation damping
C
CC       CALL GAMSP(ITR,T,ANE,AGAM)
      END IF
c     if(id.eq.1.and.itr.ge.55.and.itr.le.59)
c     if(id.eq.1)
c     if(id.eq.1.and.itr.ge.344.and.itr.le.346)
c    * write(*,"('gra',2i5,1p2e11.3)") itr,ip,gamar(ip),agam
C
C     Stark broadening
C
      Z=FLOAT(IZ(IE))
      ANFF=Z*Z*EH/ENION(J)
      IF(STARK1(IP).LT.0..AND.ANFF.GT.0.) THEN
         AGAM=AGAM+1.e-8*ANFF**2.5*ANE*ABS(STARK1(IP))
       ELSE IF (STARK1(IP).GT.0.) THEN
         AGAM=AGAM+ANE*(STARK1(IP)*T**STARK2(IP)+STARK3(IP))
      END IF
c     if(id.eq.1.and.itr.ge.55.and.itr.le.59)
c     if(id.eq.1)
c     if(id.eq.1.and.itr.ge.344.and.itr.le.346)
c    * write(*,"('gst',2i5,1p3e11.3)") itr,ip,stark1(ip),anff,agam
C
C     Van der Waals broadening
C
      IF(IELH.GT.0) THEN
         AH=POPUL(NFIRST(IELH),ID)
       ELSE
         AH=DENS(ID)/WMM(ID)/YTOT(ID)
      END IF
      IF(IELHE1.NE.0) THEN
         AHE=AH*ABUND(IATHE,ID)
       ELSE
         AHE=AH*ABNDD(2,ID)
      END IF
      VDWC=(T*1.E-4)**0.3*(AH+0.42*AHE)
      IF(VDWH(IP).GE.0.) THEN
         IF(IAT.EQ.2) THEN
            R2=0.
          ELSE IF(IAT.LT.21) THEN
            R2=R02*(ANFF/Z)**2
          ELSE IF(IAT.LT.45) then
            R2=(R12-FLOAT(IAT))/Z
          ELSE
            R2=0.5
         END IF
         GW0=VDWC*VW0*R2**OP4
         AGAM=AGAM+GW0
       ELSE IF (VDWH(IP).LT.0.) THEN
         GW0=VDWC*EXP(2.3025851*VDWH(IP))
         AGAM=AGAM+GW0
      END IF
c     if(id.eq.1) write(*,"('gvw',2i5,1p3e11.3)") itr,ip,gw0,dop,agam
c
C     Total damping parameter in units of Doppler widths
C
      AGAM=AGAM/DOP/12.566370614
      RETURN
      END SUBROUTINE DOPGAM

C
C
C ************************************************************************
C
c

      REAL(DP) FUNCTION STARKA(BETA,FAC)
C     ==================================
C
C     Approximate expressions for the hydrogen Stark profile
C
C     Input: BETA  - delta lambda in beta units,
C            BETAD - Doppler width in beta units
C            A     - auxiliary parameter
C                    A=1.5*LOG(BETAD)-1.761
C            DIV   - only for A > 1; division point between Doppler
C                    and asymptotic Stark wing, expressed in units
C                    of betad.
C                    DIV = solution of equation
C                    exp(-(beta/betad)**2)/betad/sqrt(pi)=
C                     = 1.5*FAC*beta**-5/2
C                    (ie. the point where Doppler profile is equal to
C                     the asymptotic Holtsmark)
C                    In order to save computer time, the division point
C                    DIV is calculated in advance by routine DIVSTR.
C            FAC   - Multiplicative factor (2. for H I; 1. for He II)
C
      use accura
      use basics
      use modelq
 
      implicit none

      REAL(DP), PARAMETER :: F0=-0.5758228,F1=0.4796232,F2=0.07209481,
     *          SD=0.5641895,SLO=-2.5,THRA=1.5,BL1=1.14,BL2=11.4,
     *          SAC=0.08, PISQ1=UN/1.77245385090551,AL=1.26
      REAL(DP), INTENT(IN):: BETA,FAC
      REAL(DP)            :: BETAD1,XD,XL,FL
C
C     for a > 1 Doppler core + asymptotic Holtzmark wing with division
C               point DIV
C
      BETAD1=UN/BETAD
      IF(ADH.GT.AL) THEN
         XD=BETA*BETAD1
         IF(XD.LE.DIVH) THEN
            STARKA=EXP(-XD*XD)*BETAD1*PISQ1
          ELSE
            STARKA=THRA*FAC*EXP(SLO*LOG(BETA))
         END IF
       ELSE
C
C     empirical formula for a < 1
C
         IF(BETA.LE.BL1) THEN
            STARKA=SAC
          ELSE IF(BETA.LT.BL2) THEN
            XL=LOG(BETA)
            FL=(F0*XL+F1)*XL
            STARKA=F2*EXP(FL)
          ELSE
            STARKA=THRA*FAC*EXP(SLO*LOG(BETA))
         END IF
      END IF
      RETURN
      END FUNCTION STARKA
C
C
C ************************************************************************
C
c

      real(dp) function starkg(bet,gam)
c     =================================
c
      use accura
      use basics
 
      implicit none
c
      real(dp), intent(in) :: bet,gam
      real(dp) :: tb0(10,10),tb(10,10),gg(10),bb(10),
     *            b8dif(10),b9dif(10),b10dif(10)
      real(dp) :: coefb,coefg,tt1,tt2,prf,betm,gaml
      integer  :: ig,ig1,ig2,ib,ib1,ib2,i

      data gg/0., 0.5, 1., 1.5, 2., 3., 4.,  5.,  7., 10./
      data bb/0., 0.5, 1., 2.,  3., 5., 7., 10., 15., 20./
      data b8dif/3*3.,7*2./
      data b9dif/8*3.,2*2./
      data b10dif/4.,9*3./
      data tb0/
     * 0.004,.963,.912,.874,.837,.768,.706,.651,.556,0.440,
     * 0.000,.958,.911,.872,.834,.766,.704,.649,.554,0.439,
     * 0.992,.943,.905,.864,.826,.759,.699,.646,.552,0.438,
     * 0.936,.912,.862,.826,.794,.733,.678,.628,.540,0.430,
     * 0.846,.828,.794,.768,.742,.692,.645,.600,.520,0.417,
     * 0.591,.579,.588,.592,.588,.570,.545,.518,.461,0.379,
     * 0.292,.313,.356,.385,.402,.415,.417,.410,.382,0.324,
     * 0.860,.975,.050,.092,.123,.175,.208,.228,.242,0.228,
     * 0.370,.455,.580,.666,.729,.822,.888,.938,.001,0.043,
     * 0.996,.159,.252,.354,.434,.550,.633,.698,.786,0.864/
 
      do ig=1,10
         do ib=1,7
            tb(ig,ib)=tb0(ig,ib)-2.
         end do
         tb(ig,8)=tb0(ig,8)-b8dif(ig)
         tb(ig,9)=tb0(ig,9)-b9dif(ig)
         tb(ig,10)=tb0(ig,10)-b10dif(ig)
      end do
      tb(1,1)=tb(1,1)+1.
      tb(1,2)=tb(1,2)+1.
 
      if(bet.lt.20.) then
         ib=1
         do i=2,10
            if(bet.lt.bb(i)) exit
            ib=i
         end do

         ib1=ib
         ib2=ib+1
         coefb=(bet-bb(ib))/(bb(ib2)-bb(ib1))
 
         if(gam.le.10.) then
            ig=1
            do i=2,10
               if(gam.lt.gg(i)) exit
               ig=i
            end do
            ig1=ig
            ig2=ig+1
            coefg=(gam-gg(ig))/(gg(ig2)-gg(ig1))
            tt1=coefg*tb(ig1,ib2)+(1.-coefg)*tb(ig1,ib1)
            tt2=coefg*tb(ig2,ib2)+(1.-coefg)*tb(ig2,ib1)
            prf=coefb*tt2+(1.-coefb)*tt1
          else
            betm=bb(10)
            prf=1.5/betm**2.5+gam/(3.141593/betm**2)
            gaml=log10(gam)
            tt1=tb(10,ib1)+gaml-1.
            tt2=tb(10,ib2)+gaml-1.
            prf=coefb*tt2+(1.-coefb)*tt1
         end if
         prf=10.**prf
       else
         prf=1.5/bet**2.5+gam/(3.141593*bet**2)
c        bet2=1./bet**2
c        prf=1.5*bet2/sqrt(bet) + gam/3.1415925*bet2
      end if
c
c     if(betad.gt.20) then
c        xd=bet/betad
c        if(xd.lt.20.) prf=max(0.5642/betad*exp(-xd**2),prf)
c     end if
      starkg=prf
c
      return
      end function starkg
C        
C ************************************************************************
C
c     

      SUBROUTINE TDPINI
C     =================
C
C     initialization of only temperature dependent quantities
C
      use accura
c     use alipar
c     use atomic
      use basics
      use modelq
c     use odfpar

      implicit none

      REAL(DP), PARAMETER :: CFF1=1.3727e-25,CFF2=4.3748e-10,
     *                       CFF3=2.5993e-7,SGFF0 = 3.694e8

      REAL(DP) :: T,T1
      INTEGER  :: ID
C
C     temperature-dependent quantities
C
      DO ID=1,ND
         T=TEMP(ID)
         T1=UN/T
         HKT1(ID)=HK*T1
         HKT21(ID)=HKT1(ID)*T1
         TK1(ID)=HKT1(ID)/H
         SQT1(ID)=SQRT(T)
         TEMP1(ID)=T1
         CALL GFREE0(ID)
         EMEL1(ID)=UN
      END DO
C
C     delta m (for evaluation of optical depths)
C
      DO ID=1,ND-1
         DELDM(ID)=HALF*(DM(ID+1)-DM(ID))
         deldmz(id)=deldm(id)
         if(izscal.eq.1) deldmz(id)=half*(zd(id)-zd(id+1))
      END DO
      DEDM1=DM(1)/DENS(1)
      EE0=DEDM1*WMM(1)/DENS(1)
      RETURN
      END SUBROUTINE TDPINI
C
C
C     ****************************************************************
C
C
      SUBROUTINE OPACT1(IJ)
C     =====================
C
C     Absorption, emission, and scattering coefficients
C     at frequency IJ and for all depths
C
C     Input: IJ   opacity and emissivity is calculated for the
C                 frequency points with index IJ
C     Output: ABSO1 -  array of absorption coefficient
C             EMIS1 -  array of emission coefficient
C             SCAT1 -  array of scattering coefficient
C
      use accura
      use basics
      use modelq
      
      implicit none
 
      INTEGER,INTENT(IN) :: IJ
      REAL(DP) :: FR,T,RHO,PLAN,AB,SC,SCT
      INTEGER  :: ID

C
      FR=FREQ(IJ)
      DO ID=1,ND
         T=TEMP(ID)
         RHO=DENS(ID)
         HKT1(ID)=HK/T
         XKF(ID)=EXP(-HKT1(ID)*FR)
         XKF1(ID)=UN-XKF(ID)
         XKFB(ID)=XKF(ID)*BNUE(IJ)
         PLAN=XKFB(ID)/XKF1(ID)
         CALL OPCTAB(FR,IJ,ID,T,RHO,AB,SC,SCT,0)
         if(ioptab.lt.0) then
            ABSO1(ID)=AB+sct
            SCAT1(ID)=SCT
            ABSOT(ID)=ABSOT(ID)+ABSO1(ID)/DENS(ID)
          else if(ioptab.gt.0) then
            ABSO1(ID)=ABSO1(ID)+AB
         end if
         EMIS1(ID)=EMIS1(ID)+AB*PLAN
      END DO
      RETURN
      END SUBROUTINE OPACT1
C
C
C     ****************************************************************
C
C
      SUBROUTINE OPACTD(IJ)
C     =====================
C
C     Absorption and emission coefficients, and their derivatives
C
C     This procedure is very similar to OPACT1, the only difference is
C     the evaluation of derivatives
C
C     Input:
C      IJ    - depth index
C     Output:
C      ABSO1 - array of absorption coefficient
C      EMIS1 - array of emission coefficient
C      SCAT1 - array of scattering coefficient
C      Dxxy  - array of derivatives of xx (=AB for absorption, =EM for
C              emission, =SC for scattering) coefficient
C              wrt y (=T for temperature, =N for density)
C
      use accura
CC    use alipar
      use array1
      use basics
CC    use iterat
      use modelq

      implicit none      
 
      INTEGER,INTENT(IN) :: IJ
      REAL(DP), PARAMETER :: DELT=1.e-3, DELR=1.e-3
      REAL(DP) :: FR,T,T1,RHO,RHO1,PLAN,DPLAN,AB,SC,SCT,AB1,SC1,SCT1
      real(DP) :: AB2,SC2,SCT2
      INTEGER  :: IMODF,ID,IJE
C
      imodf=0
      if(ifryb.gt.0) imodf=1
      FR=FREQ(IJ)
      DO ID=1,ND
         T=TEMP(ID)
         T1=T*(UN+DELT)
         RHO=DENS(ID)
         RHO1=RHO*(UN+DELR)
         XKF(ID)=EXP(-HKT1(ID)*FR)
         XKF1(ID)=UN-XKF(ID)
         XKFB(ID)=XKF(ID)*BNUE(IJ)
         PLAN=XKFB(ID)/XKF1(ID)
         DPLAN=PLAN/XKF1(ID)*HKT1(ID)*FR/T
         CALL OPCTAB(FR,IJ,ID,T,RHO,AB,SC,SCT,imodf)
         CALL OPCTAB(FR,IJ,ID,T1,RHO,AB1,SC1,SCT1,imodf)
         CALL OPCTAB(FR,IJ,ID,T,RHO1,AB2,SC2,SCT2,imodf)
         ABSO1(ID)=AB+sct
         SCAT1(ID)=SCT
         EMIS1(ID)=AB*PLAN
         ABSOT(ID)=ABSO1(ID)
         IF(IMODF.EQ.0) ABSOT(ID)=ABSO1(ID)/DENS(ID)
c
c        derivatives w.r.t. temperature
c
         DABT1(ID)=(AB1-AB)/T/DELT
         DEMT1(ID)=AB*DPLAN+DABT1(ID)*PLAN
         DSCT1(ID)=(SCT1-SCT)/T/DELT
         dabt1(id)=dabt1(id)+dsct1(id)
         if(ifryb.gt.0) then
c
c        derivatives w.r.t. density
c
         DABN1(ID)=(AB2-AB)/RHO/DELR
         DEMN1(ID)=DABN1(ID)*PLAN
         DSCN1(ID)=(SCT2-SCT)/RHO/DELR
         dabn1(id)=dabn1(id)+dscn1(id)
c
c        modify derivatives  in case density is not a state parameter
c
         IF(INHE.LE.0) THEN
            DABT1(ID)=DABT1(ID)+DABN1(ID)*DRHODT(ID)
            DEMT1(ID)=DEMT1(ID)+DEMN1(ID)*DRHODT(ID)
            DSCT1(ID)=DSCT1(ID)+DSCN1(ID)*DRHODT(ID)
            DABN1(ID)=0.
            DEMN1(ID)=0.
            DSCN1(ID)=0.
         END IF
         end if
      END DO
C
C     store quantities for explicit (linearized) frequencies
C
      IF(IJEX(IJ).LE.0.OR.IFRYB.GT.0) RETURN
      IJE=IJEX(IJ)
      DO ID=1,ND
         ABSOEX(IJE,ID)=ABSO1(ID)
         SCATEX(IJE,ID)=SCAT1(ID)
         EMISEX(IJE,ID)=EMIS1(ID)
         DABTEX(IJE,ID)=DABT1(ID)
         DEMTEX(IJE,ID)=DEMT1(ID)
         DABNEX(IJE,ID)=DABN1(ID)
         DEMNEX(IJE,ID)=DEMN1(ID)
      END DO
C
      RETURN
      END SUBROUTINE OPACTD
C
C
C     ****************************************************************
C
C
      SUBROUTINE OPADD(IJ,ID)
C     =======================
C
C     Additional opacities
C     This is basically user-supplied procedure; here are some more
C     important non-standard opacity sources, namely
C     Rayleigh scattering, H- opacity, H2+ opacity, and additional
C     opacity of He I and He II.
C     Inclusion of these opacities is contolled by switches transmitted
C     by COMMON/OPCKEY - see description in START.
C
C     Input parameters:
C     IJ    - frequency index
C     ID    - depth index
C
C     Output: transmitted by COMMON/OPACAD:
C
C     ABAD  - absorption coefficient (at frequency point IJ and depth ID)
C     EMAD  - emission coefficient (at frequency point IJ and depth ID)
C     SCAD  - scattering coefficient (at frequency point IJ and depth ID)
C     Dxy   - derivatives of x (=A for Absorption, =E for Emission,
C             =S for scattering) coefficient wrt y (=T for temperature,
C             =N for electron density)
C     DDN(I)  - quantity proportional to a derivative of absorption (and
C               emission) coefficient wrt population of I-th level; ie.
C               d(abs)/d(pop) = DDN * [1-exp(-h*nu/kT)]
C               d(em)/d(pop) = DDN * (2h*nu**3/c**2)*exp(-h*nu/kT)
C
C
      use accura
      use atomic
      use basics
      use modelq
      use molec
      
      implicit none

      INTEGER, INTENT(IN) :: IJ,ID 
      REAL(DP), PARAMETER :: FRRAY =  2.463e15_dp,
     *           FRAYHe=  5.150E15_dp,
     *           FRAYH2=  2.922E15_dp,
     *           CLS   =  2.997925e18_dp,
     *           C18   =  2.997925e18_dp,
     *           CR0   =  5.799e-13_dp,
     *           CR1   =  1.422e-6_dp,
     *           CR2   =  2.784_dp,
     *           TENM4 =  1.0e-4_dp,
     *           THM0  =  8.7629e3_dp,
     *           SBHM  =  1.0353e-16_dp,
     *           TRHA  =  1.5_dp,
     *           SFF0  =  1.3727e-25_dp,
     *           SFF1  =  4.3748e-10_dp,
     *           SFFM2 =  -2.5993e-7_dp,
     *           F0HE1 =  3.29e15_dp,
     *           F0HE2 =  1.316e16_dp,
     *           SBH0  =  4.1412e-16_dp,
     *           SG01  =  2.815e-16_dp,
     *           SG02  =  4.504e-15_dp
      REAL(DP) :: AB0,AB1,DAB0,DAB1,DFF,FR,AL,T,DELTAT,ANE,HKT,T32,XHM
      REAL(DP) :: AH,AHP,POPI,SB00,AHE,SG,CROSS,SF,X2,OPH2,SBFCH,SBFOH
      REAL(DP) :: X,X1,FR15,BNX,HKFT,DB,DBF,SB,SFFHMI
      INTEGER  :: NKH,IT,I
      LOGICAL  :: LPRI
C
      AB0=0.
      AB1=0.
      DAB0=0.
      DAB1=0.
      ABAD=0.
      EMAD=0.
      SCAD=0.
      DBF=0.
      DFF=0.
      DAT=0.
      DET=0.
      DAN=0.
      DEN=0.
      DST=0.
      DSN=0.
      DO I=1,NLEVEL
         DDN(I)=0.
      END DO
C
      FR=FREQ(IJ)
      al=2.997925e18/fr
      lpri=ij.eq.1165.and.id.eq.1
      lpri=ij.eq.22.and.id.eq.69
      lpri=.false. 
      nkh=0
      if(ielh.gt.0) then
         N0HN=NFIRST(IELH)
         NKH=NKA(IATH)
      end if
c
      T=TEMP(ID)
      DELTAT=TENM4*T
      ANE=ELEC(ID)
      HKT=HK/T
      T32=UN/T/SQRT(T)
      XHM=THM0/T
      if(ielh.gt.0) then
         ah=popul(n0hn,id)
         ahp=popul(nkh,id)
       else
         ah=anato(1,id)
         ahp=anion(1,id)
      end if
      popi=ah
      SB00=SBHM*T32*EXP(XHM)*POPI*ANE
c
      if(iathe.gt.0) then
         ahe=popul(n0a(iathe),id)
       else
         ahe=anato(2,id)
      end if
      if(lpri) write(6,"('ah,ahp,ahe',1p3e12.4)") ah,ahp,ahe
C
      IT=NCON
C
C   -----------------------
C   HI  Rayleigh scattering
C   -----------------------
C
      IF(IRSCT.NE.0) THEN
         IT=IT+1
         SCAD=AH*CROSS(IT,IJ)
         if(lpri) write(6,"('H-Ray ',2i5,f10.3,1p2e12.4)") 
     *   ij,it,al,ah,scad
      END IF
C
C   -----------------------
C   He I  Rayleigh scattering
C   -----------------------
C
      IF(IRSCHE.NE.0) THEN
         IT=IT+1
         scad=scad+ahe*cross(it,ij)
       if(lpri) write(6,"('He-Ray',2i5,f10.3,1p3e12.4)") 
     * ij,it,al,ahe,ahe*cross(it,ij),scad
      END IF
C
C   -----------------------
C   H2  Rayleigh scattering
C   -----------------------
C
      IF(IRSCH2.NE.0.AND.IFMOL.GT.0) THEN
         IT=IT+1
c      if(lpri) write(*,*) 'IRSCH2',irsch2,it,tmolim
c      if(lpri) write(*,*) 'cross',cross(it,ij)
c      if(lpri) write(*,*) 'anmol(2,id)', anmol(2,id)
         sg=cross(it,ij)*anmol(2,id)
         if(t.lt.tmolim) scad=scad+sg
c      if(lpri) write(*,*) 'IRSCH2',sg
       if(lpri) write(6,"('H2-Ray',2i5,1p4e12.4)") 
     *  ij,it,anmol(2,id),cross(it,ij),sg,scad
      END IF
C
      IF(IOPHMI.GT.0) THEN
C
C   ----------------------------
C   H-  bound-free and free-free
C   ----------------------------
C
         IT=IT+1
         if(t.lt.20000.) then
            SB=SB00*CROSS(IT,IJ)
            SF=SFFHMI(AH,FR,T)*ANE
            AB0=SB+SF
         if(lpri) write(6,"('H-    ',2i5,1p3e12.4)") ij,it,sb,sf,ab0
         end if
      END IF

c     END IF
C
      IF(IOPH2P.GT.0) THEN
C
C   -----------------------------
C   H2+  bound-free and free-free
C   -----------------------------
C
         IT=IT+1
         X2=-CROSS(IT,IJ)/T+CROSS(IT+1,IJ)
         IT=IT+1
         SB=0.
         IF(X2.GT.-150..and.fr.lt.3.28e15.and.t.le.9000.)
     *      SB=AH*EXP(X2)*AHP
         AB0=AB0+SB
         DAB1=SB*CROSS(IT-1,IJ)/T/T
         IF(N0HN.GT.0) DDN(N0HN)=DDN(N0HN)+SB/POPI
         IF(NKH.GT.0) DDN(NKH)=DDN(NKH)+SB/POPUL(NKH,ID)
       if(lpri) write(6,"('H2+   ',2i4,f10.3,1p5e15.7)") 
     *   ij,it,al,sb,ab0,cross(it-1,ij),cross(it,ij),x2
      END IF
C
C   -----------------------------
C   He-  free-free
C   -----------------------------
C
      IF(IOPHEM.GT.0) THEN
         IT=IT+1
         sg=cross(it,ij)*t+cross(it+1,ij)+cross(it+2,ij)/t
         ab0=ab0+sg*ane*ahe
         if(lpri) write(6,"('He-ff ',2i4,1p4e12.4)") 
     *   it,ij,sg,ab0,ane,ahe
      END IF
C
C   -----------------------------
C   H2-  free-free
C   -----------------------------
C
      IF(IOPH2M.NE.0.AND.IFMOL.GT.0.AND.T.LT.TMOLIM) THEN
         call h2minus(t,anmol(2,id),ane,fr,oph2)
         ab1=ab1+oph2
         if(lpri) write(6,"('H2-ff ',2i5,1p2e12.4)") it,ij,oph2,ab1
      END IF

C
C   -----------------------------
C     CH and OH continuuum opacity
C   -----------------------------
C
      if(ifmol.gt.0.and.t.lt.tmolim) then
         if(iopch.gt.0) ab0=ab0+sbfch(fr,t)*anmol(5,id)
         if(lpri) write(6,"('CH    ',1p2e12.4)") anmol(5,id),ab0
         if(iopoh.gt.0) ab0=ab0+sbfoh(fr,t)*anmol(4,id)
         if(lpri) write(6,"('OH    ',1p2e12.4)") anmol(4,id),ab0
C
C     ---------------------------
C     CIA H2-H2 opacity
C     ---------------------------
C
         if(ioh2h2.gt.0) then
            call cia_h2h2(t,anmol(2,id),fr,oph2)
            ab1=ab1+oph2
            if(lpri) write(6,"('CIA H2-H2',1p2e12.4)") oph2,ab1
         end if
C
C     ---------------------------
C     CIA H2-He opacity
C     ---------------------------
C
         if(ioh2he.gt.0) then
            call cia_h2he(t,anmol(2,id),ahe,fr,oph2)
            ab1=ab1+oph2
            if(lpri) write(6,"('CIA H2-He',1p2e12.4)") oph2,ab1
         end if
C
C     ---------------------------
C     CIA H2-H opacity
C     ---------------------------
C
         if(ioh2h.gt.0) then
            call cia_h2h(t,anmol(2,id),ah,fr,oph2)
            ab1=ab1+oph2
            if(lpri) write(6,"('CIA H2-H ',1p2e12.4)") oph2,ab1
         end if
C
C     ---------------------------
C     CIA H-He opacity
C     ---------------------------
C
         if(iohhe.gt.0) then
            call cia_hhe(t,ah,ahe,fr,oph2)
            ab1=ab1+oph2
            if(lpri) write(6,"('CIA H-He ',1p2e12.4)") oph2,ab1
         end if
      end if
C
C     Finally, actual absorption and emission coefficients and
C     their derivatives

      X=EXP(-HKT*FR)
      X1=UN-X
      FR15=FR*1.e-15_dp
      BNX=BN*FR15*FR15*FR15*X
      AB1=AB1/X1
      ABAD=ABAD+AB0+AB1
      EMAD=EMAD+AB0+AB1
c     IF(MODE.EQ.1) THEN
         HKFT=HKT*FR/T
         DB=HKFT*AB0
         DAT=DAB1
         DET=DAB1
         DAN=AB0/ANE
         DEN=AB0/ANE
c     END IF
      if(lpri) write(6,"('opadd ',i4,f10.3,1p7e12.4)") ij,al,
     * abad,emad,scad,dat,det,dan,den
      RETURN
      END SUBROUTINE OPADD
C
C
C     ****************************************************************
C
C
      SUBROUTINE PRD(IJ)
c     ==================
c
c     modification of the line emission coefficient
c     and the scattering coefficient in the case of PRD
c
      use accura
      use atomic
      use basics
      use iterat
      use modelq
      
 
      real(dp), parameter :: a21=4.699e8,pi2=6.28318531,gr=2.*4.8e-8
      integer, intent(in) :: ij
      integer  :: itr,itrp,itrprd,id,ilint,ij0,ijt,ij1,kj
      real(dp) :: fr,dfr,omeg,gra,sg,scalin,scem,a1,a2
      real(dp) :: aji,t,ane,dop,agam
c
      IF(IJ.LE.0) THEN
         do itrp=1,ntrprd
            itr=itrtot(itrp)
            aji=osc0(itr)*g(ilow(itr))/g(iup(itr))*7.42163e-22*
     *   i      fr0(itr)**2
            omeg=0.
            do id=1,nd
               t=temp(id)
               ane=elec(id)
               call dopgam(itr,id,t,dop,agam)
               doptr(itrp,id)=dop
               coher(itrp,id)=0.99
               if(agam.gt.0.) coher(itrp,id)=aji/(12.5664*dop*agam)
               if(coher(itrp,id).gt.0.999) coher(itrp,id)=0.999
c
c              special expression for Lyman-alpha
c
               coher(itrp,id)=aji/(aji+9.8e-8*popul(nfirst(ielh),id)+
     *                     0.667*(gami(2,'iont',omeg,t,ane)+
     *                     gami(2,'elec',omeg,t,ane)))
               rjbar(itrp,id)=pjbar(itrp,id)
            end do
         end do
         return
       ELSE
         FR=FREQ(IJ)
         IF(ISPODF.EQ.0) THEN
            IF(IJLIN(IJ).GT.0) THEN
C
C     the "primary" line at the given frequency
C
               ITR=IJLIN(IJ)
               ITRPRD=IPRD(ITR)
               IF(ITRPRD.GT.0) THEN
                  DFR=ABS(FREQ(IJ)-FR0(ITR))
                  if(ilow(itr).eq.nfirst(ielh)) then
                     omeg=dfr*pi2
                     do id=1,nd
                        gra=a21+gr*popul(nfirst(ielh),id)
                        coher(itrprd,id)=a21/
     *                      (gra+gami(2,'elec',omeg,temp(id),elec(id)))
                     end do
                  end if
                  DO ID=1,ND
                     SG=PRFLIN(ID,IJ)
                     IF(DFR/DOPTR(ITRPRD,ID).LE.XPDIV) SG=0.
                     SCALIN=SG*ABTRA(ITR,ID)*COHER(ITRPRD,ID)
                     SCAT1(ID)=SCAT1(ID)+SCALIN
                     scem=sg*emtra(itr,id)*coher(itrprd,id)*xkfb(id)
                     EMIS1(ID)=EMIS1(ID)-SCEM
                  END DO
               END IF
            END IF
            IF(NLINES(IJ).GT.0) THEN
C
C     the "overlapping" lines at the given frequency
C
               LIN: DO ILINT=1,NLINES(IJ)
                  ITR=ITRLIN(ILINT,IJ)
                  ITRPRD=IPRD(ITR)
                  IF(ITRPRD.EQ.0) CYCLE LIN
                  IJ0=IFR0(ITR)
                  FRLOOP: DO IJT=IJ0,IFR1(ITR)
                     IF(FREQ(IJT).LE.FR) THEN
                        IJ0=IJT
                        EXIT FRLOOP
                     END IF
                  END DO FRLOOP
                  IJ1=IJ0-1
                  A1=(FR-FREQ(IJ0))/(FREQ(IJ1)-FREQ(IJ0))
                  A2=UN-A1
                  DFR=ABS(FREQ(IJ)-FR0(ITR))
                  if(ilow(itr).eq.nfirst(ielh)) then
                     omeg=dfr*pi2
                     do id=1,nd
                        gra=a21+gr*popul(nfirst(ielh),id)
                        coher(itrprd,id)=a21/
     *                  (gra+gami(2,'elec',omeg,temp(id),elec(id)))
                     end do
                  end if
                  DO ID=1,ND
                     SG=A1*PRFLIN(ID,IJ1)+A2*PRFLIN(ID,IJ0)
                     IF(DFR/DOPTR(ITRPRD,ID).LE.XPDIV) SG=0.
                     SCALIN=SG*ABTRA(ITR,ID)*COHER(ITRPRD,ID)
                     scem=sg*emtra(itr,id)*coher(itrprd,id)*xkfb(id)
                     SCAT1(ID)=SCAT1(ID)+SCALIN
                     EMIS1(ID)=EMIS1(ID)-SCEM
                  END DO
               END DO LIN
            END IF
C
C     Opacity sampling option
C
         ELSE
            IF(NLINES(IJ).GT.0) THEN
               LINO: DO ILINT=1,NLINES(IJ)
                  ITR=ITRLIN(ILINT,IJ)
                  ITRPRD=IPRD(ITR)
                  IF(ITRPRD.EQ.0) CYCLE LINO
                  KJ=IJ-IFR0(ITR)+KFR0(ITR)
                  INDXPA=IABS(INDEXP(ITR))
                  IF(INDXPA.NE.3 .AND. INDXPA.NE.4) THEN
                     DFR=ABS(FREQ(IJ)-FR0(ITR))
                     if(ilow(itr).eq.nfirst(ielh)) then
                        omeg=dfr*pi2
                        do id=1,nd
                           gra=a21+gr*popul(nfirst(ielh),id)
                           coher(itrprd,id)=a21/
     *                     (gra+gami(2,'elec',omeg,temp(id),elec(id)))
                        end do
                     end if
                     DO ID=1,ND
                        SG=PRFLIN(ID,KJ)
                        IF(DFR/DOPTR(ITRPRD,ID).LE.XPDIV) SG=0.
                        SCALIN=SG*ABTRA(ITR,ID)*COHER(ITRPRD,ID)
                        scem=sg*emtra(itr,id)*coher(itrprd,id)*xkfb(id)
                        SCAT1(ID)=SCAT1(ID)+SCALIN
                        EMIS1(ID)=EMIS1(ID)-SCEM
                     END DO
                  END IF
               END DO LINO
            END IF
         END IF
      END IF
      RETURN

      CONTAINS


      real(dp) function gami(j,aper,omeg,t,ane)
c     =========================================
c
c     function i(j) defined by eqs. (4.5)-(4.9) of
c            cooper, ballagh, and hubeny (1989), ap.j. 344, 949.
c     j    = principal quantum number
c     aper = either 'iont', or 'elec', whether one calculates the
c            ion or electron contribution
c     omeg = delta omega (circular frequency)
c     t    = temperature
c     ane  = electron density (assumed equal to proton density)
c
      use accura
      implicit none

      real(dp), intent(in) :: omeg,t,ane
      integer, intent(in)  :: j
      character(len=4), intent(in) ::  aper
      real(dp) ::  xx(3) = (/0., 50.6205, 68.6112/)
      real(dp) :: x,omegp,amu,omegc,corr,gamp,gam0,gamc
c
      if(omeg.gt.0.) then
         gami=xx(j)*ane/sqrt(omeg)
         return
      end if
c
      x=j*j
      omegp=5.64e4*sqrt(ane)
      amu=1.
      if(aper.eq.'iont') then
         amu=30.2
         omegp=omegp/42.85
      end if
      omegc=1.7455e11*t/amu/amu/j
      corr=0.27-log(8.356e-13*x*amu*amu*ane/t/t)
      gami=3.885e-5*amu*x*ane/sqrt(t)*corr
      if(omeg.lt.omegp) return
      gamp=gami
      gam0=22.58*x**0.75*ane
      gamc=gam0/sqrt(omegc)
      if(omeg.lt.omegc) then
         gami=log(omeg/omegp)/log(omegc/omegp)*log(gamc/gamp)+
     *        log(gamp)
         gami=exp(gami)
       else
         gami=gam0/sqrt(omeg)
      end if
      return
      end function gami


      END SUBROUTINE PRD
c

C
C     ****************************************************************
C
C
      subroutine quasim(ij)
c     =====================
c
c     quasi-molecular opacity for Lyman alpha, beta, gamma
c
      use accura
      use atomic
      use basics
      use modelq
      
      implicit none 
 
      integer, intent(in) :: ij
      real(dp) ::  sgd(mdepth)
      real(dp) :: fr,wlam,t,sg0,a1,a2,sg
      integer  :: ii,jj,jup,itr,id,ilint,itt,ij0,ijt,ij1

      if(iquasi.le.0) return
      fr=freq(ij)
      wlam=2.997925e18/fr
      if(wlam.lt.911..or.wlam.gt.1727.) return
      ii=nfirst(ielh)
c
!     write(*,*) 'quasim',ij,ii,wlam
      do jup=2,iquasi+1
         jj=ii+1
         itr=itra(ii,jj)
         do id=1,nd
            anp=popul(nnext(ielh),id)
            t=temp(id)
            if(tqmprf.gt.0.) t=tqmprf
!           write(*,*) 'qu',id,t,anp,ii,jj,jup
            call allard(wlam,t,popul(ii,id),anp,sg,1,jup)
!           write(*,*) 'q2',id,sg
            sgd(id)=sg
         end do
         if(ijlin(ij).ne.itr) then
            sg0=0.
            do ilint=1,nlines(ij)
               itt=itrlin(ilint,ij)
               if(itt.eq.itr) then
                  IJ0=IFR0(ITR)
                  IJTLOOP: DO IJT=IJ0,IFR1(ITR)
                     IF(FREQ(IJT).LE.FR) THEN
                     IJ0=IJT
                     EXIT IJTLOOP
                     END IF
                  END DO IJTLOOP
                  IJ1=IJ0-1
!                 write(*,*) 'ilint',ilint,itt,ij0,ij1
                  A1=(FR-FREQ(IJ0))/(FREQ(IJ1)-FREQ(IJ0))
                  A2=UN-A1
                  do id=1,nd
                     SG0=A1*PRFLIN(ID,IJ1)+A2*PRFLIN(ID,IJ0)
                 end do
               end if
            end do
         end if
         do id=1,nd
            abso1(id)=abso1(id)+sgd(id)*abtra(itr,id)
            emis1(id)=emis1(id)+sgd(id)*emtra(itr,id)
         end do
      end do
c
      return
      end subroutine quasim
C
C
C     ****************************************************************
C
C

      subroutine cia_h2h(t,ah2,ah,ff,opac)
c     ====================================
c
c     CIA H2-H opacity - data taken from TURBOSPEC
c
      use accura               
      implicit none

      real(dp), intent(in)  :: t,ah2,ah,ff
      real(dp), intent(out) :: opac

      integer, parameter  :: ndatp=67,ntemp=4
      real(dp), parameter :: amagat=2.6867774e19,fac=1./amagat**2
      real(dp), parameter :: CAS=2.997925e10
      real(dp),save ::  fred(ndatp),temp(ntemp),alpha(ndatp,ntemp)
      REAL(DP) :: F,Y1,Y2,Y3,Y4,TT,UU,ALP
      INTEGER  :: IFIRST,I,J

      data temp / 1000. , 1500., 2000. , 2500. /
      data ifirst /0/

c     input frequency in Hz but needed wave numbers in cm^-1
      f=ff/cas
c     read in CIA tables if this is the first call
      if (ifirst.eq.0) then
         write(*,'(a)') 'Reading in H2-H CIA opacity tables...'
         open(10,file="./data/CIA_H2H.dat",status='old')
         do i=1,3
            read (10,*)
         end do
         do i=1,ndatp
            read (10,*) fred(i),(alpha(i,j),j=1,ntemp)
         end do
         close(10)

c     take logarithm of tables prior to doing linear interpolations

         do i=1,ndatp
            do j=1,ntemp
               alpha(i,j)=log(alpha(i,j))
            end do
         end do

         ifirst=1
      end if

c     locate position in temperature array

      if(t.gt.2500.) return
      call locate(temp,ntemp,t,j,ntemp)

      if (j.eq.0) then
         write(*,*)
         write(*,'(a,f6.0,a)')
     *   'Warning: requested temperature is below',temp(1),' K'
         write(*,'(a)') 'CIA H2-H CIA opacity set to zero'
         write(*,*)
         opac=0.
         return
      end if

c     locate position in frequency array
      call locate(fred,ndatp,f,i,ndatp)

c     linearly interpolate in frequency and temperature

      if (j.eq.ntemp) then
c     hold values constant if off high temperature end of table
         y1=alpha(i,j)
         y2=alpha(i+1,j)
         tt=(f-fred(i))/(fred(i+1)-fred(i))
         alp=(1.-tt)*y1 + tt*y2
       else if (i.eq.0 .or. i.eq.ndatp) then
c        set values to a very small number if off frequency table
         alp=-50.
       else
c        interpolate linearly within table
         y1=alpha(i,j)
         y2=alpha(i+1,j)
         y3=alpha(i+1,j+1)
         y4=alpha(i,j+1)

         tt=(f-fred(i))/(fred(i+1)-fred(i))
         uu=(t-temp(j))/(temp(j+1)-temp(j))

         alp=(1.-tt)*(1.-uu)*y1 + tt*(1.-uu)*y2 + tt*uu*y3 +
     *       (1.-tt)*uu*y4
      end if

      alp=exp(alp)

c     final opacity

      opac=fac*ah2*ah*alp
c
      return
      end subroutine cia_h2h
C
C     ****************************************************************
C
C
C
      subroutine cia_h2h2(t,ah2,ff,opac)
c     ===================--=============
c
c     CIA H2-H2 opacity
c     data from Borysow A., Jorgensen U.G., Fu Y. 2001, JQSRT 68, 235
c
      use accura
      implicit none

      real(dp), intent(in)  :: t,ah2,ff
      real(dp), intent(out) :: opac

      integer, parameter  :: ndatp=1000,ntemp=7
      real(dp), parameter :: amagat=2.6867774e19,fac=1./amagat**2
      real(dp), parameter :: CAS=2.997925e10
      real(dp),save ::  fred(ndatp),temp(ntemp),alpha(ndatp,ntemp)
      REAL(DP) :: F,Y1,Y2,Y3,Y4,TT,UU,ALP
      INTEGER  :: IFIRST,I,J

      data temp / 1000. , 2000. , 3000. , 4000. , 5000. , 6000. ,
     *            7000. /
      data ifirst /0/

c     input frequency in Hz but needed wave numbers in cm^-1
      f=ff/cas
c     read in CIA tables if this is the first call
      if (ifirst.eq.0) then
         write(*,'(a)') 'Reading in H2-H2 CIA opacity tables...'
         open(10,file="./data/CIA_H2H2.dat",status='old')
         do i=1,3
            read (10,*)
         end do
         do i=1,ndatp
            read (10,*) fred(i),(alpha(i,j),j=1,ntemp)
         end do
         close(10)

c     take logarithm of tables prior to doing linear interpolations

         do i=1,ndatp
            do j=1,ntemp
               alpha(i,j)=log(alpha(i,j))
            end do
         end do

         ifirst=1
      end if

c     locate position in temperature array
      call locate(temp,ntemp,t,j,ntemp)

      if (j.eq.0) then
         write(*,*)
         write(*,'(a,f6.0,a)')
     *   'Warning: requested temperature is below',temp(1),' K'
         write(*,'(a)') 'CIA H2-H2 opacity set to 0'
         write(*,*)
         opac=0.
         return
      end if

c     locate position in frequency array
      call locate(fred,ndatp,f,i,ndatp)

c     linearly interpolate in frequency and temperature

      if (j.eq.ntemp) then
c     hold values constant if off high temperature end of table
         y1=alpha(i,j)
         y2=alpha(i+1,j)
         tt=(f-fred(i))/(fred(i+1)-fred(i))
         alp=(1.-tt)*y1 + tt*y2
       else if (i.eq.0 .or. i.eq.ndatp) then
c        set values to a very small number if off frequency table
         alp=-50.
       else
c        interpolate linearly within table
         y1=alpha(i,j)
         y2=alpha(i+1,j)
         y3=alpha(i+1,j+1)
         y4=alpha(i,j+1)

         tt=(f-fred(i))/(fred(i+1)-fred(i))
         uu=(t-temp(j))/(temp(j+1)-temp(j))

         alp=(1.-tt)*(1.-uu)*y1 + tt*(1.-uu)*y2 + tt*uu*y3 +
     *       (1.-tt)*uu*y4
      end if

      alp=exp(alp)

c     final opacity

      opac=fac*ah2*ah2*alp
c
      return
      end subroutine cia_h2h2
