      subroutine getlal
c     =================
c
c     getlal reads in the profile functions for Lyman alpha, beta, gamma,
c     and Balmer alpha, including the quasi-molecular satellites;
c     valid for first and second order in neutral and ionized H density
c     modified routine provided originally by D. Koester
c
      use accura
      use basics
      use allarp

      implicit none

      integer  :: i,j,it,nualp

      allocate (xlalp(NXMAX),plalp(NXMAX,NNMAX))
      allocate (xlbet(NXMAX),plbet(NXMAX,NNMAX))
      allocate (xlgam(NXMAX),plgam(NXMAX,NNMAX))
      allocate (xlbal(NXMAX),plbal(NXMAX,NNMAX))
      allocate (xlalpd(NXMAX,NTAMAX),plalpd(NXMAX,NNMAX,NTAMAX),
     *          stnead(ntamax),stnchd(ntamax),
     *          vneuad(ntamax),vchaad(ntamax),
     *          talpd(ntamax),nxalpd(ntamax))
c
c     Lyman alpha
c
      nxalp=0
      nunalp=67
      if(nunalp.gt.0) then
         open(unit=nunalp,file='./data/laquasi.dat',status='old')
         read(nunalp,*) nxalp,stnnea,stncha,vneua,vchaa
         do i=1,nxalp
            read(nunalp,*) xlalp(i),(plalp(i,j),j=1,NNMAX)
         end do
         close(nunalp)
         stnnea=10.0**stnnea
         stncha=10.0**stncha
         iwarna=0
       else if(nunalp.lt.0) then
c
c      input of temperature-dependent profile
c
         nualp=-nunalp
         read(nualp,*) ntalpd
         do it=1,ntalpd
            read(nualp,*) talpd(it)
            read(nualp,*) nxalpd(it),stnead(it),stnchd(it),vneuad(it),
     *                    vchaad(it)
            do i=1,nxalpd(it)
               read(nualp,*) xlalpd(i,it),(plalpd(i,j,it),j=1,NNMAX)
            end do
            stnead(it)=10.0**stnead(it)
            stnchd(it)=10.0**stnchd(it)
         end do
         close(nualp)
      end if
c
c     Lyman beta
c
      nxbet=0
      if(nunbet.gt.0) then
         nunbet=67
         open(unit=nunbet,file='./data/lbquasi.dat',status='old')
         read(nunbet,*) nxbet,stnneb,stnchb,vneub,vchab
         do i=1,nxbet
            read(nunbet,*) xlbet(i),(plbet(i,j),j=1,NNMAX)
         end do
         close(nunbet)
         stnneb=10.0**stnneb
         stnchb=10.0**stnchb
         iwarnb=0
      end if
c
c     Lyman gamma
c
      nxgam=0
      if(nungam.gt.0) then
         nungam=67
         open(unit=nungam,file='./data/lgquasi.dat',status='old')
         read(nungam,*) nxgam,stnneg,stnchg,vneug,vchag
         do i=1,nxgam
            read(nungam,*) xlgam(i),(plgam(i,j),j=1,NNMAX)
         end do
         close(nungam)
         stnneg=10.0**stnneg
         stnchg=10.0**stnchg
         iwarng=0
      end if
c
c     Balmer alpha
c
      nxbal=0
      if(nunbal.gt.0) then
         nunbal=67
         open(unit=nunbal,file='./data/lhquasi.dat',status='old')
         read(nunbal,*) nxbal,stnnec,stnchc,vneuc,vchac
         do i=1,nxbal
            read(nunbal,*) xlbal(i),(plbal(i,j),j=1,NNMAX)
         end do
         close(nunbal)
         stnnec=10.0**stnnec
         stnchc=10.0**stnchc
         iwarnc=0
      end if
      return
      end
C
C
C     ****************************************************************
C
C

      subroutine allard(xl,t,hneutr,hcharg,prof,iq,jq)
c     ================================================
c
c     quasi-molecular opacity for Lyman alpha, beta, and Balmer alpha
c     modified routine provided originally by D. Koester
c
c     Input:  xl:  wavelength in [A]
c             hneutr:  neutral H particle density [cm-3]
c             hcharg: ionized H particle density [cm-3]
c             iq:   quantum number of the lower level
c             jq:   quantum number of the upper level;
c                   =2  -  Lyman alpha
c                   =3  -  Lyman beta
c     Output: prof:  Lyman alpha line profile, normalized to 1.0e8
c             if integrated over A;
c             It then renormalized by multiplying by
c             8.853e-29*lambda_0^2*f_ij
c
      use accura
      use basics
      use allarp

      implicit none

      real(dp), intent(in) :: xl,t,hneutr,hcharg
      real(dp),intent(out) :: prof
      integer, intent(in)  :: iq,jq

      real(dp) :: vn1,vn2,vns,vn11,vn22,vn12,xnorm,a1,p1,p11,p2,p22,p12
      integer  :: jl,ju,jm,j

      prof=0.
!     write(*,*) 'allard',iq,jq,nunalp
!        write(*,*) 'alp',nxalp
!        write(*,*) 'xlalp',shape(xlalp),size(xlalp)
c
c     Lyman alpha
c
      if(iq.eq.1.and.jq.eq.2) then
      if(nunalp.lt.0) then
         call allardt(xl,t,hneutr,hcharg,prof)
       else
         if(xl.lt.xlalp(1).or.xl.gt.xlalp(nxalp)) return
         vn1=hneutr/stnnea
         vn2=hcharg/stncha
         vns=vn1*vneua+vn2*vchaa
         if(iwarna.eq.0) then
            if(vn1*vneua.gt.0.3.or.vn2*vchaa.gt.0.3) then
               write(*,*) '          warning: density too high for',
     *                    ' Lyman alpha expansion'
               iwarna=1
            endif
         endif
         vn11=vn1*vn1
         vn22=vn2*vn2
         vn12=vn1*vn2
         xnorm=1.0/(1.0+vns+0.5*vns*vns)
c
         jl=0
         ju=nxalp+1
         do while (ju-jl.gt.1) 
            jm=(ju+jl)/2
            if((xlalp(nxalp).gt.xlalp(1)).eqv.(xl.gt.xlalp(jm))) then
               jl=jm
            else
               ju=jm
            endif
         end do
         j=jl
!        write(*,*) 'jl,ju',jl,ju
!        write(*,*) 'plalp',shape(plalp),size(plalp)
         
c
         if(j.eq.0) j=1
         if(j.eq.nxalp) j=j-1
         a1=(xl-xlalp(j))/(xlalp(j+1)-xlalp(j))
         p1=  vn1*((1.0-a1)*plalp(j,1)+a1*plalp(j+1,1))
         p11=vn11*((1.0-a1)*plalp(j,2)+a1*plalp(j+1,2))
         p2=  vn2*((1.0-a1)*plalp(j,3)+a1*plalp(j+1,3))
         p22=vn22*((1.0-a1)*plalp(j,4)+a1*plalp(j+1,4))
         p12=vn12*((1.0-a1)*plalp(j,5)+a1*plalp(j+1,5))
         prof=(p1+p2+p11+p22+p12)*xnorm*xnorma
         return
      end if
      end if
c
c     Lyman beta
c
      if(iq.eq.1.and.jq.eq.3) then
         if(nxbet.eq.0) return
         if(xl.lt.xlbet(1).or.xl.gt.xlbet(nxbet)) return
         vn1=hneutr/stnneb
         vn2=hcharg/stnchb
         vns=vn1*vneub+vn2*vchab
         if(iwarnb.eq.0) then
            if(vn1*vneub.gt.0.3.or.vn2*vchab.gt.0.3) then
               write(*,*) '          warning: density too high for',
     *                    ' Lyman beta expansion'
               iwarnb=1
            endif
         endif
         vn11=vn1*vn1
         vn22=vn2*vn2
         vn12=vn1*vn2
         xnorm=1.0/(1.0+vns+0.5*vns*vns)
c
         jl=0
         ju=nxbet+1
 20      if(ju-jl.gt.1) then
            jm=(ju+jl)/2
            if((xlbet(nxbet).gt.xlbet(1)).eqv.(xl.gt.xlbet(jm))) then
               jl=jm
            else
               ju=jm
            endif
            go to 20
         endif
         j=jl
c
         if(j.eq.0) j=1
         if(j.eq.nxbet) j=j-1
         a1=(xl-xlbet(j))/(xlbet(j+1)-xlbet(j))
         p1=  vn1*((1.0-a1)*plbet(j,1)+a1*plbet(j+1,1))
         p11=vn11*((1.0-a1)*plbet(j,2)+a1*plbet(j+1,2))
         p2=  vn2*((1.0-a1)*plbet(j,3)+a1*plbet(j+1,3))
         p22=vn22*((1.0-a1)*plbet(j,4)+a1*plbet(j+1,4))
         p12=vn12*((1.0-a1)*plbet(j,5)+a1*plbet(j+1,5))
         prof=(p1+p2+p11+p22+p12)*xnorm*xnormb
         return
      end if
c
c     Lyman gamma
c
      if(iq.eq.1.and.jq.eq.4) then
         if(nxgam.eq.0) return
         if(xl.lt.xlgam(1).or.xl.gt.xlgam(nxgam)) return
         vn1=hneutr/stnneg
         vn2=hcharg/stnchg
         vns=vn1*vneug+vn2*vchag
         if(iwarng.eq.0) then
            if(vn1*vneug.gt.0.3.or.vn2*vchag.gt.0.3) then
               write(*,*) '          warning: density too high for',
     *                    ' Lyman gamma expansion'
               iwarng=1
            endif
         endif
         vn11=vn1*vn1
         vn22=vn2*vn2
         vn12=vn1*vn2
         xnorm=1.0/(1.0+vns+0.5*vns*vns)
c
         jl=0
         ju=nxgam+1
 30      if(ju-jl.gt.1) then
            jm=(ju+jl)/2
            if((xlgam(nxgam).gt.xlgam(1)).eqv.(xl.gt.xlgam(jm))) then
               jl=jm
            else
               ju=jm
            endif
            go to 30
         endif
         j=jl
c
         if(j.eq.0) j=1
         if(j.eq.nxgam) j=j-1
         a1=(xl-xlgam(j))/(xlgam(j+1)-xlgam(j))
         p1=  vn1*((1.0-a1)*plgam(j,1)+a1*plgam(j+1,1))
         p11=vn11*((1.0-a1)*plgam(j,2)+a1*plgam(j+1,2))
         p2=  vn2*((1.0-a1)*plgam(j,3)+a1*plgam(j+1,3))
         p22=vn22*((1.0-a1)*plgam(j,4)+a1*plgam(j+1,4))
         p12=vn12*((1.0-a1)*plgam(j,5)+a1*plgam(j+1,5))
         prof=(p1+p2+p11+p22+p12)*xnorm*xnormg
         return
      end if
c
c     Balmer alpha
c
      if(iq.eq.2.and.jq.eq.3) then
         if(xl.lt.xlbal(1).or.xl.gt.xlbal(nxbal)) return
         vn1=0.
         vn2=hcharg/stnchc
         vns=vn1*vneuc+vn2*vchac
         vn11=vn1*vn1
         vn22=vn2*vn2
         vn12=vn1*vn2
         xnorm=1.0/(1.0+vns+0.5*vns*vns)
c
         jl=0
         ju=nxbal+1
 40      if(ju-jl.gt.1) then
            jm=(ju+jl)/2
            if((xlbal(nxbal).gt.xlbal(1)).eqv.(xl.gt.xlbal(jm))) then
               jl=jm
            else
               ju=jm
            endif
            go to 40
         endif
         j=jl
c
         if(j.eq.0) j=1
         if(j.eq.nxbal) j=j-1
         a1=(xl-xlbal(j))/(xlbal(j+1)-xlbal(j))
         p1=  vn1*((1.0-a1)*plbal(j,1)+a1*plbal(j+1,1))
         p11=vn11*((1.0-a1)*plbal(j,2)+a1*plbal(j+1,2))
         p2=  vn2*((1.0-a1)*plbal(j,3)+a1*plbal(j+1,3))
         p22=vn22*((1.0-a1)*plbal(j,4)+a1*plbal(j+1,4))
         p12=vn12*((1.0-a1)*plbal(j,5)+a1*plbal(j+1,5))
         prof=(p1+p2+p11+p22+p12)*xnorm*xnormc
      end if
c
      return
      end subroutine allard
C
C
C     ****************************************************************
C
C

      subroutine allardt(xl,t,hneutr,hcharg,prof)
c     ===========================================
c
c     quasi-molecular opacity for Lyman alpha, with T-dependent
c     profile
c
c     Input:  xl:  wavelength in [A]
c             hneutr:  neutral H particle density [cm-3]
c             hcharg: ionized H particle density [cm-3]
c     Output: prof:  Lyman alpha line profile, normalized to 1.0e8
c             if integrated over A;
c             It then renormalized by multiplying by
c             8.853e-29*lambda_0^2*f_ij
c
      use accura
      use basics
      use allarp

      implicit none

      real(dp),intent(in) :: xl,t,hneutr,hcharg
      real(dp),intent(out):: prof
      real(dp) :: vn1,vn2,vns,vn11,vn22,vn12,xnorm,a1,p1,p2,p11,p22,p12
      real(dp) :: prof0,prof1,dt
      integer  :: it,it0,jl,ju,jm,j

      prof=0.
c
c     find the two partial tables close to actual T
c
      it0=0
      do it=1,ntalpd
         it0=it
         if(t.lt.talpd(it)) then
            it0=it-1
            exit
         end if
      end do
      if(it0.eq.0.or.it0.ge.ntalpd) then
         it0=max(it0,1)
         it0=min(it0,ntalpd)
         if(xl.lt.xlalpd(1,it0).or.xl.gt.xlalpd(nxalpd(it0),it0)) return
         vn1=hneutr/stnead(it0)
         vn2=hcharg/stnchd(it0)
         vns=vn1*vneuad(it0)+vn2*vchaad(it0)
         vn11=vn1*vn1
         vn22=vn2*vn2
         vn12=vn1*vn2
         xnorm=1.0/(1.0+vns+0.5*vns*vns)
c
         jl=0
         ju=nxalpd(it0)+1
         do while (ju-jl.gt.1)
            jm=(ju+jl)/2
            if(xl.gt.xlalpd(jm,it0)) then
               jl=jm
            else
               ju=jm
            endif
         end do
         j=jl
c
         if(j.eq.0) j=1
         if(j.eq.nxalpd(it0)) j=j-1
         a1=(xl-xlalpd(j,it0))/(xlalpd(j+1,it0)-xlalpd(j,it0))
         p1=  vn1*((1.0-a1)*plalpd(j,1,it0)+a1*plalpd(j+1,1,it0))
         p11=vn11*((1.0-a1)*plalpd(j,2,it0)+a1*plalpd(j+1,2,it0))
         p2=  vn2*((1.0-a1)*plalpd(j,3,it0)+a1*plalpd(j+1,3,it0))
         p22=vn22*((1.0-a1)*plalpd(j,4,it0)+a1*plalpd(j+1,4,it0))
         p12=vn12*((1.0-a1)*plalpd(j,5,it0)+a1*plalpd(j+1,5,it0))
         prof=(p1+p2+p11+p22+p12)*xnorm*xnorma
c
        else
c
c     interpolate in the tables for different T
c
c     the lower T
c
         if(xl.lt.xlalpd(1,it0).or.xl.gt.xlalpd(nxalpd(it0),it0)) return
         vn1=hneutr/stnead(it0)
         vn2=hcharg/stnchd(it0)
         vns=vn1*vneuad(it0)+vn2*vchaad(it0)
         vn11=vn1*vn1
         vn22=vn2*vn2
         vn12=vn1*vn2
         xnorm=1.0/(1.0+vns+0.5*vns*vns)
         jl=0
         ju=nxalpd(it0)+1
         do while (ju-jl.gt.1) 
            jm=(ju+jl)/2
            if(xl.gt.xlalpd(jm,it0)) then
               jl=jm
            else
               ju=jm
            endif
         end do
         j=jl
c
         if(j.eq.0) j=1
         if(j.eq.nxalpd(it0)) j=j-1
         a1=(xl-xlalpd(j,it0))/(xlalpd(j+1,it0)-xlalpd(j,it0))
         p1=  vn1*((1.0-a1)*plalpd(j,1,it0)+a1*plalpd(j+1,1,it0))
         p11=vn11*((1.0-a1)*plalpd(j,2,it0)+a1*plalpd(j+1,2,it0))
         p2=  vn2*((1.0-a1)*plalpd(j,3,it0)+a1*plalpd(j+1,3,it0))
         p22=vn22*((1.0-a1)*plalpd(j,4,it0)+a1*plalpd(j+1,4,it0))
         p12=vn12*((1.0-a1)*plalpd(j,5,it0)+a1*plalpd(j+1,5,it0))
         prof0=(p1+p2+p11+p22+p12)*xnorm*xnorma
c
c     the higher T
c
         it0=it0+1
         if(xl.lt.xlalpd(1,it0).or.xl.gt.xlalpd(nxalpd(it0),it0)) return
         vn1=hneutr/stnead(it0)
         vn2=hcharg/stnchd(it0)
         vns=vn1*vneuad(it0)+vn2*vchaad(it0)
         vn11=vn1*vn1
         vn22=vn2*vn2
         vn12=vn1*vn2
         xnorm=1.0/(1.0+vns+0.5*vns*vns)
         jl=0
         ju=nxalpd(it0)+1
         do while (ju-jl.gt.1) 
            jm=(ju+jl)/2
            if(xl.gt.xlalpd(jm,it0)) then
               jl=jm
            else
               ju=jm
            endif
         end do
         j=jl
c
         if(j.eq.0) j=1
         if(j.eq.nxalpd(it0)) j=j-1
         a1=(xl-xlalpd(j,it0))/(xlalpd(j+1,it0)-xlalpd(j,it0))
         p1=  vn1*((1.0-a1)*plalpd(j,1,it0)+a1*plalpd(j+1,1,it0))
         p11=vn11*((1.0-a1)*plalpd(j,2,it0)+a1*plalpd(j+1,2,it0))
         p2=  vn2*((1.0-a1)*plalpd(j,3,it0)+a1*plalpd(j+1,3,it0))
         p22=vn22*((1.0-a1)*plalpd(j,4,it0)+a1*plalpd(j+1,4,it0))
         p12=vn12*((1.0-a1)*plalpd(j,5,it0)+a1*plalpd(j+1,5,it0))
         prof1=(p1+p2+p11+p22+p12)*xnorm*xnorma
c
c     final profile coefficient
c
         dt=talpd(it0)-talpd(it0-1)
         prof=(prof0*(talpd(it0)-t)+prof1*(t-talpd(it0-1)))/dt
      end if
c
      return
      end subroutine allardt
C
C
C     ****************************************************************
C
C


!     include 'modules.f'
!     program rat
!     call ratsp1
!     end program rat

C     
C     ***************************************************
c

      SUBROUTINE RATMAT(ID,IICAL,IMODE)
C     =================================
C
C     Evaluation of the rate matrix
C
C
C     Constraint equations:
C        the rows corresponding to the last explicit level of each atom
C        (ie. a one-level ion representing the highest ionization degree
C        of the given atom) are the abundance definition equations
C
C     Input: ID - depth index
C     Input transmitted by COMMON blocks:
C            RRU - array of upward radiative rates in all transitions
C            RRD - array of downward radiative rates in all transitions
C            COLRAT - array of collisional rates (only upward) in all
C                     transitions
C            SBF - array of Saha-Boltzmann factors
C            USUM - array of upper sums
C
C     Output: A - rate matrix
C             B - the right-hand-side vector
C
      use atomic
      use basics
      use modelq
c     use iterat

      implicit none

      INTEGER, INTENT(IN)  :: ID,IMODE,IICAL(MLEVEL)

      REAL(DP) ::  AIJ(MTRANS),AJI(MTRANS),SBW(MLEVEL)
      LOGICAL  ::  LLTE(MLEVEL)

      REAL(DP) :: T,ANE,HKT,TK,SUM,CORR
      INTEGER  :: IAT,ITR,I,ILT,J,NKE,II,JJ,NREFI,JJJ,IL,III,N,
     *            NREFII
      LOGICAL  :: LLT
c
      if(ioptab.lt.0.or.iopfrc.gt.0) return
c
      if(ipslte.ne.0) then
         do itr=1,ntrans
            rru(itr,id)=0.
            rrd(itr,id)=0.
            drdt(itr,id)=0.
         end do
      end if
c
      T=TEMP(ID)
      ANE=ELEC(ID)
      HKT=HK/T
      TK=HKT/H
      DO I=1,NLEVEL
         BESE(I)=0.
         SBW(I)=ANE*SBF(I)*WOP(I,ID)
         ILT=ILTION(IEL(I))
         LLT=ILT.EQ.1.AND.IMODE.EQ.0
         LLTE(I)=LLT.OR.LTE.OR.ILTLEV(I).GE.1.OR.ILT.GE.2
         LLTE(I)=LLTE(I).OR.ID.GE.IDLTE
         DO J=1,NLEVEL
            ESEMAT(J,I)=0.
         END DO
      END DO
C
C     determine reference levels
C
      CALL REFLEV(ID,IABS(IMODE))
C
C ******* First part - the rows corresponding to true statistical
C                      equilibrium equations
C                      i.e. NLTE rate equations
C
C     1) simple expression in the case of LTE
C
      DO IAT=1,NATOM
         IF(IIFIX(IAT).NE.1.OR.IMODE.LT.0) THEN
            NREFI=NREFS(IAT,ID)
            DO I=N0A(IAT),NKA(IAT)
               II=IABS(IICAL(I))
               IF(I.NE.NREFI.AND.II.NE.0.AND.LLTE(I)) THEN
                  ESEMAT(II,II)=UN
                  N=IABS(IICAL(ILTERF(I,ID)))
                  ESEMAT(II,N)=ESEMAT(II,N)-SBLPSI(I,ID)
               END IF
c      if(id.ge.nd-1) 
c    * write(*,"('ratmat',7i3,1p3e12.4)") 
c    * id,i,ii,nrefi,iltref(i,id),ilterf(i,id),iical(ilterf(i,id)),
c    * sblpsi(i,id),sbf(i),wop(i,id)
            END DO
         END IF
      END DO
C
C     2) NLTE rate equation
C
       IF(.NOT.LTE) THEN
          DO ITR=1,NTRANS
             I=ILOW(ITR)
             IF(IIFIX(IATM(I)).EQ.1) CYClE
             J=IUP(ITR)
             NKE=NNEXT(IEL(I))
C
C            upward total rate
C
             AIJ(ITR)=(COLRAT(ITR,ID)+RRU(ITR,ID))*WOP(J,ID)
C
C            downward total rate
C
             IF(LINE(ITR)) THEN
C
C               bound-bound
C
                AJI(ITR)=(COLTAR(ITR,ID)+RRD(ITR,ID)*
     *               G(I)/G(J)*EXP(HKT*FR0(ITR)))*WOP(I,ID)
c    *               G(I)/G(J))*WOP(I,ID)
             ELSE
C
C               Bound-free
C               Quantity CORR is a factor which allows the bound-free
C               transition to end at an excited state
C
                CORR=UN
                IF(NKE.NE.J) CORR=G(NKE)/G(J)*
     *               EXP((ENION(NKE)-ENION(J))*TK)
                AJI(ITR)=COLTAR(ITR,ID)*WOP(I,ID)+
     *                   RRD(ITR,ID)*SBW(I)*CORR
             END IF

c     if(id.eq.39) then
c     if(i.le.4.or.(i.ge.11.and.i.le.13).or.(i.ge.25.and.i.le.27))
c    *write(6,"('R',4i4,1p6e12.4)") id,i,j,itr,rru(itr,id),rrd(itr,id),
c    *  colrat(itr,id),coltar(itr,id),aij(itr),aji(itr)
c     end if
             IF(IICAL(I).LT.0.AND.IICAL(J).LT.0) THEN
                IF(IICAL(I).NE.IICAL(J)) THEN
                   AIJ(ITR)=AIJ(ITR)*SBPSI(I,ID)
                   AJI(ITR)=AJI(ITR)*SBPSI(J,ID)
                 ELSE
                   AIJ(ITR)=0.
                   AJI(ITR)=0.
                END IF
             END IF
          END DO
C
C      Elements of the rate matrix
C
         DO ITR=1,NTRANS
            I=ILOW(ITR)
            IF(IIFIX(IATM(I)).EQ.1) CYCLE
            NREFI=NREFS(IATM(I),ID)
            J=IUP(ITR)
            II=IABS(IICAL(I))
            JJ=IABS(IICAL(J))
            IF(IPZERO(I,ID).NE.0.OR.IPZERO(J,ID).NE.0) CYCLE
            IF(I.NE.NREFI.AND.II.GT.0.AND..NOT.LLTE(I)) THEN
               ESEMAT(II,II)=ESEMAT(II,II)+AIJ(ITR)
               IF(JJ.NE.0) THEN
                  ESEMAT(II,JJ)=ESEMAT(II,JJ)-AJI(ITR)
                ELSE
                  JJJ=IICAL(ILTREF(J,ID))
                  ESEMAT(II,JJJ)=ESEMAT(II,JJJ)-AJI(ITR)*SBPSI(J,ID)
               END IF
            END IF
            IF(J.NE.NREFI.AND.JJ.GT.0.AND..NOT.LLTE(J)) THEN
               ESEMAT(JJ,JJ)=ESEMAT(JJ,JJ)+AJI(ITR)
               IF(II.NE.0) THEN
                  ESEMAT(JJ,II)=ESEMAT(JJ,II)-AIJ(ITR)
                ELSE
                  III=IICAL(ILTREF(I,ID))
                  ESEMAT(JJ,III)=ESEMAT(JJ,III)-AIJ(ITR)*SBPSI(I,ID)
               END IF
            END IF
         END DO
       END IF
C
C        reset the rate matrix elements for "small" populations
C
         DO I=1,NLEVEL
            II=IICAL(I)
            IF(II.GT.0) THEN
               IF(IPZERO(I,ID).GT.0) THEN
                  DO J=1,NLEVEL
                     ESEMAT(II,J)=0.
                 END DO
                 ESEMAT(II,II)=1.
               END IF
             ELSE IF(II.LT.0) THEN
               IF(IGZERO(-II,ID).GT.0) THEN
                  DO J=1,NLEVEL
                     ESEMAT(-II,J)=0.
                  END DO
                  ESEMAT(-II,-II)=1.
               END IF
            END IF
         END DO
C
C ******** Second part - abundance definition equations
C
      DO IAT=1,NATOM
         IF(IIFIX(IAT).EQ.1.AND.IMODE.GE.0) CYCLE
         NREFII=IABS(IICAL(NREFS(IAT,ID)))
         DO I=N0A(IAT),NKA(IAT)
            IL=ILK(I)
            II=IICAL(I)
            IF(II.GT.0) THEN
               ESEMAT(NREFII,II)=ESEMAT(NREFII,II)+UN
               IF(IL.NE.0) THEN
                  ESEMAT(NREFII,II)=ESEMAT(NREFII,II)+ANE*USUM(IL)
               END IF
             ELSE IF(II.LT.0) THEN
               ESEMAT(NREFII,-II)=ESEMAT(NREFII,-II)+SBPSI(I,ID)
               IF(IL.NE.0) THEN
                  ESEMAT(NREFII,-II)=ESEMAT(NREFII,-II)
     *                    +ANE*USUM(IL)*SBPSI(I,ID)
               END IF
             ELSE
               III=IICAL(ILTREF(I,ID))
               ESEMAT(NREFII,III)=ESEMAT(NREFII,III)+SBPSI(I,ID)
            END IF
         END DO
         BESE(NREFII)=BESE(NREFII)+
     *             DENS(ID)/WMM(ID)/YTOT(ID)*ABUND(IAT,ID)
      END DO

c     write(67,"(i4,1p5e12.4)") 
c    * id,dens(id),wmm(id),ytot(id),abund(1,id),bese(nrefii)
C
c     check for all-zero rows and fix thems
c
      sum=0.
      do i=1,nlevel
         sum=0.
         do j=1,nlevel
            sum=sum+abs(esemat(i,j))
         end do
         if(sum.eq.0.) then
            esemat(i,i)=1.
         end if
      end do
c
      RETURN
      END SUBROUTINE RATMAT

C
C     ***************************************************
c

      SUBROUTINE STEQEQ(ID,POP1,MODE)
C     ===============================
C
      use accura
      use atomic
      use basics
      use iterat
      use modelq

      implicit none 

      INTEGER, INTENT(IN)  :: ID,MODE
      REAL(DP),INTENT(OUT) :: POP1(MLEVEL)

      REAL(DP) :: POP0(MLEVEL),SBW(MLEVEL)

      REAL(DP) :: t,aein,an,ane,enrg,entt,wm,popm
      INTEGER  :: ipri,i,ii,iat,ion,iii
      LOGICAL  :: lkit
C
      if(ioptab.lt.0.or.iopfrc.gt.0) return
c
      t=temp(id)
      aein=elec(id)
      an=dens(id)/wmm(id)+elec(id)
      if(ifmol.gt.0.and.t.lt.tmolim) then
CC       ipri=0
         ipri=1
       write(80,*) 'before moleq',t,an,aein
         call moleq(id,t,an,aein,ane,enrg,entt,wm,ipri)
C        don't change the electron density when
C        charge conservation is not solved
C        elec(id)=ane
         if(INPC.ne.0) elec(id)=ane
      end if
c
C     evaluation of the global rate matrix
C
c      if(id.le.nd-1) write(*,*) 'steqeq t,aein,an',t,aein,an,nlevel
      CALL SABOLF(ID)
c      if(id.eq.1) write(*,"(1p10e10.2)") (sbf(i),i=1,nlevel)
c      if(id.eq.1) write(*,"(40i3)") (iifor(i),i=1,nlevel)
      iprat=1
      CALL RATMAT(ID,IIFOR,1)
!      if(id.ge.1) then
!       write(68,*) 'esemat id=',id
!       do i=1,nlevel
!          write(68,"(i3/(1p10e10.2))") 
!    *     i,(esemat(i,ii),ii=1,nlevel)
!       end do
!       write(68,*) 'bese id=',id
!       write(68,"(1p10e10.2)") (bese(i),i=1,nlevel)
!      end if
C
C     new populations - solution of the rate equations
C
      CALL LEVSOL(POP0,IIFOR,NLVFOR,0)
c
C     array of new populations
C
c     if(id.ge.nd-1) write(*,*) 'nlvfor',nlvfor
      DO I=1,NLEVEL
         SBW(I)=ELEC(ID)*SBF(I)*WOP(I,ID)
         II=IIFOR(I)
         IF(II.GT.0) THEN
            POP1(I)=POP0(II)
          ELSE IF(II.LT.0) THEN
            POP1(I)=POP0(-II)*SBPSI(I,ID)
          ELSE
            if(imodl(i).lt.0.or.iifix(iatm(i)).gt.0) then
               pop1(i)=popul(i,id)
             else
               III=IIFOR(ILTREF(I,ID))
               POP1(I)=SBPSI(I,ID)*POP0(III)
            end if
         END IF
c         if(id.ge.nd-1)
c    *     write(*,"(5i3,1p3e10.2)") i,ii,imodl(i),iltref(i,id),iii,
c    *     pop0(ii),sbpsi(i,id),pop1(i)
         if(iifix(iatm(i)).gt.0) pop1(i)=popul(i,id)
         if(ipzero(i,id).gt.0) pop1(i)=0.
      END DO
C
C     set up the parameter IPZERO indicating that a population is "small"
C     and will subsequently be set to zero
C
      IF(ITER.EQ.0) THEN
         LKIT=.TRUE.
      ELSE
         LKIT=KANT(ITER).EQ.0 .AND. ITER.LT.IACC
      ENDIF
      IF(LKIT) THEN
      DO IAT=1,NATOM
         POPM=DENS(ID)/WMM(ID)/YTOT(ID)*ABUND(IAT,ID)
         DO I=N0A(IAT),NKA(IAT)
            IF(POP1(I)/POPM.LT.POPZER) THEN
               POP1(I)=0.
               IPZERO(I,ID)=1
            END IF
         END DO
         if(nrefs(iat,id).gt.n0a(iat)) then
            do i=nrefs(iat,id),n0a(iat),-1
               if(ipzero(i,id).gt.0.and.ilk(i).gt.0) then
                  do iii=nfirst(ilk(i)),nlast(ilk(i))
                     ipzero(iii,id)=1
                     pop1(iii)=0.
                  end do
               end if
            end do
         end if
      END DO
      END IF
!      if(id.ge.1) write(68,*) 'pop1 id=',id
!      if(id.ge.1) write(68,"(1p10e10.2)") (pop1(i),i=1,nlevel)
C
C     if required (MODE=1), set up the global array POPUL
C
c      if(id.eq.1) write(*,*) 'mode',mode
      IF(MODE.NE.1) RETURN
      DO I=1,NLEVEL
         POPUL(I,ID)=POP1(I)
      END DO
C
C     array of b-factors
C
      DO I=1,NLEVEL
         BFAC(I,ID)=UN
      END DO
      IF(LTE.OR.IPSLTE.NE.0) RETURN
      DO ION=1,NION
         DO I=NFIRST(ION),NLAST(ION)
            IF(POPUL(NNEXT(ION),ID).GT.0..AND.IPZERO(I,ID).EQ.0)
     *      BFAC(I,ID)=POPUL(I,ID)/(POPUL(NNEXT(ION),ID)*SBW(I))
         END DO
      END DO
c      if(id.eq.1) write(*,"(1p10e10.2)") (popul(i,id),i=1,nlevel)
C
      RETURN
      END SUBROUTINE STEQEQ

C
C     ***************************************************
c

      SUBROUTINE LEVSOL(POPP,IICAL,NLVCAL,IALL)
C     =========================================
C
      use accura
      use atomic
      use basics
      use iterat
      use modelq

      implicit none

      REAL(DP) :: POPP(MLEVEL),
     *            AP(MLEVEL,MLEVEL),BP(MLEVEL),POPP1(MLEVEL)
      INTEGER, INTENT(IN)  :: IICAL(MLEVEL),IALL

      INTEGER  :: IAT,N1,NK,I,NLP,J,NLVCAL
C
      if(ioptab.lt.0) return
c
C     new populations - solution of the rate equations
C
C     a) either by inverting the global rate matrix (if IRSPLT=0)
C
      IF(IRSPLT.EQ.0) THEN
         CALL LINEQS(ESEMAT,BESE,POPP,NLVCAL,MLEVEL)
C
C     b) or by inverting several partial rate matrices for the
C        individual chemical species
C
       ELSE
         DO IAT=1,NATOM
            IF(IIFIX(IAT).EQ.1.AND.IALL.EQ.0) CYCLE
            N1=N0A(IAT)
            NK=NKA(IAT)
            N1=IABS(IICAL(N1))
            NK=IABS(IICAL(NK))
            IF(N1.LE.0) THEN
               DO I=N0A(IAT),NKA(IAT)
                  N1=IICAL(I)
                  IF(IICAL(I).GT.0) EXIT
               END DO
            END IF
            IF(N1.LE.0) CYCLE
            NLP=NK-N1+1
            DO I=N1,NK
               DO J=N1,NK
                  AP(I-N1+1,J-N1+1)=ESEMAT(I,J)
               END DO
               BP(I-N1+1)=BESE(I)
            END DO
            CALL LINEQS(AP,BP,POPP1,NLP,MLEVEL)
            DO I=N1,NK
                POPP(I)=POPP1(I-N1+1)
            END DO
         END DO
      END IF
      RETURN
      END SUBROUTINE LEVSOL

C
C     ***************************************************
c

      SUBROUTINE LINEQS(A,B,X,N,NR)
C     =============================
C
C     Solution of the linear system A*X=B
C     by Gaussian elimination with partial pivoting
C
C     Input: A  - matrix of the linear system, with actual size (N x N),
C                and maximum size (NR x NR)
C            B  - the rhs vector
C     Output: X - solution vector
C     Note that matrix A and vector B are destroyed here
C
      use accura
      use basics

      implicit none

      INTEGER, INTENT(IN) :: N,NR
      REAL(DP) :: A(NR,NR),B(NR),X(NR),D(NR) 
      INTEGER  :: IP(NR)

      REAL(DP) :: A11,A12,A21,A22,AM,SUM
      INTEGER  :: I,J,IM1,IT,JP1,K,IP1,KP1
c
      if(n.eq.2) then
         a11=a(1,1)
         a12=a(1,2)
         a21=a(2,1)
         a22=a(2,2)
         x(1)=(a(2,2)*b(1)-a(1,2)*b(2))/
     *        (a(1,1)*a(2,2)-a(1,2)*a(2,1))
         x(2)=(b(2)-a(2,1)*x(1))/a(2,2)
         return
      end if
c
      DO I=1,N
         DO J=1,N
            D(J)=A(J,I)
         END DO
         IM1=I-1
         IF(IM1.GE.1) THEN
            DO J=1,IM1
               IT=IP(J)
               A(J,I)=D(IT)
               D(IT)=D(J)
               JP1=J+1
               DO K=JP1,N
                  D(K)=D(K)-A(K,J)*A(J,I)
               END DO
            END DO
         END IF
         AM=ABS(D(I))
         IP(I)=I
         DO K=I,N
            IF(AM.LT.ABS(D(K))) THEN
               IP(I)=K
               AM=ABS(D(K))
            END IF
         END DO
         IT=IP(I)
         A(I,I)=D(IT)
         D(IT)=D(I)
         IP1=I+1
         IF(IP1.GT.N) EXIT
         DO K=IP1,N
            A(K,I)=D(K)/A(I,I)
         END DO
      END DO

      DO I=1,N
         IT=IP(I)
         X(I)=B(IT)
         B(IT)=B(I)
         IP1=I+1
         IF(IP1.GT.N) EXIT
         DO J=IP1,N
            B(J)=B(J)-A(J,I)*X(I)
         END DO
      END DO

      DO I=1,N
         K=N-I+1
         SUM=0.
         KP1=K+1
         IF(KP1.LE.N) THEN
            DO J=KP1,N
               SUM=SUM+A(K,J)*X(J)
            END DO
         END IF
         X(K)=(X(K)-SUM)/A(K,K)
      END DO
      RETURN
      END SUBROUTINE LINEQS

C
C     ***************************************************
c

      SUBROUTINE REFLEV(ID,IMODE)
C     ===========================
C
C     determination of the global reference level, and
C     determination of the LTE reference levels and corresponding
C     quantities
C
      use accura
      use atomic
      use basics
      use iterat
      use modelq

      implicit none

      INTEGER, INTENT(IN) :: ID,IMODE

      REAL(DP) :: XSBF(MLEVEL),PMAX,X,XA,XT,XN,SBB1,XSBMX
      INTEGER  :: IAT,I,N1,NK,II,III,IFSUP,IN,I1,ISBMX,ITR,
     *            NFIR
      LOGICAL  :: LREFP,LRF

      if(ioptab.lt.0) return
C
C     determination of the reference level (if required)
C
      LREFP=.TRUE.
      LREFP=.false.
      IF(MODREF.GE.1) THEN
         IF(IMODE.EQ.1.AND.(ITER.LE.1.OR.KANT(ITER).EQ.0)) THEN
            DO IAT=1,NATOM
               PMAX=0.
               IREF=0
               DO I=N0A(IAT),NKA(IAT)
                  IF(POPUL(I,ID).GE.PMAX) THEN
                     PMAX=POPUL(I,ID)
                     IREF=I
                  END IF
               END DO
               IF(IREF.NE.NKA(IAT).AND.IREF.NE.NFIRST(IEL(IREF))) then
                  IREF=NFIRST(IEL(IREF))
               end if
               IF(MODREF.EQ.2.AND.IREF.LT.NFIRST(IEL(NKA(IAT))))
     *            IREF=NFIRST(IEL(NKA(IAT)))
               NREF(IAT)=IREF
               LREFP=LREFP .AND. NREFS(IAT,ID).EQ.NREF(IAT)
               NREFS(IAT,ID)=NREF(IAT)
               if(modref.eq.3.and.ifmeta(iel(iref)).eq.1) then
                  do i=n0a(iat),nka(iat)
                     nrefs(iat,id)=nfirst(iel(iref))+1
                  end do
               end if
            END DO
          ELSE
            DO IAT=1,NATOM
               NREF(IAT)=NREFS(IAT,ID)
            END DO
         END IF
       ELSE
         DO IAT=1,NATOM
            LREFP=LREFP .AND. NREFS(IAT,ID).EQ.NREF(IAT)
            NREFS(IAT,ID)=NREF(IAT)
         END DO
      END IF
C
C     set to the zeroing mode levels with SBF*ANE large;
C     check whether reference level is not zerod, and is so, re-establish
C     the reference level.
C
      IF(ITER.LE.NITZER) THEN
         DO IAT=1,NATOM
            N1=N0A(IAT)
            NK=NKA(IAT)
            ISBMX=0
            XSBMX=0.
            IREF=NREFS(IAT,ID)
            DO II=N1,NK
               IF(ITER.LE.NITZER) IPZERO(II,ID)=0
               XSBF(II)=SBF(II)*ELEC(ID)
               IF(.NOT.LTE) THEN
                  ITR=ITRA(II,NNEXT(IEL(II)))
                  IF(ITR.GT.0) THEN
                     IF(RRU(ITR,ID).GT.1.E-30)
     *               XSBF(II)=SBF(II)*ELEC(ID)*RRD(ITR,ID)/RRU(ITR,ID)
                  END IF
               END IF
            END DO
            IF(LTE) THEN
               IREF=N1
               DO II=N1+1,NK
                  IF(ILK(II).GT.0) THEN
                    IREF=II
                    IF(XSBF(II).GT.1.) EXIT
                  END IF
               END DO
               NREFS(IAT,ID)=IREF
               NREF(IAT)=IREF
            END IF
            IF(IREF.GT.N0A(IAT)) THEN
               X=1.
               DO II=IREF-1,N1,-1
                  IF(ILK(II).GT.0.OR.II.EQ.N0A(IAT)) THEN
                     X=X*XSBF(II)
                     IF(X.LT.POPZR2) THEN
                        DO III=N1,NLAST(IEL(II))
                           IPZERO(III,ID)=1
                        END DO
                        EXIT
                     END IF
                  END IF
               END DO
            END IF
            IF(IREF.LT.NK) THEN
               X=1.
               DO II=IREF+1,NK
                  IF(ILK(II).GT.0) THEN
                     X=X*XSBF(NFIRST(ILK(II)))
                     IF(X.GT.1./POPZR2) THEN
                        NFIR=NFIRST(IEL(II))
                        IF(II.EQ.NK) NFIR=NK
                        DO III=NFIR,NK
                           IPZERO(III,ID)=1
                        END DO
                        EXIT
                     END IF
                  END IF
               END DO
            END IF
         END DO
      END IF
C
C     determination of the LTE reference levels and corresponding
C     quantities
C
      ELEC1(ID)=UN/ELEC(ID)
      DO IAT=1,NATOM
         IFSUP=0
         IREF=NREF(IAT)
         DO I=N0A(IAT),NKA(IAT)
C
C           generalized LTE reference level formalism
C
            IF(IABS(IMODL(I)).EQ.1.OR.IABS(IMODL(I)).EQ.2) THEN
               IN=NNEXT(IEL(I))
               IF(I.LT.IREF.OR.POPUL(I,ID).LT.POPUL(IN,ID)) THEN
                  ILTREF(I,ID)=IN
                  SBPSI(I,ID)=SBF(I)*ELEC(ID)*WOP(I,ID)*BFAC(I,ID)
                  DSBPST(I,ID)=DSBF(I)
                  DSBPSN(I,ID)=ELEC1(ID)
                ELSE IF(I.GT.IREF) THEN
                  I1=NFIRST(IEL(I))
                  ILTREF(I,ID)=I1
                  SBPSI(I,ID)=SBF(I)*WOP(I,ID)*BFAC(I,ID)/
     *                        (SBF(I1)*WOP(I1,ID)*BFAC(I1,ID))
                  DSBPST(I,ID)=DSBF(I)-DSBF(I1)
                  DSBPSN(I,ID)=0.
               END IF
C
C            original scheme
C
             ELSE IF(IABS(IMODL(I)).EQ.3.OR.IMODL(I).EQ.0) THEN
               ILTREF(I,ID)=NNEXT(IEL(I))
               SBPSI(I,ID)=SBF(I)*ELEC(ID)*WOP(I,ID)*BFAC(I,ID)
               DSBPST(I,ID)=DSBF(I)
               DSBPSN(I,ID)=ELEC1(ID)
             ELSE IF(IABS(IMODL(I)).EQ.5) THEN
               IFSUP=1
            END IF
         END DO
C
C        super-reference level formalism
C
         LRF=LTE.AND.IREF.NE.NKA(IAT)
         IF(IFSUP.EQ.1.OR.LRF) THEN
         XA=UN
         XT=0.
         XN=0.
         ILTREF(IREF,ID)=IREF
         IF(IREF.GT.N0A(IAT)) THEN
            DO I=IREF-1,N0A(IAT),-1
               ILTREF(I,ID)=IREF
               SBPSI(I,ID)=XA*SBF(I)*ELEC(ID)*BFAC(I,ID)*WOP(I,ID)
               if(sbpsi(i,id).lt.popzr2) then
                  sbpsi(i,id)=0.
                else
                  DSBPST(I,ID)=XT+DSBF(I)
                  DSBPSN(I,ID)=XN+ELEC1(ID)
               end if
               IF(I.EQ.NFIRST(IEL(I))) THEN
                  XA=SBPSI(I,ID)
                  XT=DSBPST(I,ID)
                  XN=DSBPSN(I,ID)
                  if(xn.eq.0.) ilk(i)=0
               END IF
            END DO
         END IF
C
         XA=UN
         XT=0.
         XN=0.
         IF(IREF.LT.NKA(IAT)) THEN
            IF(IREF.EQ.NLAST(IEL(IREF))) THEN
               XA=UN/(SBF(IREF)*BFAC(IREF,ID)*WOP(IREF,ID)*ELEC(ID))
               XT=-DSBF(IREF)
               XN=-ELEC1(ID)
            END IF
            DO I=IREF+1,NKA(IAT)-1
               ILTREF(I,ID)=IREF
               I1=NFIRST(IEL(I))
               SBB1=UN/(SBF(I1)*BFAC(I1,ID)*WOP(I1,ID))
               SBPSI(I,ID)=XA*SBF(I)*BFAC(I,ID)*WOP(I,ID)*SBB1
               if(sbpsi(i,id).lt.popzr2) then
                  sbpsi(i,id)=0.
                else
                  DSBPST(I,ID)=XT+DSBF(I)-DSBF(I1)
                  DSBPSN(I,ID)=XN
               end if
               IF(I.EQ.NLAST(IEL(I))) THEN
                  XA=XA*SBB1*ELEC1(ID)
                  XT=XT-DSBF(I1)
                  XN=XN-ELEC1(ID)
               END IF
            END DO
            I=NKA(IAT)
            ILTREF(I,ID)=IREF
            SBPSI(I,ID)=XA
            DSBPST(I,ID)=XT
            DSBPSN(I,ID)=XN
            END IF
         END IF
C
C        different meaning of SBPSI for IMODL=2, i.e. for levels
C        with fixed ratio of population to that of reference level
C
         DO I=N0A(IAT),NKA(IAT)
            IF(IABS(IMODL(I)).EQ.2) THEN
               IF(POPUL(I,ID).EQ.0..OR.POPUL(ILTREF(I,ID),ID).EQ.0.)
     *            THEN
                  IN=NNEXT(IEL(I))
                  IF(I.LT.IREF.OR.POPUL(I,ID).LT.POPUL(IN,ID)) THEN
                     ILTREF(I,ID)=IN
                     SBPSI(I,ID)=SBF(I)*ELEC(ID)*WOP(I,ID)*BFAC(I,ID)
                   ELSE IF(I.GT.IREF) THEN
                     I1=NFIRST(IEL(I))
                     ILTREF(I,ID)=I1
                     SBPSI(I,ID)=SBF(I)*WOP(I,ID)*BFAC(I,ID)/
     *                           (SBF(I1)*WOP(I1,ID)*BFAC(I1,ID))
                  END IF
                ELSE
                  SBPSI(I,ID)=POPUL(I,ID)/POPUL(ILTREF(I,ID),ID)
               END IF
               DSBPST(I,ID)=0.
               DSBPSN(I,ID)=0.
            END IF
         END DO
C
C        different meaning of SBPSI for IMODL=6 or 7, i.e. for levels
C        with fixed ratio of population to that of a "guiding" level
C
         if(imode.eq.1) then
            DO I=N0A(IAT),NKA(IAT)
               IF(IABS(IMODL(I)).EQ.6) THEN
                  ILTREF(I,ID)=IGUIDE(I)
                if(POPUL(ILTREF(I,ID),ID).gt.0.) then
                  SBPSI(I,ID)=POPUL(I,ID)/POPUL(ILTREF(I,ID),ID)
                end if
                  DSBPST(I,ID)=0.
                  DSBPSN(I,ID)=0.
               END IF
            END DO
         end if
      END DO
C
C     true LTE reference level
C
      DO IAT=1,NATOM
         DO I=N0A(IAT),NKA(IAT)
            IF(IABS(IMODL(I)).LT.6) THEN
               ILTERF(I,ID)=ILTREF(I,ID)
               SBLPSI(I,ID)=SBPSI(I,ID)
             ELSE
               ILTERF(I,ID)=NNEXT(IEL(I))
               SBLPSI(I,ID)=SBF(I)*ELEC(ID)*WOP(I,ID)*BFAC(I,ID)
            END IF
         END DO
      END DO
      RETURN
      END SUBROUTINE REFLEV

C
C     ***************************************************
c

      SUBROUTINE ROSSTD(IJ)
C     =====================
C
C     Rosseland mean opacity
C
      use accura
      use alipar
      use atomic
      use basics
      use iterat
      use modelq

       implicit none

       integer, intent(in) :: IJ
c      DIMENSION TAUR(MDEPTH)
       REAL(DP) ::  pld(mdepth),abpld(mdepth)

       REAL(DP) :: PLAN,DPLAN,DTAUR,ABPL,PLL
       INTEGER  :: ID,IDR
C
C     for IJ > 0 - contribution from the frequency IJ to the Rosseland
C                  opacity integrals
C
      IF(IJ.GT.0) THEN
         if(ij.eq.1) then
            do id=1,nd
               pld(id)=0.
               abpld(id)=0.
            end do
         end if
         IF(IJX(IJ).GE.0) THEN
           DO ID=1,ND
             PLAN=XKFB(ID)/XKF1(ID)*W(IJ)
             DPLAN=PLAN/XKF1(ID)*FREQ(IJ)*HKT21(ID)
             ABROSD(ID)=ABROSD(ID)+DPLAN/ABSO1(ID)
             SUMDPL(ID)=SUMDPL(ID)+DPLAN
             pld(id)=pld(id)+plan
             abpld(id)=abpld(id)+(abso1(id)-scat1(id))*pld(id)
           END DO
         END IF
       ELSE
C
C     for IJ=0 - evaluation of the Rosseland optical depth and
C                the radiative equilibrium division point
C
         ID=1
         IDR=0
         TAURS(ID)=HALF*DEDM1*ABROSD(ID)*DENS(ID)
         TROSS(ID)=TAURS(ID)
         DO ID=2,ND
            DTAUR=DELDM(ID-1)*(ABROSD(ID)+ABROSD(ID-1))
            TAURS(ID)=TAURS(ID-1)+DTAUR
            IF(TAURS(ID).LE.TAUDIV) IDR=ID
            TROSS(ID)=TAURS(ID)
         END DO
C
C        in the last iteration, output of The Rosseland opacity and
C        optical depth; skip the rest
C
         IF(LFIN) THEN
            DO ID=1,ND
               TROSS(ID)=TAURS(ID)
               abpl=abpld(id)/pld(id)/dens(id)
               pll=sig4p*4.*temp(id)**4
               WRITE(11,"(I4,2X,1P6E12.4,2x,3e12.4)") 
     *                       ID,DM(ID),TAURS(ID),ABROSD(ID),
     *                       TEMP(ID),ELEC(ID),DENS(ID)
CC   *                       pld(id),pll,abpl
            END DO
            CLOSE(11)
            RETURN
         END IF
C
C        determination of the radiative equilibrium parameters
C        REINT and REDIF;
C        REINT=1 for all ID .le. ND-idlst
C        REDIF=1 for Rosseland optical depth > taudiv  (taur.gt.taudiv)
C                typically 0.1 - 0.5;
C              - this value has been empirically shown to yield
C                the best convergence rate
C
         IF(ITER.GT.ITNDRE) RETURN
         if(ndre.gt.1) then
           do id=1,nd
              if(id.lt.ndre) then
                 reint(id)=1.
                 redif(id)=0.
               else
                 reint(id)=0.
                 redif(id)=1.
               end if
            end do
            idr=ndre
          else if(ndre.eq.-1) then
            write(6,"(/'  id        redif          reint'/)")
            do id=1,nd
               reint(id)=1.
               redif(id)=0.
            end do
            redif(1)=1.
          else
c
           DO ID=1,ND
              REINT(ID)=UN
              REDIF(ID)=UN
              IF(ID.GT.ND-IDLST) REINT(ID)=0.
              IF(ID.LT.IDR) THEN
                 REDIF(ID)=0.
                 IF(MOD(NDRE,10).EQ.-1) THEN
                    REDIF(ID)=TAURS(ID)
                  ELSE IF(MOD(NDRE,10).EQ.-2) THEN
                    REDIF(ID)=TAURS(ID)*TAURS(ID)
                 END IF
              END IF
              IF(NDRE.LE.-10) THEN
                 REDIF(ID)=REDIF(ID)/SIG4P/TEFF**4
                 REINT(ID)=REINT(ID)/ABPLAD(ID)*DENS(ID)
              END IF
c
              IF(REINT(ID).LE.0..AND.REDIF(ID).LE.0.) REDIF(ID)=UN
c
           END DO
           ID=1
           IF(MOD(NDRE,10).EQ.-5) REDIF(ID)=UN
           IF(NDRE.LE.-10) THEN
              REDIF(ID)=REDIF(ID)/SIG4P/TEFF**4
           END IF
           NDRE=1
           if(iter.eq.1) then
              WRITE(6,"(/' SCHEME OF RADIATIVE EQUIL. SET IN RESOLV'/
     *        ' ONLY INTEGRAL EQUATION FOR ID          <= ',I3/
     *        ' BOTH FOR                  ',I5,' <= ID <= ',I3/)") 
     *        IDR,IDR+1,ND-idlst
              WRITE(10,"(/' SCHEME OF RADIATIVE EQUIL. SET IN RESOLV'/
     *        ' ONLY INTEGRAL EQUATION FOR ID          <= ',I3/
     *        ' BOTH FOR                  ',I5,' <= ID <= ',I3/)") 
     *        IDR,IDR+1,ND-idlst
            endif
        endif
      END IF
      RETURN
      END SUBROUTINE ROSSTD

C
C     ***************************************************
c


C
C     ***************************************************
c

      SUBROUTINE NEWPOP(ID,POP1)
C     ==========================
C
      use accura
      use atomic
      use basics
      use iterat
      use modelq

      implicit none

      REAL(DP) :: POP1(MLEVEL),DPOP(MLEVEL),DPMAX(MDEPTH),
     *             SBW(MLEVEL)
      INTEGER,INTENT(IN) :: ID
      INTEGER            :: I,ION,IMAX 
c
      if(ioptab.lt.0) return
C
      DPMAX(ID)=0.
      DO I=1,NLEVEL
         IF(POPUL(I,ID).GT.0.)
     *      DPOP(I)=(POP1(I)-POPUL(I,ID))/POPUL(I,ID)
         IF(ABS(DPOP(I)).GT.DPMAX(ID)) THEN
            DPMAX(ID)=ABS(DPOP(I))
            IMAX=I
         END IF
         POPUL(I,ID)=POP1(I)
      END DO

c     if(id.eq.1) write(*,*) 'newpop'
c     if(id.eq.1) write(*,"(1p10e10.2)") (popul(i,id),i=1,nlevel)
C
C     array of b-factors
C
      DO I=1,NLEVEL
         BFAC(I,ID)=UN
         SBW(I)=ELEC(ID)*SBF(I)*WOP(I,ID)
      END DO
      IF(.NOT.LTE.AND.IPSLTE.EQ.0) THEN
         DO ION=1,NION
            DO I=NFIRST(ION),NLAST(ION)
                IF(POPUL(NNEXT(ION),ID).GT.0.)
     *          BFAC(I,ID)=POPUL(I,ID)/(POPUL(NNEXT(ION),ID)*SBW(I))
            END DO
         END DO
      END IF
      RETURN
      END

