C     ***************************************************
c


      SUBROUTINE RATES1(IMOR)
C     ======================
C
C     Evaluation of  radiative rates
C
C     Output (transferred by COMMON blocks):
C            RRU(IT,ID) - upward radiative rate in transition IT and
C                         depth ID
C            RRD(IT,ID) - analogously the downward rate; more precisely
C                         the exact downward rate is given by:
C               lines   : RRD * stat.weight(lower)/stat.weight(upper)
C               continua: RRD * n(elec) * Saha-Boltzmann factor
C
      use accura
c     use alipar
      use atomic
      use basics
c     use iterat
      use modelq
      use odfpar

      implicit none

      INTEGER, INTENT(IN) :: IMOR
      REAL(DP) ::  RBNE(MDEPTH),CROSS

      REAL(DP) :: FR,W0,WW,DTA,FL,SG,SGW0,SGW,S,A1,A2
      INTEGER  :: ID,ITRP,IJ,ITR,II,JJ,JC,ICDW,IMER,ITRPRD,IJ0,IJT,IJ1,
     *            KJ,INDXPA,KJD,IBFT,ILINT
      LOGICAL  :: LROSS
C
C     zero the rates
C
      DO ID=1,ND
         PRADT(ID)=0.
         PRADA(ID)=0.
         FLRD(ID)=0.
         DO ITR=1,NTRANS
            RRU(ITR,ID)=0.
            RRD(ITR,ID)=0.
         END DO
         DO ITRP=1,NTRPRD
            PJBAR(ITRP,ID)=0.
         END DO
      END DO
      PRD0=0.
C
      LROSS=NDRE.LE.0.AND.ITER.EQ.1.OR.LFIN
      IF(HMIX0.GT.0..or.nnewd.gt.0) LROSS=.TRUE.
      IF(LROSS) THEN
         DO ID=1,ND
             ABROSD(ID)=0.
             SUMDPL(ID)=0.
         END DO
      END IF
C
      FRLOOP: DO IJ=1,NFREQ
         IF(IJX(IJ).EQ.-1) CYCLE FRLOOP
         FR=FREQ(IJ)
         W0=W0E(IJ)
         WW=W(IJ)
         CALL OPACF1(IJ)
         IF(IMOR.EQ.0) THEN
            CALL RTEFR1(IJ)
          ELSE
            RAD1(ID)=RAD(IJ,ID)
         END IF
         IF(LROSS) CALL ROSSTD(IJ)
         FLRD(1)=FLRD(1)+WW*(FH(IJ)*RAD1(1)-HEXTRD(IJ))
         DO ID=2,ND
            DTA=UN/(ABSOT(ID)+ABSOT(ID-1))/DELDMZ(ID-1)
            FL=(RAD1(ID)*FAK1(ID)-RAD1(ID-1)*FAK1(ID-1))*DTA
            FLRD(ID)=FLRD(ID)+WW*FL
         END DO
         if(ioptab.lt.0) CYCLE FRLOOP
C
C        ---------------------
C        Continuum transitions
C        ---------------------
C
         DO ID=1,ND
c           RBLI(ID)=RAD1(ID)+BNUE(IJ)
            RBNE(ID)=(RAD1(ID)+BNUE(IJ))*EXP(-HKT1(ID)*FR)
c           RBNE(ID)=RBLI(ID)*EXP(-HKT1(ID)*FR)
            IBLOOP: DO IBFT=1,NTRANC
               ITR=ITRBF(IBFT)
               SG=CROSS(IBFT,IJ)
               IF(SG.LE.0.) CYCLE IBLOOP
               II=ILOW(ITR)
               JJ=IUP(ITR)
               IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE IBLOOP
               JC=ITRA(JJ,II)
               IF(IFWOP(II).GE.0) THEN
                 ICDW=MCDW(ITR)
                 IF(ICDW.GE.1) SG=SG*DWF1(ICDW,ID)
               ELSE
                 IMER=IMRG(II)
                 SG=SGMG(IMER,ID)
               ENDIF
               SGW0=SG*W0
               RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
               RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNE(ID)
            END DO IBLOOP
         END DO
C
C        ----------------
C        Line transitions
C        ----------------
C
         IF(ISPODF.EQ.0) THEN
            IF(IJLIN(IJ).GT.0) THEN
C
C        the "primary" line at the given frequency
C
               ITR=IJLIN(IJ)
               II=ILOW(ITR)
               JJ=IUP(ITR)
               DO ID=1,ND
                  IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
                  SGW=PRFLIN(ID,IJ)*W0
                  RRU(ITR,ID)=RRU(ITR,ID)+SGW*RAD1(ID)
                  RRD(ITR,ID)=RRD(ITR,ID)+SGW*RBNE(ID)
               END DO
               itrprd=iprd(itr)
               ITRPRD=0
               if(itrprd.gt.0) then
                  s=un/(0.02654*osc0(itr))
                  do id=1,nd
                     sg=prflin(id,ij)*s
                     pjbar(itrprd,id)=pjbar(itrprd,id)+sg*w(ij)*rad1(id)
                  end do
               end if
            END IF

            IF(NLINES(IJ).LE.0) CYCLE FRLOOP
C
C        the "overlapping" lines at the given frequency
C
            LLOOP: DO ILINT=1,NLINES(IJ)
               ITR=ITRLIN(ILINT,IJ)
               if(linexp(itr)) CYCLE LLOOP
               IJ0=IFR0(ITR)
               II=ILOW(ITR)
               JJ=IUP(ITR)
               IJTLOOP: DO IJT=IJ0,IFR1(ITR)
                  IF(FREQ(IJT).LE.FR) THEN
                     IJ0=IJT
                     EXIT IJTLOOP
                  END IF
               END DO IJTLOOP
               IJ1=IJ0-1
               A1=(FR-FREQ(IJ0))/(FREQ(IJ1)-FREQ(IJ0))*W0
               A2=W0-A1
               DO ID=1,ND
                  IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
                  SGW=A1*PRFLIN(ID,IJ1)+A2*PRFLIN(ID,IJ0)
                  RRU(ITR,ID)=RRU(ITR,ID)+SGW*RAD1(ID)
                  RRD(ITR,ID)=RRD(ITR,ID)+SGW*RBNE(ID)
               END DO
c
CC             itrprd=iprd(itr)
               if(itrprd.gt.0) then
                  s=un/(0.02654*osc0(itr))
                  do id=1,nd
                     SG=(A1*PRFLIN(ID,IJ1)+A2*PRFLIN(ID,IJ0))*s
CC                   pjbar(itrprd,id)=pjbar(itrprd,id)+sg*w(ij)*rad1(id)
                  end do
               end if
            END DO LLOOP
C
C
C     Opacity sampling option
C
         ELSE
           NLILOOP: DO ILINT=1,NLINES(IJ)
             ITR=ITRLIN(ILINT,IJ)
             KJ=IJ-IFR0(ITR)+KFR0(ITR)
             INDXPA=IABS(INDEXP(ITR))
             II=ILOW(ITR)
             JJ=IUP(ITR)
             IF(INDXPA.NE.3 .AND. INDXPA.NE.4) THEN
               DO ID=1,ND
                  IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
                  SG=PRFLIN(ID,KJ)
                  SGW0=SG*W0
                  RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
                  RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNE(ID)
               END DO
             ELSE
               DO ID=1,ND
                  IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
                  KJD=JIDI(ID)
                  SG=EXP(XJID(ID)*SIGFE(KJD,KJ)+
     *            (UN-XJID(ID))*SIGFE(KJD+1,KJ))
                  SGW0=SG*W0
                  RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
                  RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNE(ID)
               END DO
             END IF
           END DO NLILOOP
         END IF
      END DO FRLOOP
C
C     radiation pressure
C
      DO ID=1,ND
         PRADT(ID)=PRADT(ID)*PCK
         PRADA(ID)=PRADA(ID)*PCK
      END DO
      PRD0=PRD0/DENS1(1)*DM(1)*PCK
C
C     Rosseland mean opacity
C
      IF(LROSS) THEN
         DO ID=1,ND
            ABROSD(ID)=SUMDPL(ID)/(ABROSD(ID)*DENS(ID))
         END DO
      END IF
c
      RETURN
      END
C
C     ***************************************************
c

      SUBROUTINE RATSP1
C     =================
C
C     Evaluation of "preconditioned" radiative rates
C
      use accura
      use alipar
      use array1
      use atomic
      use basics
      use iterat
      use modelq
      use odfpar

      implicit none

      REAL(DP), PARAMETER :: PGRD=4.1916825e-10
      REAL(DP) ::  EHK(MDEPTH),CROSS

      INTEGER  :: ID,IJ,ITR,IBFT,II,JJ,JC,ICDW,IMER,ITRPRD,ILINT,
     *            IJ0,IJ1,IJT,KJ,INDXPA,KJD,ITRP
      REAL(DP) :: FR,W0,WW,FLUXW,DTA,FL,SG,SGW0,RLAM,ELIN,
     *            RADRES,BNURES,S,A1,A2,PRDX,PRDR
      LOGICAL  :: LROSS


C     DIMENSION EHKL(MFREQL)
C
C     zero the rates
C
      DO ID=1,ND
         PRADT(ID)=0.
         PRADA(ID)=0.
         FLRD(ID)=0.
         DO ITR=1,NTRANS
            RRU(ITR,ID)=0.
            RRD(ITR,ID)=0.
         END DO
         DO ITRP=1,NTRPRD
            PJBAR(ITRP,ID)=0.
         END DO
      END DO
      PRD0=0.
C
      LROSS=NDRE.LE.0.AND.ITER.EQ.1.OR.LFIN
      IF(HMIX0.GT.0..or.nnewd.gt.0) LROSS=.TRUE.
      IF(LROSS) THEN
         DO ID=1,ND
            ABROSD(ID)=0.
            SUMDPL(ID)=0.
         END DO
      END IF
C
      FRLOOP: DO IJ=1,NFREQ
         IF(IJX(IJ).EQ.-1) CYCLE FRLOOP
         FR=FREQ(IJ)
         W0=W0E(IJ)
         WW=W(IJ)
         CALL OPACF1(IJ)
         CALL RTEFR1(IJ)
         IF(LROSS) CALL ROSSTD(IJ)
         FLUXW=W(IJ)*RAD1(1)*FH(IJ)
CC       GRADF(1,IJ)=FLUXW*ABSO1(1)/DENS(1)*PGRD
         FLRD(1)=FLRD(1)+WW*(FH(IJ)*RAD1(1)-HEXTRD(IJ))
         DO ID=2,ND
            DTA=UN/(ABSOT(ID)+ABSOT(ID-1))/DELDMZ(ID-1)
            FL=(RAD1(ID)*FAK1(ID)-RAD1(ID-1)*FAK1(ID-1))*DTA
            FLRD(ID)=FLRD(ID)+WW*FL
         END DO
!        write(*,"(a,i6,1p3e12.4)") 'frq',ij,fr,abso1(1),rad1(1)
         if(ioptab.lt.0) CYCLE FRLOOP
C
C        ---------------------
C        Continuum transitions
C        ---------------------
C
         DO ID=1,ND
            EHK(ID)=EXP(-HKT1(ID)*FR)
            if(ilpsct.eq.0) then
               ALAB(ID)=ALI1(ID)/(ABSO1(ID)-ELSCAT(ID))
            else
               ALAB(ID)=ALI1(ID)/ABSO1(ID)
            end if
            DO IBFT=1,NTRANC
               ITR=ITRBF(IBFT)
               SG=CROSS(IBFT,IJ)
               IF(SG.LE.0.) CYCLE
               II=ILOW(ITR)
               JJ=IUP(ITR)
               IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
               JC=ITRA(JJ,II)
               IF(IFWOP(II).GE.0) THEN
                 ICDW=MCDW(ITR)
                 IF(ICDW.GE.1) SG=SG*DWF1(ICDW,ID)
               ELSE
                 IMER=IMRG(II)
                 SG=SGMG(IMER,ID)
               ENDIF
               SGW0=SG*W0
               RLAM=SG*ALAB(ID)
               ELIN=EMTRA(ITR,ID)*EHK(ID)
               RADRES=RAD1(ID)-RLAM*BNUE(IJ)*ELIN
               BNURES=BNUE(IJ)*(UN-RLAM*(ABTRA(ITR,ID)-ELIN))
c              BNURES=BNUE(IJ)*(UN-RLAM*ABTRA(ITR,ID))
               RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RADRES
               RRD(ITR,ID)=RRD(ITR,ID)+SGW0*(RADRES+BNURES)*EHK(ID)
c              RRD(ITR,ID)=RRD(ITR,ID)+SGW0*(RAD1(ID)+BNURES)*EHK(ID)
            END DO
!         if(id.ge.1) write(*,*) 'cont',ij,ijlin(ij),nlines(ij)
         END DO
C
C        ----------------
C        Line transitions
C        ----------------
C
         IF(ISPODF.EQ.0) THEN
            IF(IJLIN(IJ).GT.0) THEN
C
C        the "primary" line at the given frequency
C
               ITR=IJLIN(IJ)
               II=ILOW(ITR)
               JJ=IUP(ITR)
               DO ID=1,ND
                  IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
                  SG=PRFLIN(ID,IJ)
                  SGW0=SG*W0
                  RLAM=SG*ALAB(ID)
                  ELIN=EMTRA(ITR,ID)*EHK(ID)
                  RADRES=RAD1(ID)-RLAM*BNUE(IJ)*ELIN
c                 RADRES=RAD1(ID)-RLAM*BNUE(IJ)*EMTRA(ITR,ID)
                  BNURES=BNUE(IJ)*(UN-RLAM*(ABTRA(ITR,ID)-ELIN))
c                 BNURES=BNUE(IJ)*(UN-RLAM*ABTRA(ITR,ID))
                  RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RADRES
                  RRD(ITR,ID)=RRD(ITR,ID)+SGW0*(RADRES+BNURES)*EHK(ID)
c                 RRD(ITR,ID)=RRD(ITR,ID)+SGW0*(RADRES+BNURES)
c                 RRD(ITR,ID)=RRD(ITR,ID)+SGW0*(RAD1(ID)+BNURES)
               END DO
c
CC             itrprd=iprd(itr)
C   TEMPORARY
               ITRPRD=0
               if(itrprd.gt.0) then
               s=un/(0.02654*osc0(itr))
               do id=1,nd
                  sg=prflin(id,ij)*s
CC                pjbar(itrprd,id)=pjbar(itrprd,id)+sg*w(ij)*rad1(id)
               end do
               end if
c
            END IF
C
C        the "overlapping" lines at the given frequency
C
            LLOOP: DO ILINT=1,NLINES(IJ)
               ITR=ITRLIN(ILINT,IJ)
               if(linexp(itr)) CYCLE LLOOP
               IJ0=IFR0(ITR)
               DO IJT=IJ0,IFR1(ITR)
                  IF(FREQ(IJT).LE.FR) THEN
                     IJ0=IJT
                     EXIT
                  END IF
               END DO
               IJ1=IJ0-1
!            write(*,"(a,5i6)") 'ij,ilint,itr',ij,ij0,ij1,ilint,itr
               A1=(FR-FREQ(IJ0))/(FREQ(IJ1)-FREQ(IJ0))
               A2=UN-A1
               II=ILOW(ITR)
               JJ=IUP(ITR)
!            write(*,"(a,5i6)") 'ij,ilint,itr',ij,ij0,ij1,ilint,itr
               DO ID=1,ND
                  IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
                  SG=A1*PRFLIN(ID,IJ1)+A2*PRFLIN(ID,IJ0)
                  SGW0=SG*W0
                  RLAM=SG*ALAB(ID)
                  ELIN=EMTRA(ITR,ID)*EHK(ID)
!                 write(6,"(a,i4,1p4e12.4)") 
!    &            'sgr',id,sg,sgw0,abtra(itr,id),emtra(itr,id)
c                 RADRES=RAD1(ID)-RLAM*BNUE(IJ)*EMTRA(ITR,ID)
c                 BNURES=BNUE(IJ)*(UN-RLAM*ABTRA(ITR,ID))
c                 RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RADRES
c                 RRD(ITR,ID)=RRD(ITR,ID)+SGW0*(RAD1(ID)+BNURES)
                  RADRES=RAD1(ID)-RLAM*BNUE(IJ)*ELIN
                  BNURES=BNUE(IJ)*(UN-RLAM*(ABTRA(ITR,ID)-ELIN))
                  RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RADRES
                  RRD(ITR,ID)=RRD(ITR,ID)+SGW0*(RADRES+BNURES)*EHK(ID)
!                 write(6,"(a,i4,1p2e12.4)") 
!    &            'rru',id,rru(itr,id),rrd(itr,id)
               END DO
!              write(*,*) 'end loop id',id
c            write(*,*) 'ilint,ij,itr',ilint,ij,itr
CC           write(*,*) 'iprd',iprd(itr)
CC             itrprd=iprd(itr)
!!             itrprd=0
!!             if(itrprd.gt.0) then
!!                s=un/(0.02654*osc0(itr))
!!                do id=1,nd
!!                   SG=(A1*PRFLIN(ID,IJ1)+A2*PRFLIN(ID,IJ0))*s
!!                   pjbar(itrprd,id)=pjbar(itrprd,id)+sg*w(ij)*rad1(id)
!!                end do
!!             end if
c
!              write(*,*) 'end do lloop',itr
            END DO LLOOP
C
C     Opacity sampling option
C
         ELSE
           LLOOPS: DO ILINT=1,NLINES(IJ)
              ITR=ITRLIN(ILINT,IJ)
              KJ=IJ-IFR0(ITR)+KFR0(ITR)
              INDXPA=IABS(INDEXP(ITR))
              II=ILOW(ITR)
              JJ=IUP(ITR)
!!            write(*,"(a,5i5)") 'line',ilint,itr,ii,jj,kj
              IF(INDXPA.NE.3 .AND. INDXPA.NE.4) THEN
                 DO ID=1,ND
                    IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
                    SG=PRFLIN(ID,KJ)
                    SGW0=SG*W0
                    RLAM=SG*ALAB(ID)
                    ELIN=EMTRA(ITR,ID)*EHK(ID)
c                   RADRES=RAD1(ID)-RLAM*BNUE(IJ)*EMTRA(ITR,ID)
c                   BNURES=BNUE(IJ)*(UN-RLAM*ABTRA(ITR,ID))
c                   RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RADRES
c                   RRD(ITR,ID)=RRD(ITR,ID)+SGW0*(RAD1(ID)+BNURES)
                    RADRES=RAD1(ID)-RLAM*BNUE(IJ)*ELIN
                    BNURES=BNUE(IJ)*(UN-RLAM*(ABTRA(ITR,ID)-ELIN))
                    RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RADRES
                    RRD(ITR,ID)=RRD(ITR,ID)+SGW0*(RADRES+BNURES)*EHK(ID)
!!                  if(id.eq.1) write(*,*) 'linr',itr,ii,jj,rru(itr,id)
                 END DO
              ELSE
                 DO ID=1,ND
                    IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
                    KJD=JIDI(ID)
                    SG=EXP(XJID(ID)*SIGFE(KJD,KJ)+
     *                 (UN-XJID(ID))*SIGFE(KJD+1,KJ))
                    SGW0=SG*W0
                    RLAM=SG*ALAB(ID)
                    ELIN=EMTRA(ITR,ID)*EHK(ID)
c                   RADRES=RAD1(ID)-RLAM*BNUE(IJ)*EMTRA(ITR,ID)
c                   BNURES=BNUE(IJ)*(UN-RLAM*ABTRA(ITR,ID))
c                   RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RADRES
c                   RRD(ITR,ID)=RRD(ITR,ID)+SGW0*(RAD1(ID)+BNURES)
                    RADRES=RAD1(ID)-RLAM*BNUE(IJ)*ELIN
                    BNURES=BNUE(IJ)*(UN-RLAM*(ABTRA(ITR,ID)-ELIN))
                    RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RADRES
                    RRD(ITR,ID)=RRD(ITR,ID)+SGW0*(RADRES+BNURES)*EHK(ID)
                 END DO
              END IF
           END DO LLOOPS
         END IF
      END DO FRLOOP
C
C     radiation pressure
C
      PRDX=1.
      DO ID=1,ND
         PRADT(ID)=PRADT(ID)*PCK
         PRADA(ID)=PRADA(ID)*PCK
         if(prada(id).gt.0.) PRDR=PRADT(ID)/PRADA(ID)
         IF(PRDR.LT.PRDX) PRDX=PRDR
!        write(6,"(a,i4,1p2e12.4)") 'prad',id,pradt(id),prada(id)
      END DO
      PRD0=PRD0/DENS1(1)*DM(1)*PCK
CC    IF(LFIN) WRITE(10,"(' PRAD MIN RATIO ',F10.6,I4)") PRDX,ITER
C
C     Rosseland mean opacity
C
      IF(LROSS) THEN
      DO ID=1,ND
         ABROSD(ID)=SUMDPL(ID)/(ABROSD(ID)*DENS(ID))
!        write(6,"(a,i4,1pe12.4)") 'ross',id,abrosd(id)
      END DO
      END IF

      RETURN
      END SUBROUTINE RATSP1


!*********************************************************************


      SUBROUTINE COLIS(ID,T)
C     ======================
C
C     Driving procedure for evaluation of the collisional rates
C
C     Input:  T   - temperature
C     Output: COL - array of quantities proportional to the
C                   collisional rates in all transitions
C                   for a given temperature (ie. at a given depth)
C                   Precisely,  COL(IT)*Nlow(IT)  is the UPWARD
C                   collisional rate of the transition IT
C     Output: CLOC - array of quantities proportional to the
C                   collisional rates in all transitions
C                   for a given temperature (ie. at a given depth)
C                   Precisely, CLOC(IT)*Nupp(IT) is the DOWNWARD
C                   collisional rate of the transition IT
C
C     Procedure COLIS calls procedures COLH and COLHE for evaluating
C     the collisional rates in hydrogen and helium,
C     and itself evaluates collisional rates for other species
C
C     Evaluation is controlled by input parameter ICOL(ITR).
C     Meaning of ICOL for all species, excluding hydrogen and helium:
C
C      a) for ionization
C         ICOL = 0  - Seatons formula ; here the value of the photo-
C                     ionization cross section at the threshold is
C                     transmitted in array OSC0
C              = 1  - Allen's formula; again, OSC0 has the meaning of
C                     the necessary multiplicative parameter
C              = 2  - the so-called SIMPLE1 mode - see below
C              = 3  - the so-called SIMPLE2 mode - see below
C      b) for excitation
C         ICOL = 0  - Van Regemorter formula, with standard g(bar)=0.25
C              = 1  - Van Regemorter formula, with "exact" g(bar)
C              = 2  - the so-called SIMPLE1 mode - see below
C              = 3  - the so-called SIMPLE2 mode - see below
C              = 4  - Eissner-Seaton formula - see below
C
C
      use accura
      use atomic
      use basics
      use modelq
!     use odfpar
      use ctdata

      implicit none      

      INTEGER, INTENT(IN)  :: ID
      REAL(DP), INTENT(IN) :: T 

      REAL(DP), PARAMETER :: EXPIA1=-0.57721566,EXPIA2=0.99999193,
     *           EXPIA3=-0.24991055,EXPIA4=0.05519968,
     *           EXPIA5=-0.00976004,EXPIA6=0.00107857,
     *           EXPIB1=0.2677734343,EXPIB2=8.6347608925,
     *           EXPIB3=18.059016973,EXPIB4=8.5733287401,
     *           EXPIC1=3.9584969228,EXPIC2=21.0996530827,
     *           EXPIC3=25.6329561486,EXPIC4=9.5733223454
      REAL(DP) :: CCRATE(MCFIT),CCTEMP(MCFIT)
      INTEGER  :: TYPEARR(MXTCOL)

      REAL(DP) :: ANH,ANE,AHM,HKT,SRT,T32,TK,CSTD,T0,TT0,SRT0,CORR,
     *            C1,C2,U0,U0HM,U0P,CINV,CS,CINH,! HCTION,CSEATN,CALLEN,
!    *            CSMPL1,CSMPL2,
     *            RNO,REL,XJ,GG,EXPIU0,GG0,CC1,YLINTP,CION

      INTEGER  :: NKE,N0I,NKI,I,IE,J,IT,IC,K,IORICE,ITYPE,NX,IA,IZC,II,
     *            N0Q,N1Q,IQ,JQ,IAT
C
      DO I=1,NTRANS
         CLOC(I)=0.
         COL(I)=0.
      END DO
C
C calculate collider's populations: e, p, H(1s)
C     ANE :  Electron
C     ANP :  Proton
C     AHM :  H-
C     ANH :  H(1s)

      ANE=ELEC(ID)
c
      IF (IELH.gt.0) THEN ! if H is an explicit atom
         ANP=POPUL(NNEXT(IELH),ID) ! Protons
         ANH=POPUL(NFIRST(IELH),ID) ! H(1s)
       else
         anh=ahtot-anp
      END IF
      IF (IELHM.gt.0) THEN
         AHM=POPUL(NFIRST(IELHM),ID) ! if H- is an explicit atom
       else
         ahm=1.0353e-16/t/sqrt(t)*exp(8762.9/t)*anh*ane
      END IF
C
      HKT=HK/T
      SRT=SQRT(T)
      T32=UN/T/SRT
      TK=HKT/H
      CSTD=0.25
      T0=TEFF
      TT0=0.
      SRT0=0.
      if(t0.gt.0.) then
         TT0=UN-T/T0
         SRT0=SQRT(T0)/SRT
      end if
C
C     Call procedures COLH and COLHE for hydrogen and helium
C
      IF(IATH.NE.0) CALL COLH(ID,T)
      IF(IATHE.NE.0) THEN
         CALL COLHE(T)
         IF(IELHE2.GT.0) CALL COLHE2(T)
      END IF
      IF(IATH.NE.0.OR.IATHE.NE.0) THEN
         DO I=1, NTRANS
            COL(I)=COL(I) * ANE
            IF (LINE(I)) THEN
               CLOC(I)=COL(I) * EXP(FR0(I)*HKT)*G(ILOW(I))/G(IUP(I))
            ELSE
               CORR=UN
               NKE=NNEXT(IEL(ILOW(I)))
               IF(NKE.NE.IUP(I)) CORR=G(NKE)/G(IUP(I))*
     *              EXP((ENION(NKE)-ENION(IUP(I)))*TK)
               CLOC(I)=COL(I) * ANE * SBF(ILOW(I))*CORR
            ENDIF
          END DO
      END IF
C
C     Loop over all explicit species, excluding hydrogen and helium
C
      ATOMS: DO IAT=1,NATOM
         IF(IAT.EQ.IATH.OR.IAT.EQ.IATHE) CYCLE ATOMS
         N0I=N0A(IAT)
         NKI=NKA(IAT)
         LOWER: DO I=N0I,NKI-1
            IE=IEL(I)
            UPPER: DO J=I+1,NKI
               IT=ITRA(I,J)
               IF(IT.EQ.0) CYCLE UPPER
               IC=ICOL(IT)
               COL(IT)=0.0
               CLOC(IT)=0.0
               C1=OSC0(IT)
               C2=CPAR(IT)
               U0=FR0(IT)*HKT
               U0HM=U0-8752.072/T ! including H-minus potential !
               U0P =U0-157821.5/T ! including H-proton potential!
               DO K=1, MXTCOL
                  TYPEARR(K)=0
               ENDDO
C
C=============
C============= collisional ionization block

               IF(.NOT.LINE(IT)) THEN
C
C     the detailed balancing factor for an inverse process
C
                  CORR=UN
                  NKE=NNEXT(IEL(I))
                  IF(NKE.NE.J) CORR=G(NKE)/G(J)*
     *               EXP((ENION(NKE)-ENION(J))*TK)
                  CINV=ANE*SBF(I)*CORR
C
C     *********** tabulated data ***************
C     For collisional processes that change the total
C     charge of the target atom, there are three
C     processes considered here:
C     - TYPE 1 Electron Collisional ionization
C     - TYPE 2 Charge exchange with protons
C     - TYPE 3 Charge exchange with hydrogen
C
C     There are several 'calculated' options in the code for
C     electron collisional excitation that are
C     neglected if TYPE 1 tabulated data are present.
C
C     There is also an option for TYPE 2 that is calculated
C     here (ICOL ge 10) that is also overriden if TYPE 2 is
C     present.
                  IF (IC.GE.1000) THEN
                     IORICE=1
                     IF (IC.LT.0) IORICE=-1
                     IC=ABS(IC)
                     ITYPE=IC/1000
                     IC=IORICE*(MOD(IC,1000)-1) !ICOL RECOVERED
                     DO K=1, MXTCOL
                        TYPEARR(K)=MOD(ITYPE/(2**(K-1)),2)
                     ENDDO
C
C ****** START 'GENCOL' FOR IONIZATION **********
C
C ****** ELECTRON COLLISIONAL IONIZATION *****
                     IF (TYPEARR(1).EQ.1) THEN
                        NX=0
                        DO K=1,MCFIT
                           IF (CTEMP(1,K,IT).NE.0) THEN
                              CCRATE(K)=log(CRATE(1,K,IT))
                              CCTEMP(K)=CTEMP(1,k,IT)
                              NX=NX+1
                           ELSE    ! CLEAN CC**** ARRAYS
                              CCRATE(K)=0.
                              CCTEMP(K)=0.
                           ENDIF
                        ENDDO
                        cs=ylintp(t,cctemp,ccrate,nx,mcfit)
                        CS=ANE*exp(CS)
                        COL(IT)=COL(IT) + CS !UPPWARD
                        CLOC(IT)=CLOC(IT) + CS*CINV !DOWNWARD
                     ENDIF
C     ****** CHARGE EXCHANGE WITH PROTONS *******
                     IF (TYPEARR(2).EQ.1) THEN
                        NX=0
                        DO K=1,MCFIT
                           IF (CTEMP(2,K,IT).NE.0) THEN
                              CCRATE(K)=log(CRATE(2,K,IT))
                              CCTEMP(K)=CTEMP(2,K,IT)
                              NX=NX+1
                           ELSE    ! CLEAN CC**** ARRAYS
                              CCRATE(K)=0.
                              CCTEMP(K)=0.
                           ENDIF
                        ENDDO
                        cs=ylintp(t,cctemp,ccrate,nx,mcfit)
                        cs=exp(cs)*ANP
                        COL(IT)=COL(IT) + CS ! UPPWARD
                        CINH=G(I)/G(J)*0.5*EXP(U0P)
                        CLOC(IT)=CLOC(IT) + CS*CINH*ANH !DOWNWARD
                     ENDIF
C     ******* CHARGE EXCHANGE WITH HYDROGEN *****
                     IF (TYPEARR(3).EQ.1) THEN
                        NX=0
                        DO K=1,MCFIT
                           IF (CTEMP(3,K,IT).NE.0) THEN
                              CCRATE(K)=log(CRATE(3,K,IT))
                              CCTEMP(K)=CTEMP(3,K,IT)
                              NX=NX+1
                           ELSE    ! CLEAN CC**** ARRAYS
                              CCRATE(K)=0.
                              CCTEMP(K)=0.
                           ENDIF
                        ENDDO
                        cs=ylintp(t,cctemp,ccrate,nx,mcfit)
                        cs=exp(cs)*ANH
                        COL(IT)=COL(IT) + CS ! UPPWARD
                        CINH=G(I)/G(J)*TWO*EXP(U0HM)
                        CLOC(IT)=CLOC(IT) + CS*CINH*AHM !DOWNWARD
                     ENDIF
C     ************** END GENCOL ******************
                     IF (IC.EQ.-1) CYCLE UPPER
                  ENDIF
C
C ********* Charge transfer with protons reactions- an old scheme
C
                  IF(IC.GE.10) THEN
                     IF(TYPEARR(2).NE.1) THEN
C               radiative charge transfer ionization of neutrals in the
C               grround state with protons
                        CS=HCTIon(1,NUMAT(IAT),T)
                        CS=CS*ANP
                        COL(IT)=COL(IT) + CS !UPPWARD
                        CS=CS*0.5*G(I)/G(J) * EXP(U0P)
                        CLOC(IT)=CLOC(IT) + CS*ANH !DOWNWARD
                     ENDIF
                     IC=IC-10
                     IF(TYPEARR(1).eq.1) CYCLE UPPER
                  END IF

C
C ********* Electron collisional ionization
C
                  SELECT CASE(IC)
                  CASE(0)
                    CS=CSEATN(UN/SRT,U0,C1)*ANE
                    COL(IT)=COL(IT)+CS
                  CASE(1)
                    CS=CALLEN(T32,U0,C1)*ANE
                    COL(IT)=COL(IT)+CS
                  CASE(2)
                    CS=CSMPL1(SRT,U0,C1)*ANE
                    COL(IT)=COL(IT)+CS
                  CASE(3)
                    CS=CSMPL2(SRT,U0,C1)*ANE
                    COL(IT)=COL(IT)+CS
                  CASE(4)
                    ia=numat(iatm(i))
                    CS=cion(ia,iz(iel(i)),enion(i)*6.24298e11,t)*ANE
                    COL(IT)=COL(IT)+CS
                  CASE(5)
                    ia=numat(iatm(i))
                    izc=iz(ie)
                    rno=16.
                    ii=i-nfirst(ie)+1
                    call irc(ii,t,izc,rno,cs)
                    CS=CS*ANE
                    col(it)=COL(IT)+CS
                  CASE(:-1)
                    CALL CSPEC(I,J,IC,C1,C2,U0,T,CS)
                    CS=CS*ANE
                    COL(IT)=COL(IT)+CS
                  END SELECT
                  CLOC(IT)=CLOC(IT)+CS*CINV !DOWNWARD
                  if(ic.eq.4) cycle upper
C
C     collisional excitations from level I to higher, non-explicit
C      levels are lumped into the collisional ionization rate
C      (the so-called modified collision ionization rate)
C
                  N0Q=NQUANT(NLAST(IE))+1
                  N1Q=ICUP(IE)
                  IF(N1Q.ge.0) CYCLE UPPER
                  IQ=NQUANT(I)
                  REL=G(I)/2./IQ/IQ
                  HIGH: DO JQ=N0Q,N1Q
                     XJ=JQ
                     U0=(ENION(I)-EH/XJ/XJ)*TK
                     IF(JQ.LE.20) CC1=OSH(IQ,JQ)*REL
                     IF(JQ.GT.20) CC1=OSH(IQ,20)*(20./XJ)**3*REL
                     GG=CSTD
                     if(u0.gt.35.) CYCLE HIGH
                     IF(U0.LE.UN) THEN
                        EXPIU0=-LOG(U0)+EXPIA1+U0*(EXPIA2+
     *                  U0*(EXPIA3+U0*(EXPIA4+
     *                  U0*(EXPIA5+U0*EXPIA6))))
                      ELSE
                        EXPIU0=EXP(-U0)*((EXPIB1+U0*(EXPIB2+
     *                  U0*(EXPIB3+
     *                  U0*(EXPIB4+U0))))/(EXPIC1+U0*(EXPIC2+
     *                  U0*(EXPIC3+U0*(EXPIC4+U0)))))/U0
                     END IF
                     GG0=0.276*EXP(U0)*EXPIU0
                     IF(GG0.GT.GG) GG=GG0
                     CS=CREGER(T32,U0,CC1,GG)*ANE
                     COL(IT)=COL(IT)+CS !UPPWARD
                     CLOC(IT)=CLOC(IT)+CS*ANE*SBF(I)*CORR !DOWNWARD
                  END DO HIGH
                  CYCLE UPPER
C
C =========
C ========= Collisional excitation block
C
               ELSE
C
C           the detailed balancing factor for an inverse process
C
                  CINV=EXP(U0)*G(I)/G(J)
C
c **********  Tabulated Data
                  IF (IC.GE.1000) THEN
                     IORICE=1
                     IF (IC.LT.0) IORICE=-1
                     IC=ABS(IC)
                     ITYPE=IC/1000
                     IC=IORICE*(MOD(IC,1000)-1) !ICOL RECOVERED
                     DO K=1, MXTCOL
                        TYPEARR(K)=MOD(ITYPE/(2**(K-1)),2)
                     END DO


C ****** START 'GENCOL' FOR EXCITATION **********
C
C ****** ELECTRON COLLISIONAL EXCITATION *****
                     IF (TYPEARR(1).EQ.1) THEN
                        NX=0
                        DO K=1,MCFIT
                           IF (CTEMP(1,K,IT).NE.0) THEN
                              CCRATE(K)=log(CRATE(1,K,IT))
                              CCTEMP(K)=CTEMP(1,K,IT)
                              NX=NX+1
                           ELSE       !CLEAN CC**** ARRAYS
                              CCRATE(K)=0.
                              CCTEMP(K)=0.
                           ENDIF
                        END DO
                        cs=ylintp(t,cctemp,ccrate,nx,mcfit)
                        CS=exp(CS)*ANE
                        COL(IT)=COL(IT) + CS ! UPPWARD
                           CLOC(IT)=CLOC(IT) + CS*CINV ! DOWNWARD
                     END IF
C ****** PROTON COLLISIONAL EXCITATION *******
                     IF (TYPEARR(2).EQ.1) THEN
                        NX=0
                        DO K=1,MCFIT
                           IF (CTEMP(2,K,IT).NE.0) THEN
                              CCRATE(K)=log(CRATE(2,K,IT))
                              CCTEMP(K)=CTEMP(2,K,IT)
                              NX=NX+1
                           ELSE       !CLEAN CC**** ARRAYS
                              CCRATE(K)=0.
                              CCTEMP(K)=0.
                           ENDIF
                        END DO
                        cs=ylintp(t,cctemp,ccrate,nx,mcfit)
                        CS=exp(CS)*ANP
                        COL(IT)=COL(IT) + CS ! UPPWARD
                        CLOC(IT)=CLOC(IT) + CS*CINV ! DOWNWARD
                     END IF
C ******* HYDROGEN COLLISIONAL EXCITATION  *****
                     IF (TYPEARR(3).EQ.1) THEN
                        NX=0
                        DO K=1,MCFIT
                           IF (CTEMP(3,K,IT).NE.0) THEN
                              CCRATE(K)=log(CRATE(3,K,IT))
                              CCTEMP(K)=CTEMP(3,K,IT)
                              NX=NX+1
                            ELSE       !CLEAN CC**** ARRAYS
                              CCRATE(K)=0.
                              CCTEMP(K)=0.
                           ENDIF
                        END DO
                        cs=ylintp(t,cctemp,ccrate,nx,mcfit)
                        CS=exp(CS)*ANH
                        COL(IT)=COL(IT) + CS ! UPPWARD
                        CLOC(IT)=CLOC(IT) + CS*CINV ! DOWNWARD
                     END IF
C ************** END GENCOL ******************
                     IF (IC.EQ.-1) CYCLE UPPER
                  END IF
                  IF(IC.LE.1.AND.IC.GT.0) THEN
                     GG=CSTD
                     IF(IC.EQ.1) GG=C2
                     IF(U0.LE.UN) THEN
                        EXPIU0=-LOG(U0)+EXPIA1+
     *                  U0*(EXPIA2+U0*(EXPIA3+U0*(EXPIA4+
     *                  U0*(EXPIA5+U0*EXPIA6))))
                      ELSE
                        EXPIU0=EXP(-U0)*((EXPIB1+U0*
     *                  (EXPIB2+U0*(EXPIB3+
     *                  U0*(EXPIB4+U0))))/(EXPIC1+U0*(EXPIC2+
     *                  U0*(EXPIC3+U0*(EXPIC4+U0)))))/U0
                     END IF
                     GG0=0.276*EXP(U0)*EXPIU0
                     IF(GG0.GT.GG) GG=GG0
                     CS=CREGER(T32,U0,C1,GG)*ANE
                     COL(IT)=COL(IT) + CS ! UPPWARD
                   ELSE IF(IC.EQ.2) THEN
                     CS=CSMPL1(SRT,U0,C1*C2)*ANE
                     COL(IT)=COL(IT) + CS ! UPPWARD
                   ELSE IF(IC.EQ.3) THEN
                     CS=CSMPL2(SRT,U0,C2)*ANE
                     COL(IT)=COL(IT) + CS ! UPPWARD
                   ELSE IF(IC.EQ.4) THEN
                     CS=CUPSX(SRT,U0,C2/G(I))*ANE
                     COL(IT)=COL(IT) + CS ! UPPWARD
                   ELSE IF(IC.EQ.9) THEN
                     CS=OMECOL(I,J)*SRT0*EXP(-U0*TT0) * ANE
                     COL(IT)=COL(IT) + CS ! UPPWARD
                   ELSE IF(IC.LT.0) THEN
                     CALL CSPEC(I,J,IC,C1,C2,U0,T,CS)
                     CS=CS*ANE
                     COL(IT)=COL(IT) + CS ! UPPWARD
                  END IF
                  CLOC(IT)=CLOC(IT) + CS*CINV ! DOWNWARD
               END IF
            END DO UPPER
         END DO LOWER
      END DO ATOMS
      RETURN

      CONTAINS
         REAL(DP) FUNCTION CREGER(X,U,A,GG)
            REAL(DP), INTENT(IN) :: X,U,A,GG
            CREGER=19.7363*X*EXP(-U)/U*GG*A
         END FUNCTION CREGER

!        ********************************************************

         REAL(DP) FUNCTION CSEATN(X,U,A)
            REAL(DP), INTENT(IN) :: X,U,A
            CSEATN=1.55e13*X/ABS(U)*EXP(-U)*A
         END FUNCTION CSEATN


!        ********************************************************

         REAL(DP) FUNCTION CALLEN(X,U,A)
            REAL(DP), INTENT(IN) :: X,U,A
            CALLEN=X*A*EXP(-U)/U/U
         END FUNCTION CALLEN


!        ********************************************************

         REAL(DP) FUNCTION CSMPL1(X,U,A)
            REAL(DP), INTENT(IN) :: X,U,A
            CSMPL1=5.465e-11*X*EXP(-U)*A
         END FUNCTION CSMPL1


!        ********************************************************

         REAL(DP) FUNCTION CSMPL2(X,U,A)
            REAL(DP), INTENT(IN) :: X,U,A
            CSMPL2=5.465e-11*X*EXP(-U)*A*(1.+U)
         END FUNCTION CSMPL2


!        ********************************************************

         REAL(DP) FUNCTION CUPSX(X,U,A)
            REAL(DP), INTENT(IN) :: X,U,A
            CUPSX=8.631e-6/X*EXP(-U)*A
         END FUNCTION CUPSX


!        ********************************************************

         REAL(DP) FUNCTION HCTION(ION,NELEM,TE)
c
c     ion is stage of ionization, 1 for atom
c     nelem is atomic number of element, 2 up to 30
c     Example:  O + H+ => O+ + H is HCTIon(1,8)
    
            use accura
            use ctdata

            implicit none

            INTEGER, INTENT(IN) :: ION,NELEM
            REAL(DP),INTENT(IN) :: TE
            REAL(DP) :: TUSED
            INTEGER  :: IPION
c
            ipIon = ion
c
c     Make sure te is between temp. boundaries; set constant outside of range
            tused = max( te,CTIon(5,ipIon,nelem) )
            tused = min( tused , CTIon(6,ipIon,nelem) )
            tused = tused * 1e-4
c
c     the interpolation equation
            HCTIon = CTIon(1,ipIon,nelem)* 1e-9 *
     *      (tused**CTIon(2,ipIon,nelem)) * (1. +
     *      CTIon(3,ipIon,nelem) * 
     *      exp(CTIon(4,ipIon,nelem)*tused) ) *
     *      exp(-CTIon(7,ipIon,nelem)/tused)
c
         END FUNCTION HCTION

!     ********************************************************



      END SUBROUTINE COLIS


!*********************************************************************


      SUBROUTINE COLH(ID,T)
C     =====================
C
C     Hydrogen collision rates
C
C     All standard expressions  are taken from Mihalas, Heasley, and
C     Auer, NCAR-TN/STR-104 (1975)
C
C     New expressions (also from Mihalas) for collisional ionization
C     for first 10 levels taken from Klaus Werner.
C
C     New standard expressions from Giovanardi et al. (1987, AAS, 70, 29)
C      for collisional excitation (valid from 3000K to 500000K)
C
C     Meaning of ICOL:
C      a) for ionization - .ge.0  - standard expression
C                           <  0  - non-standard, user suplied formula
C      b) for 1 - 2 transition =0 - standard theoretical formula
C                             = 1 - experimental fit (formula quted in
C                                   Mihalas et al.)
C                             = 2 - formula by Crandall et al (procedure
C                                   CEH12)
C      c) for all other line transitions
C                           .ge.0 - standard expression
C                            <  0 - non-standard, user supplie formula
C
      use accura
      use atomic
      use basics
      use modelq

      implicit none

      INTEGER,  INTENT(IN) :: ID
      REAL(DP), INTENT(IN) :: T

       REAL(DP) :: HKT,CT,TK,T0,X,X2,X3,X4,X5,SQT,SUM1,SUM2,EHK,XI,
     &             XII,RNO,CS,U0,GAM,VI,ALF,BET,CSUM,CSCA,XJ,VJ,E,C1,
     &             EX,E1,E5,CEH12
       INTEGER  :: N1H,NKH,N0Q,N1Q,II,I,IT,N00Q,N11Q,IMG,IZC,IC,
     &             I1,NHL,N1HC,J,JJ,K,ICT,ITH,ICA,IERR,IX


      REAL(DP), PARAMETER :: CC0   =   5.465e-11,
     *           CEX1  = -30.20581,
     *           CEX2  =   3.8608704,
     *           CEX3  = 305.63574,
     *           CI1   =   0.3,
     *           CI2   =   0.435,
     *           CA1   =   5.444416e7,
     *           CA2   =  -2.8185937e4,
     *           CA3   =  19.987261,
     *           CA4   =  -5.8906298e-5,
     *           CB1   =   1.3935312e3,
     *           CB2   =  -1.6805859e2,
     *           CB3   =  -2.539D3,
     *           CC1   =   2.0684609e3,
     *           CC2   =  -3.341582e2,
     *           CC3   =  -7.6440625e3,
     *           CD1   =   3.2174844e3,
     *           CD2   =  -5.5882422e2,
     *           CD3   =  -6.86325e3,
     *           CE1   =   5.759125e3,
     *           CE2   =  81.75,
     *           CE3   =  -1.5163e3,
     *           CF1   =   1.461475e4,
     *           CF2   = 393.4,
     *           CF3   =  -4.8284e3,
     *           ALF0  =   1.8,
     *           ALF1  =   0.4,
     *           BET0  =   3.0,
     *           BET1  =   1.2,
     *           O148  =   0.148,
     *           CHMI  =   5.59e-15
      REAL(DP), PARAMETER :: 
     *           EXPIA1=-0.57721566,EXPIA2=0.99999193,
     *           EXPIA3=-0.24991055,EXPIA4=0.05519968,
     *           EXPIA5=-0.00976004,EXPIA6=0.00107857,
     *           EXPIB1=0.2677734343,EXPIB2=8.6347608925,
     *           EXPIB3=18.059016973,EXPIB4=8.5733287401,
     *           EXPIC1=3.9584969228,EXPIC2=21.0996530827,
     *           EXPIC3=25.6329561486,EXPIC4=9.5733223454
      REAL(DP) :: A(6,10),CCOOL(4,14,15),CHOT(4,14,15),XTT(4)
