     . 4.6651e-07,-9.3659e-07,-2.7485e-07, 1.2462e-05, 6.2559e-07,
     .-6.1634e-07,-5.1080e-07, 1.2493e-02, 8.2057e-03, 2.9562e-03,
     . 3.3090e-04,-3.7349e-04,-2.8886e-04,-7.4606e-05, 1.2726e-05,
     .-1.6480e-07,-1.5006e-06,-1.1181e-07, 1.4846e-07, 8.7160e-03,
     . 4.2652e-03, 5.2455e-04,-2.6363e-04,-7.9836e-05/
C
C     SET ALL ELEMENTS OF COLHE1 = 0
C
      DO I=1,N
         DO J=1,N
            COLHE1(I,J)=0.
         END DO
      END DO
C
C     EVALUATE GAMMAS FOR REQUESTED LEVELS
C
      XXX=2.D0*(LOG10(T)-C1)/C2
      TFAC=UN/SQRT(T)
C
C     LOOPS OVER LEVELS
C
      DO IL=1,N-1
         DO IU=IL+1,N
            J=((IU*IU-3*IU+4)/2)+IL-1
            N1=NSTART(J)
            NF=NSTART(J+1)-1
            NT=NF-N1+1
            NTM2=NT-2
C
C           CLENSHAW SUMMATION
C
            B(NT)=A(NF)
            B(NT-1)=XXX*B(NT)+A(NF-1)
            IR=NTM2
            JJ=NF-2
            DO J=1,NTM2
               B(IR)=XXX*B(IR+1)-B(IR+2)+A(JJ)
               IR=IR-1
               JJ=JJ-1
            END DO
            COLHE1(IU,IL)=(B(1)-B(3))*TFAC
            X=(ENER(IL)-ENER(IU))/8.62D-5/T
            COLHE1(IL,IU)=COLHE1(IU,IL)*STWT(IU)/STWT(IL)*EXP(X)
         END DO
      END DO
      RETURN
      END SUBROUTINE COLLHE


