      SUBROUTINE CSPEC(I,J,IC,OS,CP,U0,T,CS)
C     ======================================
C
C     Non-standard evaluation of collision rates
C     Basically user-supplied procedure; here is an example
C
C      Van Regemorter's formula following the recommendations of
C         Mihalas (1978, Stellar Atmospheres, 2nd edition)
C       IC=-1 for neutrals
C        IC=-2 for ions
C
      use accura
      use atomic
      use basics

      implicit none

      INTEGER,INTENT(IN)  :: I,J,IC
      REAL(DP),INTENT(IN) :: OS,CP,U0,T
      REAL(DP),INTENT(OUT):: CS

      REAL(DP) :: EXPIU0,GG0,GG,T32,XR,XT,GAM
      INTEGER  :: N0I,IFORB,IK,JK

      REAL(DP), PARAMETER :: 
     *           EXPIA1=-0.57721566,EXPIA2=0.99999193,
     *           EXPIA3=-0.24991055,EXPIA4=0.05519968,
     *           EXPIA5=-0.00976004,EXPIA6=0.00107857,
     *           EXPIB1=0.2677734343,EXPIB2=8.6347608925,
     *           EXPIB3=18.059016973,EXPIB4=8.5733287401,
     *           EXPIC1=3.9584969228,EXPIC2=21.0996530827,
     *           EXPIC3=25.6329561486,EXPIC4=9.5733223454
      REAL(DP) :: CHE1FB(3,4)
      DATA CHE1FB/ 9.63675,-2.22941,-17.30103,
     *            10.85578,-2.40931,-27.00903,
     *             8.38043,-2.04791,-7.36621,
     *             6.95825,-2.01967,-5.98779/

      CS=0.

      IF(IC.GT.-10) THEN

               IF(U0.LE.UN) THEN
         EXPIU0=-LOG(U0)+EXPIA1+U0*(EXPIA2+U0*(EXPIA3+U0*(EXPIA4+
     *            U0*(EXPIA5+U0*EXPIA6))))
               ELSE
         EXPIU0=EXP(-U0)*((EXPIB1+U0*(EXPIB2+U0*(EXPIB3+
     *           U0*(EXPIB4+U0))))/(EXPIC1+U0*(EXPIC2+
     *           U0*(EXPIC3+U0*(EXPIC4+U0)))))/U0
               END IF

CCCCCC Neutrals (See Auer & Mihalas 1973)

        GG=1.
        IF(IC.EQ.-1) THEN

           IF(U0.LE.14.) THEN
               GG=0.276*EXP(U0)*EXPIU0
           ELSE
               GG=0.066*(1.+1.5/U0)/SQRT(U0)
           ENDIF

CCCCCC Ions (See Mihalas 1972)
        ELSE IF(IC.EQ.-2) THEN

           GG0=0.276*EXP(U0)*EXPIU0
           GG=CP
           IF(GG0.GT.CP) GG=GG0

        END IF
        T32=T**(-1.5)
        CS=CS+19.7363*T32*EXP(-U0)/U0*GG*OS

        RETURN
      END IF
C
      IF(IC.EQ.-11) THEN
         XR=-1.68D0
         CS=CS+2.16*U0**XR/T/SQRT(T)*EXP(-U0)*OS
C
C     Forbidden transitions between n=2 He I sublevels
C     (from Klaus Werner)
C
       ELSE IF(IC.EQ.-12) THEN
         N0I=NFIRST(IELHE1)
         IK=I-N0I+1
         JK=J-N0I+1
         IFORB=0
         IF(IK.EQ.2 .AND. Jk.EQ.3) IFORB=1
         IF(IK.EQ.2 .AND. JK.EQ.5) IFORB=2
         IF(IK.EQ.3 .AND. JK.EQ.4) IFORB=3
         IF(IK.EQ.4 .AND. JK.EQ.5) IFORB=4
         IF(IFORB.EQ.0) CALL QUIT(' Inconsistent ICOL - CSPEC',iforb,0)
         XT=LOG10(T)
         GAM=CHE1FB(1,IFORB)+CHE1FB(2,IFORB)*XT+CHE1FB(3,IFORB)/XT/XT
         GAM=EXP(2.30258509299405*GAM)
         CS=CS+5.465D-11*SQRT(T)*EXP(-U0)*GAM
      END IF

      RETURN
      END SUBROUTINE CSPEC


!*********************************************************************


      SUBROUTINE COLHE2(T)
C     ====================
C    
      use accura
      use basics
      use atomic
      use modelq

      implicit none

      REAL(DP), INTENT(IN) :: T
      REAL(DP), PARAMETER ::
     *           EIA1=-0.57721566,EIA2=0.99999193,
     *           EIA3=-0.24991055,EIA4=0.05519968,
     *           EIA5=-0.00976004,EIA6=0.00107857,
     *           EIB1=0.2677734343,EIB2=8.6347608925,
     *           EIB3=18.059016973,EIB4=8.5733287401,
     *           EIC1=3.9584969228,EIC2=21.0996530827,
     *           EIC3=25.6329561486,EIC4=9.5733223454
      REAL(DP) :: HKT,TK,SRT,CT,CT1,CT2,X,X2,X3,X4,X5,RNO,U0,GAM,XI,
     *            VI,XJ,VJ,C1,EIU0,CS
      INTEGER  :: N0I,N1I,NKI,N0Q,N1Q,I,IT,IZC,IC,I1,NHL,J,JJ,ICT,II

      REAL(DP) :: G0(3),G1(3),G2(3),G3(3),A(6,10)
      DATA G0/ 7.3399521D-2,  1.7252867,      8.6335087    /,
     *     G1/-1.4592763D-7,  2.0944117D-6,   2.7575544D-5 /,
     *     G2/ 7.6621299D5,   5.4254879D6,    6.6395519D6  /,
     *     G3/ 2.3775439D2,   2.2177891D3,    5.20725D3    /
      DATA ((A(I,J),J=1,10),I=1,6) /
     * -8.5931587    , 85.014091    , 923.64099, 2018.6470, 1551.5061  ,
     * -2327.4819    ,-10701.481    ,-27619.789,-41099.602,-61599.023  ,
     *  9.3868790    ,-78.834488    ,-969.18451,-2243.1768,-2059.9768  ,
     *  1546.7107    , 9834.3447    , 27067.436, 41421.254, 63594.133  ,
     * -4.0027571    , 28.360615    , 401.23965, 983.83374, 1051.4103  ,
     * -204.82320    ,-3335.4211    ,-10100.119,-15863.257,-24949.125  ,
     * 0.83941799    ,-4.7963457    ,-81.122566,-209.86169,-251.30855  ,
     * -43.175175    , 530.37292    , 1826.1049, 2941.6460, 4740.8364  ,
     * -.08639670    ,0.37385577    , 8.0078983, 21.757591, 28.375637  ,
     *  11.890312    ,-39.536087    ,-161.52513,-266.86011,-440.88257  ,
     * 0.0034853835  ,-.01040131    ,-.30957383,-.87988985,-1.2254572  ,
     * -.72724497    , 1.0879648    , 5.6239786, 9.5323009, 16.150818  /

      HKT=HK/T
      TK=HKT/H
      SRT=SQRT(T)
      CT=5.465D-11*SRT
      CT1=5.4499487/T/SRT
C
      N0I=NFIRST(IELHE2)
      N1I=NLAST(IELHE2)
      NKI=NNEXT(IELHE2)
      N0Q=NQUANT(NLAST(IELHE2))+1
      N1Q=ICUP(IELHE2)
      X=LOG10(T)
      X2=X*X
      X3=X2*X
      X4=X3*X
      X5=X4*X
      CT2=3.7036489/T/SRT
C
      LOWER: DO II=N0I,N1I
         I=II-N0I+1
         IT=ITRA(II,NKI)
C
C ********* Collisional ionization
C
c        for high temperature, use XSTAR formulae
C
         if(t.gt.1.e5) then
            rno=16.
            izc=2
            call irc(i,t,izc,rno,cs)
            col(it)=cs
          ELSE
C      usual expressions
c
            IC=ICOL(IT)
            U0=FR0(IT)*HKT
            IF(IC.EQ.0) THEN
               IF(I.LE.3) THEN
                  GAM=G0(I)-G1(I)*T+(G2(I)/T-G3(I))/T
                ELSE IF(I.EQ.4) THEN
                  GAM=-95.23828+(62.656249-8.1454078*X)*X
                ELSE IF(I.EQ.5) THEN
                  GAM=472.99219-74.144287*X-1869.6562/X2
                ELSE IF(I.EQ.6) THEN
                  GAM=825.17186-134.23096*X-2739.4375/X2
                ELSE IF(I.EQ.7) THEN
                  GAM=1181.3516-200.71191*X-2810.7812/X2
                ELSE IF(I.EQ.8) THEN
                  GAM=1440.1016-259.75781*X-1283.5625/X2
                ELSE IF(I.EQ.9) THEN
                  GAM=2492.1250-624.84375*X+30.101562*X2
                ELSE IF(I.EQ.10) THEN
                  GAM=4663.3129-1390.1250*X+97.671874*X2
                ELSE
                  GAM=I*I*I
               END IF
               COL(IT)=CT*EXP(-U0)*GAM
             ELSE IF(IC.GE.1) THEN
               GAM=I*I*I
               IF(I.LE.10) GAM=A(1,I)+A(2,I)*X+A(3,I)*X2+
     *            A(4,I)*X3+A(5,I)*X4+A(6,I)*X5
               COL(IT)=CT*EXP(-U0)*GAM
             ELSE
               CALL CSPEC(II,NKI,IC,OSC0(IT),CPAR(IT),U0,T,COL(IT))
            END IF
         END IF

         I1=I+1
         XI=I
         VI=XI*XI
         NHL=N1I-N0I+1
         IF(N1Q.GT.0) NHL=N1Q
         IF(I1.GT.NHL) CYCLE LOWER
C
C ********** collisional excitation
C
C     both explicit transitions as well as contributions to the
C     modified collisional ionization rate
C
         UPPER: DO J=I1,NHL
            JJ=J+N0I-1
            IC=0
            IF(JJ.LE.N1I) THEN
               ICT=ITRA(II,JJ)
               IF(ICT.EQ.0) CYCLE UPPER
               IC=ICOL(ICT)
            END IF
            XJ=J
            VJ=XJ*XJ
            U0=ENION(N0I)*(1./VI-1./VJ)*TK
            IF(J.LE.20) C1=OSH(I,J)
            IF(J.GT.20) C1=OSH(I,20)*(20./XJ)**3
            IF(IC.GE.0) THEN
               GAM=XI-(XI-1.)/(XJ-XI)
               IF(GAM.GT.XJ-XI) GAM=XJ-XI
               IF(I.GT.1) GAM=GAM*1.1
               IF(U0.LE.UN) THEN
                  EIU0=-LOG(U0)+EIA1+U0*(EIA2+U0*(EIA3+U0*(EIA4+
     *               U0*(EIA5+U0*EIA6))))
                ELSE
                  EIU0=EXP(-U0)*((EIB1+U0*(EIB2+U0*(EIB3+
     *              U0*(EIB4+U0))))/(EIC1+U0*(EIC2+
     *              U0*(EIC3+U0*(EIC4+U0)))))/U0
               END IF
               CS=CT2/U0*C1*(0.693*EXP(-U0)+EIU0)*GAM
             ELSE
               CALL CSPEC(II,JJ,IC,C1,CPAR(ICT),U0,T,COL(ICT))
               CYCLE UPPER
            END IF
            IF(JJ.LE.N1I) THEN
               COL(ICT)=CS
             ELSE
               IF(IT.NE.0) COL(IT)=COL(IT)+CS
            END IF
         END DO UPPER
      END DO LOWER
      RETURN
      END SUBROUTINE COLHE2


!*********************************************************************



      SUBROUTINE IRC(N,T,IC,RNO,SE)
c     =============================
c
C IRC CALCULATES THE EXCITATION RATE, SE [cm**3/s], FOR IONIZATION
C OF HYDROGEN ATOMS FROM STATE N DUE TO ELECTRON COLLISIONS, ASSUMING
C THE CONTINUUM STARTS AT LEVEL RNO.
C REF. JOHNSON (1972)
C
c     a modification of Tim Kallman's XSTAR routine
c
      use accura

      REAL(DP), INTENT(IN)  :: T,RNO
      REAL(DP), INTENT(OUT) :: SE
      INTEGER, INTENT(IN)   :: N,IC

      REAL(DP) :: XO,XN,XN2,YN,AN,BN,RN,G0,G1,G2,ZN,EY,EZ

      IF(IC.NE.1) THEN   
         CALL SZIRC(N,T,IC,rno,SE)
         RETURN
      END IF
c
      XN=FLOAT(N)
      XN2=XN*XN
      XO=1.-XN2/RNO/RNO
      YN=XO*157803./(T*XN2)
      IF(N.LE.1) THEN
         AN=1.9603*N*(1.133/3./XO**3-0.4059/4./XO**4+0.07014/5./XO**5)
         BN=2./3.*XN/XO*(3.+2./XO-0.603/XO/XO)
         RN=0.45
       ELSE IF(N.EQ.2) THEN
         AN=1.9603*XN*(1.0785/3./XO**3-0.2319/4./XO**4+0.02947/5./XO**5)
         BN=(4.-18.63/XN+36.24/(XN2)-28.09/(XN2*XN))/XN
         BN=2./3.*XN2/XO*(3.+2./XO+BN/XO/XO)
         RN=0.653
       ELSE
         G0=(0.9935+0.2328/XN-0.1296/XN2)/3./XO**3
         G1=-(0.6282-0.5598/XN+0.5299/XN2)/(XN*4.)/XO**4
         G2=(0.3887-1.181/XN+1.470/XN2)/(XN2*5.)/XO**5
         AN=1.9603*XN*(G0+G1+G2)
         BN=(4.-18.63/XN+36.24/XN2-28.09/(XN2*XN))/XN
         BN=(3.+2./XO+BN/XO/XO)*2.*XN2/3./XO
         RN=1.94*XN**(-1.57)
      END IF
C
      RN=RN*XO
      ZN=RN+YN
      CALL EXPINX(YN,EY)
      CALL EXPINX(ZN,EZ)
      SE=AN*(EY/YN/YN-EXP(-RN)*EZ/ZN/ZN)
      EY=1.+1./YN-EY*(2./YN+1.)
      EZ=EXP(-RN)*(1.+1./ZN-EZ*(2./ZN+1.))
      SE=SE+(BN-AN*LOG(2.*N*N/XO))*(EY-EZ)
      SE=SE*SQRT(T)*YN*YN*XN2*1.095E-10/XO
      RETURN

      CONTAINS


         subroutine szirc(nn,T,ic,rno,cii)
c        =================================
c
c     calculates electron impact ionizition rates from semiempirical
c     formula (eq.35) from Sampson & Zhang (1988, ApJ 335, 516)
c
c     a modification of Tim Kallman's XSTAR routine
c
         use accura
         implicit none

         real(dp), intent(in) :: t,rno
         real(dp), intent(out):: cii
         integer, intent(in)  :: nn,ic
         real(dp) :: rz,boltz,eion,const,rc,an,hn,rrn,tt,rn,yy,
     *               e1,e2,e3,ss,expo
         integer  :: i
     
         real(dp) :: abethe(11), hbethe(11), rbethe(11)
         DATA(abethe(i),i=1,11)/ 1.134, 0.603, 0.412, 0.313, 0.252,
     *       0.211, 0.181, 0.159, 0.142, 0.128, 1.307 /
         DATA(hbethe(i),i=1,11)/ 1.48, 3.64, 5.93, 8.32, 10.75, 12.90,
     *       15.05, 17.20, 19.35, 21.50, 2.15 /
         DATA(rbethe(i),i=1,11)/ 2.20, 1.90, 1.73, 1.65, 1.60, 1.56,
     *       1.54, 1.52, 1.52, 1.52, 1.52 /

         rz=float(ic)
         Boltz=1.38066e-16
         Eion=2.179874e-11
         const=4.6513e-3
C
         rc=float(int(rno))
         if (nn.lt.11) then
           an=abethe(nn)
           hn=hbethe(nn)
           rrn=rbethe(nn)
         else
           an=abethe(11)/float(nn)
           hn=hbethe(11)*float(nn)
           rrn=rbethe(11)
         endif
         tt= T*Boltz
         rn=float(nn)
         yy=rz*rz*Eion/tt*(1./rn/rn-1./rc/rc-.25*(1./(rc-1.)**2-
     *      1./rc/rc))
c
c         call eint(yy,e1,e2,e3)
c         replace by inlining the routine eint
c
         e1=0.
         e2=0.
         e3=0.
         call expinx(yy,ss)
         e1=ss/t/expo(yy)
         e2=exp(-yy)-yy*e1
         e3=0.5*(expo(-yy)-yy*e2)

         cii=const*sqrt(tt)*(rn**5)/(rz**4)*an*yy* (
     *      e1/rn-(exp(-yy)-yy*e3)/(3.*rn)+(yy*e2-2.*yy*e1+exp(-yy))*
     *      3.*hn/rn/(3.-rrn)+(e1-e2)*3.36*yy)
         return
         end subroutine szirc

      END SUBROUTINE IRC


!*********************************************************************



      subroutine expinx(x,em1)
c     ========================
c
c expinx is a subroutine to calculate the value of e1, the exponential
c integral or em1=x*expo(x)*e1 at the point x.  the polynomial
c expressions that are used come from abromowitz and stegen
c
c     a modification of Tim Kallman's XSTAR routine
c
      use accura
      implicit none

      real(dp), intent(in) :: x
      real(dp), intent(out):: em1

      real(dp) :: b1,b2,b3,b4,c1,c2,c3,c4,a0,a1,a2,a3,a4,a5,e1
      real(dp) :: expo

      if(x.gt.1.) then
         b1=9.5733223454
         b2=25.6329561486
         b3=21.0996530827
         b4=3.9584969228
         c1=8.5733287401
         c2=18.0590169730
         c3=8.6347608925
         c4=0.2677737343
         em1=x**4+c1*x**3+c2*x*x+c3*x+c4
         em1=em1/(x**4+b1*x*x*x+b2*x*x+b3*x+b4)
       else
         a0=-0.57721566
         a1=0.99999193
         a2=-0.24991055
         a3=0.05519968
         a4=-0.00976004
         a5=0.00107857
         if(x.gt.0) then
            e1= a0+a1*x+a2*x*x+a3*x**3+a4*x**4+a5*x**5-log(x)
          else
            e1=-a0+a1*x+a2*x*x+a3*x**3+a4*x**4+a5*x**5-log(-x)
         end if
         em1=e1*x*expo(x)
      end if
      return
      end subroutine expinx

!*********************************************************************


!     real(dp) function expo(x)
c     =========================
c
!     use accura
!     implicit none

!     real(dp), intent(in) :: x
!     real(dp), parameter  :: crit=80.
!     real(dp) :: xm
!  
!     xm=x
!     if(x.lt.-crit) xm=-crit
!     if(x.gt.crit) xm=crit
!     expo=exp(xm)
!     return
!     end function expo


!*********************************************************************



      real(dp) function cion(n,j,e,t)
c     ===============================
c
c     collisional ionization rate from Raymond
c     rate is returned in units cm^3/s
c     inputs are: n=nuclear charge,
c                 j=ion stage
c                 e=valence shell ionization threshold (in eV)
c                 t=temperature in K.
c
c Tim Kallman's routine for calculating collisional ionization rates.
c    Note that this routine only accounts for valence shell ionization.
c    It should be called only once for each ion stage and the valence
c    shell ionization threshold should be the lowest one (e.g. the 2p
c    ionization potential for CI).
c
c
      use accura
      implicit none

      REAL(DP), INTENT(IN) :: E,T
      INTEGER, INTENT(IN)  :: N,J

      real(dp) :: chir,chi,ch2,ch3,alpha,beta,a,b,c,d,ch,fchi,expo
      integer  :: j2,j3,iso
c
c  sm younger jqsrt 26, 329; 27, 541; 29, 61   with moores for undone
c  a0 for b-like ion has twice 2s plus one 2p  as in summers et al
c  chi = kt / i
c
      real(dp) ::  a0(30),a1(30),a2(30),a3(30),b0(30),b1(30),
     &          b2(30),b3(30),c0(30),c1(30),c2(30),c3(30),
     &          d0(30),d1(30),d2(30),d3(30)
c
      data a0/13.5,27.0,9.07,11.80,20.2,28.6,37.0,45.4,
     &     53.8,62.2,11.7,38.8,37.27,46.7,57.4,67.0,
     &     77.8,90.1,106.,120.8,135.6,150.4,165.2,180.0,
     &     194.8,209.6,224.4,239.2,154.0,268.8/
      data a1/ - 14.2,-60.1,4.30,27*0./
      data a2/40.6,140.,7.69,27*0./
      data a3/ - 17.1,-89.8,-7.53,27*0./
c
      data b0/ - 4.81,-9.62,-2.47,-3.28,-5.96,-8.64,-11.32,
     &     -14.00,-16.68,-19.36,-4.29,-16.7,-14.58,-16.95,
     &     -19.93,-23.05,-26.00,-29.45,-34.25,-38.92,
     &     -43.59,-48.26,-52.93,-57.60,-62.27,-66.94,
     &     -71.62,-76.29,-80.96,-85.63/
      data b1/9.77,33.1,-3.78,27*0./
      data b2/ - 28.3,-82.5,-3.59,27*0./
      data b3/11.4,54.6,3.34,27*0./
c
      data c0/1.85,3.69,1.34,1.64,2.31,2.984,3.656,4.328,
     &     5.00,5.672,1.061,1.87,3.26,5.07,6.67,8.10,
     &     9.92,11.79,7.953,8.408,8.863,9.318,9.773,
     &     10.228,10.683,11.138,11.593,12.048,12.505,12.96/
      data c1/0.,4.32,.343,27*0./
      data c2/0.,-2.527,-2.46,27*0./
      data c3/0.,.262,1.38,27*0./
c
      data d0/ - 10.9,-21.7,-5.37,-7.58,-12.66,-17.74,
     &     -22.82,-27.9,-32.98,-38.06,-7.34,-28.8,-24.87,
     &     -30.5,-37.9,-45.3,-53.8,-64.6,-54.54,-61.70,
     &     -68.86,-76.02,-83.18,-90.34,-97.50,-104.66,
     &     -111.82,-118.98,-126.14,-133.32/
      data d1/8.90,42.5,-12.4,27*0./
      data d2/ - 35.7,-131.,-8.09,27*0./
      data d3/16.5,87.4,1.23,27*0./
c
      cion = 0.
      chir = t/(11590.*e)
      if ( chir.le..0115 ) return
      chi=chir
      if(chi.lt.0.1) ch=0.1
      ch2 = chi*chi
      ch3 = ch2*chi
      alpha = (.001193+.9764*chi+.6604*ch2+.02590*ch3)
     &        /(1.0+1.488*chi+.2972*ch2+.004925*ch3)
      beta = (-.0005725+.01345*chi+.8691*ch2+.03404*ch3)
     &       /(1.0+2.197*chi+.2457*ch2+.002503*ch3)
      j2 = j*j
      j3 = j2*j
      iso = n - j + 1
c
      a = a0(iso) + a1(iso)/j + a2(iso)/j2 + a3(iso)/j3
      b = b0(iso) + b1(iso)/j + b2(iso)/j2 + b3(iso)/j3
      c = c0(iso) + c1(iso)/j + c2(iso)/j2 + c3(iso)/j3
      d = d0(iso) + d1(iso)/j + d2(iso)/j2 + d3(iso)/j3
c
c  fe ii experimental ionization montague et al: d. neufeld fit
      if ( n.eq.26 .and. j.eq.2 ) then
         a = -13.825
         b = -11.0395
         c = 21.07262
         d = 0.
      endif
c
      ch = 1./chi
      fchi = 0.3*ch*(a+b*(1.+ch)+(c-(a+b*(2.+ch))*ch)*alpha+d*beta*ch)
      cion = 2.2e-6*sqrt(chir)*fchi*expo(-1./chir)/(e*sqrt(e))
      return
      end

!*********************************************************************


      SUBROUTINE BUTLER (NI,NJ,T,U0,CS,IERR)
C     =======================================
C
C Rate coefficients for collisional excitation of hydrogen
C by electrons. Interpolates in Table 3 of Przybilla & Butler
C (2004, ApJ).
C
C
C Input:
C NI Principal quantum number lower level
C NJ "" upper level
C T Temperature
C U0 =h*nu/K/T
C Output:
C COL collisional rate (cm3 s-1)
C IERR error flat (0=ok, 1=T exceeds table range,
C 2=NI higher than 6 or lower than 1
C NJ higher than 7 or lower than 2)
C
      use accura

      implicit none

      integer, intent(in)  :: ni,nj
      real(dp), intent(in) :: t,u0
      real(dp), intent(out):: cs
      integer, intent(out) :: ierr
      real(dp) :: SL,OR
      integer  :: NL,I,J,K,ILOW,IHIG

      REAL(DP) :: COLSTR(16,21),TREF(16)

      DATA (TREF(I), I=1,16) /
     * 2.5e3, 5e3, 7.5e3, 1e4, 1.5e4, 2e4, 2.5e4, 3e4, 4e4, 5e4, 6e4,
     * 8e4, 1e5, 1.5e5, 2e5, 2.5e5 /

      DATA ((COLSTR(I,J),J=1,21),I=1,16) /
C J=1,21 corresponds to (NI,NJ)={(1,2),(1,3),...,(1,NL),(2,3),...}
C where NL=7 (higher n covered in Table)
C I=1,16 corresponds to T={2.5e3,5e3,7.5e3,1e4,1.5e4,2e4,2.5e4,3e4,
C 4e4,5e4,6e4,8e4,1e5,1.5e5,2e5,2.5e5}
     * 6.40e-1, 2.20e-1, 9.93e-2, 4.92e-2, 2.97e-2, 5.03e-2, 2.35e+1,
     * 1.07e+1, 5.22e+0, 2.91e+0, 5.25e+0, 1.50e+2, 7.89e+1, 4.13e+1,
     * 7.60e+1, 5.90e+2, 2.94e+2, 4.79e+2, 1.93e+3, 1.95e+3, 6.81e+3,

     * 6.98e-1, 2.40e-1, 1.02e-1, 5.84e-2, 4.66e-2, 6.72e-2, 2.78e+1,
     * 1.15e+1, 5.90e+0, 4.53e+0, 7.26e+0, 1.90e+2, 9.01e+1, 6.11e+1,
     * 1.07e+2, 8.17e+2, 4.21e+2, 7.06e+2, 2.91e+3, 3.24e+3, 1.17e+4,

     * 7.57e-1, 2.50e-1, 1.10e-1, 7.17e-2, 6.28e-2, 7.86e-2, 3.09e+1,
     * 1.23e+1, 6.96e+0, 6.06e+0, 8.47e+0, 2.28e+2, 1.07e+2, 8.21e+1,
     * 1.25e+2, 1.07e+3, 5.78e+2, 8.56e+2, 4.00e+3, 4.20e+3, 1.50e+4,

     * 8.09e-1, 2.61e-1, 1.22e-1, 8.58e-2, 7.68e-2, 8.74e-2, 3.38e+1,
     * 1.34e+1, 8.15e+0, 7.32e+0, 9.27e+0, 2.70e+2, 1.26e+2, 1.01e+2,
     * 1.37e+2, 1.35e+3, 7.36e+2, 9.66e+2, 5.04e+3, 4.95e+3, 1.73e+4,

     * 8.97e-1, 2.88e-1, 1.51e-1, 1.12e-1, 9.82e-2, 1.00e-1, 4.01e+1,
     * 1.62e+1, 1.04e+1, 9.17e+0, 1.03e+1, 3.64e+2, 1.66e+2, 1.31e+2,
     * 1.52e+2, 1.93e+3, 1.02e+3, 1.11e+3, 6.81e+3, 6.02e+3, 2.03e+4,

     * 9.78e-1, 3.22e-1, 1.80e-1, 1.33e-1, 1.14e-1, 1.10e-1, 4.71e+1,
     * 1.90e+1, 1.23e+1, 1.05e+1, 1.08e+1, 4.66e+2, 2.03e+2, 1.54e+2,
     * 1.61e+2, 2.47e+3, 1.26e+3, 1.21e+3, 8.20e+3, 6.76e+3, 2.21e+4,

     * 1.06e+0, 3.59e-1, 2.06e-1, 1.50e-1, 1.25e-1, 1.16e-1, 5.45e+1,
     * 2.18e+1, 1.39e+1, 1.14e+1, 1.12e+1, 5.70e+2, 2.37e+2, 1.72e+2,
     * 1.68e+2, 2.96e+3, 1.46e+3, 1.29e+3, 9.29e+3, 7.29e+3, 2.33e+4,

     * 1.15e+0, 3.96e-1, 2.28e-1, 1.64e-1, 1.33e-1, 1.21e-1, 6.20e+1,
     * 2.44e+1, 1.52e+1, 1.21e+1, 1.14e+1, 6.72e+2, 2.68e+2, 1.86e+2,
     * 1.72e+2, 3.40e+3, 1.64e+3, 1.34e+3, 1.02e+4, 7.70e+3, 2.41e+4,

     * 1.32e+0, 4.64e-1, 2.66e-1, 1.85e-1, 1.45e-1, 1.27e-1, 7.71e+1,
     * 2.89e+1, 1.74e+1, 1.31e+1, 1.17e+1, 8.66e+2, 3.19e+2, 2.08e+2,
     * 1.78e+2, 4.14e+3, 1.92e+3, 1.41e+3, 1.15e+4, 8.26e+3, 2.52e+4,

     * 1.51e+0, 5.26e-1, 2.95e-1, 2.01e-1, 1.53e-1, 1.31e-1, 9.14e+1,
     * 3.27e+1, 1.90e+1, 1.38e+1, 1.18e+1, 1.04e+3, 3.62e+2, 2.24e+2,
     * 1.81e+2, 4.75e+3, 2.15e+3, 1.46e+3, 1.26e+4, 8.63e+3, 2.60e+4,

     * 1.68e+0, 5.79e-1, 3.18e-1, 2.12e-1, 1.58e-1, 1.34e-1, 1.05e+2,
     * 3.60e+1, 2.03e+1, 1.44e+1, 1.19e+1, 1.19e+3, 3.98e+2, 2.36e+2,
     * 1.83e+2, 5.25e+3, 2.33e+3, 1.50e+3, 1.34e+4, 8.88e+3, 2.69e+4,

     * 2.02e+0, 6.70e-1, 3.55e-1, 2.29e-1, 1.65e-1, 1.35e-1, 1.29e+2,
     * 4.14e+1, 2.23e+1, 1.51e+1, 1.19e+1, 1.46e+3, 4.53e+2, 2.53e+2,
     * 1.85e+2, 6.08e+3, 2.61e+3, 1.55e+3, 1.49e+4, 9.21e+3, 2.90e+4,

     * 2.33e+0, 7.43e-1, 3.83e-1, 2.39e-1, 1.70e-1, 1.37e-1, 1.51e+2,
     * 4.56e+1, 2.37e+1, 1.56e+1, 1.20e+1, 1.67e+3, 4.95e+2, 2.65e+2,
     * 1.86e+2, 6.76e+3, 2.81e+3, 1.57e+3, 1.63e+4, 9.43e+3, 3.17e+4,

     * 2.97e+0, 8.80e-1, 4.30e-1, 2.59e-1, 1.77e-1, 1.39e-1, 1.93e+2,
     * 5.31e+1, 2.61e+1, 1.63e+1, 1.19e+1, 2.08e+3, 5.68e+2, 2.83e+2,
     * 1.87e+2, 8.08e+3, 3.15e+3, 1.61e+3, 1.97e+4, 9.78e+3, 3.94e+4,

     * 3.50e+0, 9.79e-1, 4.63e-1, 2.71e-1, 1.82e-1, 1.39e-1, 2.26e+2,
     * 5.83e+1, 2.78e+1, 1.68e+1, 1.19e+1, 2.39e+3, 6.16e+2, 2.94e+2,
     * 1.86e+2, 9.13e+3, 3.36e+3, 1.62e+3, 2.27e+4, 1.00e+4, 4.73e+4,

     * 3.95e+0, 1.06e+0, 4.88e-1, 2.81e-1, 1.85e-1, 1.40e-1, 2.52e+2,
     * 6.23e+1, 2.89e+1, 1.71e+1, 1.19e+1, 2.62e+3, 6.51e+2, 3.02e+2,
     * 1.87e+2, 1.00e+4, 3.51e+3, 1.63e+3, 2.54e+4, 1.02e+4, 5.50e+4 /

      NL=7
      IERR=0
      CS=0.

      IF (T.LT.2.5e3.OR.T.GE.2.5e5) IERR=1
      IF (NI.LT.1.OR.NI.GT.NL-1.OR.NJ.LT.2.OR.NJ.GT.NL) IERR=2

      IF (IERR.EQ.0) THEN
      J=0
      DO I=1,NI-1
         J=J+(NL-I)
      END DO
      DO K=I+1,NJ
         J=J+1
      END DO

C find out nearest points in TREF

      ILOW=1
      DO WHILE (T.GE.TREF(ILOW+1))
         ILOW=ILOW+1
      END DO

      IHIG=16
      DO WHILE (T.LT.TREF(IHIG-1))
         IHIG=IHIG-1
      END DO

      IF (IHIG.EQ.ILOW) IHIG=IHIG+1

C interpolate linearly (log-log) the collision strength

      SL=LOG10(COLSTR(IHIG,J))-LOG10(COLSTR(ILOW,J))
      SL=SL/(LOG10(TREF(IHIG))-LOG10(TREF(ILOW)))
      OR=LOG10(COLSTR(IHIG,J))-SL*LOG10(TREF(IHIG))
      CS=LOG10(T)*SL+OR
      CS=10.**CS

C derive the rate

      CS=8.631e-6/(2.*NI**2)/SQRT(T)*EXP(-U0)*CS
      END IF

      RETURN
      END


!*********************************************************************


      SUBROUTINE LTEGR
C     ================
C
C     Driving procedure for computing the initial LTE-grey model
C     atmosphere
C
      use accura
      use atomic
      use basics
      use modelq
C
      implicit none 

      REAL(DP) :: DPLOG1,DPLOG2,TAUR,PLOG,ERROR,PNEW,PLOG4,DPLOG3,AN,
     *            ANE,TAU1,TAUL,TAU2,ABROS,DML0,DLGM,DPLOG,DPRAD,
     *            HOPF0,P,PLOG1,PLOG2,PLOG3,PRAD0,PTOT,T
      INTEGER  :: NDEPTH,IDEPTH,ND0,I,J,ID
      LOGICAL  :: LTE0


      REAL(DP) :: DEPTH(MDEPTH),DEPTH0(MDEPTH),TAU(MDEPTH),TAU0(MDEPTH),
     *            TEMP0(MDEPTH),ELEC0(MDEPTH),DENS0(MDEPTH),DM0(MDEPTH)
C
C ----------------
C Input parameters
C ----------------
C
C     NDEPTH  - number of depth points for evaluating LTE-grey model
C             = 0 - NDEPTH is taken to be ND-1
C     TAUFIR  - Rosseland optical depth in the first depth point
C     TAULAS  - Rosseland optical depth in the last depth point
C     ABROS0  - an estimate of the Rosseland opacity (per gram) at the
C               first depth point
C     TSURF   = 0  - surface temperature and the Hopf function are
C                    evaluated exactly
C             > 0  - value of surface temperature is set to TSURF, and
C                    the Hopf function is assumed to be constant,
C                    corresponding to TSURF
C     ALBAVE  = 0  - wind blanketing is not considered
C             > 0  - wind blanketing is considered; the averaged value
C                    of albedo [precisely the quantity (1+rho)/(1-rho)
C                    in the notation of Hummer (Ap.J. 257, 724, 1982)
C                    see his Eq. (3.1)] is ALBAVE
C     DION0        - initial estimate of the degree of ionization at
C                    the first depth point (=1 for completely ionized;
C                    =1/2 for completely neutral)
C
C --------------------------------------------------------------------
C     IDEPTH  -  mode of determining the mass-depth scale to be used
C                in linearization
C             =  0 - depth scale DM (in g*cm**-2) is evaluated as mass
C                    corresponding to Rosseland optical depths which
C                    are equidistantly spaced in logarithms between
C                    the first point TAUFIR and the last point TAULAS
C                    the last-but-one point is, however, set to
C                    TAULAS-1.
C             =  2 - depth scale DM is evaluated as that corresponding
C                    to input values of Rosseland optical depth -
C                    array TAU0(ID), ID=1,ND
C             =  1 - similar, but now DM is evaluated as mass
C                    corresponding to Rosseland optical depths which
C                    are equidistantly spaced in logarithms between
C                    the first point TAU1 and the last-but-one point
C                    TAU2; the last point is TAUL
C                    (i.e. similar to option 0, now TAU1 and TAUL may
C                    be different from TAUFIR nad TAULAS)
C             =  3 - depth scale DM has already been read in START
C     NCONIT       - number of internal iterations for calculating the
C                    gray model with convection
C             =  0 - and HMIX0>0, then NCONIT is set to 10
C     IPRING       - controls diagnostic output of the LTE-gray model
C                    calculations
C              = 0 - no output
C              = 1 - only final LTE-gray model
C              = 2 - results of all internal iterations
C
      ipring=2
      IF(NDGREY.EQ.0) THEN
         NDEPTH=ND
       ELSE
         NDEPTH=NDGREY
      END IF
      IF(NDEPTH.GT.MDEPTH)
     *   CALL QUIT('ndepth.gt.mdepth in LTEGR',ndepth,mdepth)
      IDEPTH=IDGREY
      IF(ALBAVE.GT.0.AND.TSURF.EQ.0.) TSURF=(0.433*ALBAVE)**0.25
      HOPF0=0.
      IF(TSURF.NE.0.) HOPF0=4.0*TSURF**4/3.0
      ANEREL=(DION0-HALF )/DION0
      IF(NCONIT.EQ.0.AND.HMIX0.GT.0.) NCONIT=10
      IF(ANEREL.LT.1.e-3) ANEREL=1.e-3
      LTE0=LTE
      LTE=.TRUE.
      IF(NDEPTH.EQ.0) NDEPTH=ND-1
      ND0=ND
      ND=NDEPTH
      DO I=1,ND0
         DM0(I)=DM(I)
      END DO
C
C     tau(ross) scale - logarithmically equidistant points between
C     input TAUFIR and TAULAS
C
      DML0=LOG(TAUFIR)
      DLGM=(LOG(TAULAS)-DML0)/(NDEPTH-1)
      DO I=1,NDEPTH
         TAU0(I)=DML0+(I-1)*DLGM
         TAU(I)=EXP(TAU0(I))
         TAUROS(I)=TAU(I)
      END DO
C
      DPRAD=1.891204931e-15_dp*TEFF**4
      if(ifprad.eq.0) dprad=0.
C
      PRAD0=DPRAD/1.732_dp
c     PRAD0=0
      ABROS=ABROS0
      PLOG1=0.
      PLOG2=0.
      PLOG3=0.
      DPLOG1=0.
      DPLOG2=0.
      IF(IPRING.GT.0) WRITE(6,"(/' COMPUTED LTE-GREY MODEL'//
     * '    ID    TAU',7X,
     * 'MASS',5X,'TEMP',7X,'N',10X,'NE',9X,'P',8X,'ROSS.OP',
     * '    Ptot    TAUR*DPRAD   PRAD0     Pg(comp)'/)")
C
C -------------------------------------------------------------------
C
C     1.part
C     Integration of the hydrostatic equilibrium equation on the
C     tau(ross) scale;
C     basically by a predictor-corrector method
C     (similar to Kurucz's ATLAS code)
C
      DEPT: DO ID=1,NDEPTH
         J=0
         TAUR=TAU(ID)
         PREDCOR: DO       
            IF(J.EQ.0) THEN
C
C              predictor step
C  
               SELECT CASE(ID)
               CASE(1)
                  PLOG=LOG(GRAV/ABROS*TAUR+prad0)
               CASE(2:4)
                  PLOG=PLOG1+DPLOG1
               CASE(5:)
                  PLOG=(3._dp*PLOG4+8._dp*DPLOG1-
     *                  4._dp*DPLOG2+8._dp*DPLOG3)/3._dp
               END SELECT
               ERROR=1.
             ELSE
C
C            corrector step
C              
               SELECT CASE(ID)
               CASE(1)
                  PNEW=LOG(GRAV/ABROS*TAUR+prad0)
               CASE(2:4)
                  PNEW=(PLOG+2._dp*PLOG1+DPLOG+DPLOG1)/3._dp
               CASE(5:)
                  PNEW=(126._dp*PLOG1- 14._dp*PLOG3 + 9._dp*PLOG4+
     *                   42._dp*DPLOG+108._dp*DPLOG1-54._dp*DPLOG2+
     *                   24._dp*DPLOG3)/121._dp
               END SELECT
               ERROR=ABS(PNEW-PLOG)
               PLOG=PNEW
            END IF
!       write(*,"('g1 '2i4,1p7e10.2)") id,j,plog,pnew,taur,dprad,prad0
c            if(id.ge.nd-1) then
cc            write(*,*) 'ltegr',id,pnew,error,taur
c             write(*,"(a,2i3,9f11.6)") 
c    *        'corre',id,j,plog,plog1,plog1,plog3,plog4,
c    *        dplog,dplog1,dplog2,dplog3
c            end if
            PTOT=EXP(PLOG)
            P=PTOT-TAUR*DPRAD-prad0
            if(p.le.0.) p=grav*taur/abros*0.3
            J=J+1
!       if(id.eq.1)
!    *  write(6,"('g2 '2i4,1p4e14.6)") id,j,taur,dprad,p,ptot
            CALL ROSSOP(ID,P,TAUR,HOPF0,T,ANE,ABROS)
!       if(id.eq.1)
!    *  write(6,"('g3 ',2i4,1p6e14.6)") id,j,taur,p,hopf0,t,ane,abros
            DPLOG=GRAV/ABROS*TAUR/PTOT*DLGM
            IF(ERROR.LT.1.e-4.OR.J.GE.10) EXIT PREDCOR
         END DO PREDCOR
C
C ------ end of the iteration loop;
C        set up necessary quantities for the next depth step of the
C        hydrostatic equilibrium
C
         PLOG4=PLOG3
         PLOG3=PLOG2
         PLOG2=PLOG1
         PLOG1=PLOG
         DPLOG3=DPLOG2
         DPLOG2=DPLOG1
         DPLOG1=DPLOG
         TEMP0(ID)=T
         ELEC0(ID)=ANE
         AN=P/T/BOLK
         DEPTH(ID)=(PTOT-prad0)/GRAV
         DM(ID)=DEPTH(ID)
         DENS0(ID)=WMM(ID)*(AN-ANE)
         IF(IPRING.GT.0) WRITE(6,"(I4,1P2E11.3,0PF9.0,1P9E11.3)")
     *                   ID,TAU(ID),DEPTH(ID),T*1.e-0,AN,ANE,P,ABROS,
     *     ptot,taur*dprad,prad0,ptot-taur*dprad-prad0
         PTOTAL(ID)=PTOT
         PGS(ID)=P
         TOTN(ID) = DENS(ID)/WMM(ID)+ELEC(ID)
      END DO DEPT
C
C -------------------------------------------------------------------
C
C     2. Second part - taking into account convection
C
      IF(HMIX0.GT.0.) THEN
         CALL CONTMP
c      write(*,*) 'AFTER CONTMP'
         CALL CONOUT(2,IPRING)
         LTE=LTE0


c     write(*,*) 'interpolated gray model'
c     write(*,*)
c     do id=1,nd
c        IF(IPRING.GT.0) WRITE(6,"(I4,1P2E11.3,0PF8.0,1P9E11.3)")
c    *                   ID,TAU(ID),DM(ID),TEMP(ID),TOTN(ID),
c    *   elec(id),PGS(ID),ptotal(id)
c     end do
         RETURN
      END IF


c     write(*,*) 'LTEGR idepth',idepth
C
C -------------------------------------------------------------------
C
C     3. Third part
C     Interpolation of the computed model to the depth scale which is
C     going to be used in the subsequent - complete-linearization -
C     part of the model atmosphere construction
C
      ND=ND0
C
C     First option - logarithmically equidistant Rosseland opt.depths
C                    the same first and last depth as in the first part
C
      IF(IDEPTH.EQ.0) THEN
         TAU1=TAUFIR
         TAUL=TAULAS
         TAU2=TAULAS-1.
C
C     Second option - logarithmically equidistant Rosseland opt.depths
C                     the first, last-but-one, and last depths are read
C
        ELSE IF(IDEPTH.EQ.1) THEN
          READ(IBUFF,*) TAU1,TAU2,TAUL
      END IF
C
CC    IF(IDEPTH.LE.1) THEN
      IF(IDEPTH.EQ.1) THEN
         DML0=LOG(TAU1)
         IF(TAUL.GT.0.) THEN
            DLGM=(LOG(TAU2)-DML0)/(ND-2)
            DO ID=1,ND-1
               TAU0(ID)=DML0+(ID-1)*DLGM
            END DO
            TAU0(ND)=LOG(TAUL)
          ELSE
            DLGM=(LOG(TAU2)-DML0)/(ND-1)
            DO ID=1,ND
               TAU0(ID)=DML0+(ID-1)*DLGM
            END DO
         END IF
       ELSE IF(IDEPTH.EQ.2) THEN
C
C     Third option - prescribed set of Rosseland optical depths
C
         READ(IBUFF,*) (TAU0(ID),I=1,ND)
         DO ID=1,ND
            TAU0(ID)=LOG(TAU0(ID))
         END DO
       ELSE if(idepth.eq.3) then
C
C     Fourth option - interpolation to the prescribed mass scale DM
C
         DO ID=1,ND
            DM(ID)=DM0(ID)
            DM0(ID)=LOG(DM(ID))
         END DO
         CALL INTERP(DEPTH0,TEMP0,DM0,TEMP,NDEPTH,ND,2,0,0)
         CALL INTERP(DEPTH0,ELEC0,DM0,ELEC,NDEPTH,ND,2,0,1)
         CALL INTERP(DEPTH0,DENS0,DM0,DENS,NDEPTH,ND,2,0,1)
      END IF
C
C     in the first three options - interpolation from the previous
C     Rosseland opacity scale to the new scale and from the previous
C     mass depth scale to the new one
C
CC    IF(IDEPTH.LE.2) THEN
      IF(IDEPTH.EQ.1.OR.IDEPTH.EQ.2) THEN
         DO ID=1,NDEPTH
            TEMP0(ID)=TEMP(ID)
            ELEC0(ID)=ELEC(ID)
            DENS0(ID)=DENS(ID)
            TAU(ID)=LOG(TAUROS(ID))
            DEPTH0(ID)=LOG(DM(ID))
         END DO
         CALL INTERP(TAU,DEPTH0,TAU0,DM0,NDEPTH,ND,3,0,0)
         CALL INTERP(TAU,TEMP0,TAU0,TEMP,NDEPTH,ND,3,0,0)
         CALL INTERP(TAU,ELEC0,TAU0,ELEC,NDEPTH,ND,3,0,1)
         CALL INTERP(TAU,DENS0,TAU0,DENS,NDEPTH,ND,3,0,1)
         DO ID=1,ND
            DM(ID)     = EXP(DM0(ID))
            TOTN(ID)   = DENS(ID)/WMM(ID)+ELEC(ID)
            PTOTAL(ID) = DM(ID)*GRAV+PRAD0
            PGS(ID)    = TOTN(ID)*BOLK*TEMP(ID)
         END DO
      END IF


      write(*,*)
      write(*,*) 'INTERPOLATED GRAY MODEL'
      write(*,*)
      do id=1,nd
         IF(IPRING.GT.0) WRITE(6,"(I4,1P2E11.3,0PF8.0,1P9E11.3)")
     *                   ID,TAU(ID),DM(ID),TEMP(ID)*1.e-3,TOTN(ID),
     *   elec(id),PGS(ID),ptotal(id)
      end do



C
C     Recalculation of the populations
C
      DO ID=1,ND
         CALL WNSTOR(ID)
         CALL STEQEQ(ID,POP,1)
      END DO
C
      LTE=LTE0

      RETURN
      END SUBROUTINE LTEGR

      
!*************************************************************************


      SUBROUTINE ROSSOP(ID,P,TAUR,HOPF,T,ANE,ABROSS)
C     ==============================================
C
C     Auxiliary procedure for LTEGR
C     Evaluation of temperature, electron density, and Rosseland
C     opacity for a given TAUR (Rosseland optical depth) and P (total
C     pressure)
C
C     Input parameters:
C     ID     - depth index
C     P      - total pressure
C     TAUR   - Rosseland optical depth
C     HOPF   - mode of evaluating Hopf function;
C            = 0  -  exact Hopf function
C            > 0  -  constant Hopf function to HOPF
C
C     Output:
C     T      - temperature
C     ANE    - electron density
C     ABROSS - Rosseland opacity (per gram)
C
      use accura
      use atomic
      use basics
      use modelq

      REAL(DP), INTENT(IN) :: P,TAUR,HOPF
      REAL(DP), INTENT(OUT):: T,ANE,ABROSS
      INTEGER,  INTENT(IN) :: ID

      REAL(DP) :: X,EX,E1,E,AN,ENRG,ENTT,WM,RHO,OPROS,OPPLA,RHOEOS
      REAL(DP) :: EXPINT
      INTEGER  :: I
      REAL(DP) :: A(5)
C
      DATA A/0.7104460_dp,-0.2830385_dp,0.57975839_dp,-0.75751038_dp,
     *       0.45026781_dp/
C
C     Hopf function
C
      X=HOPF
      IF(X.EQ.0) THEN
         X=A(1)
         IF(TAUR.LT.160.) THEN
            EX=EXP(-TAUR)
            E1=EXPINT(TAUR)
            E=E1
            DO I=1,4
               E=(EX-TAUR*E)/I
               X=X+E*A(I+1)
            END DO
         END IF
      END IF
C
C     Temperature
C
      T=TEFF*(0.75_dp*(TAUR+X)+EXTOT)**0.25_dp
C
C     Determination of electron density from the total pressure
C
      if(ioptab.ge.-1) then
         AN=P/T/BOLK
         CALL ELDENS(ID,T,AN,ANE,ENRG,ENTT,WM,1)
CC       ANE=AN/2.
         RHO=WMM(ID)*(AN-ANE)
         DENS(ID)=RHO
C
C     temperature and electron density are transmitted to SABOLF
C     and RATMAT through arrays TEMP and ELEC
C
         TEMP(ID)=T
         ELEC(ID)=ANE
C
C     Corresponding LTE populations
C
         if(ioptab.ge.0) then
            CALL WNSTOR(ID)
            CALL STEQEQ(ID,POP,1)
         
C
C     Finally, evaluation of the Rosseland opacity for the new values
C     of temperature, electron density, and populations
C     (ROSS - Rosseland opacity per 1 cm**3)
C
            CALL OPACF0(ID)

            CALL MEANOP(T,OPROS,OPPLA)
            ABROSS=OPROS/RHO
            ABROSD(ID)=ABROSS
            ABPLAD(ID)=OPPLA/RHO

           else
            call meanopt(t,id,rho,opros,oppla)
            abrosd(id)=opros
            abplad(id)=oppla
            abross=opros
         end if
       else
         temp(id)=t
         rho=rhoeos(t,p)
         dens(id)=rho
         call meanopt(t,id,rho,opros,oppla)
         abrosd(id)=opros
         abplad(id)=oppla
         abross=opros
      end if
      RETURN
      END SUBROUTINE ROSSOP

      
!*************************************************************************


      SUBROUTINE MEANOP(T,OPROS,OPPLA)
C     ================================
C
C     Rosseland and Planck mean opacities
C
C     Input parameters:
C      T    - temperature
C      ABSO - array of absorption coefficients in all explicit
C             frequency points
C      SCAT - array of scttering coefficients
C     Output:
C      OPROS - Rosseland opacity (per 1 cm**3)
C      OPPLA - Planck mean opacity (per 1 cm**3)
C
      use accura
      use atomic
      use basics
      use modelq

      REAL(DP), INTENT(IN) :: T
      REAL(DP), INTENT(OUT):: OPROS,OPPLA

      REAL(DP) :: ABR,ABP,SUMDB,SUMB,HKT,FR,X,EX,E1,PLAN,DPLAN
      INTEGER  :: IJ,ipr

      data ipr /1/

      ABR=0.
      SUMDB=0.
      ABP=0.
      SUMB=0.
      HKT=HK/T
C
CC    DO IJ=1,NFREQC
      DO IJ=1,NFREQ
         FR=FREQ(IJ)
         X=HKT*FR
         IF(X.GT.150.) X=150.
         EX=EXP(X)
         E1=UN/(EX-UN)
         PLAN=BNUE(IJ)*E1*W(IJ)
         DPLAN=PLAN*HKT*FR*EX*E1
         ABR=ABR+DPLAN/ABSO(IJ)
         ABP=ABP+PLAN*(ABSO(IJ)-SCAT(IJ))
         SUMDB=SUMDB+DPLAN
         SUMB=SUMB+PLAN
         if(ipr.eq.1) write(39,"(i4,1pe13.5,4e12.4)") 
     &   ij,freq(ij),abso(ij),scat(ij),abso(ij)-scat(ij),abr
      END DO
      ipr=0
      OPROS=SUMDB/ABR
      OPPLA=ABP/SUMB
      RETURN
      END SUBROUTINE MEANOP

      
!*************************************************************************


      SUBROUTINE MEANOPT(T,ID,RHO,OPROS,OPPLA)
C     ========================================
C
C     Rosseland and Planck mean opacities
C
C     Input parameters:
C      T    - temperature
C      RHO  - density
C     Output:
C      OPROS - Rosseland opacity (per gram)
C      OPPLA - Planck mean opacity (per gram)
C
      use accura
      use basics
      use modelq

      REAL(DP), INTENT(IN) :: T,RHO
      REAL(DP), INTENT(OUT):: OPROS,OPPLA
      INTEGER , INTENT(IN) :: ID

      REAL(DP) :: ABR,ABP,SUMDB,SUMB,HKT,FR,EX,E1,PLAN,DPLAN,AB,SC,SCT
      INTEGER  :: IJ
C
      ABR=0.
      SUMDB=0.
      ABP=0.
      SUMB=0.
      HKT=HK/T
C
      DO IJ=1,NFREQ
         FR=FREQ(IJ)
         EX=EXP(HKT*FR)
         E1=UN/(EX-UN)
         PLAN=BNUE(IJ)*E1*W(IJ)
         DPLAN=PLAN*HKT*FR*EX*E1
         CALL OPCTAB(FR,IJ,ID,T,RHO,AB,SC,SCT,1)
         ABR=ABR+DPLAN/(AB+SCT)
         ABP=ABP+PLAN*AB
         SUMDB=SUMDB+DPLAN
         SUMB=SUMB+PLAN
      END DO
      OPROS=SUMDB/ABR
      OPPLA=ABP/SUMB
      RETURN
      END SUBROUTINE MEANOPT

      
!*************************************************************************


      SUBROUTINE ELDENS(ID,T,AN,ANE,ENRG,ENTT,WM,IPRI)
C     ===============================================
C
C     Evaluation of the electron density and the total hydrogen
C     number density for a given total particle number density
C     and temperature;
C     by solving the set of Saha equations, charge conservation and
C     particle conservation equations (by a Newton-Raphson method)
C
C     Input parameters:
C     T    - temperature
C     AN   - total particle number density
C
C     Output:
C     ANE   - electron density
C     ANP   - proton number density
C     AHTOT - total hydrogen number density
C     AHMOL - relativer number of hydrogen molecules with respect to the
C             total number of hydrogens
C     ENERG - part of the internal energy: excitation and ionization
C
      use accura
      use atomic
      use basics
      use modelq
      use molec, only: rhoter,anta

      implicit none

      REAL(DP), INTENT(IN) :: T,AN
      REAL(DP), INTENT(OUT):: ANE,ENRG,ENTT,WM
      INTEGER , INTENT(IN) :: ID,IPRI
      logical              :: lp

      REAL(DP) ::  R(3,3),S(3),P(3)

      REAL(DP) :: AEIN,QMI,Q2,QP,TK,THET,QH,QH0,UH,DUH,UH2,DUH2,TKLN15,
     *            AH,ANH,G2,G3,G4,G5,GG,A,B,D,E,C1,C2,C3,F1,FE,AE,
     *            DELNE,ANHMIN,ENERG,ENTROP
      INTEGER  :: IT,I,mp
c
      if(ioptab.lt.-1) return
C
!!    if(anerel.le.0..or.id.eq.1) then
         anerel=0.5
         if(t.lt.9000.) anerel=0.4
         if(t.lt.8000.) anerel=0.1
         if(t.lt.7000.) anerel=0.01
         if(t.lt.6000.) anerel=0.001
         if(t.lt.5500.) anerel=0.0001
         if(t.lt.5000.) anerel=1.e-5
         if(t.lt.4000.) anerel=1.e-6
!!    end if
      if(elec(id).gt.0.) anerel=elec(id)/an
c
!      write(*,"('ELDENS beg',i4,f10.1,1p3e12.4)") id,t,an,aein,tmolim
      if(ifmol.gt.0.and.t.lt.tmolim) then
         aein=an*anerel
!      write(*,"('ELDENS bef moleq',i4,f10.1,1p2e12.4)") id,t,an,aein
         call moleq(id,t,an,aein,ane,enrg,entt,wm,ipri)
         anerel=ane/an
         return
      end if
c
      QMI=0.
      Q2=0.
      QP=0.
      Q=0.
      DQN=0.
      TK=BOLK*T
      THET=5.0404e3_dp/T
CC    pfhyd=2.
      anta=an
C
C     Coefficients entering ionization (dissociation) balance of:
C     atomic hydrogen          - QH;
C     negative hydrogen ion    - QM   (considered only if IHM>0);
C     hydrogen molecule        - QP   (considered only if IH2>0);
C     ion of hydrogen molecule - Q2   (considered only if IH2P>0).
C
c     IF(T.LE.TMOLIM) THEN
      IF(T.LE.9000.) THEN
         QMI=1.0353e-16_dp/T/SQRT(T)*EXP(8762.9_dp/T)
         QP=TK*EXP((-11.206998_dp+THET*(2.7942767_dp+THET*
     *      (0.079196803_dp-0.024790744_dp*THET)))*2.30258509299405_dp)
         call mpartf(1,1,0,t,uh,duh)
         uh=max(uh,two)
         call mpartf(0,0,2,t,uh2,duh2)
         q2=1.47e-20_dp/(t*sqrt(t))*uh2/uh/uh*exp(51951.8_dp/t)
      END IF
      tkln15=log(bolk*t)*1.5_dp
      QH0=EXP((15.38287+1.5*LOG10(T)-13.595*THET)*
     *    2.30258509299405)*two
C
      ANE=AN*ANEREL

      mp=169
      if(id.eq.mp) write(6,"('el0',1p5e16.8)") t,an,ane,qh0,qp
     
      IT=0
C
C     Basic Newton-Raphson loop - solution of the non-linear set
C     for the unknown vector P, consistiong of AH, ANH (neutral
C     hydrogen number density) and ANE.
C
      ITLOOP: DO
         IT=IT+1
C
C        procedure STATE determines Q (and DQN) - the total charge (and its
C        derivative wrt temperature) due to ionization of all atoms which
C        are considered (both explicit and non-explicit), by solving the set
C        of Saha equations for the current values of T and ANE
C
         CALL STATE(1,ID,T,ANE)
C
C        Auxiliary parameters for evaluating the elements of matrix of
C        linearized equations.
C        Note that complexity of the matrix depends on whether the hydrogen
C        molecule is taken into account
C        Treatment of hydrogen ionization-dissociation is based on
C        Mihalas, in Methods in Comput. Phys. 7, p.10 (1967)
C
         QH=QH0/PFHYD
         A=UN+QH/ANE+QMI*ANE
         IF(IATREF.EQ.IATH) THEN
            qh=qh0/pfhyd
            G2=QH/ANE
            G3=0.
            G4=0.
            G5=0.
            D=0.
            E=0.
            G3=QMI*ANE
            A=UN+G2+G3
            D=G2-G3
            IF(IT.LE.1) THEN
               IF(T.GT.9000.) THEN
                  F1=UN/A
                  FE=D/A+Q
                  AH=ANE/FE
                  ANH=AH/A
                else if(t.gt.4000.) then
                  E=G2*QP/Q2
                  B=TWO*(UN+E)
                  GG=ANE*Q2
                  C1=B*(GG*B+A*D)-E*A*A
                  C2=A*(TWO*E+B*Q)-D*B
                  C3=-E-B*Q
                  F1=(SQRT(C2*C2-4.*C1*C3)-C2)*HALF/C1
                  FE=F1*D+E*(UN-A*F1)/B+Q
                  AH=ANE/FE
                  ANH=AH*F1
                else
                  c1=q2*(two*ytot(id)-un)
                  c2=ytot(id)
                  c3=-an
                  anh=(sqrt(c2*c2-4.*c1*c3)-c2)*half/c1
                  ah=anh*(un+two*anh*q2)
                  c1=un+qmi*anh
                  c2=-q*ah
                  c3=-qh*anh
                  ane=(sqrt(c2*c2-4.*c1*c3)-c2)*half/c1
               end if
            END IF
   
            AE=ANH/ANE
            GG=AE*QP
            E=ANH*Q2
            B=ANH*QMI
C
C           Matrix of the linearized system R, and the rhs vector S
C
            if(ifmol.eq.0.or.t.ge.tmolim) then
               R(1,1)=YTOT(ID)
               R(1,2)=0.
               R(1,3)=UN
               S(1)=AN-ANE-YTOT(ID)*AH
             else
               R(1,1)=YTOT(ID)-UN
               R(1,2)=A+E+GG
               R(1,3)=UN
               S(1)=AN-ANE-ANH*(A+E+GG)-(YTOT(ID)-UN)*AH
            end if
c
            R(2,1)=-Q
            R(2,2)=-D-TWO*GG
            R(2,3)=UN+B+AE*(G2+GG)-DQN*AH
            R(3,1)=-UN
            R(3,2)=A+4.*(E+GG)
            R(3,3)=B-AE*(G2+TWO*GG)
            S(2)=ANH*(D+GG)+Q*AH-ANE
            S(3)=AH-ANH*(A+TWO*(E+GG))

            if(id.eq.mp) then
             write(*,"(a,i4,1p8e16.8)") 'it',it,an,ane,ah,anh,a,d,ae,e

             write(6,"(1p4e16.8)") (r(1,i),i=1,3),s(1)
             write(6,"(1p4e16.8)") (r(2,i),i=1,3),s(2)
             write(6,"(1p4e16.8)") (r(3,i),i=1,3),s(3)
            end if
C
C           Solution of the linearized equations for the correction vector P
C
            CALL LINEQS(R,S,P,3,3)
C
C           New values of AH, ANH, and ANE
C
            AH=AH+P(1)
            ANH=ANH+P(2)
            DELNE=P(3)
            ANE=ANE+DELNE
            if(id.eq.mp)
     *       write(6,"(1p6e16.8)") (p(i),i=1,3),ah,anh,ane/delne
C
C        hydrogen is not the reference atom
C
         ELSE
C
C           Matrix of the linearized system R, and the rhs vector S
C
            IF(IT.EQ.1) THEN
               ANE=AN*HALF
               AH=ANE/YTOT(ID)
            END IF
            R(1,1)=YTOT(ID)
            R(1,2)=UN
            R(2,1)=-Q-QREF
            R(2,2)=UN-(DQN+DQNR)*AH
            S(1)=AN-ANE-YTOT(ID)*AH
            S(2)=(Q+QREF)*AH-ANE
C
C           Solution of the linearized equations for the correction vector P
C
            CALL LINEQS(R,S,P,2,3)
            AH=AH+P(1)
            DELNE=P(2)
            ANE=ANE+DELNE
         END IF
C
C        Convergence criterion
C
         IF(ANE.LE.0.) ANE=1.e-6_dp*AN
         IF(ABS(DELNE/ANE).LT.1.e-6.OR.IT.GT.50) EXIT ITLOOP
      END DO ITLOOP

!     write(*,"('elden',i4,f10.1,1p4e12.4)") id,t,ane,an,ah
      
C
C     ANEREL is the exact ratio betwen electron density and total
C     particle density, which is going to be used in the subseguent
C     call of ELDENS
C      
      IF(IATREF.NE.IATH) THEN
         AHTOT=AH*ABUND(IATH,ID)
         AH=AHTOT
         ANH=AHTOT/A
       ELSE
         AHTOT=AH
      END IF
      ANEREL=ANE/AN
      AHMOL=ANH*ANH*Q2
      ANP=ANH/ANE*QH
      ANHMIN=ANH*ANE*QMI
      RHOTER=WMY(ID)*AHTOT*HMASS
      if(ipri.gt.0) then
         dens(id)=rhoter
         elec(id)=ane
         wmm(id)=dens(id)/(an-ane)
      end if
C
c     internal energy and entropy
c

      if(id.eq.mp) write(*,"('elden',i4,f10.1,1p4e16.8)") id,t,ane,an,ah
      energ=0.
      entrop=0.
      call entene(id,t,an,ah,anh,anp,ane,energ,entrop)
      ener=energ
      entr=entrop
      if(id.eq.mp) write(6,"('end eld',i4,1p4e16.8)") id,t,an,ener,entr
c
c     energy and entropy of H_2
c
      if(t.lt.9000..and.ahmol.gt.0..and.uh2.gt.0.) then
         ener=ener+(duh2-51951.8_dp/t)*tk*ahmol
         entr=entr+ahmol*(tkln15-log(ahmol)+log(uh2)+1.0487_dp+
     *        103.973_dp)*bolk
      end if
C
      enrg=ener
      entt=entr
      wm=rhoter/an/hmass
c
      if(ifmol.le.0.or.t.ge.tmolim) then
         if(n0hn.gt.0) then
            anato(1,id)=popul(n0hn,id)
         end if
         if(iathe.gt.0) then
            anato(2,id)=popul(n0a(iathe),id)
         end if
      end if
c
      RETURN
      END SUBROUTINE ELDENS
      

!*************************************************************************

      subroutine moleq(id,tt,an,aein,ane,energ,entt,wm,ipri)
c     ======================================================
c
c     calculation of the equilibrium state of atoms and molecules
c
c     Input:  id    - depth point
c             tt    - temperature [K]
c             an    - total particle number density
c             aein  - initial estimate of the electron density
c
c     Output: 1) parameters transported through formal parameters"
C                ane    - electron density
c                entt   - entropy
c                energ  - internal energy
c             2) parameters transported through COMMON blocks
c                ELEC(ID)    - electron denity
c                DENS(ID)    - mass density
c                WMM(ID)     - mean molecular weight
c                QADD(ID)    - total charge of non-explicit species
c                ABUND(I,ID) - abundances of explicit atoms,
c                              counting only atoms and ions
c                              (not atoms sequestered in molecules)
c
c     Input data for molecules given in file tsuji.molec
c
      use accura
      use atomic
      use basics
      use modelq
      use molec

      implicit none

      REAL(DP), INTENT(IN) :: TT,AN,AEIN
      REAL(DP), INTENT(OUT):: ANE,ENERG,ENTT,WM
      INTEGER,  INTENT(IN) :: ID,IPRI
c
      CHARACTER(LEN=128)  :: MOLFILE
      REAL(DP),PARAMETER :: ECONST=4.342945E-1_DP,EV2ERG=1.6018e-12_DP,
     *                      EPS=0.001

CC    REAL(DP),SAVE :: C(600,5),CCOMP(100),
CC   *                 XIP(100),XIP2(100),EMASS(100)
      REAL(DP),SAVE :: EMASS(100)
CC    INTEGER,SAVE  :: NELEM(5,600),NATO(5,600),MMAX(600),
CC   *                 NELEMX(100),NMETAL,NMOLEC,NIMAX
      INTEGER       :: NATOMM(5),NELEMM(5)

CC    REAL(DP) :: PPMOL(600),APMLOG(600),UIIDUI(100),
CC   *            P(100),FP(100),XKP(100),XK2(100)
CC    REAL(DP) :: anion2(30,mdepth)
CC    REAL(DP) :: entato(100),ention(100),entmol(600)
CC    REAL(DP) :: uelem(100),ull(100),anden(800),
CC   *            aelem(100),ammol(600),   !cmol(600),
CC   *            anat0(100),anio0(100),anmo0(600),pfmol(600),
CC   *            denso(mdepth),eleco(mdepth),wmmo(mdepth)
CC    CHARACTER(LEN=8),SAVE :: CMOL(600)
c
      REAL(DP) :: TK,SAHCON,THET,TEM,PGLOG,PG,TKLN15,TKLN25,TKEV,PE,
     *            ENTCON,ANX,TKK,ANTT,TMASS,U0,U1,DULOG,AN1,FPLOG,
     *            PLOG,XKPLOG,PIONL,X2LOG,PION2,PMOLL,UMOLL,
     *            AMASM,UM,ANN,ENTEL,PELOG,PESAVE,PGAS
      INTEGER  :: IREAD,I,IA,J,K,IOS,M,MMAXJ,IDSTP,
     *            NELEMI,JBEG,JM,JJJ,mp

      data iread/1/
c
      if(ifmol.eq.0) return
      MOLFILE ='data/tsuji.molec_bc2'
      if(moltab.eq.0) MOLFILE='data/tsuji.molec_orig'
c
      tk=1./(tt*bolk)
      pgas=an/tk
      sahcon=1.87840e20_dp*tt*sqrt(tt)
      nimax=1000
C
      if(iread.eq.1) then
c
C---- data for atoms  ----------------
C
         do i=1,nmetal
            ia=i
            nelemx(i)=ia
            ccomp(ia)=abndd(ia,id)
            xip(ia)=enev(ia,1)
            xip2(ia)=enev(ia,2)
            emass(ia)=amas(ia)
         end do
c
c---- read molecular data from tsuji.molec ----------------------
c
         J=0
         OPEN(UNIT=26,FILE=MOLFILE,STATUS='OLD')
         READMOL: DO
            J=J+1
            READ(26,"(A8,5E13.5,9I3)",IOSTAT=IOS) 
     *        CMOL(J),(C(J,K),K=1,5),
     *        MMAX(J),(NELEMM(M),NATOMM(M),M=1,4)
            IF(IOS.NE.0) EXIT READMOL
c      write(6,"(i4,2x,a8,1p5e12.4)") j,cmol(j),(C(J,K),K=1,5)
c           J=J+1
c
c           for now, exclude all molecules with 4 or more C atoms
c
            do m=1,4
               if(nelemm(m).eq.6.and.natomm(m).ge.5) then
                  j=j-1
                  cycle readmol
               end if
            end do
!      write(6,"(i4,2x,a8,1p5e12.4)") j,cmol(j),(C(J,K),K=1,5)

            MMAXJ=MMAX(J)
            IF(MMAXJ.GT.0) THEN
               DO M=1,MMAXJ
                  NELEM(M,J)=NELEMM(M)
                  NATO(M,J)=NATOMM(M)
               END DO
               cycle readmol
            END IF
         END DO READMOL

         NMOLEC=J-1
         NMOLEC=461
         CLOSE(26)

!        write(*,*) 'NMOLEC',nmolec

c
         DO I=1,NMETAL
            NELEMI=NELEMX(I)
            P(NELEMI)=1.e-70_dp
         END DO
         iread=0
      end if
c
c---- end of reading atomic and molecular data  ----------------------
c
      p(99)= aein/tk
      pesave=p(99)
      p(99)=pesave
c
      THET=5040._dp/tt
      TEM=tt
      PGLOG=log10(Pgas)
      PG=Pgas
      tkln25=-log(tk)*2.5_dp
      tkln15=log(bolk*tt)*1.5_dp
      tkev=5040./tt
c
      CALL RUSSEL(TEM,PG)
c
      PE=P(99)
      ane=pe*tk
      PELOG=log10(PE)
      emass(99)=5.486e-4_dp
      uelem(99)=TWO
c     aelem(99)=pe*tk/(2.*sahcon*emass(nelemi)**1.5)
      aelem(99)=pe*tk/(2.*sahcon*emass(99)**1.5)
      ull(99)=log10(aelem(99))
      idstp=nd*2/3
      entcon=103.973_dp
      ann=an-ane
      tkk=bolk*tt*tt


c     if(id.eq.32) write(*,"('aft.Russel',i4,1p5e10.2)") 
c    * nelemi,pe,ane,emass(99),aelem(99),ull(99)
c
c----atoms-----------------------------------------------------------------
c
      mp=2
      entt=0
      antt=0.
      energ=0.
      tmass=0.
      DO I=1,NMETAL
         NELEMI=NELEMX(I)
         FPLOG=log10(FP(NELEMI))
        anden(i)=(p(nelemi)+1.e-70_dp)*tk 
         tmass=tmass+anden(i)*emass(nelemi)
         call mpartf(nelemi,1,0,tt,u0,dulog)
         uelem(nelemi)=u0
         aelem(nelemi)=anden(i)/(u0*sahcon*emass(nelemi)**1.5)
         ull(nelemi)=log10(aelem(nelemi))
         anat0(nelemi)=anden(i)
         if(dulog.lt.0.) dulog=0.
         entato(nelemi)=tkln15-log(anden(i))+log(u0)+
     *         1.5*log(emass(nelemi))+entcon+tkk*dulog
         anx=anden(i)/ann
         antt=antt+anx
         entt=entt+entato(nelemi)*anden(i)
         energ=energ+dulog/tk*anden(i)
!      if(id.eq.mp) write(*,"('ato',2i5,1p2e12.4)") 
!    * id,nelemi,entato(nelemi),entt
      END DO
      an1=anden(1)
c
c---- positive ions ---------------------------------------------------------
c
      DO I=1,NMETAL
         NELEMI=NELEMX(I)
         PLOG= log10(P(NELEMI)+1.0e-70_dp)
         XKPLOG=log10(XKP(NELEMI)+1.0e-70_dp)
         PIONL=PLOG+XKPLOG-PELOG
         anden(i+nmetal)=exp(pionl/econst)*tk
         tmass=tmass+anden(i+nmetal)*emass(nelemi)
         call mpartf(nelemi,2,0,tt,u1,dulog)
         if(dulog.lt.0.) dulog=0.
         anio0(nelemi)=anden(i+nmetal)
         ention(nelemi)=tkln15-log(anden(i+nmetal))+log(u1)+
     *      1.5*log(emass(nelemi))+entcon+tkk*dulog
         anx=anio0(nelemi)/ann
         antt=antt+anx
         entt=entt+ention(nelemi)*anio0(nelemi)
!      if(id.eq.mp) write(*,"('ion',2i5,1p2e12.4)") 
!    * id,nelemi,ention(nelemi),entt
         energ=energ+(xip(nelemi)*1.6018e-12+
     *         dulog/tk)*anio0(nelemi)
         if(nelemi.ge.2.and.nelemi.le.30) then
            x2log=log10(XK2(NELEMI)+1.0e-70_dp)
            pion2=pionl+x2log-pelog
            anion2(nelemi,id)=exp(pion2/econst)*tk
         end if
      END DO
c
c     H- (incorrect in the original Tsuji's table)
c
      jbeg=1
      if(moltab.eq.0) then
         j=1
         anmo0(1)=1.0353e-16_dp/tt/sqrt(tt)*exp(8762.9_dp/tt)*
     *            anat0(1)*ane
         ammol(1)=emass(1)
         pfmol(1)=1.
         entmol(1)=tkln15-log(anmo0(1))+1.5*log(emass(1))+entcon
         anx=anmo0(1)/ann
         antt=antt+anx
         entt=entt+entmol(j)*anmo0(1)
         tmass=tmass+emass(1)*anmo0(1)
         jbeg=2
      end if
c
c---- molecules-------------------------------------------------------------
c
C     if(id.le.1) write(*,*) 'jbeg,nmolec',jbeg,nmolec
      DO J=jbeg,NMOLEC
         jm=j+2*nmetal
         PMOLL=log10(PPMOL(J)+1.0e-70_dp)
         anden(jm)=exp(pmoll/econst)*tk
CC       if(pmoll.lt.-20.) cycle
CC       if(pmoll.lt.-20.) cycle
         umoll=log10(anden(jm))+c(j,2)*thet
c      if(id.eq.32.and.j.eq.427) write(*,*) 'um1',umoll
         amasm=0.
         do jjj=1,mmax(j)
            i=nelem(jjj,j)
            amasm=amasm+NATO(jjj,j)*emass(i)
            umoll=umoll-NATO(jjj,j)*ull(i)
c      if(id.eq.32.and.j.eq.427) write(*,"('um2a',3i5,1p2e12.4)") 
c    *  jjj,i,nato(jjj,j),ull(i),umoll
         end do
c      if(id.eq.32.and.j.eq.427) write(*,*) 'um2',umoll
         ammol(j)=amasm
         tmass=tmass+anden(jm)*amasm
         umoll=exp(umoll/econst)/(sahcon*amasm**1.5)
c      if(id.eq.32.and.j.eq.427) write(*,*) 'um3',umoll
c
c        replace with Irwin data whenever available
c
         call mpartf(0,0,j,tt,um,dulog)

c        if(j.le.30.and.id.le.71) write(6,"(3i4,2x,a8,1p4e12.4)")
c    *   id,j,jm,cmol(j),pmoll,anden(jm),umoll,um


CC       anmo0(j)=anden(jm)
CC       pfmol(j)=umoll
         if(pmoll.lt.-20.) cycle


         if(um.gt.0.) umoll=um
c      if(id.eq.32.and.j.eq.427) write(*,*) 'um4',um,umoll
         if(umoll.lt.1.) umoll=1.
c
         anmo0(j)=anden(jm)
         pfmol(j)=umoll
         if(dulog.lt.0.) dulog=0.
         entmol(j)=tkln15-log(anden(jm))+log(umoll)+
     *             1.5*log(amasm)+entcon+tkk*dulog
CC       if(pmoll.lt.-20.) cycle
         anx=anden(jm)/ann
         antt=antt+anx
         entt=entt+entmol(j)*anden(jm)
!      if(id.eq.mp) write(*,"('mol',3i5,1p7e12.4)") 
!    * id,j,jm,anden(jm),umoll,amasm,c(2,j),dulog,entmol(j),entt
         energ=energ+dulog/tk*anden(jm)
         if(j.eq.2) energ=energ-4.476*ev2erg*anden(jm)
      END DO
c
c     electrons
c
      entel=tkln15-log(ane)+1.5*log(emass(99))+entcon
      entt=entt+entel*ane
c      if(id.eq.32) write(*,"('ele',2i5,1p2e12.4)")
c    *  id,nmetal+1,entel,entt
      antt=antt+ane/ann
c
c     final entropy, density, and mean mnolecular weight
c
      entt=entt*bolk
      rhoter=tmass*hmass
      ahtot=anat0(1)+anio0(1)+anmo0(1)+2.*anmo0(2)
      wm=tmass/antt/ann
c      write(*,"('fin.entr,rho',2i4,1p2e12.4)") id,nmetal,entt,rhoter
c
      if(ipri.eq.0) return
c
      do i=1,nmetal
         j=nelemx(i)
         anato(j,id)=anat0(j)
         anion(j,id)=anio0(j)
      end do
c
      do j=1,nmolec
CC       anmol(j,id)=anmo0(j)
         anmol(j,id)=anden(j+2*nmetal)
C        if(j.le.630.and.id.le.1) write(6,"(i4,2x,a8,1p3e12.4)") 
CC   *   j,cmol(j),anmol(j,id),entmol(j),pfmol(j) 
C    *   j,cmol(j),anmol(j,id)
      end do
c
      anhm(id)=anmol(1,id)
      anh2(id)=anmol(2,id)
C
C     save new density, molecular weight, and abundances of
c     atomic species
c
      denso(id)=dens(id)
      eleco(id)=elec(id)
      wmmo(id)=wmm(id)
      dens(id)=tmass*hmass
      elec(id)=ane
      wmm(id)=dens(id)/(an-elec(id))
      qadd(id)=0.
      do i=1,nmetal
          NELEMI=NELEMX(I)
          ia=iatex(nelemi)
          if(ia.gt.0) then
             abund(ia,id)=(anato(nelemi,id)+anion(nelemi,id))*
     *       wmm(id)/dens(id)*ytot(id)
           else
             qadd(id)=qadd(id)+anion(nelemi,id)
          end if
      end do
      if(ielhm.eq.0) qadd(id)=qadd(id)-anhm(id)
c
      if(ipri.eq.0) return
c
c     don't change structure if particle conservation in not solved
c
      IF(INPC.eq.0) THEN
         dens(id)=denso(id)
         elec(id)=eleco(id)
         wmm(id)=wmmo(id)
      END IF

c     write(*,*) 'end of moleq in id=',id
c
      RETURN 
      END SUBROUTINE MOLEQ

      
!*************************************************************************


         SUBROUTINE RUSSEL(TEM,PG)
c        =========================
c
        use accura
        use basics
        use modelq
        use molec

        implicit none 

        REAL(DP), INTENT(IN) :: TEM,PG

        REAL(DP),PARAMETER :: XKCON=6.667343E-1,EPSDIE=5.0E-5,EPS=0.001

        REAL(DP) :: FX(100),DFX(100),Z(100),PREV(100),WA(100),
     *              UIIDU2(100)
        REAL(DP) :: T,PGLOG,TK,HEH,APLOGJ,DHH,TEM25,G0,G1,G2,DULOG,HKP,
     *              PH,U,QR,R,S,X,F,DF,XR,PHH,PPH,FPH,PE,SPNION,SPNPLU,
     *              PMOLJ,ATOMJ,DELTRS,PEREV,PMOLJL,ECONST
        INTEGER  :: ISWIT,I,J,K,M,NELEMI,ITERAT,NITERR,MMAXJ,NATOMJ,
     *              NELEMJ,IMAXP1
C
        ISWIT=1
        ECONST=4.3426E-1_dp
        T=5040.4/TEM
        PGLOG=log10(PG)
        tk=1./(tem*1.38054e-16_dp)
C
C       HEH=helium/hydrogen ratio by number
C
c       HEH=CCOMP(2)/CCOMP(1)
        HEH=YTOT(1)-UN
C
C       evaluation of log XKP(MOL)
C
        DO J=1,NMOLEC
           APLOGJ=C(J,5)
           DO K=1,4
              APLOGJ=APLOGJ*T + C(J,5-K)
           END DO
           APMLOG(J)=APLOGJ
        END DO
        apmlog(1)=-log10(1.0353e-16_dp/tem/sqrt(tem)*tk*
     *            exp(8762.9_dp/tem))
        DHH=(((0.1196952E-02_DP*T-0.2125713E-01_DP)*T+0.1545253_dp)*T
     *     -0.5161452E+01_DP)*T+0.1277356E+02_DP
        DHH=EXP(DHH/ECONST)
C
C       evaluation of the ionization constants
C
        TEM25=TEM**2*SQRT(TEM)
        DO I=1,NMETAL
           NELEMI = NELEMX(I)
*
*          calculation of the partition functions following Irwin (1981)
C
           call mpartf(nelemi,1,0,tem,g0,dulog)
           call mpartf(nelemi,2,0,tem,g1,dulog)
           call mpartf(nelemi,3,0,tem,g2,dulog)
           uiidui(nelemi)=g1/g0*xkcon
           uiidu2(nelemi)=g2/g1*xkcon
           uiidui(nelemi)=g1/g0*xkcon
           XKP(NELEMI)=UIIDUI(NELEMI)*TEM25*
     *                 EXP(-XIP(NELEMI)*T/ECONST)
           XK2(NELEMI)=UIIDU2(NELEMI)*TEM25*
     *                 EXP(-XIP2(NELEMI)*T/ECONST)
           xk2(nelemi)=max(xk2(nelemi),1.e-70_dp)
        END DO
        XK2(1)=0.
C
C       preliminary value of PH at high temperatures
C
        HKP=XKP(1)
        IF(T.LT.0.6) THEN
           PPH=SQRT(HKP*(PG/(1.0+HEH)+HKP))-HKP
           PH=PPH**2/HKP
         ELSE
           IF(PG/DHH.LE.0.1) THEN
              PH=PG/(UN+HEH)
            ELSE
              PH=HALF * (SQRT(DHH*(DHH+4.0_dp *PG/(UN+HEH)))-DHH)
           END IF
        END IF
C
C       evaluation of the fictitious pressures of hydrogen
C        PG=PH+PHH+TWO*PPH+HEH*(PH+TWO*PHH+PPH)
C
        U=(UN+TWO*HEH)/DHH
        QR=UN+HEH
        R=(TWO+HEH)*SQRT(HKP)
        S=-UN*PG
        X=SQRT(PH)
C
C       Russell iterations
C
        ITERAT=0
        ITRAS: DO
           F=((U*X**2+QR)*X+R)*X+S
           DF=TWO*(TWO*U*X**2+QR)*X+R
           XR=X-F/DF
           IF(ABS((X-XR)/XR).GT.EPSDIE) THEN
              ITERAT=ITERAT+1
              IF(ITERAT.GT.50) THEN
                 WRITE(6,"(' NOT CONVERGE IN RUSSEL '
     *           /// 'TEM=',F9.2,5X,'PG=',E12.5,5X,
     *           'X1=',E12.5,5X,'X2=',E12.5,5X,'PH=',E12.5/////)") 
     *           TEM,PG,X,XR,PH
                 EXIT ITRAS
               ELSE
                 X=XR
                 CYCLE ITRAS
              END IF
            ELSE
              EXIT ITRAS
           END IF
        END DO ITRAS

        PH=XR**2
        PHH=PH**2/DHH
        PPH=SQRT(HKP*PH)
        FPH=PH+TWO*PHH+PPH
        P(100)=PPH
C
C   evaluation of the fictitious pressure of each element
C
        DO I=1,NMETAL
           NELEMI=NELEMX(I)
           FP(NELEMI)=CCOMP(NELEMI)*FPH
        END DO
C
C   check of initialization
C
        PE=P(99)
C
C    Russell equations
C
        NITERR = 0
        RUSS: DO
           DO I=1,NMETAL
              NELEMI=NELEMX(I)
              DFX(NELEMI)=UN+XKP(NELEMI)/PE*(UN+XK2(NELEMI)/PE)
              FX(NELEMI)=-FP(NELEMI)+P(NELEMI)*DFX(NELEMI)
           END DO
C
           SPNION=0.0
           spnplu=0.
           DO J=1,NMOLEC
              MMAXJ=MMAX(J)
              PMOLJL=-APMLOG(J)
              DO M=1,MMAXJ
                 NELEMJ=NELEM(M,J)
                 NATOMJ=NATO(M,J)
CC               PMOLJL=PMOLJL+DFLOAT(NATOMJ)*log10(P(NELEMJ))
                 PMOLJL=PMOLJL+REAL(NATOMJ)*log10(P(NELEMJ))
              END DO
C
              PMOLJ=EXP(PMOLJL/ECONST)
              DO M=1,MMAXJ
                 NELEMJ=NELEM(M,J)
                 NATOMJ=NATO(M,J)
                 ATOMJ=REAL(NATOMJ)
                 IF(NELEMJ.EQ.99) then
                    if(natomj.ge.0) then
                       SPNION=SPNION+PMOLJ*NATOMJ
                     else
                       SPNPLU=SPNPLU-PMOLJ*NATOMJ
                    end if
                 end if
                 DO I=1,NMETAL
                    NELEMI=NELEMX(I)
                    IF(NELEMJ.EQ.NELEMI) THEN
                       FX(NELEMI)=FX(NELEMI)+ATOMJ*PMOLJ
                       DFX(NELEMI)=DFX(NELEMI)+ATOMJ**2*
     *                          PMOLJ/P(NELEMI)
                    END IF
                 END DO
              END DO
              PPMOL(J)=PMOLJ
           END DO
C
C          solution of the Russell equations by Newton-Raphson method
C
           DO I=1,NMETAL
              NELEMI=NELEMX(I)
              WA(I)=log10(P(NELEMI)+1.0e-70_dp)
           END DO
           IMAXP1=NMETAL+1
           WA(IMAXP1)=log10(PE+1.0e-70_dp)
           DELTRS = 0.0
           DO I=1,NMETAL
              NELEMI=NELEMX(I)
              PREV(NELEMI)=P(NELEMI)-FX(NELEMI)/DFX(NELEMI)
              PREV(NELEMI)=ABS(PREV(NELEMI))
              IF(PREV(NELEMI).LT.1.0e-70_dp) PREV(NELEMI)=1.0e-70_dp
              Z(NELEMI)=PREV(NELEMI)/P(NELEMI)
              DELTRS=DELTRS+ABS(Z(NELEMI)-1.0)
              IF(ISWIT.GT.0) THEN
                 P(NELEMI)=(PREV(NELEMI)+P(NELEMI))*HALF
               ELSE
                 P(NELEMI)=PREV(NELEMI)
              END IF
           END DO
C
C          ionization equilibrium
C
           PEREV =0.0
           DO I=1,NMETAL
              NELEMI = NELEMX(I)
              PEREV=PEREV+XKP(NELEMI)*P(NELEMI)*(un+xk2(nelemi)/pe)
           END DO
C
           PEREV=SQRT(PEREV/(UN+SPNION/PE))
           DELTRS=DELTRS+ABS((PE-PEREV)/PE)
           PE=(PEREV+PE)*HALF
           P(99)=PE
           IF(DELTRS.LE.EPS) THEN
              EXIT RUSS
            ELSE
              NITERR=NITERR+1
              IF(NITERR.LE.NIMAX) THEN
                 CYCLE RUSS
               ELSE
                 WRITE(6,"('*DOES NOT CONVERGE AFTER ',I4,' ITER')") 
     *           NIMAX
                 EXIT RUSS
              END IF
           END IF
        END DO RUSS
C
        RETURN
        END SUBROUTINE RUSSEL

C                 
C     ***************************************************************
C                       


      subroutine mpartf(jatom,ion,indmol,t,u,dulog)
c     =============================================
c
c     yields partition functions with polynomial data from
c     ref. Irwin, A.W., 1981, ApJ Suppl. 45, 621.
c     ln u(temp)=sum(a(i)*(ln(temp))**(i-1)) 1<=a<=6
c
c     Input:
c       jatom = element number in periodic table
c       ion   = 1 for neutral, 2 for once ionized and 3 for twice ionized
c       indmol= index of a molecular specie (Tsuji index)
c       temp  = temperature
c     Output:
c       u     = partf.(linear scale) for iat,ion, or indmol, and temperature t
c       dulog = d ln(u)/d ln(T)
c
      use accura
      use basics

      implicit none 
       
      INTEGER,  INTENT(IN) :: jatom,ion,indmol
CC    REAL(DP), INTENT(INOUT) :: T
      REAL(DP)                :: T
      REAL(DP), INTENT(OUT):: U,DULOG
      REAL(DP),SAVE        :: a(6,3,92),aa(6),am(6,600)
      INTEGER, SAVE        :: indtsu(324),irw(600),igle(28)
      INTEGER, SAVE        :: NMOLI

      REAL(DP) :: SP,SPEC,TL,ULOG
      INTEGER  :: IREAD,I,J,K,INDM

      DATA IGLE/2,1,2,1,6,9,4,9,6,1,2,1,6,9,4,9,6,1,
     *          10,21,28,25,6,25,28,21,10,21/
C
      data indtsu / 2,  5, 12, 4, 8, 7, 6,
     *              9, 11, 10, 29, 50, 59, 46, 133,  52, 19,
     *             13, 42, 38, 39, 37, 44, 36,  14, 118, 33,
     *              3, 16, 57, 32, 49, 60, 54,  41, 107,304,
     *            148, 152, 153, 155, 303, 17,  24,  25, 28, 51,
     *            112, 119, 102,   0,  21, 15,  43,  22,478, 64,
     *             47,  65, 414,  61, 191, 62 ,109,  40, 66,214,
     *             120*0,    30, 136*0/
c
      data iread /0/
c
c     read data if first call:
c
      if(iread.ne.1) then
         if(irwtab.eq.0) then
            open(67,file= './data/irwin_orig.dat',status='old')
            nmoli=66
          else
            open(67,file= './data/irwin_bc.dat',status='old')
            nmoli=324
         end if
         read(67,*)
         read(67,*)
         do j=1,92
           icyk: do i=1,3
             if(j.eq.1.and.i.eq.3) cycle icyk
             sp=float(j)+float(i-1)/100.
             read(67,*) spec,aa
             do k=1,6
                 a(k,i,j)=aa(k)
             end do
          end do icyk
        end do
c
        read(67,*)
        read(67,*)
        read(67,*)
        do i=1,600
           irw(i)=0
        end do
        do i=1,nmoli
           read(67,*) spec,aa
           indm=indtsu(i)
           if(indm.gt.0) then
              irw(indm)=i
              do j=1,6
                 am(j,indm)=aa(j)
              end do
          end if
        end do
        close(67)
        iread=1
      endif
c
c     evaluation of the partition function
c     stop if T is out of limits of Irwin's tables
c
      u=1.
      dulog=0.
      if(t.lt.1000.) then
         t=1000.
       else if(t.gt.16000..and.ioverr.eq.0) then
         if(indmol.eq.0) then
            if(jatom.le.28.and.ion.le.jatom) u=igle(jatom-ion+1)
         end if
         return
      endif
      tl=log(t)
      u=0.
c
c     atomic species
c
      if(jatom.gt.0.and.ion.gt.0) then
        ulog=    a(1,ion,jatom)+
     *       tl*(a(2,ion,jatom)+
     *       tl*(a(3,ion,jatom)+
     *       tl*(a(4,ion,jatom)+
     *       tl*(a(5,ion,jatom)+
     *       tl*(a(6,ion,jatom))))))
        if(jatom.eq.5.and.ion.eq.3) ulog=1.
        u=exp(ulog)
        dulog=   a(2,ion,jatom)+
     *       tl*(a(3,ion,jatom)*2.+
     *       tl*(a(4,ion,jatom)*3.+
     *       tl*(a(5,ion,jatom)*4.+
     *       tl*(a(6,ion,jatom)*5.))))
      end if
c
c     molecular species
c
      if(indmol.gt.0) then
         indm=indmol
         if(irw(indm).gt.0) then
            ulog=    am(1,indm)+
     *           tl*(am(2,indm)+
     *           tl*(am(3,indm)+
     *           tl*(am(4,indm)+
     *           tl*(am(5,indm)+
     *           tl*(am(6,indm))))))
            u=exp(ulog)
            dulog=   am(2,indm)+
     *        tl*(am(3,indm)*2.+
     *        tl*(am(4,indm)*3.+
     *        tl*(am(5,indm)*4.+
     *        tl*(am(6,indm)*5.))))
         end if
      end if
      return
      end subroutine mpartf

C     
C     ***************************************************************
C     


      subroutine entene(id,t,an,ah,anh,anpr,ane,energ,entrop)
c     =======================================================
c
c     internal energy and entropy of atoms and ions
c
      use accura
      use atomic
      use basics
      use modelq

      implicit none

      real(dp), parameter :: ev2erg=1.6018e-12_dp,entcon=103.973_dp

      real(dp), intent(in)  :: t,an,ah,anh,anpr,ane
      real(dp), intent(out) :: energ,entrop
      integer, intent(in)   :: id

      real(dp) :: tk,tkk,tkln15,xmax,u,dulog,dut,dun,alm,chip,
     *            anref,aden,xj,xmx,entel
      integer  :: natomi,i,j,mp
c
      mp=-2
      tk=bolk*t
      tkk=tk*t
      tkln15=1.5_dp*log(tk)
      natomi=30
      energ=0.
      entrop=0.
c
c     hydrogen
c
      i=1
      j=1
      xmax=2.154e4_dp*sqrt(t/ane)
      if(t.lt.16000..or.ioverr.eq.1) then
CC    if(t.lt.16000..and.iirwin.eq.1) then
         call mpartf(i,j,0,t,u,dulog)
         if(dulog.lt.0.) dulog=0.
         if(u.le.two) u=two
         if(id.eq.mp) write(*,"('E0',1p3e16.8)") t,u,dulog
       else
         call partf(i,j,t,ane,xmax,u,dut,dun)
         if(u.le.two) u=two
         if(dut.le.0.) then
            dulog=0.
          else
            dulog=dut*t/u
         end if
      end if
      alm=1.5_dp*log(amas(1))
      energ=tk*dulog*anh
      entrop=(tkln15-log(anh)+log(u)+alm+tkk*dulog+entcon)*anh
      energ=energ+enev(1,1)*ev2erg*anpr
      entrop=entrop+(tkln15-log(anpr)+alm+entcon)*anpr
      if(id.eq.mp) write(*,"('EE',1p7e16.8)") 
     *   t,u,dulog,anh,anpr,energ,entrop
c      if(id.eq.1) write(*,"('entr',2i3,f8.1,1p6e12.4)") 
c    * i,j,t,u,dulog,ah,anh,anpr,entrop
!!     if(id.eq.1) write(61,"('entr',2i3,f8.1,1p6e12.4)") 
!!   * i,j,t,u,dulog,ah,anh,anpr,entrop
c
c     other species
c
      anref=(an-ane)/ytot(1)
      do i=2,natomi
         chip=0
         do j=1,2
            if(rr(i,j).gt.1.e-15) then
            aden=rr(i,j)*anref
            if(aden.lt.1.e-20) aden=1.e-20
            if(t.lt.16000..or.ioverr.eq.1) then
               call mpartf(i,j,0,t,u,dulog)
               if(dulog.lt.0.) dulog=0.
               if(u.le.un) u=un
         if(id.eq.mp) write(*,"('O0',1p3e16.8,2i4)") t,u,dulog,i,j
             else
               xj=j
               xmx=xmax*sqrt(xj)
               call partf(i,j,t,ane,xmx,u,dut,dun)
               if(u.lt.un) u=un
               if(dut.le.0.) then
                  dulog=0.
                else
                  dulog=dut*t/u
               end if
            end if
c
            energ=energ+(chip*ev2erg+tk*dulog)*aden
            entrop=entrop+(tkln15-log(aden)+log(u)+
     *             1.5*log(amas(i))+tkk*dulog+entcon)*aden
            end if
            chip=chip+enev(i,j)
c         if(id.eq.1) write(*,"('entr',2i3,f8.1,1p5e12.4)") 
c    *    i,j,t,u,dulog,rr(i,j),aden,entrop
          if(id.eq.1) write(61,"('entr',2i3,f8.1,1p5e12.4)") 
     *    i,j,t,u,dulog,rr(i,j),aden,entrop
      if(id.eq.mp) write(*,"('OO',1p7e16.8,2i4)") 
     *   t,u,dulog,anh,anpr,energ,entrop,i,j
         end do
      end do
c
c     entropy of electrons
c
c     entel=tkln15-log(ane)+1.5*log(emass(99))+entcon
      entel=tkln15-log(ane)-11.2622_dp+entcon
      entrop=entrop+entel*ane
      entrop=entrop*bolk
      if(id.eq.mp) write(*,"('E2',1p2e16.8)") entel,entrop
C
      return
      end subroutine entene
C     
C     ***************************************************************
C     


      REAL(DP) FUNCTION RHOEOS(T,P)
C     ============================
C
C     equation of state - determining density from
C     temperature and pressure
C
C     Input:   T - temperature (K)
C              P - total pressure (cgs)
C
      use accura
      use basics
      use modelq

      implicit none

      real(dp), parameter  :: wmol0=1.67333E-24_dp/2.3_dp
      real(dp), intent(in) :: T,P
      real(dp) :: an,rho,p0,s0,p1,s1,dpdr,drxx
      integer  :: inirea,niteos

      data inirea /0/
C
C      initialize EOS tables
C
       if(inirea.eq.0) then
          call settrm
          inirea=1
       end if
C
      AN=P/BOLK/T
      RHO=AN*wmol0
C
      niteos=0
      ITE: DO
         niteos=niteos+1
         CALL PRSENT(RHO,T,P0,S0)
         CALL PRSENT(RHO*1.01,T,P1,S1)
         DPDR=(P1-P0)/(.01*RHO)
         DRXX=(P-P0)/DPDR/rho
         if(drxx.lt.-0.9) drxx=-0.9
         rho=rho*(un+drxx)
         IF(ABS(DRXX).LE.1.e-5.or.niteos.lt.20) EXIT ITE
      END DO ITE
C
      rhoeos=rho
      return
      end function rhoeos
C     
C     ***************************************************************
C     


      SUBROUTINE STATE(MODE,ID,T,ANE)
C     ===============================
C
C     For MODE=0 - initialization of the basic parameters for the
C                  chemical species
C     for MODE=2 - solves the set of LTE Saha equations to determine
C                  the total charge due to ionization of non-explicit
C                  chemical species
C     for MODE=3 - similar as MODE=2, but also with derivatives wrt
C                  temperature and electron density (called from BPOP,
C                  ie. from the linearization step)
C     for MODE=1 - similar as MODE=2, but the total charge is evaluated
C                  summing the contributions of both non-explicit and
C                  explicit chemical species (called from LTEGR)
C
C     Input for MODE > 0:
C
C        T   - temperature
C        ANE - electron density
C
C     Output for MODE > 0 (through module modelq)
C
C        Q    - total charge, relative to the reference atom
C        QM   - charge of H- (in LTE), evaluated only if H- is not
C               explicit ion, and if desired (if IHM=1)
C        DQT  - derivative of Q wrt temperature
C        DQN  - derivative of Q wrt electron density
C        DQM  - derivative of QM wrt temperature
C        ENER - internal energy (of all species in all considered
C               ionization stages (needed only for evaluating
C               thermodynamic derivatoves if convection is considerd)
C        QREF - total charge due to the reference species
C        DQTR - derivative of QREF wrt temperature
C        DQNR - derivative of QREF wrt electron density
C
      use accura
      use atomic
      use basics
      use modelq
      use molec

      implicit none
 
      REAL(DP), INTENT(IN) :: T,ANE
      INTEGER, INTENT(IN)  :: MODE,ID

      REAL(DP), PARAMETER :: 
     *            TH0=5.0404e3_dp,XMX0=2.154e4_dp,
     *            THL0=2.3025851_dp,FI0=3.6113e1_dp,
     *            TRHA=1.5_dp,c1qm=1.0353e-16_dp,c2qm=8762.9_dp,
     *            ev2erg=1.6018e-12_dp,entcon=103.973_dp
      REAL(DP) :: ABND(matom)
      real(dp) :: ffi(matom),pfstu(matom),pfstt(matom),pfstn(matom),
     *            entot(matom)

      REAL(DP) :: TK,TKK,TLN,TKLN15,THET,THL,XMX,DCH,HPOP,DRQT,DRQN,
     *            DRST,DRSN,DFT,DFN,RS,UM,DUTM,DUNM,FI,AREF,
     *            U,DUT,DUN,DCHT,TE,X,XMAX,R,RQ,RI,RE,DFIT,DFIN,
     *            X1,CHIP,DULOG,ADEN,TINV,ENTEL,ANTM
      INTEGER  :: I,ION,JMAX,JMIN,J,J1,JJ,JP1
C
      TLN=LOG(T)*TRHA
      TK=BOLK*T
      TKK=TK+T
      TKLN15=TRHA*LOG(TK)
      THET=TH0/T
      THL=THL0*THET
      XMX=XMX0*SQRT(SQRT(T/ANE))
      DCH=EH/(XMX*XMX*TK)
      Q=0.
      QM=0.
      DQT=0.
      DQN=0.
      DQM=0.
      ENER=0.
      ENTR=0.
      hpop=dens(id)/wmm(id)/ytot(id)

!     if(id.eq.1.or.id.eq.nd) write(*,"(/'STAT',2i4,1p4e11.3/)") 
!    *   id,mode,t,ane,xmx,dch

      ATO: DO I=1,NATOMS
         IF((MODE.GT.1.AND.LRM(I)).OR.(MODE.EQ.1.AND.LGR(I))) CYCLE ATO
         ION=IONIZ(I)
         DRQT=0.
         DRQN=0.
         DRST=0.
         DRSN=0.
         DFT=0.
         DFN=0.
         ENTOT(1)=0.
         RS=UN
         CALL PARTF(I,1,T,ANE,XMX,UM,DUTM,DUNM)
         if(i.eq.1) pfhyd=max(um,two)
         pfstu(1)=um
         pfstt(1)=dutm
         pfstn(1)=dunm
         JMAX=1
         DO J=2,ION
            J1=J-1
            DCHT=DCH*J1
            TE=ENEV(I,J1)*THL
            ENTOT(J)=ENTOT(J1)+TE
            dcht=0.
            FI=FI0+TLN-TE+DCHT
            X=J
            XMAX=XMX*SQRT(X)
            CALL PARTF(I,J,T,ANE,XMAX,U,DUT,DUN)
            pfstu(j)=u
            pfstt(j)=dut
            pfstn(j)=dun
            FFI(J)=0.
            IF(FI.GT.-20.) FFI(J)=EXP(FI)*U/UM/ANE
            IF(FFI(J).GT.UN) JMAX=J
            UM=U
!           if(id.eq.1.or.id.eq.nd) !rite(*,"('atom',3i4,1p4e10.2)")
!    *      id,i,j,pfstu(j),ffi(j),pfstt(j),pfstn(j)
         END DO
         RQ=JMAX-1
         RI=ENTOT(JMAX)
         RE=PFSTT(JMAX)/PFSTU(JMAX)*T
!        if(id.eq.1.or.id.eq.nd)
!    *   write(*,"(12x,i4,1p3e10.1)") jmax,rq,ri,re
         if(jmax.lt.ion) then
            R=UN
            DO J=JMAX+1,ION
               J1=J-1
               DCHT=DCH*J1
               TE=ENEV(I,J1)*THL
               R=R*FFI(J)
c              RR(I,J)=R/pfstu(j)
               RR(I,J)=R
               RS=RS+R
               RQ=RQ+J1*R
               RI=RI+R*ENTOT(J)
               RE=RE+R*PFSTT(J)/PFSTU(J)*T
               DFIT=pfstt(j)/pfstu(j)-pfstt(j1)/pfstu(j1)
     .              +(TRHA+TE-TRHA*DCHT)/T
               DFIN=pfstn(j)/pfstu(j)-pfstn(j1)/pfstu(j1)
     .              +(HALF*DCHT-UN)/ANE
               DFT=DFT+DFIT
               DFN=DFN+DFIN
               DFIT=DFT*R
               DFIN=DFN*R
               DRST=DRST+DFIT
               DRSN=DRSN+DFIN
               DRQT=DRQT+J1*DFIT
               DRQN=DRQN+J1*DFIN
            END DO
         end if
         if(jmax.gt.1) then
            R=UN
            DFT=0.
            DFN=0.
            jmin=min(4,jmax-1)
            DO JJ=1,JMIN
               J=JMAX-JJ
               J1=J-1
               JP1=J+1
               DCHT=DCH*J
               TE=ENEV(I,J)*THL
               R=R/FFI(JP1)
C              RR(I,J)=R/pfstu(j)
               RR(I,J)=R
               RS=RS+R
               RQ=RQ+J1*R
               RI=RI+R*ENTOT(J)
               RE=RE+R*PFSTT(J)/PFSTU(J)*T
               DFIT=pfstt(jp1)/pfstu(jp1)-pfstt(j)/pfstu(j)
     *              +(TRHA+TE-TRHA*DCHT)/T
               DFIN=pfstn(jp1)/pfstu(jp1)-pfstn(j)/pfstu(j)
     *              +(HALF*DCHT-UN)/ANE
               DFT=DFT-DFIT
               DFN=DFN-DFIN
               DFIT=DFT*R
               DFIN=DFN*R
               DRST=DRST+DFIT
               DRSN=DRSN+DFIN
               DRQT=DRQT+J1*DFIT
               DRQN=DRQN+J1*DFIN
!              if(id.eq.1.or.id.eq.nd) write(*,"(12x,2i4,6x,1p4e10.2)")
!    *         jj,j,r,rr(i,j),rs,rq
            END DO
         endif
         X=RQ/RS
         ABND(I)=ABNDD(I,ID)
         X1=ABND(I)/RS
         RR(I,JMAX)=X1
         DO J=1,ION
            IF(J.NE.JMAX) RR(I,J)=RR(I,J)*X1
         END DO
c        RR(I,JMAX)=RR(I,JMAX)/PFSTU(JMAX)
c
c        internal energy and entropy (per 1 hydrogen  atom)
c
         chip=0
         antm=(anta-ane)/ytot(id)
         aref=dens(id)/wmm(id)/ytot(id)
!        if(id.eq.1.and.i.eq.1) write(61,"(i3,1p5e12.4/)") 
!    *   i,anta,ane,antm,aref,ytot(id)
c        do j=1,ion
         do j=1,2
            dulog=0.
            aden=rr(i,j)*antm
            if(aden.lt.1.e-20) aden=1.e-20
            if(pfstu(j).lt.un) pfstu(j)=un
            if(pfstt(j).gt.0.) dulog=pfstt(j)*t/pfstu(j)
            ener=ener+(chip*ev2erg+tk*dulog)*aden
            entr=entr+(tkln15-log(aden)+log(pfstu(j))+
     *           trha*log(amas(i))+tkk*dulog+entcon)*aden
            chip=chip+enev(i,j)
!           if(id.eq.1) write(61,"(2i3,f8.1,1p5e12.4)") 
!    *      i,j,t,pfstu(j),dulog,rr(i,j),aden,entr
         end do
c
         aref=dens(id)/wmm(id)/ytot(id)
c
         rr(i,99)=0.
         if(irefa.eq.0) irefa=1
         IF(I.EQ.IREFA) THEN
            QREF=X*ABND(I)
c           DQTR=(DRQT-X*DRST)*X1
c           DQNR=(DRQN-X*DRSN)*X1
!           if(id.eq.1) write(*,"('qref',2i4,1p3e12.4)")
!    *      irefa,i,abnd(i),x,qref
          ELSE
            Q=X*ABND(I)+Q
c           DQT=DQT+(DRQT-X*DRST)*X1
c           DQN=DQN+(DRQN-X*DRSN)*X1
!           if(id.eq.1) write(*,"('qele',2i4,1p3e12.4)")
!    *      irefa,i,abnd(i),x,q
         END IF
         do j=2,ion
            rr(i,99)=rr(i,99)+rr(i,j)*aref
         end do
         anato(i,id)=rr(i,1)*pfstu(1)
         anion(i,id)=rr(i,2)*pfstu(2)
      END DO ATO

      if(id.eq.1.or.id.eq.nd) then
!        write(6,"(/'state - Q',i4,f10.1,1p3e12.4/)") 
!    *   id,t,ane,qref,q
         do i=1,natoms
            do j=1,ioniz(i)
!              write(*,"('rr',3i4,1p2e12.4)")
!    *         id,i,j,rr(i,j),rr(i,j)/abnd(i)
            end do
         end do
      end if
c
c
c     entropy of electrons
c
c     entel=tkln15-log(ane)+1.5_dp*log(emass(99))+entcon
      entel=tkln15-log(ane)-11.2622_dp+entcon
      entr=entr+entel*ane

!     if(id.eq.1) write(61,"()")

C
C     Negative hydrogen ion
C
c     IF(IHM.EQ.1) THEN
         tinv=un/t
         QM=C1QM*Tinv/SQRT(T)*EXP(C2QM*Tinv)
         DQM=-QM*Tinv*(TRHA+C2QM*Tinv)
c     END IF
      RETURN
      END SUBROUTINE STATE


C     
C     ***************************************************************
C     


      SUBROUTINE INTERP(X,Y,XX,YY,NX,NXX,NPOL,ILOGX,ILOGY)
C     ====================================================
C
C     General interpolation procedure of the (NPOL-1)-th order
C
C     for  ILOGX = 1  logarithmic interpolation in X
C     for  ILOGY = 1  logarithmic interpolation in Y
C
C     Input:
C      X    - array of original x-coordinates
C      Y    - array of corresponding functional values Y=y(X)
C      NX   - number of elements in arrays X or Y
C      XX   - array of new x-coordinates (to which is to be
C             interpolated
C      NXX  - number of elements in array XX
C     Output:
C      YY   - interpolated functional values YY=y(XX)
C
      use accura
      use basics

      implicit none

CC    REAL(DP), INTENT(INOUT)  :: X(MDEPTH),Y(MDEPTH),XX(MDEPTH)
CC    REAL(DP), INTENT(OUT) :: YY(MDEPTH)
      REAL(DP), INTENT(INOUT)  :: X(NX),Y(NX),XX(NXX)
      REAL(DP), INTENT(OUT) :: YY(NXX)

      INTEGER, INTENT(IN)   :: NX,NXX,NPOL,ILOGX,ILOGY
 
      REAL(DP) :: XXX,YYY,T
      INTEGER  :: I,N,NM,NM1,NUP,ID,J,JJ,K,M
C
C     no interpolation for NPOL.LE.0 or NX.le.0
C
      IF(NPOL.LE.0.OR.NX.LE.0) THEN
         N=NX
         IF(NXX.GE.NX) N=NXX
         DO I=1,N
            XX(I)=X(I)
            YY(I)=Y(I)
         END DO
         RETURN
      END IF
C
C     interpolation
C
C     if required, compute logarithms to be interpolated
C
      IF(ILOGX.GT.0) THEN
         DO I=1,NX
            X(I)=LOG10(X(I))
         END DO
         DO I=1,NXX
            XX(I)=LOG10(XX(I))
         END DO
      END IF
      IF(ILOGY.GT.0) THEN
         DO I=1,NX
            Y(I)=LOG10(Y(I))
         END DO
      END IF
C
      NM=(NPOL+1)/2
      NM1=NM+1
      NUP=NX+NM1-NPOL
      DO ID=1,NXX
         XXX=XX(ID)
         DO I=NM1,NUP
            IF(XXX.LE.X(I)) EXIT
         END DO
         J=I-NM
         JJ=J+NPOL-1
         YYY=0.
         DO K=J,JJ
            T=1.
            DO  M=J,JJ
               IF(K.EQ.M) CYCLE
               T=T*(XXX-X(M))/(X(K)-X(M))
            END DO
            YYY=Y(K)*T+YYY
         END DO
         YY(ID)=YYY
      END DO
C
      IF(ILOGX.GT.0) THEN
         DO I=1,NX
            X(I)=EXP(X(I)*2.30258509299405)
         END DO
         DO I=1,NXX
            XX(I)=EXP(XX(I)*2.30258509299405)
         END DO
      END IF
      IF(ILOGY.GT.0) THEN
         DO I=1,NX
            Y(I)=EXP(Y(I)*2.30258509299405)
         END DO
         DO I=1,NXX
            YY(I)=EXP(YY(I)*2.30258509299405)
         END DO
      END IF
C
      RETURN
      END SUBROUTINE INTERP

C     
C     ***************************************************************
C     


      REAL(DP) FUNCTION EXPINT(X)
C     ============================
C
C     First exponential integral function E1(X)
C
      use accura

      implicit none

      REAL(DP), INTENT(IN):: X
      REAL(DP), PARAMETER :: A1  =  -0.57721566,
     *                       A2  =   0.99999193,
     *                       A3  =  -0.24991055,
     *                       A4  =   0.05519968,
     *                       A5  =  -0.00976004,
     *                       A6  =   0.00107857,
     *                       B1  =   0.2677734343,
     *                       B2  =   8.6347608925,
     *                       B3  =  18.059016973,
     *                       B4  =   8.5733287401,
     *                       C1  =   3.9584969228,
     *                       C2  =  21.0996530827,
     *                       C3  =  25.6329561486,
     *                       C4  =   9.5733223454,
     *                       UN  =   1.0
C
      IF(X.LE.UN) THEN
         EXPINT=-LOG(X)+A1+X*(A2+X*(A3+X*(A4+X*(A5+X*A6))))
       ELSE
         EXPINT=EXP(-X)*((B1+X*(B2+X*(B3+X*(B4+X))))/
     *                   (C1+X*(C2+X*(C3+X*(C4+X)))))/X
      END IF
      RETURN
      END FUNCTION EXPINT


