      real(dp), parameter :: xen=2.302585093,xmil=0.001,xmilen=xmil*xen,
     *                       xbtz=1.38054e-16
c
      real(dp) :: tt(50),pn(10),
     *            p4a(22),p4b(10,28),
     *            p5a(30),p5b(10,20),
     *            p6a(37),p6b(10,13),
     *            p7a(40),p7b(10,10),
     *            p8a(41),p8b(10,9),
     *            p9a(45),p9b(10,5)
