     * 209530092, 450866762,  96613623, 186524763, 318839893,   600000,
     * 209530092, 450866762,  96613623, 186524763, 318839893,  1200000,
     * 209530092, 450866762,  96613623, 186524763, 318839893,  2000000,
     * 209530092, 450866762,  96613623, 186524763, 318839893,   600000,
     * 209530092, 450866762,  96613623, 186524763, 318839893,  1200000,
     * 209530092, 450866762,  96613623, 186524763, 318839893,  2000000,
     * 209530092, 450866762,  96613623, 186524763, 318839893,   600000/
      DATA NNN40/
     * 209530092, 450866762,  96613623, 186524763, 318839893,  1200000,
     * 209530092, 450866762,  96613623, 186524763, 318839893,  2000000/
      DATA SCALE/.001,.01,.1,1./
C
      if(mode.lt.0) return
      tk=1.38054d-16*t
      tv=8.6171d-5*t
C     LOWERING OF THE IONIZATION POTENTIAL IN VOLTS FOR UNIT ZEFF
      CHARGE=ANE*2.
      DEBYE=SQRT(TK*DEBCON/CHARGE)
      POTLOW=MIN(1.D0,1.44E-7/DEBYE)
      IF(IIZ.LE.28)then
         write(6,*) 'Error, routine PFHEAV for Z.GE.28 only'
         stop
       endif
c removed elements with z<28
      if(iiz.eq.28) n=1
      IF(IIZ.GT.28) N=3*IIZ+54-135
      IF(IIZ.eq.28) NIONS=4
      IF(IIZ.GT.28) NIONS=3
      NION2=MIN0(JNION+2,NIONS)
      N=N-1
C
      DO ION=1,NION2
         Z=ION
         POTLO(ION)=POTLOW*Z
         N=N+1
         nnn6n=nnn(6+6*(N-1))
         NNN100=NNN6N/100
         XN1= NNN100
         IP(ION)=XN1*1.e-3
         IG=NNN6N-NNN100*100
         GGG=IG
         T2000=IP(ION)*T211
         IT=MAX0(1,MIN0(9, INT(T/T2000-HALF)))
         XIT=IT
         DT=T/T2000-XIT-HALF
         PMIN=ONE
         I=(IT+1)/2
         nnnin=nnn(i+6*(N-1))
         K1=NNNIN/100000
         K2=NNNIN-K1*100000
         K3=K2/10
         xk1=k1
         xk3=k3
         KSCALE=K2-K3*10
         IF(MOD(IT,2).NE.0) THEN
            P1=XK1*SCALE(KSCALE)
            P2=XK3*SCALE(KSCALE)
            IF(DT.LT.0.AND.KSCALE.LE.1) KP1=INT(P1)
            KP1=int(P1)
            IF(KP1.EQ.INT(P2+.5)) PMIN=KP1
          ELSE
            xk3=k3
            P1=XK3*SCALE(KSCALE)
            nnni1n=nnn(i+1+6*(N-1))
            K1=NNNI1N/100000
            KSCALE=MOD(NNNI1N,10)
            xk1=k1
            P2=XK1*SCALE(KSCALE)
         END IF
         PART(ION)= MAX (PMIN,P1+(P2-P1)*DT)
         IF(GGG.EQ.0..OR.POTLO(ION).LT..1.OR.T.LT.T2000*4.) CYCLE
         IF(T.GT.(T2000*11.)) TV=(T2000*11.)*TVCON
         D1=.1/TV
         D2=POTLO(ION)/TV
         DX=SQRT(HIONEV*Z*Z/TV/D2)**3
         PART(ION)=PART(ION)+GGG*EXP(-IP(ION)/TV)*
     *             (DX*(THIRD+(ONE-(HALF+(X18+D2*X120)*D2)*D2)*D2)-
     *              DX*(THIRD+(ONE-(HALF+(X18+D1*X120)*D1)*D1)*D1))
      END DO
      u=part(jnion)
      RETURN
      END SUBROUTINE PFHEAV


!*************************************************************************

 
      SUBROUTINE PFSPEC(IAT,IZI,T,ANE,U,DUT,DUN)
C     ==========================================

C     Non-standard evaluation of the partition function
C     user supplied procedure
C
C     Input:
C      IAT   - atomic number
C      IZI   - ionic charge (=1 for neutrals, =1 for once ionized, etc)
C      T     - temperature
C      ANE   - electron density
C      XMAX  - principal quantum number of the last bound level
C
C     Output:
C      U     - partition function
C      DUT   - derivative dU/dT
C      DUN   - derivative dU/d(ANE)
C
      use accura
      implicit none

      REAL(DP), INTENT(IN) :: T,ANE
      REAL(DP),INTENT(OUT) :: U,DUT,DUN
      INTEGER, INTENT(IN)  :: IAT,IZI

      REAL(DP) :: T1,A1
C
      U=0.
      DUT=0.
      DUN=0.
      T1=T
      A1=ANE
      IF(IAT.EQ.10) THEN
         IF(IZI.EQ.5) U=9.
         IF(IZI.EQ.6) U=6.
         IF(IZI.EQ.7) U=12.
         IF(IZI.EQ.8) U=8.
         IF(IZI.EQ.9) U=1.
         RETURN
      END IF
      IF(IAT.EQ.16) THEN
         IF(IZI.EQ.5) U=1.
         IF(IZI.EQ.6) U=2.
         IF(IZI.EQ.7) U=1.
         IF(IZI.EQ.8) U=6.
         IF(IZI.EQ.9) U=9.
         RETURN
      END IF

      RETURN
      END SUBROUTINE PFSPEC
!     include 'modules.f'
!     program alites
!     write(*,*) 'alites'
!     end program alites
C     
C     
C     ****************************************************************
C 
C
      SUBROUTINE ALIFR1(IJ)
C     =====================
C
C     hydrostatic and radiative equilibrium quantities -
C     derivatives of the total heating and cooling rates in the
C     ALI points with respect to the
C     temperature, electron density, and populations
C     a variant for consistent tridiagonal operator
C
      use accura
      use alipar
      use atomic
      use basics
      use modelq

      implicit none

      INTEGER, INTENT(IN) :: IJ
      REAL(DP), PARAMETER :: T23=TWO/3.0, T43=4.0/3.0
      REAL(DP) :: DSFP1(MLVEXP),DSFP1M(MLVEXP),
     *            DSFP1P(MLVEXP),DSFPMM(MLVEXP)

      REAL(DP) :: WW,DSFT1M,DSFN1M,DSFM1M,DSFT1,DSFN1,DSFM1,DSFX1,
     *            DSFX1D,EMISIV,ABST,S0,SCT,ST,EMISIP,ABSTP,S0P,
     *            SC,SCP,SCTP,STP,DSFT1P,DSFN1P,DSFM1P,
     *            CHMUL,ETMUL,FLMUL,WF,D0,DSFTMM,DSFNMM,DSFMMM,
     *            A0,E0,DDT,DA,FL,D0M,D0P,DTI,PLAD,PLAM,RHO,
     *            DPLA,DBDT,DBDTM,AD,R0,E0M
      INTEGER  :: ID,II
      LOGICAL  :: LNSKIP
C
      IF(IFALI.LE.1) RETURN
      IF(IFALI.GT.5) THEN
         CALL ALIFR3(IJ)
         RETURN
      END IF

      WW=WC(IJ)
      IF(WC(IJ).LE.0.) RETURN
C
      DSFT1M=0.
      DSFN1M=0.
      DSFM1M=0.
      DSFT1D=0.
      DSFN1D=0.
      DSFM1D=0.
      DSFX1=0.
      DSFX1D=0.
      DSFM1=0.
      DO II=1,NLVEXP
         DSFP1M(II)=0.
         DSFP1D(II)=0.
      END DO
c
c ****1. Special expressions for the first depth  -  id=1
c
      ID=1
      LNSKIP=.NOT.LSKIP(ID,IJ)
c
c     Basic auxliliary quantities - derivatives of the source function
c
      if(emis1(id).lt.1.e-35) emis1(id)=1.e-35
      EMISIV=UN/EMIS1(ID)
      ABST=UN/ABSO1(ID)
      S0=EMIS1(ID)*ABST
      sc=scat1(id)
      SCT=SC*ABST
      ST=S0+SCT*RAD1(ID)
      DSFT1=S0*DEMT1(ID)*EMISIV-ST*DABT1(ID)*ABST
      DSFN1=S0*DEMN1(ID)*EMISIV+SIGEC(IJ)*RAD1(ID)*ABST
     *             -ST*DABN1(ID)*ABST
      DSFM1=S0*DEMM1(ID)*EMISIV-ST*DABM1(ID)*ABST
      DO II=1,NLVEXP
         DSFP1(II)=S0*DEMP1(II,ID)*EMISIV-ST*DABP1(II,ID)*ABST
      END DO
C
c     preparations for the next depth
c
      if(emis1(id+1).lt.1.e-35) emis1(id+1)=1.e-35
      EMISIP=UN/EMIS1(ID+1)
      ABSTP=UN/ABSO1(ID+1)
      S0P=EMIS1(ID+1)*ABSTP
      scp=scat1(id+1)
      SCTP=SCP*ABSTP
      STP=S0P+SCTP*RAD1(ID+1)
      DSFT1P=S0P*DEMT1(ID+1)*EMISIP-STP*DABT1(ID+1)*ABSTP
      DSFN1P=S0P*DEMN1(ID+1)*EMISIP+SIGEC(IJ)*RAD1(ID+1)*ABSTP
     *       -STP*DABN1(ID+1)*ABSTP
      DSFM1P=S0P*DEMM1(ID+1)*EMISIP-STP*DABM1(ID+1)*ABSTP
      DO II=1,NLVEXP
          DSFP1P(II)=S0P*DEMP1(II,ID+1)*EMISIP-
     *                      STP*DABP1(II,ID+1)*ABSTP
      END DO
      IF(IRDER.EQ.1.OR.IRDER.EQ.3) THEN
        DSFDT(ID)=DSFT1*ALI1(ID)
        DSFDN(ID)=DSFN1*ALI1(ID)
        DSFDM(ID)=DSFM1*ALI1(ID)
      END IF
      IF(IRDER.GT.1) THEN
        DO II=1,NLVEXP
          DSFDP(II,ID)=DSFP1(II)*ALI1(ID)
        END DO
      END IF
c
c     Hydrostatic equilibrium quantities
c
      WF=WW*FH(IJ)
c     IF(LNSKIP) THEN
c        WF=WW*FH(IJ)
c        WQ=WW*Q0(IJ)
c        WEUR=WW*EMIS1(ID)*UU0(IJ)
c        WEQ=WW*EMIS1(ID)*Q0(IJ)
c
c        FPRD(ID)=FPRD(ID)+WF*RAD1(ID)-WQ*EMIS1(ID)
c    *                    -WW*HEXTRD(IJ)*ABSO1(ID)
c       E0=WF*RAD1(ID)
c       D0=WF*ABSO1(ID)*ALI1(ID)-WW*DEDM1*UU0(IJ)*EMIS1(ID)
c       C0=WW*Q0(IJ)
c       F0=ww*EE0*DEDM1*EMIS1(ID)*UU0(IJ)
c       HEIT(ID)=HEIT(ID)+(WF-WEUR)*DSFT1-(WQ-*DEMT1(ID)
c       HEIT(ID)=HEIT(ID)+D0*DSFT1+E0*DABT1(ID)-C0*DEMT1(ID)
c       HEIN(ID)=HEIN(ID)+D0*DSFN1+E0*DABN1(ID)-C0*DEMN1(ID)+F0
c       HEIM(ID)=HEIM(ID)+D0*DSFM1+E0*DABM1(ID)-C0*DEMM1(ID)-F0
c       HEIM(ID)=HEIM(ID)+F0
c       DO II=1,NLVEXP
c         HEIP(II,ID)=HEIP(II,ID)+D0*DSFP1(II)+E0*DABP1(II,ID)
c    *               -C0*DEMP1(II,ID)
c       END DO
c     END IF
c
      IF(LNSKIP) THEN
        CHMUL=WW*(FH(IJ)*RAD1(ID)-EMIS1(ID)*UU0(IJ)*DEDM1
     *       -FH(IJ)*S0*ALI1(ID))
        ETMUL=WW*(Q0(IJ)-FH(IJ)*ALI1(ID))
        FLMUL=WW*(FH(IJ)*ABSO1(ID)*RAD1(ID)-EMIS1(ID)*Q0(IJ))
C
        FPRD(ID)=FPRD(ID)+FLMUL
        HEIT(ID)=HEIT(ID)+CHMUL*DABT1(ID)-ETMUL*DEMT1(ID)
        HEIN(ID)=HEIN(ID)+CHMUL*DABN1(ID)-ETMUL*DEMN1(ID)
        HEIM(ID)=HEIM(ID)+WW*EMIS1(ID)*UU0(IJ)*ABSO1(ID)
        DO II=1,NLVEXP
           HEIP(II,ID)=HEIP(II,ID)+CHMUL*DABP1(II,ID)-ETMUL*DEMP1(II,ID)
        END DO
      END IF
c
c     Differential equation part of radiative equilibrium
c
      FLFIX(ID)=FLFIX(ID)+WF*RAD1(ID)-WW*HEXTRD(IJ)
      FLRD(ID)=FLRD(ID)+W(IJ)*FH(IJ)*RAD1(ID)-W(IJ)*HALF*EXTRAD(IJ)
      IF(REDIF(ID).GT.0.) THEN
        WF=WW*ALI1(ID)
        REDT(ID)=REDT(ID)+WF*DSFT1
        REDN(ID)=REDN(ID)+WF*DSFN1
        REDM(ID)=REDM(ID)+WF*DSFM1
        REDX(ID)=REDX(ID)+WF*DSFX1
        DO II=1,NLVEXP
          REDP(II,ID)=REDP(II,ID)+WF*DSFP1(II)
        END DO
      END IF
c
C     Integral equation part of the radiative equilibrium
C
      IF(REINT(ID).GT.0) THEN
c     ABST=ABSO1(ID)-ELSCAT(ID)
      abst=abso1(id)-scat1(id)
      D0=ABST*ALI1(ID)
      FCOOLI(ID)=FCOOLI(ID)+WW*(EMIS1(ID)-ABST*RAD1(ID))
        REIT(ID)=REIT(ID)+WW*(D0*DSFT1+RAD1(ID)*DABT1(ID)-DEMT1(ID))
c      write(6,"('alist2',i5,1p10e12.4)")
c    * ij,ww,d0,abso1(id),scat1(id),ali1(id),
c    * dsft1,rad1(id),dabt1(id),demt1(id),reit(id)
        REIN(ID)=REIN(ID)+WW*(D0*DSFN1+
     &                   RAD1(ID)*(DABN1(ID)-SIGEC(IJ))-DEMN1(ID))
        REIM(ID)=REIM(ID)+WW*(D0*DSFM1+RAD1(ID)*DABM1(ID)-DEMM1(ID))
        DO II=1,NLVEXP
          REIP(II,ID)=REIP(II,ID)+WW*(D0*DSFP1(II)+
     &                     RAD1(ID)*DABP1(II,ID)-DEMP1(II,ID))
        END DO
      END IF

C
c ****2. loop over depths
c
      DO ID=2,ND-1

        LNSKIP=.NOT.LSKIP(ID,IJ)

        DSFTMM=DSFT1M
        DSFNMM=DSFN1M
        DSFMMM=DSFM1M
        DO II=1,NLVEXP
           DSFPMM(II)=DSFP1M(II)
        END DO
        DSFT1M=DSFT1
        DSFN1M=DSFN1
        DSFM1M=DSFM1
        DO II=1,NLVEXP
           DSFP1M(II)=DSFP1(II)
        END DO
        S0=S0P
        DSFT1=DSFT1P
        DSFN1=DSFN1P
        DSFM1=DSFM1P
        DO II=1,NLVEXP
           DSFP1(II)=DSFP1P(II)
        END DO
c
        if(emis1(id+1).lt.1.e-35) emis1(id+1)=1.e-35
        EMISIP=UN/EMIS1(ID+1)
        ABSTP=UN/ABSO1(ID+1)
        S0P=EMIS1(ID+1)*ABSTP
        scp=scat1(id+1)
        SCTP=SCP*ABSTP
        STP=S0P+SCTP*RAD1(ID+1)
        DSFT1P=S0P*DEMT1(ID+1)*EMISIP-STP*DABT1(ID+1)*ABSTP
        DSFN1P=S0P*DEMN1(ID+1)*EMISIP+SIGEC(IJ)*RAD1(ID+1)*ABSTP
     *        -STP*DABN1(ID+1)*ABSTP
        DSFM1P=S0P*DEMM1(ID+1)*EMISIP-STP*DABM1(ID+1)*ABSTP
        DO II=1,NLVEXP
           DSFP1P(II)=S0P*DEMP1(II,ID+1)*EMISIP-
     *                      STP*DABP1(II,ID+1)*ABSTP
        END DO

        IF(IRDER.EQ.1.OR.IRDER.EQ.3) THEN
           DSFDT(ID)=DSFT1*ALI1(ID)
           DSFDN(ID)=DSFN1*ALI1(ID)
           DSFDM(ID)=DSFM1*ALI1(ID)
        END IF
        IF(IRDER.GT.1) THEN
           DO II=1,NLVEXP
              DSFDP(II,ID)=DSFP1(II)*ALI1(ID)
           END DO
        END IF
c
c       Hydrostatic equilibrium equation
c
        IF(LNSKIP) THEN
          D0=WW*FAK1(ID)
          A0=WW*FAK1(ID-1)
          FPRD(ID)=FPRD(ID)+D0*RAD1(ID)-A0*RAD1(ID-1)
          E0=D0*ALIM1(ID)-A0*ALI1(ID-1)
          D0=D0*ALI1(ID)-A0*ALIP1(ID-1)
          HEIT(ID)=HEIT(ID)+D0*DSFT1
          HEIN(ID)=HEIN(ID)+D0*DSFN1
          HEIM(ID)=HEIM(ID)+D0*DSFM1
          HEITM(ID)=HEITM(ID)+E0*DSFT1M
          HEINM(ID)=HEINM(ID)+E0*DSFN1M
          HEIMM(ID)=HEIMM(ID)+E0*DSFM1M
          DO II=1,NLVEXP
            HEIP(II,ID)=HEIP(II,ID)+D0*DSFP1(II)
            HEIPM(II,ID)=HEIPM(II,ID)+E0*DSFP1M(II)
          END DO
        END IF
C
C       Differential equation part of radiative equilibrium
C
        DDT=UN/(ABSOT(ID)+ABSOT(ID-1))
        DA=DDT/DELDMZ(ID-1)
        FL=(RAD1(ID)*FAK1(ID)-RAD1(ID-1)*FAK1(ID-1))*DA
        FLFIX(ID)=FLFIX(ID)+WW*FL
        FLRD(ID)=FLRD(ID)+W(IJ)*FL
        IF(REDIF(ID).GT.0) THEN
          D0=WW*FAK1(ID)*DA
          A0=WW*FAK1(ID-1)*DA
          D0M=D0*ALIM1(ID)-A0*ALI1(ID-1)
          D0P=D0*ALIP1(ID)
          D0=D0*ALI1(ID)-A0*ALIP1(ID-1)
          E0=WW*FL*DDT
          REDX(ID)=REDX(ID)+E0*ABSO1(ID)
          REDXM(ID)=REDXM(ID)+E0*ABSO1(ID-1)
          E0M=E0*DENSI(ID-1)
          E0=E0*DENSI(ID)
          REDT(ID)=REDT(ID)+D0*DSFT1-E0*DABT1(ID)
          REDTM(ID)=REDTM(ID)+D0M*DSFT1M-E0M*DABT1(ID-1)
          REDN(ID)=REDN(ID)+D0*DSFN1-E0*DABN1(ID)
          REDNM(ID)=REDNM(ID)+D0M*DSFN1M-E0M*DABN1(ID-1)
          REDM(ID)=REDM(ID)+D0*DSFM1-E0*DABM1(ID)
          REDMM(ID)=REDMM(ID)+D0M*DSFM1M-E0M*DABM1(ID-1)
          DO II=1,NLVEXP
            REDP(II,ID)=REDP(II,ID)+D0*DSFP1(II)-E0*DABP1(II,ID)
            REDPM(II,ID)=REDPM(II,ID)+D0M*DSFP1M(II)-
     *                   E0M*DABP1(II,ID-1)
          END DO
        END IF
c
C       Integral equation part of the radiative equilibrium
C
        IF(REINT(ID).GT.0) THEN
          ABST=ABSO1(ID)-SCAT1(ID)
          D0=ABST*ALI1(ID)
          FCOOLI(ID)=FCOOLI(ID)+WW*(EMIS1(ID)-ABST*RAD1(ID))
          REIN(ID)=REIN(ID)+WW*(D0*DSFN1+
     *                 RAD1(ID)*(DABN1(ID)-SIGEC(IJ))-DEMN1(ID))
          DO II=1,NLVEXP
            REIP(II,ID)=REIP(II,ID)+WW*(D0*DSFP1(II)+
     *                     RAD1(ID)*DABP1(II,ID)-DEMP1(II,ID))
          END DO
          REIT(ID)=REIT(ID)+WW*(D0*DSFT1+
     *                RAD1(ID)*DABT1(ID)-DEMT1(ID))
          REIM(ID)=REIM(ID)+WW*(D0*DSFM1+
     *                RAD1(ID)*DABM1(ID)-DEMM1(ID))
        END IF

      END DO

C
c ****3. deepest point - ID=ND
c
      ID=ND

      LNSKIP=.NOT.LSKIP(ID,IJ)

      DSFTMM=DSFT1M
      DSFNMM=DSFN1M
      DSFMMM=DSFM1M
      DO II=1,NLVEXP
         DSFPMM(II)=DSFP1M(II)
      END DO
      DSFT1M=DSFT1
      DSFN1M=DSFN1
      DSFM1M=DSFM1
      DO II=1,NLVEXP
         DSFP1M(II)=DSFP1(II)
      END DO
      S0=S0P
      DSFT1=DSFT1P
      DSFN1=DSFN1P
      DSFM1=DSFM1P
      DO II=1,NLVEXP
         DSFP1(II)=DSFP1P(II)
      END DO
      DSFT1D=0.
      DSFN1D=0.
      DSFM1D=0.
      DO II=1,NLVEXP
         DSFP1D(II)=0.
      END DO
C
C     Improved lower boundary condition
C
      IF(IBC.LT.0.AND.IDISK.EQ.0) THEN
        DTI=UN/(DELDMZ(ID-1)*(ABSOT(ID)+ABSOT(ID-1)))
        PLAD=XKFB(ID)/XKF1(ID)
        DBDT=PLAD/XKF1(ID)*HKT21(ID)*FREQ(IJ)*DTI
        IF(IBC.EQ.-1) THEN
          DSFT1=DSFT1+DBDT
        ELSE IF(IBC.lE.-2) THEN
           RHO=DENS(ID)
           PLAM=XKFB(ID-1)/XKF1(ID-1)
           DPLA=(PLAD-PLAM)*DTI
           AD=(PLAD+T23*DPLA)*DTI
           A0=-(PLAD+T43*DPLA)*DTI*DTI
           R0=DELDMZ(ID-1)/RHO
           D0=A0*R0
           E0=ABSO1(ID)/RHO*WMM(ID)
           DSFT1=DSFT1-DBDT*(UN+T23*DTI)+D0*DABT1(ID)
           DSFN1=DSFN1+D0*(DABN1(ID)+E0)
           DSFM1=DSFM1-D0*E0
           DO II=1,NLVEXP
              DSFP1(II)=DSFP1(II)+D0*DABP1(II,ID)
           END DO
C
           DBDTM=PLAM/XKF1(ID-1)*HKT21(ID-1)*FREQ(IJ)*DTI
           R0=DELDMZ(ID-1)/DENS(ID-1)
           D0=A0*R0
           E0=ABSO1(ID-1)/DENS(ID-1)*WMM(ID-1)
           DSFT1D=-T23*DBDTM*DTI+D0*DABT1(ID-1)
           DSFN1D=D0*(DABN1(ID-1)+E0)
           DSFM1D=-D0*E0
           DO II=11,NLVEXP
              DSFP1D(II)=D0*DABP1(II,ID-1)
           END DO
        END IF
c
c       new formulation

       ELSE
        DTI=UN/(DELDMZ(ID-1)*(ABSOT(ID)+ABSOT(ID-1)))
        PLAD=XKFB(ID)/XKF1(ID)
        DBDT=PLAD/XKF1(ID)*HKT21(ID)*FREQ(IJ)*DTI
        RHO=DENS(ID)
        PLAM=XKFB(ID-1)/XKF1(ID-1)
        DPLA=(PLAD-PLAM)*DTI
        AD=(PLAD+T23*DPLA)*DTI
        A0=-(PLAD+T43*DPLA)*DTI*DTI
        R0=DELDMZ(ID-1)/RHO
        D0=A0*R0
        E0=ABSO1(ID)/RHO*WMM(ID)
        DSFT1=DSFT1+DBDT*(UN+T23*DTI)+D0*DABT1(ID)
        DSFN1=DSFN1+D0*(DABN1(ID)+E0)
        DSFM1=DSFM1-D0*E0
        DO II=1,NLVEXP
           DSFP1(II)=DSFP1(II)+D0*DABP1(II,ID)
        END DO
C
        DBDTM=PLAM/XKF1(ID-1)*HKT21(ID-1)*FREQ(IJ)*DTI
        R0=DELDMZ(ID-1)/DENS(ID-1)
        D0=A0*R0
        E0=ABSO1(ID-1)/DENS(ID-1)*WMM(ID-1)
        DSFT1D=(-T23*DBDTM*DTI+D0*DABT1(ID-1))*ALI1(ID)
        DSFN1D=D0*(DABN1(ID-1)+E0)*ALI1(ID)
        DSFM1D=-D0*E0*ALI1(ID)
        DO II=11,NLVEXP
           DSFP1D(II)=D0*DABP1(II,ID-1)*ALI1(ID)
        END DO

      END IF
C
      IF(IRDER.EQ.1.OR.IRDER.EQ.3) THEN
        DSFDT(ID)=DSFT1*ALI1(ID)
        DSFDN(ID)=DSFN1*ALI1(ID)
        DSFDM(ID)=DSFM1*ALI1(ID)
      END IF
      IF(IRDER.GT.1) THEN
        DO II=1,NLVEXP
          DSFDP(II,ID)=DSFP1(II)*ALI1(ID)
        END DO
      END IF
c
c     Hydrostatic equilibrium equation
c
      IF(LNSKIP) THEN
        D0=WW*FAK1(ID)
        A0=WW*FAK1(ID-1)
        FPRD(ID)=FPRD(ID)+D0*RAD1(ID)-A0*RAD1(ID-1)
        E0=D0*ALIM1(ID)-A0*ALI1(ID-1)
        D0=D0*ALI1(ID)-A0*ALIP1(ID-1)
        HEIT(ID)=HEIT(ID)+D0*DSFT1
        HEIN(ID)=HEIN(ID)+D0*DSFN1
        HEIM(ID)=HEIM(ID)+D0*DSFM1
        HEITM(ID)=HEITM(ID)+E0*DSFT1M+A0*DSFT1D
        HEINM(ID)=HEINM(ID)+E0*DSFN1M+A0*DSFN1D
        HEIMM(ID)=HEIMM(ID)+E0*DSFM1M+A0*DSFM1D
        DO II=1,NLVEXP
          HEIP(II,ID)=HEIP(II,ID)+D0*DSFP1(II)
          HEIPM(II,ID)=HEIPM(II,ID)+E0*DSFP1M(II)+A0*DSFP1D(II)
        END DO
      END IF
C
C     Differential equation part of radiative equilibrium
C
      DDT=UN/(ABSOT(ID)+ABSOT(ID-1))
      DA=DDT/DELDMZ(ID-1)
      FL=(RAD1(ID)*FAK1(ID)-RAD1(ID-1)*FAK1(ID-1))*DA
      FLFIX(ID)=FLFIX(ID)+WW*FL
      FLRD(ID)=FLRD(ID)+W(IJ)*FL
      IF(REDIF(ID).GT.0) THEN
        D0=WW*FAK1(ID)*DA
        A0=WW*FAK1(ID-1)*DA
        D0M=D0*ALIM1(ID)-A0*ALI1(ID-1)
        D0P=D0*ALIP1(ID)
        D0=D0*ALI1(ID)-A0*ALIP1(ID-1)
        E0=WW*FL*DDT
        REDX(ID)=REDX(ID)+E0*ABSO1(ID)
        REDXM(ID)=REDXM(ID)+E0*ABSO1(ID-1)
        E0M=E0*DENSI(ID-1)
        E0=E0*DENSI(ID)
        REDT(ID)=REDT(ID)+D0*DSFT1-E0*DABT1(ID)
        REDTM(ID)=REDTM(ID)+D0M*DSFT1M-E0M*DABT1(ID-1)+A0*DSFT1D
        REDN(ID)=REDN(ID)+D0*DSFN1-E0*DABN1(ID)
        REDNM(ID)=REDNM(ID)+D0M*DSFN1M-E0M*DABN1(ID-1)+A0*DSFN1D
        REDM(ID)=REDM(ID)+D0*DSFM1-E0*DABM1(ID)
        REDMM(ID)=REDMM(ID)+D0M*DSFM1M-E0M*DABM1(ID-1)+A0*DSFM1D
        DO II=1,NLVEXP
          REDP(II,ID)=REDP(II,ID)+D0*DSFP1(II)-E0*DABP1(II,ID)
          REDPM(II,ID)=REDPM(II,ID)+D0M*DSFP1M(II)-
     *                 E0M*DABP1(II,ID-1)+A0*DSFP1D(II)
        END DO
      END IF
c
C     Integral equation part of the radiative equilibrium
C
      IF(REINT(ID).GT.0) THEN
        ABST=ABSO1(ID)-SCAT1(ID)
        D0=ABST*ALI1(ID)
        FCOOLI(ID)=FCOOLI(ID)+WW*(EMIS1(ID)-ABST*RAD1(ID))
        REIN(ID)=REIN(ID)+WW*(D0*DSFN1+
     *                RAD1(ID)*(DABN1(ID)-SIGEC(IJ))-DEMN1(ID))
        REIM(ID)=REIM(ID)+WW*(D0*DSFM1+RAD1(ID)*DABM1(ID)-DEMM1(ID))
        DO II=1,NLVEXP
          REIP(II,ID)=REIP(II,ID)+WW*(D0*DSFP1(II)+
     *                   RAD1(ID)*DABP1(II,ID)-DEMP1(II,ID))
        END DO
        IF(IBC.EQ.0) THEN
          REIT(ID)=REIT(ID)+WW*(D0*DSFT1+
     *                  RAD1(ID)*DABT1(ID)-DEMT1(ID))
        ELSE
          REIT(ID)=REIT(ID)+WW*(D0*(DSFT1-DBDT)+E0*DABT1(ID)+
     *                  RAD1(ID)*DABT1(ID)-DEMT1(ID)+
     *                  ALI1(ID)/ABST*DBDT)
        END IF
      END IF

      RETURN
      END SUBROUTINE ALIFR1
C     
C     
C     ****************************************************************
C 
C
      SUBROUTINE ALIFR3(IJ)
C     =====================
C
C     hydrostatic and radiative equilibrium quantities -
C     derivatives of the total heating and cooling rates in the
C     ALI points with respect to the
C     temperature, electron density, and populations
C     a variant for consistent tridiagonal operator
C
      use accura
      use alipar
      use atomic
      use basics
      use modelq

      implicit none

      INTEGER, INTENT(IN) :: IJ
      REAL(DP), PARAMETER :: T23=TWO/3.0, T43=4.0/3.0
      REAL(DP) :: DSFP1(MLVEXP),DSFP1M(MLVEXP),
     *            DSFP1P(MLVEXP),DSFPMM(MLVEXP)

      REAL(DP) :: WW,DSFT1M,DSFN1M,DSFX1,WWK,WWKA,WWKC,
     *            DSFT1,DSFN1,TAU23,TAU43,
     *            DSFX1D,EMISIV,ABST,S0,SCT,ST,EMISIP,ABSTP,S0P,
     *            SC,SCP,SCTP,STP,DSFT1P,DSFN1P,
     *            WF,D0,DSFTMM,DSFNMM,E1,EXTD,
     *            A0,E0,DDT,DA,FL,D0M,D0P,PLAD,PLAM,RHD,
     *            DBDT,DBDTM,E0M
      INTEGER  :: ID,II
      LOGICAL  :: LNSKIP
C
      IF(IFALI.LE.1) RETURN
      WW=WC(IJ)
C
      DSFT1M=0.
      DSFN1M=0.
      DSFT1D=0.
      DSFN1D=0.
      DO II=1,NLVEXP
         DSFP1M(II)=0.
         DSFP1D(II)=0.
      END DO

c ****1. Special expressions for the first depth  -  id=1
c
      ID=1
      LNSKIP=.NOT.LSKIP(ID,IJ)
c
c     Basic auxliliary quantities - derivatives of the source function
c
      EMISIV=UN/EMIS1(ID)
      ABST=UN/ABSO1(ID)
      S0=EMIS1(ID)*ABST
      SC=ELEC(ID)*SIGEC(IJ)
      SCT=SC*ABST
      ST=S0+SCT*RAD1(ID)
      DSFT1=S0*DEMT1(ID)*EMISIV-ST*DABT1(ID)*ABST
      DSFN1=S0*DEMN1(ID)*EMISIV+SIGEC(IJ)*RAD1(ID)*ABST-
     *            ST*DABN1(ID)*ABST
      DO II=1,NLVEXP
        DSFP1(II)=S0*DEMP1(II,ID)*EMISIV-ST*DABP1(II,ID)*ABST
      END DO
      EMISIP=UN/EMIS1(ID+1)
      ABSTP=UN/ABSO1(ID+1)
      S0P=EMIS1(ID+1)*ABSTP
      SCP=ELEC(ID+1)*SIGE
      SCTP=SCP*ABSTP
      STP=S0P+SCTP*RAD1(ID+1)
      DSFT1P=S0P*DEMT1(ID+1)*EMISIP-STP*DABT1(ID+1)*ABSTP
      DSFN1P=S0P*DEMN1(ID+1)*EMISIP+SIGEC(IJ)*RAD1(ID+1)*ABSTP-
     *              STP*DABN1(ID+1)*ABSTP
      DO II=1,NLVEXP
        DSFP1P(II)=S0P*DEMP1(II,ID+1)*EMISIP-
     *                    STP*DABP1(II,ID+1)*ABSTP
      END DO
C
C
C     additional quantites in case of external irradiation
C
      extd=extrad(ij)
      if(extd.gt.0) then
         DA=UN/(DELDMZ(ID)*(ABSOT(ID)+ABSOT(ID+1)))
         D0=TWO*HEXTRD(IJ)*DA*DA
         E0=D0*DELDMZ(ID)*DENSI(ID)
         E1=D0*DELDMZ(ID+1)*DENSI(ID+1)
         DSFT1=DSFT1-E0*DABT1(ID)
         DSFN1=DSFN1-E0*(DABN1(ID)+ABSO1(ID)*DENSIM(ID))
         DSFX1=E0*ABSO1(ID)*DENSIM(ID)
         DSFT1D=DSFT1D-E1*DABT1(ID+1)
         DSFN1D=DSFN1D-E1*(DABN1(ID+1)+ABSO1(ID+1)*DENSIM(ID+1))
         DSFX1D=E1*ABSO1(ID+1)*DENSIM(ID+1)
         DO II=1,NLVEXP
            DSFP1(II)=DSFP1(II)-E0*DABP1(II,ID)
            DSFP1D(II)=DSFP1D(II)-E0*DABP1(II,ID+1)
         END DO
      end if
c
      IF(IRDER.EQ.1.OR.IRDER.EQ.3) THEN
        DSFDT(ID)=DSFT1*ALI1(ID)
        DSFDN(ID)=DSFN1*ALI1(ID)
        DSFDTM(ID)=DSFT1M*ALIM1(ID)
        DSFDNM(ID)=DSFN1M*ALIM1(ID)
        DSFDTP(ID)=DSFT1P*ALIP1(ID)
        DSFDNP(ID)=DSFN1P*ALIP1(ID)
      END IF
      IF(IRDER.GT.1) THEN
        DO II=1,NLVEXP
          DSFDP(II,ID)=DSFP1(II)*ALI1(ID)
          DSFDPM(II,ID)=DSFP1M(II)*ALIM1(ID)
          DSFDPP(II,ID)=DSFP1P(II)*ALIP1(ID)
        END DO
      END IF
c
c     Hydrostatic equilibrium quantities
c
      WF=WW*FH(IJ)
      IF(LNSKIP) THEN
        FPRD(ID)=FPRD(ID)+WF*ABSO1(ID)*RAD1(ID)-
     *               WW*HEXTRD(IJ)*ABSO1(ID)
        E0=WF*RAD1(ID)
        D0=WF*ABSO1(ID)*ALI1(ID)
        HEIT(ID)=HEIT(ID)+D0*DSFT1+E0*DABT1(ID)
        HEIN(ID)=HEIN(ID)+D0*DSFN1+E0*DABN1(ID)
        DO II=1,NLVEXP
          HEIP(II,ID)=HEIP(II,ID)+D0*DSFP1(II)+E0*DABP1(II,ID)
        END DO
      END IF
c
c     Differential equation part of radiative equilibrium
c
      FLFIX(ID)=FLFIX(ID)+WF*RAD1(ID)-WW*HEXTRD(IJ)
      IF(REDIF(ID).GT.0.) THEN
        WF=WF*ALI1(ID)
        REDT(ID)=REDT(ID)+WF*DSFT1
        REDN(ID)=REDN(ID)+WF*DSFN1
        DO II=1,NLVEXP
          REDP(II,ID)=REDP(II,ID)+WF*DSFP1(II)
        END DO
        redtp(id)=redtp(id)+wf*dsft1d
        rednp(id)=rednp(id)+wf*dsfn1d
      END IF
c
C     Integral equation part of the radiative equilibrium
C
      IF(REINT(ID).GT.0) THEN
        ABST=ABSO1(ID)-ELSCAT(ID)
        D0=ABST*ALI1(ID)
        WWKC=WW*ABST*ALIP1(ID)
        FCOOLI(ID)=FCOOLI(ID)+WW*(EMIS1(ID)-ABST*RAD1(ID))
        REIN(ID)=REIN(ID)+WW*(D0*DSFN1+
     *                   RAD1(ID)*(DABN1(ID)-SIGEC(IJ))-DEMN1(ID))
        CREIT(ID)=CREIT(ID)+WWKC*DSFT1P
        CREIN(ID)=CREIN(ID)+WWKC*DSFN1P
        DO II=1,NLVEXP
          REIP(II,ID)=REIP(II,ID)+WW*(D0*DSFP1(II)+
     *                     RAD1(ID)*DABP1(II,ID)-DEMP1(II,ID))
          CREIP(II,ID)=CREIP(II,ID)+WWKC*DSFP1P(II)
        END DO
        REIT(ID)=REIT(ID)+WW*(D0*DSFT1+RAD1(ID)*DABT1(ID)-DEMT1(ID))
        if(extd.gt.0.) then
           creit(id)=creit(id)+ww*d0*dsft1d
           crein(id)=crein(id)+ww*d0*dsfn1d
        end if
      END IF

C
c ****2. loop over depths
c
      DO ID=2,ND-1

        LNSKIP=.NOT.LSKIP(ID,IJ)

        DSFTMM=DSFT1M
        DSFNMM=DSFN1M
        DO II=1,NLVEXP
          DSFPMM(II)=DSFP1M(II)
        END DO
        DSFT1M=DSFT1
        DSFN1M=DSFN1
        DO II=1,NLVEXP
          DSFP1M(II)=DSFP1(II)
        END DO
        S0=S0P
        DSFT1=DSFT1P
        DSFN1=DSFN1P
        DO II=1,NLVEXP
          DSFP1(II)=DSFP1P(II)
        END DO

        EMISIP=UN/EMIS1(ID+1)
        ABSTP=UN/ABSO1(ID+1)
        S0P=EMIS1(ID+1)*ABSTP
        SCP=ELEC(ID+1)*SIGEC(IJ)
        SCTP=SCP*ABSTP
        STP=S0P+SCTP*RAD1(ID+1)
        DSFT1P=S0P*DEMT1(ID+1)*EMISIP-STP*DABT1(ID+1)*ABSTP
        DSFN1P=S0P*DEMN1(ID+1)*EMISIP+SIGEC(IJ)*RAD1(ID+1)*ABSTP-
     *                STP*DABN1(ID+1)*ABSTP
        DO II=1,NLVEXP
          DSFP1P(II)=S0P*DEMP1(II,ID+1)*EMISIP-
     *                      STP*DABP1(II,ID+1)*ABSTP
        END DO

        IF(IRDER.EQ.1.OR.IRDER.EQ.3) THEN
          DSFDT(ID)=DSFT1*ALI1(ID)
          DSFDN(ID)=DSFN1*ALI1(ID)
        END IF
        IF(IRDER.GT.1) THEN
          DO II=1,NLVEXP
            DSFDP(II,ID)=DSFP1(II)*ALI1(ID)
         END DO
        END IF
c
c       Hydrostatic equilibrium equation
c
        IF(LNSKIP) THEN
          D0=WW*FAK1(ID)
          A0=WW*FAK1(ID-1)
          FPRD(ID)=FPRD(ID)+D0*RAD1(ID)-A0*RAD1(ID-1)
          E0=D0*ALIM1(ID)-A0*ALI1(ID-1)
          D0=D0*ALI1(ID)-A0*ALIP1(ID-1)
          HEIT(ID)=HEIT(ID)+D0*DSFT1
          HEIN(ID)=HEIN(ID)+D0*DSFN1
          HEITM(ID)=HEITM(ID)+E0*DSFT1M
          HEINM(ID)=HEINM(ID)+E0*DSFN1M
          DO II=1,NLVEXP
            HEIP(II,ID)=HEIP(II,ID)+D0*DSFP1(II)
            HEIPM(II,ID)=HEIPM(II,ID)+E0*DSFP1M(II)
          END DO
        END IF
C
C       Differential equation part of radiative equilibrium
C
        DDT=UN/(ABSOT(ID)+ABSOT(ID-1))
        DA=DDT/DELDMZ(ID-1)
        FL=(RAD1(ID)*FAK1(ID)-RAD1(ID-1)*FAK1(ID-1))*DA
        FLFIX(ID)=FLFIX(ID)+WW*FL
        IF(REDIF(ID).GT.0) THEN
          if(ifalih.eq.0) then
          D0=WW*FAK1(ID)*DA
          A0=WW*FAK1(ID-1)*DA
          D0M=D0*ALIM1(ID)-A0*ALI1(ID-1)
          D0P=D0*ALIP1(ID)
          D0=D0*ALI1(ID)-A0*ALIP1(ID-1)
          E0=WW*FL*DDT
          REDX(ID)=REDX(ID)+E0*ABSO1(ID)
          REDXM(ID)=REDXM(ID)+E0*ABSO1(ID-1)
          E0M=E0*DENSI(ID-1)
          E0=E0*DENSI(ID)
          REDT(ID)=REDT(ID)+D0*DSFT1-E0*DABT1(ID)
          REDTM(ID)=REDTM(ID)+D0M*DSFT1M-E0M*DABT1(ID-1)
          REDN(ID)=REDN(ID)+D0*DSFN1-E0*DABN1(ID)
          REDNM(ID)=REDNM(ID)+D0M*DSFN1M-E0M*DABN1(ID-1)
          DO II=1,NLVEXP
            REDP(II,ID)=REDP(II,ID)+D0*DSFP1(II)-E0*DABP1(II,ID)
            REDPM(II,ID)=REDPM(II,ID)+D0M*DSFP1M(II)-
     *                         E0M*DABP1(II,ID-1)
          END DO
          else
          d0=ww*alih1(id)
          REDT(ID)=REDT(ID)+D0*DSFT1
          REDN(ID)=REDN(ID)+D0*DSFN1
          DO II=1,NLVEXP
            REDP(II,ID)=REDP(II,ID)+D0*DSFP1(II)
          END DO
          end if
        END IF
c
C       Integral equation part of the radiative equilibrium
C
        IF(REINT(ID).GT.0) THEN
          WWK=WW*ABST
          WWKA=WWK*ALIM1(ID)
          WWKC=WWK*ALIP1(ID)
          ABST=ABSO1(ID)-ELSCAT(ID)
          D0=ABST*ALI1(ID)
          FCOOLI(ID)=FCOOLI(ID)+WW*(EMIS1(ID)-ABST*RAD1(ID))
          REIN(ID)=REIN(ID)+WW*(D0*DSFN1+
     *             RAD1(ID)*(DABN1(ID)-SIGEC(IJ))-DEMN1(ID))
          DO II=1,NLVEXP
             REIP(II,ID)=REIP(II,ID)+WW*(D0*DSFP1(II)+
     *                   RAD1(ID)*DABP1(II,ID)-DEMP1(II,ID))
             AREIP(II,ID)=AREIP(II,ID)+WWKA*DSFP1M(II)
             CREIP(II,ID)=CREIP(II,ID)+WWKC*DSFP1P(II)
          END DO
          REIT(ID)=REIT(ID)+WW*(D0*DSFT1+
     *             RAD1(ID)*DABT1(ID)-DEMT1(ID))
          AREIT(ID)=AREIT(ID)+WWKA*DSFT1M
          AREIN(ID)=AREIN(ID)+WWKA*DSFN1M
          CREIT(ID)=CREIT(ID)+WWKC*DSFT1P
          CREIN(ID)=CREIN(ID)+WWKC*DSFN1P
        END IF

      END DO

C
c ****3. deepest point - ID=ND
c
      ID=ND

      LNSKIP=.NOT.LSKIP(ID,IJ)

      DSFTMM=DSFT1M
      DSFNMM=DSFN1M
      DO II=1,NLVEXP
        DSFPMM(II)=DSFP1M(II)
      END DO
      DSFT1M=DSFT1
      DSFN1M=DSFN1
      DO II=1,NLVEXP
        DSFP1M(II)=DSFP1(II)
      END DO
      S0=S0P
      DSFT1=DSFT1P
      DSFN1=DSFN1P
      DO II=1,NLVEXP
        DSFP1(II)=DSFP1P(II)
      END DO
C
C     Improved lower boundary condition
C
      DA=UN/(DELDMZ(ID-1)*(ABSOT(ID)+ABSOT(ID-1)))
      PLAD=XKFB(ID)/XKF1(ID)
      DBDT=PLAD/XKF1(ID)*HKT21(ID)*FREQ(IJ)*DA
      IF(IBC.GT.0.AND.IDISK.EQ.0) THEN
        IF(IBC.EQ.1) THEN
          DSFT1=DSFT1+DBDT
        ELSE IF(IBC.GE.2) THEN
          PLAM=XKFB(ID-1)/XKF1(ID-1)
          TAU23=T23*DA
          TAU43=T43*DA
          D0=(PLAD*(UN+TAU43)-T43*PLAM*DA)*DA*DA
          RHD=DELDMZ(ID-1)*DENSI(ID)
          E0=D0*RHD
          DSFT1=DSFT1+DBDT*(UN+TAU23)-E0*DABT1(ID)
          DSFN1=DSFN1-E0*(DABN1(ID)+ABSO1(ID)*DENSIM(ID))
          DO II=1,NLVEXP
            DSFP1(II)=DSFP1(II)-E0*DABP1(II,ID)
          END DO
          IF(IBC.GE.3) THEN
            DBDTM=PLAM/XKF1(ID-1)*HKT21(ID-1)*FREQ(IJ)*DA
            RHD=DELDMZ(ID-1)*DENSI(ID-1)
            E0=D0*RHD
            DSFT1D=-DBDTM*DA*T23-E0*DABT1(ID-1)
            DSFN1D=-E0*(DABN1(ID-1)+ABSO1(ID-1)*DENSIM(ID-1))
            DO II=1,NLVEXP
              DSFP1D(II)=-E0*DABP1(II,ID-1)
            END DO
          END IF
        END IF
      END IF
C
      IF(IRDER.EQ.1.OR.IRDER.EQ.3) THEN
        DSFDT(ID)=DSFT1*ALI1(ID)
        DSFDN(ID)=DSFN1*ALI1(ID)
        DSFDTM(ID)=DSFT1M*ALIM1(ID)
        DSFDNM(ID)=DSFN1M*ALIM1(ID)
        DSFDTP(ID)=DSFT1P*ALIP1(ID)
        DSFDNP(ID)=DSFN1P*ALIP1(ID)
      END IF
      IF(IRDER.GT.1) THEN
        DO II=1,NLVEXP
          DSFDP(II,ID)=DSFP1(II)*ALI1(ID)
          DSFDPM(II,ID)=DSFP1M(II)*ALIM1(ID)
          DSFDPP(II,ID)=DSFP1P(II)*ALIP1(ID)
        END DO
      END IF
c
c     Hydrostatic equilibrium equation
c
      IF(LNSKIP) THEN
        D0=WW*FAK1(ID)
        A0=WW*FAK1(ID-1)
        FPRD(ID)=FPRD(ID)+D0*RAD1(ID)-A0*RAD1(ID-1)
        E0=D0*ALIM1(ID)-A0*ALI1(ID-1)
        D0=D0*ALI1(ID)-A0*ALIP1(ID-1)
        HEIT(ID)=HEIT(ID)+D0*DSFT1
        HEIN(ID)=HEIN(ID)+D0*DSFN1
        HEITM(ID)=HEITM(ID)+E0*DSFT1M
        HEINM(ID)=HEINM(ID)+E0*DSFN1M
        DO II=1,NLVEXP
          HEIP(II,ID)=HEIP(II,ID)+D0*DSFP1(II)
          HEIPM(II,ID)=HEIPM(II,ID)+E0*DSFP1M(II)
        END DO
        IF(IBC.GE.3) THEN
          HEITM(ID)=HEITM(ID)-D0*DSFT1D
          HEINM(ID)=HEINM(ID)-D0*DSFN1D
          DO II=1,NLVEXP
            HEIPM(II,ID)=HEIPM(II,ID)-D0*DSFP1D(II)
          END DO
        END IF
      END IF
C
C     Differential equation part of radiative equilibrium
C
      DDT=UN/(ABSOT(ID)+ABSOT(ID-1))
      DA=DDT/DELDMZ(ID-1)
      FL=(RAD1(ID)*FAK1(ID)-RAD1(ID-1)*FAK1(ID-1))*DA
      FLFIX(ID)=FLFIX(ID)+WW*FL
      IF(REDIF(ID).GT.0) THEN
        D0=WW*FAK1(ID)*DA
        A0=WW*FAK1(ID-1)*DA
        D0M=D0*ALIM1(ID)-A0*ALI1(ID-1)
        D0P=D0*ALIP1(ID)
        D0=D0*ALI1(ID)-A0*ALIP1(ID-1)
        E0=WW*FL*DDT
        REDX(ID)=REDX(ID)+E0*ABSO1(ID)
        REDXM(ID)=REDXM(ID)+E0*ABSO1(ID-1)
        E0M=E0*DENSI(ID-1)
        E0=E0*DENSI(ID)
        REDT(ID)=REDT(ID)+D0*DSFT1-E0*DABT1(ID)
        REDTM(ID)=REDTM(ID)+D0M*DSFT1M-E0M*DABT1(ID-1)
        REDN(ID)=REDN(ID)+D0*DSFN1-E0*DABN1(ID)
        REDNM(ID)=REDNM(ID)+D0M*DSFN1M-E0M*DABN1(ID-1)
        DO II=1,NLVEXP
          REDP(II,ID)=REDP(II,ID)+D0*DSFP1(II)-E0*DABP1(II,ID)
          REDPM(II,ID)=REDPM(II,ID)+D0M*DSFP1M(II)-
     *                         E0M*DABP1(II,ID-1)
        END DO
        IF(IBC.GE.3) THEN
          REDTM(ID)=REDTM(ID)+D0*DSFT1D
          REDNM(ID)=REDNM(ID)+D0*DSFN1D
          DO II=1,NLVEXP
            REDPM(II,ID)=REDPM(II,ID)+D0*DSFP1D(II)
          END DO
        END IF
      END IF
c
C     Integral equation part of the radiative equilibrium
C
      IF(REINT(ID).GT.0) THEN
        ABST=ABSO1(ID)-ELSCAT(ID)
        WWKA=WW*ABST*ALIM1(ID)
        D0=ABST*ALI1(ID)
        FCOOLI(ID)=FCOOLI(ID)+WW*(EMIS1(ID)-ABST*RAD1(ID))
        REIN(ID)=REIN(ID)+WW*(D0*DSFN1+
     *                RAD1(ID)*(DABN1(ID)-SIGEC(IJ))-DEMN1(ID))
        DO II=1,NLVEXP
          REIP(II,ID)=REIP(II,ID)+WW*(D0*DSFP1(II)+
     *                   RAD1(ID)*DABP1(II,ID)-DEMP1(II,ID))
          AREIP(II,ID)=AREIP(II,ID)+WWKA*DSFP1M(II)
        END DO
        IF(IBC.EQ.0) THEN
          REIT(ID)=REIT(ID)+WW*(D0*DSFT1+
     *                  RAD1(ID)*DABT1(ID)-DEMT1(ID))
        ELSE
          REIT(ID)=REIT(ID)+WW*(D0*(DSFT1-DBDT)+E0*DABT1(ID)+
     *                  RAD1(ID)*DABT1(ID)-DEMT1(ID)+
     *                  ALI1(ID)/ABST*DBDT)
        END IF
        AREIT(ID)=AREIT(ID)+WWKA*DSFT1M
        AREIN(ID)=AREIN(ID)+WWKA*DSFN1M
      END IF

      RETURN
      END SUBROUTINE ALIFR3
C
C
C     ****************************************************************
C
C
      SUBROUTINE ALIFRK(IJ)
C     =====================
C
C     Simplified routine ALIFR1tfor a Kantorovich iteration
C
C     hydrostatic and radiative equilibrium quantities -
C     derivatives of the total heating and cooling rates in the
C     ALI points with respect to the
C     temperature, electron density, and populations
C
      use accura
      use alipar
      use atomic
      use basics
      use modelq

      implicit none

      INTEGER, INTENT(IN) :: IJ

      REAL(DP) :: WFL(MDEPTH)
      REAL(DP) :: ABST,DA,FL,WW,WF
      INTEGER  :: ID
      LOGICAL  :: LNSKIP
C
      if(ifali.le.1) return
      WW=WC(IJ)

c **** Special expressions for the first depth  -  id=1

      ID=1
      LNSKIP=.NOT.LSKIP(ID,IJ)
      WF=WW*(FH(IJ)*RAD1(ID)-HEXTRD(IJ)
     *  -emis1(id)/abso1(id)*q0(ij))
      IF(LNSKIP) FPRD(ID)=FPRD(ID)+WF*ABSO1(ID)
     *                   -ww*emis1(id)*q0(ij)
      FLFIX(ID)=FLFIX(ID)+WF
      FLRD(ID)=FLRD(ID)+W(IJ)*(FH(IJ)*RAD1(ID)-HEXTRD(IJ))
      IF(REINT(ID).GT.0) THEN
         ABST=ABSO1(ID)-SCAT1(ID)
         FCOOLI(ID)=FCOOLI(ID)+WW*(EMIS1(ID)-ABST*RAD1(ID))
      END IF

c     Loop over depths

      DO ID=2,ND
        LNSKIP=.NOT.LSKIP(ID,IJ)
        DA=UN/((ABSOT(ID)+ABSOT(ID-1))*DELDMZ(ID-1))
        FL=RAD1(ID)*FAK1(ID)-RAD1(ID-1)*FAK1(ID-1)
        WFL(ID)=WW*FL
        IF(LNSKIP) FPRD(ID)=FPRD(ID)+WFL(ID)
        FLFIX(ID)=FLFIX(ID)+WFL(ID)*DA
        FLRD(ID)=FLRD(ID)+FL*W(IJ)*DA
        IF(REINT(ID).GT.0) THEN
          ABST=ABSO1(ID)-SCAT1(ID)
          FCOOLI(ID)=FCOOLI(ID)+WW*(EMIS1(ID)-ABST*RAD1(ID))
        END IF
      END DO

      RETURN
      END SUBROUTINE ALIFRK
C     
C     
C     ****************************************************************
C 
C
      SUBROUTINE ALISK1
C     =================
C
C     Simplified routine ALIST1 for Kantorovich iteration
C
C     Evaluation of all nexcessary ALI parameters + radiative rates
C
      use accura
      use alipar
      use array1
      use atomic
      use basics
      use iterat
      use modelq
      use odfpar

      implicit none

      REAL(DP) :: RBNU(MDEPTH)

      REAL(DP) :: FR,W0,SG,SGW0,A1,A2,PRDR,PRDX,CROSS
      INTEGER  :: ID,IJ,IBFT,ITR,II,JJ,JC,ICDW,IMER,ILINT,IJ0,IJT,IJ1,
     *            IJE
      LOGICAL  :: LROSS
C
C     zero the rates and other quantities (subr. NULL)
C
      DO ID=1,ND
         FCOOLI(ID)=0.
         FLFIX(ID)=0.
         FPRD(ID)=0.
         FLRD(ID)=0.
         PRADT(ID)=0.
         PRADA(ID)=0.
         DO ITR=1,NTRANS
            RRU(ITR,ID)=0.
            RRD(ITR,ID)=0.
         END DO
      END DO
      PRD0=0.
C
      LROSS=NDRE.LE.0.AND.ITER.EQ.1.OR.LFIN
      IF(HMIX0.GT.0..or.nnewd.gt.0) LROSS=.TRUE.
      IF(LROSS) THEN
         DO ID=1,ND
            ABROSD(ID)=0.
            SUMDPL(ID)=0.
         END DO
      END IF
C
      FRLOOP: DO IJ=1,NFREQ
         IF(IJX(IJ).EQ.-1) CYCLE FRLOOP
         FR=FREQ(IJ)
         W0=W0E(IJ)
         CALL OPACF1(IJ)
         IF(IJEX(IJ).GT.0) THEN
            IJE=IJEX(IJ)
            DO ID=1,ND
               ABSOEX(IJE,ID)=ABSO1(ID)
               EMISEX(IJE,ID)=EMIS1(ID)
               SCATEX(IJE,ID)=SCAT1(ID)
            END DO
         END IF
         CALL RTEFR1(IJ)
         CALL ALIFRK(IJ)
         IF(LROSS) CALL ROSSTD(IJ)
         IF(IOPTAB.LT.0) CYCLE FRLOOP
C
C        ---------------------
C        Continuum transitions
C        ---------------------
C
         DLOOP: DO ID=1,ND
            RBNU(ID)=(RAD1(ID)+BNUE(IJ))*EXP(-HKT1(ID)*FR)
            DO IBFT=1,NTRANC
               ITR=ITRBF(IBFT)
               SG=CROSS(IBFT,IJ)
               IF(SG.LE.0.) CYCLE
               II=ILOW(ITR)
               JJ=IUP(ITR)
               IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
               JC=ITRA(JJ,II)
               ICDW=MCDW(ITR)
               IMER=IMRG(II)
               IF(IFWOP(II).GE.0) THEN
                 IF(ICDW.GE.1) SG=SG*DWF1(ICDW,ID)
               ELSE
                 SG=SGMG(IMER,ID)
               ENDIF
               SGW0=SG*W0
               RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
               RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
            END DO
         END DO DLOOP
C
C        ----------------
C        Line transitions
C        ----------------
C
         IF(IJLIN(IJ).GT.0) THEN
C
C        the "primary" line at the given frequency
C
            ITR=IJLIN(IJ)
            DO ID=1,ND
               SGW0=PRFLIN(ID,IJ)*W0
               RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
               RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
           END DO
         END IF
         IF(NLINES(IJ).LE.0) CYCLE FRLOOP
C
C        the "overlapping" lines at the given frequency
C
         LLOOP: DO ILINT=1,NLINES(IJ)
            ITR=ITRLIN(ILINT,IJ)
            if(linexp(itr)) CYCLE LLOOP
            IJ0=IFR0(ITR)
            DO IJT=IJ0,IFR1(ITR)
               IF(FREQ(IJT).LE.FR) THEN
                  IJ0=IJT
                  EXIT
               END IF
            END DO
            IJ1=IJ0-1
            A1=(FR-FREQ(IJ0))/(FREQ(IJ1)-FREQ(IJ0))*W0
            A2=W0-A1
            DO ID=1,ND
               SGW0=A1*PRFLIN(ID,IJ1)+A2*PRFLIN(ID,IJ0)
               RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
               RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
            END DO
         END DO LLOOP
      END DO FRLOOP
C
C     multiply some quantities by frequency-independent constants
C
      DO ID=1,ND
         FCOOL(ID)=REINT(ID)*FCOOLI(ID)-REDIF(ID)*FLFIX(ID)
      END DO
C
C     radiation pressure
C
      PRDX=1.
      PRDR=1.
      DO ID=1,ND
         PRADT(ID)=PRADT(ID)*PCK
         PRADA(ID)=PRADA(ID)*PCK
         if(prada(id).gt.0.) PRDR=PRADT(ID)/PRADA(ID)
         IF(PRDR.LT.PRDX) PRDX=PRDR
      END DO
      PRD0=PRD0/DENS1(1)*DM(1)*PCK
      IF(LFIN) WRITE(10,"(' PRAD MIN RATIO ',F10.6,I4)") PRDX,ITER
C
C     Rosseland mean opacity
C
      IF(LROSS) THEN
         DO ID=1,ND
            ABROSD(ID)=SUMDPL(ID)/(ABROSD(ID)*DENS(ID))
         END DO
      END IF
      RETURN
      END
C     
C     
C     ****************************************************************
C 
C
      SUBROUTINE ALISK2
C     =================
C
C     Simplified routine ALISET for Kantorovich iteration
C
C     Evaluation of all nexcessary ALI parameters + radiative rates
C     (the routine is analogous to RATES)
C
C
      use accura
      use alipar
      use array1
      use atomic
      use basics
      use iterat
      use modelq
      use odfpar

      implicit none

      REAL(DP) :: RBNU(MDEPTH)

      REAL(DP) :: FR,W0,SG,SGW0,A1,A2,PRDR,PRDX,CROSS
      INTEGER  :: II,ID,IJ,IBFT,ITR,JJ,JC,ICDW,IMER,
     *            ILINT,IJE,IJ0,IJT,IJ1,KJ,INDXPA,KJD
      LOGICAL  :: LROSS

C
C     zero the rates and other quantities
C
      DO ID=1,ND
         FCOOLI(ID)=0.
         FLFIX(ID)=0.
         FLEXP(ID)=0.
         FPRD(ID)=0.
         FLRD(ID)=0.
         PRADT(ID)=0.
         PRADA(ID)=0.
         DO ITR=1,NTRANS
            RRU(ITR,ID)=0.
            RRD(ITR,ID)=0.
         END DO
      END DO
      PRD0=0.
C
      LROSS=NDRE.LE.0.AND.ITER.EQ.1.OR.LFIN
      IF(HMIX0.GT.0..or.nnewd.gt.0) LROSS=.TRUE.
      IF(LROSS) THEN
         DO ID=1,ND
            ABROSD(ID)=0.
            SUMDPL(ID)=0.
         END DO
      END IF
C
      FRLOOP: DO IJ=1,NFREQ
         IF(IJX(IJ).EQ.-1) CYCLE FRLOOP
         FR=FREQ(IJ)
         W0=W0E(IJ)
         CALL OPACF1(IJ)
         CALL RTEFR1(IJ)
         CALL ALIFRK(IJ)
         IF(LROSS) CALL ROSSTD(IJ)
         if(ioptab.lt.0) CYCLE FRLOOP
         IF(IJEX(IJ).GT.0) THEN
            IJE=IJEX(IJ)
            DO ID=1,ND
               ABSOEX(IJE,ID)=ABSO1(ID)
               EMISEX(IJE,ID)=EMIS1(ID)
               SCATEX(IJE,ID)=SCAT1(ID)
            END DO
         END IF
C
C        ---------------------
C        Continuum transitions
C        ---------------------
C
         DO ID=1,ND
            RBNU(ID)=(RAD1(ID)+BNUE(IJ))*EXP(-HKT1(ID)*FR)
            DO IBFT=1,NTRANC
               ITR=ITRBF(IBFT)
               SG=CROSS(IBFT,IJ)
               IF(SG.LE.0.) CYCLE
               II=ILOW(ITR)
               JJ=IUP(ITR)
               IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
               JC=ITRA(JJ,II)
               IF(IFWOP(II).GE.0) THEN
                  ICDW=MCDW(ITR)
                  IF(ICDW.GE.1) SG=SG*DWF1(ICDW,ID)
                ELSE
                  IMER=IMRG(II)
                  SG=SGMG(IMER,ID)
               END IF
               SGW0=SG*W0
               RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
               RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
            END DO
         END DO
C
C        ----------------
C        Line transitions
C        ----------------
C
         IF(ISPODF.EQ.0) THEN
            IF(IJLIN(IJ).GT.0) THEN
C
C        the "primary" line at the given frequency
C
               ITR=IJLIN(IJ)
               II=ILOW(ITR)
               JJ=IUP(ITR)
               DO ID=1,ND
                  IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
                  SGW0=PRFLIN(ID,IJ)*W0
                  RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
                  RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
               END DO
            END IF
            IF(NLINES(IJ).LE.0) CYCLE FRLOOP
C
C        the "overlapping" lines at the given frequency
C
            LLOOP: DO ILINT=1,NLINES(IJ)
               ITR=ITRLIN(ILINT,IJ)
               if(linexp(itr)) CYCLE LLOOP
               II=ILOW(ITR)
               JJ=IUP(ITR)
               IJ0=IFR0(ITR)
               DO IJT=IJ0,IFR1(ITR)
                  IF(FREQ(IJT).LE.FR) THEN
                     IJ0=IJT
                     EXIT
                  END IF
               END DO
               IJ1=IJ0-1
               A1=(FR-FREQ(IJ0))/(FREQ(IJ1)-FREQ(IJ0))*W0
               A2=W0-A1
               DO ID=1,ND
                  IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
                  SGW0=A1*PRFLIN(ID,IJ1)+A2*PRFLIN(ID,IJ0)
                  RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
                  RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
               END DO
            END DO LLOOP
C
C        Opacity sampling option
C
         ELSE
            IF(NLINES(IJ).LE.0) CYCLE FRLOOP
            LLOOP2: DO ILINT=1,NLINES(IJ)
               ITR=ITRLIN(ILINT,IJ)
               KJ=IJ-IFR0(ITR)+KFR0(ITR)
               INDXPA=IABS(INDEXP(ITR))
               II=ILOW(ITR)
               JJ=IUP(ITR)
               IF(INDXPA.NE.3 .AND. INDXPA.NE.4) THEN
                  DO ID=1,ND
                     IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
                     SGW0=PRFLIN(ID,KJ)*W0
                     RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
                     RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
                  END DO
                ELSE
                  DO ID=1,ND
                     IF(IPZERO(II,ID).NE.0.OR.
     *               IPZERO(JJ,ID).NE.0) CYCLE
                     KJD=JIDI(ID)
                     SG=EXP(XJID(ID)*SIGFE(KJD,KJ)+(UN-XJID(ID))*
     *               SIGFE(KJD+1,KJ))
                     SGW0=SG*W0
                     RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
                     RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
                  END DO
               END IF
            END DO LLOOP2
         END IF
      END DO FRLOOP
C
C     multiply some quantities by frequency-independent constants
C
      DO ID=1,ND
         FCOOL(ID)=REINT(ID)*FCOOLI(ID)-REDIF(ID)*FLFIX(ID)
      END DO
C
C     radiation pressure
C
      PRDR=1.
      PRDX=1.
      DO ID=1,ND
         PRADT(ID)=PRADT(ID)*PCK
         PRADA(ID)=PRADA(ID)*PCK
         if(prada(id).gt.0.) PRDR=PRADT(ID)/PRADA(ID)
         IF(PRDR.LT.PRDX) PRDX=PRDR
      END DO
      PRD0=PRD0/DENS1(1)*DM(1)*PCK
      IF(LFIN) WRITE(10,"(' PRAD MIN RATIO ',F10.6,I4)") PRDX,ITER
C
C     Rosseland mean opacity
C
      IF(LROSS) THEN
         DO ID=1,ND
            ABROSD(ID)=SUMDPL(ID)/(ABROSD(ID)*DENS(ID))
         END DO
      END IF
      RETURN
      END
C     
C     
C     ****************************************************************
C 
C
      SUBROUTINE ALIST1
C     =================
C
C     Evaluation of all nexcessary ALI parameters + radiative rates
C     (the routine is analogous to RATES1)
C
C
      use accura
      use alipar
      use atomic
      use basics
      use iterat
      use modelq
      use odfpar

      implicit none 

      REAL(DP):: EXX(MDEPTH),RBNU(MDEPTH),RBNUF(MDEPTH)

      REAL(DP) :: FR,W0,SG,SGW0,A1,A2,PRDR,PRDX,CROSS
      INTEGER  :: ID,ITR,IJ,IBFT,II,JJ,JC,ICDW,IMER,ILINT,IJ0,IJT,IJ1,
     *            KJ,INDXPA,KJD,IE,JE
      LOGICAL  :: LROSS
C
C     zero the rates and other quantities
C
      DO ID=1,ND
         REIT(ID)=0.
         REIN(ID)=0.
         REIX(ID)=0.
         AREIT(ID)=0.
         AREIN(ID)=0.
         CREIT(ID)=0.
         CREIN(ID)=0.
         CREIX(ID)=0.
         REDT(ID)=0.
         REDTM(ID)=0.
         REDTP(ID)=0.
         REDN(ID)=0.
         REDNM(ID)=0.
         REDNP(ID)=0.
         REDX(ID)=0.
         REDXM(ID)=0.
         REDXP(ID)=0.
         HEIT(ID)=0.
         HEITM(ID)=0.
         HEITP(ID)=0.
         HEIN(ID)=0.
         HEINM(ID)=0.
         HEINP(ID)=0.
         EHET(ID)=0.
         EHEN(ID)=0.
         ERET(ID)=0.
         EREN(ID)=0.
         FCOOLI(ID)=0.
         FLFIX(ID)=0.
         FLEXP(ID)=0.
         FLRD(ID)=0.
         FPRD(ID)=0.
         PRADT(ID)=0.
         PRADA(ID)=0.
         DO II=1,NLVEXP
            HEIP(II,ID)=0.
            REIP(II,ID)=0.
            AREIP(II,ID)=0.
            CREIP(II,ID)=0.
            REDP(II,ID)=0.
            REDPM(II,ID)=0.
            HEIPM(II,ID)=0.
            REDPP(II,ID)=0.
            HEIPP(II,ID)=0.
            EHEP(II,ID)=0.
            EREP(II,ID)=0.
         END DO
         DO ITR=1,NTRANS
            RRU(ITR,ID)=0.
            RRD(ITR,ID)=0.
            DRDT(ITR,ID)=0.
         END DO
      END DO
      PRD0=0.
C
      LROSS=NDRE.LE.0.AND.ITER.EQ.1.OR.LFIN
      IF(HMIX0.GT.0..or.nnewd.gt.0) LROSS=.TRUE.
      IF(LROSS) THEN
         DO ID=1,ND
            ABROSD(ID)=0.
            SUMDPL(ID)=0.
         END DO
      END IF
C
      FRLOOP: DO IJ=1,NFREQ
         IF(IJX(IJ).EQ.-1) CYCLE FRLOOP
         FR=FREQ(IJ)
         W0=W0E(IJ)
         CALL OPACFD(IJ)
         CALL RTEFR1(IJ)
         CALL ALIFR1(IJ)
         IF(LROSS) CALL ROSSTD(IJ)
         if(ioptab.lt.0) CYCLE FRLOOP
C
C        ---------------------
C        Continuum transitions
C        ---------------------
C
         DO ID=1,ND
            EXX(ID)=EXP(-HKT1(ID)*FR)
            RBNU(ID)=(RAD1(ID)+BNUE(IJ))*EXX(ID)
            RBNUF(ID)=RBNU(ID)*FR*HKT21(ID)*EXX(ID)
            DO IBFT=1,NTRANC
               ITR=ITRBF(IBFT)
               SG=CROSS(IBFT,IJ)
               IF(SG.LE.0.) CYCLE
               II=ILOW(ITR)
               JJ=IUP(ITR)
               IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
               JC=ITRA(JJ,II)
               IF(IFWOP(II).GE.0) THEN
                 ICDW=MCDW(ITR)
                 IF(ICDW.GE.1) SG=SG*DWF1(ICDW,ID)
               ELSE
                 IMER=IMRG(II)
                 SG=SGMG(IMER,ID)
               ENDIF
               SGW0=SG*W0
               RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
               RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
               DRDT(ITR,ID)=DRDT(ITR,ID)+SGW0*RBNUF(ID)
            END DO
         END DO
C
C        ----------------
C        Line transitions
C        ----------------
C
         IF(ISPODF.EQ.0) THEN
            IF(IJLIN(IJ).GT.0) THEN
C
C        the "primary" line at the given frequency
C
               ITR=IJLIN(IJ)
               II=ILOW(ITR)
               JJ=IUP(ITR)
               DO ID=1,ND
                  IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
                  SGW0=PRFLIN(ID,IJ)*W0
                  RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
                  RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
C                 RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBLI(ID)
                  DRDT(ITR,ID)=DRDT(ITR,ID)+SGW0*RBNUF(ID)
               END DO
            ENDIF
            IF(NLINES(IJ).LE.0) CYCLE FRLOOP
C
C        the "overlapping" lines at the given frequency
C
            LLOOP: DO ILINT=1,NLINES(IJ)
               ITR=ITRLIN(ILINT,IJ)
               if(linexp(itr)) CYCLE LLOOP
               IJ0=IFR0(ITR)
               DO IJT=IJ0,IFR1(ITR)
                  IF(FREQ(IJT).LE.FR) THEN
                     IJ0=IJT
                     EXIT
                  END IF
               END DO
               IJ1=IJ0-1
               A1=(FR-FREQ(IJ0))/(FREQ(IJ1)-FREQ(IJ0))*W0
               A2=W0-A1
               II=ILOW(ITR)
               JJ=IUP(ITR)
               DO ID=1,ND
                  IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
                  SGW0=A1*PRFLIN(ID,IJ1)+A2*PRFLIN(ID,IJ0)
                  RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
                  RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
                  DRDT(ITR,ID)=DRDT(ITR,ID)+SGW0*RBNUF(ID)
               END DO
            END DO LLOOP
C
C     Opacity sampling option
C
         ELSE
            IF(NLINES(IJ).LE.0) CYCLE FRLOOP
            LLOOP2: DO ILINT=1,NLINES(IJ)
               ITR=ITRLIN(ILINT,IJ)
               II=ILOW(ITR)
               JJ=IUP(ITR)
               IE=IABS(IIEXP(II))
               JE=IABS(IIEXP(JJ))
               KJ=IJ-IFR0(ITR)+KFR0(ITR)
               INDXPA=IABS(INDEXP(ITR))
               IF(INDXPA.NE.3 .AND. INDXPA.NE.4) THEN
                  DO ID=1,ND
                     IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
                     SGW0=PRFLIN(ID,KJ)*W0
                     RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
                     RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
                     DRDT(ITR,ID)=DRDT(ITR,ID)+SGW0*RBNUF(ID)
                  END DO
               ELSE
                  DO ID=1,ND
                     IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
                     KJD=JIDI(ID)
                     SG=EXP(XJID(ID)*SIGFE(KJD,KJ)+
     *               (UN-XJID(ID))*SIGFE(KJD+1,KJ))
                     SGW0=SG*W0
                     RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
                     RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
                     DRDT(ITR,ID)=DRDT(ITR,ID)+SGW0*RBNUF(ID)
                  END DO
               END IF
            END DO LLOOP2
         END IF
      END DO FRLOOP
C
C     multiply some quantities by frequency-independent constants
C
      DO ID=1,ND
         REDX(ID)=REDX(ID)*WMM(ID)*DENS1(ID)*DENS1(ID)
         IF(ID.GT.1) REDXM(ID)=REDXM(ID)*WMM(ID)*
     *                         DENS1(ID-1)*DENS1(ID-1)
         FCOOL(ID)=REINT(ID)*FCOOLI(ID)-REDIF(ID)*FLFIX(ID)
      END DO
C
C     radiation pressure
C
      PRDX=1.
      PRDR=1.
      DO ID=1,ND
         PRADT(ID)=PRADT(ID)*PCK
         PRADA(ID)=PRADA(ID)*PCK
         if(prada(id).gt.0.) PRDR=PRADT(ID)/PRADA(ID)
         IF(PRDR.LT.PRDX) PRDX=PRDR
      END DO
      PRD0=PRD0/DENS1(1)*DM(1)*PCK
      IF(LFIN) WRITE(10,"(' PRAD MIN RATIO ',F10.6,I4)") PRDX,ITER
C
C     Rosseland mean opacity
C
      IF(LROSS) THEN
         DO ID=1,ND
            ABROSD(ID)=SUMDPL(ID)/(ABROSD(ID)*DENS(ID))
         END DO
         if(ioptab.lt.0.and.ifryb.gt.0) then
            do id=1,nd
               abrosd(id)=abrosd(id)*dens(id)
            end do
         end if
         call rosstd(0)
      END IF
c
      RETURN
      END SUBROUTINE ALIST1
C     
C     
C     ****************************************************************
C 
C
      SUBROUTINE ALIST2
C     =================
C
C     Evaluation of all nexcessary ALI parameters + radiative rates
C     (the routine is analogous to RATES1)
C     a variant for derivatives of the rate matrix w.r.t. populations
C
C
      use accura
      use alipar
      use array1
      use atomic
      use basics
      use iterat
      use modelq
      use odfpar

      implicit none 

      REAL(DP) ::  EXX(MDEPTH),RBNU(MDEPTH),RBNUF(MDEPTH)

      REAL(DP) :: FR,W0,SG,SGW0,SI,SJ,APFR,A1,A2,PRDR,PRDX,GRPR,CROSS
      INTEGER  :: II,ID,IJ,IBFT,ITR,JJ,JC,ICDW,IMER,IE,JE,NREFI,KK,
     *            ILINT,IJ0,IJT,IJ1,KJ,INDXPA,KJD
      LOGICAL  :: LROSS,LRDER
C
C     zero the rates and other quantities
C
      DO ID=1,ND
         REIT(ID)=0.
         REIN(ID)=0.
         REIX(ID)=0.
         AREIT(ID)=0.
         AREIN(ID)=0.
         CREIT(ID)=0.
         CREIN(ID)=0.
         CREIX(ID)=0.
         REDT(ID)=0.
         REDTM(ID)=0.
         REDTP(ID)=0.
         REDN(ID)=0.
         REDNM(ID)=0.
         REDNP(ID)=0.
         REDX(ID)=0.
         REDXM(ID)=0.
         REDXP(ID)=0.
         HEIT(ID)=0.
         HEITM(ID)=0.
         HEITP(ID)=0.
         HEIN(ID)=0.
         HEIm(ID)=0.
         HEINM(ID)=0.
         HEINP(ID)=0.
         EHET(ID)=0.
         EHEN(ID)=0.
         ERET(ID)=0.
         EREN(ID)=0.
         FCOOLI(ID)=0.
         FLFIX(ID)=0.
         FLEXP(ID)=0.
         FLRD(ID)=0.
         FPRD(ID)=0.
         PRADT(ID)=0.
         PRADA(ID)=0.
         DO II=1,NLVEXP
            HEIP(II,ID)=0.
            REIP(II,ID)=0.
            AREIP(II,ID)=0.
            CREIP(II,ID)=0.
            REDP(II,ID)=0.
            REDPM(II,ID)=0.
            HEIPM(II,ID)=0.
            REDPP(II,ID)=0.
            HEIPP(II,ID)=0.
            APT(II,ID)=0.
            APN(II,ID)=0.
            APM(II,ID)=0.
            AAPT(II,ID)=0.
            AAPN(II,ID)=0.
            AAPM(II,ID)=0.
            DO JJ=1,NLVEXP
               APP(JJ,II,ID)=0.
               AAPP(JJ,II,ID)=0.
CC             CAPP(JJ,II,ID)=0.
            END DO
         END DO
         DO ITR=1,NTRANS
            RRU(ITR,ID)=0.
            RRD(ITR,ID)=0.
            DRDT(ITR,ID)=0.
         END DO
      END DO
      PRD0=0.
C
      dedm1=dm(1)/dens(1)
!     IF (IRDER.EQ.3) THEN
C
      LROSS=NDRE.LE.0.AND.ITER.EQ.1.OR.LFIN
      IF(HMIX0.GT.0..or.nnewd.gt.0) LROSS=.TRUE.
      IF(LROSS) tHEN
         DO ID=1,ND
            ABROSD(ID)=0.
            SUMDPL(ID)=0.
         END DO
      END IF
C
      FRLOOP: DO IJ=1,NFREQ
         IF(IJX(IJ).EQ.-1) CYCLE FRLOOP
         FR=FREQ(IJ)
         W0=W0E(IJ)
         LRDER=IJALI(IJ).GT.0
         CALL OPACFD(IJ)
         CALL RTEFR1(IJ)
         CALL ALIFR1(IJ)
         IF(LROSS) CALL ROSSTD(IJ)
         if(ioptab.lt.0) CYCLE FRLOOP
C
C        ---------------------
C        Continuum transitions
C        ---------------------
C

c      write(6,"('RA00',4i4,1pe12.4)") ij,ijali(ij),ntranc,nd,fr
         DLOOP: DO ID=1,ND
            EXX(ID)=EXP(-HKT1(ID)*FR)
            RBNU(ID)=(RAD1(ID)+BNUE(IJ))*EXX(ID)
            RBNUF(ID)=RBNU(ID)*FR*HKT21(ID)
            TLOOP: DO IBFT=1,NTRANC
               ITR=ITRBF(IBFT)
               SG=CROSS(IBFT,IJ)
c       if(id.eq.39.and.ibft.eq.2) write(6,"('RA*',3i4,1pe12.4)") 
c       if(id.eq.39) write(6,"('RA*',3i4,1pe12.4)") 
c    *  ij,ibft,itr,sg
               IF(SG.LE.0.) CYCLE TLOOP
               II=ILOW(ITR)
               JJ=IUP(ITR)
               IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE TLOOP
               JC=ITRA(JJ,II)
               IF(IFWOP(II).GE.0) THEN
                  ICDW=MCDW(ITR)
                  IF(ICDW.GE.1) SG=SG*DWF1(ICDW,ID)
                ELSE
                  IMER=IMRG(II)
                  SG=SGMG(IMER,ID)
               ENDIF
               SGW0=SG*W0
               RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
               RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
               DRDT(ITR,ID)=DRDT(ITR,ID)+SGW0*RBNUF(ID)
c      if(id.eq.39.and.itr.eq.2) write(6,"('RAT',6i4,1p9e12.4)") 
c    *  ij,itr,ii,jj,ifwop(ii),icdw,fr,
c    *  sg,w0,rad1(id),rbnu(id),rbnuf(id),rru(itr,id),rrd(itr,id),
c    *  drdt(itr,id)
               IF(LRDER) THEN
                  SI=ABTRA(ITR,ID)
                  SJ=EMTRA(ITR,ID)
                  APFR=(SI-SJ*EXX(ID))*SGW0
                  IE=IABS(IIEXP(II))
                  JJ=IUP(ITR)
                  JE=IABS(IIEXP(JJ))
                  NREFI=NREFS(IATM(II),ID)
                  IF(IE.GT.0.AND.II.NE.NREFI.AND.ILTLEV(II).LE.0) THEN
                     APT(IE,ID)=APT(IE,ID)+APFR*DSFDT(ID)
                     APN(IE,ID)=APN(IE,ID)+APFR*DSFDN(ID)
                     DO KK=1,NLVEXP
                        APP(KK,IE,ID)=APP(KK,IE,ID)+APFR*DSFDP(KK,ID)
                     END DO
                     IF(ID.EQ.ND) THEN
                        APM(IE,ID)=APM(IE,ID)+APFR*DSFDM(ID)
                        AAPT(IE,ID)=AAPT(IE,ID)+APFR*DSFT1D
                        AAPN(IE,ID)=AAPN(IE,ID)+APFR*DSFN1D
                        AAPM(IE,ID)=AAPM(IE,ID)+APFR*DSFM1D
                        DO KK=1,NLVEXP
                           AAPP(KK,IE,ID)=AAPP(KK,IE,ID)+APFR*DSFP1D(KK)
                        END DO
                     END IF
                  END IF
                  IF(JE.GT.0.AND.JJ.NE.NREFI.AND.ILTLEV(JJ).LE.0.
     *                   AND.IABS(IMODL(II)).NE.4) THEN
                     APT(JE,ID)=APT(JE,ID)-APFR*DSFDT(ID)
                     APN(JE,ID)=APN(JE,ID)-APFR*DSFDN(ID)
                     DO KK=1,NLVEXP
                        APP(KK,JE,ID)=APP(KK,JE,ID)-APFR*DSFDP(KK,ID)
                     END DO
                     IF(ID.EQ.ND) THEN
                        APM(JE,ID)=APM(JE,ID)-APFR*DSFDM(ID)
                        AAPT(JE,ID)=AAPT(JE,ID)-APFR*DSFT1D
                        AAPN(JE,ID)=AAPN(JE,ID)-APFR*DSFN1D
                        AAPM(JE,ID)=AAPM(JE,ID)-APFR*DSFM1D
                        DO KK=1,NLVEXP
                           AAPP(KK,JE,ID)=AAPP(KK,JE,ID)-APFR*DSFP1D(KK)
                        END DO
                     END IF
                  END IF
               END IF
            END DO TLOOP
         END DO DLOOP
C
C        ----------------
C        Line transitions
C        ----------------
C
         IF(ISPODF.EQ.0) THEN
            IF(IJLIN(IJ).GT.0) THEN
C
C        the "primary" line at the given frequency
C
               ITR=IJLIN(IJ)
               II=ILOW(ITR)
               JJ=IUP(ITR)
               IE=IABS(IIEXP(II))
               JE=IABS(IIEXP(JJ))
               DO ID=1,ND
                  IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) CYCLE
                  IF(IE.EQ.JE) CYCLE
                  SGW0=PRFLIN(ID,IJ)*W0
                  RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
                  RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
                  DRDT(ITR,ID)=DRDT(ITR,ID)+SGW0*RBNUF(ID)
                  IF(LRDER) THEN
                     SI=ABTRA(ITR,ID)
                     SJ=EMTRA(ITR,ID)
                     APFR=(SI-SJ*EXX(ID))*SGW0
c                    APFR=(ABTRA(ITR,ID)-EMTRA(ITR,ID)*EXX(ID))*SGW0
                     NREFI=NREFS(IATM(II),ID)
                     IF(IE.GT.0.AND.II.NE.NREFI.AND.ILTLEV(II).LE.0) 
     *               THEN
                        APT(IE,ID)=APT(IE,ID)+APFR*DSFDT(ID)
                        APN(IE,ID)=APN(IE,ID)+APFR*DSFDN(ID)
                        DO KK=1,NLVEXP
                           APP(KK,IE,ID)=APP(KK,IE,ID)+
     *                     APFR*DSFDP(KK,ID)
                        END DO
                        IF(ID.EQ.ND) THEN
                           APM(IE,ID)=APM(IE,ID)+APFR*DSFDM(ID)
                           AAPT(IE,ID)=AAPT(IE,ID)+APFR*DSFT1D
                           AAPN(IE,ID)=AAPN(IE,ID)+APFR*DSFN1D
                           AAPM(IE,ID)=AAPM(IE,ID)+APFR*DSFM1D
                           DO KK=1,NLVEXP
                              AAPP(KK,IE,ID)=AAPP(KK,IE,ID)+
     *                        APFR*DSFP1D(KK)
                           END DO
                        END IF
                     END IF
                     IF(JE.GT.0.AND.JJ.NE.NREFI.AND.ILTLEV(JJ).LE.0.
     *                   AND.IABS(IMODL(II)).NE.4) THEN
                        APT(JE,ID)=APT(JE,ID)-APFR*DSFDT(ID)
                        APN(JE,ID)=APN(JE,ID)-APFR*DSFDN(ID)
                        DO KK=1,NLVEXP
                           APP(KK,JE,ID)=APP(KK,JE,ID)-
     *                     APFR*DSFDP(KK,ID)
                        END DO
                        IF(ID.EQ.ND) THEN
                           APM(JE,ID)=APM(JE,ID)-APFR*DSFDM(ID)
                           AAPT(JE,ID)=AAPT(JE,ID)-APFR*DSFT1D
                           AAPN(JE,ID)=AAPN(JE,ID)-APFR*DSFN1D
                           AAPM(JE,ID)=AAPM(JE,ID)-APFR*DSFM1D
                           DO KK=1,NLVEXP
                              AAPP(KK,JE,ID)=AAPP(KK,JE,ID)-
     *                        APFR*DSFP1D(KK)
                           END DO
                        END IF
                     END IF
                  END IF
               END DO
            END IF
            IF(NLINES(IJ).LE.0) CYCLE FRLOOP
C
C        the "overlapping" lines at the given frequency
C
            OLLOOP: DO ILINT=1,NLINES(IJ)
               ITR=ITRLIN(ILINT,IJ)
               if(linexp(itr)) CYCLE OLLOOP
               II=ILOW(ITR)
               JJ=IUP(ITR)
               IE=IABS(IIEXP(II))
               JE=IABS(IIEXP(JJ))
               IF(IE.EQ.JE) CYCLE OLLOOP
               IJ0=IFR0(ITR)
               DO IJT=IJ0,IFR1(ITR)
                  IF(FREQ(IJT).LE.FR) THEN
                     IJ0=IJT
                     EXIT
                  END IF
               END DO
               IJ1=IJ0-1
               A1=(FR-FREQ(IJ0))/(FREQ(IJ1)-FREQ(IJ0))*W0
               A2=W0-A1
               DELOOP: DO ID=1,ND
                  IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) 
     *            CYCLE DELOOP
                  SGW0=A1*PRFLIN(ID,IJ1)+A2*PRFLIN(ID,IJ0)
                  RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
                  RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
                  DRDT(ITR,ID)=DRDT(ITR,ID)+SGW0*RBNUF(ID)
                  IF(LRDER) THEN
                     SI=ABTRA(ITR,ID)
                     SJ=EMTRA(ITR,ID)
                     APFR=(SI-SJ*EXX(ID))*SGW0
                     NREFI=NREFS(IATM(II),ID)
                     IF(IE.GT.0.AND.II.NE.NREFI.AND.ILTLEV(II).LE.0) 
     *               THEN
                        APT(IE,ID)=APT(IE,ID)+APFR*DSFDT(ID)
                        APN(IE,ID)=APN(IE,ID)+APFR*DSFDN(ID)
                        DO KK=1,NLVEXP
                           APP(KK,IE,ID)=APP(KK,IE,ID)+
     *                     APFR*DSFDP(KK,ID)
                        END DO
                        IF(ID.EQ.ND) THEN
                        APM(IE,ID)=APM(IE,ID)+APFR*DSFDM(ID)
                        AAPT(IE,ID)=AAPT(IE,ID)+APFR*DSFT1D
                        AAPN(IE,ID)=AAPN(IE,ID)+APFR*DSFN1D
                        AAPM(IE,ID)=AAPM(IE,ID)+APFR*DSFM1D
                        DO KK=1,NLVEXP
                           AAPP(KK,IE,ID)=AAPP(KK,IE,ID)+
     *                     APFR*DSFP1D(KK)
                        END DO
                        END IF
                     END IF
                     IF(JE.GT.0.AND.JJ.NE.NREFI.AND.ILTLEV(JJ).LE.0.
     *                    AND.IABS(IMODL(II)).NE.4) THEN
                        APT(JE,ID)=APT(JE,ID)-APFR*DSFDT(ID)
                        APN(JE,ID)=APN(JE,ID)-APFR*DSFDN(ID)
                         DO KK=1,NLVEXP
                            APP(KK,JE,ID)=APP(KK,JE,ID)-
     *                      APFR*DSFDP(KK,ID)
                         END DO
                        IF(ID.EQ.ND) THEN
                        APM(JE,ID)=APM(JE,ID)-APFR*DSFDM(ID)
                        AAPT(JE,ID)=AAPT(JE,ID)-APFR*DSFT1D
                        AAPN(JE,ID)=AAPN(JE,ID)-APFR*DSFN1D
                        AAPM(JE,ID)=AAPM(JE,ID)-APFR*DSFM1D
                         DO KK=1,NLVEXP
                            AAPP(KK,JE,ID)=AAPP(KK,JE,ID)-
     *                      APFR*DSFP1D(KK)
                         END DO
                        END IF
                     END IF
                  END IF
               END DO DELOOP
            END DO OLLOOP
C
C     Opacity sampling option
C
         ELSE
            IF(NLINES(IJ).LE.0) CYCLE FRLOOP
            OLILOOP: DO ILINT=1,NLINES(IJ)
               ITR=ITRLIN(ILINT,IJ)
               II=ILOW(ITR)
               JJ=IUP(ITR)
               IE=IABS(IIEXP(II))
               JE=IABS(IIEXP(JJ))
               IF(IE.EQ.JE) CYCLE OLILOOP
               KJ=IJ-IFR0(ITR)+KFR0(ITR)
               INDXPA=IABS(INDEXP(ITR))
               IF(INDXPA.NE.3 .AND. INDXPA.NE.4) THEN
                  DDLOOP: DO ID=1,ND
                     IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) 
     *               CYCLE DDLOOP
                     SGW0=PRFLIN(ID,KJ)*W0
                     RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
                     RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
                     DRDT(ITR,ID)=DRDT(ITR,ID)+SGW0*RBNUF(ID)
                     IF(LRDER) THEN
                        SI=ABTRA(ITR,ID)
                        SJ=EMTRA(ITR,ID)
                        APFR=(SI-SJ*EXX(ID))*SGW0
                        NREFI=NREFS(IATM(II),ID)
                        IF(IE.GT.0.AND.II.NE.NREFI.AND.ILTLEV(II).LE.0)
     *                  THEN
                           APT(IE,ID)=APT(IE,ID)+APFR*DSFDT(ID)
                           APN(IE,ID)=APN(IE,ID)+APFR*DSFDN(ID)
                           DO KK=1,NLVEXP
                              APP(KK,IE,ID)=APP(KK,IE,ID)+
     *                        APFR*DSFDP(KK,ID)
                           END DO
                           IF(ID.EQ.ND) THEN
                              APM(IE,ID)=APM(IE,ID)+APFR*DSFDM(ID)
                              AAPT(IE,ID)=AAPT(IE,ID)+APFR*DSFT1D
                              AAPN(IE,ID)=AAPN(IE,ID)+APFR*DSFN1D
                              AAPM(IE,ID)=AAPM(IE,ID)+APFR*DSFM1D
                              DO KK=1,NLVEXP
                                 AAPP(KK,IE,ID)=AAPP(KK,IE,ID)+
     *                           APFR*DSFP1D(KK)
                              END DO
                           END IF
                        END IF
                        IF(JE.GT.0.AND.JJ.NE.NREFI.AND.ILTLEV(JJ).LE.0
     *                       .AND.IABS(IMODL(II)).NE.4) THEN
                           APT(JE,ID)=APT(JE,ID)-APFR*DSFDT(ID)
                           APN(JE,ID)=APN(JE,ID)-APFR*DSFDN(ID)
                           DO KK=1,NLVEXP
                              APP(KK,JE,ID)=APP(KK,JE,ID)-
     *                        APFR*DSFDP(KK,ID)
                           END DO
                           IF(ID.EQ.ND) THEN
                              APM(JE,ID)=APM(JE,ID)-APFR*DSFDM(ID)
                              AAPT(JE,ID)=AAPT(JE,ID)-APFR*DSFT1D
                              AAPN(JE,ID)=AAPN(JE,ID)-APFR*DSFN1D
                              AAPM(JE,ID)=AAPM(JE,ID)-APFR*DSFM1D
                              DO KK=1,NLVEXP
                                 AAPP(KK,JE,ID)=AAPP(KK,JE,ID)-
     *                           APFR*DSFP1D(KK)
                              END DO
                           END IF
                        END IF
                     END IF
                  END DO DDLOOP
               ELSE
                  DLOOP2: DO ID=1,ND
                     IF(IPZERO(II,ID).NE.0.OR.IPZERO(JJ,ID).NE.0) 
     *               CYCLE DLOOP2
                     KJD=JIDI(ID)
                     SG=EXP(XJID(ID)*SIGFE(KJD,KJ)+
     *               (UN-XJID(ID))*SIGFE(KJD+1,KJ))
                     SGW0=SG*W0
                     RRU(ITR,ID)=RRU(ITR,ID)+SGW0*RAD1(ID)
                     RRD(ITR,ID)=RRD(ITR,ID)+SGW0*RBNU(ID)
                     DRDT(ITR,ID)=DRDT(ITR,ID)+SGW0*RBNUF(ID)
                     IF(LRDER) THEN
                        SI=ABTRA(ITR,ID)
                        SJ=EMTRA(ITR,ID)
                        APFR=(SI-SJ*EXX(ID))*SGW0
C                       APFR=(ABTRA(ITR,ID)-EMTRA(ITR,ID)*EXX(ID))*SGW0
                        NREFI=NREFS(IATM(II),ID)
                        IF(IE.GT.0.AND.II.NE.NREFI.AND.ILTLEV(II).LE.0) 
     *                  THEN
                           APT(IE,ID)=APT(IE,ID)+APFR*DSFDT(ID)
                           APN(IE,ID)=APN(IE,ID)+APFR*DSFDN(ID)
                           DO KK=1,NLVEXP
                              APP(KK,IE,ID)=APP(KK,IE,ID)+
     *                        APFR*DSFDP(KK,ID)
                           END DO
                           IF(ID.EQ.ND) THEN
                              APM(IE,ID)=APM(IE,ID)+APFR*DSFDM(ID)
                              AAPT(IE,ID)=AAPT(IE,ID)+APFR*DSFT1D
                              AAPN(IE,ID)=AAPN(IE,ID)+APFR*DSFN1D
                              AAPM(IE,ID)=AAPM(IE,ID)+APFR*DSFM1D
                              DO KK=1,NLVEXP
                                 AAPP(KK,IE,ID)=AAPP(KK,IE,ID)+
     *                           APFR*DSFP1D(KK)
                              END DO
                           END IF
                        END IF
                        IF(JE.GT.0.AND.JJ.NE.NREFI.AND.ILTLEV(JJ).LE.0
     *                          .AND.IABS(IMODL(II)).NE.4) THEN
                           APT(JE,ID)=APT(JE,ID)-APFR*DSFDT(ID)
                           APN(JE,ID)=APN(JE,ID)-APFR*DSFDN(ID)
                           DO KK=1,NLVEXP
                              APP(KK,JE,ID)=APP(KK,JE,ID)-
     *                        APFR*DSFDP(KK,ID)
                           END DO
                           IF(ID.EQ.ND) THEN
                              APM(JE,ID)=APM(JE,ID)-APFR*DSFDM(ID)
                              AAPT(JE,ID)=AAPT(JE,ID)-APFR*DSFT1D
                              AAPN(JE,ID)=AAPN(JE,ID)-APFR*DSFN1D
                              AAPM(JE,ID)=AAPM(JE,ID)-APFR*DSFM1D
                              DO KK=1,NLVEXP
                                 AAPP(KK,JE,ID)=AAPP(KK,JE,ID)-
     *                           APFR*DSFP1D(KK)
                              END DO
                           END IF
                        END IF
                     END IF
                  END DO DLOOP2
               END IF
            END DO OLILOOP
         END IF
      END DO FRLOOP
C
C     multiply some quantities by frequency-independent constants
C
      DO ID=1,ND
        REDX(ID)=REDX(ID)*WMM(ID)*DENS1(ID)*DENS1(ID)
        IF(ID.GT.1) REDXM(ID)=REDXM(ID)*WMM(ID)*
     *                        DENS1(ID-1)*DENS1(ID-1)
        FCOOL(ID)=REINT(ID)*FCOOLI(ID)-REDIF(ID)*FLFIX(ID)
      END DO
C
C     radiation pressure
C
      PRDX=1.
      PRDR=1.
      DO ID=1,ND
         PRADT(ID)=PRADT(ID)*PCK
         PRADA(ID)=PRADA(ID)*PCK
         if(prada(id).gt.0.) PRDR=PRADT(ID)/PRADA(ID)
         IF(PRDR.LT.PRDX) PRDX=PRDR
       if(id.gt.1) grpr=(pradt(id)-pradt(id-1))/(dm(id)-dm(id-1))
      END DO
      PRD0=PRD0/DENS1(1)*DM(1)*PCK
      IF(LFIN) WRITE(10,"(' PRAD MIN RATIO ',F10.6,I4)") PRDX,ITER
C
C     Rosseland mean opacity
C
      IF(LROSS) THEN
         DO ID=1,ND
            ABROSD(ID)=SUMDPL(ID)/(ABROSD(ID)*DENS(ID))
         END DO
         if(ioptab.lt.0.and.ifryb.gt.0) then
            do id=1,nd
               abrosd(id)=abrosd(id)*dens(id)
            end do
         end if
         call rosstd(0)
      END IF
c
      RETURN
      END SUBROUTINE ALIST2
C
C
C     ****************************************************************
C
C
      SUBROUTINE CONVEC(ID,T,PTOT,PG,PRAD,ABROS,DELTA,FLXCNV,VCONV)
C     =============================================================
C
C     Determination of the mixing-lengths convective flux
C
C     Input:  T     - temperature
C             PTOT  - total pressure
C             PG    - gas pressure
C             PRAD  - radiation pressure
C             ABROS - Rosseland opacity (per gram)
C             DELTA - corresponding temperature gradient
C     Output: FLXCNV - convective flux (expressed as H, ie F/4/pi)
C             VCONV  - convective velocity
C
      use accura
      use basics
      use conveq
      use modelq, only : taurs,delmde

      implicit none
 
      REAL(DP), INTENT(IN)  :: T,PTOT,PRAD,PG,ABROS,DELTA
      REAL(DP), INTENT(OUT) :: FLXCNV,VCONV
      INTEGER, INTENT(IN)   :: ID

      REAL(DP) :: HMIX,TAUE,FAC,A,B,D,DLT 
C
      VCONV=0.
      FLXCNV=0.
      DLT=0.
      GRDADB=0.
      IF(HMIX0.LT.0.) RETURN
CC    IF(ID.LT.IDCONZ) RETURN
C
C     Thermodynamic derivatives
C
      if(ioptab.ge.-1) then
         TAUE=TAURS(ID)
!      write(*,*) 'CONVEC bef trmder,id,t,pg',id,t,pg
         CALL TRMDER(ID,T,PG,PRAD,TAUE)
!      write(*,"('conve0',i4,2f10.5)") id,grdadb,delta
       else
         call trmdrt(t,ptot)
      end if
      DDEL=DELTA-GRDADB
!                 write(*,"('con1',2i4,1p7e12.4)")
!    *            id,id,t,ptot,pg,prad,abros,delta,grdadb
C
C     Convective instability criterion
C
      IF(DDEL.LE.1.e-15) RETURN
      if(idisk.eq.0) then
         HSCALE=PTOT/RHOD/GRAV
       else
         if(gravd.eq.0.) return
         hscale=ptot/rhod/gravd
      end if
      HMIX=HMIX0
      if(hmix0.eq.0.) hmix=1.
      VCO=HMIX*SQRT(ABS(aconml*PTOT/RHOD*DLRDLT))
      FLCO=bconml*RHOD*HEATCP*T*HMIX/12.5664_dp
      TAUE=HMIX*ABROS*RHOD*HSCALE
      FAC=TAUE/(UN+HALF *TAUE*TAUE)
C
C     Set up parameters A and B (see Mihalas, Eq. 7-76, 7-79, etc)
C
      B=5.67e-5_dp*T**3/(rhod*heatcp*VCO)*FAC*cconml*half
      A=0.
      IF(FLXTOT.GT.0.) A=FLCO*VCO/FLXTOT*DELTA
C
C     Determination of   Delta - Delta(E)
C
      D=B*B*HALF
      DLT=D+DDEL-B*SQRT(D*HALF+DDEL)
      IF(DLT.LT.0.) DLT=0.
      ACNV=A
      BCNV=B
      DELMDE=DLT
C
C     Resulting convective velocity VCONV and flux FLXCNV
C
      VCONV=VCO*SQRT(DLT)
      FLXCNV=FLCO*VCONV*DLT

!!    write(*,"(73x,'convec',i4,4f10.3,1p4e10.2)") 
!!   * id,delta,grdadb,ddel,dlt,flco,vco,vconv,flxcnv


      RETURN
      END SUBROUTINE CONVEC
C
C
C     ****************************************************************
C
C
      SUBROUTINE CONVC1(ID,T,PTOT,PG,PRAD,ABROS,DELTA,FLXCNV,FC0)
C     ===========================================================
C
C     Determination of the mixing-lengths convective flux
C
C     Input:  T     - temperature
C             PTOT  - total pressure
C             PG    - gas pressure
C             PRAD  - radiation pressure
C             ABROS - Rosseland opacity (per gram)
C             DELTA - corresponding temperature gradient
C     Output: FLXCNV - convective flux (expressed as H, ie F/4/pi)
C             VCONV  - convective velocity
C
      use accura
      use basics
      use conveq
      use modelq, only : taurs

      implicit none
 
      REAL(DP), INTENT(IN)  :: T,PTOT,PG,PRAD,ABROS,DELTA
      REAL(DP), INTENT(OUT) :: FLXCNV,FC0
      INTEGER, INTENT(IN)   :: ID

      REAL(DP) :: HMIX,TAUE,FAC,A,B,D,DLT,VCONV
C
      VCONV=0.
      FLXCNV=0.
      DLT=0.
      IF(HMIX0.LT.0.) RETURN
CCC   IF(ID.LT.IDCONZ) RETURN
C
C     Thermodynamic derivatives
C
      if(ioptab.ge.-1) then
         TAUE=TAURS(ID)
         CALL TRMDER(ID,T,PG,PRAD,TAUE)
       else
         call trmdrt(t,ptot)
      end if
      DDEL=DELTA-GRDADB
C
C     Convective instability criterion
C
      if(idisk.eq.0) then
         HSCALE=PTOT/RHOD/GRAV
       else
         if(gravd.eq.0.) return
         hscale=ptot/rhod/gravd
      end if
      HMIX=HMIX0
      if(hmix0.eq.0.) hmix=1.
      VCO=HMIX*SQRT(ABS(aconml*PTOT/RHOD*DLRDLT))
      FLCO=bconml*RHOD*HEATCP*T*HMIX/12.5664_dp
      FC0=FLCO*VCO
      IF(DDEL.LT.0.) RETURN
c
      TAUE=HMIX*ABROS*RHOD*HSCALE
      FAC=TAUE/(UN+HALF *TAUE*TAUE)
C
C     Set up parameters A and B (see Mihalas, Eq. 7-76, 7-79, etc)
C
      B=5.67e-5_dp*T**3/(rhod*heatcp*VCO)*FAC*cconml*half
      A=0.
      IF(FLXTOT.GT.0.) A=FLCO*VCO/FLXTOT*DELTA
C
C     Determination of   Delta - Delta(E)
C
      D=B*B*HALF
      DLT=D+DDEL-B*SQRT(D*HALF+DDEL)
      IF(DLT.LT.0.) DLT=0.
!     ACNV=A
      BCNV=B
C
C     Resulting convective velocity VCONV and flux FLXCNV
C
      VCONV=VCO*SQRT(DLT)
      FLXCNV=FLCO*VCONV*DLT
      RETURN
      END SUBROUTINE CONVC1
C
C
C     ****************************************************************
C
C
      SUBROUTINE CONVEP(ID,T,PTOT,PG,PRAD,ABROS,DELTA,FLXCNV,VCONV)
C     =============================================================
C
C     Determination of the mixing-lengths convective flux
C
C     Input:  T     - temperature
C             PTOT  - total pressure
C             PG    - gas pressure
C             PRAD  - radiation pressure
C             ABROS - Rosseland opacity (per gram)
C             DELTA - corresponding temperature gradient
C     Output: FLXCNV - convective flux (expressed as H, ie F/4/pi)
C             VCONV  - convective velocity
C
      use accura
      use basics
      use conveq
      use modelq, only : taurs

      implicit none
 
      REAL(DP), INTENT(IN)  :: T,PTOT,PG,PRAD,ABROS,DELTA
      REAL(DP), INTENT(OUT) :: FLXCNV,VCONV
      INTEGER, INTENT(IN)   :: ID

      REAL(DP) :: HMIX,TAUE,FAC,B,D,DLT
C
      VCONV=0.
      FLXCNV=0.
      DLT=0.
      GRDADB=0.
      IF(HMIX0.LT.0.) RETURN
CCC   IF(ID.LT.IDCONZ) RETURN
C
C     Thermodynamic derivatives
C
      if(ioptab.ge.-1) then
         CALL TRMDEP(ID,T,PG,PRAD,TAURS(ID))
       else
         call trmdrt(t,ptot)
      end if
      DDEL=DELTA-GRDADB
C
C     Convective instability criterion
C
      IF(DDEL.LT.0.) RETURN
      if(idisk.eq.0) then
         HSCALE=PTOT/RHOD/GRAV
       else
         if(gravd.eq.0.) return
         hscale=ptot/rhod/gravd
      end if
      HMIX=HMIX0
      if(hmix0.eq.0.) hmix=1.
      VCO=HMIX*SQRT(ABS(aconml*PTOT/RHOD*DLRDLT))
      FLCO=bconml*RHOD*HEATCP*T*HMIX/12.5664_dp
      TAUE=HMIX*ABROS*RHOD*HSCALE
      FAC=TAUE/(UN+HALF *TAUE*TAUE)
C
C     Set up parameters A and B (see Mihalas, Eq. 7-76, 7-79, etc)
C
      B=5.67e-5_dp*T**3/(rhod*heatcp*VCO)*FAC*cconml*half
!     IF(FLXTOT.GT.0.) A=FLCO*VCO/FLXTOT*DELTA
C
C     Determination of   Delta - Delta(E)
C
      D=B*B*HALF
      DLT=D+DDEL-B*SQRT(D*HALF+DDEL)
      IF(DLT.LT.0.) DLT=0.
C
C     Resulting convective velocity VCONV and flux FLXCNV
C
      VCONV=VCO*SQRT(DLT)
      FLXCNV=FLCO*VCONV*DLT
      RETURN
      END SUBROUTINE CONVEP
C
C
C     ****************************************************************
C
C
      SUBROUTINE CONVDE(ID,T,PTOT,PG,PRAD,ABROS,DELTA,AD0,FLXCNV,VCONV)
C     =================================================================
C
C     Determination of the mixing-lengths convective flux
C
C     Input:  T     - temperature
C             PTOT  - total pressure
C             PG    - gas pressure
C             PRAD  - radiation pressure
C             ABROS - Rosseland opacity (per gram)
C             DELTA - corresponding temperature gradient
C     Output: FLXCNV - convective flux (expressed as H, ie F/4/pi)
C             VCONV  - convective velocity
C
      use accura
      use basics
      use conveq
      use modelq, only : taurs

      implicit none
 
      REAL(DP), INTENT(IN)  :: T,PTOT,PG,PRAD,ABROS,DELTA,AD0
      REAL(DP), INTENT(OUT) :: FLXCNV,VCONV
      INTEGER, INTENT(IN)   :: ID

      REAL(DP) :: HMIX,TAUE,FAC,B,D,DLT
C
      VCONV=0.
      FLXCNV=0.
      DLT=0.
      GRDADB=0.
      IF(HMIX0.LT.0.) RETURN
CCC   IF(ID.LT.IDCONZ) RETURN
C
C     Thermodynamic derivatives
C
      if(ioptab.ge.-1) then
         TAUE=TAURS(ID)
         CALL TRMDER(ID,T,PG,PRAD,TAUE)
       else
         call trmdrt(t,ptot)
      end if
      DDEL=DELTA-AD0
C
C     Convective instability criterion
C
      IF(DDEL.LT.0.) RETURN
      if(idisk.eq.0) then
         HSCALE=PTOT/RHOD/GRAV
       else
         if(gravd.eq.0.) return
         hscale=ptot/rhod/gravd
      end if
      HMIX=HMIX0
      if(hmix0.eq.0.) hmix=1.
      VCO=HMIX*SQRT(ABS(aconml*PTOT/RHOD*DLRDLT))
      FLCO=bconml*RHOD*HEATCP*T*HMIX/12.5664_dp
      TAUE=HMIX*ABROS*RHOD*HSCALE
      FAC=TAUE/(UN+HALF *TAUE*TAUE)
C
C     Set up parameters A and B (see Mihalas, Eq. 7-76, 7-79, etc)
C
      B=5.67e-5_dp*T**3/(rhod*heatcp*VCO)*FAC*cconml*half
!     IF(FLXTOT.GT.0.) A=FLCO*VCO/FLXTOT*DELTA
C
C     Determination of   Delta - Delta(E)
C
      D=B*B*HALF
      DLT=D+DDEL-B*SQRT(D*HALF+DDEL)
      IF(DLT.LT.0.) DLT=0.
C
C     Resulting convective velocity VCONV and flux FLXCNV
C
      VCONV=VCO*SQRT(DLT)
      FLXCNV=FLCO*VCONV*DLT
      RETURN
      END SUBROUTINE CONVDE
C
C
C     ****************************************************************
C
C
      SUBROUTINE CONTMD
C     =================
C
C     Auxiliary procedure for LTEGRD
C     Determination of temperature in convectively unstable layers
C     for disks.
C     This is done by solving the energy balance equation
C     F(rad)+F(conv)=F(mech), which yields a cubic equation for
C     the logarithmic temperature gradient
C
C
      use accura
      use alipar
      use atomic
      use basics
      use modelq
      use conveq

      implicit none
 
      REAL(DP) :: DELTR(MDEPTH),TEMPR(MDEPTH)
      INTEGER  :: ICON0(MDEPTH)

      REAL(DP), PARAMETER :: ERRT=1.e-3
      REAL(DP) :: FLXTO0,DPRAD,PRAD0,CHANTM,T,PTOT,PGAS,PTURB,PRAD,TM,
     *            PTOTM,PT0,DELR,TOLD,T0,PG0,PR0,AB0,DELTA0,FAC,
     *            DELT0,CHANT0,PGM,PRADM,P,DELTC,
     *            ABROS,ABPLA,OPROS,OPPLA,HR1,ABFLX,
     *            FLXCNV,VCON,RHO,RHOEOS
      INTEGER  :: ID,ICONIT,ICONBE,J
C
C     First, store the temperature(rad) and gradient Delta(rad) -
C     quantities for the  purely raditive equilibrium model
C
      write(*,*) 'contmd',nd,t4,flxto0
      T4=TEFF**4
      FLXTO0=SIG4P*T4
      DPRAD=1.891204931e-15*T4
      if(ifprad.eq.0) dprad=0.
      PRAD0=DPRAD/1.732
      DO ID=1,ND
         TEMPR(ID)=TEMP(ID)
         IF(ID.EQ.1) THEN
            DELTR(ID)=0.
          ELSE
            DELTR(ID)=
     *      (TEMP(ID)-TEMP(ID-1))/(PTOTAL(ID)-PTOTAL(ID-1))*
     *      (PTOTAL(ID)+PTOTAL(ID-1))/(TEMP(ID)+TEMP(ID-1))
         END IF
         write(*,"(i4,1p4e12.4)") id,tempr(id),ptotal(id),deltr(id)
      END DO
C
C     ------------------------------------------------------
C     Global iteration loop for calculating convective model
C     ------------------------------------------------------
C
      GLOB: DO ICONIT=1,NCONIT
         ICONBE=0
         HR1=FLXTO0*PCK*ABROSD(1)/QGRAV
         CHANTM=0.
         DEPID: DO ID=1,ND
CCC      DEPID: DO ID=IDCONZ,ND
            T=TEMP(ID)
            PTOT=PTOTAL(ID)
            PGAS=PGS(ID)
            PTURB=HALF*DENS(ID)*VTURB(ID)*VTURB(ID)
            PRAD=PRADT(ID)
            FLXTOT=FLXTO0*(UN-THETA(ID))
            GRAVD=ZD(ID)*QGRAV
            ICON0(ID)=0
C
            IF(ID.GT.1) THEN
               J=0
               IF(ICONIT.EQ.1) T=T-TEMPR(ID-1)+TEMP(ID-1)
               TM=TEMP(ID-1)
               IF(T.LT.0.) T=TM
               PGM=PGS(ID-1)
               PTOTM=PTOTAL(ID-1)
               PT0=HALF*(PTOT+PTOTM)
               DELR=DELTR(ID)
C
C        Inner iteration loop for determining temperature in the
C        conectively unstable layers
C
               INNER: DO J=1,5
                  TOLD=T
                  T0=HALF*(T+TM)
                  PG0=HALF*(PGAS+PGM)
                  PR0=HALF*(PRAD+PRADM)
                  AB0=HALF*(ABROSD(ID)+ABROSD(ID-1))
                  GRAVD=(ZD(ID)+ZD(ID-1))*HALF*QGRAV
                  CALL CONVEC(ID,T0,PT0,PG0,PR0,AB0,DELR,FLXCNV,VCON)
                  IF(FLXCNV.EQ.0.) EXIT INNER
                  ICON0(ID)=1
                  ICONBE=1
                  CALL CUBIC(DELTA0)
                  FAC=DELTA0*(PTOT-PTOTM)/(PTOT+PTOTM)
                  T=TM*(UN+FAC)/(UN-FAC)
                  IF(T.LT.TM) T=TM*1.001
                  IF(ABS(UN-T/TOLD).LT.ERRT) EXIT INNER
               END DO INNER
C
C     Store the final quantitites
C
            END IF
            IF(ID.GT.1.AND.ICON0(ID).EQ.0.AND.ICON0(ID-1).EQ.1)
     *         DELTC=DELT0
            DELT0=TEMP(ID)-T
            PRADT(ID)=PRADT(ID)*(T/TEMP(ID))**4
            DENS(ID)=DENS(ID)*(TEMP(ID)/T)
            IF(TEMP(ID).NE.0.) CHANT0=ABS((T-TEMP(ID))/TEMP(ID))
            IF(CHANT0.GT.CHANTM) CHANTM=CHANT0
            TEMP(ID)=T
            IF(ICONIT.GT.1.AND.ICON0(ID).EQ.0.AND.ICONBE.EQ.1)
     *         TEMP(ID)=T-DELTC
            PRADM=PRADT(ID)
         END DO DEPID
C
C     Diagnostic outprint
C
         IF(IPRING.EQ.2) THEN
            WRITE(6,"('CONVECTIVE FLUX: AT CONTMD, ITER=',I2/)") ICONIT
            CALL CONOUT(1,IPRING)
         END IF
C
C     2. New values of electron density and density
C
         CALL HESOL6
c        CALL HESOLV
C
         DO ID=1,ND
CCC      DO ID=IDCONZ,ND
            if(ioptab.ge.0) then
               CALL OPACF0(ID)
               CALL MEANOP(T,OPROS,OPPLA)
               ABROS=OPROS/DENS(ID)
               ABPLA=OPPLA/DENS(ID)
               if(abpla.lt.abpmin) abpla=abpmin
               ABFLX=ABROS
               ABPLAD(ID)=ABPLA
               ABROSD(ID)=ABROS
             else if(ioptab.eq.-1) then
               rho=dens(id)
               call meanopt(t,id,rho,opros,oppla)
               abrosd(id)=opros
               abplad(id)=oppla
               abros=opros
               abpla=oppla
             else
               temp(id)=t
               p=ptotal(id)
               rho=rhoeos(t,p)
               dens(id)=rho
               call meanopt(t,id,rho,opros,oppla)
               abrosd(id)=opros
               abplad(id)=oppla
               abros=opros
               abpla=oppla
            end if
         END DO

         IF(CHANTM.LT.ERRT) EXIT GLOB
      END DO GLOB
      RETURN
      END SUBROUTINE CONTMD
C
C
C     ****************************************************************
C
C
      SUBROUTINE CONTMP
C     =================
C
C     Auxiliary procedure for LTEGR
C     Determination of temperature in convectively unstable layers
C     This is done by solving the energy balance equation
C     F(rad)+F(conv)=F(mech), which yields a cubic equation for
C     the logarithmic temperature gradient
C
C
      use accura
      use alipar
      use atomic
      use basics
      use modelq
      use conveq

      implicit none
 
      REAL(DP) :: DELTR(MDEPTH),TEMPR(MDEPTH)
      INTEGER  :: ICON0(MDEPTH)
      REAL(DP), PARAMETER :: ERRT=1.e-3_dp

      REAL(DP) :: FLXTO0,DPRAD,PRAD0,CHANTM,T,PTOT,PGAS,PTURB,PRAD,TM,
     *            PTOTM,PT0,DELR,TOLD,T0,PG0,PR0,AB0,DELTA0,REFF,FAC,
     *            DELT0,CHANT0,PGM,PRADM,P,AN,ANE,ENRG,ENTT,RHO,RHOEOS,
     *            WM,ABROS,ABPLA,OPROS,OPPLA,PTOLD,DELTC,FLXCNV,VCON 
      INTEGER  :: ID,ICONIT,ICONBE,J,ITINT
C
C     First, store the temperature(rad) and gradient Delta(rad) -
C     quantities for the  purely raditive equilibrium model
C
      T4=TEFF**4
      FLXTO0=SIG4P*T4
      DPRAD=1.891204931e-15_dp*T4
      if(ifprad.eq.0) dprad=0.
C
      PRAD0=DPRAD/1.732_dp
      DO ID=1,ND
         TEMPR(ID)=TEMP(ID)
         IF(ID.EQ.1) THEN
            DELTR(ID)=0.
          ELSE
            if(ilgder.eq.0) then
               DELTR(ID)=
     *         (TEMP(ID)-TEMP(ID-1))/(PTOTAL(ID)-PTOTAL(ID-1))*
     *         (PTOTAL(ID)+PTOTAL(ID-1))/(TEMP(ID)+TEMP(ID-1))
              else
               DELTR(ID)=
     *         LOG(TEMP(ID)/TEMP(ID-1))/LOG(PTOTAL(ID)/PTOTAL(ID-1))
            end if
         END IF
!        write(*,"(a,i4,1p3e12.4)") 'con',
!    *   id,tempr(id),ptotal(id),deltr(id)
      END DO
C
C     ------------------------------------------------------
C     Global iteration loop for calculating convective model
C     ------------------------------------------------------
C
      GLOB: DO ICONIT=1,NCONIT
         ICONBE=0
         CHANTM=0.
         DO ID=1,ND
CCC      DO ID=IDCONZ,ND
            T=TEMP(ID)
            PTOT=PTOTAL(ID)
            PGAS=PGS(ID)
            PTURB=HALF*DENS(ID)*VTURB(ID)*VTURB(ID)
            PRAD=PRADT(ID)
            FLXTOT=FLXTO0
            IF(IDISK.EQ.1) THEN
               FLXTOT=FLXTO0*(UN-THETA(ID))
               GRAVD=ZD(ID)*QGRAV
            END IF
            ICON0(ID)=0
C
            IF(ID.GT.1) THEN
               J=0
               IF(ICONIT.EQ.1) T=T-TEMPR(ID-1)+TEMP(ID-1)
               TM=TEMP(ID-1)
               IF(T.LT.0.) T=TM
               PTOTM=PTOTAL(ID-1)
               if(ilgder.eq.0) then
                  PT0=HALF*(PTOT+PTOTM)
                else
                  pt0=sqrt(ptot*ptotm)
               end if
               DELR=DELTR(ID)
C
C        Inner iteration loop for determining temperature in the
C        conectively unstable layers
C
               INNER: DO
                  J=J+1
                  TOLD=T
                  if(ilgder.eq.0) then
                     T0=HALF*(T+TM)
                     PG0=HALF*(PGAS+PGM)
                     PR0=HALF*(PRAD+PRADM)
                     AB0=HALF*(ABROSD(ID)+ABROSD(ID-1))
                   else
                     t0=sqrt(t*tm)
                     pg0=sqrt(pgas*pgm)
                     pr0=sqrt(prad*pradm)
                     ab0=sqrt(abrosd(id)*abrosd(id-1))
                  end if
!                 write(*,"('con0',2i4,1p6e12.4)")
!    *            id,j,t0,pt0,pg0,pr0,ab0,delr
                  IF(ID.GE.ND-2.AND.ICONBE.EQ.0) EXIT INNER
                  CALL CONVEC(ID,T0,PT0,PG0,PR0,AB0,DELR,FLXCNV,VCON)
                  IF(FLXCNV.EQ.0..or.id.lt.idconz) EXIT INNER
                  ICON0(ID)=1
                  ICONBE=1
                  CALL CUBIC(DELTA0)
                  REFF=DELTA0/DELR
                  PRADT(ID)=PRADT(ID)*(T/TEMP(ID))**4
                  PGAS=PTOT-PRAD-PTURB
                  if(ilgder.eq.0) then
                     IF(REFF.GT.UN) REFF=UN
                     IF(REFF.LT.0.) REFF=0.
                     FAC=DELTA0*(PTOT-PTOTM)/(PTOT+PTOTM)
                     T=TM*(UN+FAC)/(UN-FAC)
                     IF(T.LT.TM) T=TM
                   else
                     T=TM*(PTOT/PTOTM)**DELTA0
                     IF(T.LT.TM) T=TM*1.0001_dp
                  end if
c      if(j.lt.20) write(60,"('conv',4i4,3f12.2,3f8.5,1p6e11.3)") 
c    * iconit,id,j,ilgder,told,t,tm,un-t/told,delta0,delr,ptot,ptotm,
c    * flxcnv,acnv,bcnv,rhod
                  IF(ABS(UN-T/TOLD).LT.ERRT.OR.J.GT.10) EXIT INNER
               END DO INNER
C
C     Store the final quantitites
C
               IF(ID.GT.1.AND.ICON0(ID).EQ.0.AND.ICON0(ID-1).EQ.1)
     *            DELTC=DELT0
            END IF
            DELT0=TEMP(ID)-T
            IF(TEMP(ID).NE.0.) CHANT0=ABS((T-TEMP(ID))/TEMP(ID))
            IF(CHANT0.GT.CHANTM) CHANTM=CHANT0
            TEMP(ID)=T
            IF(ICONIT.GT.1.AND.ICON0(ID).EQ.0.AND.ICONBE.EQ.1)
     *      TEMP(ID)=T-DELTC
            PGM=PGAS
            PRADM=PRAD
            PGS(ID)=PGAS
         END DO
C
C     Diagnostic outprint
C
         IF(IPRING.EQ.2) THEN
            WRITE(6,"(/' CONVECTIVE FLUX: AT CONTMP, ITER=',I2/)") 
     *         ICONIT
            CALL CONOUT(1,IPRING)
         END IF
C
C     2. New values of electron density, density, sound spped,
C        and mean opacities and optical depths
C
c
         ANEREL=ELEC(1)/(DENS(1)/WMM(1)+ELEC(1))
         DEPID: DO ID=1,ND
            T=TEMP(ID)
            P=PTOTAL(ID)
            INIITER: DO ITINT=1,5
               if(ioptab.ge.-1) then
                  AN=PGS(ID)/T/BOLK
                  CALL ELDENS(ID,T,AN,ANE,ENRG,ENTT,WM,1)
                  ELEC(ID)=ANE
                  DENS(ID)=WMM(ID)*(AN-ANE)
                  PHMOL(ID)=AHMOL
C
C     Corresponding LTE populations
C
                  if(ioptab.ge.0) then
                     CALL WNSTOR(ID)
                     CALL STEQEQ(ID,POP,1)
C
C        Evaluation of the Rosseland and Planck mean opacities
C
                     CALL OPACF0(ID)
                     CALL MEANOP(T,OPROS,OPPLA)
                     ABROS=OPROS/DENS(ID)
                     ABPLA=OPPLA/DENS(ID)
                   else
                     rho=dens(id)
                     call meanopt(t,id,rho,abros,abpla)
                     abrosd(id)=abros
                     abplad(id)=abpla
                  end if
                else
                  rho=rhoeos(t,p)
                  dens(id)=rho
                  call meanopt(t,id,rho,abros,abpla)
                  abrosd(id)=abros
                  abplad(id)=abpla
               end if
C
C        New values of the the column mass
C
               PTOLD=PTOTAL(ID)
               if(idisk.eq.0.and.ichanm.gt.0) then
                  IF(ID.EQ.1) THEN
                     DM(ID)=TAUROS(ID)/ABROS
                     PTOTAL(ID)=DM(ID)*GRAV+PRAD0
                   ELSE
                     DM(ID)=DM(ID-1)+(TAUROS(ID)-TAUROS(ID-1))/
     *                      HALF/(ABROSD(ID-1)+ABROS)
                     PTOTAL(ID)=DM(ID)*GRAV+PRAD0
                  END IF
C
C        Store the final quantitites
C
                  PTURB=HALF*DENS(ID)*VTURB(ID)*VTURB(ID)
                  PGS(ID)=PTOTAL(ID)-PRADT(ID)-PTURB
               end if
               ABROSD(ID)=ABROS
               ABPLAD(ID)=ABPLA
               IF((PTOTAL(ID)-PTOLD)/PTOLD.LT.1.e-3) CYCLE DEPID
               IF(ITINT.GT.5) THEN
                  WRITE(6,"('SLOW CONVERGENCE OF INTERNAL ITERATIONS',
     *          ' IN CONTMP: ID, PTOT(OLD), PTOT(NEW) ='/I3,1P2D10.2/)")
     *            ID,PTOLD,PTOTAL(ID)
                  CYCLE DEPID
                ELSE
                  CYCLE INIITER
               END IF
            END DO INIITER
         END DO DEPID
      END DO GLOB
      RETURN
      END SUBROUTINE CONTMP
C
C
C     ****************************************************************
C
C
      SUBROUTINE CONREF
C     =================
C
CC    use array1
      use basics
      use modelq
      use conveq

      implicit none
 
      integer  :: idcon(mdepth)
      real(dp) :: flxtt(mdepth),delta0(mdepth)

      REAL(DP) :: FLXTO0,DLTND,T,P,PG,PRAD,TM,PM,PGM,PRADM,FAC,T0,P0,
     *            PG0,PR0,AB0,DLT,THT,FCNV,TOR,DLT0,FC0,DLT1,TOLD,DLP,
     *            FF,DTT,ERFL,BEC,DELTAA,DLTP,T0P,DELE,DELEP,DTA,ALP,
     *            FLR,FLC,AN,ANE,ENRG,ENTT,WM,RHO,VL,BB,DELE3,
     *            FLXCN0,T1,PRAD0,PPD,FLXCNV,VCON,DELTAE
      INTEGER  :: ID,IGAP,IDD,IIC,ITRNCR,IFNDM1
CC    INTEGER, SAVE :: ICBEGP,ICENDP,ICBEG0,ICBEGD
      LOGICAL  :: LCREF

c     IF(ICONV.EQ.0.AND.INDL.EQ.0) RETURN
      IF(ICONV.EQ.0) RETURN
      lcref=iconre.gt.0.and.iter.le.iconre.and.iter.ge.iconrs
      FLXTO0=SIG4P*TEFF**4
      DLTND=DELTA(ND)
      IFNDM1=0
C
      ICBEG=0
      ICEND=0
      ICBEGP=0
      ICENDP=0
      DO ID=2,ND
         T=TEMP(ID)
         P=PTOTAL(ID)
         PG=PGS(ID)
         prad=pradt(id)
         TM=TEMP(ID-1)
         PM=PTOTAL(ID-1)
         PGM=PGS(ID-1)
         pradm=pradt(id-1)
         IF(ID.EQ.ND.AND.IFNDM1.EQ.1) THEN
            FAC=DLTND*(P-PM)/(P+PM)
            T=TM*(UN+FAC)/(UN-FAC)
         END IF
         if(ilgder.eq.0) then
            T0=HALF*(T+TM)
            P0=HALF*(P+PM)
            PG0=HALF*(PG+PGM)
            PR0=HALF*(PRAD+PRADM)
            AB0=HALF*(ABROSD(ID)+ABROSD(ID-1))
            DLT=(T-TM)/(P-PM)*P0/T0
          else
            T0=SQRT(T*TM)
            P0=SQRT(P*PM)
            PG0=SQRT(PG*PGM)
            PR0=SQRT(PRAD*PRADM)
            AB0=SQRT(ABROSD(ID)*ABROSD(ID-1))
            DLT=LOG(T/TM)/LOG(P/PM)
         end if
         DELTA(ID)=DLT
         if(idisk.eq.0) then
            flxtot=flxto0
            gravd=grav
          else
            if(id.gt.1) tht=(thetav(id)+thetav(id-1))*half
            flxtot=flxto0*(1.d0-tht)
            gravd=qgrav*(zd(id)+zd(id-1))*half
         end if
         flxtt(id)=flxtot
C
C        convective flux
C
c         write(*,*) 'CONREF id,t0,p0',id,t0,p0,p,pradt(id),pgs0(id)
         CALL CONVEC(ID,T0,P0,PG0,PR0,AB0,DLT,FLXCNV,VCON)
         FLXC(ID)=FLXCNV
         idcon(id)=0
         if(flxc(id).gt.0.) idcon(id)=1
         IF(ICBEG.EQ.0.AND.FLXC(ID).GT.0..AND.FLXC(ID-1).EQ.0..
     *      AND.ID.GT.IDCONZ) ICBEG=ID
         if(icbeg.gt.0.and.flxc(id).gt.0.) icend=id
c        if(icbeg.gt.0.and.flxc(id).eq.0) lcref=.true.
      END DO
      if(icbeg.gt.0.and.iter.ge.iconrs) then
         do id=icbeg,icend
            if(flxc(id).eq.0) lcref=.true.
         end do
      end if
      if(.not.lcref) return
C
c     correction algorithm - if in the convetion zone one has
c     some depth point have gradient slightly smaller that the
c     adaibatic gradient, recompute gradients to have convection there.
C     in this case, the radiation flux is held fixed
c
c
      icbeg0=icbeg
      if(ideepc.gt.0) then
         if(icend.eq.nd-1.and.ideepc.eq.2) icend=nd
         icbegd=icend
         do id=icend,icbeg,-1
            if(idcon(id).gt.0) then
               icbegd=id
             else
               igap=0
               do idd=id-1,id-ndcgap,-1
                  if(idcon(idd).gt.0) igap=1
               end do
               if(igap.gt.0) then
                  icbegd=id
                else
                  exit
               end if
            end if
         end do
         icbeg0=icbegd
      end if
c
      if(ideepc.eq.3) icend=nd
      if(ideepc.ge.4) then
         if(icend.le.icbegp) then
            icbeg0=icbegp
            icend=icendp
         end if
      end if
      icbegp=icbeg0
      icendp=icend
c
      if(icbeg0.le.0.or.icend.le.0) return
      write(6,"(/' convective refinement in ITER=',i3,
     *        '  between depths ',2i4/)") iter-1,icbeg0,icend
c
c     check the temperature at the depth just above the base of
c     convection zone; if there is an oscillation there, re-adjust
c     the temperature
c
      if(temp(icbeg0-1).lt.temp(icbeg0-2).and.
     *   temp(icbeg0-1).lt.temp(icbeg0)) then
         temp(icbeg0-1)=half*(temp(icbeg0)+temp(icbeg0-2))
      end if
c

      write(6,"('  id iic    tor      t        flxtot     flrd ',
     * '   flrd/flxtot     p0        pg0        pr0        ab0',
     * '        rhod  flxcn0/flxtot   deltae    deltaa      dlt',
     * '       grdadb'/)")    

      depid: do id=icbeg0,icend
         T=TEMP(ID)
         if(idisk.eq.0) then
            flxtot=flxto0
            gravd=grav
          else
            tht=(thetav(id)+thetav(id-1))*half
            flxtot=flxto0*(1.d0-tht)
            gravd=qgrav*(zd(id)+zd(id-1))*half
         end if
         if(flrd(id).gt.flxtot) cycle depid
c        if(flrd(id).gt.flxtot) then
c           t=temp(id)*(0.999*flxtot/flrd(id))**0.25
c           flrd(id)=0.999*flxtot
c        end if
c
         P=PTOTAL(ID)
         PG=PGS(ID)
         prad=pradt(id)
         TM=TEMP(ID-1)
         PM=PTOTAL(ID-1)
         PGM=PGS(ID-1)
         pradm=pradt(id-1)
         ppd=(p+pm)/(p-pm)
         if(ilgder.eq.0) then
            P0=HALF*(P+PM)
            T0=HALF*(T+TM)
            PG0=HALF*(PG+PGM)
            PR0=HALF*(PRAD+PRADM)
            AB0=HALF*(ABROSD(ID)+ABROSD(ID-1))
            DLT=(T-TM)/(P-PM)*P0/T0
!           ppd=(p+pm)/(p-pm)
          else
            T0=SQRT(T*TM)
            P0=SQRT(P*PM)
            PG0=SQRT(PG*PGM)
            PR0=SQRT(PRAD*PRADM)
            AB0=SQRT(ABROSD(ID)*ABROSD(ID-1))
            DLT=LOG(T/TM)/LOG(P/PM)
         end if
         fcnv=flxtot-flrd(id)
         tor=t
         if(fcnv.le.0..and.idisk.eq.0) fcnv=flxtot*(un-flrd(id)/flrd(2))
         if(fcnv.lt.0..and.idisk.ne.0) fcnv=0.001*flxtot
c
c        iteration loop to correct temperature
c
         do iic=1,10
            if(ilgder.eq.0) then
               T0=HALF*(T+TM)
               AB0=HALF*(ABROSD(ID)+ABROSD(ID-1))
               DLT=(T-TM)/(P-PM)*P0/T0
             else
               T0=SQRT(T*TM)
               AB0=SQRT(ABROSD(ID)*ABROSD(ID-1))
               DLT=LOG(T/TM)/LOG(P/PM)
            end if
            dlt0=dlt
            DELTA(ID)=DLT
            if(flxc(id)/flxtot.ge.crflim) then
               CALL CONVC1(ID,T0,P0,PG0,PR0,AB0,DLT,FLXCNV,FC0)
               deltae=(fcnv/fc0)**0.666666666666667
               deltaa=deltae+bcnv*sqrt(deltae)
               dlt=deltaa+grdadb
            end if
            dlt1=dlt
            told=t
            if(ilgder.eq.0) then
               dlp=dlt/ppd
               t=tm*(un+dlp)/(un-dlp)
             else
               t=tm*(P/PM)**DLT
            end if
            flxcnv=fc0*deltae**1.5
            ff=flxcnv/flxtot
            dtt=(t-told)/told
            erfl=(flrd(id)+flxcnv)/flxtot
            if(ilgder.eq.0) then
               T0=HALF*(T+TM)
               DLT=(T-TM)/(P-PM)*P0/T0
             else
               T0=SQRT(T*TM)
               DLT=LOG(T/TM)/LOG(P/PM)
            end if
            CALL CONVEC(ID,T0,P0,PG0,PR0,AB0,DLT,FLXCN0,VCON)
            erfl=(flrd(id)+flxcn0)/flxtot
            if(abs(dtt).le.1.e-9) exit
         end do

         delta(id)=dlt
         temp(id)=t
         write(6,"(2i4,2f9.1,1p13e11.2)") 
     *      id,iic,tor,t,flxtot,flrd(id),flrd(id)/flxtot,
     *      p0,pg0,pr0,ab0,rhod,
     *      flxcn0/flxtot,deltae,deltaa,dlt,grdadb
      end do depid
c
c     new refinement procedure
c
c      write(*,*) 'iter,imucon',iter,imucon,icbeg,icend
      if(iter.ge.imucon) then
         icbeg0=icbeg
         icend=nd
         icendp=nd
         write(6,"(/' modification with imucon: icbeg0,icend',3i4)")
     *   imucon,icbeg0,icend
         write(6,"(/' new refinement procedure: icbeg0, icend ',2i4/
     *   ' entries are: id,itrc,t,dlt,grdadb,flrd/ft,flr/ft,fcn0/ft,
     *   (fcn0+flr)/ft'/)") icbeg0,icend

         do id=icbeg0,icend
            t=temp(id)
            p=ptotal(id)
            tm=temp(id-1)
            pm=ptotal(id-1)
            PG=PGS(ID)
            PRAD=PRADT(ID)
            PGM=PGS(ID)
            PRADM=PRADT(ID-1)
            pg0=sqrt(pg*pgm)
            pr0=sqrt(prad*pradm)
            told=t
            fcnv=flxtt(id)-flrd(id)
            t0=sqrt(t*tm)
            p0=sqrt(p*pm)
            ab0=sqrt(abrosd(id)*abrosd(id-1))
            dlt=log(t/tm)/log(p/pm)
            if(idisk.eq.0) then
               flxtot=flxto0
               gravd=grav
             else
               tht=(thetav(id)+thetav(id-1))*half
               flxtot=flxto0*(1.d0-tht)
               gravd=qgrav*(zd(id)+zd(id-1))*half
            end if
            call convc1(id,t0,p0,pg0,prad0,ab0,dlt,flxcn0,fc0)
            alp=min(flrd(id),flxtt(id))/t0**4/dlt
c
            if(fcnv.gt.0..and.flxcn0.gt.0.) then
               BEC=bcnv/t0**3
               deltae=(fcnv/fc0)**0.6666667
               deltaa=deltae+bcnv*sqrt(deltae)
               dlt=deltaa+grdadb
               t=tm*(P/PM)**DLT
               t0=sqrt(t*tm)
 
               do itrncr=1,20
                  t1=un/t
                  dltp=t1/log(p/pm)
                  t0p=half*t0*t1
                  dele=(flxtt(id)-alp*t0**4*dlt)/fc0
                  dele3= dele**0.33333333
                  delep=-alp*t0**4*dlt/fc0*(two*t1+dltp/dlt)
                  vl=dlt-grdadb-dele3*(dele3+BEC*t0**3)
                  bb=dltp-0.6666667*delep/dele3-
     *               BEC*t0**3*dele3*(1.5*t1+delep/dele/3.)
                  dta=-vl/bb*t1
                  t=t*(un+dta)
                  t0=sqrt(t*tm)
                  dlt=log(t/tm)/log(p/pm)
                  call convc1(id,t0,p0,pg0,prad0,ab0,dlt,flxcn0,fc0)
                  if(abs(dta).lt.1.e-9.or.itrncr.gt.20) exit
               end do
c
            else
               if(flxtt(id).lt.flrd(id)) then
                  alp=flxtt(id)/flrd(id)*t0**4*delta0(id)
                  do itrncr=1,20
                     t1=un/t
                     dltp=t1/log(p/pm)
                     t0p=half*t0*t1
                     dele=alp-t0**4*dlt
                     delep=-t0**4*dlt*(two*t1+dltp/dlt)
                     dta=-dele/delep*t1
                     t=t*(un+dta)
                     write(6,"(2i4,1pe11.3,0pf8.2,1p3e13.5)") 
     *               id,itrncr,dta,t
                     if(abs(dta).lt.1.e-6) exit
                     t0=sqrt(t*tm)
                     dlt=log(t/tm)/log(p/pm)
                  end do
                  alp=flrd(id)/t0**4/dlt
               end if
            end if

            delta(id)=dlt
            temp(id)=t
            flr=alp*t0**4*dlt
            if(dlt.ge.grdadb) then
               flc=fc0*dele
               write(6,"(2i4,f8.1,1p7e12.4)") 
     *           id,itrncr,t,dlt,grdadb,flrd(id)/flxtt(id),
     *           flr/flxtt(id),flc/flxtt(id),flxcn0/flxtt(id),
     *           (flr+flxcn0)/flxtt(id)
             else
               itrncr=0
               write(6,"(2i4,f8.1,1p7e12.4)") 
     *         id,itrncr,t,dlt,grdadb,flrd(id)/flxtt(id),flr/flxtt(id)
            end if
         end do
      end if

      write(*,*) 'after imucon iterations'
c
      if(ioptab.ge.-1.and.ifryb.gt.0) then
         do id=1,nd
            t=temp(id)
            an=pgs(id)/bolk/t
c          write(*,*) 'contref before eldens',id,t,an
            CALL ELDENS(ID,T,AN,ANE,ENRG,ENTT,WM,1)
c          write(*,*) 'after eldens',ane,wm
            RHO=WMM(ID)*(AN-ANE)
            DENS(ID)=RHO
            ELEC(ID)=ANE
            CALL WNSTOR(ID)
c         write(*,*) 'conref before steqeq'
            CALL STEQEQ(ID,POP,1)
          if(id.eq.2) write(*,"(/'POPUL end refin',1p7e12.4/)")
     *     popul(1,id),popul(17,id),an,ane,sbf(id),pgs(id),dens(id)
         END DO
c
c     write(*,*) 'end do loop'
      call tdpini
      ipconf=1
c     write(*,*) 'after tdpini',ipconf
      call conout(1,ipconf)
       write(*,*) 'after conout'
      end if
c
      return
      end subroutine conref
C
C
C     ****************************************************************
C
C
      SUBROUTINE CONOUT(IMOD,IPRIN)
C     =============================
C
C     Diagnostic outprint of temperature gradients, convective flux,
C     and their derivatives
C
      use accura
CC    use alipar
      use basics
      use modelq
      use conveq

      implicit none
 
      INTEGER, INTENT(IN) :: IMOD,IPRIN
      REAL(DP) :: FLXTO0,T,PTOT,PG,PRAD,FLXCR,TM,TAU,PTOTM,PGM,PRADM,
     *            T0,PT0,PG0,PR0,AB0,DLT,PRADR,CONREL,RADREL,
     *            THT,OPROS,OPPLA,FLXCNV,VCON,TAUM
      INTEGER  :: ID,NDREC
 
       write(*,*) 'conout imod,iprin',imod,iprin
      IF(IPRIN.GT.0) WRITE(6,"(//'  ID',3X,' DM ',7X,'TEMP',6X,
     *  'DELTA',2X,'DELTA(AD)',2X,'CON/TOT  RAD/TOT  (C+R)/TOT'//)")
      ANEREL=ELEC(1)/(DENS(1)/WMM(1)+ELEC(1))
      ICBEG=0
      FLXTO0=SIG4P*TEFF**4
      DO ID=1,ND
CCC   DO ID=IDCONZ,ND
         FLXCR=0.
         GRDADB=0.
         DELTA(ID)=0.
         FLXC(ID)=0.
         FLXCNV=0.
         T=TEMP(ID)
         PTOT=PTOTAL(ID)
         PG=PGS(ID)
         prad=pradt(id)
         if(prad.lt.0.) prad=0.
c      write(*,*) 'conout1',id,t,ptot,pg,prad
         IF(IMOD.EQ.2) THEN
            if(ioptab.ge.0) then
               CALL OPACF0(ID)
               CALL MEANOP(T,OPROS,OPPLA)
               ABROSD(ID)=OPROS/DENS(ID)
             else
               call meanopt(t,id,dens(id),opros,oppla)
               if(hmix0.gt.0.) abrosd(id)=opros
            end if
c       write(*,"('conout2',i4,1p2e10.2)") id,opros,abrosd(id)
         END IF
         FLXTOT=flxto0
         if(idisk.eq.1) then
            if(id.gt.1) tht=(thetav(id)+thetav(id-1))*half
            flxtot=flxto0*(un-tht)
            gravd=(zd(id)+zd(id-1))*half*qgrav
            prad=pradt(id)
         end if
         IF(ID.EQ.1) THEN
            TAU=DM(ID)*ABROSD(ID)
            FLXCR=0.
            GRDADB=0.
            DELTA(ID)=0.
            FLXC(ID)=0.
            FLXCNV=0.
          ELSE
            TM=TEMP(ID-1)
            TAU=TAUM+HALF*(DM(ID)-DM(ID-1))*(ABROSD(ID)+ABROSD(ID-1))
            PTOTM=PTOTAL(ID-1)
            PGM=PGS(ID-1)
            PRADM=PTOTM-PGM-HALF*DENS(ID-1)*VTURB(ID-1)**2
            if(idisk.eq.1) pradm=pradt(id-1)
            if(pradm.lt.0.) pradm=0.
            if(idisk.ge.1) gravd=(zd(id)+zd(id-1))*half*qgrav
            if(ilgder.eq.0) then
               T0=HALF*(T+TM)
               PT0=HALF*(PTOT+PTOTM)
               PG0=HALF*(PG+PGM)
               PR0=HALF*(PRAD+PRADM)
               AB0=HALF*(ABROSD(ID)+ABROSD(ID-1))
               DLT=(T-TM)/(PTOT-PTOTM)*PT0/T0
             else
               T0=SQRT(T*TM)
               PT0=SQRT(PTOT*PTOTM)
               PG0=SQRT(PG*PGM)
               PR0=SQRT(PRAD*PRADM)
               AB0=SQRT(ABROSD(ID)*ABROSD(ID-1))
               DLT=LOG(T/TM)/LOG(PTOT/PTOTM)
            end if
            DELTA(ID)=DLT
            flxcnv=0.
c           write(*,"(73x,'conout3',i4,f10.1,1p7e10.2)")
c    *      id,t0,pt0,pg0,pr0,ab0,dlt
            if((idisk.ge.0.or.id.lt.nd).and.id.gt.idconz)
     *      CALL CONVEC(ID,T0,PT0,PG0,PR0,AB0,DLT,FLXCNV,VCON)
c           write(*,"(73x,'conout4',i4,f10.3,1pe10.2)") id,dlt,flxcnv
            if(hmix0.gt.0.) FLXC(ID)=FLXCNV
            IF(ICBEG.EQ.0.AND.FLXC(ID).GT.0..AND.FLXC(ID-1).EQ.0..
     *         AND.ID.GT.25) ICBEG=ID
            if(icbeg.gt.0.and.flxc(id).gt.0.) icend=id
         END IF
         PRADR=PRAD/PTOT
         conrel=0.
         radrel=1.
         if(flxtot.gt.0.) then
           conrel=FLXCNV/FLXTOT
           radrel=flrd(id)/flxtot
         end if
         IF(IPRIN.GT.0) WRITE(6,"(I4,1PE9.2,0PF9.1,1P5E10.2,2x,
     *                  3e10.2,2x,3e10.2)") ID,DM(ID),T,DELTA(ID),
     *                  GRDADB,conrel,radrel,conrel+radrel
c    *                 ,flxtot,flrd(id),flxcnv,
c    *                  delmde
         TAUM=TAU
      END DO
      if(iprin.gt.0) 
     *  write(6,"(/'convective zone between depths (inclusive)',2i4/)") 
     *  icbeg,icend
C
c     if ICONV=3, then:
c     in the convective zone the radiative (+ convective) equilibrium
c     is taken obligatorily in the differential form, i.e.
c     NDRE is modified to have the value just below the beginning of
c     convection zone, and
c     rediff(id) has to be set to unity, and reint(id) to 0 for id => ndre
c
      IF(ICBEG.GT.3.AND.ICONV.EQ.2) THEN
         NDREC=ICBEG-1
         DO ID=1,ND
            IF(ID.GE.NDREC) REDIF(ID)=1.
         END DO
c        WRITE(6,"(//' NDRE IS RESET IN CONOUT DUE TO THE EXISTENCE OF'
c    *       ,' CONVECTIVE ZONE'/'  NDRE= ',I3/)") NDREC
      END IF
c
      IF(ICBEG.GT.3.AND.ICONV.EQ.3) THEN
         NDREC=ICBEG-1
         DO ID=1,ND
            IF(ID.GE.NDREC) THEN
               REINT(ID)=0.
               REDIF(ID)=1.
             else
               reint(id)=1.
               redif(id)=0.
            END IF
         END DO
         WRITE(6,"(//' NDRE IS RESET IN CONOUT DUE TO THE EXISTENCE OF'
     *       ,' CONVECTIVE ZONE'/'  NDRE= ',I3/)") NDREC
      END IF
c
      IF(ICBEG.GT.3.AND.ICONV.GE.4) THEN
         NDREC=ICBEG-1
         DO ID=1,ND
            IF(ID.GE.NDREC) REDIF(ID)=1.
            if(id.ge.ndrec-(iconv-10)) REINT(ID)=0.
         END DO
c        WRITE(6,"(//' NDRE IS RESET IN CONOUT DUE TO THE EXISTENCE OF'
c    *       ,' CONVECTIVE ZONE'/'  NDRE= ',I3/)") NDREC
      END IF
c
      IF(ICBEG.GT.3.AND.ICONV.LE.-1) THEN
         NDREC=ICBEG-1
         DO ID=1,ND
            IF(ID.GE.NDREC) REDIF(ID)=1.
            if(id.ge.ndrec-iconv) REINT(ID)=0.
         END DO
         WRITE(6,"(//' NDRE IS RESET IN CONOUT DUE TO THE EXISTENCE OF'
     *       ,' CONVECTIVE ZONE'/'  NDRE= ',I3/)") NDREC
      END IF
c
      RETURN
      END SUBROUTINE CONOUT
C
C
C     ****************************************************************
C
C
      SUBROUTINE CONOUP
C     =================
C
C     Diagnostic outprint of temperature gradients, convective flux,
C     and their derivatives
C
      use accura
      use alipar
      use basics
      use modelq
      use conveq

      implicit none
 
      REAL(DP) :: FLXTO0,T,PTOT,PG,PRAD,FLXCR,TM,TAU,PTOTM,PGM,PRADM,
     *            T0,PT0,PG0,PR0,AB0,DLT,PRADR,CONREL,RADREL,THT,
     *            FLXCNV,VCON,TAUM
      INTEGER  :: ID
C
      ANEREL=ELEC(1)/(DENS(1)/WMM(1)+ELEC(1))
      ICBEG=0
      FLXTO0=SIG4P*TEFF**4
      DO ID=1,ND
CCC   DO ID=IDCONZ,ND
         T=TEMP(ID)
         PTOT=PTOTAL(ID)
         PG=PGS(ID)
         prad=pradt(id)
         if(prad.lt.0.) prad=0.
         FLXTOT=flxto0
         if(idisk.eq.1) then
            if(id.eq.1) then
               tht=thetav(id)
             else
               tht=(thetav(id)+thetav(id-1))*half
            end if
            flxtot=flxto0*(un-tht)
            gravd=(zd(id)+zd(id-1))*half*qgrav
            prad=pradt(id)
         end if
         IF(ID.EQ.1) THEN
            TAU=DM(ID)*ABROSD(ID)
            FLXCR=0
            GRDADB=0.
            DELTA(ID)=0.
            FLXC(ID)=0.
            FLXCNV=0.
          ELSE
            TM=TEMP(ID-1)
            TAU=TAUM+HALF*(DM(ID)-DM(ID-1))*(ABROSD(ID)+ABROSD(ID-1))
            PTOTM=PTOTAL(ID-1)
            PGM=PGS(ID-1)
            PRADM=PTOTM-PGM-HALF*DENS(ID-1)*VTURB(ID-1)**2
            if(idisk.eq.1) pradm=pradt(id-1)
            if(pradm.lt.0.) pradm=0.
            if(idisk.ge.1) gravd=(zd(id)+zd(id-1))*half*qgrav
            if(ilgder.eq.0) then
               T0=HALF*(T+TM)
               PT0=HALF*(PTOT+PTOTM)
               PG0=HALF*(PG+PGM)
               PR0=HALF*(PRAD+PRADM)
               AB0=HALF*(ABROSD(ID)+ABROSD(ID-1))
               DLT=(T-TM)/(PTOT-PTOTM)*PT0/T0
             else
               T0=SQRT(T*TM)
               PT0=SQRT(PTOT*PTOTM)
               PG0=SQRT(PG*PGM)
               PR0=SQRT(PRAD*PRADM)
               AB0=SQRT(ABROSD(ID)*ABROSD(ID-1))
               DLT=LOG(T/TM)/LOG(PTOT/PTOTM)
            end if
!            IF(ID.EQ.ND) WRITE(64,*) 'conoup'
            if(idisk.ge.0.or.id.lt.nd)
     *      CALL CONVEC(ID,T0,PT0,PG0,PR0,AB0,DLT,FLXCNV,VCON)
            IF(ICBEG.EQ.0.AND.FLXC(ID).GT.0..AND.FLXC(ID-1).EQ.0..
     *         AND.ID.GT.25) ICBEG=ID
            if(icbeg.gt.0.and.flxc(id).gt.0.) icend=id
         END IF
         PRADR=PRAD/PTOT
         conrel=FLXCNV/FLXTOT
         radrel=flrd(id)/flxtot
!        WRITE(63,"(2i4,1pe10.2,f8.1,1p12e11.3)") 
!    *                 ID,ITER,TAU,T,PTOT,DLT,
!    *                 GRDADB,conrel,radrel,conrel+radrel,
!    *                 flxtot,flrd(id),flxcnv,
!    *                 delmde,ddel,abrosd(id)
         TAUM=TAU
      END DO
       write(6,"(/'convective zone between depths (inclusive)',2i4/)") 
     *   icbeg,icend
C
      RETURN
      END SUBROUTINE CONOUP
C
C
C     ****************************************************************
C
C
      SUBROUTINE CONCOR
C     =================
C
C     Auxiliary procedure called from INILAM
C     Initialization of the model parameter DELTA immediately
C     after a completed iteration of complete linearization
C
C     DELTA is defined as d(lnT)/dln(P)
C
      use accura
      use basics
      use modelq
      use conveq, only: icbeg

      implicit none

      REAL(DP) :: PRAD0,P,PM,DEL1,TM,T1,FAC,T2,DEL2
      INTEGER  :: ID,NDEL
 
C
      IF(INDL.EQ.0) RETURN
      NDEL=NFREQE+INDL
C
      if(idisk.eq.0) then
         PRAD0=PRADT(1)-PRD0
         DO ID=1,ND
            PTOTAL(ID)=DM(ID)*GRAV+PRAD0
         END DO
      end if
C
      DO ID=2,ND
         P=PTOTAL(ID)
         PM=PTOTAL(ID-1)
         DEL1=DELTA(ID)
         TM=TEMP(ID-1)
         T1=TEMP(ID)
         FAC=DEL1*(P-PM)/(P+PM)
         T2=TM*(UN+FAC)/(UN-FAC)
         DEL2=(T1-TM)/(P-PM)/(T1+TM)*(P+PM)
         IF(ITEMP.EQ.1.AND.ID.GE.ICBEG-1) TEMP(ID)=T2
         IF(ITEMP.EQ.2) TEMP(ID)=T2
      END DO
C
C     check whether the corresponding convective flux is less
C     than total flux; if not, recalculate tempertaure
C
      if(itmcor.ne.0) then
         CALL TEMCOR
         write(6,"('  recalculation of convective flux in CONCOR'/)")
         call conout(1,ipconf)
      end if
c
      RETURN
      END SUBROUTINE CONCOR
C
C
C     ****************************************************************
C
C
      SUBROUTINE TRMDER(ID,T,PG,PRAD,TAU)
C     ===================================
C
C     Thermodynamic derivatives
C     Evaluation similar as in Kurucz's ATLAS
C
C     Input:  T     -  temperature
C             PG    -  gas pressure
C             PRAD  -  radiation pressure
C     Output: DEDT  -  d(energy)/d(T)
C             DRDT  -  d(rho)/d(T)
C             DEDPG -  d(energy)/d(PG)
C             DRDPG -  d(rho)/d(PG)
C             RHO   -  density
C
      use accura
      use basics
      use molec, only: entrp,RHOTER
      use conveq

      implicit none
 
      REAL(DP), INTENT(IN) :: T,PG,PRAD,TAU
      INTEGER, INTENT(IN)  :: ID

      REAL(DP) :: P,TMOLI0,T16,TE,TKN,ANT,ANE,ENRG,ENT,WM,
     *            DRDT,DRDPG,DPDPG,DPDT,PTOT,DEDT,DEDPG,HEATCV,
     *            DSDT,DSDP
 
      REAL(DP) :: TT(5),PP(5),RHON(5),ENER(5),entr(5)
      INTEGER  :: I,ipr,mp

      data ipr /1/
C
C     NUMERICAL EVALUATION OF THERMODYNAMIC DERIVATIVES
C
      mp=-2
c     prad=0.
      P=PG
      TT(1)=T*(UN+DIFT)
      TT(2)=T*(UN-DIFT)
      TT(3)=T
      TT(4)=T
      TT(5)=T
      PP(1)=P
      PP(2)=P
      PP(3)=P*(UN+DIFP)
      PP(4)=P*(UN-DIFT)
      PP(5)=P
      tmoli0=tmolim
      if(t.lt.tmolim) tmolim=t*(un+dift+0.001)
      if(t.ge.tmolim) tmolim=t*(un-dift-0.001)
      ioverr=0
      t16=16000.
      if(t.lt.t16.and.tt(1).gt.t16) ioverr=1
      if(t.gt.t16.and.tt(2).le.t16) ioverr=1
      DO I=1,5
         TE=TT(I)
         TKN=TE*1.38054e-16_dp
         ANT=PP(I)/TKN
         CALL ELDENS(ID,TE,ANT,ANE,ENRG,ENT,WM,0)
         RHON(I)=rhoter
         ENER(I)=(1.5_dp*PP(I)+ENRG+3._dp*PRAD*(TE/T)**4)/RHON(I)
         entr(i)=ent/RHON(I)
         if(id.eq.mp) write(*,"('tr',2i4,1p6e17.8)") 
     *   id,i,te,pp(i),ant,rhon(i),ener(i),entr(i)
      END DO
      ioverr=0
      tmolim=tmoli0
      entrp=entr(5)
c
      DRDT=(RHON(1)-RHON(2))/(TWO*T*DIFT)
      DRDPG=(RHON(3)-RHON(4))/(TWO*P*DIFP)
      RHOD=RHON(5)
      DPDPG=UN
      dpdt=0.
      if(tau.lt.50.) DPDT=4._dp*PRAD/T*(un-exp(-tau))
      DPDT=4._dp*PRAD/T
      DLRDLT=T/RHOD*(DRDT-DRDPG*DPDT/DPDPG)
      ptot=pg+prad
c
      if(ifentr.le.0) then
         DEDT= (ENER(1)-ENER(2))/(TWO*T*DIFT)
         DEDPG=(ENER(3)-ENER(4))/(TWO*P*DIFP)
         HEATCV=DEDT-DEDPG*DRDT/DRDPG
         HEATCP=DEDT-DEDPG*DPDT/DPDPG-
     *          PTOT/RHOD/RHOD*(DRDT-DRDPG*DPDT/DPDPG)
         GRDADB=-PTOT/RHOD/T*DLRDLT/HEATCP
       else
         DSDT= (ENTR(1)-ENTR(2))/(TWO*T*DIFT)
         DSDP= (ENTR(3)-ENTR(4))/(TWO*P*DIFP)
         grdadb=-dsdp/dsdt*pg/t
c        heatcp=-PTOT/RHOD/T*DLRDLT/grdadb
         heatcp=t*dsdt
      end if
      if(id.eq.mp) write(*,"(a,2i4,1p5e17.8)") 
     *'gr',id,ifentr,rhod,dsdt,dsdp,heatcp,grdadb
      ipr=0
c
      if(iter.le.itgrad.and.grdad0.gt.0)
     *   grdadb=grdad0*0.4_dp+(un-grdad0)*grdadb
!     write(6,"(i4,1p4e10.2)") id,dsdt,dsdp,-dsdp/dsdt*pg/t,heatcp
      
      RETURN
      END SUBROUTINE TRMDER
C
C
C     ****************************************************************
C
C
      SUBROUTINE TRMDEP(ID,T,PG,PRAD,TAU)
C     ===================================
C
C     Thermodynamic derivatives
C     Evaluation similar as in Kurucz's ATLAS
C
C     Input:  T     -  temperature
C             PG    -  gas pressure
C             PRAD  -  radiation pressure
C     Output: DEDT  -  d(energy)/d(T)
C             DRDT  -  d(rho)/d(T)
C             DEDPG -  d(energy)/d(PG)
C             DRDPG -  d(rho)/d(PG)
C             RHO   -  density
C
      use accura
      use basics
      use molec, only: entrp,rhoter
      use conveq

      implicit none
 
      INTEGER, INTENT(IN) :: ID
      REAL(DP),INTENT(IN) :: T,PG,PRAD,TAU

      REAL(DP) :: P,TMOLI0,T16,TE,TKN,ANT,ANE,ENRG,ENT,WM,
     *            DRDT,DRDPG,DPDPG,DPDT,PTOT,DEDT,DEDPG,HEATCV,
     *            DSDT,DSDP
      REAL(DP) :: TT(5),PP(5),RHON(5),ENER(5),entr(5)
      INTEGER  :: I
C
C   NUMERICAL EVALUATION OF THERMODYNAMIC DERIVATIVES
C
c     prad=0.
      P=PG
      TT(1)=T*(UN+DIFT)
      TT(2)=T*(UN-DIFT)
      TT(3)=T
      TT(4)=T
      TT(5)=T
      PP(1)=P
      PP(2)=P
      PP(3)=P*(UN+DIFP)
      PP(4)=P*(UN-DIFT)
      PP(5)=P
      tmoli0=tmolim
      if(t.lt.tmolim) tmolim=t*(un+dift+0.001)
      if(t.ge.tmolim) tmolim=t*(un-dift-0.001)
      ioverr=0
      t16=16000.
      if(t.lt.t16.and.tt(1).gt.t16) ioverr=1
      if(t.gt.t16.and.tt(2).le.t16) ioverr=1
      if(ioverr.eq.1) write(6,"('**** IOVERR=1 *****  T, T+, T- =',
     *   3f10.2)") t,tt(1),tt(2)

      DO I=1,5
         TE=TT(I)
         TKN=TE*1.38054e-16_dp
         ANT=PP(I)/TKN
         CALL ELDENS(ID,TE,ANT,ANE,ENRG,ENT,WM,0)
         RHON(I)=rhoter
         ENER(I)=(1.5_dp*PP(I)+ENRG+3._dp*PRAD*(TE/T)**4)/RHON(I)
         entr(i)=ent/RHON(I)
      END DO
      ioverr=0
      tmolim=tmoli0
      entrp=entr(5)
c
      DRDT=(RHON(1)-RHON(2))/(2.*T*DIFT)
      DRDPG=(RHON(3)-RHON(4))/(2.*P*DIFP)
      RHOD=RHON(5)
      DPDPG=1.
      dpdt=0.
      if(tau.lt.50.) DPDT=4._dp*PRAD/T*(un-exp(-tau))
      DPDT=4._dp*PRAD/T
      DLRDLT=T/RHOD*(DRDT-DRDPG*DPDT/DPDPG)
      ptot=pg+prad
      if(ifentr.le.0) then
         DEDT= (ENER(1)-ENER(2))/(TWO*T*DIFT)
         DEDPG=(ENER(3)-ENER(4))/(TWO*P*DIFP)
         HEATCV=DEDT-DEDPG*DRDT/DRDPG
         HEATCP=DEDT-DEDPG*DPDT/DPDPG-
     *          PTOT/RHOD/RHOD*(DRDT-DRDPG*DPDT/DPDPG)
         GRDADB=-PTOT/RHOD/T*DLRDLT/HEATCP
       else
         DSDT= (ENTR(1)-ENTR(2))/(TWO*T*DIFT)
         DSDP= (ENTR(3)-ENTR(4))/(TWO*P*DIFP)
         grdadb=-dsdp/dsdt*pg/t
c        heatcp=-PTOT/RHOD/T*DLRDLT/grdadb
         heatcp=t*dsdt
      end if
c
      if(iter.le.itgrad.and.grdad0.gt.0)
     *   grdadb=grdad0*0.4+(un-grdad0)*grdadb
      RETURN
      END SUBROUTINE TRMDEP
C
C
C     ****************************************************************
C
C
      SUBROUTINE TRMDRT(T,P)
C     ======================
C
C     Thermodynamic derivatives - based on statew equation and entropy
C     tables
C
C     Input:  T     -  temperature
C             P     -  gas pressure
C
C     Output: HEATCP - specific heat at constant pressure
C             DLRDLT - d(ln rho)/d(ln T)
C             GRDADB - adiabatic gradient d(ln T)/d(ln P)_ad
C
      use accura
      use basics
      use thermo
      use conveq

      implicit none

      real(dp), intent(in) :: t,p
 
      real(dp), parameter :: RCON=8.31434E7,wmol0=1.67333E-24/2.3

      real(dp) :: rho,drho,dt,p0,s0,p1,s1,p2,s2,p3,s3,p4,s4,
     *            dpdr,dpdt,dsdr,dsdt,den,heatcv,dq,gamma,tdpt,
     *            rhoeos
C
C     numerical evaluation of thermodynamic derivatives
C
      rho=rhoeos(t,p)
      drho=0.01*rho
      dt=0.01*t
      call prsent(rho,t,p0,s0)
      call prsent(rho+drho,t,p1,s1)
      call prsent(rho-drho,t,p2,s2)
      call prsent(rho,t+dt,p3,s3)
      call prsent(rho,t-dt,p4,s4)
      dpdr=(p1-p2)/(2.*drho)
      dpdt=(p3-p4)/(2.*dt)
      dsdr=(s1-s2)/(2.*drho)*rcon
      dsdt=(s3-s4)/(2.*dt)*rcon
      DEN=DPDR*DSDT-DPDT*DSDR
c
      if(jon .eq. 0) then
         HEATCV=T*DSDT
         HEATCP=T*DEN/DPDR
         DQ=DSDT*P/(DEN*RHO)
         GAMMA=1.0/DQ
         DLRDLT = -RHO*DPDR/(T*DPDT)
         DLRDLT = 1.0/DLRDLT
         GRDADB = -P/(HEATCP*RHO*T)*DLRDLT
         TDPT=T*DPDT
       else if(jon .ne. 0) then
         HEATCV = cvedge(JON)
         HEATCP = cpedge(JON)
         DLRDLT = -1.0
         GRDADB = -P/(HEATCP*RHO*T)*DLRDLT  ! 0.4
         GAMMA = gammaedge(JON)
      end if
 
      grdadb=p/t*(dsdr/(dsdr*dpdt-dsdt*dpdr))
 
      RETURN
      END SUBROUTINE TRMDRT
C
C
C     ****************************************************************
C
C
      SUBROUTINE CUBIC(DELTA)
C     =======================
C
C     Solution of the cubic equation for determination of
C     the true gradient DELTA
C
C     Input:   A,B   - coefficients (through module conveq)
C              DDEL   - DELTA(RAD) - DELTA(ADIAB); also transm. by CUBCON
C     Output:  DELTA - true gradient
C
      use accura
      use basics
      use conveq

      implicit none
 
      REAL(DP),INTENT(OUT) :: DELTA
      REAL(DP), PARAMETER  :: THIRD = UN/3._dp
      REAL(DP) :: AA,BB,CC,P,Q,D,D1,D2,SOL,COSF,TANF,FI,DELDA,X0,DELX
      INTEGER  :: J,IPRI

      data ipri /0/
C
C     first solve the cubic equation
C         A*X**3 + X**2 + B*X = DEL
C     A and B stored in ACNV nd BCNV
C
      AA=THIRD/ACNV
      BB=BCNV/ACNV
      CC=-DDEL/ACNV
      P=BB*THIRD-AA*AA
      Q=AA**3-(BB*AA-CC)*HALF
      D=Q*Q+P*P*P
      IF(D.GT.0.) THEN
         D=SQRT(D)
         if(d-abs(q).lt.1.e-14*d) then
            SOL=(TWO*D)**THIRD-AA
          ELSE
            D1=ABS(D-Q)
            D2=ABS(D+Q)
            SOL=D1/(D-Q)*D1**THIRD-D2/(D+Q)*D2**THIRD-AA
          END IF
       ELSE
         COSF=-Q/SQRT(ABS(P*P*P))
         TANF=SQRT(UN-COSF*COSF)/COSF
         FI=ATAN(TANF)*THIRD
         SOL=TWO*SQRT(ABS(P))*COS(FI)-AA
      END IF


c     write(*,"('cubbeg',1p5e12.4)") acnv,bcnv,sol,
c    *  acnv*sol**3+sol**2+bcnv*sol,ddel
C
C     if the previous formalism gives an unphysical solution
C     x > DEL, then find the physical solution in the range (0, DEL)
C     by a Newton-Raphson solution of the cubic equation
C
      DELDA=SOL*(BCNV+SOL)
      IF(DELDA.GT.DDEL.OR.DELDA.LT.0.) THEN
         X0=sol
         DO J=1,50
            DELX=(DDEL-X0*(BCNV+X0+ACNV*X0*X0))/(3._dp*ACNV*X0*X0+
     &             TWO*X0+BCNV)
            X0=X0+DELX
            IF(ABS(DELX/X0).LT.1e-6) EXIT
         END DO
         SOL=X0
      END IF
C
C     finally, the actual gradient delta
C
      DELTA=GRDADB+BCNV*SOL+SOL*SOL
c     write(*,"('cubic',1p6e12.4)") acnv,bcnv,ddel,grdadb,sol,delta
      RETURN
      END SUBROUTINE CUBIC
C
C
C     ****************************************************************
C
C
      SUBROUTINE SETDRT
C     =================
C
      use accura
      use basics
      use modelq

      implicit none
 
      REAL(DP), PARAMETER:: DDTMIN=0., DDTPLU=0.001
      REAL(DP) :: T,P,RHO1,RHO2,RHOEOS
      INTEGER  :: ID
C
      DO ID=1,ND
         T=TEMP(ID)
         P=PTOTAL(ID)
         RHO1=RHOEOS(T*(UN-DDTMIN),P)
         RHO2=RHOEOS(T*(UN+DDTPLU),P)
         DRHODT(ID)=(RHO2-RHO1)/T/(DDTMIN+DDTPLU)
      END DO
      RETURN
      END SUBROUTINE SETDRT
