C
C     ****************************************************************
C
C

      SUBROUTINE TEMCOR
C     =================
C
C     Auxiliary procedure for INILAM.
C     Tests wheather the convective flux corresponding to newly
C     determined temperature and logarithmic gradient DELTA
C     is larger than the total flux. If so, the temperature is modified
C     by an iterative procedure for determining new temperature
C     that yields convective flux less than SIG4P*TEFF**4
C
      use accura
      use alipar
      use array1
      use basics
      use modelq
      use conveq

      implicit none

      REAL(DP) :: FLXTO0,DLTND,T,P,PG,PRAD,TM,PM,PGM,PRADM,FAC,
     *            T0,P0,PG0,PR0,AB0,DLT,FLXCNV,VCON,DHCDD,FLXC1,
     *            DHCDT,TT,DDT0,DFLCDT,DELTEM,AN,ANE,ENRG,ENTT,WM,
     *            OPROS,OPPLA,ABROS,GRADV,RHO,T1
      INTEGER  :: ID,IFNDM1,KKK

      IF(ICONV.EQ.0.AND.INDL.EQ.0) RETURN
      FLXTO0=SIG4P*TEFF**4
      ANEREL=ELEC(1)/(DENS(1)/WMM(1)+ELEC(1))
      DLTND=DELTA(ND)
      IFNDM1=0
C
      DEPID: DO ID=2,ND
CCC   DEPID: DO ID=IDCONZ,ND
         flxtot=flxto0
         if(idisk.eq.1) then
            flxtot=flxto0*(un-thetav(id))
            gradv=zd(id)*qgrav
         end if
         T=TEMP(ID)
         P=PTOTAL(ID)
         PG=PGS(ID)
         PRAD=P-PG-HALF*DENS(ID)*VTURB(ID)**2
         TM=TEMP(ID-1)
         PM=PTOTAL(ID-1)
         PGM=PGS(ID-1)
         PRADM=PM-PGM-HALF*DENS(ID-1)*VTURB(ID-1)**2
         IF(ID.EQ.ND.AND.IFNDM1.EQ.1) THEN
            FAC=DLTND*(P-PM)/(P+PM)
            T=TM*(UN+FAC)/(UN-FAC)
         END IF

         INLOOP: DO KKK=1,10
            T0=HALF*(T+TM)
            P0=HALF*(P+PM)
            PG0=HALF*(PG+PGM)
            PR0=HALF*(PRAD+PRADM)
            AB0=HALF*(ABROSD(ID)+ABROSD(ID-1))
            DLT=(T-TM)/(P-PM)*P0/T0
            DELTA(ID)=DLT
C
C        convective flux and its derivatives
C
            CALL CONVEC(ID,T0,P0,PG0,PR0,AB0,DLT,FLXCNV,VCON)
            FLXC(ID)=FLXCNV
            IF(FLXCNV.LT.0.999999*FLXTOT) CYCLE DEPID
C
C        in case that convective flux it too large:
C        iterative procedure for determining new temperature such
C        that yields convective flux less than SIG4P*TEFF**4
C
C        Basically by the Newton-Raphson method;
C        derivative of the convective flux wrt. T calculated
C        numerically; derivative wrt. DELTA calculated analytically
C
            DHCDD=0.
            IF(DELMDE.GT.0.) DHCDD=1.5D0/DELMDE*FLXCNV
            T1=1.001D0*T0
            CALL CONVEC(ID,T1,P0,PG0,PR0,AB0,DLT,FLXC1,VCON)
            DHCDT=(FLXC1-FLXCNV)*1.D3/T0*HALF
            TT=T*T-TM*TM
            DDT0= DLT/HALF*TM/TT
            DFLCDT=DHCDT+DHCDD*DDT0
            DELTEM=(FLXTOT-FLXCNV)/DFLCDT
            T1=T+DELTEM
            IF(T1.LT.TM+HALF*(T-TM)) T1=TM+HALF*(T-TM)
            T=T1
            write(94,"(3i4,f10.4,2f12.3,f12.5,1pe15.6)") 
     *      iter,id,kkk,delta(id),temp(id),t,deltem,flxcnv
            TEMP(ID)=T
            IF(ID.EQ.ND-1) IFNDM1=1
            IF(abs(deltem/t).gt.1.e-5) EXIT INLOOP
         END DO INLOOP
C
C        Determination of electron density from the total pressure
C
         AN=PG/T/BOLK
         CALL ELDENS(ID,T,AN,ANE,ENRG,ENTT,WM,1)
         RHO=WMM(ID)*(AN-ANE)
         DENS(ID)=RHO
         ELEC(ID)=ANE
         CALL WNSTOR(ID)
         CALL STEQEQ(ID,POP,1)
         CALL OPACF0(ID)
         CALL MEANOP(T,OPROS,OPPLA)
         ABROS=OPROS/DENS(ID)
         ABROSD(ID)=ABROS
      END DO DEPID
      RETURN
      END SUBROUTINE TEMCOR
C
C
C     ****************************************************************
C
C

      SUBROUTINE HESOL6
C     =================
C
C     Solution of the coupled system of
C     1) hydrostatic equilibrium equation;
C     2) definitions of Ptotal, Pgas and rho;
C     3) state equation
C     4) z-m relation
C     with a given temperature and radiation pressure
C     Numerical solution by a Newton-Raphson method
C
      use accura
      use basics
      use modelq
      use conveq

      implicit none

      INTEGER, PARAMETER :: MP=6,NP=6,IP=1,IG=2,IR=3,IN=4,IE=5,IZ=6,
     *                      NITERH=15
      REAL(DP),PARAMETER :: ERROR=1.e-4

      REAL(DP) :: HR1,HG1,X,F1,X1,F1D,T,AN,DMP,SUM,CHANM,CHAN,
     *            A1,B1,B2,C1,C2,WT,D0,D1,D2,AA,BB,AB,FLUXW,QG,DMM,
     *            ERFCX,GRA
      INTEGER  :: ID,IJ,IJT,IACH,IACH0,IACDH,ITERH,I,J,IPT,IPT0,IPT1,
     *            IPT2,IPNGH,IX
      LOGICAL  :: LAC2H

      REAL(DP) ::  P(MDEPTH),ANTT(MDEPTH),CHNG(MDEPTH),
     *             VEC(MP,MDEPTH),VEC1(MP,MDEPTH),
     *             VEC2(MP,MDEPTH),VEC3(MP,MDEPTH),
     *             SOL(MP),ERR(MP),CHN(MP),
     *             A(MP,MP),B(MP,MP),C(MP,MP),VL(MP),
     *             D(MP,MP,MDEPTH),ANU(MP,MDEPTH),
     *             anerl(mdepth)
C
C     radiation pressure scale feight at the surface
C
      ID=1
      IF(ITER.EQ.0) THEN
         HR1=SIG4P*TEFF**4*PCK*ABROSD(ID)/QGRAV
       ELSE
         IF(NFREQE.GT.0) THEN
            GRA=0.
            DO IJ=1,NFREQE
               IJT=IJFR(IJ)
               IF(.NOT.LSKIP(ID,IJT)) THEN
                  FLUXW=W(IJT)*(FH(IJT)*RADEX(IJ,ID)-HEXTRD(IJT))
                  GRA=GRA+FLUXW*ABSOEX(IJ,id)
               END IF
            END DO
         END IF
         HR1=PCK/QGRAV*(GRA+FPRD(ID))/DENS(ID)
      END IF
      do id=1,nd
         ANTT(ID)=DENS(ID)/WMM(ID)+ELEC(ID)
         PGS(ID)=ANTT(ID)*BOLK*TEMP(ID)
         PTOTAL(ID)=PRADT(ID)+PGS(ID)
      end do
C
C     -------------------
C     -------------------
C     Basic Newton-Raphson iteration loop
C     -------------------
C     -------------------
C
      LAC2H=.FALSE.
      IACH=6
      IACDH=4
      IACH0=IACH-3

      GLOB: DO ITERH=1,NITERH
C
C     -------------------
C     Forward elimination
C     -------------------
C
         DO ID=1,ND
            ANTT(ID)=DENS(ID)/WMM(ID)+ELEC(ID)
            PGS(ID)=ANTT(ID)*BOLK*TEMP(ID)
            PTOTAL(ID)=PRADT(ID)+PGS(ID)
            P(ID)=PTOTAL(ID)
            VEC(IP,ID)=PTOTAL(ID)
            VEC(IG,ID)=PGS(ID)
            VEC(IR,ID)=DENS(ID)
            VEC(IN,ID)=ANTT(ID)
            VEC(IE,ID)=ELEC(ID)
            VEC(IZ,ID)=ZD(ID)
C
            DO I=1,NP
               VL(I)=0.
               DO J=1,NP
                  B(I,J)=0.
                  A(I,J)=0.
                  C(I,J)=0.
               END DO
            END DO
C
            IF(ID.EQ.1) THEN
               HG1=SQRT(TWO*PGS(ID)/DENS(ID)/QGRAV)
               X=(ZD(ID)-HR1)/HG1
               IF(X.LT.3.) THEN
                  IF(X.LT.0.) X=0.
                  F1=8.86226925D-1*EXP(X*X)*ERFCX(X)
                ELSE
                  F1=HALF*(UN-HALF/X/X)/X
               END IF
               X1=X*1.01
               F1D=0.
               IF(X1.LT.3.) THEN
                  F1D=8.86226925D-1*EXP(X1*X1)*ERFCX(X1)
                ELSE
                  F1D=HALF*(UN-HALF/X1/X1)/X1
               END IF
               IF(X.GT.0.) F1D=(F1D-F1)*100./X
               B(IG,IG)=DENS(ID)*HG1*HALF/PGS(ID)*(F1-F1D*X)
               B(IG,IR)=HG1*HALF*(F1+F1D*X)
               B(IG,IZ)=DENS(ID)*F1D
               VL(IG)=DM(ID)-DENS(ID)*HG1*F1
               B(IP,IP)=UN
               B(IP,IG)=-UN
               VL(IP)=PRADT(ID)+PGS(ID)-P(ID)
            ELSE
               DMM=UN/(DM(ID)-DM(ID-1))
               QG=HALF*QGRAV
               B(IP,IP)=DMM
               B(IP,IZ)=-QG
               A(IP,IP)=DMM
               A(IP,IZ)=QG
               VL(IP)=QG*(ZD(ID)+ZD(ID-1))-(P(ID)-P(ID-1))*DMM
               B(IG,IP)=UN
               B(IG,IG)=-UN
               VL(IG)=PRADT(ID)+PGS(ID)-P(ID)
            END IF
C
            B(IR,IR)=UN
            B(IR,IN)=-WMM(ID)
            B(IR,IE)=WMM(ID)
            VL(IR)=wmm(id)*(antt(id)-elec(id))-dens(id)
C
            B(IN,IG)=UN
            B(IN,IN)=-BOLK*TEMP(ID)
            VL(IN)=antt(id)*bolk*temp(id)-pgs(id)
C
            T=TEMP(ID)
            AN=ANTT(ID)
            ANERL(ID)=ELEC(ID)/AN
            B(IE,IE)=UN
            b(ie,in)=-anerl(id)
            vl(ie)=anerl(id)*antt(id)-elec(id)
C
            IF(ID.LT.ND) THEN
               DMP=(DM(ID+1)-DM(ID))*HALF
               B(IZ,IR)=DMP/DENS(ID)**2
               B(IZ,IZ)=UN
               C(IZ,IR)=-DMP/DENS(ID+1)**2
               C(IZ,IZ)=UN
               VL(IZ)=ZD(ID+1)-ZD(ID)+DMP/DENS(ID)+DMP/DENS(ID+1)
             ELSE
               B(IZ,IZ)=UN
               VL(IZ)=0.
            END IF
C
            IF(ID.GT.1) THEN
               B(IP,IR)=B(IP,IR)-
     *               A(IP,IP)*D(IP,IR,ID-1)-
     *               A(IP,IZ)*D(IZ,IR,ID-1)
               B(IP,IZ)=B(IP,IZ)-
     *               A(IP,IP)*D(IP,IZ,ID-1)-
     *               A(IP,IZ)*D(IZ,IZ,ID-1)
               VL(IP)=VL(IP)+A(IP,IP)*ANU(IP,ID-1)+
     *                    A(IP,IZ)*ANU(IZ,ID-1)
            END IF
C
            CALL MATINV(B,NP,MP)
C
            DO I=1,NP
               SUM=0.
               DO J=1,NP
                  SUM=SUM+B(I,J)*VL(J)
               END DO
               ANU(I,ID)=SUM
            END DO
            IF(ID.LT.ND) THEN
            DO I=1,NP
               D(I,IR,ID)=B(I,IZ)*C(IZ,IR)
               D(I,IZ,ID)=B(I,IZ)*C(IZ,IZ)
            END DO
            END IF
         END DO
C
C     -------------------
C     backsubstitution
C     -------------------
C
         CHANM=0
         DO ID=ND,1,-1
            CHNG(ID)=0.
            IF(ID.EQ.ND) THEN
               DO I=1,NP
                  SOL(I)=ANU(I,ID)
               END DO
             ELSE
               DO I=1,NP
                  ANU(I,ID)=ANU(I,ID)+D(I,IR,ID)*ANU(IR,ID+1)+
     *                             D(I,IZ,ID)*ANU(IZ,ID+1)
                  SOL(I)=ANU(I,ID)
               END DO
            END IF
            DO I=1,NP
               CHAN=0.
               IF(VEC(I,ID).NE.0.) CHAN=SOL(I)/VEC(I,ID)
               CHN(I)=CHAN
               IF(ABS(CHAN).GT.CHANM) CHANM=ABS(CHAN)
               IF(ABS(CHAN).GT.CHNG(ID)) CHNG(ID)=ABS(CHAN)
               IF(CHAN.LT.-0.99) CHAN=-0.99
               IF(CHAN.GT.99.00) CHAN=99.00
               VEC(I,ID)=VEC(I,ID)*(UN+CHAN)
            END DO
C
            PTOTAL(ID)=VEC(IP,ID)
            P(ID)=PTOTAL(ID)
            PGS(ID)=VEC(IG,ID)
            DENS(ID)=VEC(IR,ID)
            ANTT(ID)=VEC(IN,ID)
            ELEC(ID)=VEC(IE,ID)
            ZD(ID)=VEC(IZ,ID)
C
            IF(ID.EQ.1) THEN
               HG1=SQRT(TWO*PGS(ID)/DENS(ID)/QGRAV)
               X=(ZD(ID)-HR1)/HG1
               IF(X.LT.3.) THEN
                  IF(X.LT.0.) X=0.
                  F1=8.86226925D-1*EXP(X*X)*ERFCX(X)
                ELSE
                  F1=HALF*(UN-HALF/X/X)/X
               END IF
               ERR(IP)=(DENS(ID)*HG1*F1-DM(ID))/DM(ID)
             ELSE IF(ID.LT.ND) THEN
               ERR(IP)=(P(ID+1)-P(ID))/(DM(ID+1)-DM(ID))*
     *              TWO/QGRAV/(ZD(ID+1)+ZD(ID))-UN
             ELSE
               ERR(IP)=0.
            END IF
            IF(P(ID).NE.0.) ERR(IG)=
     *           (PRADT(ID)+PGS(ID)-P(ID))/P(ID)
            IF(DENS(ID).NE.0.) ERR(IR)=
     *           (DENS(ID)-(ANTT(ID)-ELEC(ID))*WMM(ID))/DENS(ID)
            IF(PGS(ID).NE.0.) ERR(IN)=
     *           (PGS(ID)-ANTT(ID)*BOLK*TEMP(ID))/PGS(ID)
            IF(ELEC(ID).NE.0.)
     *      ERR(IE)=(ELEC(ID)-ANerl(id)*antt(id))/ELEC(ID)
            IF(ID.LT.ND) THEN
               ERR(IZ)=(ZD(ID)-ZD(ID+1))*TWO/(DM(ID+1)-DM(ID))/
     *                 (UN/DENS(ID)+UN/DENS(ID+1))-UN
             ELSE
               ERR(IZ)=ZD(ID)
            END IF
         END DO
C
C     -------------------
C     acceleration
C     -------------------
C
         IF(NITERH.GE.IACH .AND. ITERH.GE.IACH0) THEN
            ipngH=1
            if(iacdH.gt.0) ipngH=mod((iterH-iacH),iacdH)
            if(.not.lac2H) then
               IPT=MOD(ITERH,3)
               IPT0=MOD(IACH,3)
               IPT1=MOD((IACH+1),3)
               IPT2=MOD((IACH+2),3)
               IF(ITERH.EQ.IACH0) THEN
                  DO ID=1,ND
                     DO IX=1,NP
                        VEC3(IX,ID)=VEC(IX,ID)
                     END DO
                  END DO
               ELSE IF(IPT.EQ.IPT1) THEN
                  DO ID=1,ND
                     DO IX=1,NP
                        VEC2(IX,ID)=VEC(IX,ID)
                     END DO
                  END DO
               ELSE IF(IPT.EQ.IPT2) THEN
                  DO ID=1,ND
                     DO IX=1,NP
                        VEC1(IX,ID)=VEC(IX,ID)
                     END DO
                  END DO
               ENDIF
            else if (ipngH.ne.0) then
               DO ID=1,ND
                  DO IX=1,NP
                     VEC3(IX,ID)=VEC2(IX,ID)
                  END DO
               END DO
               DO ID=1,ND
                  DO IX=1,NP
                     VEC2(IX,ID)=VEC1(IX,ID)
                  END DO
               END DO
               DO ID=1,ND
                  DO IX=1,NP
                     VEC1(IX,ID)=VEC(IX,ID)
                  END DO
               END DO
            end if
         END IF

         IF(ITERH.GE.IACH) THEN
            A1=0.
            B1=0.
            B2=0.
            C1=0.
            C2=0.
            DO IX=1,NP
               DO ID=1,ND
                  WT=0.
                  IF(VEC(IX,ID).NE.0.) WT=1./ABS(VEC(IX,ID))
                  D0=VEC(IX,ID)-VEC1(IX,ID)
                  D1=D0-VEC1(IX,ID)+VEC2(IX,ID)
                  D2=D0-VEC2(IX,ID)+VEC3(IX,ID)
                  A1=A1+WT*D1*D1
                  B1=B1+WT*D1*D2
                  B2=B2+WT*D2*D2
                  C1=C1+WT*D0*D1
                  C2=C2+WT*D0*D2
               END DO
            END DO
            AB=B2*A1-B1*B1
            IF(AB.NE.0.) THEN
               AA=(B2*C1-B1*C2)/AB
               BB=(A1*C2-B1*C1)/AB
               DO ID=1,ND
                  DO IX=1,NP
                     VEC(IX,ID)=(UN-AA-BB)*VEC(IX,ID)+AA*VEC1(IX,ID)+
     *                   BB*VEC2(IX,ID)
                  END DO
               END DO
               LAC2H=.TRUE.
             ELSE
               IACH=IACH+IACDH
               IACH0=IACH-3
            END IF
         END IF
C
         DO ID=1,ND
            PTOTAL(ID)=VEC(IP,ID)
            P(ID)=PTOTAL(ID)
            PGS(ID)=VEC(IG,ID)
            DENS(ID)=VEC(IR,ID)
            ANTT(ID)=VEC(IN,ID)
            ELEC(ID)=VEC(IE,ID)
            ZD(ID)=VEC(IZ,ID)
C
            IF(ID.EQ.1) THEN
               HG1=SQRT(TWO*PGS(ID)/DENS(ID)/QGRAV)
               X=(ZD(ID)-HR1)/HG1
               IF(X.LT.3.) THEN
                  IF(X.LT.0.) X=0.
                  F1=8.86226925D-1*EXP(X*X)*ERFCX(X)
                ELSE
                  F1=HALF*(UN-HALF/X/X)/X
               END IF
               ERR(IP)=(DENS(ID)*HG1*F1-DM(ID))/DM(ID)
             ELSE IF(ID.LT.ND) THEN
               ERR(IP)=(P(ID)-P(ID-1))/(DM(ID)-DM(ID-1))*
     *                 TWO/QGRAV/(ZD(ID)+ZD(ID-1))-UN
            END IF
            IF(P(ID).NE.0.) ERR(IG)=
     *           (PRADT(ID)+PGS(ID)-P(ID))/P(ID)
            IF(DENS(ID).NE.0.) ERR(IR)=
     *           (DENS(ID)-(ANTT(ID)-ELEC(ID))*WMM(ID))/DENS(ID)
            IF(PGS(ID).NE.0.) ERR(IN)=
     *           (PGS(ID)-ANTT(ID)*BOLK*TEMP(ID))/PGS(ID)
            IF(ELEC(ID).NE.0.)
     *           ERR(IE)=(ELEC(ID)-ANerl(id)*antt(id))/ELEC(ID)
            IF(ID.GT.1) THEN
               ERR(IZ)=(ZD(ID-1)-ZD(ID))*TWO/(DM(ID)-DM(ID-1))/
     *              (UN/DENS(ID-1)+UN/DENS(ID))-UN
             ELSE
               ERR(IZ)=0.
            END IF
         END DO
C
C     Convergence criterion for the Newton-Raphson method
C
         IF(CHANM.LT.ERROR) EXIT GLOB
      END DO GLOB
C
      RETURN
      END SUBROUTINE HESOL6
C
C     ****************************************************************
C

      REAL(DP) FUNCTION ERFCX(X)
C     ==========================
C
C     complementary error function
C     expression from Abramowitz and Stegun, p.299, Eq. 7.1.26
C
      use accura
      implicit none

      REAL(DP), INTENT(IN) :: X
      REAL(DP)             :: T
      REAL(DP), PARAMETER  :: P  = 0.3275911,
     *                        A1 = 0.254829592,
     *                        A2 =-0.284496736,
     *                        A3 = 1.421413741,
     *                        A4 =-1.453152027,
     *                        A5 = 1.061405429,
     *                        UN = 1.
      T=UN/(UN+P*X)
      ERFCX=0.
      IF(X.GT.13.) RETURN
      ERFCX=T*(A1+T*(A2+T*(A3+T*(A4+T*A5))))*EXP(-X*X)
      RETURN
      END FUNCTION ERFCX
C
C
C     ****************************************************************
C
C
!     include 'modules.f'
!     program sol1tes
!     write(*,*) 'sol1'
!     end program sol1tes
C
C
C     ****************************************************************
C
C
      SUBROUTINE SOLVE
C     ================
C
C     Driving procedure for complete linearization
C     Solution of the system
C
C      A * del(PSI{ID-1}) + B * del(PSI{ID}) + C * del(PSI{ID+1}) = VECL
C
C     where PSI{ID} means vector PSI at depth ID,
C           del(PSI{ID}) linearization corrections to PSI;
C     Vector PSI is a vector composed of all unknown model parameters,
C     the choice and order of which is given by input parameters INHE,
C     INRE,INPC,INSE, and INMP (see START).
C     A,B,C are the so-called matrices of complete linearization
C     and VECL is the corressponding rhs vector, pertinent to depth ID.
C
C     The above block tridiagonal system is solved by the standard
C     Gaussian elimination, ie.
C
C       del(PSI{ID}) = BET{ID} - ALF{ID} * del{PSI{ID+1}),
C
C     (the so-called back-solution),
C     where the auxiliary matrix ALF and vector BET, at each depth,
C     are given by (the so-called forward elimination)
C
C       ALF{ID} = (B - A * ALF{ID-1})**-1 * C ,
C     and
C       BET{ID} = (B - A * ALF{ID-1})**-1 * (VECL - A * BET{ID-1})
C
C     Programming notes:
C     Although matrices A,B,C have size (NN x NN), only matrix B is
C     represented as array (MTOT x MTOT), MTOT being the maximum value
C     of NN; other matrices have large parts void, so that
C     A - is represented as array (MAROWS x MTOT), the maximum number of
C         rows of A is MFREX+2 (because only the transfer equations, the
C         iydrostatic equilibrium, and optionally radiative equilibrium
C         equations couple the depth point ID and ID-1)
C     C - is represented as array (MFREX x MCCOLS), ie.
C         the maximum number of rows is MFREX (only the transfer
C         equations couple the depth point ID and ID+1);
C         and since the upper square block (NFREQE x NFREQE), corresponding
C         to the radiative transfer equations, is diagonal, all the
C         transfer equations may be represemted as one column, thus
C         reducing the number of columns of C to number of constraint
C         equations + 1, ie. the maximum number to MCCOLS=MLEVEL+5.
C
      use accura
      use alipar
      use array1
      use basics
      use iterat
      use modelq

      implicit none

      REAL(DP) :: SUM,BZ,CHAN,DPLP,DPLM,CHMX,CHMT,CHPOP
      INTEGER  :: N,M,M1,ID,I,J,K,IID
      LOGICAL  :: LMKA,LITEK

      CHARACTER(LEN=16) :: FPR='(2i5,1p290e10.2)'
C      
               
      write(*,*)  
      write(*,*) '=========  LINEARIZATION, ITER =',iter
      write(*,*)
      write(*,*) 'REINT:'
      write(6,"(10f5.1)") (reint(id),id=1,nd)
      write(*,*)
      write(*,*) 'REDIF:'
      write(6,"(10f5.1)") (redif(id),id=1,nd)
      write(*,*)

      REWIND 91
      REWIND 92
      REWIND 93
      N=NN
      M=NFREQE
      IF(IFALI.LE.5) THEN
         M1=NFREQE+2
         IF(ICONV.NE.0.OR.NRETC.NE.0) M1=NFREQE+3
       ELSE
         M1=N
      END IF
C
C     --------------------------------
C     First part - forward elimination
C     --------------------------------
C
      LMKA=.FALSE.
      IF(ITER.LT.NITER) LMKA=KANT(ITER+1).EQ.1
      LASO=KANT(ITER).EQ.1
      DO ID=1,ND
C
C        evaluate matrices A,B,C, and rhs vector VECL, corresponding
C        to depth ID
C
         CALL WNSTOR(ID)
         IF(.NOT.LASO) THEN
            CALL MATGEN(ID)
            IF(LMKA) WRITE(93) ((A(I,J),I=1,M1),J=1,N)

c        if(mod(id,7).eq.1.or.id.eq.2.or.id.eq.nd-1) then
c        if(mod(id,9).eq.0) then
            write(51,fpr) iter,id,(vecl(i),i=1,nn)
            write(53,fpr) iter,id,(psy0(i,id),i=1,nn)
            write(54,fpr) iter,id,(b(i,i),i=1,nn)
c           write(55,fpr) iter,id,(b(nfreqe+inre,i),i=1,nn)
c           write(56,fpr) iter,id,(b(nfreqe+inpc,i),i=1,nn)
c           write(57,fpr) iter,id,(b(i,nfreqe+inre),i=1,nn)
c           write(58,fpr) iter,id,(b(i,nfreqe+inpc),i=1,nn)
c           write(59,fpr) iter,id,(b(nfreqe+inhe,i),i=1,nn)
c           write(60,fpr) iter,id,(b(i,nfreqe+inhe),i=1,nn)
c           irite(43,fpr) iter,id,(b(nn,i),i=1,nn)
            do i=1,nn
               write(55,fpr) i,id,(b(i,j),j=1,nn)
            end do
c        end if

         ELSE
            CALL RHSGEN(ID)
            READ(93) ((A(I,J),I=1,M1),J=1,N)
c           if(mod(id,7).eq.1.or.id.eq.2.or.id.eq.nd-1) then
               write(51,fpr) iter,id,(vecl(i),i=1,nn)
               write(53,fpr) iter,id,(psy0(i,id),i=1,nn)
c           end if
         ENDIF

         IF(ID.GT.1) THEN
C
C           expression   VECL-A*BET
C
            DO I=1,M1
               SUM=0.
               DO J=1,N
                  SUM=SUM+A(I,J)*BET(J,ID-1)
               END DO
               VECL(I)=VECL(I)-SUM
            END DO
C
C           expression   B-A*ALF,  stored in array B
C
            IF(.NOT.LASO) THEN
               DO I=1,M1
                  DO J=1,N
                     SUM=0.
                     DO K=1,N
                        SUM=SUM+A(I,K)*ALF(K,J)
                     END DO
                     B(I,J)=B(I,J)-SUM
                  END DO
               END DO
            END IF
         END IF
C
C        expression  (B-A*ALF)**-1,  stored in array B
C
         IF(LASO) THEN
            READ(92) ((B(I,J),I=1,N),J=1,N)
          ELSE
            CALL MATINV(B,N,MTOT)
          do i=1,nn
             write(56,fpr) i,id,(b(i,j),j=1,nn)
          end do
            IF(LMKA) WRITE(92) ((B(I,J),I=1,N),J=1,N)
         END IF
C
C        auxiliary vector BET = (B-A*ALF)**-1 * (L-A*BET)
C
         DO I=1,N
            SUM=0.
            DO J=1,N
               SUM=SUM+B(I,J)*VECL(J)
            END DO
            BET(I,ID)=SUM
         END DO
C
         IF(ID.LT.ND) THEN
C
C        auxiliary matrix   ALF = (B-A*ALF)**-1 * C
C
            IF(LASO) THEN
               IF(ID.LT.(ND-1)) THEN
                  READ(91) ALF(1,1)
               ELSE
                  READ(91) ((ALF(I,J),I=1,N),J=1,N)
               ENDIF
            ELSE
               DO I=1,N
                  DO J=1,M
                     ALF(I,J)=B(I,J)*C(J,J)
                  END DO
               END DO
               DO I=1,N
                  DO J=M+1,N
                     SUM=0.
                     DO K=1,M
                        SUM=SUM+B(I,K)*C(K,J)
                     END DO
                     IF(IFALI.GT.5.OR.ICONV.NE.0) THEN
                        DO K=M+1,N
                           SUM=SUM+B(I,K)*C(K,J)
                        END DO
                     END IF
                     ALF(I,J)=SUM
                  END DO
C
C     taking into account the separate elements of matrix C
C
                  BZ=0.
                  IF(INZD.GT.0) BZ=B(I,M+INZD)
                  IF(INZD.GT.0) ALF(I,M+INZD)=ALF(I,M+INZD)+BZ*CZZ
                  IF(INHE.GT.0) ALF(I,M+INHE)=ALF(I,M+INHE)+BZ*CZN
                  IF(INPC.GT.0) ALF(I,M+INPC)=ALF(I,M+INPC)+BZ*CZE
                  IF(INMP.GT.0) ALF(I,M+INMP)=ALF(I,M+INMP)+BZ*CZM
               END DO
C
C           store the auxiliary matrix ALF
C
               WRITE(91) ((ALF(I,J),I=1,N),J=1,N)
            END IF
         END IF
      END DO
C
C     --------------------------
C     Second part - backsolution
C     --------------------------
C
      DO I=1,N
         VECL(I)=0.
      END DO
      DO IID=1,ND
         ID=ND-IID+1
         IF(ID.LT.ND) THEN
C
C           read old  PSI
C
            DO I=1,N
               PSI0(I)=PSY0(I,ID)
            END DO
C
C           read auxiliary matrix ALF and vector BET
C
            BACKSPACE 91
            READ(91) ((ALF(I,J),I=1,N),J=1,N)
            BACKSPACE 91
C
C           expression  ALF * delta(PSI{previous depth}), stored
C           in array VECL
C
            DO I=1,N
               SUM=0.
               DO J=1,N
                  SUM=SUM+ALF(I,J)*DPSI(J)
               END DO
               VECL(I)=SUM
            END DO
         END IF
C
C        finally, evaluate delta(PSI) and corresponding relative changes
C        delta(PSI)/PSI
C
         DO I=1,N
            DPSI(I)=BET(I,ID)-VECL(I)
            CHAN=0.
            IF(PSI0(I).GT.0.) CHAN=DPSI(I)/PSI0(I)
            BET(I,ID)=CHAN
C
C           over-relaxation
C
            IF(I.GE.NFREQE+INSE) CHAN=ORELAX*CHAN
C
C           To avoid instabilities, relative changes of all quantities
C           are artificially limited not to exceed certain predefined values
C
            IF(CHAN.LE.UN/DPSILG-UN) CHAN=UN/DPSILG-UN
            IF(CHAN.GE.DPSILG-UN) CHAN=DPSILG-UN
            IF(INRE.GT.0) THEN
               DPLP=DPSILT-UN
               DPLM=UN/DPSILT-UN
               IF(CHAN.LE.DPLM.AND.I.EQ.NFREQE+INRE) CHAN=DPLM
               IF(CHAN.GT.DPLP.AND.I.EQ.NFREQE+INRE) CHAN=DPLP
            END IF
            IF(INHE.GT.0) THEN
               DPLP=DPSILN-UN
               DPLM=UN/DPSILN-UN
               IF(CHAN.LE.DPLM.AND.I.EQ.NFREQE+INHE) CHAN=DPLM
               IF(CHAN.GT.DPLP.AND.I.EQ.NFREQE+INHE) CHAN=DPLP
            END IF
            IF(INPC.GT.0) THEN
               DPLP=DPSILN-UN
               DPLM=UN/DPSILN-UN
               IF(CHAN.LE.DPLM.AND.I.EQ.NFREQE+INPC) CHAN=DPLM
               IF(CHAN.GT.DPLP.AND.I.EQ.NFREQE+INPC) CHAN=DPLP
            END IF
            IF(INDL.GT.0) THEN
               DPLP=DPSILD-UN
               DPLM=UN/DPSILD-UN
               IF(CHAN.LE.DPLM.AND.I.EQ.NFREQE+INDL) CHAN=DPLM
               IF(CHAN.GT.DPLP.AND.I.EQ.NFREQE+INDL) CHAN=DPLP
            END IF
C
C           new vector PSI
C
            PSI0(I)=PSI0(I)*(CHAN+UN)
         END DO
         IF(INRE.GT.0) CHANT(ID)=BET(NFREQE+INRE,ID)
c        if(mod(id,7).eq.1.or.id.eq.2.or.id.eq.nd-1) then
            write(52,fpr) iter,id,(bet(i,id),i=1,nn)
c        end if
C
C        new vector PSI is stored
C
         DO I=1,N
            PSY0(I,ID)=PSI0(I)
         END DO
      END DO
      DO ID=1,ND
         write(99,"(i4,2f8.1,1p2e11.3)") 
     *   id,redif(id),reint(id),bet(nfreqe+inre,id),
     *   psy0(nfreqe+inre,id)
      END DO
      close(99)
C
C     print out the relative changes of vector PSI
C
      CALL PRCHAN(BET,CHMX,CHMT,CHPOP)
C
C     STOP if changes become too large
C
      IF(ITER.NE.1 .AND. ABS(CHMX).GT.1.D16) THEN
         WRITE(6,"(' **** STOP in SOLVE after ITER',I4,/,
     * ' Max change:',1PE12.2)") ITER,CHMX
         WRITE(10,"(' **** STOP in SOLVE after ITER',I4,/,
     * ' Max change:',1PE12.2)") ITER,CHMX
         CALL CLOSEF
         STOP
      END IF

C     Reset iron lines cross-sections if changes are still large

      if(iter.le.1) LIROST=.FALSE.
      LITEK=.FALSE.
      if(iter.eq.7 .or. iter.eq.11 .or. iter.eq.15) LITEK=.TRUE.
      if(chmt.gt.chmaxt .and. ispodf.ge.1) LIROST=.TRUE.
      if(LITEK.and.LIROST) then
         call iroset
         LIROST=.FALSE.
      end if

C     Set up Kantorovich method

         IF(LASO) THEN
            WRITE(6,"(' **** KANTOROVICH acceleration: ITER',I4)") ITER
            WRITE(10,"(' **** KANTOROVICH acceleration: ITER',I4)") ITER
         END IF
c     END IF
C
C     Finally, set up quantity LFIN that indicates whether or not
C     this iteration of complete linearization is the last one
C
c     LFIN=ABS(CHMX).LE.CHMAX.OR.ITER.GE.NITER.OR.CHPOP.LE.10.*CHMX
      LFIN=ABS(CHMX).LE.CHMAX.OR.ITER.GE.NITER.OR.CHPOP.LE.10.*CHMAX

       write(67,*) 'iter,chmx',iter,chmx,chmax,chpop,'lfin=',lfin 

c     lfin=lfin.or.chmt.le.0.1*chmax

      RETURN
      END SUBROUTINE SOLVE
C
C
C     ****************************************************************
C
C
      SUBROUTINE MATGEN(ID)
C     =====================
C
C     Auxiliary procedure for SOLVE
C     controls evaluation of matrices A,B, and C
C
C     Input:  ID - depth index
C
      use accura
      use alipar
      use array1
      use atomic
      use basics
      use iterat
      use modelq

      implicit none

      INTEGER, INTENT(IN) :: ID
      INTEGER :: I,IJ,IJT,II,J,NSE,INONZ,JJ
C
C     evaluation of the opacity, emissivity, scattering, and
C     their derivatives, at the current depth point ID;
C
         DO I=1,NN
            PSI0(I)=PSY0(I,ID)
         END DO
         IF(NFREQE.GT.0) THEN
         DO IJ=1,NFREQE
            IJT=IJFR(IJ)
            WDEP0(IJ)=W(IJT)
            RAD0(IJ)=RADEX(IJ,ID)
            FK0(IJ)=FAKEX(IJ,ID)
            ABSO0(IJ)=ABSOEX(IJ,ID)
            EMIS0(IJ)=EMISEX(IJ,ID)
            SCAT0(IJ)=SCATEX(IJ,ID)
            DABT0(IJ)=DABTEX(IJ,ID)
            DEMT0(IJ)=DEMTEX(IJ,ID)
            DABN0(IJ)=DABNEX(IJ,ID)
            DEMN0(IJ)=DEMNEX(IJ,ID)
            DABM0(IJ)=DABMEX(IJ,ID)
            DEMM0(IJ)=DEMMEX(IJ,ID)
            DO II=1,NLVEXP
               DRCH0(II,IJ)=DRCHEX(II,IJ,ID)
               DRET0(II,IJ)=DRETEX(II,IJ,ID)
            END DO
         END DO
         END IF
C
      IF(ID.GT.1) THEN
         DO I=1,NN
            PSIM(I)=PSY0(I,ID-1)
         END DO
         IF(NFREQE.GT.0) THEN
         DO IJ=1,NFREQE
            IJT=IJFR(IJ)
            RADM(IJ)=RADEX(IJ,ID-1)
            FKM(IJ)=FAKEX(IJ,ID-1)
            ABSOM(IJ)=ABSOEX(IJ,ID-1)
            EMISM(IJ)=EMISEX(IJ,ID-1)
            SCATM(IJ)=SCATEX(IJ,ID-1)
            DABTM(IJ)=DABTEX(IJ,ID-1)
            DEMTM(IJ)=DEMTEX(IJ,ID-1)
            DABNM(IJ)=DABNEX(IJ,ID-1)
            DEMNM(IJ)=DEMNEX(IJ,ID-1)
            DABMM(IJ)=DABMEX(IJ,ID-1)
            DEMMM(IJ)=DEMMEX(IJ,ID-1)
            DO II=1,NLVEXP
               DRCHM(II,IJ)=DRCHEX(II,IJ,ID-1)
               DRETM(II,IJ)=DRETEX(II,IJ,ID-1)
            END DO
         END DO
         END IF
      END IF
C
      IF(ID.LT.ND) THEN
         DO I=1,NN
            PSIP(I)=PSY0(I,ID+1)
         END DO
         IF(NFREQE.GT.0) THEN
         DO IJ=1,NFREQE
            IJT=IJFR(IJ)
            RADP(IJ)=RADEX(IJ,ID+1)
            FKP(IJ)=FAKEX(IJ,ID+1)
            ABSOP(IJ)=ABSOEX(IJ,ID+1)
            EMISP(IJ)=EMISEX(IJ,ID+1)
            SCATP(IJ)=SCATEX(IJ,ID+1)
            DABTP(IJ)=DABTEX(IJ,ID+1)
            DEMTP(IJ)=DEMTEX(IJ,ID+1)
            DABNP(IJ)=DABNEX(IJ,ID+1)
            DEMNP(IJ)=DEMNEX(IJ,ID+1)
            DABMP(IJ)=DABMEX(IJ,ID+1)
            DEMMP(IJ)=DEMMEX(IJ,ID+1)
            DO II=1,NLVEXP
               DRCHP(II,IJ)=DRCHEX(II,IJ,ID+1)
               DRETP(II,IJ)=DRETEX(II,IJ,ID+1)
            END DO
         END DO
         END IF
      END IF
C
C
C     ------------------------------------------------------------
C     Actual evaluation of matrices A,B,C, and the rhs vector VECL
C     ------------------------------------------------------------
C
C     First null arrays A,B,C,VECL
C
      DO I=1,NN0
         VECL(I)=0.
         DO J=1,NN0
            B(J,I)=0.
            A(J,I)=0.
            C(J,I)=0.
CC          E(J,I)=0.
         END DO
      END DO
C
C     for the sake of clarity, the matrices are evaluated by several
C     different subroutines
C
      IF(IDISK.EQ.0) THEN
         CALL BRTE(ID)
         IF(INHE.NE.0) CALL BHE(ID)
         IF(INRE.NE.0) CALL BRE(ID)
CC     ELSE
CC       IF(IZSCAL.EQ.0)  THEN
CC          CALL BRTE(ID)
CC          IF(INHE.NE.0.or.inzd.ne.0) CALL BHED(ID)
CC          IF(INRE.NE.0) CALL BRE(ID)
CC        ELSE
CC          CALL BRTEZ(ID)
CC          IF(INHE.NE.0.or.inzd.ne.0) CALL BHEZ(ID)
CC          IF(INRE.NE.0) CALL BREZ(ID)
CC       END IF
      END IF
C
C     contribution to matrix elements due to convection
C
      CALL MATCON(ID)
C
      IF(INSE.GT.0) THEN
      CALL SABOLF(ID)
      CALL BPOP(ID)
CC    CALL EMAT(ID)
C
C     skip rows corresponding to fully-zeroed populations
C
      NSE=NFREQE+INSE
      INONZ=NSE
      DO II=NSE,NN0
         IF(IGZERT(II-NSE+1).EQ.0) THEN
          IF(INONZ.NE.II) THEN
             DO JJ=1,NN0
                B(INONZ,JJ)=B(II,JJ)
                A(INONZ,JJ)=A(II,JJ)
                C(INONZ,JJ)=C(II,JJ)
             END DO
             VECL(INONZ)=VECL(II)
          END IF
          INONZ=INONZ+1
       END IF
      END DO
C
C     skip also corresponding columns
C
      INONZ=NSE
      DO II=NSE,NN0
         IF(IGZERT(II-NSE+1).EQ.0) THEN
          IF(INONZ.NE.II) THEN
             DO JJ=1,NN
                B(JJ,INONZ)=B(JJ,II)
                A(JJ,INONZ)=A(JJ,II)
                C(JJ,INONZ)=C(JJ,II)
             END DO
          END IF
          INONZ=INONZ+1
       END IF
      END DO
      END IF
C
      RETURN
      END SUBROUTINE MATGEN
C
C
C     ****************************************************************
C
C
      SUBROUTINE BRTE(ID)
C     ===================
C
C     The part of matrices A,B,C corresponding to the linearized
C     radiative transfer equation
C     i.e. the first NFREQE rows
C
      use accura
      use alipar
      use array1
      use atomic
      use basics
      use iterat
      use modelq

      implicit none
C      
      INTEGER, INTENT(IN) :: ID
      REAL(DP), PARAMETER :: XCON=8.0935e-21,YCON=1.68638e-10
      REAL(DP), PARAMETER :: SIXTH=UN/6.0,THIRD=UN/3.0

      REAL(DP) :: GP,GN,DDP,DDM,OMEG0,OMEGP,OMEGM,DZP,DZM,DTAUP,DTAUM,
     *            DTAU0,ALF1,ALF2,BET1,BET2,GAM1,GAM2,CHIEL0,CHIELM,
     *            CHIELP,AS,BS,CS,A1,B1,C1,A2,B2,C2,A3,B3,C3,X,X1,
     *            S0,SM,SP,AL3,GA3,AV,CV,GAM3,
     *            RTN,RTNA,T,TM,HKT,HKTM,FR,FR15,EX,XM,EXM,
     *            PLAN,PLANM,DPLAN,DPLANM,DTAUI,RTNC,
     *            BET0,BB,B0,P0,RD,RDM,ED,EDM,P0RD,P0RDM,FRD,RADSUM

      REAL(DP) :: ZJ0,ZJ1,ZJ2,DLT,COMBID,COMAID,E2,ZXX0,ZXXM,ZXX,
     *            CMA,CMB,CMC,CME,CMS,CMD
      INTEGER  :: ISPL,NHE,NRE,NPC,NSE,NMP,IJ,IJ1,IJT,IJP,IJM,II,I,IJI
C
      IF(NFREQE.LE.0) RETURN
      ispl=isplin
      if(isplin.ge.5) isplin=isplin-5
      NHE=NFREQE+INHE
      NRE=NFREQE+INRE
      NPC=NFREQE+INPC
      NSE=NFREQE+INSE-1
      NMP=NFREQE+INMP
C
      GP=0.
      GN=UN
      IF(INMP.GT.0) THEN
         GP=UN
         GN=0.
      END IF
c
c     in the case of Compton scattering - boundary condition
c     for the highest frequency
C
      IJ1=1
      if(icompt.gt.0.and.icombc.gt.0.and.ijex(1).gt.0) then
         IJ1=2
         ij=1
         iji=nfreq
         zj1=exp(-hk*freq(ij)/temp(id))
         zj2=exp(-hk*freq(ij+1)/temp(id))
         dlt=delj(iji-1,id)
         if(ichcoo.eq.0) then
            zj0=un/(hk*sqrt(freq(ij)*freq(ij+1))/temp(id))
            zxx=un-3.*zj0+(un-dlt)*zj1+dlt*zj2
            combid=zj0/dlnfr(iji-1)+(un-dlt)*zxx
            comaid=-zj0/dlnfr(iji-1)+dlt*zxx
          else
            e2=ycon*temp(id)
            zxx0=xcon*freq(ij)*(un+zj1)-3.*e2
            zxxm=xcon*freq(ij+1)*(un+zj2)-3.*e2
            zxx=(un-dlt)*zxx0+dlt*zxxm
            combid=e2/dlnfr(iji-1)+(un-dlt)*zxx
            comaid=-e2/dlnfr(iji-1)+dlt*zxx
         end if
         b(ij,ij)=combid
         b(ij,ij+1)=comaid
         vecl(ij)=-b(ij,ij)*rad(iji,id)-b(ij,ij+1)*rad(iji-1,id)
      end if
C
C     ----------------------------------------
C     For  ID = 1  -  upper boundary condition
C     ----------------------------------------
C
      IF(ID.EQ.1) THEN
         DDP=(DM(2)-DM(1))*HALF
         DO IJ=IJ1,NFREQE
            IJT=IJFR(IJ)
            OMEG0=ABSO0(IJ)/DENS(ID)
            OMEGP=ABSOP(IJ)/DENS(ID+1)
            DZP=OMEG0+OMEGP
            DTAUP=DZP*DDP
            ALF1=(FK0(IJ)*RAD0(IJ)-FKP(IJ)*RADP(IJ))/DTAUP
            CHIEL0=SCAT0(IJ)
            CHIELP=SCATP(IJ)
            S0=(EMIS0(IJ)+CHIEL0*RAD0(IJ))/ABSO0(IJ)
            BS=HALF*DTAUP
            CS=0.
            C2=0.
            GAM2=0.
            BET2=0.
            SP=0.
c
c        additional terms for Compton scattering
c
            if(icompt.gt.0) then
               call compt0(ijt,id,abso0(ij),cma,cmb,cmc,cme,cms,cmd)
               s0=s0+cms
            end if
C
            IF(MOD(ISPLIN,3).GT.0) THEN
C
C      Spline collocation and/or Hermitian method (ISPLIN=1 or 2) -
C      both give the same expression for the boundary conditions
C
               BS=DTAUP*THIRD
               CS=HALF *BS
               SP=(EMISP(IJ)+CHIELP*RADP(IJ))/ABSOP(IJ)
               C2=CS/ABSOP(IJ)
               GAM2=CS*(RADP(IJ)-SP)
            END IF
C
C      auxiliary quantities
C
            ALF2=BS*(RAD0(IJ)-S0)
            BET2=ALF2+GAM2
            X1=(ALF1-BET2)/DZP
            B2=(BS+Q0(IJT))/ABSO0(IJ)
            B1=X1/DENS(1)
c           B1=B1+UU0(IJT)*S0*DM(1)*HALF/DENS(1)
            B1=B1+UU0(IJT)*S0*DM(1)/DENS(1)
            C1=X1/DENS(2)
C
C *** elements of the IJ-th row of matrices B and C
C
            RTN=OMEG0*WMM(1)*B1
            B(IJ,NHE)=-GN*RTN
            B1=B1-B2*S0
C
            RTNC=OMEGP*WMM(2)*C1
            C(IJ,NHE)=-GN*RTNC
            C1=C1-C2*SP
C
            B(IJ,NRE)=B1*DABT0(IJ)+B2*(DEMT0(IJ)+DST*RAD0(IJ))
            C(IJ,NRE)=C1*DABTP(IJ)+C2*(DEMTP(IJ)+DST*RADP(IJ))
            B(IJ,NPC)=B1*DABN0(IJ)+
     *             B2*(DEMN0(IJ)+(DSN+SIGEC(IJT))*RAD0(IJ))+
     *             GN*RTN
            C(IJ,NPC)=C1*DABNP(IJ)+
     *             C2*(DEMNP(IJ)+(DSN+SIGEC(IJT))*RADP(IJ))+
     *             GN*RTNC
            B(IJ,NMP)=B1*DABM0(IJ)+B2*DEMM0(IJ)-GP*RTN
            C(IJ,NMP)=C1*DABMP(IJ)+C2*DEMMP(IJ)-GP*RTNC
            DO II=1,NLVEXP
                B(IJ,NSE+II)=B(IJ,NSE+II)+
     *                    B1*DRCH0(II,IJ)+B2*DRET0(II,IJ)
                C(IJ,NSE+II)=C(IJ,NSE+II)+
     *                    C1*DRCHP(II,IJ)+C2*DRETP(II,IJ)
            END DO
            B(IJ,NFREQE)=0.
            B(IJ,IJ)=-FK0(IJ)/DTAUP-FH(IJT)-BS*(UN-CHIEL0/ABSO0(IJ))
     *            +Q0(IJT)*CHIEL0/ABSO0(IJ)
            C(IJ,NFREQE)=0.
            C(IJ,IJ)=FKP(IJ)/DTAUP-CS*(UN-CHIELP/ABSOP(IJ))
C
C *** the IJ-th element of the rhs vector
C
            VECL(IJ)=ALF1+BET2+FH(IJT)*RAD0(IJ)
     *          -S0*Q0(IJT)
           IF(IWINBL.LT.0) VECL(IJ)=VECL(IJ)-HEXTRD(IJT)
c
c        additional terms for Compton scattering
c
            if(icompt.gt.4) then
               iji=nfreq-kij(ijt)+1
               b(ij,ij)=b(ij,ij)+bs*(cmb+cme)
               if(iji.gt.1) then
                  ijm=ijex(ijorig(iji-1))
                  if(ijm.gt.0) b(ij,ijm)=b(ij,ijm)+bs*cma
               end if
               if(iji.lt.nfreq) then
                  ijp=ijex(ijorig(iji+1))
                  if(ijp.gt.0) b(ij,ijp)=b(ij,ijp)+bs*cmc
               end if
               if(inre.gt.0) b(ij,nre)=b(ij,nre)+cmd*bs
               if(inpc.gt.0) b(ij,npc)=b(ij,npc)+cms*bs/elec(id)
            end if
         END DO

       ELSE IF (ID.LT.ND) THEN
C
C     ---------------------------------------
C     For  1 < ID < ND  -  normal depth point
C     ---------------------------------------
C
         DDM=(DM(ID)-DM(ID-1))*HALF
         DDP=(DM(ID+1)-DM(ID))*HALF
         DO IJ=IJ1,NFREQE
            IJT=IJFR(IJ)
            OMEG0=ABSO0(IJ)/DENS(ID)
            OMEGP=ABSOP(IJ)/DENS(ID+1)
            OMEGM=ABSOM(IJ)/DENS(ID-1)
            DZP=OMEG0+OMEGP
            DZM=OMEG0+OMEGM
            DTAUP=DZP*DDP
            DTAUM=DZM*DDM
            DTAU0=HALF *(DTAUP+DTAUM)
            FRD=FK0(IJ)*RAD0(IJ)
            ALF1=(FRD-FKP(IJ)*RADP(IJ))/DTAUP/DTAU0
            GAM1=(FRD-FKM(IJ)*RADM(IJ))/DTAUM/DTAU0
            BET1=ALF1+GAM1
            X1=HALF *BET1/DTAU0
            A1=(GAM1+X1*DTAUM)/DZM
            C1=(ALF1+X1*DTAUP)/DZP
            B1=(A1+C1)/DENS(ID)
            A1=A1/DENS(ID-1)
            C1=C1/DENS(ID+1)
            BS=UN
            CHIELM=SCATM(IJ)
            CHIEL0=SCAT0(IJ)
            CHIELP=SCATP(IJ)
            S0=(EMIS0(IJ)+CHIEL0*RAD0(IJ))/ABSO0(IJ)
            AS=0.
            CS=0.
            A2=0.
            C2=0.
            A3=0.
            C3=0.
            BET2=0.
            SM=0.
            SP=0.
c
c        additional terms for Compton scattering
c
            if(icompt.gt.0) then
               call compt0(ijt,id,abso0(ij),cma,cmb,cmc,cme,cms,cmd)
               s0=s0+cms
            end if
C
            IF(MOD(ISPLIN,3).NE.0) THEN
               SM=(EMISM(IJ)+RADM(IJ)*CHIELM)/ABSOM(IJ)
               SP=(EMISP(IJ)+RADP(IJ)*CHIELP)/ABSOP(IJ)
               IF(ISPLIN.EQ.1) THEN
C
C     spline collocation (ISPLIN=1)
C
                  AS=DTAUM/DTAU0*SIXTH
                  CS=DTAUP/DTAU0*SIXTH
                  BS=0.666666666666667
                  ALF2=AS*(RADM(IJ)-SM)
                  GAM2=CS*(RADP(IJ)-SP)
                  BET2=ALF2+GAM2
                  X =HALF *BET2/DTAU0
                  A2=(GAM2-X*DTAUM)/DZM
                  C2=(ALF2-X*DTAUP)/DZP
                ELSE
C
C     Hermitian method (ISPLIN=2)
C
                  AS=DTAUP*DTAUP/DTAUM/DTAU0
                  CS=DTAUM*DTAUM/DTAUP/DTAU0
                  AL3=(RADP(IJ)-SP-RAD0(IJ)+S0)*SIXTH
                  GA3=(RADM(IJ)-SM-RAD0(IJ)+S0)*SIXTH
                  AV=AL3*CS
                  CV=GA3*AS
                  AS=(UN-HALF *AS)*SIXTH
                  CS=(UN-HALF *CS)*SIXTH
                  BS=UN-AS-CS
                  X=(AV+CV)/DTAU0/4.D0
                  A2=(X*DTAUM+HALF *CV-AV)/DZM
                  C2=(X*DTAUP+HALF *AV-CV)/DZP
                  BET2=AS*(RADM(IJ)-SM)+CS*(RADP(IJ)-SP)
               END IF
C
C     auxiliary quantities
C
               B1=B1-(A2+C2)/DENS(ID)
               A1=A1-A2/DENS(ID-1)
               C1=C1-C2/DENS(ID+1)
               A2=AS/ABSOM(IJ)
               C2=CS/ABSOP(IJ)
               A3=A2*SM
               C3=C2*SP
            END IF

            B2=BS/ABSO0(IJ)
            B3=B2*S0
C
C *** elements of the IJ-th row of matrices A, B, and C
C
            RTNA=OMEGM*WMM(ID-1)*A1
            A(IJ,NHE)=-GN*RTNA
            A1=A1-A3
C
            RTN=OMEG0*WMM(ID)*B1
            B(IJ,NHE)=-GN*RTN
            B1=B1-B3
C
            RTNC=OMEGP*WMM(ID+1)*C1
            C(IJ,NHE)=-GN*RTNC
            C1=C1-C3
C
            A(IJ,NRE)= A1*DABTM(IJ)+A2*(DEMTM(IJ)+DST*RADM(IJ))
            B(IJ,NRE)= B1*DABT0(IJ)+B2*(DEMT0(IJ)+DST*RAD0(IJ))
            C(IJ,NRE)= C1*DABTP(IJ)+C2*(DEMTP(IJ)+DST*RADP(IJ))
            A(IJ,NPC)= A1*DABNM(IJ)+
     *              A2*(DEMNM(IJ)+(DSN+SIGEC(IJT))*RADM(IJ))+
     *              GN*RTNA
            B(IJ,NPC)= B1*DABN0(IJ)+
     *              B2*(DEMN0(IJ)+(DSN+SIGEC(IJT))*RAD0(IJ))+
     *              GN*RTN
            C(IJ,NPC)= C1*DABNP(IJ)+
     *              C2*(DEMNP(IJ)+(DSN+SIGEC(IJT))*RADP(IJ))+
     *              GN*RTNC
            A(IJ,NMP)= A1*DABMM(IJ)+A2*DEMMM(IJ)-GP*RTNA
            B(IJ,NMP)= B1*DABM0(IJ)+B2*DEMM0(IJ)-GP*RTN
            C(IJ,NMP)= C1*DABMP(IJ)+C2*DEMMP(IJ)-GP*RTNC
            DO II=1,NLVEXP
               A(IJ,NSE+II)=A(IJ,NSE+II)+
     *                   A1*DRCHM(II,IJ)+A2*DRETM(II,IJ)
               B(IJ,NSE+II)=B(IJ,NSE+II)+
     *                   B1*DRCH0(II,IJ)+B2*DRET0(II,IJ)
               C(IJ,NSE+II)=C(IJ,NSE+II)+
     *                   C1*DRCHP(II,IJ)+C2*DRETP(II,IJ)
            END DO
            A(IJ,NFREQE)=0.
            A(IJ,IJ)=FKM(IJ)/DTAUM/DTAU0-AS*(UN-CHIELM/ABSOM(IJ))
            B(IJ,NFREQE)=0.
            B(IJ,IJ)=-FK0(IJ)/DTAU0*(UN/DTAUP+UN/DTAUM)-
     *             BS*(UN-CHIEL0/ABSO0(IJ))
            C(IJ,NFREQE)=0.
            C(IJ,IJ)=FKP(IJ)/DTAUP/DTAU0-CS*(UN-CHIELP/ABSOP(IJ))
C
C *** the IJ-th element of the rhs vector
C
            VECL(IJ)=BET1+BET2+BS*(RAD0(IJ)-S0)
c
c        additional terms for Compton scattering
c
            if(icompt.gt.4) then
               iji=nfreq-kij(ijt)+1
               b(ij,ij)=b(ij,ij)+bs*(cmb+cme)
               if(iji.gt.1) then
                  ijm=ijex(ijorig(iji-1))
                  if(ijm.gt.0) b(ij,ijm)=b(ij,ijm)+bs*cma
               end if
               if(iji.lt.nfreq) then
                  ijp=ijex(ijorig(iji+1))
                  if(ijp.gt.0) b(ij,ijp)=b(ij,ijp)+bs*cmc
               end if
               if(inre.gt.0) b(ij,nre)=b(ij,nre)+cmd*bs
               if(inpc.gt.0) b(ij,npc)=b(ij,npc)+cms*bs/elec(id)
            end if
c
         END DO
      
       ELSE
C
C   --------------------------------------
C   For ID=ND  -  lower boundary condition
C   --------------------------------------
C
         DDM= HALF*(DM(ID)-DM(ID-1))
         IF(IDISK.EQ.0.OR.IFZ0.LT.0) THEN
            IF(IBC.EQ.-1) THEN
               T=TEMP(ID)
               TM=TEMP(ID-1)
               IF(TEMPBD.NE.0.) THEN
                  T=TEMPBD
                  TM=T
               END IF
               HKT=HK/T
               HKTM=HK/TM
C
C     auxiliary quantites
C
               DO IJ=IJ1,NFREQE
                  IJT=IJFR(IJ)
                  CHIELM=SCATM(IJ)
                  CHIEL0=SCAT0(IJ)
                  OMEGM=ABSOM(IJ)/DENS(ID-1)
                  OMEG0=ABSO0(IJ)/DENS(ID)
                  DZM=OMEG0+OMEGM
                  DTAUM=DZM*DDM
                  FRD=FK0(IJ)*RAD0(IJ)-FKM(IJ)*RADM(IJ)
                  GAM1=FRD/DTAUM
                  A1=GAM1/DZM
                  AS=0.
                  BS=0.
                  A2=0.
                  B2=0.
                  A3=0.
                  B3=0.
                  ALF2=0.
                  BET2=0.
                  GAM2=0.
CCC ****TENTATIVE
                  GAM3=0.
CCC END TENTATIVE
C
C        second-order boundary condition
C
                  BS=DTAUM*HALF
                  S0=(EMIS0(IJ)+CHIEL0*RAD0(IJ))/ABSO0(IJ)
c
c        additional terms for Compton scattering
c
                  if(icompt.gt.0) then
                      call compt0(ijt,id,abso0(ij),cma,cmb,cmc,cme,cms,
     *                            cmd)
                      s0=s0+cms
                  end if
C
                  BET2=BS*(RAD0(IJ)-S0)
                  X1=BET2/DZM
                  A1=GAM1/DZM-X1
                  B2=BS/ABSO0(IJ)
                  B3=B2*S0
C
C     auxiliary parameters
C
                  FR=FREQ(IJT)
                  FR15=FR*1.D-15
                  X=HKT*FR
                  EX=EXP(X)
                  XM=HKTM*FR
                  EXM=EXP(XM)
                  PLAN=BN*FR15*FR15*FR15/(EX-UN)*RRDIL
                  A1=A1-GAM3/DZM
                  GAM1=GAM1-GAM3
                  C1=A1
                  A1=C1/DENS(ID-1)
                  B1=C1/DENS(ID)
C
C *** elements of the IJ-th row of matrices A and B
C
                  RTNA=OMEGM*WMM(ID-1)*A1
                  A(IJ,NHE)=-GN*RTNA
C
                  RTN=OMEG0*WMM(ID)*B1
                  B(IJ,NHE)=-GN*RTN
                  B1=B1-B3
C
                  PLANM=BNUE(IJT)/(EXM-UN)*RRDIL
                  DPLANM=PLANM*XM/TM/(UN-UN/EXM)
                  A(IJ,NRE)=A1*DABTM(IJ)+A2*(DEMTM(IJ)+DST*RADM(IJ))-
     *              DPLANM/DTAUM*THIRD
                  A(IJ,NPC)=A1*DABNM(IJ)+
     *              A2*(DEMNM(IJ)+(DSN+SIGEC(IJT))*RADM(IJ))+
     *              GN*RTNA
                  BB=HALF+THIRD/DTAUM
                  DPLAN=PLAN*X/T/(UN-UN/EX)
                  B(IJ,NRE)= B1*DABT0(IJ)+B2*(DEMT0(IJ)+DST*RAD0(IJ))+
     *              BB*DPLAN
                  B(IJ,NPC)= B1*DABN0(IJ)+
     *              B2*(DEMN0(IJ)+(DSN+SIGEC(IJT))*RAD0(IJ))+
     *              GN*RTN
                  A(IJ,NMP)= A1*DABMM(IJ)+A2*DEMMM(IJ)-GP*RTNA
                  B(IJ,NMP)= B1*DABM0(IJ)+B2*DEMM0(IJ)-GP*RTN
                  DO II=1,NLVEXP
                     A(IJ,NSE+II)=A(IJ,NSE+II)+
     *                      A1*DRCHM(II,IJ)+A2*DRETM(II,IJ)
                     B(IJ,NSE+II)=B(IJ,NSE+II)+
     *                   B1*DRCH0(II,IJ)+B2*DRET0(II,IJ)
                  END DO
                  A(IJ,NFREQE)=0.
                  A(IJ,IJ)=FKM(IJ)/DTAUM-AS*(UN-CHIELM/ABSOM(IJ))
                  B(IJ,NFREQE)=0.
C
C *** the IJ-th element of the rhs vector
C
                  IF(IBC.EQ.0.OR.IBC.EQ.4) THEN
                     B(IJ,IJ)=B(IJ,IJ)-FK0(IJ)/DTAUM-
     *               BS*(UN-CHIEL0/ABSO0(IJ))-HALF
                     VECL(IJ)=GAM1+BET2-HALF*(PLAN-RAD0(IJ))
                   ELSE
                     B(IJ,IJ)=B(IJ,IJ)-FK0(IJ)/DTAUM-
     *               BS*(UN-CHIEL0/ABSO0(IJ))-FHD(IJT)
                     VECL(IJ)=GAM1+BET2-HALF*PLAN+FHD(IJT)*RAD0(IJ)
                  END IF
c
c        additional terms for Compton scattering
c
                  if(icompt.gt.4) then
                     iji=nfreq-kij(ijt)+1
                     b(ij,ij)=b(ij,ij)+bs*(cmb+cme)
                     if(iji.gt.1) then
                        ijm=ijex(ijorig(iji-1))
                        if(ijm.gt.0) b(ij,ijm)=b(ij,ijm)+bs*cma
                     end if
                     if(iji.lt.nfreq) then
                        ijp=ijex(ijorig(iji+1))
                        if(ijp.gt.0) b(ij,ijp)=b(ij,ijp)+bs*cmc
                     end if
                     if(inre.gt.0) b(ij,nre)=b(ij,nre)+cmd*bs
                     if(inpc.gt.0) b(ij,npc)=b(ij,npc)+cms*bs/elec(id)
                  end if

               END DO

            ELSE
C
C---  new formulation
C
               DDM= HALF*(DM(ID)-DM(ID-1))
               T=TEMP(ID)
               TM=TEMP(ID-1)
               HKT=HK/T
               HKTM=HK/TM
               DO IJ=IJ1,NFREQE
                  IJT=IJFR(IJ)
                  FR=FREQ(IJT)
                  EX=EXP(HKT*FR)
                  EXM=EXP(HKTM*FR)
                  PLAN=BNUE(IJT)/(EX-UN)*RRDIL
                  DPLAN=PLAN/(UN-UN/EX)*HKT*FR/T
                  PLANM=BNUE(IJT)/(EXM-UN)*RRDIL
                  DPLANM=PLANM/(UN-UN/EXM)*HKTM*FR/TM
C
                  DTAUM=DDM*(ABSO0(IJ)/DENS(ID)+ABSOM(IJ)/DENS(ID-1))
                  DTAUI=UN/DTAUM
                  GAM3=(FK0(IJ)*RAD0(IJ)-FKM(IJ)*RADM(IJ))*DTAUI
                  S0=(EMIS0(IJ)+SCAT0(IJ)*RAD0(IJ))/ABSO0(IJ)
                  BS=DTAUM*HALF
                  BET0=BS*(RAD0(IJ)-S0)
                  BB=PLAN*HALF+(PLAN-PLANM)*DTAUI*THIRD
                  B0=-(PLAN-PLANM)*DTAUI**2*THIRD
                  P0=(GAM3-BET0)*DTAUI+B0
                  RD=DDM/DENS(ID)
                  RDM=DDM/DENS(ID-1)
                  ED=ABSO0(IJ)/DENS(ID)*WMM(ID)
                  EDM=ABSOM(IJ)/DENS(ID-1)*WMM(ID-1)
                  P0RD=P0*RD
                  P0RDM=P0*RDM
C
                  B(IJ,NRE)=P0RD*DABT0(IJ)
     *               +BS/ABSO0(IJ)*(DEMT0(IJ)-S0*DABT0(IJ))
     *               +DPLAN*(HALF+THIRD*DTAUI)
                  A(IJ,NRE)=P0RDM*DABTM(IJ)-DPLANM*THIRD*DTAUI
                  B(IJ,NPC)=P0RD*(DABN0(IJ)+GN*ED)
     *            +BS/ABSO0(IJ)*(DEMN0(IJ)-S0*DABN0(IJ)
     *            +RAD0(IJ)*SIGEC(IJT))
                  A(IJ,NPC)=P0RDM*(DABNM(IJ)+GN*EDM)
                  B(IJ,NHE)=-GN*P0RD*ED
                  A(IJ,NHE)=-GN*P0RDM*EDM
                  B(IJ,NMP)=-GP*P0RD*ED
                  A(IJ,NMP)=-GP*P0RDM*EDM
                  DO II=1,NLVEXP
                     B(IJ,NSE+II)=P0RD*DRCH0(II,IJ)+
     *                   BS/ABSO0(IJ)*(DRET0(II,IJ)-S0*DRCH0(II,IJ))
                     A(IJ,NSE+II)=P0RDM*DRCHM(II,IJ)
                  END DO
C
                  B(IJ,NFREQE)=0.
                  A(IJ,NFREQE)=0.
                  B(IJ,IJ)=-FK0(IJ)*DTAUI-FHD(IJT)-
     *                   BS*(UN-SCAT0(IJ)/ABSO0(IJ))
                  A(IJ,IJ)=FKM(IJ)*DTAUI
                  VECL(IJ)=GAM3+BET0+FHD(IJT)*RAD0(IJ)-BB
c          write(*,"(a,i3,1p6e12.4)") 
c    *     'vecl',ij,gam3,bet0,fhd(ijt),rad0(ij),bb,vecl(ij)
               END DO
            END IF
C   
C---- end of new formulation
C
         ELSE
C
C   --------------------------------------
C   For ID=ND  -  lower boundary condition - for disks
C   --------------------------------------
C     lower b.c. expresses just I(taumax,-mu,nu)=I(taumax,+mu,nu)
C
            DO IJ=IJ1,NFREQE
               IJT=IJFR(IJ)
               CHIELM=SCATM(IJ)
               CHIEL0=SCAT0(IJ)
               OMEGM=ABSOM(IJ)/DENS(ID-1)
               OMEG0=ABSO0(IJ)/DENS(ID)
               DZM=OMEG0+OMEGM
               DTAUM=DZM*DDM
               FRD=FK0(IJ)*RAD0(IJ)-FKM(IJ)*RADM(IJ)
               GAM1=FRD/DTAUM
               A1=GAM1/DZM
               AS=0.
               A2=0.
               A3=0.
               ALF2=0.
               GAM2=0.
               BS=DTAUM*HALF
               S0=(EMIS0(IJ)+CHIEL0*RAD0(IJ))/ABSO0(IJ)
c
c        additional terms for Compton scattering
c
               if(icompt.gt.0) then
                  call compt0(ijt,id,abso0(ij),cma,cmb,cmc,cme,cms,cmd)
                  s0=s0+cms
               end if
C
               GAM2=BS*(RAD0(IJ)-S0)
               BET2=ALF2+GAM2
               X1=BET2/DZM
               A1=A1-X1
               B2=BS/ABSO0(IJ)
               B3=B2*S0
               C1=A1
               A1=C1/DENS(ID-1)
               B1=C1/DENS(ID)
C
C *** elements of the IJ-th row of matrix A
C
               RTN=OMEGM*WMM(ID)*A1
               A(IJ,NHE)=-GN*RTN
               A(IJ,NMP)=-GP*RTN
               A1=A1-A3
               A(IJ,NRE)=A1*DABTM(IJ)+A2*(DEMTM(IJ)+DST*RADM(IJ))
               A(IJ,NPC)=A1*DABNM(IJ)+
     *              A2*(DEMNM(IJ)+(DSN+SIGEC(IJT))*RADM(IJ))+
     *              GN*RTN
               A(IJ,NMP)= A1*DABMM(IJ)+A2*DEMMM(IJ)-GP*RTN
               DO I=1,NLVEXP
                  A(IJ,NSE+I)=A1*DRCHM(I,IJ)+A2*DRETM(I,IJ)
               END DO
               A(IJ,NFREQE)=0.
               A(IJ,IJ)=FKM(IJ)/DTAUM-AS*(UN-CHIELM/ABSOM(IJ))
C
C *** elements of the IJ-th row of matrix B
C
               RTN=OMEG0*WMM(ID)*B1
               B(IJ,NHE)=-GN*RTN
               B(IJ,NMP)=-GP*RTN
               B1=B1-B3
               B(IJ,NRE)=B1*DABT0(IJ)+B2*(DEMT0(IJ)+DST*RAD0(IJ))
               B(IJ,NPC)=B1*DABN0(IJ)+
     *              B2*(DEMN0(IJ)+(DSN+SIGEC(IJT))*RAD0(IJ))+
     *              GN*RTN
               B(IJ,NMP)= B1*DABM0(IJ)+B2*DEMM0(IJ)-GP*RTN
               DO I=1,NLVEXP
                  B(IJ,NSE+I)=B1*DRCH0(I,IJ)+B2*DRET0(I,IJ)
               END DO
               B(IJ,NFREQE)=0.
               B(IJ,IJ)=-FK0(IJ)/DTAUM-BS*(UN-CHIEL0/ABSO0(IJ))
C
C *** the IJ-th element of the rhs vector
C
               VECL(IJ)=GAM1+BET2
c
c        additional terms for Compton scattering
c
               if(icompt.gt.4) then
                  iji=nfreq-kij(ijt)+1
                  b(ij,ij)=b(ij,ij)+bs*(cmb+cme)
                  if(iji.gt.1) then
                     ijm=ijex(ijorig(iji-1))
                     if(ijm.gt.0) b(ij,ijm)=b(ij,ijm)+bs*cma
                  end if
                  if(iji.lt.nfreq) then
                     ijp=ijex(ijorig(iji+1))
                     if(ijp.gt.0) b(ij,ijp)=b(ij,ijp)+bs*cmc
                  end if
                  if(inre.gt.0) b(ij,nre)=b(ij,nre)+cmd*bs
                  if(inpc.gt.0) b(ij,npc)=b(ij,npc)+cms*bs/elec(id)
               end if

            END DO
         END IF
      END IF

      ISPLIN=ISPL
c
c     zeroing radiation field for very low intensities (if required)
c
      if(radzer.gt.0) then
c
C     find the peak in nu*rad_nu:
c
         radsum=0.
         DO IJ=IJ1,NFREQE
             radsum=max(freq(ij)*radex(ij,id),radsum)
         END DO
C
C        if much smaller than peak in nu*rad_nu, then set to zero:
C
         DO IJ=IJ1,NFREQE
            if(freq(ij)*radex(ij,id).lt.radzer*radsum) then
               do ii=1,nn0
                  a(ij,ii)=0.
                  b(ij,ii)=0.
                  c(ij,ii)=0.
               end do
               vecl(ij)=0.
               b(ij,ij)=un
            end if
       end do
      end if
      isplin=ispl
      isplin=ispl
c
      RETURN
      END SUBROUTINE BRTE
C
C
C     ****************************************************************
C
!     include 'modules.f'
!     program sol2tes
!     write(*,*) 'a'
!     end program sol2tes
C
C
C     ****************************************************************
C
C
      SUBROUTINE BHE(ID)
C     ==================
C
C     The part of matrices A and B corresponding to the hydrostatic
C     equilibrium equation,
C     i.e. the (NFREQE+INHE)-th row;
C     and, if desired (INMP > 0), the part corresponding to the
C     definition equation for the fictitious massive particle density,
C     ie. the (NFREQE+INMP)-th row.
C
C     Input:  ID - depth index
C
      use accura
      use alipar
      use array1
      use atomic
      use basics
      use iterat
      use modelq

      implicit none

      INTEGER, INTENT(IN) :: ID
      REAL(DP) :: GP,GN,HEXT,HEXN,HEXM,HEXQ,HEXE,GRP,FLUXW,X1,X2,
     *            WW,WFJ,WFQ,WEUR,WEQ,RTN,VT0,VTM,PCX
      INTEGER  :: NHE,NRE,NPC,NSE,NMP,I,IJ,IJT,II
C
      NHE=NFREQE+INHE
      NRE=NFREQE+INRE
      NPC=NFREQE+INPC
      NSE=NFREQE+INSE-1
C
      GP=0.
      GN=UN
      IF(INMP.GT.0) THEN
         GP=UN
         GN=0.
      END IF
c
c     the case of fixed mass density
c
      if(ifixde.gt.0) then
         b(nhe,nhe)=un
         b(nhe,npc)=-un
         vecl(nhe)=dens(id)/wmm(id)+elec(id)-totn(id)
         return
      end if
C
C ***********  Linearized equation for the fictitious massive particle
C              density
C
      IF(INMP.GT.0) THEN
         NMP=NFREQE+INMP
         B(NMP,NMP)=-UN
         B(NMP,NHE)=UN
         IF(INPC.GT.0) B(NMP,NPC)=-UN
      END IF
C
C ***********  Linearized hydrostatic equilibrium
C
      HEXT=0.
      HEXN=0.
      HEXM=0.
      GRP=0.
      FLUXW=0.

      IF(ID.EQ.1) THEN
C
C *** Upper boundary condition (ID=1)
C     Basically, linearized eq. (7-10) of Mihalas (1978)
C
         DO I=1,NLVEXP
            HEX(I)=0.
         END DO
         X1=PCK/DENS(ID)
         X2=X1/DENS(ID)*WMM(ID)
         IF(NFREQE.GT.0.AND.IFPRAD.GT.0) THEN
            DO IJ=1,NFREQE
               IJT=IJFR(IJ)
               IF(.NOT.LSKIP(ID,IJT)) THEN
                  WW=W(IJT)
                  WFJ=WW*FH(IJT)*RAD0(IJ)
                  WFQ=WW*Q0(IJT)
                  WEUR=WW*EMIS0(IJ)*UU0(IJT)*ABSO0(IJ)
                  WEQ=WW*EMIS0(IJ)*Q0(IJT)
                  GRP=GRP+WFJ*ABSO0(IJ)-WFQ*EMIS0(IJ)
                  HEXT=HEXT+(WFJ-WEUR)*DABT0(IJ)-WFQ*DEMT0(IJ)
                  HEXN=HEXN+(WFJ-WEUR)*DABN0(IJ)-WFQ*DEMN0(IJ)
                  HEXM=HEXM+WEUR
                  HEXQ=HEXQ+WEQ
                  HEXE=HEXE+WEUR*ABSO0(IJ)
                  DO I=1,NLVEXP
                     HEX(I)=HEX(I)+WFJ*DRCH0(I,IJ)-WFQ*DRET0(I,IJ)
                  END DO
C
C              Columns corresponding to mean intensities
C
                  B(NHE,IJ)=X1*W(IJT)*FH(IJT)*ABSO0(IJ)
               END IF
            END DO
         END IF
C
         RTN=X1*WMM(ID)/DENS(ID)*(GRP+FPRD(ID))
         VT0=HALF*VTURB(ID)*VTURB(ID)/DM(ID)*WMM(ID)
C
C     columns corresponding to total particle density, fictitious
C     massive particle density, temperature, and electron density,
C     respectively
C
         B(NHE,NHE)=BOLK*TEMP(ID)/DM(ID)-GN*(RTN-VT0)
     *          +X1*EE0*(HEXM+HEIM(ID))
     *          -X2*(GRP+FPRD(ID))
         IF(INMP.GT.0) B(NHE,NFREQE+INMP)=GP*(VT0-RTN)
         IF(INRE.GT.0) THEN
            B(NHE,NRE)=BOLK*TOTN(ID)/DM(1)+X1*(HEXT+HEIT(ID))
            C(NHE,NRE)=X1*HEITP(ID)
         END IF
         IF(INPC.GT.0) THEN
            B(NHE,NPC)=X1*(HEXN+HEIN(ID)-(HEXM+HEIM(ID)*EE0))+
     *                 GN*(RTN-VT0)
     *             +X2*(GRP+FPRD(ID))
            C(NHE,NPC)=X1*HEINP(ID)
         END IF
C
C     Columns corresponding to populations
C
         DO II=1,NLVEXP
             B(NHE,NSE+II)=B(NHE,NSE+II)+X1*(HEX(II)+HEIP(II,ID))
             C(NHE,NSE+II)=C(NHE,NSE+II)+X1*HEIPP(II,ID)
         END DO
C
C     The rhs vector also accounts for the total radiation pressure in
C     the fixed-option transitions (array FPRD, generated by FIXLIN)
C
         VECL(NHE)=GRAV-BOLK*TEMP(ID)*TOTN(ID)/DM(ID)-
     *          X1*(GRP+FPRD(ID))-VT0/WMM(ID)*DENS(ID)
         RETURN

       ELSE
C
C *** Normal depth point (ID > 1)
C
C     Columns (for matrices A and B) corresponding to mean intensities
C
         PCX=PCK*FPRAD(ID)
         IF(NFREQE.GT.0.and.ifprad.gt.0) THEN
         DO IJ=1,NFREQE
            IF(.NOT.LSKIP(ID,IJFR(IJ))) THEN
            GRP=GRP+(FK0(IJ)*RAD0(IJ)-FKM(IJ)*RADM(IJ))*W(IJFR(IJ))
            A(NHE,IJ)=-PCX*W(IJFR(IJ))*FKM(IJ)
            B(NHE,IJ)=PCX*W(IJFR(IJ))*FK0(IJ)
            END IF
         END DO
         END IF
C
         VT0=HALF*VTURB(ID)*VTURB(ID)*WMM(ID)
         VTM=HALF*VTURB(ID-1)*VTURB(ID-1)*WMM(ID-1)
C
C     columns corresponding to total particle density
C
         A(NHE,NHE)=-BOLK*TEMP(ID-1)-GN*VTM
         B(NHE,NHE)=BOLK*TEMP(ID)+GN*VT0
C
C     columns corresponding to temperature
C
         IF(INRE.GT.0) THEN
            A(NHE,NRE)=-BOLK*TOTN(ID-1)+PCX*HEITM(ID)
            B(NHE,NRE)=BOLK*TOTN(ID)+PCX*HEIT(ID)
            C(NHE,NRE)=PCX*HEITP(ID)
         END IF
C
C     columns corresponding to electron density
C
         IF(INPC.GT.0) THEN
            A(NHE,NPC)=GN*VTM+PCX*HEINM(ID)
            B(NHE,NPC)=-GN*VT0+PCX*HEIN(ID)
            C(NHE,NPC)=PCX*HEINP(ID)
         END IF
C
C     columns corresponding to NMP
C
         IF(INMP.GT.0) THEN
            A(NHE,NFREQE+INMP)=-GP*VTM
            B(NHE,NFREQE+INMP)=GP*VT0
         END IF
C
C     columns corresponding to populations
C
         DO II=1,NLVEXP
            A(NHE,NSE+II)=PCX*HEIPM(II,ID)
            B(NHE,NSE+II)=PCX*HEIP(II,ID)
            C(NHE,NSE+II)=PCX*HEIPP(II,ID)
         END DO
C
C     the rhs vector
C     again, which accounts for the total radiation pressure in the
C     fixed-option transitions (array FPRD)
C
         VECL(NHE)=GRAV*(DM(ID)-DM(ID-1))-
     *          BOLK*(TEMP(ID)*TOTN(ID)-TEMP(ID-1)*TOTN(ID-1))-
     *          PCX*(GRP+FPRD(ID))-
     *          VT0/WMM(ID)*DENS(ID)+VTM/WMM(ID-1)*DENS(ID-1)
      END IF

      RETURN
      END SUBROUTINE BHE
C
C
C     ****************************************************************
C
C
      SUBROUTINE BRE(ID)
C     ==================
C
C     The part of matrices A and B corresponding to the radiative
C     equilibrium equation
C     i.e. the (NFREQE+INRE)-th row
C
C     Input:  ID  - depth index
C
      use accura
      use alipar
      use array1
      use atomic
      use basics
      use iterat
      use modelq

      implicit none

      INTEGER, INTENT(IN) :: ID
C      
      REAL(DP) :: BREPC,BREMP,HEAT,TEFFD,AREN,BREN,AREPC,GP,GN,DDM,
     *            OMEG0,OMEGM,DTAUM,FRD,GAMR,A1,A3R,B3R,RTR,WF
      REAL(DP) :: CMA,CMB,CMC,CMD,CME,CMS
      INTEGER  :: NHE,NRE,NPC,NSE,NMP,I,IJ,IJI,IJ1,IJT,IJM,IJP,II,ITTC
      REAL(DP) :: REXB(MLEVEL)
C
      NHE=NFREQE+INHE
      NRE=NFREQE+INRE
      NPC=NFREQE+INPC
      NMP=NFREQE+INMP
      NSE=NFREQE+INSE-1
      IJ1=1
      if(icompt.gt.0.and.icombc.gt.0.and.ijex(1).gt.0) IJ1=2
C
      ittc=abs(nretc)/100
      if(iter.gt.ittc) then
         if(id.le.mod(abs(nretc),100)) then
            b(nre,nre)=1.
            if(nretc.lt.0) then
               c(nre,nre)=-1.
               vecl(nre)=temp(-nretc+1)-temp(id)
            end if
            return
         end if
      end if
C
C     the rhs vector accounts for total net cooling in ALI
C     transitions (FCOOL)
C
      VECL(NRE)=FCOOL(ID)
      IF(IDISK.EQ.1) VECL(NRE)=FCOOL(ID)-reint(id)*TVISC(ID)

      IF(REINT(ID).GT.0) THEN
C
C *********     integral equation part of the radiative
C     equilibrium equation
C
         BREPC=0.
         BREMP=0.
         DO I=1,NLVEXP
            REXB(I)=0.
         END DO
         DO IJ=IJ1,NFREQE
            IJT=IJFR(IJ)
            BREPC=BREPC+((DABN0(IJ)-SIGEC(IJT))*RAD0(IJ)-
     *         DEMN0(IJ))*WDEP0(IJ)
            BREMP=BREMP+(DABM0(IJ)*RAD0(IJ)-DEMM0(IJ))*WDEP0(IJ)
            DO I=1,NLVEXP
               REXB(I)=REXB(I)+(DRCH0(I,IJ)*RAD0(IJ)-
     *             DRET0(I,IJ))*WDEP0(IJ)
            END DO
            B(NRE,NRE)=B(NRE,NRE)+(DABT0(IJ)*RAD0(IJ)-
     *              DEMT0(IJ))*WDEP0(IJ)*reint(id)
            HEAT=ABSO0(IJ)-SCAT0(IJ)
            B(NRE,IJ)=WDEP0(IJ)*HEAT*reint(id)
            VECL(NRE)=VECL(NRE)-(HEAT*RAD0(IJ)-EMIS0(IJ))*WDEP0(IJ)*
     *             reint(id)
c
c        additional terms for Compton scattering
c
            if(icompt.gt.5) then
             ijt=ijfr(ij)
             call compt0(ijt,id,abso0(ij),cma,cmb,cmc,cme,cms,cmd)
             vecl(nre)=vecl(nre)+abso0(ij)*cms*wdep0(ij)*reint(id)
             if(icompt.gt.6) then
             if(icmdra.gt.0) then
                b(nre,ij)=b(nre,ij)-abso0(ij)*(cmb+cme)*wdep0(ij)*
     *                    reint(id)
              else
                b(nre,ij)=b(nre,ij)-abso0(ij)*(cmb+cme)*reint(id)
             end if
             iji=nfreq-kij(ijt)+1
             if(iji.gt.1) then
                ijm=ijex(ijorig(iji-1))
                if(ijm.gt.0) then
                   if(icmdra.gt.0) then
                      b(nre,ijm)=b(nre,ijm)-abso0(ij)*cma*wdep0(ij)*
     *                           reint(id)
                   else
                      b(nre,ijm)=b(nre,ijm)-abso0(ij)*cma*reint(id)
                   end if
                end if
             end if
             if(iji.lt.nfreq) then
                ijp=ijex(ijorig(iji+1))
                if(ijp.gt.0) then
                   if(icmdra.gt.0) then
                      b(nre,ijp)=b(nre,ijp)-abso0(ij)*cmc*wdep0(ij)*
     *                           reint(id)
                   else
                      b(nre,ijp)=b(nre,ijp)-abso0(ij)*cmc*reint(id)
                   end if
                end if
             end if
             b(nre,nre)=b(nre,nre)-cmd*abso0(ij)*wdep0(ij)*reint(id)
             b(nre,npc)=b(nre,npc)-cms*abso0(ij)/elec(id)*wdep0(ij)*
     *                    reint(id)
             end if
            end if
         END DO
C
C     corrections for ALI frequency points
C
         B(NRE,NRE)=B(NRE,NRE)+REIT(ID)*reint(id)
         IF(INPC.GT.0) B(NRE,NPC)=B(NRE,NPC)+(BREPC+REIN(ID))*reint(id)
         IF(INMP.GT.0) B(NRE,NMP)=B(NRE,NMP)+(BREMP+REIM(ID))*reint(id)
         IF(INHE.GT.0) B(NRE,NHE)=REIX(ID)*reint(id)
         IF(IFALI.GT.5) THEN
            A(NRE,NRE)=AREIT(ID)*reint(id)
            IF(INPC.GT.0) A(NRE,NPC)=AREIN(ID)*reint(id)
            IF(INMP.GT.0) A(NRE,NMP)=AREIM(ID)*reint(id)
            C(NRE,NRE)=CREIT(ID)*reint(id)
            IF(INPC.GT.0) C(NRE,NPC)=CREIN(ID)*reint(id)
            IF(INMP.GT.0) C(NRE,NMP)=CREIM(ID)*reint(id)
            IF(INHE.GT.0) C(NRE,NHE)=CREIX(ID)*reint(id)
         END IF
C
C     additional terms for disks because of viscosity
C
         IF(IDISK.EQ.1) THEN
            B(NRE,NRE)=B(NRE,NRE)+DTVIST(ID)*reint(id)
            IF(INPC.GT.0) B(NRE,NPC)=B(NRE,NPC)-DTVISR(ID)*reint(id)
            IF(INHE.GT.0) B(NRE,NFREQE+INHE)=
     *                 (DTVISR(ID)+DTVISN(ID))*reint(id)
            IF(INMP.GT.0) B(NRE,NFREQE+INMP)=
     *                 DTVISR(ID)*HMASS/WMM(ID)*reint(id)
         END IF
C
         DO II=1,NLVEXP
            B(NRE,NSE+II)=B(NRE,NSE+II)+(REXB(II)+REIP(II,ID))*reint(id)
         END DO
         IF(IFALI.GT.5.AND.ID.GT.1) THEN
            DO II=1,NLVEXP
               A(NRE,NSE+II)=A(NRE,NSE+II)+AREIP(II,ID)*reint(id)
            END DO
         END IF
         IF(IFALI.GT.5.AND.ID.LT.ND) THEN
            DO II=1,NLVEXP
               C(NRE,NSE+II)=C(NRE,NSE+II)+CREIP(II,ID)*reint(id)
            END DO
         END IF

      END IF
C
C *********    differential equation part of the
C     radiative equilibrium equation
C
      IF(REDIF(ID).EQ.0) RETURN
C
      TEFFD=TEFF**4
      IF(IDISK.EQ.1) TEFFD=TEFF**4*(UN-THETAV(ID))
      VECL(NRE)=VECL(NRE)+SIG4P*TEFFD*redif(id)
c
      IF(ID.GT.1) THEN
C
         DDM=(DM(ID)-DM(ID-1))*HALF
         AREN=0.
         BREN=0.
         AREPC=0.
         BREPC=0.
C
         GP=0.
         GN=UN
         IF(INMP.GT.0) THEN
            GP=UN
            GN=0.
         END IF
C
         DO I=1,NLVEXP
            REXB(I)=0.
            REXA(I)=0.
         END DO
C
         DO IJ=1,NFREQE
            OMEG0=ABSO0(IJ)*DENS1(ID)
            OMEGM=ABSOM(IJ)*DENS1(ID-1)
            DTAUM=(OMEG0+OMEGM)*DDM
            FRD=FK0(IJ)*RAD0(IJ)-FKM(IJ)*RADM(IJ)
            GAMR=FRD/DTAUM
            A1=GAMR/(OMEG0+OMEGM)
            A3R=A1*DENS1(ID-1)*WDEP0(IJ)
            B3R=A1*DENS1(ID)*WDEP0(IJ)
C
C     Corresponding elements of matrix A
C
            A(NRE,IJ)=-WDEP0(IJ)*FKM(IJ)/DTAUM*redif(id)
            RTR=OMEGM*WMM(ID-1)*A3R
            AREN=AREN+RTR*GN
            AREPC=AREPC-A3R*DABNM(IJ)-RTR*GN
            IF(INMP.NE.0) A(NRE,NFREQE+INMP)=A(NRE,NFREQE+INMP)+RTR*GP*
     *                                    redif(id)
            A(NRE,NRE)=A(NRE,NRE)-A3R*DABTM(IJ)*redif(id)
C
C     Corresponding elements of matrix B
C     Columns corresponding to mean intensities
C
            B(NRE,IJ)=B(NRE,IJ)+WDEP0(IJ)*FK0(IJ)/DTAUM*redif(id)
            RTR=OMEG0*WMM(ID)*B3R
            BREN=BREN+RTR*GN
            BREPC=BREPC-B3R*DABN0(IJ)-RTR*GN
            IF(INMP.NE.0) B(NRE,NFREQE+INMP)=B(NRE,NFREQE+INMP)+
     *                     (RTR+REDX(ID))*GP*redif(id)
C
C     Column corresponding to temperature
C
            B(NRE,NRE)=B(NRE,NRE)-B3R*DABT0(IJ)*redif(id)
C
C     auxiliary vectors for columns corresponding to populations
C
         DO I=1,NLVEXP
            REXA(I)=REXA(I)-A3R*DRCHM(I,IJ)
            REXB(I)=REXB(I)-B3R*DRCH0(I,IJ)
         END DO
C
C     The rhs vector
C
            VECL(NRE)=VECL(NRE)-WDEP0(IJ)*GAMR*redif(id)
         END DO
C
C     Column corresponding to N (total particle number density)
C     for both A and B matrices
C
         IF(INHE.NE.0) THEN
            A(NRE,NFREQE+INHE)=(AREN+REDXM(ID))*redif(id)
            B(NRE,NFREQE+INHE)=B(NRE,NFREQE+INHE)+(BREN+REDX(ID))*
     *                         redif(id)
         END IF
C
C     Column corresponding to temperature
C
         A(NRE,NRE)=A(NRE,NRE)+REDTM(ID)*REDIF(ID)
         B(NRE,NRE)=B(NRE,NRE)+REDT(ID)*REDIF(ID)
         C(NRE,NRE)=C(NRE,NRE)+REDTP(ID)*REDIF(ID)
C
C     Column corresponding to electron density (for matrices A and B)
C
         IF(INPC.NE.0) THEN
            A(NRE,NPC)=A(NRE,NPC)+(AREPC+REDNM(ID)-REDXM(ID))*redif(id)
            B(NRE,NPC)=B(NRE,NPC)+(BREPC+REDN(ID)-REDX(ID))*redif(id)
            C(NRE,NPC)=C(NRE,NPC)+REDNP(ID)*redif(id)
         END IF
C
C     Columns corresponding to populations (for matrices A and B)
C     Note that auxiliary arrays REXA and REX, which contain derivatives
C     of the absorption and emission coefficients wrt populations, have
C     been generated by BRTE
C
         DO II=1,NLVEXP
            A(NRE,NSE+II)=A(NRE,NSE+II)+(REXA(II)+REDPM(II,ID))*
     &                    redif(id)
            B(NRE,NSE+II)=B(NRE,NSE+II)+(REXB(II)+REDP(II,ID))*redif(id)
            C(NRE,NSE+II)=C(NRE,NSE+II)+REDPP(II,ID)*redif(id)
         END DO
         RETURN
c
C     upper boundary condition for the differential form
c
       ELSE
C
C     Columns corresponding to mean intensities; rhs vector
C
         DO IJ=1,NFREQE
            IJT=IJFR(IJ)
            WF=WDEP0(IJ)*FH(IJT)*REDIF(ID)
            B(NRE,IJ)=B(NRE,IJ)+WF
            VECL(NRE)=VECL(NRE)-WF*RAD0(IJ)-WDEP0(IJ)*HEXTRD(IJT)*
     *             REDIF(ID)
         END DO
C
C     Column corresponding to temperature
C
         B(NRE,NRE)=B(NRE,NRE)+REDT(ID)*REDIF(ID)
         C(NRE,NRE)=C(NRE,NRE)+REDTP(ID)*REDIF(ID)
C
C     Column corresponding to N and electron density
C
         IF(INHE.NE.0) B(NRE,NHE)=B(NRE,NHE)+REDX(ID)*redif(id)
         IF(INPC.NE.0) B(NRE,NPC)=B(NRE,NPC)+REDN(ID)*redif(id)
         IF(INHE.NE.0) C(NRE,NHE)=C(NRE,NHE)+REDXP(ID)*redif(id)
         IF(INPC.NE.0) C(NRE,NPC)=C(NRE,NPC)+REDNP(ID)*redif(id)
C
C     Columns corresponding to populations
C
         DO II=1,NLVEXP
               B(NRE,NSE+II)=B(NRE,NSE+II)+REDP(II,ID)*redif(id)
               C(NRE,NSE+II)=C(NRE,NSE+II)+REDPP(II,ID)*redif(id)
         END DO
      END IF
      RETURN
      END SUBROUTINE BRE
C
C
C     ****************************************************************
C
C
      SUBROUTINE MATCON(ID)
C     =====================
C
C     Evaluation of the terms in matrices A and B of complete
C     linearization due to convection.
C     Two rows are modified:
C      NRE  - energy balance (i.e. temperature)
C      NDEL - new row corresponding to a new model parameter DELTA
C
C     Model parameter DELTA is defined as dln(T)/dln(P);
C     FCONV is the convective flux
C
C     The equations and corresponding matrix elements are similar
C     to those considered by Grenfell, Astr.Ap. 20, 293 (1972).
C
      use accura
      use array1
      use basics
      use modelq
      use conveq

      implicit none

      INTEGER, INTENT(IN) :: ID
      REAL(DP) :: T,P,PG,PRAD,TM,PM,PGM,PRADM,T0,P0,PG0,PR0,AB0,DLT,
     *            TT,DLP,DDT0,DDTM,DDP0,DDPM,PP0,DHCDD,T1,DHCDT0,
     *            DHCDT,DHCDTM,DHCDP,DHCDPT,TP,PTP,PGP,PRADP,
     *            DHCDTU,DHCDPP,P1,DELM,RDELM,DELHC,
     *            DDTP0,DDTPM,DHCDDP,DHCDTP,FLXC1,FLXC2,FLXC3,
     *            FLXCNV,VCON,PG1
      INTEGER  :: NHE,NRE,NPC,NDEL
C      
      IF(HMIX0.LE.0.) RETURN
      NHE=NFREQE+INHE
      NRE=NFREQE+INRE
      NPC=NFREQE+INPC
      NDEL=NFREQE+INDL
C
C     Upper boundary condition (ID=1)
C
      ANEREL=ELEC(1)/(DENS(1)/WMM(1)+ELEC(1))
      IF(ID.EQ.1) THEN
         DELTA(ID)=0.
         FLXC(ID)=0.
         IF(INDL.GT.0) B(NDEL,NDEL)=UN
         RETURN
      END IF
C
C     Normal depth point 1 < ID < ND
C
      T=TEMP(ID)
      P=PTOTAL(ID)
      PG=PGS(ID)
      PRAD=P-PG-HALF*DENS(ID)*VTURB(ID)**2
      TM=TEMP(ID-1)
      PM=PTOTAL(ID-1)
      PGM=PGS(ID-1)
      PRADM=PM-PGM-HALF*DENS(ID-1)*VTURB(ID-1)**2
      if(ilgder.eq.0) then
         T0=HALF*(T+TM)
         P0=HALF*(P+PM)
         PG0=HALF*(PG+PGM)
         PR0=HALF*(PRAD+PRADM)
         AB0=HALF*(ABROSD(ID)+ABROSD(ID-1))
         DLT=(T-TM)/(P-PM)*P0/T0
         TT=T*T-TM*TM
         DDT0= DLT/HALF*TM/TT
         DDTM=-DDT0*T/TM
       else
         T0=SQRT(T*TM)
         P0=SQRT(P*PM)
         PG0=SQRT(PG*PGM)
         PR0=SQRT(PRAD*PRADM)
         AB0=SQRT(ABROSD(ID)*ABROSD(ID-1))
         DLP=UN/LOG(P/PM)
         DLT=LOG(T/TM)*DLP
         DDT0= DLP/T
         DDTM=-DLP/TM
      end if
      DELTA(ID)=DLT
      IF(INDL.GT.0) THEN
         B(NDEL,NDEL)=-UN
         VECL(NDEL)=DELTA(ID)-DLT
         DDP0=0.
         DDPM=0.
         IF(IPRESS.GT.0) THEN
             if(ilgder.eq.0) then
                PP0=P*P-PM*PM
                DDP0=-DLT/HALF*PM/PP0
                DDPM=-DDP0*P/PM
              else
                PP0=LOG(T/TM)*DLP*DLP
                DDP0=-PP0/P
                DDPM=PP0/PM
             end if
         END IF
C
C           the row of matrix A corresponding to DELTA
C
         if(inhe.gt.0) A(NDEL,NHE)=BOLK*TM*DDPM
         A(NDEL,NRE)=PGM/TM*DDPM+DDTM
C
C        the row of matrix B corresponding to DELTA
C
         if(inhe.gt.0) B(NDEL,NHE)=BOLK*T*DDP0
         B(NDEL,NRE)=PG/T*DDP0+DDT0
      END IF
C
C        convective flux and its derivatives
C        (derivativs wrt. T and P(gas) - calculated numerically;
C        derivative wrt. DELTA calculated analytically)
C
      if(idisk.eq.1) gravd=zd(id)*qgrav
      CALL CONVEC(ID,T0,P0,PG0,PR0,AB0,DLT,FLXCNV,VCON)
      FLXC(ID)=FLXCNV
      DHCDD=0.
      IF(DELMDE.GT.0.) DHCDD=1.5D0/DELMDE*FLXCNV
      T1=1.001D0*T0
      CALL CONVEC(ID,T1,P0,PG0,PR0,AB0,DLT,FLXC1,VCON)
      DHCDT0=(FLXC1-FLXCNV)*1.D3*HALF
      DHCDT =DHCDT0/T
      DHCDTM=DHCDT0/TM
      DHCDP=0.
      IF(IPRESS.GT.0) THEN
         PG1=1.001*PG0
         CALL CONVEC(ID,T0,P0,PG1,PR0,AB0,DLT,FLXC2,VCON)
         DHCDP=(FLXC2-FLXCNV)*1.D3/PG0*HALF
         IF(IPRESS.GT.1) THEN
            P1=1.001*P0
            CALL CONVEC(ID,T0,P1,PG0,PR0,AB0,DLT,FLXC3,VCON)
            DHCDPT=(FLXC3-FLXCNV)*1.D3/P0*HALF
            DHCDP=DHCDP+DHCDPT
            DHCDT=DHCDT+DHCDPT*4.*PR0/T0
         END IF
      END IF
      IF(INDL.EQ.0) THEN
         DHCDT=DHCDT+DHCDD*DDT0
         DHCDTM=DHCDTM+DHCDD*DDTM
      END IF
C
C        additional terms in matrices A and B (the row corresponding to
C        energy balance, i.e. T) due to convection
C
C
C    **  1. differential equation form
C
      if(redif(id).gt.0) then
         IF(ICONV.NE.0) THEN
            IF(INHE.GT.0) A(NRE,NHE)=A(NRE,NHE)-DHCDP*BOLK*TM*redif(id)
            A(NRE,NRE)=A(NRE,NRE)-(DHCDP*PGM/TM+DHCDTM)*redif(id)
            IF(INHE.GT.0) B(NRE,NHE)=B(NRE,NHE)+DHCDP*BOLK*T*redif(id)
            B(NRE,NRE)=B(NRE,NRE)+(DHCDP*PG/T+DHCDT)*redif(id)
            IF(INDL.GT.0) B(NRE,NDEL)=B(NRE,NDEL)+DHCDD*redif(id)
         END IF
         VECL(NRE)=VECL(NRE)-FLXC(ID)*redif(id)
      end if
C
C    **  2. integral equation form
C
      IF(REINT(ID).GT.0.AND.ICONV.NE.0) THEN
         TP=TEMP(ID+1)
         PTP=PTOTAL(ID+1)
         PGP=PGS(ID+1)
         PRADP=PTP-PGP-HALF*DENS(ID+1)*VTURB(ID+1)**2
         if(ilgder.eq.0) then
            T0=HALF*(T+TP)
            P0=HALF*(P+PTP)
            PG0=HALF*(PG+PGP)
            PR0=HALF*(PRAD+PRADP)
            AB0=HALF*(ABROSD(ID)+ABROSD(ID+1))
            DLT=(TP-T)/(PTP-P)*P0/T0
           else
            T0=SQRT(T*TP)
            P0=SQRT(P*PTP)
            PG0=SQRT(PG*PGP)
            PR0=SQRT(PRAD*PRADP)
            AB0=SQRT(ABROSD(ID)*ABROSD(ID+1))
            DLP=UN/LOG(PTP/P)
            DLT=LOG(TP/T)*DLP
            DDTP0= DLP/TP
            DDTPM=-DLP/T
         end if
         CALL CONVEC(ID,T0,P0,PG0,PR0,AB0,DLT,FLXCNV,VCON)
         DHCDDP=0.
         IF(DELMDE.GT.0.) DHCDDP=1.5D0/DELMDE*FLXCNV
         T1=1.001D0*T0
         CALL CONVEC(ID,T1,P0,PG0,PR0,AB0,DLT,FLXC1,VCON)
         DHCDT0=(FLXC1-FLXCNV)*1.D3*HALF
         DHCDTP=DHCDT0/TP
         DHCDTU=DHCDT0/T
         DHCDPP=0.
         IF(IPRESS.GT.0) THEN
            PG1=1.001*PG0
            CALL CONVEC(ID,T0,P0,PG1,PR0,AB0,DLT,FLXC2,VCON)
            DHCDPP=(FLXC2-FLXCNV)*1.D3/PG0*HALF
            IF(IPRESS.GT.1) THEN
               P1=1.001*P0
               CALL CONVEC(ID,T0,P1,PG0,PR0,AB0,DLT,FLXC3,VCON)
               DHCDPT=(FLXC3-FLXCNV)*1.D3/P0*HALF
               DHCDPP=DHCDPP+DHCDPT
               DHCDTP=DHCDTP+DHCDPT*4.*PR0/T0
            END IF
         END IF
         IF(INDL.EQ.0) THEN
            DHCDTP=DHCDTP+DHCDDP*DDTP0
            DHCDTU=DHCDTU+DHCDDP*DDTPM
         END IF
C
C        additional terms in matrices A and B (the row corresponding to
C        energy balance, i.e. T) due to convection
C
         DELM=(DM(ID+1)-DM(ID-1))*HALF
         RDELM=DENS(ID)/DELM
         DELHC=WMM(ID)/DELM*(FLXCNV-FLXC(ID))
         IF(ICONV.NE.0) THEN
            IF(INHE.GT.0) THEN
               A(NRE,NHE)=A(NRE,NHE)-RDELM*DHCDP*BOLK*TM*reint(id)
               B(NRE,NHE)=B(NRE,NHE)+
     *             (DELHC+RDELM*(DHCDP-DHCDPP)*BOLK*T)*reint(id)
               C(NRE,NHE)=C(NRE,NHE)+RDELM*DHCDPP*BOLK*TP*reint(id)
            END IF
            A(NRE,NRE)=A(NRE,NRE)-RDELM*(DHCDP*PGM/TM+DHCDTM)*reint(id)
            B(NRE,NRE)=B(NRE,NRE)+
     *              RDELM*((DHCDPP-DHCDP)*PG/T+DHCDTP-DHCDTU)*reint(id)
            C(NRE,NRE)=C(NRE,NRE)+RDELM*(DHCDPP*PGP/TP+DHCDTP)*reint(id)
            IF(INPC.GT.0) B(NRE,NPC)=B(NRE,NPC)-DELHC*reint(id)
            IF(INDL.GT.0) THEN
               B(NRE,NDEL)=B(NRE,NDEL)-RDELM*DHCDD*reint(id)
               C(NRE,NDEL)=C(NRE,NDEL)+RDELM*DHCDDP*reint(id)
            END IF
         END IF
         VECL(NRE)=VECL(NRE)-RDELM*(FLXCNV-FLXC(ID))*reint(id)
      END IF
      RETURN
      END SUBROUTINE MATCON
C
C
C     ****************************************************************
C
C
      SUBROUTINE BPOP(ID)
C     ===================
C
C     The part of matrix B corresponding to the statistical
C     equilibrium equations
C     i.e. the (NFREQE+INSE)-th thru (NFREQE+INSE+NLVEXP-1)-th rows;
C     and to the charge conservation equation, ie. the (NFREQE+INPC)-th
C     row
C
C     The formalism is similar to that described in Mihalas, Stellar
C     Atmospheres, 1978, pp. 143-145
C
C     Input: ID - depth index
C
      use accura
      use alipar
      use array1
      use atomic
      use basics
      use iterat
      use modelq
CC    use odfpar

      implicit none
 
      INTEGER, INTENT(IN) :: ID
      INTEGER  :: I,II,ION,J,III
      REAL(DP) :: sbw(mlevel),popp(mlevel)
      REAL(DP) :: ATT(MLVEXP),ANN(MLVEXP)
C
      if(ioptab.lt.0) return
      DO I=1,NLVEXP
         ATT(I)=0.
         ANN(I)=0.
      END DO
C
      IF(.NOT.LTE .AND. IFPOPR.EQ.5.AND.IPSLTE.EQ.0) THEN
      CALL RATMAT(ID,IIFOR,0)
      CALL LEVSOL(POPP,IIFOR,NLVFOR,0)
      DO I=1,NLEVEL
         II=IIEXP(I)
         IF(II.EQ.0.AND.IMODL(I).EQ.6) THEN
            III=ILTREF(I,ID)
            SBPSI(I,ID)=POPP(I)/POPP(III)
         END IF
      END DO
      DO ION=1,NION
         DO I=NFIRST(ION),NLAST(ION)
             SBW(I)=ELEC(ID)*SBF(I)*WOP(I,ID)
             IF(POPUL(NNEXT(ION),ID).GT.0..AND.IPZERO(I,ID).EQ.0)
     *       BFAC(I,ID)=POPP(I)/(POPP(NNEXT(ION))*SBW(I))
         END DO
      END DO
      END IF
C
      CALL RATMAT(ID,IIEXP,0)
      CALL LEVGRP(ID,IIEXP,0,POPP)
      CALL RATMAT(ID,IIEXP,0)
C
      IF(IFPOPR.LE.3) CALL MATINV(ESEMAT,NLVEXP,MLEVEL)
C
C     Split BPOP in separate subroutines
C
      if(ipslte.eq.0) then
      IF(.NOT.LTE.AND.IBPOPE.GT.0.AND.ID.LT.IDLTE) THEN
         CALL BPOPE(ID)
         CALL BPOPF(ID)
      END IF
      end if
      CALL BPOPT(ID)
      IF(INPC.GT.0) CALL BPOPC(ID)
C
C     reset matrix elements for "small" populations
C
      DO I=1,NLVEXP
         IF(IGZERO(I,ID).NE.0) THEN
         DO J=1,NLVEXP
            B(NFREQE+INSE-1+I,NFREQE+INSE-1+J)=0.
         END DO
         B(NFREQE+INSE-1+I,NFREQE+INSE-1+I)=1.
         VECL(NFREQE+INSE-1+I)=0.
         END IF
      END DO
      RETURN
      END SUBROUTINE BPOP
C
C
C     ****************************************************************
C
C
      SUBROUTINE BPOPE(ID)
C     ====================
C
C     the part of B-matrix corresponding to the population rows and
C     the explicit frequency columns
C     -- a variant for the full overlap case
C
      use accura
      use alipar
      use array1
      use atomic
      use basics
CC    use iterat
      use modelq
      use odfpar

      implicit none

      INTEGER, INTENT(IN) :: ID
      REAL(DP) :: AJIJ(MFREX,MLVEXP),EHKE(MFREX)
      REAL(DP) :: HKT,FR,FRINV,FR3INV,SG,DW1,SGME1,W0,SGW0,SI,SJ,APFR,
     *            SGW,X,A1,A2,SUME,CROSS
      INTEGER  :: NSE,I,IJ,IJE,IBFT,ITR,ICDW,IMER,II,J,JJ,NREFI,IZZ,
     *            ILINT,IJ0,IJT,IJ1,KJ,KJD,INDXPA
C
      IF(NFREQE.LE.0) RETURN
      NSE=NFREQE+INSE-1
      DO I=1,NLVEXP
         DO IJE=1,NFREQE
            AJIJ(IJE,I)=0.
         END DO
      END DO
      HKT=HK/TEMP(ID)
      DO IJE=1,NFREQE
         EHKE(IJE)=EXP(-HKT1(ID)*FREQ(IJFR(IJE)))
      END DO
C
      FRLOOP: DO IJ=1,NFREQ
         IF(IJEX(IJ).LE.0) CYCLE FRLOOP
         IF(IJX(IJ).EQ.-1) CYCLE FRLOOP
         IJE=IJEX(IJ)
         FR=FREQ(IJ)
         FRINV=UN/FR
         FR3INV=FRINV*FRINV*FRINV
C
C        ---------------------
C        Continuum transitions
C        ---------------------
C
         CONTLOOP: DO IBFT=1,NTRANC
            ITR=ITRBF(IBFT)
            SG=CROSS(IBFT,IJ)
            IF(SG.LE.0.) CYCLE CONTLOOP
            I=ILOW(ITR)
            IF(ILTION(IEL(I)).GE.1.OR.IIFIX(IATM(I)).EQ.1) 
     *         CYCLE CONTLOOP
            ICDW=MCDW(ITR)
            IMER=IMRG(I)
            II=IABS(IIEXP(I))
            J=IUP(ITR)
            IF(IPZERO(I,ID).NE.0.OR.IPZERO(J,ID).NE.0) CYCLE CONTLOOP
            JJ=IABS(IIEXP(J))
            NREFI=NREFS(IATM(I),ID)
            IF(IFWOP(I).GE.0) THEN
              IF(ICDW.GE.1) THEN
                 IZZ=IZ(IEL(I))
                 CALL DWNFR1(FR,FR0(ITR),ID,IZZ,DW1)
                 SG=SG*DW1
              END IF
            ELSE
              CALL SGMER1(FRINV,FR3INV,IMER,ID,SGME1)
              SG=SGME1
            ENDIF
            W0=W0E(IJ)
            SGW0=SG*W0
            SI=ABTRA(ITR,ID)
            SJ=EMTRA(ITR,ID)
            APFR=(SI-SJ*EHKE(IJE))*SGW0
            IF(II.GT.0.AND.I.NE.NREFI.AND.ILTLEV(I).LE.0)
     *         AJIJ(IJE,II)=AJIJ(IJE,II)+APFR
            IF(JJ.GT.0.AND.J.NE.NREFI.AND.ILTLEV(J).LE.0.
     *         and.iabs(imodl(i)).ne.4)
     *         AJIJ(IJE,JJ)=AJIJ(IJE,JJ)-APFR
         END DO CONTLOOP
C
C        ----------------
C        Line transitions
C        ----------------
C
         IF(ISPODF.EQ.0) THEN
            ITR=IJLIN(IJ)
            IF(ITR.GT.0) THEN
C
C        the "primary" line at the given frequency
C
               PRIM: DO
                  IF(LINEXP(ITR)) EXIT PRIM
                  I=ILOW(ITR)
                  IF(ILTION(IEL(I)).GE.1.OR.IIFIX(IATM(I)).EQ.1) 
     *               EXIT PRIM
                  J=IUP(ITR)
                  IF(IPZERO(I,ID).NE.0.OR.IPZERO(J,ID).NE.0) EXIT PRIM
                  II=IABS(IIEXP(I))
                  JJ=IABS(IIEXP(J))
                  IF(II.LE.0.AND.JJ.LE.0) EXIT PRIM
                  IF(II.EQ.JJ) EXIT PRIM
                  NREFI=NREFS(IATM(I),ID)
                  SGW=PRFLIN(ID,IJ)*W0E(IJ)
                  SI=ABTRA(ITR,ID)
                  SJ=EMTRA(ITR,ID)
                  APFR=(SI-SJ*EHKE(IJE))*SGW
                  IF(II.GT.0.AND.I.NE.NREFI.AND.ILTLEV(I).LE.0)
     *            AJIJ(IJE,II)=AJIJ(IJE,II)+APFR
                  IF(JJ.GT.0.AND.J.NE.NREFI.AND.ILTLEV(J).LE.0.
     *            and.iabs(imodl(i)).ne.4)
     *            AJIJ(IJE,JJ)=AJIJ(IJE,JJ)-APFR
                  EXIT PRIM
               END DO PRIM
            END IF
C
C        the "overlapping" lines at the given frequency
C
            IF(NLINES(IJ).LE.0) CYCLE FRLOOP
            OLIN: DO ILINT=1,NLINES(IJ)
               ITR=ITRLIN(ILINT,IJ)
               IF(LINEXP(ITR)) CYCLE OLIN
               I=ILOW(ITR)
               IF(ILTION(IEL(I)).GE.1.OR.IIFIX(IATM(I)).EQ.1) CYCLE OLIN
               J=IUP(ITR)
               IF(IPZERO(I,ID).NE.0.OR.IPZERO(J,ID).NE.0) CYCLE OLIN
               II=IABS(IIEXP(I))
               JJ=IABS(IIEXP(J))
               IF(II.LE.0.AND.JJ.LE.0) CYCLE OLIN
               IF(II.EQ.JJ) CYCLE OLIN
               NREFI=NREFS(IATM(I),ID)
               IJ0=IFR0(ITR)
               DO IJT=IJ0,IFR1(ITR)
                  IF(FREQ(IJT).LE.FR) THEN
                     IJ0=IJT
                     EXIT
                  END IF
               END DO
               IJ1=IJ0-1
               X=W0E(IJ)/(FREQ(IJ1)-FREQ(IJ0))
               A1=(FR-FREQ(IJ0))*X
               A2=(FREQ(IJ1)-FR)*X
               SGW=A1*PRFLIN(ID,IJ1)+A2*PRFLIN(ID,IJ0)
               SI=ABTRA(ITR,ID)
               SJ=EMTRA(ITR,ID)
               APFR=(SI-SJ*EHKE(IJE))*SGW
               IF(II.GT.0.AND.I.NE.NREFI.AND.ILTLEV(I).LE.0)
     *         AJIJ(IJE,II)=AJIJ(IJE,II)+APFR
               IF(JJ.GT.0.AND.J.NE.NREFI.AND.ILTLEV(J).LE.0.
     *         and.iabs(imodl(i)).ne.4)
     *         AJIJ(IJE,JJ)=AJIJ(IJE,JJ)-APFR
            END DO OLIN
C
C     Opacity sampling option
C
         ELSE
            IF(NLINES(IJ).LE.0) CYCLE FRLOOP
            OLINT: DO ILINT=1,NLINES(IJ)
               ITR=ITRLIN(ILINT,IJ)
               I=ILOW(ITR)
               IF(ILTION(IEL(I)).GE.1.OR.IIFIX(IATM(I)).EQ.1) 
     *            CYCLE OLINT
               J=IUP(ITR)
               IF(IPZERO(I,ID).NE.0.OR.IPZERO(J,ID).NE.0) CYCLE OLINT
               KJ=IJ-IFR0(ITR)+KFR0(ITR)
               II=IABS(IIEXP(I))
               JJ=IABS(IIEXP(J))
               IF(II.LE.0.AND.JJ.LE.0) CYCLE OLINT
               IF(II.EQ.JJ) CYCLE OLINT
               NREFI=NREFS(IATM(I),ID)
               INDXPA=IABS(INDEXP(ITR))
               IF(INDXPA.NE.3 .AND. INDXPA.NE.4) THEN
                 SG=PRFLIN(ID,KJ)
                ELSE
                 KJD=JIDI(ID)
                 SG=EXP(XJID(ID)*SIGFE(KJD,KJ)+
     *              (UN-XJID(ID))*SIGFE(KJD+1,KJ))
               END IF
               SI=ABTRA(ITR,ID)
               SJ=EMTRA(ITR,ID)
               APFR=(SI-SJ*EHKE(IJE))*SG*W0E(IJ)
               IF(II.GT.0.AND.I.NE.NREFI.AND.ILTLEV(I).LE.0)
     *         AJIJ(IJE,II)=AJIJ(IJE,II)+APFR
               IF(JJ.GT.0.AND.J.NE.NREFI.AND.ILTLEV(J).LE.0.
     *         and.iabs(imodl(i)).ne.4)
     *         AJIJ(IJE,JJ)=AJIJ(IJE,JJ)-APFR
            END DO OLINT
         END IF
      END DO FRLOOP
C
C     elements of the B-matrix
C
      DO I=1,NLVEXP
         DO IJE=1,NFREQE
            IF(IFPOPR.LE.3) THEN
               SUME=0.
               DO J=1,NLVEXP
                  SUME=SUME-ESEMAT(I,J)*AJIJ(IJE,J)
               END DO
             ELSE
               SUME=AJIJ(IJE,I)
            END IF
            B(NSE+I,IJE)=SUME
         END DO
      END DO

      RETURN
      END SUBROUTINE BPOPE
C
C
C     ****************************************************************
C
C
      SUBROUTINE BPOPF(ID)
C     =====================
C
C     the part of B-matrix corresponding to the population rows and
C     populations - i.e. derivatives of the ALI points intensities
C                   wrt. populations
C
      use accura
      use alipar
      use array1
      use atomic
      use basics
      use modelq
      use odfpar

      implicit none

      INTEGER, INTENT(IN) :: ID
      REAL(DP) :: SUMT,SUMN,SUMM,SUME,ASUMT,ASUMN,ASUMM,CSUMT,CSUMN,
     *            ASUM,CSUM
      INTEGER  :: NHE,NSE,NRE,NPC,I,II,J

C      
      NSE=NFREQE+INSE-1
      NRE=NFREQE+INRE
      NHE=NFREQE+INHE
      NPC=NFREQE+INPC
C
C     matrix B of complete linearization
C
      DO I=1,NLVEXP
         SUMT=0.
         SUMN=0.
         SUMM=0.
         DO II=1,NLVEXP
            IF(IFPOPR.LE.3) THEN
               SUMT=SUMT-ESEMAT(I,II)*APT(II,ID)
               SUMN=SUMN-ESEMAT(I,II)*APN(II,ID)
               SUMM=SUMM-ESEMAT(I,II)*APM(II,ID)
               SUME=0.
               DO J=1,NLVEXP
                  SUME=SUME-ESEMAT(I,J)*APP(II,J,ID)
               END DO
             ELSE
               SUME=APP(II,I,ID)
            END IF
            B(NSE+I,NSE+II)=B(NSE+I,NSE+II)+SUME
         END DO
         IF(IFPOPR.GT.3) THEN
            SUMT=APT(I,ID)
            SUMN=APN(I,ID)
            SUMM=APM(I,ID)
         END IF
         IF(INRE.NE.0) B(NSE+I,NRE)=B(NSE+I,NRE)+SUMT
         IF(INPC.NE.0) B(NSE+I,NPC)=B(NSE+I,NPC)+SUMN
         IF(INHE.NE.0) B(NSE+I,NHE)=B(NSE+I,NHE)+SUMM
      END DO
C
C     matrix A and C of complete linearization
C
      IF(IFALI.NE.6.AND.ID.LT.ND) RETURN
      DO I=1,NLVEXP
         ASUMT=0.
         ASUMN=0.
         ASUMM=0.
         CSUMT=0.
         CSUMN=0.
         DO II=1,NLVEXP
            IF(IFPOPR.LE.3) THEN
               ASUMT=ASUMT-ESEMAT(I,II)*AAPT(II,ID)
               ASUMN=ASUMN-ESEMAT(I,II)*AAPN(II,ID)
               ASUMM=ASUMN-ESEMAT(I,II)*AAPM(II,ID)
               CSUMT=CSUMT-ESEMAT(I,II)*CAPT(II,ID)
               CSUMN=CSUMN-ESEMAT(I,II)*CAPN(II,ID)
               ASUM=0.
               CSUM=0.
               DO J=1,NLVEXP
                  ASUM=ASUM-ESEMAT(I,J)*AAPP(II,J,ID)
CC                CSUM=CSUM-ESEMAT(I,J)*CAPP(II,J,ID)
               END DO
             ELSE
               ASUM=AAPP(II,I,ID)
CC             CSUM=CAPP(II,I,ID)
            END IF
            A(NSE+I,NSE+II)=ASUM
            C(NSE+I,NSE+II)=CSUM
         END DO
         IF(IFPOPR.GT.3) THEN
            ASUMT=AAPT(I,ID)
            ASUMN=AAPN(I,ID)
            ASUMM=AAPM(I,ID)
            CSUMT=CAPT(I,ID)
            CSUMN=CAPN(I,ID)
         END IF
         IF(INRE.NE.0) THEN
            A(NSE+I,NRE)=A(NSE+I,NRE)+ASUMT
            C(NSE+I,NRE)=C(NSE+I,NRE)+CSUMT
         END IF
         IF(INPC.NE.0) THEN
            A(NSE+I,NPC)=A(NSE+I,NPC)+ASUMN
            C(NSE+I,NPC)=C(NSE+I,NPC)+CSUMN
         END IF
         IF(INHE.NE.0) THEN
            A(NSE+I,NHE)=A(NSE+I,NHE)+ASUMM
         END IF
      END DO
C
      RETURN
      END SUBROUTINE BPOPF
C
C
C     ****************************************************************
C
C

      SUBROUTINE BPOPT(ID)
C     ====================
C
C     the part of B-matrix corresponding to the population rows
C     and T and ne columns
C
      use accura
      use alipar
      use array1
      use atomic
      use basics
      use modelq
      use odfpar
 
      implicit none

      INTEGER, INTENT(IN) :: ID

      REAL(DP), PARAMETER :: TRHA=1.5,CCOR=0.09,SIXTH=UN/6.
      REAL(DP) ::  DCOL(MTRANS),DLOC(MTRANS),
     *             AM(MLEVEL),ATT(MLVEXP),ANN(MLVEXP)
      REAL(DP) :: T,ANE,HKT,TK,ANMNE1,DELTAT,DLGT,DLGN,POPI,POPJ,PJI,
     *            AVT,AVN,AVM,PIJ,SUME
      INTEGER  :: NSE,NKH,ITR,I,J,II,JJ,NREFI,IAT,NREFII,IL
      LOGICAL  :: LLT
C
      NSE=NFREQE+INSE-1
      IF(INRE.NE.0.AND.INPC.NE.0) THEN
         IF(IELH.GT.0) N0HN=NFIRST(IELH)
         NKH=IABS(IIEXP(NREFS(IATREF,ID)))
         T=TEMP(ID)
         ANE=ELEC(ID)
         HKT=HK/T
         TK=HKT/H
         ANMNE1=WMM(ID)*DENS1(ID)
         DO I=1,NTRANS
            DCOL(I)=0.
            DLOC(I)=0.
         END DO
         DO I=1,NLEVEL
            AM(I)=0.
         END DO
C
C     Derivatives of collisional rates wrt temperature - DCOL
C     Note that these derivatives are calculated numerically
C
         IF(.NOT.LTE.AND.INRE.GT.0.AND.ID.LT.IDLTE) THEN
            DELTAT=T*1.e-4
            CALL COLIS(ID,T+DELTAT)
            DO ITR=1,NTRANS
               DCOL(ITR)=(COL(ITR)-COLRAT(ITR,ID))/DELTAT
               DLOC(ITR)=(CLOC(ITR)-COLTAR(ITR,ID))/DELTAT
            END DO
         END IF
C
C     Column corresponding to temperature and electron density, ie. the
C     (NFREQE+INRE)-th and (NFREQE+INPC)-t resach columns
C
C      ATT(I) - auxiliary vector = (derivative of rate matrix wrt
C              temperature) times (vector of populations)
C
C      ANN(I) - auxiliary vector = (derivative of rate matrix wrt
C              electron density) times (vector of populations)
C
C
C     a) contribution to AT and AN from true statistical equilibrium
C        equations (arising due to dependence of transition rates on
C        temperature and electron density);
C        derivatives contain the collisional-radiative switching
C        parameter CRSW
C
         IF(.NOT.LTE.AND.ID.LT.IDLTE) THEN
            TRLOOP: DO ITR=1,NTRANS
               I=ILOW(ITR)
               IF(ILTION(IEL(I)).GE.1.OR.IIFIX(IATM(I)).EQ.1) 
     *            CYCLE TRLOOP
               J=IUP(ITR)
               IF(IPZERO(I,ID).NE.0.OR.IPZERO(J,ID).NE.0) CYCLE TRLOOP
               II=IABS(IIEXP(I))
               JJ=IABS(IIEXP(J))
               IF(II.EQ.JJ) CYCLE TRLOOP
               NREFI=NREFS(IATM(I),ID)
               IF(.NOT.LINE(ITR)) THEN
                  DLGT=-(TRHA+HKT*FR0(ITR))/T
                  DLGN=ELEC1(ID)
                ELSE
                  DLGT=-HKT*FR0(ITR)/T
                  DLGN=0.
               END IF
               POPI=ABTRA(ITR,ID)
               POPJ=EMTRA(ITR,ID)
               PJI=POPJ*(RRD(ITR,ID)+COLRAT(ITR,ID))
               AVT=(POPI-POPJ)*DCOL(ITR)-PJI*DLGT-
     *              POPJ*DRDT(ITR,ID)
               AVN=(POPI-POPJ)*COLRAT(ITR,ID)/ane-PJI*DLGN
c      if(ii.eq.2.and.id.eq.39) write(6,"('BT0',6i4,1p10e12.4)")
c    * itr,i,ii,j,jj,nrefi,dlgt,dlgn,popi,popj,
c    * rrd(itr,id),colrat(itr,id),dcol(itr),drdt(itr,id),avt,avn
C
               IF(I.NE.NREFI.AND.II.GT.0.AND.ILTLEV(I).LE.0) THEN
                  ATT(II)=ATT(II)+AVT
                  ANN(II)=ANN(II)+AVN
                  IF(JJ.EQ.0) THEN
                     ATT(II)=ATT(II)-PJI*DSBPST(J,ID)
                     ANN(II)=ANN(II)-PJI*DSBPSN(J,ID)
c         if(ii.eq.2.and.id.eq.39) write(*,"('BT1',5i4,1p11e12.4)") 
c    *    itr,i,ii,j,jj,
c    *    dlgt,dlgn,popi,popj,pji,dcol(itr),drdt(itr,id),avt,avn,
c    *    att(ii),ann(ii)
                  END IF
               END IF
               IF(J.NE.NREFI.AND.JJ.GT.0.AND.ILTLEV(J).LE.0.
     *         and.iabs(imodl(i)).ne.4) THEN
                  ATT(JJ)=ATT(JJ)-AVT
                  ANN(JJ)=ANN(JJ)-AVN
                  IF(II.EQ.0) THEN
                     PIJ=POPI*(RRU(ITR,ID)+COLRAT(ITR,ID))
                     ATT(JJ)=ATT(JJ)-PIJ*DSBPST(I,ID)
                     ANN(JJ)=ANN(JJ)-PIJ*DSBPSN(I,ID)
c         if(ii.eq.2.and.id.eq.39) write(*,"('BT2',5i4,1p11e12.4)") 
c    *    itr,i,ii,j,jj,
c    *    dlgt,dlgn,popi,popj,pij,dcol(itr),drdt(itr,id),avt,avn,
c    *    att(jj),ann(jj)
                  END IF
               END IF
            END DO TRLOOP
         END IF
C
C      simple expressions in the case of LTE
C
         LLT=LTE.OR.ID.GE.IDLTE
         DO IAT=1,NATOM
            DO I=N0A(IAT),NKA(IAT)
               II=IABS(IIEXP(I))
               IF(II.NE.0.AND.I.NE.NREFS(IAT,ID)) THEN
                  IF(LLT.OR.ILTION(IEL(I)).GE.1.OR.ILTLEV(I).GE.1) THEN
                     ATT(II)=ATT(II)-POPUL(I,ID)*DSBPST(I,ID)
                     ANN(II)=ANN(II)-POPUL(I,ID)*DSBPSN(I,ID)
                  END IF
               END IF
            END DO
         END DO
C
C
C      b) contribution to AT and AN (and AM - for total particle density)
C         from the abundance definition equations
C
         ATO: DO IAT=1,NATOM
            IF(IIFIX(IAT).EQ.1) CYCLE ATO
            NREFII=IABS(IIEXP(NREFS(IAT,ID)))
            IF(NREFII.EQ.0) CYCLE ATO
            DO I=N0A(IAT),NKA(IAT)
               IL=ILK(I)
               II=IIEXP(I)
               IF(IL.EQ.0) THEN
                  IF(II.EQ.0) THEN
                     ATT(NREFII)=ATT(NREFII)+POPUL(I,ID)*DSBPST(I,ID)
                     ANN(NREFII)=ANN(NREFII)+POPUL(I,ID)*DSBPSN(I,ID)
                  END IF
                ELSE
                  ATT(NREFII)=ATT(NREFII)+POPUL(I,ID)*DUSUMT(IL)*ANE
                  ANN(NREFII)=ANN(NREFII)+
     *                     POPUL(I,ID)*(USUM(IL)+ANE*DUSUMN(IL))
               END IF
            END DO
            IF(IFMOL.EQ.0.OR.T.GT.TMOLIM) THEN
               ANN(NREFII)=ANN(NREFII)+UN/YTOT(ID)*ABUND(IAT,ID)
               AM(NREFII)=AM(NREFII)-UN/YTOT(ID)*ABUND(IAT,ID)
            END IF
         END DO ATO
C
C -----------------------
C     Having evaluated auxiliary vectors AT, AN, AM, we may now set up
C     the columns corresponding to temperature, el.density, and total
C     particle number density
C
         DO I=1,NLVEXP
            IF(IFPOPR.LE.3) THEN
            AVT=0.
            AVN=0.
            AVM=0.
            DO J=1,NLVEXP
               AVT=AVT-ESEMAT(I,J)*ATT(J)
               AVN=AVN-ESEMAT(I,J)*ANN(J)
               AVM=AVM-ESEMAT(I,J)*AM(J)
            END DO
            ELSE
               AVT=ATT(I)
               AVN=ANN(I)
               AVM=AM(I)
            END IF
            IF(INHE.NE.0) B(NSE+I,NFREQE+INHE)=B(NSE+I,NFREQE+INHE)+AVM
            IF(INRE.NE.0) B(NSE+I,NFREQE+INRE)=B(NSE+I,NFREQE+INRE)+AVT
            IF(INPC.NE.0) B(NSE+I,NFREQE+INPC)=B(NSE+I,NFREQE+INPC)+AVN
         END DO

      END IF
C
C     Columns corresponding to populations
C
      IF(IFPOPR.LE.3) THEN
         DO I=1,NLVEXP
            B(NSE+I,NSE+I)=B(NSE+I,NSE+I)-UN
            IF(IABS(IFPOPR).GE.3) THEN
               SUME=0.
               DO J=1,NLVEXP
                  SUME=SUME+ESEMAT(I,J)*BESE(J)
               END DO
               VECL(NSE+I)=POPGRP(I)-SUME
            END IF
         END DO
       ELSE IF(IFPOPR.LE.5) THEN
         DO I=1,NLVEXP
            SUME=0.
            DO J=1,NLVEXP
               SUME=SUME+ESEMAT(I,J)*POPGRP(J)
               B(NSE+I,NSE+J)=B(NSE+I,NSE+J)+ESEMAT(I,J)
            END DO
            VECL(NSE+I)=BESE(I)-SUME
c      if(id.eq.1) write(*,"('bv',2i3,1p5e11.3,2x,3e11.3,2x,5e11.3)")
c    *   i,nse+i,(esemat(i,j),j=1,nlvexp),bese(i),sume,vecl(nse+i),
c    *   (POPGRP(j),j=1,nlvexp)
         END DO
      END IF
      RETURN
      END SUBROUTINE BPOPT
C
C
C     ****************************************************************
C
C
      SUBROUTINE BPOPC(ID)
C     ====================
C
      use accura
      use alipar
      use array1
      use atomic
      use basics
      use modelq
      use odfpar

      implicit none

      INTEGER, INTENT(IN) :: ID
C      
      REAL(DP) :: AJ(MLEVEL)
      REAL(DP) :: T,ANE,HKT,TK,ANMNE1,QQ,APTT,APNN,APMM,VPC,
     *            CH,DCHT,DCHN,QQQ
      INTEGER  :: NSE,NPC,NKH,I,IAT,II,IL,III
C
      NSE=NFREQE+INSE-1
      NPC=NFREQE+INPC
      IF(IELH.GT.0) N0HN=NFIRST(IELH)
      NKH=NREFS(IATREF,ID)
      NKH=IABS(IIEXP(NKH))
      T=TEMP(ID)
      ANE=ELEC(ID)
      HKT=HK/T
      TK=HKT/H
      ANMNE1=WMM(ID)*DENS1(ID)
      DO I=1,NLEVEL
         AJ(I)=0.
      END DO
C
C *************************
C     remaining equation - (NFREQE+INPC)-th row
C     linearized charge conservation equation
C *************************
C
C     This part is very similar to procedure ELCOR (obviously);
C     array AJ has the meaning of coefficients of the charge conserv.
C     ie. charge conservation is written
C           AJ   * (vector of populations) = electron density
C     then
C           APTT = (vector of populations) * (derivative AJ wrt temp)
C           APNN = (vector of populations) * (derivative AJ wrt n(el))
C           APMM = (vector of populations) * (derivative AJ wrt N)
C
      IF(INPC.EQ.0) RETURN
      QQ=0.
      if(ifmol.eq.0.or.t.gt.tmolim) then
         CALL STATE(3,ID,T,ANE)
         QQ=Q*ABUND(IATREF,ID)/YTOT(ID)
         if(ioptab.gt.0) QQ=Q/YTOT(ID)
       else
         qq=qadd(id)*anmne1
         dqt=0.
         dqn=0.
      end if
C
      APTT=0.
      APNN=0.
      APMM=0.
      VPC=QFIX(ID)+QQ/ANMNE1
      ATO: DO IAT=1,NATOM
         IF(IIFIX(IAT).EQ.1) CYCLE ATO
         DO I=N0A(IAT),NKA(IAT)
            IF(IPZERO(I,ID).EQ.0) THEN
               IL=ILK(I)
               II=IIEXP(I)
               IF(IL.EQ.0) THEN
                  CH=IZ(IEL(I))-1
                  DCHT=0.
                  DCHN=0.
                ELSE
                  CH=IZ(IL)+(IZ(IL)-1)*USUM(IL)*ANE
                  DCHT=(IZ(IL)-1)*ANE*DUSUMT(IL)*POPUL(I,ID)
                  DCHN=(IZ(IL)-1)*(ANE*DUSUMN(IL)+USUM(IL))*POPUL(I,ID)
               END IF
               IF(IMODL(I).GE.0) VPC=VPC+CH*POPUL(I,ID)
               IF(II.GT.0) THEN
                  AJ(II)=AJ(II)+CH
                  APTT=APTT+DCHT
                  APNN=APNN+DCHN
                ELSE IF(II.LT.0) THEN
                  AJ(-II)=AJ(-II)+CH*SBPSI(I,ID)
                  APTT=APTT+DCHT*SBPSI(I,ID)
                  APNN=APNN+DCHN*SBPSI(I,ID)
                ELSE
                  III=IIEXP(ILTREF(I,ID))
                  AJ(III)=AJ(III)+CH*SBPSI(I,ID)
                  APTT=APTT+CH*POPUL(I,ID)*DSBPST(I,ID)
                  APNN=APNN+CH*POPUL(I,ID)*DSBPSN(I,ID)
               END IF
            END IF
         END DO
      END DO ATO
C
C     (NFREQE+INPC)-th row of matrix B
C
      NPC=NFREQE+INPC
      QQQ=ABUND(IATREF,ID)/YTOT(ID)/ANMNE1
      if(ioptab.gt.0) QQQ=UN/YTOT(ID)/ANMNE1
      IF(INHE.NE.0) B(NPC,NFREQE+INHE)=APMM+QQ
      IF(INRE.NE.0) B(NPC,NFREQE+INRE)=APTT+QQQ*DQT
      B(NPC,NPC)=APNN-QQ-UN+QQQ*DQN
      DO II=1,NLVEXP
         B(NPC,NSE+II)=AJ(II)
      END DO
C
C     (NFREQE+INPC)-th element of the rhs vector VECL
C
      VECL(NPC)=ANE-VPC
      RETURN
      END SUBROUTINE BPOPC
C
C
C     ****************************************************************
C
C
      SUBROUTINE RHSGEN(ID)
C     =====================
C
C     Auxiliary procedure for SOLVE
C     controls evaluation of rhs vector when
C     matrices A,B, and C are kept fixed.
C
C     Input:  ID - depth index
C
      use accura
      use alipar
      use array1
      use atomic
      use basics
      use modelq
      use conveq

      implicit none
C      
      INTEGER, INTENT(IN) :: ID

      REAL(DP), PARAMETER :: XCON=8.0935e-21,YCON=1.68638e-10,
     &                       SIXTH=UN/6., THIRD=UN/3.
C     REAL(DP) :: AJ(MLEVEL)
      REAL(DP) ::  POPP(MLEVEL)

      REAL(DP) :: DDP,DDM,OMEG0,OMEGP,OMEGM,DZP,DTAUP,ALF1,BET1,GAM1,
     *            S0,AS,BS,CS,CHIEL0,CHIELP,CHIELM,ALF2,BET2,GAM2,
     *            SM,SP,T,HKT,SUMB,SUMF,FR,FR15,WD,X,EX,PLAN,DPLAN,
     *            DZM,FI,FL,ZZ,X1,DTAUM,DTAU0,FRD,C2,GRAVZ
      REAL(DP) :: GRP,FLUXW,VT0,CCC,HR1,HG1,PG1,F1,GGG,VTM,
     *            PCX,HEAT,TEFFD,GAMR,SUME,ANE,VPC,CH,ERFCX
      REAL(DP) :: P,PG,TM,PM,PGM,PRADM,T0,P0,PG0,PR0,PRAD,AB0,
     *            DLT,FLXCNV,VCON,TP,PGP,PRADP,FLXCP,DELM,RDELM
      REAL(DP) :: ZJ0,ZJ1,ZJ2,ZXX,COMBID,COMAID,E2,ZXX0,ZXXM,
     *            CMA,CMB,CMC,CMD,CME,CMS
      INTEGER  :: ISPL,IJ,IJ1,IJI,I,IJT,NHE,NZD,NRE,NSE,ITTC,IAT,IL,
     *            NPC,NDEL,INONZ,II,J

C
      ispl=isplin
      if(isplin.ge.5) isplin=isplin-5
      IJ1=1
C
C     in the case of Compton scattering - boundary condition
C     for the highest frequency
C
      if(icompt.gt.0.and.icombc.gt.0.and.ijex(1).gt.0) then
         IJ1=2
         ij=1
         iji=nfreq
         zj1=exp(-hk*freq(ij)/temp(id))
         zj2=exp(-hk*freq(ij+1)/temp(id))
         dlt=delj(iji-1,id)
         if(ichcoo.eq.0) then
            zj0=un/(hk*sqrt(freq(ij)*freq(ij+1))/temp(id))
            zxx=un-3.*zj0+(un-dlt)*zj1+dlt*zj2
            combid=zj0/dlnfr(iji-1)+(un-dlt)*zxx
            comaid=-zj0/dlnfr(iji-1)+dlt*zxx
         else
            e2=ycon*temp(id)
            zxx0=xcon*freq(ij)*(un+zj1)-3.*e2
            zxxm=xcon*freq(ij+1)*(un+zj2)-3.*e2
            zxx=(un-dlt)*zxx0+dlt*zxxm
            combid=e2/dlnfr(iji-1)+(un-dlt)*zxx
            comaid=-e2/dlnfr(iji-1)+dlt*zxx
        end if
        vecl(ij)=-combid*rad(iji,id)-comaid*rad(iji-1,id)
      end if
C
C     evaluation of the opacity, emissivity, scattering, and
C     their derivatives, at the current depth point ID;
C
      DO I=1,NN
         PSI0(I)=PSY0(I,ID)
      END DO
      IF(NFREQE.GT.0) THEN
         DO IJ=1,NFREQE
            IJT=IJFR(IJ)
            WDEP0(IJ)=W(IJT)
            RAD0(IJ)=RADEX(IJ,ID)
            FK0(IJ)=FAKEX(IJ,ID)
            ABSO0(IJ)=ABSOEX(IJ,ID)
            EMIS0(IJ)=EMISEX(IJ,ID)
            SCAT0(IJ)=SCATEX(IJ,ID)
         END DO
      END IF
C
      IF(ID.GT.1) THEN
         DO I=1,NN
            PSIM(I)=PSY0(I,ID-1)
         END DO
         IF(NFREQE.GT.0) THEN
         DO IJ=1,NFREQE
            IJT=IJFR(IJ)
            RADM(IJ)=RADEX(IJ,ID-1)
            FKM(IJ)=FAKEX(IJ,ID-1)
            ABSOM(IJ)=ABSOEX(IJ,ID-1)
            EMISM(IJ)=EMISEX(IJ,ID-1)
            SCATM(IJ)=SCATEX(IJ,ID-1)
         END DO
         END IF
      END IF
C
      IF(ID.LT.ND) THEN
         DO I=1,NN
            PSIP(I)=PSY0(I,ID+1)
         END DO
         IF(NFREQE.GT.0) THEN
         DO IJ=1,NFREQE
            IJT=IJFR(IJ)
            RADP(IJ)=RADEX(IJ,ID+1)
            FKP(IJ)=FAKEX(IJ,ID+1)
            ABSOP(IJ)=ABSOEX(IJ,ID+1)
            EMISP(IJ)=EMISEX(IJ,ID+1)
            SCATP(IJ)=SCATEX(IJ,ID+1)
         END DO
         END IF
      END IF
c
C
C     ------------------------------------------------------------
C     Actual evaluation of the rhs vector VECL
C     ------------------------------------------------------------
C
      DO I=1,NN
         VECL(I)=0.
      END DO
C
C     -----------------------------------------------------------
C     1. Radiative transfer components
C     -----------------------------------------------------------
C
C     For  ID = 1  -  upper boundary condition
C
      IF(ID.EQ.1) THEN
         DDP=DELDMZ(1)
         DO IJ=1,NFREQE
            IJT=IJFR(IJ)
            IF(IZSCAL.EQ.0) THEN
               OMEG0=ABSO0(IJ)/DENS(ID)
               OMEGP=ABSOP(IJ)/DENS(ID+1)
             ELSE
               OMEG0=ABSO0(IJ)
               OMEGP=ABSOP(IJ)
            END IF
            DZP=OMEG0+OMEGP
            DTAUP=DZP*DDP
            ALF1=(FK0(IJ)*RAD0(IJ)-FKP(IJ)*RADP(IJ))/DTAUP
            CHIEL0=SCAT0(IJ)
            CHIELP=SCATP(IJ)
            S0=(EMIS0(IJ)+CHIEL0*RAD0(IJ))/ABSO0(IJ)
            BS=HALF*DTAUP
            CS=0.
            C2=0.
            SP=0.
            BET2=0.
            GAM2=0.
c
c        additional terms for Compton scattering
c
            if(icompt.gt.0) then
             call compt0(ijt,id,abso0(ij),cma,cmb,cmc,cme,cms,cmd)
             s0=s0+cms
            end if
C
            IF(ISPLIN.GT.0) THEN
C
C      Spline collocation and/or Hermitian method (ISPLIN=1 or 2) -
C      both give the same expression for the boundary conditions
C
               BS=DTAUP*THIRD
               CS=HALF*BS
               SP=(EMISP(IJ)+CHIELP*RADP(IJ))/ABSOP(IJ)
               C2=CS/ABSOP(IJ)
               GAM2=CS*(RADP(IJ)-SP)
            END IF
C
C      auxiliary quantities
C
            ALF2=BS*(RAD0(IJ)-S0)
            BET2=ALF2+GAM2
C
C *** the IJ-th element of the rhs vector
C
            VECL(IJ)=ALF1+BET2+FH(IJT)*RAD0(IJ)
     *           -S0*Q0(IJT)
            IF(IWINBL.LT.0) VECL(IJ)=VECL(IJ)-HEXTRD(IJT)
C
         END DO

       ELSE IF(ID.LT.ND) THEN
C
C     For  1 < ID < ND  -  normal depth point
C
         DDM=DELDMZ(ID-1)
         DDP=DELDMZ(ID)
         DO IJ=1,NFREQE
            IF(IZSCAL.EQ.0) THEN
               OMEG0=ABSO0(IJ)/DENS(ID)
               OMEGP=ABSOP(IJ)/DENS(ID+1)
               OMEGM=ABSOM(IJ)/DENS(ID-1)
             ELSE
               OMEG0=ABSO0(IJ)
               OMEGP=ABSOP(IJ)
               OMEGM=ABSOM(IJ)
            END IF
            DZP=OMEG0+OMEGP
            DZM=OMEG0+OMEGM
            DTAUP=DZP*DDP
            DTAUM=DZM*DDM
            DTAU0=HALF*(DTAUP+DTAUM)
            FRD=FK0(IJ)*RAD0(IJ)
            ALF1=(FRD-FKP(IJ)*RADP(IJ))/DTAUP/DTAU0
            GAM1=(FRD-FKM(IJ)*RADM(IJ))/DTAUM/DTAU0
            BET1=ALF1+GAM1
            BS=UN
            CHIELM=SCATM(IJ)
            CHIEL0=SCAT0(IJ)
            CHIELP=SCATP(IJ)
            S0=(EMIS0(IJ)+CHIEL0*RAD0(IJ))/ABSO0(IJ)
            BET2=0.
c
c        additional terms for Compton scattering
c
            if(icompt.gt.0) then
             call compt0(ijt,id,abso0(ij),cma,cmb,cmc,cme,cms,cmd)
             s0=s0+cms
            end if
C
            IF(ISPLIN.EQ.1) THEN
C
C     spline collocation (ISPLIN=1)
C
               AS=DTAUM/DTAU0*SIXTH
               CS=DTAUP/DTAU0*SIXTH
               BS=0.666666666666667
               SM=(EMISM(IJ)+RADM(IJ)*CHIELM)/ABSOM(IJ)
               SP=(EMISP(IJ)+RADP(IJ)*CHIELP)/ABSOP(IJ)
               ALF2=AS*(RADM(IJ)-SM)
               GAM2=CS*(RADP(IJ)-SP)
               BET2=ALF2+GAM2
             ELSE IF(ISPLIN.EQ.2) THEN
C
C     Hermitian method (ISPLIN=2)
C
               AS=DTAUP*DTAUP/DTAUM/DTAU0
               CS=DTAUM*DTAUM/DTAUP/DTAU0
               SM=(EMISM(IJ)+RADM(IJ)*CHIELM)/ABSOM(IJ)
               SP=(EMISP(IJ)+RADP(IJ)*CHIELP)/ABSOP(IJ)
               AS=(UN-HALF*AS)*SIXTH
               CS=(UN-HALF*CS)*SIXTH
               BS=UN-AS-CS
               BET2=AS*(RADM(IJ)-SM)+CS*(RADP(IJ)-SP)
            END IF
C
C *** the IJ-th element of the rhs vector
C
            VECL(IJ)=BET1+BET2+BS*(RAD0(IJ)-S0)
         END DO

       ELSE
C
C   For ID=ND  -  lower boundary condition
C
         T=TEMP(ID)
         IF(TEMPBD.GT.0.) T=TEMPBD
         HKT=HK/T
         DDM=HALF*(DM(ID)-DM(ID-1))
C
c     the case of stellar atmospheres
C
         IF(IDISK.EQ.0.OR.IFZ0.LT.0) THEN
C
C     1. the case NDRE.le.ND, ie. radiative equilibrium equation at this
C        depth is treated as differential equation.
C
C     2. the case NDRE > ND, ie. radiative equilibrium equation at this
C        depth is treated as integral equation.
C        Boundary condition of the transfer equation is then complex,
C        because it has to incorporate the constraint of the total flux
C        equal to SIG4P*Teff**4 (integral form of the radiative
C        equation does not fix the total flux)
C
C        Details of this approach are presented in Mihalas, Heasley, Auer
C        NCAR-TN/STR-104 (1975).
C
C        This option is presented here for the sake of continuity with
C        previous work; otherwise the first option (NDRE.le.ND) is
C        recommended due to its better numerical properties
C
C        auxiliary quantities for the second option
C
            IF(ID.LT.NDRE.AND.INRE.NE.0) THEN
               SUMB=0.
               SUMF=0.
               DO IJ=1,NFREQE
                  IJT=IJFR(IJ)
                  FR=FREQ(IJT)
                  FR15=FR*1.D-15
                  WD=WDEP0(IJ)
                  X=HKT*FR
                  EX=EXP(X)
                  PLAN=BN*FR15*FR15*FR15/(EX-UN)*RRDIL
                  DPLAN=PLAN*X/T/(UN-UN/EX)*WD
                  SUMB=SUMB+(PLAN-RAD0(IJ))*WD
                  FI=DPLAN/ABSO0(IJ)
                  SUMF=SUMF+FI
               END DO
               FL=SIG4P*TEFF*TEFF*TEFF*TEFF
               ZZ=(FL-HALF*SUMB)/SUMF
            END IF
C
C        auxiliary quantities for both options
C
            DO IJ=1,NFREQE
               IJT=IJFR(IJ)
               CHIELM=SCATM(IJ)
               CHIEL0=SCAT0(IJ)
               IF(IZSCAL.EQ.0) THEN
                  OMEG0=ABSO0(IJ)/DENS(ID)
                  OMEGM=ABSOM(IJ)/DENS(ID-1)
                ELSE
                  OMEG0=ABSO0(IJ)
                  OMEGM=ABSOM(IJ)
               END IF
               DZM=OMEG0+OMEGM
               DTAUM=DZM*DDM
               GAM1=(FK0(IJ)*RAD0(IJ)-FKM(IJ)*RADM(IJ))/DTAUM
               BET2=0.
C
C        second-order boundary condition
C
               IF(IBC.GT.0.AND.IBC.LT.4) THEN
                  BS=DTAUM*HALF
                  S0=(EMIS0(IJ)+CHIEL0*RAD0(IJ))/ABSO0(IJ)
c
c              additional terms for Compton scattering
c
                  if(icompt.gt.0) then
                   call compt0(ijt,id,abso0(ij),cma,cmb,cmc,cme,cms,cmd)
                   s0=s0+cms
                  end if
C
                  BET2=BS*(RAD0(IJ)-S0)
               END IF
C
               FR=FREQ(IJT)
               X=HKT*FR
               EX=EXP(X)
               PLAN=BN*(FR*1.D-15)**3/(EX-UN)*RRDIL
               IF(INRE.EQ.0.OR.ID.GE.NDRE) THEN
                  DPLAN=BN*(FR*1.D-15)**3/(EXP(HK*FR/TEMP(ID-1))-UN)
                  GAM1=GAM1-(PLAN-DPLAN)/DTAUM*THIRD
               ELSE
                  DPLAN=PLAN*X/T/(UN-UN/EX)
                  FI=DPLAN/ABSO0(IJ)
                  X1=FI*ZZ
                  GAM1=GAM1-X1
               END IF
C
C *** the IJ-th element of the rhs vector
C
               IF(IBC.EQ.0.OR.IBC.EQ.4) THEN
                  VECL(IJ)=GAM1+BET2-HALF*(PLAN-RAD0(IJ))
                ELSE
                  VECL(IJ)=GAM1+BET2-HALF*PLAN+FHD(IJT)*RAD0(IJ)
               END IF
            END DO
C
C     the case of accretion disks
C
         ELSE
C
            DO IJ=IJ1,NFREQE
               CHIELM=SCATM(IJ)
               CHIEL0=SCAT0(IJ)
               IF(IZSCAL.EQ.0) THEN
                  OMEG0=ABSO0(IJ)/DENS(ID)
                  OMEGM=ABSOM(IJ)/DENS(ID-1)
                ELSE
                  OMEG0=ABSO0(IJ)
                  OMEGM=ABSOM(IJ)
               END IF
               DZM=OMEG0+OMEGM
               DTAUM=DZM*DDM
               FRD=FK0(IJ)*RAD0(IJ)-FKM(IJ)*RADM(IJ)
               GAM1=FRD/DTAUM
               BS=DTAUM*HALF
               S0=(EMIS0(IJ)+CHIEL0*RAD0(IJ))/ABSO0(IJ)
               GAM2=BS*(RAD0(IJ)-S0)
C
C *** the IJ-th element of the rhs vector
C
               VECL(IJ)=GAM1+GAM2
            END DO
         END IF
      END IF
C
C     -----------------------------------------------------------
C     2. Hydrostatic equilibrium
C     -----------------------------------------------------------
C
      isplin=ispl
      IF(INHE.GT.0) THEN
         NHE=NFREQE+INHE
         GRP=0.
C
         IF(ID.EQ.1) THEN
C
C     Upper boundary condition (ID=1)
C     Basically, linearized eq. (7-10) of Mihalas (1978)
C
            IF(IDISK.EQ.0.OR.IBCHE.EQ.0) THEN
               DO IJ=1,NFREQE
                  IJT=IJFR(IJ)
                  IF(.NOT.LSKIP(ID,IJT)) THEN
                     FLUXW=W(IJT)*(FH(IJT)*RAD0(IJ)-HEXTRD(IJT))
                     GRP=GRP+FLUXW*ABSO0(IJ)
                  END IF
               END DO
C
               X1=PCK/DENS(ID)*FPRAD(ID)
               VT0=HALF*VTURB(ID)*VTURB(ID)/DM(ID)*WMM(ID)
C
C     The rhs vector also accounts for the total radiation pressure in
C     the fixed-option transitions (array FPRD, generated by FIXLIN)
C
               VECL(NHE)=GRAV-BOLK*TEMP(ID)*PSI0(NHE)/DM(ID)-
     *            X1*(GRP+FPRD(ID))-VT0/WMM(ID)*DENS(ID)
C
C
C        specifically disk
C
            ELSE
               IF(IBCHE.EQ.1) THEN
C
C              newer variant
C
                  CCC=PCK/QGRAV
                  HR1=CCC*SIG4P*TEFF**4*ABROSD(1)
                  PG1=BOLK*PSI0(NHE)*TEMP(1)
                  HG1=SQRT(TWO*PG1/DENS(1)/QGRAV)
                  X=(ZD(1)-HR1)/HG1
                  IF(X.LT.3.) THEN
                     IF(X.LT.0.) X=0.
                     F1=8.86226925D-1*EXP(X*X)*ERFCX(X)
                   ELSE
                     F1=HALF*(UN-HALF/X/X)/X
                  END IF
                  GGG=DENS(1)*HG1*F1
                  VECL(NHE)=DM(1)-GGG
C
C            older variant
C
                ELSE IF(IBCHE.EQ.2) THEN
                  DO IJ=IJ1,NFREQE
                     IJT=IJFR(IJ)
                     IF(.NOT.LSKIP(ID,IJT)) THEN
                        FLUXW=W(IJT)*FH(IJT)*RAD0(IJ)
                        GRP=GRP+FLUXW*ABSO0(IJ)
                     END IF
                  END DO
C
                  CCC=PCK/QGRAV
                  HR1=CCC*(GRP+FPRD(1))/DENS(1)
                  PG1=BOLK*PSI0(NHE)*TEMP(1)
                  HG1=SQRT(TWO*PG1/DENS(1)/QGRAV)
                  X=(ZD(1)-HR1)/HG1
                  IF(X.LT.3.) THEN
                     IF(X.LT.0.) X=0.
                     F1=8.86226925D-1*EXP(X*X)*ERFCX(X)
                   ELSE
                     F1=HALF*(UN-HALF/X/X)/X
                  END IF
                  GGG=HG1*QGRAV*HALF/F1
C
C        The rhs vector
C
                  VECL(NHE)=DM(1)*GGG-PG1
                ELSE
                  VECL(NHE)=PGAS0-BOLK*TEMP(1)*PSI0(NHE)
               END IF
            END IF
C
         ELSE
C
C     Normal depth point (ID > 1)
C
C
            DO IJ=1,NFREQE
               IF(.NOT.LSKIP(ID,IJFR(IJ)))
     *         GRP=GRP+(FK0(IJ)*RAD0(IJ)-FKM(IJ)*RADM(IJ))*W(IJFR(IJ))
            END DO
C
            VT0=HALF*VTURB(ID)*VTURB(ID)*WMM(ID)
            VTM=HALF*VTURB(ID-1)*VTURB(ID-1)*WMM(ID-1)
C
C     the rhs vector
C     again, which accounts for the total radiation pressure in the
C     fixed-option transitions (array FPRD, generated by FIXLIN)
C
            PCX=PCK*FPRAD(ID)
            IF(IDISK.EQ.0) PCX=PCK*FPRAD(ID)
            IF(IDISK.EQ.1) GRAV=QGRAV*(ZD(ID)+ZD(ID-1))*HALF
            IF(IZSCAL.EQ.0) THEN
               VECL(NHE)=GRAV*(DM(ID)-DM(ID-1))-
     *            BOLK*(TEMP(ID)*PSI0(NHE)-TEMP(ID-1)*PSIM(NHE))-
     *            PCX*(GRP+FPRD(ID))-
     *            VT0/WMM(ID)*DENS(ID)+VTM/WMM(ID-1)*DENS(ID-1)
             ELSE
               GRAVZ=GRAV*(ZD(ID)-ZD(ID-1))
               VECL(NHE)=-GRAVZ*(DENS(ID)+DENS(ID-1))*HALF-
     *            BOLK*(TEMP(ID)*PSI0(NHE)-TEMP(ID-1)*PSIM(NHE))-
     *            PCX*(GRP+FPRD(ID))-
     *            VT0/WMM(ID)*DENS(ID)+VTM/WMM(ID-1)*DENS(ID-1)
            END IF
         END IF

      END IF
C
C     -----------------------------------------------------------
C     2a. z-m relation
C     -----------------------------------------------------------
C
      IF(INZD.GT.0.AND.ID.LT.ND.AND.IDISK.GT.0) THEN
         NZD=NFREQE+INZD
         DDP=(DM(ID+1)-DM(ID))*HALF
         VECL(NZD)=ZD(ID+1)-ZD(ID)+DDP/DENS(ID)+DDP/DENS(ID+1)
      END IF
C
C     -----------------------------------------------------------
C     3. Radiative equilibrium
C     -----------------------------------------------------------
C
      IF(INRE.GT.0) THEN
         NRE=NFREQE+INRE
C
C     integral equation part of the radiative
C     equilibrium equation
C
C     the rhs vector accounts for total net cooling in ALI transitions
C
         VECL(NRE)=FCOOL(ID)
         IF(IDISK.EQ.1) VECL(NRE)=FCOOL(ID)-TVISC(ID)*reint(id)
C
         IF(REINT(ID).GT.0.AND.NFREQE.GT.0) THEN
            DO IJ=1,NFREQE
               HEAT=ABSO0(IJ)-SCAT0(IJ)
               VECL(NRE)=VECL(NRE)-
     *                (HEAT*RAD0(IJ)-EMIS0(IJ))*WDEP0(IJ)*reint(id)
c
c           additional terms for Compton scattering
c
               if(icompt.gt.5) then
                  ijt=ijfr(ij)
                  call compt0(ijt,id,abso0(ij),cma,cmb,cmc,cme,cms,cmd)
                  vecl(nre)=vecl(nre)+abso0(ij)*cms*wdep0(ij)*reint(id)
               end if
c
            END DO
         END IF
C
C
C     differential equation part of the
C     radiative equilibrium equation
C
         if(redif(id).gt.0) then
            TEFFD=TEFF**4
            IF(IDISK.EQ.1) TEFFD=TEFFD*(UN-THETAV(ID))
            VECL(NRE)=vecl(nre)+SIG4P*TEFFD*redif(id)
            IF(ID.GT.1) THEN
               DDM=(DM(ID)-DM(ID-1))*HALF
                  DO IJ=1,NFREQE
                     OMEG0=ABSO0(IJ)*DENSI(ID)
                     OMEGM=ABSOM(IJ)*DENSI(ID-1)
                     DTAUM=(OMEG0+OMEGM)*DDM
                     FRD=FK0(IJ)*RAD0(IJ)-FKM(IJ)*RADM(IJ)
                     GAMR=FRD/DTAUM
                     VECL(NRE)=VECL(NRE)-WDEP0(IJ)*GAMR*redif(id)
                  END DO
              ELSE
                  DO IJ=1,NFREQE
                     IJT=IJFR(IJ)
                     VECL(NRE)=VECL(NRE)-
     *                      WDEP0(IJ)*FH(IJT)*RAD0(IJ)*REDIF(ID)
                  END DO
            END IF
         end if

         ITTC=ABS(NRETC)/100
         IF(ITER.GT.ITTC) THEN
            if(id.le.mod(abs(nretc),100)) then
               if(nretc.lt.0) vecl(nre)=temp(-nretc+1)-temp(id)
            end if
         END IF

      END IF
C
C     -----------------------------------------------------------
C     4. Statistical equilibrium
C     -----------------------------------------------------------
C
      IF(IABS(IFPOPR).GE.3.and.ifpopr.le.5) THEN
         if(inse.gt.0) then
         NSE=NFREQE+INSE-1
         CALL SABOLF(ID)
         CALL LEVGRP(ID,IIEXP,0,POPP)
         CALL RATMAT(ID,IIEXP,0)
         IF(IFPOPR.LE.3) THEN
            CALL MATINV(ESEMAT,NLVEXP,MLEVEL)
            DO I=1,NLVEXP
               SUME=0.
               DO J=1,NLVEXP
                  SUME=SUME+ESEMAT(I,J)*BESE(J)
               END DO
               VECL(NSE+I)=POPGRP(I)-SUME
               IF(IGZERO(I,ID).GT.0) VECL(NFREQE+INSE-1+I)=0.
            END DO
          ELSE
            DO I=1,NLVEXP
               SUME=0.
               DO J=1,NLVEXP
                  SUME=SUME+ESEMAT(I,J)*POPGRP(J)
               END DO
               VECL(NSE+I)=BESE(I)-SUME
               IF(IGZERO(I,ID).GT.0) VECL(NFREQE+INSE-1+I)=0.
           END DO
         END IF
         end if
      END IF
C
C     -----------------------------------------------------------
C     5. charge conservation
C     -----------------------------------------------------------
C
      IF(INPC.GT.0) THEN
         NPC=NFREQE+INPC
C
C     This part is very similar to procedure ELCOR (obviously);
C     array AJ has the meaning of coefficients of the charge conserv.
C     ie. charge conservation is written
C           AJ * (vector of populations) = electron density
C
         T=TEMP(ID)
         ANE=ELEC(ID)
         CALL STATE(2,ID,T,ANE)
C
         VPC=QFIX(ID)+Q*DENS(ID)/WMM(ID)/YTOT(ID)
         IF(IOPTAB.EQ.0) VPC=VPC*ABUND(IATREF,ID)
         DO IAT=1,NATOM
            IF(IIFIX(IAT).NE.1) THEN
            DO I=N0A(IAT),NKA(IAT)
               IL=ILK(I)
               CH=IZ(IEL(I))-1
               IF(IL.GT.0) CH=IZ(IL)+(IZ(IL)-1)*ANE*USUMS(IL,ID)
               IF(IMODL(I).GE.0) VPC=VPC+CH*POPUL(I,ID)
            END DO
            END IF
         END DO
C
         VECL(NPC)=ANE-VPC
      END IF
C
C     -----------------------------------------------------------
C     6. Convection
C     -----------------------------------------------------------
C
      IF(HMIX0.GT.0.) THEN
         NRE=NFREQE+INRE
         NDEL=NFREQE+INDL
C
C     Upper boundary condition (ID=1)
C
         ANEREL=ELEC(1)/(DENS(1)/WMM(1)+ELEC(1))
         IF(ID.EQ.1) THEN
            DELTA(ID)=0.
            FLXC(ID)=0.
         ELSE
C
C     Normal depth point 1 < ID < ND
C
            T=TEMP(ID)
            P=PTOTAL(ID)
            PG=PGS(ID)
            PRAD=P-PG-HALF*DENS(ID)*VTURB(ID)**2
            TM=TEMP(ID-1)
            PM=PTOTAL(ID-1)
            PGM=PGS(ID-1)
            PRADM=PM-PGM-HALF*DENS(ID-1)*VTURB(ID-1)**2
            T0=HALF*(T+TM)
            P0=HALF*(P+PM)
            PG0=HALF*(PG+PGM)
            PR0=HALF*(PRAD+PRADM)
            AB0=HALF*(ABROSD(ID)+ABROSD(ID-1))
            DLT=(T-TM)/(P-PM)*P0/T0
            DELTA(ID)=DLT
            IF(INDL.GT.0) VECL(NDEL)=DELTA(ID)-DLT
            IF(IDISK.EQ.1) GRAVD=ZD(ID)*QGRAV
C
C        convective flux
C
            CALL CONVEC(ID,T0,P0,PG0,PR0,AB0,DLT,FLXCNV,VCON)
            FLXC(ID)=FLXCNV
            if(redif(id).gt.0) then
               VECL(NRE)=VECL(NRE)-FLXC(ID)*redif(id)
            end if
   
            if(reint(id).gt.0.AND.ICONV.NE.0) then
               TP=TEMP(ID+1)
               PM=PTOTAL(ID+1)
               PGP=PGS(ID+1)
               PRADP=PM-PGP-HALF*DENS(ID+1)*VTURB(ID+1)**2
               T0=HALF*(T+TP)
               P0=HALF*(P+PM)
               PG0=HALF*(PG+PGP)
               PR0=HALF*(PRAD+PRADP)
               AB0=HALF*(ABROSD(ID)+ABROSD(ID+1))
               DLT=(TP-T)/(PM-P)*(PM+P)/(TP+T)
               CALL CONVEC(ID+1,T0,P0,PG0,PR0,AB0,DLT,FLXCP,VCON)
               DELM=(DM(ID+1)-DM(ID))*HALF
               RDELM=DENS(ID)/DELM
               VECL(NRE)=VECL(NRE)-RDELM*(FLXCP-FLXCNV)*reint(id)
            end if
         END IF
      END IF
C
C     skip rows corresponding to fully-zeroed populations
C
      NSE=NFREQE+INSE
      INONZ=NSE
      DO II=NSE,NN0
         IF(IGZERT(II-NSE+1).EQ.0) THEN
            IF(INONZ.NE.II) VECL(INONZ)=VECL(II)
            INONZ=INONZ+1
         END IF
      END DO
C
      RETURN
      END SUBROUTINE RHSGEN
C
C
C     ****************************************************************
C
C

      SUBROUTINE PRCHAN(CHANG,CHM,CHMT,CHPOP)
C     =======================================
C
C     Diagnostic output of relative changes of vector PSI
C
C     Input:
C      CHANG - array of relative changes of vector PSI at depth ID
C      ID    - depth index
C     Output:
C      CHM   - maximum relative change of all unknowns at all depths
C      CHMT  - maximum relative change in temperature at all depths
C      CHPOP - maximum relative change in populations at all depths
C
      use accura
      use atomic
      use basics
      use iterat
      use modelq

      implicit none

      REAL(DP), INTENT(IN) :: CHANG(MTOT,MDEPTH)
      REAL(DP), INTENT(OUT):: CHM,CHMT,CHPOP
      REAL(DP) :: CHANM(MDEPTH)

      REAL(DP) :: CH,CHRAD,CHT,CHE
      INTEGER  :: I1,I,ID,II,JJR,JJP,ITL
C
C     maximum relative change of all unknowns in depth ID
C
      CHMT=0.
      I1=1
      if(icompt.gt.0.and.icombc.gt.0.and.ijex(1).gt.0) i1=2
      DO ID=ND,1,-1
         CH=0.
         chrad=0.
         chpop=0.
         cht=0.
         che=0.
         DO I=I1,NN
            IF(ITER.EQ.1.AND.I.EQ.NFREQE+INDL) CYCLE
            IF(I.GE.NFREQE+INSE) THEN
               II=INDLGZ(I-NFREQE-INSE+1)
               IF(RPOP0(II,ID).LT.POPZCH) CYCLE
            END IF
            IF(ABS(CHANG(I,ID)).LT.ABS(CH)) CYCLE
            CH=CHANG(I,ID)
         END DO
         CHANM(ID)=CH
         IF(NFREQE.GT.0) THEN
            DO I=I1,NFREQE
               IF(ABS(CHANG(I,ID)).LT.ABS(CHRAD)) CYCLE
               CHRAD=CHANG(I,ID)
               jjr=i
            END DO
         END IF
         DO I=NFREQE+INSE,NFREQE+INSE+NLVEXZ-1
            II=INDLGZ(I-NFREQE-INSE+1)
            IF(RPOP0(II,ID).LT.POPZCH) CYCLE
            IF(ABS(CHANG(I,ID)).LT.ABS(CHPOP)) CYCLE
            CHpop=CHANG(I,ID)
            jjp=ii
         END DO
         if(inre.gt.0) then
            cht=chang(nfreqe+inre,id)
            if(abs(cht).ge.abs(chmt)) chmt=abs(cht)
         end if
         if(inpc.gt.0) che=chang(nfreqe+inpc,id)
C
C        output onto file 9
C
         IF(ID.EQ.ND.AND.ITER.EQ.1) 
     &      WRITE(9,"(' RELATIVE CHANGES OF VECTOR PSI'/
     &   '  ITER  ID    TEMP        NE       POP     RAD      MAXIMUM',
     &   '   ilev   ifr',/)")
         WRITE(9,"(2I5,1P5e10.2,2i5)") 
     &      ITER,ID,cht,che,CHpop,CHrad,ch,jjp,jjr
      END DO
C
C     determination of the maximum relative change of all unknowns
C     at all depths
C
      CHM=0.
      DO I=1,ND
         IF(ABS(CHANM(I)).GE.ABS(CHM)) CHM=CHANM(I)
      END DO
C
      if(chmt.lt.chmaxt) then
         do itl=iter,niter+1
            nitlam(itl)=nlamt
         end do
      end if
      chpop=abs(chpop)
      RETURN
      END SUBROUTINE PRCHAN
C
C
C     ****************************************************************
C
C

      SUBROUTINE COMPT0(IJ,ID,ab,compa,compb,compc,compe,comps,compd)
C     ===============================================================
C
c     auxiliary quantities for the Compton scattering source function
c
      use accura
      use alipar
      use basics
      use iterat
      use modelq

      implicit none

      INTEGER, INTENT(IN) :: IJ,ID
      REAL(DP),INTENT(IN) :: AB
      REAL(DP),INTENT(OUT):: COMPA,COMPB,COMPC,COMPE,COMPS,COMPD

      REAL(DP),PARAMETER :: XCON=8.0935e-21,YCON=1.68638e-10

      REAL(DP) :: FR,FRP,FRM,XCOMP,E1,E2,DEL0,SS0,EPSNU,X0,
     *            ZXX0,ZXXM,ZXXP,ZXXP12,ZXXM12,COMPU,COMPV,CBS
      INTEGER  :: IJI
c
      IJI=NFREQ-KIJ(IJ)+1
!     if(iji.eq.1) then
         compa=0.
         compb=0.
         compc=0.
         compd=0.
         compe=0.
         comps=0.
         compu=0.
         compv=0.
         cbs  =0.
      if(iji.eq.1) then
         return
      end if
c
      FR=FREQ(IJ)
      frp=freq(ijorig(iji+1))
      frm=freq(ijorig(iji-1))
      xcomp=fr*xcon
      e2=ycon*temp(id)
      e1=xcomp-3.*e2
c
      del0=two/(dlnfr(iji)+dlnfr(iji-1))
      cder1p(iji)=(un-delj(iji,id))*del0
      cder1m(iji)=-delj(iji-1,id)*del0
      cder10(iji)=-del0*(un-delj(iji-1,id)-delj(iji,id))
      ss0=elec(id)*sige/ab
      if(ichcoo.eq.0) then
         cder10(iji)=-cder1m(iji)-cder1p(iji)
         compa=ss0*(e1*cder1m(iji)+e2*cder2m(iji))
         compb=ss0*(un-xcomp-sigec(ij)/sige+e1*cder10(iji)+
     *         e2*cder20(iji))
         compc=ss0*(e1*cder1p(iji)+e2*cder2p(iji))
       else
         epsnu=(ab-elec(id)*sigec(ij))/ab
         zxxp=xcon*frp+0.5*bnus(iji+1)*rad(iji+1,id)-3.*e2
         zxx0=xcomp+0.5*bnus(iji)*rad(iji,id)-3.*e2
         zxxm=xcon*frm+0.5*bnus(iji-1)*rad(iji-1,id)-3.*e2
         zxxp12=((un-delj(iji,id))*zxxp+delj(iji,id)*zxx0)*del0
         zxxm12=((un-delj(iji-1,id))*zxx0+delj(iji-1,id)*zxxm)*del0
         compa=ss0*(-delj(iji-1,id)*zxxm12+e2*cder2m(iji))
         compc=ss0*((un-delj(iji,id))*zxxp12+e2*cder2p(iji))
         compb=ss0*(delj(iji,id)*zxxp12-(un-delj(iji-1,id))*zxxm12+
     *         e2*cder20(iji)-sigec(ij)/sige)-epsnu+1.
         compe=0.
      end if
      compd=(-3.*cder10(iji)+cder20(iji))*rad(iji,id)
c
      IF(ICOMDE.EQ.0) THEN
         COMPA=0.
         COMPC=0.
         COMPB=0.
      END IF
c
      x0=ss0*bnus(iji)
      if(icomst.eq.0) x0=0.
      if(ichcoo.eq.0) then
         compe=x0*(cder10(iji)-un)
         compu=x0*cder1m(iji)
         compv=x0*cder1p(iji)
         cbs=compe*rad(iji,id)
         compe=cbs
      end if
      comps=compb*rad(iji,id)
      if(iji.gt.1) then
         if(ichcoo.eq.0) cbs=cbs+compu*rad(iji-1,id)
         comps=comps+compa*rad(iji-1,id)
         compd=compd+(-3.*cder1m(iji)+cder2m(iji))*rad(iji-1,id)
      end if
      if(iji.lt.nfreq) then
         if(ichcoo.eq.0) cbs=cbs+compv*rad(iji+1,id)
         comps=comps+compc*rad(iji+1,id)
         compd=compd+(-3.*cder1p(iji)+cder2p(iji))*rad(iji+1,id)
      end if
      if(ichcoo.eq.0) then
         compb=compb+cbs
         compa=compa+compu*rad(iji,id)
         compc=compc+compv*rad(iji,id)
         comps=comps+cbs*rad(iji,id)
      end if
      compd=compd*ss0*ycon
      IF(ICOMDE.EQ.0) COMPD=0.
c
c     a variant with ICOMPT=2 - no off-diagonal terms in intensity
c
      if(icompt.eq.2) then
         if(iji.gt.1) compb=compb+compa*rad(iji-1,id)
         if(iji.lt.nfreq) compb=compb+compc*rad(iji+1,id)
         compa=0.
         compc=0.
       else if(icompt.eq.3) then
         compa=0.
         compb=0.
         compc=0.
      end if
      return
      end subroutine compt0
C
C
C     ****************************************************************
C
C

!     include 'modules.f'
!     program rybtes
!     write(*,*) 'rybtes'
!     end program rybtes
C
C
C     ****************************************************************
C
C

      SUBROUTINE RYBMAT(IJ)
C     =====================
C
C     evaluation of the complete-linearization matrices in the Rybicki
c     formalism
c
      use accura
CC    use alipar
CC    use array1
      use basics
      use modelq
      use rybpar

      implicit none

      INTEGER, INTENT(IN) :: IJ
      REAL(DP), PARAMETER :: SIXTH=UN/6.0,
     *                       THIRD=UN/3.0,
     *                       TWOTHR=TWO/3.0
C
      REAL(DP) :: DDM,DTM,DTM2,FD,EXTI,BEP,GAM,S0,C1,B1,UNQ,CORF,
     *            DDP,DZM,DZP,DTAUM,DTAU0,FRD,ALF1,BET1,GAM1,X1,
     *            A1,BS,CHIELM,CHIEL0,CHIELP,AS,CS,A2,C2,A3,C3,BET2,
     *            SM,SP,ALF2,GAM2,X,AL3,GA3,AV,CV,B2,B3,T0,TM,DTAUP,
     *            FR,FR15,BNU,X0,XM,PLAND,PLANM,DPLDT0,DPLDTM,DPLAN,
     *            HEAT,DHEAT,WDR,WF,OMEG0,OMEGM,GAMR,WWR,FRM,FRP,FLX,
     *            DMTM,DMTP,RM,RP,ALP,DT0,DTP
      INTEGER  :: ID,ND1,ICENTR


C     ==============================================================
C     1. components corresponding to the radiative transfer equation
C     ==============================================================
C
C     -----------------------------------
C     ID = 1  -  upper boundary condition
C
      ID=1
      DDM=(DM(ID+1)-DM(ID))*HALF
      DTM=UN/((ABSO1(ID)+ABSO1(ID+1))*DDM)
      DTM2=DTM*DTM
      ALP=DTM*DDM
      FD=TWO*FH(IJ)
      EXTI=EXTRAD(IJ)
      BEP=(EXTI-FD*RAD1(ID))*DTM
      GAM=(FAK1(ID)*RAD1(ID)-FAK1(ID+1)*RAD1(ID+1))*TWO*DTM2
      S0=(EMIS1(ID)+SCAT1(ID)*RAD1(ID))/ABSO1(ID)
      C1=ALP*(TWO*GAM-BEP)
      B1=C1-S0/ABSO1(ID)
      UNQ=UN+TWO*DTM*Q0(IJ)
c     unq=un
      RB(ID)=-(UN+DTM*(FD+TWO*FAK1(ID)*DTM))+
     *        SCAT1(ID)/ABSO1(ID)*UNQ
      RC(ID)= TWO*FAK1(ID+1)*DTM2
      VR(ID)= GAM-BEP+RAD1(ID)-S0*UNQ
      UB(ID)= B1*DABT1(ID)+(DEMT1(ID)+
     *        DSCT1(ID)*RAD1(ID))/ABSO1(ID)*UNQ-
     *        emis1(id)/abso1(id)**2*dabt1(id)*two*dtm*q0(ij)+
     *        dtm*s0*(uu0(ij)*dm(1)*dabt1(id)-
     *        two*q0(ij)*dtm*ddm*dabt1(id))
      UC(ID)= C1*DABT1(ID+1)-two*dtm*q0(ij)*s0*dtm*ddm*dabt1(id+1)
      if(ij.eq.42) write(6,"('u',1p10e10.2)")
     * c1,dabt1(id+1),alp,two,gam,bep,dtm,ddm,s0,uc(id)
c
      if(iubc.gt.0) then
         corf=half/dtm
         rb(id)=rb(id)*corf
         rc(id)=rc(id)*corf
         vr(id)=vr(id)*corf
         c1=(gam-rad1(id)+s0)*corf*alp
         b1=c1-corf*s0/abso1(id)
         UB(ID)= B1*DABT1(ID)+(DEMT1(ID)+
     *           DSCT1(ID)*RAD1(ID))/ABSO1(ID)*corf
         UC(ID)= C1*DABT1(ID+1)
      end if
C
C
C     ----------------------------------
C     1 < ID < ND  -  normal depth point
C
      DO ID=2,ND-1
         DDM=(DM(ID)-DM(ID-1))*HALF
         DDP=(DM(ID+1)-DM(ID))*HALF
         DZM=ABSO1(ID)+ABSO1(ID-1)
         DZP=ABSO1(ID)+ABSO1(ID+1)
         DTAUP=DZP*DDP
         DTAUM=DZM*DDM
         DTAU0=HALF *(DTAUP+DTAUM)
         FRD=FAK1(ID)*RAD1(ID)
         ALF1=(FRD-FAK1(ID+1)*RAD1(ID+1))/DTAUP/DTAU0
         GAM1=(FRD-FAK1(ID-1)*RAD1(ID-1))/DTAUM/DTAU0
         BET1=ALF1+GAM1
         X1=HALF *BET1/DTAU0
         A1=(GAM1+X1*DTAUM)/DZM
         C1=(ALF1+X1*DTAUP)/DZP
         B1=A1+C1
         BS=UN
         CHIELM=SCAT1(ID-1)
         CHIEL0=SCAT1(ID)
         CHIELP=SCAT1(ID+1)
         S0=(EMIS1(ID)+CHIEL0*RAD1(ID))/ABSO1(ID)
         AS=0.
         CS=0.
         A2=0.
         C2=0.
         A3=0.
         C3=0.
         BET2=0.
         SM=0.
         SP=0.
         IF(MOD(ISPLIN,3).NE.0) THEN
            SM=(EMIS1(ID-1)+RAD1(ID-1)*CHIELM)/ABSO1(ID-1)
            SP=(EMIS1(ID+1)+RAD1(ID+1)*CHIELP)/ABSO1(ID+1)

            IF(ISPLIN.EQ.1) THEN
C
C     spline collocation (ISPLIN=1)
C
               AS=DTAUM/DTAU0*SIXTH
               CS=DTAUP/DTAU0*SIXTH
               BS=0.666666666666667D0
               ALF2=AS*(RAD1(ID-1)-SM)
               GAM2=CS*(RAD1(ID+1)-SP)
               BET2=ALF2+GAM2
               X =HALF *BET2/DTAU0
               A2=(GAM2-X*DTAUM)/DZM
               C2=(ALF2-X*DTAUP)/DZP
             ELSE
C
C     Hermitian method (ISPLIN=2)
C
               AS=DTAUP*DTAUP/DTAUM/DTAU0
               CS=DTAUM*DTAUM/DTAUP/DTAU0
               AL3=(RAD1(ID+1)-SP-RAD1(ID)+S0)*SIXTH
               GA3=(RAD1(ID-1)-SM-RAD1(ID)+S0)*SIXTH
               AV=AL3*CS
               CV=GA3*AS
               AS=(UN-HALF *AS)*SIXTH
               CS=(UN-HALF *CS)*SIXTH
               BS=UN-AS-CS
               X=(AV+CV)/DTAU0/4.D0
               A2=(X*DTAUM+HALF *CV-AV)/DZM
               C2=(X*DTAUP+HALF *AV-CV)/DZP
               BET2=AS*(RAD1(ID-1)-SM)+CS*(RAD1(ID+1)-SP)
            END IF
C
C     auxiliary quantities
C
            B1=B1-(A2+C2)
            A1=A1-A2
            C1=C1-C2
            A2=AS/ABSO1(ID-1)
            C2=CS/ABSO1(ID+1)
            A3=A2*SM
            C3=C2*SP
         END IF

         B2=BS/ABSO1(ID)
         B3=B2*S0
         A1=A1-A3
         B1=B1-B3
         C1=C1-C3
C
C *** elements of the matrices
C
         RA(ID)= FAK1(ID-1)/DTAUM/DTAU0-AS*(UN-CHIELM/ABSO1(ID-1))
         RB(ID)=-FAK1(ID)/DTAU0*(UN/DTAUP+UN/DTAUM)-
     *             BS*(UN-CHIEL0/ABSO1(ID))
         RC(ID)= FAK1(ID+1)/DTAUP/DTAU0-CS*(UN-CHIELP/ABSO1(ID+1))
         VR(ID)= BET1+BET2+BS*(RAD1(ID)-S0)
         UA(ID)= A1*DABT1(ID-1)+A2*(DEMT1(ID-1)+DSCT1(ID-1)*RAD1(ID-1))
         UB(ID)= B1*DABT1(ID)+B2*(DEMT1(ID)+DSCT1(ID)*RAD1(ID))
         UC(ID)= C1*DABT1(ID+1)+C2*(DEMT1(ID+1)+DSCT1(ID+1)*RAD1(ID+1))
!        if(id.eq.nd-1) write(64,"(i7,1p9e14.6)") ij,freq(ij),
!    *   bet1,bet2,bs,rad1(id),s0,bet1+bet2,bs*(rad1(id)-s0),vr(id)
!        if(id.eq.52) write(65,"(i7,1p9e14.6)") ij,freq(ij),
!    *   bet1,bet2,bs,rad1(id),s0,bet1+bet2,bs*(rad1(id)-s0),vr(id)
   
c        if(ij.le.2) then
c          write(6,"('umat',2i4,1p10e12.4)") ij,id,
c    *     dabt1(id),demt1(id),dsct1(id),rad1(id),b1,b2,bs,abso1(id),
c    *     dtau0,ub(id)
c        end if
      END DO
C
C   ----------------------------------
C   ID=ND  -  lower boundary condition
C
      ID=ND
      DDM=HALF*(DM(ID)-DM(ID-1))
      T0=TEMP(ID)
      TM=TEMP(ID-1)
      IF(IBC.GT.0.AND.IBC.LT.4.AND.IDISK.EQ.0) THEN
         DTM=UN/((ABSO1(ID-1)+ABSO1(ID))*DDM)
         DTM2=DTM*DTM

         FD=TWO*FHD(IJ)
         FR=FREQ(IJ)
         FR15=FR*1.D-15
         BNU=BN*FR15*FR15*FR15
         X0=HK*FR/T0
         XM=HK*FR/TM
         PLAND=BNU/(EXP(X0)-UN)
         PLANM=BNU/(EXP(XM)-UN)
         DPLDT0=PLAND/(UN-EXP(-X0))*X0/T0
         DPLDTM=PLANM/(UN-EXP(-XM))*XM/TM
         DPLAN=(PLAND-PLANM)*DTM
         ALP=DTM*DDM
         BEP=(PLAND-FD*RAD1(ID))*DTM
         GAM=(FAK1(ID)*RAD1(ID)-FAK1(ID-1)*RAD1(ID-1)-
     *        THIRD*(PLAND-PLANM))*TWO*DTM2
         S0=(EMIS1(ID)+SCAT1(ID)*RAD1(ID))/ABSO1(ID)
         A1=ALP*(TWO*GAM-BEP)
         B1=A1-S0/ABSO1(ID)
         RA(ID)= TWO*FAK1(ID-1)*DTM2
         RB(ID)=-(UN+DTM*(FD+TWO*FAK1(ID)*DTM))+
     *           SCAT1(ID)/ABSO1(ID)
         VR(ID)= GAM-BEP+RAD1(ID)-S0
         UA(ID)= B1*DABT1(ID-1)
     *           +(DEMT1(ID-1)+
     *           DSCT1(ID-1)*RAD1(ID-1))/ABSO1(ID-1)
     *           -DPLDTM*DTM2*TWOTHR
         UB(ID)= B1*DABT1(ID)+(DEMT1(ID)+
     *           DSCT1(ID)*RAD1(ID))/ABSO1(ID)+
     *           DPLDT0*DTM*(UN+TWOTHR*DTM)
C
      if(ifryb.gt.0) then
         DTM=UN/((ABSO1(ID-1)+ABSO1(ID))*DDM)
         FR=FREQ(IJ)
         FR15=FR*1.D-15
         BNU=BN*FR15*FR15*FR15
         X0=HK*FR/T0
         XM=HK*FR/TM
         PLAND=BNU/(EXP(X0)-UN)
         PLANM=BNU/(EXP(XM)-UN)
         DPLDT0=PLAND/(UN-EXP(-X0))*X0/T0
         DPLDTM=PLANM/(UN-EXP(-XM))*XM/TM
         GAM=(FAK1(ID)*RAD1(ID)-FAK1(ID-1)*RAD1(ID-1)-
     *        THIRD*(PLAND-PLANM))*DTM
         S0=(EMIS1(ID)+SCAT1(ID)*RAD1(ID))/ABSO1(ID)
         BS=HALF/DTM
         BEP=BS*(RAD1(ID)-S0)
         A1=(GAM-BEP)*DTM*DDM
         B1=A1-BS*S0/ABSO1(ID)
         RA(ID)=FAK1(ID-1)*DTM
         RB(ID)=-FAK1(ID)*DTM-BS*(UN-SCAT1(ID)/ABSO1(ID))-FHD(IJ)
         VR(ID)=GAM+BEP-HALF*PLAND+FHD(IJ)*RAD1(ID)
         UA(ID)=A1*DABT1(ID-1)-DPLDTM*DTM*THIRD
         UB(ID)=B1*DABT1(ID)+
     *          BS*(DEMT1(ID)+DSCT1(ID)*RAD1(ID))/ABSO1(ID)+
     *          (HALF+THIRD*DTM)*DPLDT0
!        write(63,"(i7,1p8e14.6)") ij,fr,pland,
!    *   gam,bep,fhd(ij),rad1(id),fhd(ij)*rad1(id)-half*pland,vr(id)
       end if
C
       ELSE
C
C     for disks -
C     lower b.c. expresses just I(taumax,-mu,nu)=I(taumax,+mu,nu)
C
         DZM=ABSO1(ID)+ABSO1(ID-1)
         FRD=FAK1(ID)*RAD1(ID)-FAK1(ID-1)*RAD1(ID-1)
         DTAUM=DZM*DDM
         GAM1=FRD/DTAUM
         A1=GAM1/DZM
         AS=0.
         BS=DTAUM*HALF
         S0=(EMIS1(ID)+SCAT1(ID)*RAD1(ID))/ABSO1(ID)
         GAM2=BS*(RAD1(ID)-S0)
         X1=GAM2/DZM
         A1=A1-X1
         A2=0. !?????????????????????????????
         B2=BS/ABSO1(ID)
         B1=A1-B2*S0
         RA(ID)=FAK1(ID-1)/DTAUM-AS*(UN-SCAT1(ID-1)/ABSO1(ID-1))
         RB(ID)=-FAK1(ID)/DTAUM-BS*(UN-SCAT1(ID)/ABSO1(ID))
         UA(ID)=A1*DABT1(ID-1)+A2*(DEMT1(ID-1)+DSCT1(ID-1)*RAD1(ID-1))
         UB(ID)=B1*DABT1(ID)+B2*(DEMT1(ID)+DSCT1(ID)*RAD1(ID))
         VR(ID)=GAM1+GAM2
      END IF
C
C
C   =====================================================
C   components corresponding to the radiative equilibrium
C   =====================================================
C
      DO ID=1,ND
C
C *********     integral equation part
C
         IF(REINT(ID).GT.0.) THEN
            HEAT     = ABSO1(ID)-SCAT1(ID)
            DHEAT    = (DABT1(ID)-DSCT1(ID))*RAD1(ID)
            WDR      = W(IJ)*dens(id)*reint(id)
            VB(ID)   = HEAT*WDR
            WM(ID,ID)= WM(ID,ID)+(DHEAT-DEMT1(ID))*WDR
            WR(ID)   = WR(ID)-(HEAT*RAD1(ID)-EMIS1(ID))*WDR
         END IF
      END DO
C
C *********     differential equation part
C
      ID=1
      IF(REDIF(ID).GT.0.) THEN
         WF=W(IJ)*FH(IJ)*REDIF(ID)
         VB(ID)=VB(ID)+WF
         WR(ID)=WR(ID)-WF*RAD1(ID)
      END IF
c
c     original variant with 1st-order mid-point differences
c
      icentr=0
      if(icentr.eq.0) then
         nd1=nd
         if(ilbc.ne.0) nd1=nd-1
         DO ID=2,nd1
            IF(REDIF(ID).GT.0.) THEN
            DDM=(DM(ID)-DM(ID-1))*HALF
            OMEG0=ABSO1(ID)
            OMEGM=ABSO1(ID-1)
            DTAUM=(OMEG0+OMEGM)*DDM
            FRD=FAK1(ID)*RAD1(ID)-FAK1(ID-1)*RAD1(ID-1)
            GAMR=FRD/DTAUM*redif(id)
            A1=GAMR/(OMEG0+OMEGM)
            VA(ID)     =-W(IJ)*FAK1(ID-1)/DTAUM*redif(id)
            VB(ID)     = VB(ID)+W(IJ)*FAK1(ID)/DTAUM*redif(id)
            WM(ID,ID-1)= WM(ID,ID-1)-A1*W(IJ)*DABT1(ID-1)
            WM(ID,ID)  = WM(ID,ID)-A1*W(IJ)*DABT1(ID)
            WR(ID)     = WR(ID)-W(IJ)*GAMR
            END IF
         END DO
c
         if(ilbc.gt.0) then
            id=nd
            IF(REDIF(ID).GT.0.) THEN
               DDM=(DM(ID)-DM(ID-1))*HALF
               DTAUM=(ABSO1(ID)+ABSO1(ID-1))*DDM*3.0
               FR=FREQ(IJ)
               FR15=FR*1.D-15
               BNU=BN*FR15*FR15*FR15
               X0=HK*FR/TEMP(ID)
               XM=HK*FR/TEMP(ID-1)
               PLAND=BNU/(EXP(X0)-UN)
               PLANM=BNU/(EXP(XM)-UN)
               DPLDT0=PLAND/(UN-EXP(-X0))*X0/TEMP(ID)
               DPLDTM=PLANM/(UN-EXP(-XM))*XM/TEMP(ID-1)
               FLX=(PLAND-PLANM)/DTAUM*redif(id)
               A1=FLX/(ABSO1(ID)+ABSO1(ID-1))
               WM(ID,ID-1)= WM(ID,ID-1)+W(IJ)*(DPLDTM-A1*DABT1(ID-1))
               WM(ID,ID)  = WM(ID,ID)+W(IJ)*(DPLDT0-A1*DABT1(ID))
               WR(ID)     = WR(ID)-W(IJ)*FLX

            END IF
         end if
c
c     centered difference variant
c
       else
         do id=2,nd-1
            if(redif(id).gt.0) then
               wwr=w(ij)*redif(id)
               ddm=half*(dm(id)-dm(id-1))
               ddp=half*(dm(id+1)-dm(id))
               dtm=(abso1(id-1)+abso1(id))*ddm
               dtp=(abso1(id+1)+abso1(id))*ddp
               dt0=dtm+dtp
               frm=fak1(id)*rad1(id)-fak1(id-1)*rad1(id-1)
               frp=fak1(id+1)*rad1(id+1)-fak1(id)*rad1(id)
               alp=dtp/dtm/dt0
               gam=dtm/dtp/dt0
               flx=alp*frm+gam*frp
c
c              matrix elements
c
               va(id)=-wwr*fak1(id-1)*alp
               vb(id)=vb(id)+wwr*fak1(id)*(alp-gam)
               vc(id)=wwr*fak1(id+1)*gam
c
               dmtm=ddm/(dtm*dtm)
               dmtp=ddp/(dtp*dtp)
               rm=dtm/dt0
               rp=dtp/dt0
               wm(id,id-1) = wm(id,id-1)+wwr*dabt1(id-1)*dmtm*
     *                 (rm*rm*frp-(un+rm)*frm)
               wm(id,id)   = wm(id,id)+wwr*dabt1(id)*
     *                 ((dmtp*rp*rp-dmtm*rp*(un+rm))*frm +
     *                  (dmtm*rm*rm-dmtp*rm*(un+rp)*frp))
               wr(id)=wr(id)-wwr*flx
            end if
         end do
c
         id=nd
         IF(REDIF(ID).GT.0.) THEN
            DDM=(DM(ID)-DM(ID-1))*HALF
            DTAUM=(ABSO1(ID)+ABSO1(ID-1))*DDM
            FRD=FAK1(ID)*RAD1(ID)-FAK1(ID-1)*RAD1(ID-1)
            FLX=FRD/DTAUM*redif(id)
            A1=FLX/(ABSO1(ID)+ABSO1(ID-1))
            VA(ID)     =-W(IJ)*FAK1(ID-1)/DTAUM*redif(id)
            VB(ID)     = VB(ID)+W(IJ)*FAK1(ID)/DTAUM*redif(id)
            WM(ID,ID-1)= WM(ID,ID-1)-A1*W(IJ)*DABT1(ID-1)
            WM(ID,ID)  = WM(ID,ID)-A1*W(IJ)*DABT1(ID)
            WR(ID)     = WR(ID)-W(IJ)*FLX

         END IF
      end if
c
      if(nretc.gt.0) then
         do id=1,nretc
            wr(id)=0.
            vb(id)=0.
            va(id)=0.
            wm(id,id)=1.
            if(id.gt.1) wm(id,id-1)=0.
         end do
      end if
      RETURN
      END SUBROUTINE RYBMAT
C
C
C     ****************************************************************
C
C
      SUBROUTINE RYBHEQ
C     =================
C
      use accura
      use basics
      use modelq
      use rybpar

      implicit none

      real(dp) ::  pradfc(mdepth),ptb(mdepth)
      REAL(DP) :: DMM,DMP,DM0,QQ,DELPG,GGR,T,AN,RHO,CPRAD,HR1,HG1,X,
     *            ANE,ENRG,ENTT,WM0,GRA,GRV,ERFCX,ALGR
      INTEGER  :: ID,IJ,NTEMP

c
      DO ID=1,ND
         GRD(ID)=0.
         pra(id)=0.
         pradt(id)=0.
         pradfc(id)=0.
         ptb(id)=0.5*dens(id)*vturb(id)**2
      END DO
      PRD0=0.
c
      if(ifprad.gt.0) then
         CALL OPAINI(1)
         DO IJ=1,NFREQ
            CALL OPACF1(IJ)
            CALL RTEFR1(IJ)
            if(.not.lskip(1,ij))
     *      GRD(1)=GRD(1)+W(IJ)*((FH(IJ)*RAD1(1)-HEXTRD(IJ))*ABSO1(1)
     *                   -EMIS1(1)*Q0(IJ))
            DO ID=2,ND
               if(.not.lskip(id,ij)) then
               GRD(ID)=GRD(ID)+(RAD1(ID)*FAK1(ID)-
     *                 RAD1(ID-1)*FAK1(ID-1))*W(IJ)
               pra(id)=pra(id)+RAD1(ID)*FAK1(ID)*W(IJ)
               end if
            END DO
            pra(1)=pra(1)+RAD1(1)*FAK1(1)*W(IJ)
c           pra(1)=pra(1)+RAD1(1)*FAK1(1)*W(IJ)-ABSO1(1)*W(IJ)*
c    *             (RAD1(1)*FH(IJ)-HEXTRD(IJ))
         END DO
         if(idisk.eq.0) then
            GRD(1)=PCK*GRD(1)/DENS(1)
          else
            grd(1)=pck*grd(2)
         end if
         PRD0=PRD0*DENS(1)*DM(1)*PCK
c
         do id=2,nd
            grd(id)=grd(id)*pck/(dm(id)-dm(id-1))
         end do
         do id=1,nd
            pra(id)=pra(id)*pck
            pradt(id)=pra(id)
            pradfc(id)=pra(id)/(2.5213e-15*temp(id)**4)
            fprad(id)=min(grav/grd(id)*(un-pgsgra),un)
         end do
C
         do id=2,nd-1
            dmm=un/(dm(id)-dm(id-1))
            dmp=un/(dm(id+1)-dm(id))
            dm0=two/(dm(id+1)-dm(id-1))
            qq=((pra(id+1)-pra(id))*dmp-(pra(id)-pra(id-1))*dmm)*dm0
            prad2d(id)=qq
         end do
         prad2d(1)=prad2d(2)
         prad2d(nd)=0.
      end if
c
      if(idisk.eq.0) then
         pgs0(1)=dm(1)*(grav-fprad(1)*grd(1))-ptb(1)
c        write(6,631) grav,grd(1),dm(1)*(grav-grd(1)),fprad(1),pgs0(1)
c 631    format('***** RYBHEQ ID=1 grav,grd,pgs-ex,pgs',1p5e12.4)
         DO ID=2,ND
            delpg=(DM(ID)-DM(ID-1))*(grav-fprad(id)*grd(id))
     *           -(ptb(id)-ptb(id-1))
            PGS0(ID)=PGS0(ID-1)+DELPG
         END DO
       else
         pgs0(1)=pgs(1)
         do id=2,nd
            grv=(dm(id)-dm(id-1))*qgrav*(zd(id)+zd(id-1))*half
            pgs0(id)=pgs0(id-1)-pck*grd(id)+grv
         end do
      end if
      iprybh=1
      if(iprybh.gt.0) write(6,"(/' RYBHEQ in iter',i4/
     *'   id      dm          dens        pgs0          pra',
     *'          pradfc      grad        log grad'/)") iter
c
      if(iprybh.gt.0) then
         do id=1,nd
            if(id.eq.1) then
               ggr=qgrav*zd(id)
             else
               ggr=qgrav*(zd(id)+zd(id-1))*half
            end if
            if(idisk.eq.0) then
               algr=log10(grd(id))
               write(6,"(i4,1p9e13.4)") 
     *         id,dm(id),dens(id),pgs0(id),pra(id),
     *         pradfc(id),grd(id),algr
             else
               write(6,"(i4,1p9e13.4)") 
     *         id,dm(id),dens(id),pgs0(id),pra(id),
     *         pradfc(id),grd(id),gra,ggr,zd(id)
            end if
         end do
      end if
C
      if(idisk.eq.0.and.iopfrc.eq.0) then
         DO ID=1,ND
            T=TEMP(ID)
            pgs(id)=pgs0(id)
            AN=PGS(ID)/BOLK/T
c     write(6,"('rybheq before eldens',i3,f10.1,1pe12.4)") id,t,an
            CALL ELDENS(ID,T,AN,ANE,ENRG,ENTT,WM0,1)
c     write(6,"('rybheq after',i3,f10.1,1p3e12.4)") id,t,an,ane,wm0
            RHO=WMM(ID)*(AN-ANE)
            DENS(ID)=RHO
            ELEC(ID)=ANE
            CALL WNSTOR(ID)
c     write(6,"('rybheq bef steqeq',i3,f10.1,1pe12.4)") id,t,elec(id)
      write(76,"('rybheq bef steqeq',i3,f10.1)") id,t
            CALL STEQEQ(ID,POP,1)
c     write(6,"('rybheq aft steqeq',i3,f10.1,1pe12.4)") id,t,elec(id)
c            IF(.NOT.LCHC.and.iter.lt.ielcor) CALL ELCOR(ID)
         END DO
       else
c
c        --------------------------
c        the rest is only for disks
c        --------------------------
c
         cprad=2.5213e-15
         do id=1,nd
            csnd(id)=pgs0(id)/dens(id)/temp(id)
c           pi(id)=cprad*pradfc(id)
         end do
c
         hr1=grd(1)/qgrav
         hg1=sqrt(two*csnd(1)*temp(1)/qgrav)
         x=(zd(1)-hr1)/hg1
         IF(X.LT.3.) THEN
            IF(X.LT.0.) X=0.
            F1HE=8.86226925D-1*EXP(X*X)*ERFCX(X)
          ELSE
            F1HE=HALF*(UN-HALF/X/X)/X
         END IF
c
         ntemp=2
         call pgset(ntemp)
c
         do id=1,nd
            pgs(id)=pgs0(id)
            ptotal(id)=pgs0(id)+pra(id)
        end do
c
      END IF
C
      RETURN
      END SUBROUTINE RYBHEQ
C
C
C     ****************************************************************
C
C
      SUBROUTINE RYBENE
C     =================
C
C     complementing partial matrices of complete linearization
c     corresponding to the contribution of ALI frequencies and the
c     convection to the radiative/convective equilibrium equation in
c     the Rybicki formalism
c
      use accura
      use alipar
CC    use array1
      use basics
      use modelq
      use rybpar
      use conveq

      implicit none

      REAL(DP) :: FLXTO0,THT,T,P,TM,PM,PG,PGM,PR0,T0,P0,
     *            PG0,AB0,DLT,DDT0,DDTM,DBB,DHCDD,BB,DHCDTP,
     *            CORD,C1,C2,T1,DHCDT0,DGRAD,DHCDT,DHCDTM,TP,PTP,
     *            DDTP0,DHCDDP,DHCDTU,DELM,RDELM,DDTPM,DELHC,
     *            FLXCNV,VCON,DLP,FLXC1
      INTEGER  :: ID,ICENTR

C
C     contribution from the radiative equilibrium part of the energy eq.
c
      write(67,*) 'redif'
      write(67,"(30f3.0)") (redif(id),id=1,nd)
      write(67,*) 'reint'
      write(67,"(30f3.0)") (reint(id),id=1,nd)
      write(67,"('IDCONZ',5i4)") idconz,icbeg,icbegp,icend,icendp

      flxto0=sig4p*teff**4
      DO ID=1,ND
         WR(ID)=WR(ID)+FCOOL(ID)
         IF(IDISK.EQ.1) WR(ID)=WR(ID)-reint(id)*TVISC(ID)
         if(reint(id).gt.0.) then
            IF(ID.GT.1) WM(ID,ID-1)
     *                 =WM(ID,ID-1)+AREIT(ID)*dens(id)*reint(id)
!!      if(id.ge.66)
!!   *  write(6,"('rybene - int',i4,1p4e12.4)") 
!!   *     id,reit(id),dens(id),reint(id),wm(id,id)
            WM(ID,ID)  =WM(ID,ID)  + REIT(ID)*dens(id)*reint(id)
            IF(IDISK.EQ.1) WM(ID,ID)=WM(ID,ID)+
     *                     DTVIST(ID)*reint(id)
            IF(ID.LT.ND) WM(ID,ID+1)
     *                  =WM(ID,ID+1)+CREIT(ID)*dens(id)*reint(id)
         end if
c
         if(idisk.eq.0) then
            flxtot=flxto0
            gravd=grav
          else
            tht=(thetav(id)+thetav(id-1))*half
c           flxtot=flxto0*(1.d0-thetav(id))
            flxtot=flxto0*(1.d0-tht)
            gravd=(zd(id)+zd(id-1))*half*qgrav
         end if
         if(redif(id).gt.0) then
            WR(ID)=WR(ID)+flxtot*redif(id)
            IF(ID.GT.1) WM(ID,ID-1)=WM(ID,ID-1)+REDTM(ID)*REDIF(ID)
!!      if(id.ge.66)
!!   *  write(6,"('rybene - dif',i4,1p4e12.4)")
!!   *     id,redt(id),dens(id),redif(id),wm(id,id)
            WM(ID,ID)=  WM(ID,ID)+  REDT (ID)*REDIF(ID)
         end if
      END DO
c
C     contribution from convection
C
      IF(HMIX0.LE.0.OR.ICONV.EQ.0) RETURN
      if(dert.eq.0.) dert=0.01
      icentr=0
      DO ID=idconz,ND
         T=TEMP(ID)
         P=PTOTAL(ID)
         TM=TEMP(ID-1)
         PM=PTOTAL(ID-1)
         pg=pgs(id)
         pgm=pgs(id-1)
         pr0=0.
         T0=SQRT(T*TM)
         P0=SQRT(P*PM)
         pg0=sqrt(pg*pgm)
         AB0=SQRT(ABROSD(ID)*ABROSD(ID-1))
         pr0=sqrt(pradt(id)*pradt(id-1))
         if(idisk.eq.0) then
            flxtot=flxto0
            gravd=grav
          else
            tht=(thetav(id)+thetav(id-1))*half
            flxtot=flxto0*(1.d0-tht)
            gravd=(zd(id)+zd(id-1))*half*qgrav
         end if
         DLP=UN/LOG(P/PM)
         DLT=LOG(T/TM)*DLP
         DELTA(ID)=DLT
         DDT0= DLP/T
         DDTM=-DLP/TM
         CALL CONVEC(ID,T0,P0,pg0,pr0,AB0,DLT,FLXCNV,VCON)
c        CALL CONVEP(ID,T0,P0,pg0,pr0,AB0,DLT,FLXCNV,VCON)
         FLXC(ID)=FLXCNV
         if(flxcnv.le.0.) cycle
         GRDAD0=GRDADB
         DBB=1.5*BCNV
         DHCDD=0.
         C1=0.
         C2=0.
         IF(DELMDE.GT.0.) THEN
            bb=bcnv*half
            cord=bb/sqrt(bb*bb+(dlt-grdadb))
            c1=1.-cord
            c2=c1-bb*bb/cord
            DHCDD=1.5D0/DELMDE*FLXCNV*c1
         END IF
CC       if(id.lt.icbegp-2) then
CC       if(id.lt.icbeg-2) then
CC          flxc(id)=0.
CC          cycle
CC       end if
         T1=(un+dert)*T0
c        CALL CONVEC(ID,T1,P0,pg0,pr0,AB0,DLT,FLXC1,VCON)
         CALL CONVDE(ID,T1,P0,pg0,pr0,AB0,DLT,GRDAD0,FLXC1,VCON)
         DHCDT0=(FLXC1-FLXCNV)*HALF/dert
         DGRAD =(GRDADB-GRDAD0)*HALF/DERT
         DHCDT =DHCDT0/T+DHCDD*DDT0-C1*DGRAD*HALF/DERT/T-C2*DBB/T
         DHCDTM=DHCDT0/TM+DHCDD*DDTM-C1*DGRAD*HALF/DERT/TM-C2*DBB/TM
C
C        additional terms in matrix WM
C
C    **  1. differential equation form
C
         if(redif(id).gt.0) then
            WM(ID,ID-1)=WM(ID,ID-1)+DHCDTM*redif(id)
            WM(ID,ID)=  WM(ID,ID)+DHCDT*redif(id)
            WR(ID)=WR(ID)-FLXC(ID)*redif(id)
            if(icentr.ne.0.and.id.lt.nd) then
               WM(ID,ID+1)=WM(ID,ID+1)+DHCDTP*redif(id)
            end if
             if(id.ge.30) write(67,632) id,iter,wr(id)+flxc(id),
C    *                    flxc(id),flxc1,dhcdt0,grdadb,grdad0,
c    *                    delmde,dbb,bb,cord,dhcdd,
c    *                    wr(id),wm(id,id-1),wm(id,id),wm(id,id+1)
     *                    flxc(id),dlt,p,grdadb,delmde,abrosd(id),
     *                    wr(id),wm(id,id-1),wm(id,id),wm(id,id+1)
           
  632 format('diff-tot',2i4,1p2e11.3,2x,5e11.3,2x,4e11.3)
         END IF
C
C    **  2. integral equation form
C
         if(reint(id).gt.0.) then
         if(id.lt.nd) then
            TP=TEMP(ID+1)
            PTP=PTOTAL(ID+1)
            T0=SQRT(T*TP)
            P0=SQRT(P*PTP)
            pg0=sqrt(pgs(id)*pgs(id+1))
            pr0=sqrt(pradt(id)*pradt(id+1))
            AB0=SQRT(ABROSD(ID)*ABROSD(ID+1))
            DLP=UN/LOG(PTP/P)
            DLT=LOG(TP/T)*DLP
            DDTP0= DLP/TP
            DDTPM=-DLP/T
            if(idisk.ne.0) then
               gravd=(zd(id)+zd(id+1))*half*qgrav
               flxtot=flxto0*(1.-(thetav(id)+thetav(id+1))*half)
            end if
            CALL CONVEC(ID,T0,P0,pg0,pr0,AB0,DLT,FLXCNV,VCON)
            GRDAD0=GRDADB
            DBB=1.5*BCNV
            DHCDDP=0.
            IF(DELMDE.GT.0.) THEN
               BB=BCNV*HALF
               cord=bb/sqrt(bb*bb+(dlt-grdadb))
               c1=1.-cord
               c2=c1-bb*bb/cord
               DHCDDp=1.5D0/DELMDE*FLXCNV*c1
            if(id.eq.67) write(68,"(2i4,1p4e11.3,2x,4e11.3,2x,6e11.3)")
     *      id,iter,delmde,bb,dlt,grdadb,cord,flxcnv,c1,dhcddp,
     &      bb*bb,dlt-grdadb,bb*bb+dlt-grdadb
            END IF
            T1=(un+dert)*T0
c           CALL CONVEC(ID,T1,P0,pg0,pr0,AB0,DLT,FLXC1,VCON)
            CALL CONVDE(ID,T1,P0,pg0,pr0,AB0,DLT,GRDAD0,FLXC1,VCON)
            DHCDT0=(FLXC1-FLXCNV)*HALF/DERT
            DGRAD =(GRDADB-GRDAD0)*HALF/DERT
            DHCDTP=DHCDT0/TP+DHCDDP*DDTP0-C1*DGRAD*0.5/DERT/TP-C2*DBB/TP
            DHCDTU=DHCDT0/T+DHCDDP*DDTPM-C1*DGRAD*HALF/DERT/T-C2*DBB/T

            if(id.eq.67) write(68,"(2i4,1p4e11.3,2x,4e11.3,2x,6e11.3)")
     *      id,iter,dhcdt0,dhcddp,ddtp0,dgrad,tp,t,dert,dbb,
     *      flxc1,flxcnv,delmde,bb,dlt,grdadb
C
C           additional terms in matrices A and B (the row corresponding to
C           energy balance, i.e. T) due to convection
C
            DELM=(DM(ID+1)-DM(ID-1))*HALF
            RDELM=DENS(ID)/DELM*reint(id)
            IF(ICONV.NE.0) THEN
               WM(ID,ID-1)=WM(ID,ID-1)-RDELM*DHCDTM
               WM(ID,ID)=WM(ID,ID)+RDELM*(DHCDTU-DHCDT)
               WM(ID,ID+1)=WM(ID,ID+1)+RDELM*DHCDTP
            END IF
            WR(ID)=WR(ID)-RDELM*(FLXCNV-FLXC(ID))
            gravd=(zd(id)+zd(id-1))*half*qgrav
       if(id.ge.30) write(68,633) id,iter,dlt,flxcnv,flxc(id),rdelm,
     *              dhcdtm,dhcdtu,dhcdt,dhcdtp,
     *              wr(id),wm(id,id-1),wm(id,id),wm(id,id+1)
  633  format(2i4,1p4e11.3,2x,4e11.3,2x,4e11.3)
          ELSE
            if(idisk.eq.0) then
            TP=TEMP(ID-2)
            PTP=PTOTAL(ID-2)
            T0=SQRT(T*TP)
            P0=SQRT(P*PTP)
            pr0=sqrt(pradt(id)*pradt(id-1))*pck
            AB0=SQRT(ABROSD(ID)*ABROSD(ID-2))
            DLP=UN/LOG(PTP/P)
            DLT=LOG(TP/T)*DLP
            DDTP0= DLP/TP
            DDTPM=-DLP/T
            gravd=(zd(id)+zd(id-2))*half*qgrav
            CALL CONVEC(ID,T0,P0,p0-pr0,pr0,AB0,DLT,FLXCNV,VCON)
            if(flxcnv.le.0.) cycle
               DHCDDP=0.
               IF(DELMDE.GT.0.) DHCDDP=1.5D0/DELMDE*FLXCNV
               T1=1.001D0*T0
               CALL CONVEC(ID,T1,P0,p0-pr0,pr0,AB0,DLT,FLXC1,VCON)
               DHCDTP=(FLXC1-FLXCNV)*1.D3/T0*HALF+DHCDDP*DDTP0
C
C           additional terms in matrices A and B (the row corresponding to
C           energy balance, i.e. T) due to convection
C
               DELM=(DM(ID)-DM(ID-2))*HALF
               RDELM=DENS(ID)/DELM*reint(id)
               DELHC=WMM(ID)/DELM*(FLXCNV-FLXC(ID))
               WM(ID,ID-1)=WM(ID,ID-1)+RDELM*(DHCDT-DHCDTP)
               WM(ID,ID)=WM(ID,ID)+RDELM*DHCDT
               WR(ID)=WR(ID)-RDELM*(FLXC(ID)-FLXCNV)
               end if
            END IF
            gravd=(zd(id)+zd(id-1))*half*qgrav
         END IF
      END DO
c
      RETURN
      END SUBROUTINE RYBENE
C
C
C     ****************************************************************
C
C
      SUBROUTINE RYBSOL
C     =================
C
C     driver of the complete-linearization solution in the Rybicki
C     formalism
C
      use accura
      use alipar
CC    use array1
      use atomic
      use basics
      use iterat
      use modelq
      use rybpar

      implicit none

      REAL(DP) :: AL(MDEPTH),AU(MDEPTH),VAL(MDEPTH),UCOL(MDEPTH),
     *            VAU(MDEPTH,MDEPTH),CHANGT(MDEPTH),prae(mdepth)
      REAL(DP) :: pop1(mlevel),babs(mlevel,mdepth)
c
      REAL(DP) :: FR,W0
      INTEGER  :: ID,ID1,IJ,IDC,I,IFLEV0

      write(*,*)
      write(*,*) '=========  LINEARIZATION, ITER =',iter
      write(*,*)
      write(6,"('reint',35f2.0/5x,35f2.0)") (reint(id),id=1,nd)
      write(6,"('redif',35f2.0/5x,35f2.0)") (redif(id),id=1,nd)
C
C     zeroing needed quantities
C
      DO ID=1,ND
         REIT(ID)=0.
         REIN(ID)=0.
         AREIT(ID)=0.
         AREIN(ID)=0.
         CREIT(ID)=0.
         CREIN(ID)=0.
         REDT(ID)=0.
         REDTM(ID)=0.
         REDTP(ID)=0.
         REDN(ID)=0.
         REDNM(ID)=0.
         REDNP(ID)=0.
         FCOOLI(ID)=0.
         FLFIX(ID)=0.
         FLRD(ID)=0.
         ABROSD(ID)=0.
         SUMDPL(ID)=0.
         PRAE(ID)=PRADT(ID)
      END DO
C
C     zero vectors and matrices of the Rybicki formalism
C
      DO ID=1,ND
         RA(ID)=0.
         RB(ID)=0.
         RC(ID)=0.
         UA(ID)=0.
         UB(ID)=0.
         UC(ID)=0.
         VA(ID)=0.
         VB(ID)=0.
         VC(ID)=0.
         VR(ID)=0.
         WR(ID)=0.
         AL(ID)=0.
         AU(ID)=0.
         VAL(ID)=0.
         DO ID1=1,ND
            WM(ID1,ID)=0.
            VAU(ID1,ID)=0.
         END DO
      END DO
C
      if(ioptab.lt.-1) call setdrt
c
!      write(*,*) 'before ij loop'
      DO IJ=1,NFREQ
         FR=FREQ(IJ)
         W0=W0E(IJ)
c        IF(IOPTAB.GE.0) THEN
            CALL OPACTR(IJ)
c         ELSE
c           CALL OPACFD(IJ)
c        END IF
!       if(ij.ge.1) write(*,*) 'before rtefr1',ij
         CALL RTEFR1(IJ)
!       if(ij.ge.1) write(*,*) 'before alifr1',ij
         CALL ALIFR1(IJ)
!       if(ij.ge.1) write(*,*) 'before rosstd',ij
         CALL ROSSTD(IJ)
C
!       if(ij.ge.1) write(*,*) 'before rybmat',ij
         CALL RYBMAT(IJ)
        if(ij.eq.-42) then
           write(*,*) 'before tridag - ra,rb,rc,vr - ij',ij
           write(6,"(1p15e10.2)") ra
           write(*,*) 'rb - ij',ij
           write(6,"(1p15e10.2)") rb
           write(*,*) 'rc - ij',ij
           write(6,"(1p15e10.2)") rc
           write(*,*) 'vr - ij',ij
           write(6,"(1p15e10.2)") vr
           write(*,*)
        end if
         CALL TRIDAG(RA,RB,RC,VR,AL,ND)
        if(ij.eq.-42) then
           write(*,*) 'after tridag - ua,ub,uc,wr -0 ij',ij 
           write(6,"(1p15e10.2)") ua
           write(*,*) 'ub - ij',ij
           write(6,"(1p15e10.2)") ub
           write(*,*) 'uc - ij.ij'
           write(6,"(1p15e10.2)") uc
           write(*,*) 'wr - ij',ij
           write(6,"(1p15e10.2)") wr
           write(*,*)
         end if
         ID=1
         VAL(ID)=VAL(ID)+VB(ID)*AL(ID)+VC(ID)*AL(ID+1)
         DO ID=2,ND-1
            VAL(ID)=VAL(ID)+VA(ID)*AL(ID-1)+VB(ID)*AL(ID)+
     *                      VC(ID)*AL(ID+1)
         END DO
         ID=ND
         VAL(ID)=VAL(ID)+VA(ID)*AL(ID-1)+VB(ID)*AL(ID)
        if(ij.eq.-42) then
           write(*,*) 'va,vb,al,val - ij',ij 
           write(6,"(1p15e10.2)") va
           write(*,*) 'vb - ij',ij
           write(6,"(1p15e10.2)") vb
           write(*,*) 'al - ij',ij
           write(6,"(1p15e10.2)") al
           write(*,*) 'val - ij',ij
           write(6,"(1p15e10.2)") val
           write(*,*)
        end if
C
c        if(ij.le.0) write(*,*) 'vau'
         DO IDC=1,ND
            DO ID=1,ND
               UCOL(ID)=0.
            END DO
            UCOL(IDC)=UB(IDC)
            IF(IDC.GT.1) UCOL(IDC-1)=UC(IDC-1)
            IF(IDC.LT.ND) UCOL(IDC+1)=UA(IDC+1)
            CALL TRIDAG(RA,RB,RC,UCOL,AU,ND)
!          if(ij.eq.-42) then
!             write(*,*) 'au'
!             write(6,"(1p15e10.2)") au
!          end if
!          if(ij.eq.0.and.idc.le.2) then
!             write(*,*) 'ucol - ij,idc',ij,idc
!             write(6,"(1p15e10.2)") ucol
!             write(*,*) 'au - ij,idc'
!             write(6,"(1p15e10.2)") au
!          write(*,*)
!          end if
            ID=1
            VAU(ID,IDC)=VAU(ID,IDC)+VB(ID)*AU(ID)+VC(ID)*AU(ID+1)
c          if(id.eq.42.and.idc.eq.42) 
c    *     write(6,"('vau at ij,idc,id',3i4)")  ij,idc,id
c          if(id.eq.42.and.idc.eq.42) write(6,"(1p5e10.2)")
c    *     vb(id),vc(id),au(id),au(id+1),vau(id,idc)
            DO ID=2,ND-1
               VAU(ID,IDC)=VAU(ID,IDC)+
     *         VA(ID)*AU(ID-1)+VB(ID)*AU(ID)+VC(ID)*AU(ID+1)
c          if(id.eq.42.and.idc.eq.42) 
c    *     write(6,"('vau at ij,idc,id',3i4)") ij,idc,id
c          if(id.eq.42.and.idc.eq.42) write(6,"(1p7e10.2)") 
c    *     va(id),vb(id),vc(id),au(id),au(id-1),au(id+1),vau(id,idc)
            END DO
            ID=ND
            VAU(ID,IDC)=VAU(ID,IDC)+VA(ID)*AU(ID-1)+VB(ID)*AU(ID)
c          if(ij.le.2.and.idc.eq.42) write(6,"('vau at ij,idc,id',3i4)")
c    *     ij,idc,id
c          if(ij.le.2.and.idc.eq.42) write(6,"(1p5e10.2)")
c    *     va(id),vb(id),au(id),au(id-1),vau(id,idc)
         END DO
      END DO

c     write(*,*) 'final vau',vau(1,1)
c     if(ij.eq.1) then
c        do idc=1,nd
c          write(6,"(1p15e10.2)") (vau(id,idc),id=1,nd)
c        end do
c     end if
C
      DO ID=1,ND
         ABROSD(ID)= SUMDPL(ID)/ABROSD(ID)
         FCOOL(ID)=REINT(ID)*FCOOLI(ID)*DENS(ID)-REDIF(ID)*FLFIX(ID)
c        PRADT(ID)=PRADT(ID)*PCK
         PRADT(ID)=PRAE(ID)
      END DO
      if(ioptab.lt.0) CALL ROSSTD(0)
C
C     final evaluation of matrices and the global inversion
C
!        write(*,*) 'before rybene'
      CALL RYBENE
!        write(*,*) 'after rybene'
C
      DO ID=1,ND
         DO IDC=1,ND
            WM(ID,IDC)=WM(ID,IDC)-VAU(ID,IDC)
         END DO
!!!     write(*,*) 'wm at id',id
!!!     write(6,"(1p10e12.4)") (wm(id,idc),idc=1,nd)
!!!     write(*,*) 'vau'
!!!     write(6,"(1p10e12.4)") (vau(id,idc),idc=1,nd)
         WR(ID)=WR(ID)-VAL(ID)
      END DO
!      write(*,*) 'wr'
!      write(6,"(1p10e12.4)") wr
!      write(*,*) 'val'
!      write(6,"(1p10e12.4)") val
      CALL LINEQS(WM,WR,CHANGT,ND,MDEPTH)
!        write(*,*) 'after lineqs'
!      write(*,*) 'wr'
!      write(6,"(1p10e12.4)") wr
!      write(*,*) 'changt'
!      write(6,"(1p10e12.4)") changt
!        write(*,*) 'wm'
!        write(*,"(1p15e10.2)") ,wm
!        write(*,*) 'wr',wr
!      write(*,*) 'changt',changt
C
      IF(.NOT.LTE.and.ifryb.gt.1) THEN
         lte=.true.
         iflev0=iflev
         iflev=1
         do i=1,nlevel
            imodl(i)=imodl0(i)
         end do
         call levset
         do id=1,nd
            call steqeq(id,pop1,0)
            do i=1,nlevel
               babs(i,id)=un
               if(pop1(i).gt.0.) babs(i,id)=popul(i,id)/pop1(i)
            end do
         end do
         lte=.false.
         iflev=iflev0
         do i=1,nlevel
            imodl(i)=imodl0(i)
         end do
         call levset
      end if
C
      IF(.NOT.LTE.and.ifryb.gt.2) THEN
      DO IJ=1,NFREQ
         CALL OPACTR(IJ)
         CALL RTEFR1(IJ)
         CALL ALIFR1(IJ)
          CALL ROSSTD(IJ)
         CALL RYBMAT(IJ)
         ID=1
         WR(ID)=VR(ID)-UB(ID)*CHANGT(ID)-UC(ID)*CHANGT(ID+1)
         DO ID=2,ND-1
            WR(ID)=VR(ID)-UA(ID)*CHANGT(ID-1)-UB(ID)*CHANGT(ID)-
     *             UC(ID)*CHANGT(ID+1)
         END DO
         ID=ND
         WR(ID)=VR(ID)-UA(ID)*CHANGT(ID-1)-UB(ID)*CHANGT(ID)
         CALL TRIDAG(RA,RB,RC,WR,AL,ND)
         RAD(IJ,ID)=RAD1(ID)+AL(ID)
      END DO
      END IF
C
c      write(*,*) 'before rybchn'
      CALL RYBCHN(CHANGT)
c      write(*,*) 'after rybchn'
c
      if(.not.lte.and.ifryb.gt.1) then
         lte=.true.
         iflev0=iflev
         iflev=1
         do i=1,nlevel
            imodl(i)=imodl0(i)
         end do
         call levset
         do id=1,nd
            call steqeq(id,pop1,0)
            do i=1,nlevel
               popul(i,id)=pop1(i)*babs(i,id)
            end do
         end do
         lte=.false.
         iflev=iflev0
         do i=1,nlevel
            imodl(i)=imodl0(i)
         end do
         call levset
      end if
c
         write(*,*) 'end rybsol'
      RETURN
      END SUBROUTINE RYBSOL
C
C
C     ****************************************************************
C
C
      SUBROUTINE RYBCHN(CHANGT)
C     =========================
C
C     handling relative changes in the Rybicki formalism
c 
      USE ACCURA
      use alipar
CC    use array1, only: psi0
      use basics
      use iterat
      use modelq
      use rybpar

      implicit none 

      REAL(DP) :: CHMX,CHN,DPLP,DPLM,ANOLD1,CHT,CHAN,T,PGSOR,GFAC,AN,
     &            ANE,RHO,PGPRE,DTOD,GRV,Z1,DDP,HR1,HG1,X,ENRG,ENTT,WM0,
     &            ERFCX
      INTEGER  :: JJR,ID,ITPG,NRE

      REAL(DP) :: CHANGT(MDEPTH),TMPOLD(MDEPTH)
C
      CHMX=0.
      CHN=0.
      JJR=0
      DPLP=DPSILT-UN
      DPLM=UN/DPSILT-UN
      NRE=NFREQE+1
      IF(ITER.EQ.1) WRITE(9,"(' RELATIVE CHANGES OF VECTOR PSI'/
     &   '  ITER  ID    TEMP        NE       POP     RAD      MAXIMUM',
     &   '   ilev   ifr'/)")
!     IF(ITER.EQ.1) WRITE(6,"(' RELATIVE CHANGES OF VECTOR PSI'/
!    &   '  ITER  ID    TEMP        NE       POP     RAD      MAXIMUM',
!    &   '   ilev   ifr'/)")
      ID=1
      ANOLD1=DENS(ID)/WMM(ID)+ELEC(ID)
      DO ID=ND,1,-1
         CHT=CHANGT(ID)/TEMP(ID)
         CHAN=CHT
c     write(*,*) 'rybchn0',id,nre,changt(id),temp(id)
         IF(CHAN.LE.DPLM) CHAN=DPLM
         IF(CHAN.GT.DPLP) CHAN=DPLP
         TMPOLD(ID)=TEMP(ID)
         TEMP(ID)=TEMP(ID)*(CHAN+UN)
!     write(*,*) 'rybchn',id,nre,temp(id),tmpold(id)
CC       PSI0(NRE)=TEMP(ID)
CC       PSY0(NRE,ID)=PSI0(NRE)
         PSY0(NRE,ID)=TEMP(ID)
         WRITE(9,"(2I5,1P5E10.2,2I5)") 
     *   ITER,ID,CHT,chn,chN,CHN,chT,jjr,jjr
!        WRITE(6,"(2I5,1P5E10.2,2I5)") 
!    *   ITER,ID,CHT,chn,chN,CHN,chT,jjr,jjr
         IF(ABS(CHT).GT.CHMX) CHMX=ABS(CHT)
      END DO
c
      if(ioptab.le.-2) then
         IF(ITER.NE.1 .AND. ABS(CHMX).GT.1.e16) THEN
            WRITE(6,"(' **** STOP in RYBSOL after ITER',I4,/,
     * ' Max change:',1PE12.2)") ITER,CHMX
            WRITE(10,"(' **** STOP in RYBSOL after ITER',I4,/,
     * ' Max change:',1PE12.2)") ITER,CHMX
            STOP
         END IF
         LFIN=ABS(CHMX).LE.CHMAX.OR.ITER.GE.NITER
         RETURN
      END IF
C
      if(nretc.lt.0) then
         do id=-nretc,1,-1
            temp(id)=temp(id+1)
            PSY0(NRE,ID)=PSY0(NRE,ID+1)
         end do
      end if
c
      if(idisk.eq.0) then
         if(ifprad.gt.0) then
            DO ID=1,ND
               T=TEMP(ID)
               pgsor=pgs(id)
               dtod=temp(id)/tmpold(id)-un
               if(dtod.gt.0.2) dtod=0.2
               if(dtod.lt.-0.2) dtod=-0.2
               gfac=un
               if(irgrad.eq.1.and.taurs(id).gt.0.5) gfac=un+4.*dtod
               if(irgrad.eq.2) gfac=un+4.*dtod
               if(id.eq.1) then
                  pgs(id)=dm(id)*(grav-grd(id)*gfac*fprad(id))
                else
                  pgs(id)=pgs(id-1)+(dm(id)-dm(id-1))*(grav-
     *                    grd(id)*gfac*fprad(id))
               end if
               if(pgs(id).le.0.) pgs(id)=pgsor
               AN=PGS(ID)/BOLK/T
               CALL ELDENS(ID,T,AN,ANE,ENRG,ENTT,WM0,1)
               RHO=WMM(ID)*(AN-ANE)
               DENS(ID)=RHO
               ELEC(ID)=ANE
            END DO
          else
            DO ID=1,ND
               T=TEMP(ID)
               PGS(ID)=DM(ID)*GRAV
               AN=PGS(ID)/BOLK/T
               CALL ELDENS(ID,T,AN,ANE,ENRG,ENTT,WM0,1)
               RHO=WMM(ID)*(AN-ANE)
               DENS(ID)=RHO
               ELEC(ID)=ANE
            END DO
         end if
       else
          pgpre=pgs(1)
          id=1
          do id=2,nd
            pgpre=pgs(id)
            dtod=temp(id)/tmpold(id)-un
            if(dtod.gt.0.2) dtod=0.2
            if(dtod.lt.-0.2) dtod=-0.2
            gfac=un+4.*dtod
            grv=(dm(id)-dm(id-1))*qgrav*(zd(id)+zd(id-1))*half
            pgs(id)=pgs(id-1)-pck*grd(id)*gfac+grv
            pgs0(id)=pgs(id)
         end do
         pgs0(1)=pgs(1)
c
         itpg=0
         iterpg: do
            z1=zd(1)
            itpg=itpg+1
            call pgset(1)
c
            DO ID=1,ND
               T=TEMP(ID)
               AN=ANTP(ID)
               CALL ELDENS(ID,T,AN,ANE,ENRG,ENTT,WM0,1)
               RHO=WMM(ID)*(AN-ANE)
               DENS(ID)=RHO
               ELEC(ID)=ANE
               PGS(ID)=BOLK*T*AN
               pgs0(id)=pgs(id)
            END DO
c
c        recomputing the z-distance
c
            do id=nd-1,1,-1
               ddp=(dm(id+1)-dm(id))*half
               zd(id)=zd(id+1)+ddp/dens(id+1)+ddp/dens(id)
            end do
c
            if(abs((zd(1)-z1)/z1).lt.1.e-3.or.itpg.gt.5) exit iterpg
c
            do id=1,nd
               csnd(id)=pgs(id)/dens(id)/temp(id)
            end do

            hr1=grd(1)/qgrav
            hg1=sqrt(two*csnd(1)*temp(1)/qgrav)
            x=(zd(1)-hr1)/hg1
            IF(X.LT.3.) THEN
               IF(X.LT.0.) X=0.
               F1HE=8.86226925D-1*EXP(X*X)*ERFCX(X)
             ELSE
               F1HE=HALF*(UN-HALF/X/X)/X
            END IF
            if(abs((zd(1)-z1)/z1).lt.1.e-4.or.itpg.gt.5) exit iterpg
         end do iterpg
      end if
C
C     STOP if changes become too large
C
      IF(ITER.NE.1 .AND. ABS(CHMX).GT.1.e16) THEN
         WRITE(6,"(' **** STOP in RYBSOL after ITER',I4,/,
     * ' Max change:',1PE12.2)") ITER,CHMX
         WRITE(10,"(' **** STOP in RYBSOL after ITER',I4,/,
     * ' Max change:',1PE12.2)") ITER,CHMX
         STOP
      END IF
C
C     Finally, set up quantity LFIN that indicates whether or not
C     this iteration of complete linearization is the last one
C
      LFIN=ABS(CHMX).LE.CHMAX.OR.ITER.GE.NITER
c
      write(*,*) '===== end of RYBCHN in ITER',iter
      if(hmix0.ge.0.) call conout(1,1)

      RETURN
      END SUBROUTINE RYBCHN
C
C
C     ****************************************************************
C
C

      SUBROUTINE TRIDAG(A,B,C,R,U,N)
C     ==============================
C
C     solution of the tridiagonal system
c
c     from Numerical recipes, Sect 2.4
c
      use accura
      implicit none

      REAL(DP), INTENT(IN) :: A(N),B(N),C(N),R(N)
      REAL(DP),INTENT(OUT) :: U(N)
      REAL(DP)             :: GAM(N)
      REAL(DP)             :: BET
      INTEGER, INTENT(IN)  :: N
      INTEGER              :: J 
C
      BET=B(1)
      U(1)=R(1)/BET
      DO J=2,N
         GAM(J)=C(J-1)/BET
         BET=B(J)-A(J)*GAM(J)
         U(J)=(R(J)-A(J)*U(J-1))/BET
      END DO
      DO J=N-1,1,-1
         U(J)=U(J)-GAM(J+1)*U(J+1)
      END DO
      RETURN
      END SUBROUTINE TRIDAG
C
C
C     ****************************************************************
C
C

      SUBROUTINE OPACTR(IJ)
C     =====================
C
C     Absorption and emission coefficients and their derivatives
C     for the use by Rybicki variant (RYBSOL)
C
C     This procedure is very similar to OPACT1, the only difference is
C     the evaluation of derivatives
C
C     Input:
C      IJ    - depth index
C     Output:
C      ABSO1 - array of absorption coefficient
C      EMIS1 - array of emission coefficient
C      SCAT1 - array of scattering coefficient
C      Dxxy  - array of derivatives of xx (=AB for absorption, =EM for
C              emission, =SC for scattering) coefficient wrt T
C
      use accura
      use alipar
      use atomic
      use basics
      use modelq
      use rybpar

      implicit none

      INTEGER, INTENT(IN) :: IJ
      REAL(DP), PARAMETER :: DELT=1.e-2
      REAL(DP) :: T,PGSOR,GFAC,AN,ANE,RHO,PLAN,DPLAN,ENRG,ENTT,WM0
      INTEGER  :: ID,IOPLY0,IJP,I
      LOGICAL  :: LTE0

      REAL(DP) :: ELEC0(MDEPTH),DENS0(MDEPTH),AN0(MDEPTH),
     *            ELERAT(MDEPTH),POPLTE(MLEVEL)
c
C     compute opacities at T+DELTA(T) - for derivatives
C
      IF(IJ.EQ.1) THEN
C
C        first, save absolute b-factors (for evaluating
C        derivatives w.r.t. T)
C
         IF(.NOT.LTE) THEN
            LTE0=LTE
               DO ID=1,ND
               CALL WNSTOR(ID)
               CALL SABOLF(ID)
               CALL RATMAL(ID,NLEVEL)
               CALL LEVSOL(POPLTE,IIFOR,NLEVEL,0)
               ELERAT(ID)=ELEC(ID)/(DENS(ID)/WMM(ID)+ELEC(ID))
               DO I=1,NLEVEL
                  POPUL0(I,ID)=POPUL(I,ID)
                  BFABS(I,ID)=1.
                  IF(POPLTE(I).GT.0.) BFABS(I,ID)=POPUL(I,ID)/POPLTE(I)
               END DO
            END DO
            LTE=LTE0
         END IF
C
C        opacities at T+DELTA(T) - for derivatives
C        for that, one needs also to estimate ELEC and DENS for T+DELTA(T)
C
         DO ID=1,ND
            TEMP(ID)=TEMP(ID)*(UN+DELT)
            ELEC0(ID)=ELEC(ID)
            DENS0(ID)=DENS(ID)
            an0(id)=dens(id)/wmm(id)+elec(id)
         END DO
         CALL TDPINI
         DO ID=1,ND
            T=TEMP(ID)
            pgsor=pgs(id)
            if(ifprad.gt.0) then
               if(idisk.eq.0) then
                  gfac=un
                  if(taurs(id).gt.0.5.and.irgrad.eq.1) gfac=un+4.*delt
                  if(irgrad.eq.2) gfac=un+4.*delt
                  if(id.gt.1) then
                     pgs(id)=pgs(id-1)+(dm(id)-dm(id-1))*(grav
     *                      -fprad(id)*grd(id)*gfac)
                  end if
               end if
            end if
         end do

         do id=1,nd
            t=temp(id)
            an=pgs(id)/bolk/t
            if(idisk.gt.0) an=antp(id)
c           IF(LTE) THEN
               CALL ELDENS(ID,T,AN,ANE,ENRG,ENTT,WM0,1)
c            ELSE
c              ANE=AN*ELERAT(ID)
c           END IF
            RHO=WMM(ID)*(AN-ANE)
            DENS(ID)=RHO
            ELEC(ID)=ANE
            CALL WNSTOR(ID)
c
            IF(LTE.OR.IFMOL.GT.0) THEN
c       write(*,*) 'opactr bef steqeq',id
               CALL STEQEQ(ID,POP,1)
c       write(*,*) 'opactr aft steqeq',id
             ELSE
               CALL SABOLF(ID)
               CALL RATMAL(ID,NLEVEL)
               CALL LEVSOL(POPLTE,IIFOR,NLEVEL,0)
               DO I=1,NLEVEL
                  POPUL(I,ID)=POPLTE(I)*BFABS(I,ID)
               END DO
            END IF
         END DO

         CALL OPAINI(1)

         IOPLY0=IOPLYM
         IOPLYM=0
         DO IJP=1,NFREQ
            CALL OPACF1(IJP)
            DO ID=1,ND
               ABSOPP(IJP,ID)=ABSO1(ID)/DENS(ID)
               EMISPP(IJP,ID)=EMIS1(ID)/DENS(ID)
               SCATPP(IJP,ID)=SCAT1(ID)/DENS(ID)
            END DO
         END DO
         IOPLYM=IOPLY0
C
C        reset the original structural parameters
C
         DO ID=1,ND
            TEMP(ID)=TEMP(ID)/(UN+DELT)
         END DO
         CALL TDPINI
c
         IF(IDISK.EQ.0) THEN
            DO ID=1,ND
               ELEC(ID)=ELEC0(ID)
               DENS(ID)=DENS0(ID)
               T=TEMP(ID)
               AN=DENS0(ID)/WMM(ID)+ELEC0(ID)
               PGS(ID)=AN*BOLK*T
            END DO
          ELSE
            call pgset(1)
            DO ID=1,ND
               T=TEMP(ID)
               IF(HMIX0.LE.0.) THEN
                  AN=ANTP(ID)
                  CALL ELDENS(ID,T,AN,ANE,ENRG,ENTT,WM0,1)
                  RHO=WMM(ID)*(AN-ANE)
                  DENS(ID)=RHO
                  ELEC(ID)=ANE
                  PGS(ID)=AN*BOLK*T
                ELSE
                  dens(id)=dens0(id)
                  elec(id)=elec0(id)
               END IF
            END DO
         END IF
c
         DO ID=1,ND
            CALL WNSTOR(ID)
            CALL STEQEQ(ID,POP,1)
c           DO I=1,NLEVEL
c              POPUL(I,ID)=POPUL0(I,ID)
c           END DO
         END DO
         CALL OPAINI(1)

      END IF
C
C     opacity at the original T, and derivatives
C
      CALL OPACF1(IJ)
      DO ID=1,ND
         T=TEMP(ID)
         ABSO1(ID)=ABSO1(ID)/DENS(ID)
         SCAT1(ID)=SCAT1(ID)/DENS(ID)
         EMIS1(ID)=EMIS1(ID)/DENS(ID)
         DABT1(ID)=(ABSOPP(IJ,ID)-ABSO1(ID))/T/DELT
         DSCT1(ID)=(SCATPP(IJ,ID)-SCAT1(ID))/T/DELT
         XKF(ID)=EXP(-HKT1(ID)*FREQ(IJ))
         XKF1(ID)=UN-XKF(ID)
         XKFB(ID)=XKF(ID)*BNUE(IJ)
         IF(LTE.OR.IFMOL.GT.0) THEN
            PLAN=XKFB(ID)/XKF1(ID)
            DPLAN=PLAN/XKF1(ID)*HKT1(ID)*FREQ(IJ)/TEMP(ID)
            DEMT1(ID)=(DABT1(ID)-DSCT1(ID))*PLAN+
     *                (ABSO1(ID)-SCAT1(ID))*DPLAN
          ELSE
            DEMT1(ID)=(EMISPP(IJ,ID)-EMIS1(ID))/T/DELT
         END IF
c        if(ij.le.2) write(6,"('deriv',2i4,1p5e12.4)") ij,id,
c    *    abso1(id),absopp(ij,id),t,delt,dabt1(id)
      END DO
!     if(ij.eq.42) then
!        write(*,*) 'abso1'
!        write(*,"(1p15e10.2)") abso1
!        write(*,*) 'absopp'
!        write(*,"(1p15e10.2)") (absopp(ij,id),id=1,nd)
!        write(*,*) 'emis1'
!        write(*,"(1p15e10.2)") emis1
!        write(*,*) 'scat1'
!        write(*,"(1p15e10.2)") scat1
!        write(*,*) 'dabt1'
!        write(*,"(1p15e10.2)") dabt1
!        write(*,*) 'demt1'
!        write(*,"(1p15e10.2)") demt1
!        write(*,*) 'dsct1'
!        write(*,"(1p15e10.2)") dsct1
!     end if
C
      RETURN
      END SUBROUTINE OPACTR
C
C
C     ****************************************************************
C
C

      subroutine pgset(ntemp)
c     =======================
C
      use accura
      use basics
      use iterat
      use modelq
      use rybpar

      implicit none

      integer, intent(in) :: ntemp
      integer  :: id,item,itp
      real(dp) :: dmm,dmp,dm0,alp,gam,bet,qq,pdmax,pd,ant0

      real(dp) :: a(mdepth),b(mdepth),c(mdepth),v(mdepth),
     *            p(mdepth),pnew(mdepth),delp(mdepth),
     *            temp0(mdepth),pg0(mdepth)
C
      do id=1,nd
         p(id)=pgs0(id)
         temp0(id)=temp(id)
      end do
c
      item=0
      temper: do
         item=item+1
c
         itp=0
         itera: do
            itp=itp+1
c
            id=1
            b(id)=un
            v(id)=dm(1)*sqrt(csnd(id)*temp(id)*qgrav*half)/f1he-p(id)
            do id=2,nd-1
               dmm=un/(dm(id)-dm(id-1))
               dmp=un/(dm(id+1)-dm(id))
               dm0=two/(dm(id+1)-dm(id-1))
               alp=dmm*dm0
               gam=dmp*dm0
               bet=alp+gam
               QQ=PRAD2D(ID)
               a(id)=p(id)*alp
               c(id)=p(id)*gam
               b(id)=p(id-1)*alp+p(id+1)*gam-two*p(id)*bet+qq
               v(id)=-p(id-1)*p(id)*alp-p(id+1)*p(id)*gam+p(id)**2*bet-
     *                p(id)*qq-csnd(id)*temp(id)*qgrav
            end do
c
            id=nd
            alp=two/(dm(id)-dm(id-1))**2
            a(id)=alp*p(id)
            b(id)=alp*(p(id-1)-two*p(id))
            v(id)=alp*p(id)*(p(id)-p(id-1))-csnd(id)*temp(id)*qgrav
c
            call tridag(a,b,c,v,delp,nd)
c
            pdmax=0.
            do id=1,nd
               pnew(id)=p(id)+delp(id)
               pd=(pnew(id)-p(id))/p(id)
               pnew(id)=max(pnew(id),0.5*p(id))
               pdmax=max(pdmax,abs(pd))
               p(id)=pnew(id)
            end do
            if(itp.lt.30.and.pdmax.gt.1.e-4) then
               cycle itera
             else
               exit itera
            end if
         end do itera
c
         if(item.lt.ntemp) then
            do id=1,nd
               temp0(id)=temp(id)
               pg0(id)=p(id)
               temp(id)=temp(id)*1.01
            end do
            cycle temper
          else
            exit temper
         end if
      end do temper
c
      do id=1,nd
         antp(id)=p(id)/bolk/temp(id)
         ant0=pg0(id)/bolk/temp0(id)
         temp(id)=temp0(id)
      end do
      if(ntemp.eq.1) then
         do id=1,nd
            pgs0(id)=p(id)
         end do
      end if
c
      return
      end subroutine pgset
C
C
C     ****************************************************************
C
C

!     include 'modules.f'
!     program odh
!     call odfmer
!     end program odh
C
C
C *********************************************************************
C
c
      SUBROUTINE ODFHYS(DOPO)
C     =======================
C
C     Initialization of line ODF's for hydrogen
C
      use accura
      use atomic
      use basics
      use modelq
      use hydodf

      implicit none

CC    REAL(DP), ALLOCATABLE :: FFRO(:)

      REAL(DP), PARAMETER  :: CCM=UN/2.997925e10,THIRD=UN/3.,
     *                        FRH=3.28805e15
      REAL(DP), INTENT(IN) :: DOPO
      REAL(DP) :: FRION,FRA,DOPI,FRB,TIDO,XJ2A
      INTEGER  :: IZZH,ITR,JND,MODE,I,J,IS,K,NFRO,IFQ,IFRQ0,IFRQ1,IJ00
      INTEGER  :: IK,IJQ,IJ,NFRB

!      write(*,*) 'mfro',mfro,nlmx,ntrans
      ALLOCATE (FROS(MFRO,MHOD),WNUS(MFRO,MHOD))
      ALLOCATE (FFRO(MFRO))
C
      izzh=1
      IF(ISPODF.GE.1) THEN
         DO ITR=1,NTRANS
c         write(*,*) 'itr0',itr
            JND=JNDODF(ITR)
c         write(*,*) 'jnd',jnd
            MODE=IABS(INDEXP(ITR))
            IF(JND.LE.0 .OR. MODE.NE.2) CYCLE
            LINEXP(ITR)=.FALSE.
            LCOMP(ITR)=.FALSE.
            INTMOD(ITR)=6
c        write(*,*) 'intmod',intmod(itr)
            I=ILOW(ITR)
            J=IUP(ITR)
            NQLODF(I)=IABS(IPROF(ITR))
            IF(NQLODF(I).EQ.0) NQLODF(I)=NQUANT(J)
            OSC0(ITR)=0.
            IS=NQUANT(I)
!          write(*,*) 'itr',itr,i,j,nqlodf(j)
            DO K=NQUANT(J),NLMX
               CALL STARK0(IS,K,izzh,XKIJ(JND,K),WL0(JND,K),
     *                    FIJ(JND,K))
               OSC0(ITR)=OSC0(ITR)+FIJ(JND,K)
            END DO
c        write(6,"('odfhys',4i6,f10.3)") itr,i,j,nqlodf(i),osc0(itr)
         END DO
         RETURN
      END IF
C
      NLASTE=NFREQ
      write(*,*) 'nfreq before odfhys',nfreq
      ITLOOP: DO ITR=1,NTRANS
         JND=JNDODF(ITR)
!        write(*,*) 'itrn',itr,jnd
         MODE=IABS(INDEXP(ITR))
!        write(*,*) 'itr',itr,ilow(itr),iup(itr),jndodf(itr)
         IF(JND.LE.0 .OR. MODE.NE.2) CYCLE ITLOOP
         LCOMP(ITR)=.FALSE.
         INTMOD(ITR)=6
         I=ILOW(ITR)
         J=IUP(ITR)
         NQLODF(I)=IABS(IPROF(ITR))
         IF(NQLODF(I).EQ.0) NQLODF(I)=NQUANT(J)
         XJ2A=HALF*(XI2(NQUANT(J))+XI2(NQUANT(J)-1))
C
C        set up explicit frequencies & weights
C
         NFRO=0
         DO IFQ=1,4
            NFRO=NFRO+KDO(IFQ,JND)
         END DO
         NFRO=NFRO-2
         FRION=FRH*IZ(IEL(I))*IZ(IEL(I))
         FRA=FRION*(XI2(NQUANT(I))-XJ2A)
         DOPI=DOPO*FRA*CCM
         FRB=0.99999999*FRION*XI2(NQUANT(I))
         IFRQ0=IFR0(ITR)
         IFRQ1=IFR1(ITR)
!        write(*,*) '   ',itr,ifr0(itr),ifr1(itr),frion
         IFR0(ITR)=NLASTE+1
         IFR1(ITR)=NLASTE+NFRO
         I1ODF(I)=IFR0(ITR)
         I2ODF(I)=IFR1(ITR)-1
         FFRO(1)=0.99999999*FRA
         FFRO(2)=FRA
         IJ00=1
         DO IK=1,3
            DO IJ=2,KDO(IK,JND)
               IJQ=IJ00+IJ
               FFRO(IJQ)=FFRO(IJQ-1)+XDO(IK,JND)*DOPI
            END DO
            IJ00=IJ00+KDO(IK,JND)-1
         END DO
         do ij=1,ij00
            if(ffro(ij).lt.frb) nfrb=ij
         end do
         if(nfrb.eq.ij00) then
            IJ00=IJ00+1
            FFRO(NFRO)=0.99999999*FRION*XI2(NQUANT(I))
            do while (ffro(ij00).ge.ffro(nfro))
               xdo(3,jnd)=0.75*xdo(3,jnd)
               ij00=ij00-kdo(3,jnd)
               do ij=2,kdo(3,jnd)
                  ijq=ij00+ij
                  ffro(ijq)=ffro(ijq-1)+xdo(3,jnd)*dopi
               end do
              ij00=ij00+kdo(3,jnd)
            enddo
            TIDO=(FFRO(NFRO)-FFRO(IJ00))/FLOAT(KDO(4,JND)-1)
            DO IJ=1,KDO(4,JND)-2
               IJQ=NFRO-IJ
               FFRO(IJQ)=FFRO(NFRO)-FLOAT(IJ)*TIDO
            END DO
          else
            TIDO=(FRB-FFRO(nfrb))*third
            ffro(nfrb+1)=FFRO(nfrb)+tido
            ffro(nfrb+2)=frb-tido
            ffro(nfrb+3)=frb
            nfro=nfrb+3
            IFR1(ITR)=NLASTE+NFRO
            I2ODF(I)=IFR1(ITR)-1
         endif
         DO IJ=1,NFRO
            FREQ(NLASTE+IJ)=FFRO(NFRO-IJ+1)
         END DO
         W(NLASTE+NFRO)=HALF*(FREQ(NLASTE+NFRO-1)-FREQ(NLASTE+NFRO))
         W(NLASTE+NFRO-1)=W(NLASTE+NFRO)
         DO IJ=2,NFRO-2,2
            TIDO=(FREQ(NLASTE+IJ)-FREQ(NLASTE+IJ+1))*THIRD
            W(NLASTE+IJ-1)=W(NLASTE+IJ-1)+TIDO
            W(NLASTE+IJ)=W(NLASTE+IJ)+4.*TIDO
            W(NLASTE+IJ+1)=W(NLASTE+IJ+1)+TIDO
         END DO
         NLASTE=IFR1(ITR)
!         write(*,*) 'nlaste in odfhys',nlaste,ij
         write(*,*) '******* nlaste,ij,nfro in odfhys',nlaste,ij,nfro
C
C        set up internal frequencies & Stark parameters
C
         CALL ODFFR(I,J)
         OSC0(ITR)=0.
         write(*,*) 'i,j',i,j
         IS=NQUANT(I)
         DO K=NQUANT(J),NLMX
            CALL STARK0(IS,K,izzh,XKIJ(JND,K),WL0(JND,K),FIJ(JND,K))
            OSC0(ITR)=OSC0(ITR)+FIJ(JND,K)
         END DO
         IF(INDEXP(ITR).NE.0) THEN
            CALL IJALIS(ITR,IFRQ0,IFRQ1)
         END IF
      END DO ITLOOP
C
      NFREQ=NLASTE
      MFREQ=NFREQ
      MFREQP=MFREQ
c
      write(*,*) 'MFREQ in odfhys',mfreq
CC    DEALLOCATE (FFRO)
      RETURN
      END SUBROUTINE ODFHYS
C
C
C *********************************************************************
C
C

      SUBROUTINE ODFMER
C     =================
C
C     Opacity distribution function for superlines to merged states
C     (calculated only if DT/T>=CHTL, kept constant after).
C
      use accura
      use atomic
      use basics
      use modelq, only: chant
      implicit none

      integer :: itr,id

      DO ITR=1,NTRANS
         IF(.NOT.LINE(ITR).OR.IABS(INDEXP(ITR)).NE.2) CYCLE
         DO ID=1,ND
            IF(INIT.EQ.1 .OR. ABS(CHANT(ID)).GE.1.e-3)
     *         CALL ODFHYD(ID,ITR)
         END DO
      END DO
      RETURN
      END SUBROUTINE ODFMER
C
C
C *********************************************************************
C
c

      SUBROUTINE ODFHYD(ID,ITR)
C     =========================
C
C     Line ODF's for hydrogen line series
C
      use accura
      use atomic
      use basics
      use modelq
      use hydodf

      implicit none

CC    REAL(DP),ALLOCATABLE :: SIG(:),SGT(:),ODF(:),YNUS(:),ALAM(:)
CC    INTEGER,ALLOCATABLE  :: IODF(:)

      REAL(DP), PARAMETER :: CDOP=TWO*BOLK/HMASS
      REAL(DP), PARAMETER :: CA=2.997925e18,CCM=CA/1.e8,FRH=3.28805e15
      REAL(DP), PARAMETER :: RYDEL=911.764,TTW=2./3.
      REAL(DP), PARAMETER :: C00=1.25e-9,CID=0.02654

      INTEGER, INTENT(IN) :: ID,ITR
      REAL(DP) :: ANES,F00,FRA,DOPO,WL,FXK,FID,WPROB,PRFLN
      INTEGER  :: JO,NF,IJ,IJQ,II,JJ,J,JI,I0,I1,IW1,IW2

CC    ALLOCATE (SIG(MFRO),SGT(MFRO),ODF(MFRO))
CC    ALLOCATE (IODF(MFRO))
CC    ALLOCATE (YNUS(MFRO),ALAM(MFRO))
      REAL(DP) :: SIG(MFRO),SGT(MFRO),ODF(MFRO)
      INTEGER  :: IODF(MFRO)
      REAL(DP) :: YNUS(MFRO),ALAM(MFRO)
C
      JO=JNDODF(ITR)
c      write(*,*) 'odfhyd jo,ispodf,mfro',itr,jo,ispodf,mfro
      IF(ISPODF.EQ.0) THEN
         NF=NFRODF(JO)
         DO IJ=1,NF
            IODF(IJ)=0
            SIG(IJ)=0.
            ODF(IJ)=0.
            YNUS(IJ)=FROS(IJ,JO)
            ALAM(IJ)=CAS/YNUS(IJ)
         END DO
       ELSE
         NF=IFR1(ITR)-IFR0(ITR)+1
c        write(*,*) 'nf',itr,ifr0(itr),ifr1(itr),nf
         DO IJ=1,NF
            SIG(IJ)=0.
            YNUS(IJ)=FREQ(IFR0(ITR)+IJ-1)
            ALAM(IJ)=CAS/YNUS(IJ)
c         write(*,*) 'ynus,alam',ij,ynus(ij),alam(ij)
         END DO
      END IF
C
      II=ILOW(ITR)
      JJ=IUP(ITR)
      ANES=EXP(TTW*LOG(ELEC(ID)))
      F00=C00*ANES
      FRA=FRH*(XI2(NQUANT(II))-XI2(NQUANT(JJ)))
      DOPO=FRA/CCM*SQRT(CDOP*TEMP(ID)+VTB*VTB)
c      write(*,*) 'DOP0',F00,II,JJ,fra,nqlodf(ii),nlmx
      DO J=NQLODF(II),NLMX
c       write(*,*) 'j',j
         WL=RYDEL/(XI2(NQUANT(II))-XI2(J))
c       write(*,*) 'rydel',rydel
         FXK=F00*XKIJ(JO,J)
         DBETA=WL*WL/CA/FXK
         BETAD=DBETA*DOPO
         FID=CID*FIJ(JO,J)*DBETA
c         write(*,*) 'bef divstr'
         CALL DIVSTR(1)
c         Write(*,*) 'aftr divstr'
         WPROB=WNHINT(J,ID)
c          write(*,*) 'bef odfhst',ii,j,fid,wprob
         CALL ODFHST(NF,FXK,FID,WPROB,WL,ALAM,SGT)
c          write(*,*) 'aft ofhst',sgt(1)
         DO IJ=1,NF
            SIG(IJ)=SIG(IJ)+SGT(IJ)
         END DO
      END DO
C
      IF(ISPODF.EQ.0) THEN
         CALL INDEXX(NF,SIG,IODF)
         DO IJ=1,NF
            ODF(IJ)=SIG(IODF(IJ))
         END DO
         I0=IFR0(ITR)
         I1=IFR1(ITR)
         IF(IABS(INDEXP(ITR)).EQ.2) YNUS(1)=FREQ(I0)
         IW1=IODF(1)
         DO IJ=2,NF
            IW2=IODF(IJ)
            IF(IJ.GT.2 .AND. IJ.LT.NF) THEN
               YNUS(IJ)=YNUS(IJ-1)-HALF*(WNUS(IW1,JO)+WNUS(IW2,JO))
             ELSE IF (IJ.EQ.2) THEN
               YNUS(IJ)=YNUS(IJ-1)-HALF*(TWO*WNUS(IW1,JO)+WNUS(IW2,JO))
             ELSE IF (IJ.EQ.NF) THEN
               YNUS(IJ)=YNUS(IJ-1)-HALF*(WNUS(IW1,JO)+TWO*WNUS(IW2,JO))
            END IF
            IW1=IW2
         END DO
      END IF
C
      IF(ISPODF.EQ.0) THEN
         PRFLIN(ID,I1)=1.E-35
         DO IJQ=I0,I1-1
            INL: DO IJ=2,NF
               JI=IJ
               IF(YNUS(IJ).LE.FREQ(IJQ)) EXIT INL
            END DO INL
            PRFLN=ODF(JI-1)+(ODF(JI)-ODF(JI-1))*
     *        (FREQ(IJQ)-YNUS(JI-1))/(YNUS(JI)-YNUS(JI-1))
            PRFLIN(ID,IJQ)=real(PRFLN)
         END DO
       ELSE
         DO IJ=1,NF
            PRFLIN(ID,KFR0(ITR)+IJ-1)=real(SIG(IJ))
         END DO
      END IF
CC    DEALLOCATE (SIG,SGT,ODF,YNUS,ALAM,IODF)
      RETURN
      END SUBROUTINE ODFHYD
C
C
C *********************************************************************
C
c
      SUBROUTINE ODFHST(N,FXK,FID,WP,WL,ALAM,SG)
C     ==========================================
C
C     Auxiliary routine for ODF1 (replaces multiple calls to STARKA)
C
      use accura
      use basics
      use modelq
      use odfpar

      implicit none

      REAL(DP), PARAMETER   :: F0=-0.5758228,F1=0.4796232,F2=0.07209481
      REAL(DP), PARAMETER   :: AL=1.26,SD=0.5641895,SLO=-2.5,THRA=1.5
      REAL(DP), PARAMETER   :: BL1=1.14,BL2=11.4,SAC=0.08, THR=THRA*TWO

      INTEGER, INTENT(IN)   :: N
      REAL(DP), INTENT(IN)  :: FXK,FID,WP,WL
      REAL(DP), INTENT(IN)  :: ALAM(N)
      REAL(DP), INTENT(OUT) :: SG(N)

      REAL(DP) :: BETAD1,FXK1,FIDWP,BETA,XD,ST,XL,FL
      INTEGER  :: IJ

      BETAD1=UN/BETAD
      FXK1=UN/FXK
      FIDWP=FID*WP
C
C     for a > 1 Doppler core + asymptotic Holtzmark wing with division
C               point DIV
C
      IF(ADH.GT.AL) THEN
         DO IJ=1,N
            BETA=ABS(ALAM(IJ)-WL)*FXK1
            XD=BETA*BETAD1
            IF(XD.LE.DIVH) THEN
               ST=SD*EXP(-XD*XD)*BETAD1
             ELSE
               ST=THR*EXP(SLO*LOG(BETA))
            END IF
            SG(IJ)=ST*FIDWP
         END DO
       ELSE
C
C      empirical formula for a < 1
C
         DO IJ=1,N
            BETA=ABS(ALAM(IJ)-WL)*FXK1
            XD=BETA*BETAD1
            IF(BETA.LE.BL1) THEN
               ST=SAC
             ELSE IF(BETA.LT.BL2) THEN
               XL=LOG(BETA)
               FL=(F0*XL+F1)*XL
               ST=F2*EXP(FL)
             ELSE
               ST=THR*EXP(SLO*LOG(BETA))
            END IF
            SG(IJ)=ST*FIDWP
         END DO
      END IF
C
      RETURN
      END SUBROUTINE ODFHST
C
C
C *********************************************************************
C
c

      SUBROUTINE ODFFR(IL,IU)
C     =======================
C
C     Internal frequencies set for opacity distribution function
C     for overlapping lines near the series limit
C
C     The lines converge to the edge of the (continuum) transition IL - IU,
C     IL - index of the lower level
C     IU - index of the upper level (usually the ground state of the next ion)
C          or a mean level in the line ODF formalism
C
      use accura
      use atomic
      use basics
      use modelq
      use hydodf

      implicit none

      INTEGER, INTENT(IN) :: IL,IU

      REAL(DP), PARAMETER :: FRH=3.28805e15,CDOP=2.84511e-7,CDOM=14.
      REAL(DP), PARAMETER :: SIX=6.,SEPT=7.
CC    REAL(DP)            ::  FFRO(MFRO)

      REAL(DP) :: CH,FRION,FRE,XL2,XU1,XU2,FRC,DOPO,DOPM,FR1,FR2,DF,DDF
      INTEGER  :: NF,NQ1,KT,KL,I,II,NI,J

C
      CH=IZ(IEL(IL))*IZ(IEL(IL))
      FRION=CH*FRH
      FRE=ENION(IL)/H
      NF=1
      NQ1=NQUANT(IU)
      XL2=UN/(NQUANT(IL)*NQUANT(IL))
      XU1=UN/((NQUANT(IU)-1)*(NQUANT(IU)-1))
      XU2=UN/(NQUANT(IU)*NQUANT(IU))
      FRC=FRION*(XL2-XU2)
      FFRO(NF)=HALF*(FRC+FRION*(XL2-XU1))
      KT=ITRA(IL,IU)
      KL=JNDODF(KT)
      DOPO=CDOP*SQRT(TEFF)*FRC
      DOPM=CDOM*DOPO
      FR1=FFRO(1)
c      write(*,*) 'odffr',il,iu,kl,kt
C
      LOOPI: DO I=NQ1,NLMX
         II=I*I
         FR2=FRE-FRION/II
         DF=FR2-FR1
         IF(DF.GT.DOPM) THEN
            DO J=1,7
               NF=NF+1
               FFRO(NF)=FR1+J*DOPO
c            write(*,*) 'ffro1',j,nf,ffro(nf)
            END DO
            DF=FR2-SEPT*DOPO-FFRO(NF)
            NI=int(DF/SIX/DOPO)
            DDF=DF/(NI+1)
            DO J=1,NI
               NF=NF+1
               FFRO(NF)=FR1+SEPT*DOPO+J*DDF
c            write(*,*) 'ffro2',j,nf,ffro(nf)
            END DO
            DO J=7,0,-1
               NF=NF+1
               FFRO(NF)=FR2-J*DOPO
c            write(*,*) 'ffro3',j,nf,ffro(nf)
            END DO
            FR1=FR2
          ELSE
            NI=int(DF/DOPO)
            DDF=DF/(NI+1)
            DO J=1,NI
               NF=NF+1
               if(nf.gt.mfro-3) then
                  nf=nf-1
                  EXIT LOOPI
               end if
               FFRO(NF)=FR1+J*DDF
            END DO
            NF=NF+1
c            write(*,*) 'ffro4a',nf
            FFRO(NF)=FR2
            FR1=FR2
         END IF
      END DO LOOPI

c      write(*,*) 'end loopi',nf
      NF=NF+1
c      write(*,*) 'nf',nf
      FFRO(NF)=FRE*0.999999999
c      write(*,*) 'ffro',ffro(nf),fre
      NFRODF(KL)=NF
c      write(*,*) 'nfrodf',kl,nfrodf(kl)
      if(nf.gt.mfro)
     *   CALL QUIT('too many points for hydrogen ODF - nf.gt.mfro',
     *             nf,mfro)
c      write(*,*) 'kl',kl
      DO I=1,NF
c       write(*,*) 'i,kl',i,kl,nf-i+1
         FROS(I,KL)=FFRO(NF-I+1)
c       write(*,*) fros(i,kl),ffro(nf-i+1)
      END DO
c      write(*,*) 'fros,i,kl',i,kl
C
C   Associated weights
C
      WNUS(1,KL)=HALF*(FROS(1,KL)-FROS(2,KL))
      WNUS(NF,KL)=HALF*(FROS(NF-1,KL)-FROS(NF,KL))
      DO I=2,NF-1
         WNUS(I,KL)=HALF*(FROS(I-1,KL)-FROS(I+1,KL))
      END DO
c      write(*,*) 'wnuss,i,kl',i,kl
C
      RETURN
      END SUBROUTINE ODFFR
!     include 'modules.f'
!     program hydini
!     call lemini
!     end program hydini


