      SUBROUTINE LEMINI
C     =================
C
C     Initializes necessary arrays for evaluating hydrogen line profiles
C     from the Lemke tables
C
      use accura
      use basics
      use modelq
      use hyglin

      implicit none

      REAL(DP) :: ALMIN,ANEMIN,TMIN,DLA,DLE,DLT,QLT,XCLOG,XKLOG
      INTEGER  :: I,J,ITAB,NTAB,NLLY,ILI,ILINE,ILINEB,IWL,ILNE,IT
      INTEGER  :: NE,NT,NWL,INE

      ALLOCATE (PRFHYD(MLINH,MHWL,MHT,MHE),WLHYD(MLINH,MHWL))
      ALLOCATE (WLH(MHWL,MLINH),XTLEM(MHT,MLINH),XNELEM(MHE,MLINH))
      ALLOCATE (XK0(MLINH))

      ALLOCATE (NWLHYD(MLINH),NWLH(MLINH),NTH(MLINH),NEH(MLINH))

      DO I=1,4
         DO J=1,22
            ILINH(I,J)=0
         END DO
      END DO
      if(ihydpr.eq.21) then
         open(unit=ihydpr,file='./data/lemke.dat',status='old')
         write(6,"(' -----------'/
     *       ' reading Lemke tables; ihydpr =',i3,/
     *       ' -----------')") ihydpr
       else if(ihydpr.eq.22) then
         open(unit=ihydpr,file='./data/tremblay.dat',status='old')
         write(6,"(' -----------'/
     *       ' reading Tremblay tables; ihydpr =',i3,/
     *       ' -----------')") ihydpr
      end if
C
C ---------------------------------
C     read Lemke or Tremblay tables
C ---------------------------------
C
      ILINE=0
      READ(IHYDPR,*) NTAB
      DO ITAB=1,NTAB
         ILINEB=ILINE
         READ(IHYDPR,*) NLLY
         DO ILI=1,NLLY
            ILINE=ILINE+1
            READ(IHYDPR,*) I,J,ALMIN,ANEMIN,TMIN,DLA,DLE,DLT,
     *                     NWL,NE,NT
!           write(6,"(' ntab,nlly,iline,i,j ',5i4)") ntab,nlly,iline,i,j
            write(6,"(' itab,iline,i,j,nwl,ne,nt ',7i4)") 
     *           itab,iline,i,j,nwl,ne,nt
            ILINH(I,J)=ILINE
            NWLH(ILINE)=NWL
            NWLHYD(ILINE)=NWL
            NTH(ILINE)=NT
            NEH(ILINE)=NE
            DO IWL=1,NWL
               WLH(IWL,ILINE)=ALMIN+(IWL-1)*DLA
               WLHYD(ILINE,IWL)=WLH(IWL,ILINE)
               WLH(IWL,ILINE)=EXP(2.3025851*WLH(IWL,ILINE))
            END DO
            DO INE=1,NE
               XNELEM(INE,ILINE)=ANEMIN+(INE-1)*DLE
            END DO
            DO IT=1,NT
               XTLEM(IT,ILINE)=TMIN+(IT-1)*DLT
            END DO
         END DO
c
         DO ILI=1,NLLY
            ILNE=ILINEB+ILI
            NWL=NWLH(ILNE)
            READ(IHYDPR,"(1X)")
            DO INE=1,NEH(ILNE)
               DO IT=1,NTH(ILNE)
                  READ(IHYDPR,*) QLT,
     *            (PRFHYD(ILNE,IWL,IT,INE),IWL=1,NWL)
               END DO
            END DO
C
C        coefficient for the asymptotic profile is determined from
C        the input data
C
            XCLOG=PRFHYD(ILNE,NWL,1,1)+2.5*WLHYD(ILNE,NWL)-0.477121
            XKLOG=0.6666667*XCLOG
            XK0(ILNE)=EXP(XKLOG*2.3025851)
         END DO
      END DO
      CLOSE(IHYDPR)
C
      RETURN
      END SUBROUTINE LEMINI
C
C
C     ****************************************************************
C
C

      SUBROUTINE XENINI
C     =================
C
C     Initializes necessary arrays for evaluating hydrogen line profiles
C     from the XENOMORPH tables
C
      use accura
      use basics
      use modelq
      use hyglin

      implicit none

      REAL(DP) :: ALMIN,ANEMIN,TMIN,DLA,DLE,DLT,QLT
      INTEGER  :: I,J,IHXENR,ILINE,ILINEB,ITAB,NTAB,NWL,NE,NT,IWL,INE,IT
      INTEGER  :: ILI,ILNE,NLXEN

      IF(IHXENB.LE.0) RETURN

      ALLOCATE (PRFXB(MLINH,MHWL,MHT,MHE))
      ALLOCATE (PRFXR(MLINH,MHWL,MHT,MHE))
      ALLOCATE (ALXEN(MLINH,MHWL),XK0(MLINH))
      ALLOCATE (XTXEN(MHT,MLINH),XNEXEN(MHE,MLINH))
CC    ALLOCATE (NWLHYD(MLINH),NTH(MLINH),NEH(MLINH))
C
      IF(IHXENB.LE.0) RETURN
      DO I=1,4
         DO J=1,22
            ILXEN(I,J)=0
         END DO
      END DO
      if(ihxenb.gt.0) then
         IHXENB=23
         ihxenr=ihxenb+1
         open(unit=ihxenb,file='xenomorph.blue.dat',status='old')
         open(unit=ihxenr,file='xenomorph.red.dat',status='old')
         write(6,"(' -----------'/
     *       ' reading XENOMORPH tables; ihxen =',2i3,/
     *       ' -----------')") ihxenb,ihxenr
       else
         return
      end if
c
C ---------------------------------
C     read  tables - blue wing
C ---------------------------------
C
      ILINE=0
      READ(IHXENB,*) NTAB
      DO ITAB=1,NTAB
         ILINEB=ILINE
         READ(IHXENB,*) NLXEN
         DO ILI=1,NLXEN
            ILINE=ILINE+1
            READ(IHXENB,*) I,J,ALMIN,ANEMIN,TMIN,DLA,DLE,DLT,
     *                  NWL,NE,NT
            XNEMIN=ANEMIN
            ILXEN(I,J)=ILINE
            NWLXEN(ILINE)=NWL
            NTHXEN(ILINE)=NT
            NEHXEN(ILINE)=NE
            DO IWL=1,NWL
               ALXEN(ILINE,IWL)=ALMIN+(IWL-1)*DLA
            END DO
            DO INE=1,NE
               XNEXEN(INE,ILINE)=ANEMIN+(INE-1)*DLE
            END DO
            DO IT=1,NT
               XTXEN(IT,ILINE)=TMIN+(IT-1)*DLT
            END DO
         END DO
c
         DO ILI=1,NLXEN
            ILNE=ILINEB+ILI
            NWL=NWLXEN(ILNE)
            READ(IHXENB,"(1X)")
            DO INE=1,NEHXEN(ILNE)
               DO IT=1,NTHXEN(ILNE)
                  READ(IHXENB,*) QLT,(PRFXB(ILNE,IWL,IT,INE),IWL=1,NWL)
               END DO
            END DO
C
         END DO
      END DO
      CLOSE(IHXENB)
C
C ---------------------------------
C     read  tables - red wing
C ---------------------------------
C
      ILINE=0
      READ(IHXENR,*) NTAB
      DO ITAB=1,NTAB
         ILINEB=ILINE
         READ(IHXENR,*) NLXEN
         DO ILI=1,NLXEN
            ILINE=ILINE+1
            READ(IHXENR,*) I,J,ALMIN,ANEMIN,TMIN,DLA,DLE,DLT,
     *                  NWL,NE,NT
         END DO
c
         DO ILI=1,NLXEN
            ILNE=ILINEB+ILI
            NWL=NWLXEN(ILNE)
            READ(IHXENR,*)
            DO INE=1,NEHXEN(ILNE)
               DO IT=1,NTHXEN(ILNE)
                  READ(IHXENR,*) QLT,(PRFXR(ILNE,IWL,IT,INE),IWL=1,NWL)
               END DO
            END DO
C
         END DO
      END DO
      CLOSE(IHXENR)
C
      RETURN
      END SUBROUTINE XENINI
C
C
C     ****************************************************************
C
C

      SUBROUTINE GOMINI
C     =================
C
C     Initialization and reading of the opacity table for thermal processe
C     and Rayleigh scattering
c     raytab: scattering opacities in cm^2/gm at 5.0872638d14 Hz (sodium D)
c     (NOTE: Quantities in rayleigh.tab are in log_e)
C
c     tempvec: array of temperatures
c     nu:     array of frequencies
c     table:  absorptive opacities in cm^2/gm
c     (NOTE:  Quantities in absorption.tab are in log_e)
C
      use accura
      use basics
      use modelq
      use hyglin
      
      implicit none

      REAL(DP), allocatable ::  absort(:),frlt(:)

      REAL(DP) :: xint,frg1,frg2,rc,hcs,eneev
      INTEGER  :: it,k,i,ij,jl,ju,jm,j,ir
c
      if(ihgom.eq.0) return
C
      open(unit=53,file='gomhyd.dat',status='old')
c
      read(53,*) nugfreq,nugtemp,nugele
c
c     allocate arrays
c
      allocate (absort(mfhtab),frlt(mfhtab))

      ALLOCATE (TEMVEC(NUGTEMP),ELEVEC(NUGELE),FRGTAB(NUGFREQ))
      ALLOCATE (HYDCRS(NUGTEMP,NUGELE,NUGFREQ))
      ALLOCATE (YGINT(MFREQ),JGINT(MFREQ))
      ALLOCATE (ABSORT(NUGFREQ),FRLT(NUGFREQ))

      read(53,*)
      read(53,*) (temvec(i),i=1,nugtemp)
      read(53,*)
      read(53,*) (elevec(j),j=1,nugele)
      do it=1,nugtemp
         temvec(it)=log(temvec(it)*1.161e4)
      end do
c     write(6,"(' ihgom,nugfr,nugt,nuge ',4i4)") ihgom,nugfreq,nugtemp,nugele
c
      EGTAB1 = elevec(1)
      EGTAB2 = elevec(nugele)
      TGTAB1 = temvec(1)
      TGTAB2 = temvec(nugtemp)
c
      do k = 1, nugfreq
         read(53,"(40x,f17.14)") eneev
         frgtab(k)=3.28805e15/13.595*eneev
         frlt(k)=log10(frgtab(k))
         do i = 1, nugtemp
            read(53,*) (hydcrs(i,j,k),j=1,nugele)
         end do
      end do
      close(53)
c
      FRGTB1 = log10(frgtab(1))
      FRGTB2 = log10(frgtab(nugfreq))
c
c     interpolate HYDCRS from tabular to actual frequencies
c
c     set up interpolation coefficients for frequency interpolation
c     by bisection
c
      frg1=frgtab(1)
      frg2=frgtab(nugfreq)
      do ij=1,nfreq
         jgint(ij)=0
         xint=freq(ij)
         if(xint.ge.frg1.and.xint.le.frg2) then
            jl=0
            ju=nugfreq+1
            do while (ju-jl.gt.1) 
               jm=(ju+jl)/2
               if((frg2.gt.frg1).eqv.(xint.gt.frgtab(jm))) then
                  jl=jm
                else
                  ju=jm
               end if
            end do
            j=jl
            if(j.eq.nugfreq) j=j-1
            if(j.eq.0) j=j+1
            jgint(ij)=j
            ygint(ij)=un/log10(frgtab(j+1)/frgtab(j))
         end if
      end do
c
      do it=1,nugtemp
         do ir=1,nugele
            do k=1,nugfreq
               absort(k)=log(hydcrs(it,ir,k))
            end do
            do ij=1,nfreq
               j=jgint(ij)
               hydcrs(it,ir,ij)=0.
               if(j.gt.0) then
                  rc=(absort(j+1)-absort(j))*ygint(ij)
                  hcs=rc*log10(freq(ij)/frgtab(j))+absort(j)
                  hydcrs(it,ir,ij)=hcs
               end if
            end do
         end do
      end do
c
      DEALLOCATE (ABSORT,FRLT)
      RETURN
      END SUBROUTINE GOMINI
C
C
C     ****************************************************************
C
C

      subroutine hygini
c     =================
c
      use accura
      use atomic
      use basics
      use hyglin
      use modelq

      implicit none

      real(dp), parameter :: con=3.28805e15/13.59
      integer, parameter  :: ing=16, ins=17
      character(len=40) filen
 
      REAL(DP), allocatable ::  absort(:),frlt(:),frntab(:),gcr0(:)

      REAL(DP) :: frg1,frg2,xnint,rc,hcs,hcr
      INTEGER  :: nlinn,ilnn,ios,iatom,izz,ilo,iu,iat,iatp,ion,ionp,
     *            n0i,ii,jj,itr,item,it,ir,k,ij,j,jl,ju,jm,iele,i

c
c     read table(s)
c
      nlinn=0
      ilnn=0
c     open(ing,file='tg_spe',status='old',iostat=ios)
      open(unit=16,file='tg_spe',status='old',action='read',iostat=ios)
c      write(*,*) ' ios in hygini',ios
      if(ios.ne.0) return

      ALLOCATE (HYGCRS(MLINN,MTABTN,MTABEN,MFREQ))
      ALLOCATE (HYGCR0(MLINN,MTABTN,MTABEN,MFHTAB))
      ALLOCATE (YNINT(MFREQ,MLINN))
      ALLOCATE (JNINT(MFREQ,MLINN))

      allocate (frntab(mfhtab),absort(mfhtab),frlt(mfhtab),
     *          gcr0(mfhtab))

      rd: do
         read(ing,*,iostat=ios)  iatom,izz,ilo,iu,filen
c        write(*,*) ' ios2 in hygini',ios
         if(ios.ne.0) exit rd
         iatp=0
         do iat=1,natom
            if(numat(iat).eq.iatom) iatp=iat
         end do
         if(iatp.eq.0) cycle rd
   
         ionp=0
         do ion=1,nion
            if(iz(ion).eq.izz.and.iati(ion).eq.iatom) ionp=ion
         end do
         if(ionp.eq.0) cycle rd

         n0i=nfirst(ionp)
         ii=n0i+ilo-1
         jj=n0i+iu-1
         itr=itra(ii,jj)
         if(indexp(itr).eq.0) cycle rd

         close(ins)
         ilnn=ilnn+1
         nlinn=ilnn
         iprof(itr)=10+ilnn
c
         write(6,"(/'**** The transition ',i2,' to ',i2,' of atom',
     *   i3,', Z = ',i2/'     Tlusty indices ii=',i3,'  jj=',i3,
     *   ' itr = ',i6,' lambda ',f10.2,' A'/
     *   'is treated with Gomez Stark profile'/)") 
     *   ilo,iu,iatom,izz,ii,jj,itr,2.997925e18/fr0(itr)

c        write(*,*) 'IPROF',iprof(itr)

         open(ins,file=filen,status='old')
         read(ins,*,iostat=ios) nuntem(ilnn),nunele(ilnn),nunfreq(ilnn)
         if(ios.ne.0) cycle rd
         read(ins,*) (temn(i,ilnn),i=1,nuntem(ilnn))
         read(ins,*) (elen(i,ilnn),i=1,nunele(ilnn))
         do iele=1,nunele(ilnn)
            elen(iele,ilnn)= log(10.**elen(iele,ilnn))
         end do
         do item=1,nuntem(ilnn)
            temn(item,ilnn)=log(temn(item,ilnn))
         end do

c        write(*,*) 'ilnn',ilnn,nuntem(ilnn),nunele(ilnn)
         ENTAB1(ilnn) = elen(1,ilnn)
         ENTAB2(ilnn) = elen(nunele(ilnn),ilnn)
         TNTAB1(ilnn) = temn(1,ilnn)
         TNTAB2(ilnn) = temn(nuntem(ilnn),ilnn)
c
c        write(*,*) 'ILNN',entab1(ilnn),tntab1(ilnn),fr0(itr),con
c        write(63,*) 'ILNN',entab1(ilnn),tntab1(ilnn),fr0(itr),con
         do it=1,nuntem(ilnn)
            do ir=1,nunele(ilnn)
               do k = 1, nunfreq(ilnn)
CCC               read(ins,*,iostat=ios) frntab(k),gcrnd,gcr0(k)
                  read(ins,*,iostat=ios) frntab(k),gcr0(k)
                  if(ios.ne.0) cycle rd
                  frntab(k)=con*frntab(k)+fr0(itr)
                  if(frntab(k).le.0.) frntab(k)=1.e15*float(k)
                  frlt(k)=log(frntab(k))
c             if(ir.eq.nunele(ilnn)) write(63,"(3i6,1p2e12.4)")
c    *         it,ir,k,frntab(k),gcr0(k)
          
               end do
c
c              interpolate GCR0 from tabular to actual frequencies
c
c              set up interpolation coefficients for
c              frequency interpolation by bisection
c
               frg1=frntab(1)
               frg2=frntab(nunfreq(ilnn))
               do ij=1,nfreq
                  jnint(ij,ilnn)=0
                  xnint=freq(ij)
                  if(xnint.ge.frg1.and.xnint.le.frg2) then
                    jl=0
                     ju=nunfreq(ilnn)+1
                     do while (ju-jl.gt.1)
                        jm=(ju+jl)/2
                        if((frg2.gt.frg1).eqv.(xnint.gt.frntab(jm)))
     *                  then
                           jl=jm
                         else
                           ju=jm
                        end if
                     end do
                     j=jl
                     if(j.eq.nunfreq(ilnn)) j=j-1
                     if(j.eq.0) j=j+1
                     jnint(ij,ilnn)=j
                     ynint(ij,ilnn)=un/log(frntab(j+1)/frntab(j))
                  end if
               end do

               do k=1,nunfreq(ilnn)
                  hcr=max(gcr0(k),1.e-19)
                  absort(k)=log(hcr)
               end do
               do ij=1,nfreq
                  j=jnint(ij,ilnn)
                  hygcrs(ilnn,it,ir,ij)=-40.
                  if(j.gt.0) then
                     rc=(absort(j+1)-absort(j))*ynint(ij,ilnn)
                     hcs=rc*log(freq(ij)/frntab(j))+absort(j)
                     hygcrs(ilnn,it,ir,ij)=hcs
c      if(ilnn.eq.1.and.it.eq.nuntem(ilnn).and.ir.eq.nunele(ilnn).
c    * and.ij.ge.308.and.ij.le.4042)
c    * write(63,"(4i5,1p2e12.4)") 
c    * ij,j,it,ir,freq(ij),hygcrs(ilnn,it,ir,ij)
                  end if
               end do
            end do
         end do
         close(ins)
      end do rd
      close(ing)
c
      RETURN
      END
C
C
C     ****************************************************************
C
C

      subroutine tglini
c     =================
c
      use accura
      use atomic
      use basics
      use hyglin

      implicit none

      integer, parameter  :: ing=16, ins=17
      real(dp), parameter :: temtran=11605.
      real(dp)            :: gmm(mlilor),shf(mlilor)
      character(len=30)   :: filemi,filemr
      INTEGER  :: nlnlor,ilnlor,ios,iat,iatp,iatom,izz,ionp,ion,i
      INTEGER  :: ilo,iu,ii,jj,itr,n0i,itemm,nlem
c
c     read table(s)
c
      nlnlor=0
      ilnlor=0
c
c     read the file specifying filenames for line widths and shifts
c
      open(unit=ing,file='tg_lor',status='old',iostat=ios)
c      write(*,*) ' ios in tglini',ios
      if(ios.ne.0) return

      ALLOCATE (TEMM(MTELOR),GAMM(MLILOR,MTELOR),SHIF(MLILOR,MTELOR))

      rd: do
         read(ing,*,iostat=ios)  iatom,izz,filemi,filemr
c      write(*,*) ' ios2 in tglini',ios
         if(ios.ne.0) exit rd

         iatp=0
         do iat=1,natom
            if(numat(iat).eq.iatom) iatp=iat
         end do
         if(iatp.eq.0) cycle rd

         ionp=0
         do ion=1,nion
c           write(*,*) 'ion',ion,iz(ion),izz,iati(ion),iatom
            if(iz(ion).eq.izz.and.iati(ion).eq.iatom) ionp=ion
         end do
c        ionp=1
         if(ionp.eq.0) cycle rd
c
c     read the Mi file - line widths
c
         open(ins,file=filemi,status='old')
         read(ins,*) nlem,ntemm
         read(ins,*) (temm(i),i=1,ntemm)
         do i=1,ntemm
            temm(i)=temm(i)*temtran
         end do

         rdgm: do
            read(ins,*,iostat=ios) ilo,iu,(gmm(itemm),itemm=1,ntemm)
            if(ios.ne.0) exit rdgm
            n0i=nfirst(ionp)
            ii=n0i+ilo-1
            jj=n0i+iu-1
            itr=itra(ii,jj)
            if(indexp(itr).eq.0) cycle rdgm
            ilnlor=ilnlor+1
            nlnlor=ilnlor
            iprof(itr)=50+ilnlor
            do itemm=1,ntemm
               gamm(ilnlor,itemm)=abs(gmm(itemm))
            end do
c
            write(6,"(/'**** The transition ',i2,' to ',i2,' of atom',
     *      i3,', Z = ',i2/'     Tlusty indices ii=',i3,'  jj=',i3,
     *      ' itr = ',i6,' lambda ',f10.2,' A'/
     *      'is treated with Gomez Lorentz profile'/)") 
     *      ilo,iu,iatom,izz,ii,jj,itr,2.997925e18/fr0(itr)

         end do rdgm
         close(ins)
c
c     read Mr file - line shifts
c
         open(ins,file=filemr,status='old',iostat=ios)
      
         rdsh: do
            read(ins,*,iostat=ios) 
     *           ilo,iu,(shf(i),i=1,ntemm)
            if(ios.ne.0) exit rdsh
            n0i=nfirst(ionp)
            ii=n0i+ilo-1
            jj=n0i+iu-1
            itr=itra(ii,jj)
            if(indexp(itr).eq.0) cycle rdsh
            ilnlor=iprof(itr)-50
            do itemm=1,ntemm
               shif(ilnlor,itemm)=shf(itemm)
            end do
 
            write(6,"(/'**** The transition ',i2,' to ',i2,' of atom',
     *      i3,', Z = ',i2/'     Tlusty indices ii=',i3,'  jj=',i3,
     *      ' itr = ',i6,' lambda ',f10.2,' A'/
     *      'is treated with Gomez Lorentz profile'/)") 
     *      ilo,iu,iatom,izz,ii,jj,itr,2.997925e18/fr0(itr)
         end do rdsh

         close(ins)
      end do rd

      return
      end subroutine tglini
