      SUBROUTINE INTLEM(PRFH,WL0,ILINE,ID)
C     ====================================
C
      use accura
      use basics
      use modelq
      use hyglin

      implicit none 
       
      REAL(DP), INTENT(IN) :: WL0
      INTEGER, INTENT(IN)  :: ILINE,ID
      REAL(DP), INTENT(OUT) :: PRFH(90)
      REAL(DP), PARAMETER  :: FOC1=1.25e-9,TTW=2./3.,VTBC=6.06e-9
      REAL(DP) :: T,ANE,TL,ANEL,F00,FXK,DOP,PRFH0
      INTEGER  :: NWL,IWL
C
C     temperature is modified in order to account for the
C     effect of turbulent velocity on the Doppler width
C
      T=TEMP(ID)+VTBC*VTURBS(ID)*VTURBS(ID)
      ANE=ELEC(ID)
      TL=LOG10(T)
      ANEL=LOG10(ANE)
      F00=FOC1*EXP(TTW*LOG(ANE))
      XK=XK0(ILINE)
      FXK=F00*XK
      DOP=1.E8/WL0*SQRT(1.65E8*T)
      DBETA=WL0*WL0/2.997925E18/FXK
      BETAD=DBETA*DOP
C
C     interpolation to the actual values of temperature and electron
C     density
C
      NWL=NWLHYD(ILINE)
      DO IWL=1,NWL
         CALL INTHYD(PRFH0,TL,ANEL,IWL,ILINE)
         PRFH(IWL)=PRFH0
      END DO
      RETURN
      END SUBROUTINE INTLEM
C
C
C     ****************************************************************
C
C

      SUBROUTINE INTXEN(W0B,W0R,X0,Z0,IWL,ILINE,ID)
C     =============================================
C
C     Interpolation in temperature and electron density from the
C     Xenomorph tables for hydrogen lines to the actual valus of
C     temperature and electron density
C
      use accura
      use basics
      use modelq
      use hyglin

      implicit none

      REAL(DP), INTENT(IN)   :: X0,Z0
      REAL(DP), INTENT(OUT)  :: W0B,W0R
      INTEGER,  INTENT(IN)   :: IWL,ILINE,ID
      REAL(DP), DIMENSION(3) :: ZZ,XX,WXB,WZB,WXR,WZR
      REAL(DP)               :: YINT
      INTEGER  :: ID1,NX,NZ,NT,NE,IZZ,IPZ,N0Z,N1Z,I0Z,IPX,N0X,N1X,IX,I0
C
      id1=id
      NX=2
      NZ=2
      NT=NTHXEN(ILINE)
      NE=NEHXEN(ILINE)
C
      DO IZZ=1,NE-1
         IPZ=IZZ
         IF(Z0.LE.XNEXEN(IZZ+1,ILINE)) EXIT
      END DO
      N0Z=IPZ-NZ/2+1
      IF(N0Z.LT.1) N0Z=1
      IF(N0Z.GT.NE-NZ+1) N0Z=NE-NZ+1
      N1Z=N0Z+NZ-1
C
      DO IZZ=N0Z,N1Z
         I0Z=IZZ-N0Z+1
         ZZ(I0Z)=XNEXEN(IZZ,ILINE)
         DO IX=1,NT-1
            IPX=IX
            IF(X0.LE.XTXEN(IX+1,ILINE)) EXIT
         END DO
         N0X=IPX-NX/2+1
         IF(N0X.LT.1) N0X=1
         IF(N0X.GT.NT-NX+1) N0X=NT-NX+1
         N1X=N0X+NX-1
         DO IX=N0X,N1X
            I0=IX-N0X+1
            XX(I0)=XTXEN(IX,ILINE)
            WXB(I0)=PRFXB(ILINE,IWL,IX,IZZ)
            WXR(I0)=PRFXR(ILINE,IWL,IX,IZZ)
         END DO
         WZB(I0Z)=YINT(XX,WXB,X0)
         WZR(I0Z)=YINT(XX,WXR,X0)
      END DO
      W0B=YINT(ZZ,WZB,Z0)
      W0R=YINT(ZZ,WZR,Z0)
      RETURN
      END SUBROUTINE INTXEN
C
C
C     ****************************************************************
C
C

      SUBROUTINE INTHYD(W0,X0,Z0,IWL,ILINE)
C     =====================================
C
C     Interpolation in temperature and electron density from the
C     Lemke tables for hydrogen lines to the actual valus of
C     temperature and electron density
C
      use accura
      use basics
      use modelq
      use hyglin

      implicit none

      REAL(DP), INTENT(IN)  :: X0,Z0
      REAL(DP), INTENT(OUT) :: W0
      INTEGER, INTENT(IN)   :: IWL,ILINE
      REAL(DP),DIMENSION(3) :: ZZ,XX,WX(3),WZ
      REAL(DP) :: BETA,STARKA,YINT,WXMIN
      INTEGER  :: NX,NZ,NT,NE,IZH,IZZ,IPZ,N0Z,N1Z,IX,IPX,N0X,N1X,I0,I0Z
C
      NX=2
      NZ=2
      NT=NTH(ILINE)
      NE=NEH(ILINE)
      BETA=WLH(IWL,ILINE)/XK
      IZH=1
C
C     for values lower than the lowest grid value of electron density
C     the profiles are determined by the approximate expression
C     (see STARKA); not by an extrapolation in the HYD tables which may
C     be very inaccurate
C
      IF(Z0.LT.XNELEM(1,ILINE)*0.99) THEN
         CALL DIVSTR(IZH)
         W0=STARKA(BETA,TWO)*DBETA
         W0=LOG10(W0)
         RETURN
      END IF
C
C     Otherwise, one interpolates (or extrapolates for higher than the
C     highes grid value of electron density) in the HYD tables
C
      DO IZZ=1,NE-1
         IPZ=IZZ
         IF(Z0.LE.XNELEM(IZZ+1,ILINE)) EXIT
      END DO
      N0Z=IPZ-NZ/2+1
      IF(N0Z.LT.1) N0Z=1
      IF(N0Z.GT.NE-NZ+1) N0Z=NE-NZ+1
      N1Z=N0Z+NZ-1
C
      DO IZZ=N0Z,N1Z
         I0Z=IZZ-N0Z+1
         ZZ(I0Z)=XNELEM(IZZ,ILINE)
C
C     Likewise, the approximate expression instead of extrapolation
C     is used for higher that the highest grid value of temperature,
C     if the Doppler width expressed in beta units (BETAD) is
C     sufficiently large (> 10)
C
C        IF(X0.GT.1.01*XTLEM(NT,ILINE).AND.BETAD.GT.10.) THEN
         IF(X0.GT.1.01*XTLEM(NT,ILINE)) THEN
            CALL DIVSTR(IZH)
            W0=STARKA(BETA,TWO)*DBETA
            W0=LOG10(W0)
            RETURN
         END IF
C
C     Otherwise, normal inter- or extrapolation
C
C     Both interpolations (in T as well as in electron density) are
C     by default the quadratic interpolations in logarithms
C
         DO IX=1,NT-1
            IPX=IX
            IF(X0.LE.XTLEM(IX+1,ILINE)) EXIT
         END DO
         N0X=IPX-NX/2+1
         IF(N0X.LT.1) N0X=1
         IF(N0X.GT.NT-NX+1) N0X=NT-NX+1
         N1X=N0X+NX-1
         WXMIN=0.
         DO IX=N0X,N1X
            I0=IX-N0X+1
            XX(I0)=XTLEM(IX,ILINE)
            WX(I0)=PRFHYD(ILINE,IWL,IX,IZZ)
            IF(WX(I0).LT.WXMIN) WXMIN=WX(I0)
         END DO
         IF(WXMIN.LT.-99.) THEN
            CALL DIVSTR(IZH)
            W0=STARKA(BETA,TWO)*DBETA
            W0=LOG10(W0)
            RETURN
          ELSE
            WZ(I0Z)=YINT(XX,WX,X0)
         END IF
      END DO
      W0=YINT(ZZ,WZ,Z0)
      RETURN
      END SUBROUTINE INTHYD
C
C
C     ****************************************************************
C
C

      SUBROUTINE GHYDOP(IJ)
C     =====================
c
c     hydrogen opacity -lines + pseudocontinuum from Gomez tables
c
      use accura
      use atomic
      use basics
      use modelq
      use hyglin

      implicit none

      integer, intent(in) :: ij
      real(dp) :: rl,tl,deltar,r1i,r2i,dri,deltat,t1i,t2i,dti
      real(dp) ::  opr1,opr2,opc,ab,oph
      integer  :: jf,id,jr,jt,ii
c
      if(ihgom.eq.0) return
      if(jgint(ij).eq.0) return
      jf=ij
      do id=1,nd
         if(elec(id).lt.HGLIM) cycle
         rl=log(elec(id))
         tl=log(temp(id))
c
         DELTAR=(RL-EGTAB1)/(EGTAB2-EGTAB1)*FLOAT(nugele-1)
         JR = 1 + IDINT(DELTAR)
         IF(JR.LT.1) JR = 1
         IF(JR.GT.(nugele-1)) JR = nugele-1
         r1i=elevec(jr)
         r2i=elevec(jr+1)
         dri=(RL-R1i)/(R2i-R1i)
         if(JR .eq. 1) dri = 0.d0
C
         DELTAT=(TL-TGTAB1)/(TGTAB2-TGTAB1)*FLOAT(nugtemp-1)
         JT = 1 + IDINT(DELTAT)
         IF(JT.LT.1) JT = 1
         IF(JT.GT.nugtemp-1) JT = nugtemp-1
         t1i=temvec(jt)
         t2i=temvec(jt+1)
         dti=(TL-T1i)/(T2i-T1i)
         if(JT .eq. 1) dti = 0.d0
C
         opr1=hydcrs(jt,jr,jf)+dti*
     *        (hydcrs(jt+1,jr,jf)-hydcrs(jt,jr,jf))
         opr2=hydcrs(jt,jr+1,jf)+dti*
     *        (hydcrs(jt+1,jr+1,jf)-hydcrs(jt,jr+1,jf))
         opc=opr1+dri*(opr2-opr1)
         ab = exp(opc)*0.0265*4.1347e-15
c
         if(freq(ij).gt.8.22013e14) then
            ii=nfirst(ielh)
          else
            ii=nfirst(ielh)+1
         end if
c
         oph=ab*popul(ii,id)*g(ii)
         abso1(id)=abso1(id)+oph
         emis1(id)=emis1(id)+oph*xkfb(id)/xkf1(id)
      end do
c
      return
      end subroutine ghydop
C
C
C     ****************************************************************
C
C

      SUBROUTINE GHYGOP(IJ,ID,ILNN,CRS)
C     =================================
c
c     hydrogenic line opacity - from Gomez tables
c
      use accura
      use basics
      use hyglin
      use modelq

      implicit none

      integer, intent(in)   :: ij,id,ilnn
      real(dp), intent(out) :: crs
      real(dp) :: rl,tl,deltar,deltat,r1i,r2i,dri,t1i,t2i,dti,opr1,opr2
      real(dp) :: opc
      integer  :: jf,nunel,nunte,jr,jt
c
      crs=0.
c      if(id.eq.1) write(*,*) 'hgygop',id,ij,ilnn,jnint(ij,ilnn)
      if(jnint(ij,ilnn).eq.0) return
      jf=ij
      nunel=nunele(ilnn)
      nunte=nuntem(ilnn)
c      if(id.eq.1) write(*,*) 'hgygop',id,ij,j,ilnn,jnint(j,ilnn)
       if(elec(id).GE.HGLIM) then
         rl=log(elec(id))
         tl=log(temp(id))
         if(rl.lt.elen(1,ilnn)) rl=elen(1,ilnn)
         if(rl.gt.elen(nunel,ilnn)) rl=elen(nunel,ilnn)
         if(tl.lt.temn(1,ilnn)) tl=temn(1,ilnn)
         if(tl.gt.temn(nunte,ilnn)) tl=temn(nunte,ilnn)
c
         DELTAR=(RL-ENTAB1(ILNN))/(ENTAB2(ILNN)-ENTAB1(ILNN))*
     *          FLOAT(nunel-1)
         JR = 1 + IDINT(DELTAR)
         IF(JR.LT.1) JR = 1
         IF(JR.GT.(nunel-1)) JR = nunel-1
         r1i=elen(jr,ilnn)
         r2i=elen(jr+1,ilnn)
         dri=(RL-R1i)/(R2i-R1i)
         if(JR .eq. 1) dri = 0.d0
C
         DELTAT=(TL-TNTAB1(ILNN))/(TNTAB2(ILNN)-TNTAB1(ILNN))*
     *          FLOAT(nunte-1)
         JT = 1 + IDINT(DELTAT)
         IF(JT.LT.1) JT = 1
         IF(JT.GT.nunte-1) JT = nunte-1
         t1i=temn(jt,ilnn)
         t2i=temn(jt+1,ilnn)
         dti=(TL-T1i)/(T2i-T1i)
         if(JT .eq. 1) dti = 0.d0
C
         opr1=hygcrs(ilnn,jt,jr,jf)+dti*
     *        (hygcrs(ilnn,jt+1,jr,jf)-hygcrs(ilnn,jt,jr,jf))
         opr2=hygcrs(ilnn,jt,jr+1,jf)+dti*
     *        (hygcrs(ilnn,jt+1,jr+1,jf)-hygcrs(ilnn,jt,jr+1,jf))
         opc=opr1+dri*(opr2-opr1)
         crs=exp(opc)*4.13467e-15
c        if(ij.eq.1540.or.ij.eq.1) write(*,*) ij,id,crs
      end if
c     if(id.eq.60.and.ilnn.eq.1.and.jf.ge.3982.and.jf.le.4042) then
c        write(63,"(i7,i3,3f7.2,i3,3f7.2,4f7.2,2x,5f6.3)")
c    *   jf,jr,rl,elen(jr,ilnn),elen(jr+1,ilnn),
c    *   jt,tl,temn(jt,ilnn),temn(jt+1,ilnn),
c    *   hygcrs(ilnn,jt,jr,jf),hygcrs(ilnn,jt,jr+1,jf),
c    *   hygcrs(ilnn,jt+1,jr,jf),hygcrs(ilnn,jt+1,jr+1,jf),
c    *   dri,dti,opr1,opr2,opc
c     end if
c
      return
      end subroutine ghygop
C
C
C     ****************************************************************
C
C

      REAL(DP) FUNCTION PROFSP(FR,DOP,ITR,ID)
C     =======================================
C
C     Non-standard absorption profile - normalized to unity;
C     a user supplied procedure
C
C     Input:
C     FR  - frequency
C     A   - Voigt damping parameter
C     DOP - Doppler width
C     ITR - transition index
C     ID  - depth index
C
      use accura
      use atomic
      use basics
      use modelq

      implicit none

      REAL(DP), INTENT(IN) :: FR,DOP
      INTEGER, INTENT(IN)  :: ITR,ID
      REAL(DP) :: SIJ,ZMIKRO,CH,CH32,CORRE,BETA,UBETA,SIGST,AGAMS,AGAM
      REAL(DP) :: AA,V,SIGVT,SGA,VOIGT
      INTEGER  :: IP,II,JJ,IAT,IE,I,ION,N0I,NKI
C
      PROFSP=0.
      IP=IPROF(ITR)
C
C     Klaus Werner's Voigt+Stark wing profile (formula A.3.4)
C
      IF(ABS(IP).NE.12) RETURN

C     1- Stark wings

      II=NQUANT(ILOW(ITR))
      JJ=NQUANT(IUP(ITR))
      SIJ=JJ*(JJ-1)+II*(II-1)
C
C     Micro-field
C
      ZMIKRO=0.
      DO IAT=1,NATOM
         N0I=N0A(IAT)
         NKI=NKA(IAT)
         DO I=N0I,NKI-1
            IE=IEL(I)
            CH=IZ(IE)-1
            CH32=CH*SQRT(CH)
            ZMIKRO=ZMIKRO+CH32*POPUL(I,ID)
         END DO
         CH=REAL(IZ(IEL(I)))+UN
         CH32=CH*SQRT(CH)
         ZMIKRO=ZMIKRO+CH32*POPUL(NKI,ID)
      END DO
      CALL SABOLF(ID)
      DO ION=1,NION
         CH=IZ(ION)-1
         CH32=CH*SQRT(CH)
         ZMIKRO=ZMIKRO+CH32*USUM(ION)
      END DO
      ZMIKRO=ZMIKRO**0.6666667
C
      IAT=IATM(ILOW(ITR))
      IE=IEL(ILOW(ITR))
      CH=IZ(IE)
      DBETA=1.385*CH/SIJ/ZMIKRO
C
C     empirical correction in PRO2
C
      CORRE=UN
      IF(IE.EQ.IELHE2 .AND.ILOW(ITR).GT.(NFIRST(IE)+1))
     *   CORRE=HALF
      IF(IAT.NE.IATH .AND. IAT.NE.IATHE) THEN
         CORRE=UN/(CH-UN)
      END IF
      DBETA=DBETA/CORRE
C
      BETAD=DOP*DBETA
      BETA=DBETA*ABS(FR-FR0(ITR))
      SIGST=UBETA(BETA)*BETAD

C     2- Voigt profile

      AGAMS=5.E-5*ELEC(ID)/SQRT(TEMP(ID))*JJ*JJ/CH/CH
      AGAM=2.47342D-22*FR*FR+AGAMS
      AA=AGAM/12.56637/DOP
      V=(FR-FR0(ITR))/DOP
      SIGVT=VOIGT(V,AA)/1.77245385090551D0
      SGA=SIGVT
      IF(SIGST.GT.SIGVT) SGA=SIGST
      PROFSP=SGA
      RETURN
      END FUNCTION PROFSP
C
C
C     ****************************************************************
C
C
      REAL(DP) FUNCTION UBETA(BETA)
C     =============================
C
C **********************************************************************
C ***
C *** CALLED BY: SUBROUTINE PROFSP
C *** CALLS:     SUBROUTINE LAGRAN
C ***
C *** Interpolation of function U(beta) in table from Dien (ApJ 109,452)
C ***
C **********************************************************************

      use accura
      implicit none

      REAL(DP), INTENT(IN) :: BETA
      REAL(DP)             ::  B0(46),U0(46)
      INTEGER              :: I
C
      DATA (B0(I),U0(I),I= 1,46) /
     1 0.0,.287,0.1,.286,0.2,.283,0.3,.278,0.4,.271,0.5,.262,0.6,.252,
     1 0.7,.240,0.8,.228,0.9,.215,1.0,.202,1.1,.188,1.2,.174,1.3,.161,
     1 1.4,.148,1.5,.135,1.6,.124,1.7,.113,1.8,.1024,1.9,.0928,
     1 2.0,.0839,2.1,.0758,2.2,.0684,2.3,.0617,2.4,.0557,2.5,.0502,
     1 2.6,.0454,2.7,.0411,2.8,.0373,2.9,.0338,3.0,.0310,3.2,.0260,
     1 3.4,.0220,3.6,.0187,3.8,.0160,4.0,.0238,4.2,.0120,4.4,.0104,
     1 4.6,.0091,4.8,.0080,5.0,.0071,6.0,.0041,7.0,.0027,8.0,.0018,
     1 9.0,.0014,10.0,.0011/
C
C *** asymptotic value
C
      IF(BETA.GT.10.) THEN
         UBETA=0.2992*BETA**(-2.5)
       ELSE
C *** Interpolation
C
         DO I=3,46
            IF (BETA.LT.B0(I)) EXIT
         END DO
         CALL LAGRAN (B0(I-2),B0(I-1),B0(I),U0(I-2),U0(I-1),
     *                U0(I), BETA,UBETA)
      END IF
      RETURN
      END FUNCTION UBETA
C
C
C     ****************************************************************
C
C
      SUBROUTINE LAGRAN(X0,X1,X2,Y0,Y1,Y2,X,Y)
C     =========================================
C
C ***
C *** Lagrange interpolation for three points
C ***
      use accura
      implicit none
      
      REAL(DP), INTENT(IN) :: X0,X1,X2,Y0,Y1,Y2,X
      REAL(DP), INTENT(OUT):: Y
      REAL(DP)             :: XL0,XL1,XL2
C
      XL0=(X-X1)*(X-X2)/(X0-X1)/(X0-X2)
      XL1=(X-X0)*(X-X2)/(X1-X0)/(X1-X2)
      XL2=(X-X0)*(X-X1)/(X2-X0)/(X2-X1)

      Y=Y0*XL0+Y1*XL1+Y2*XL2

      RETURN
      END SUBROUTINE LAGRAN

