C
C     ****************************************************************
C
C

      SUBROUTINE LYMLIN(IJ)
C     =====================
C
C     opacity and emissibvity in first 30 Lyman lines
C
      use accura
      use atomic
      use basics
      use modelq

      implicit none
C
      REAL(DP), PARAMETER :: SIXTH=1./6.,TTW=2./3.,
     *           OS0=0.02654,CPP=4.1412E-16,CPJ=157803.,
     *           C00=1.25E-9,C18=2.997925E18
      INTEGER, PARAMETER :: MLEVL=30
      INTEGER, INTENT(IN):: IJ
C
      REAL(DP) :: ABLYM(MDEPTH),EMLYM(MDEPTH),
     *          XKIJL(MLEVL),FIJL(MLEVL),WL0L(MLEVL),FR0L(MLEVL),
     *          F00(MDEPTH),DOP0(MDEPTH),PJ(MLEVL,MDEPTH),
     *          ABTR(MLEVL,MDEPTH),EMTR(MLEVL,MDEPTH),FID(MLEVL,MDEPTH),
     *          AD0(MLEVL,MDEPTH),DIV0(MLEVL,MDEPTH),
     *          DBET0(MLEVL,MDEPTH),BETAD0(MLEVL,MDEPTH)

      REAL(DP) :: FR,XII,XKIJ0,WL00,FIJ0,T,T1,SQT,ANE,P0,P1,X,XJJ
      REAL(DP) :: DOP,BETA,FXK,WL,F15,SG,XKT,XKB,STARKA
      INTEGER  :: INIP,J,JJ,N0H,N1H,NKH,NLH,ID
C
      DATA INIP/1/
C
      IF(IELH.EQ.0) RETURN
C
      FR=FREQ(IJ)
      IF(FR.GT.3.28805E15.OR.FR.LT.1.5E15) RETURN
C
      IF(INIP.EQ.1) THEN
         N0H=NFIRST(IELH)
         N1H=NLAST(IELH)
         NKH=NNEXT(IELH)
         NLH=N1H-N0H
         XII=1.
         DO J=2,30
            CALL STARK0(1,J,1,XKIJ0,WL00,FIJ0)
            XKIJL(J)=XKIJ0
            FIJL(J)=FIJ0
            WL0L(J)=WL00
            FR0L(J)=C18/WL0L(J)
         END DO
         DO ID=1,ND
            T=TEMP(ID)
            T1=1./T
            SQT=SQRT(T)
            ANE=ELEC(ID)
            ANP=POPUL(NKH,ID)
            F00(ID)=C00*ANE**TTW
            DOP0(ID)=1.E8*SQRT(1.65E8*T+VTURB(ID))
C
            P0=CPP*ANE*ANP*T1/SQT
            P1=POPUL(N0H,ID)
            DO J=2,30
               X=J*J
               JJ=N0H+J-1
               XJJ=1./JJ
               IF(J.LE.NLH) THEN
                  PJ(J,ID)=POPUL(JJ,ID)
                ELSE
                  PJ(J,ID)=P0*EXP(CPJ/(X*T))*X*WNHINT(J,ID)
               END IF
               ABTR(J,ID)=P1*WNHINT(J,ID)
               EMTR(J,ID)=PJ(J,ID)*XJJ*EXP(CPJ*(XII-XJJ)*T1)
C
               FXK=F00(ID)*XKIJL(J)
               DBETA=WL0L(J)*WL0L(J)/(C18*FXK)
               FID(J,ID)=OS0*FIJL(J)*DBETA
               DOP=DOP0(ID)/WL0L(J)
               BETAD=DOP*DBETA
               CALL DIVSTR(1)
               AD0(J,ID)=ADH
               DIV0(J,ID)=DIVH
               DBET0(J,ID)=DBETA
               BETAD0(J,ID)=BETAD
           END DO
        END DO
        INIP=0
      END IF
C
      FR=FREQ(IJ)
      WL=C18/FR
      F15=FR*1.E-15
      DO ID=1,ND
         ABLYM(ID)=0.
         EMLYM(ID)=0.
         DO J=2,30
            BETA=DBET0(J,ID)*ABS(FR-FR0L(J))
            BETAD=BETAD0(J,ID)
            ADH=AD0(J,ID)
            DIVH=DIV0(J,ID)
            SG=STARKA(BETA,TWO)*FID(J,ID)
            ABLYM(ID)=ABLYM(ID)+SG*ABTR(J,ID)
            EMLYM(ID)=EMLYM(ID)+SG*EMTR(J,ID)
         END DO
         XKT=EXP(-4.79928e-11*FR/TEMP(ID))
         XKB=XKT*1.4743E-2*F15*F15*F15
         ABLYM(ID)=ABLYM(ID)-XKT*EMLYM(ID)
         EMLYM(ID)=XKB*EMLYM(ID)
         ABSO1(ID)=ABSO1(ID)+ABLYM(ID)
         EMIS1(ID)=EMIS1(ID)+EMLYM(ID)
      END DO
      RETURN
      END SUBROUTINE LYMLIN
C
C
C     ****************************************************************
C
C

      REAL(DP) FUNCTION VOIGT(V,AGAM)
C     =========---------=============
C
C     Voigt function
C     Procedure after Matta and Reichel, 1971, Math.Comp. 25, 339.
C
      use accura
      implicit none

      REAL(DP), INTENT(IN):: V,AGAM
      REAL(DP), SAVE      :: HN(12),EN(12)
      REAL(DP), PARAMETER :: PI=3.141592653589793,HH=0.5,UN=1.
      REAL(DP), PARAMETER :: PISQ=1.77245385090551,PISQ1=UN/PISQ
      REAL(DP), PARAMETER :: HP=HH*PISQ1,PH=PI/HH
      INTEGER, PARAMETER  :: M=12
      INTEGER  :: ICOMP,I
      REAL(DP) :: XI,U,AGAM1,X,T,X2,X4,S1,S2,U0,S0,A,B,TSQ1,C,D,T4
      DATA ICOMP /0/ 
C
C     Initialization of auxiliary quantities
C
      IF(ICOMP.EQ.0) THEN
         DO I=1,M
            XI=FLOAT(I)
            U=XI*XI*HH*HH
            EN(I)=EXP(-U)
            HN(I)=4.*U
         END DO
         ICOMP=1
      END IF
C
C     Main term
C
      AGAM1=UN/AGAM
      X=V*AGAM1
      T=0.25D0*AGAM1*AGAM1
      X2=X*X
      X4=4.D0*X2
      S1=UN+X2
      S2=UN-X2
      U0=0.
      DO I=1,M
         S0=HN(I)*T
         U=EN(I)/((S2+S0)*(S2+S0)+X4)
         U0=U0+U*(S1+S0)
      END DO
      S2=UN/S1
      U0=HP*(S2+2.D0*U0)
C
C     Correction term
C
      IF(T.GE.0.25/(PH*PH)) THEN
         U=X/2./T
         A=COS(U)
         B=SIN(U)
         TSQ1=UN/SQRT(T)
         S1=PH*TSQ1
         S2=S1*X
         C=EXP(-S1)-COS(S2)
         D=SIN(S2)
         T4=0.25D0/T
         U=EXP(-X2*T4-S1+T4)*PISQ*TSQ1/(C*C+D*D)
         U0=U0+U*(A*C-B*D)
      END IF
C
      VOIGT=U0*AGAM1*PISQ1
      RETURN
      END FUNCTION VOIGT
C
C
C     ****************************************************************
C
C


      REAL(DP) FUNCTION YINT(XL,YL,XL0)
C     =================================
C
C     Quadratic interpolation routine
C
C     Input:  XL - array of x
C             YL - array of f(x)
C             XL0 - the point x(0) to which one interpolates
C
      use accura
      implicit none

      REAL(DP),INTENT(IN) :: XL(3),YL(3),XL0
      REAL(DP) :: A0,A1,A2,A3

      A0=(XL(2)-XL(1))*(XL(3)-XL(2))*(XL(3)-XL(1))
      A1=(XL0-XL(2))*(XL0-XL(3))*(XL(3)-XL(2))
      A2=(XL0-XL(1))*(XL(3)-XL0)*(XL(3)-XL(1))
      A3=(XL0-XL(1))*(XL0-XL(2))*(XL(2)-XL(1))
      YINT=(YL(1)*A1+YL(2)*A2+YL(3)*A3)/A0
      RETURN
      END FUNCTION YINT
