      subroutine dkini
c     ================
c
c     Initializes necessary arrates for evaluating hydrogen Lyman alpha
c     and beta line profiles from the tables adopted from Detlev Koester's
c     program ATMDK
c
      use accura
      use dktabl

      implicit none
  
      integer :: ntab,itb
      character(len=40) dkfile(5)
      data dkfile/'./data/ly_alpha_hh.tab',
     *            './data/ly_alpha_hp.tab',
     *            './data/ly_alpha_h2.tab',
     *            './data/ly_beta_hh.tab',
     *            './data/ly_beta_hp.tab'/

      allocate (tabden(mtab,mden),tabtem(mtab,mtem,mden),
     *          tablam(mtab,mlam,mden),prftab(mtab,mlam,mtem,mden))
      allocate (nden(mtab),numtem(mtab,mden),numlam(mtab,mden))

c
      ntab=5
      write(*,*)
      do itb=1,ntab
         call initab(itb,dkfile(itb))
c        write(*,*) 'reading Koester table:',dkfile(itab)
      end do
      return
      end subroutine dkini

C
C     ********************************************************************
C


      subroutine initab(itab,tabfile)
c     ===============================
c
c     initializes one particular Koester's table for hydrogen

      use accura
      use dktabl
      implicit none
  
      character(len=72)             :: inpline
      character(len=40), intent(in) :: tabfile
      integer, intent(in)           :: itab
      integer :: iun,i,item,iden,ilam
c
      iun=61
      open(iun,file=tabfile)
      write(*,*) 'reading DK table ',tabfile
      do i=1,100
         read(iun,'(a)') inpline
         if (inpline(1:3).eq.'END'.or.inpline(5:7).eq.'---') exit
      end do

      read(iun,*) nden(itab)
      do iden=1,nden(itab)
         read(iun,*) tabden(itab,iden),numlam(itab,iden),
     *               numtem(itab,iden),
     *               (tabtem(itab,item,iden),item=1,numtem(itab,iden))
        do ilam=1,numlam(itab,iden)
            read(iun,*) tablam(itab,ilam,iden),
     *      (prftab(itab,ilam,item,iden),item=1,numtem(itab,iden))
        end do
      end do
      close(iun)
      return
      end subroutine initab
C
C     ********************************************************************
C

      subroutine dkprof(itab,wl0,tt0,dd0,prof)
c     ========================================
c
      use accura
      use dktabl

      implicit none
  
      integer, intent(in)   :: itab
      real(dp), intent(in)  :: wl0,tt0,dd0
      real(dp), intent(out) :: prof

      real(dp) :: tabdei(mden),wl1(mlam),tl1(mtem)
      real(dp) :: denlog,fd,fd1,fd2,fl,fl1,fl2,ft,ft1,ft2,pr11,pr12,pr1,
     *            pr21,pr22,pr2
      integer  :: ndei,item,iden,jd,jd1,jd2,ilam,jl,jl1,jl2,jt1,jt2,jt
c
      denlog=log10(dd0)
      ndei=nden(itab)
      do iden=1,ndei
         tabdei(iden)=tabden(itab,iden)
      end do
      call locat(tabdei,ndei,denlog,jd,fd)
      jd1=jd
      jd2=jd1+1
      fd2=fd
      fd1=1.-fd2
c
c     lower density point
c
      prof=1.e-40
      do ilam=1,numlam(itab,jd1)
         wl1(ilam)=tablam(itab,ilam,jd1)
      end do
      if(wl0.lt.wl1(1).or.wl0.gt.wl1(numlam(itab,jd1))) return
      call locat(wl1,numlam(itab,jd1),wl0,jl,fl)
      jl1=jl
      jl2=jl1+1
      fl2=fl
      fl1=1.-fl2
      do item=1,numtem(itab,jd1)
         tl1(item)=tabtem(itab,item,jd1)
      end do
      call locat(tl1,numtem(itab,jd1),tt0,jt,ft)
      jt1=jt
      jt2=jt1+1
      ft2=ft
      ft1=1.-ft2
      pr11=fl1*prftab(itab,jl1,jt1,jd1)+fl2*prftab(itab,jl2,jt1,jd1)
      pr12=fl1*prftab(itab,jl1,jt2,jd1)+fl2*prftab(itab,jl2,jt2,jd1)
      pr1=ft1*pr11+ft2*pr12
c
c     upper density point
c
      do ilam=1,numlam(itab,jd2)
         wl1(ilam)=tablam(itab,ilam,jd2)
      end do
      call locat(wl1,numlam(itab,jd2),wl0,jl,fl)
      jl1=jl
      jl2=jl1+1
      fl2=fl
      fl1=1.-fl2
      do item=1,numtem(itab,jd2)
         tl1(item)=tabtem(itab,item,jd2)
      end do
      call locat(tl1,numtem(itab,jd2),tt0,jt,ft)
      jt1=jt
      jt2=jt1+1
      ft2=ft
      ft1=1.-ft2
      pr21=fl1*prftab(itab,jl1,jt1,jd2)+fl2*prftab(itab,jl2,jt1,jd2)
      pr22=fl1*prftab(itab,jl1,jt2,jd2)+fl2*prftab(itab,jl2,jt2,jd2)
      pr2=ft1*pr21+ft2*pr22
c
      prof=fd1*pr1+fd2*pr2+denlog-18.
      prof=10.**prof
      return
      end subroutine dkprof

C
C     ********************************************************************
C

      subroutine lalpdk(wl,t,ane,anp,anh,anh2,prof)
c     =============================================
c
c     Lyman alpha profile using DK tables
c
      use accura
      use dktabl
      use hyglin
      use basics, only: igcomb

      implicit none
  
      real(dp), intent(in)  :: wl,t,ane,anp,anh,anh2
      real(dp), intent(out) :: prof
      real(dp), parameter   :: con=1215.67**2*88.53*0.4162*1.e-30
      real(dp) :: profhh,profhp,profh2,profe,dl,zz,ff,alp
c
c
c     broadening by neutral hydrogen
      call dkprof(1,wl,t,anh,profhh)

c     broadening by protons
      call dkprof(2,wl,t,anp,profhp)

c     broadening by H2
      if(anh2.gt.1.e-10*anh) call dkprof(3,wl,t,anh2,profh2)

c     broadening by electrons (after DK)
      profe=0.
      if(igcomb.eq.0) then
      dl=abs(wl-1215.67)
      zz=7862.67*dl/t
      zz=0.5+0.5*(zz-1.)/(zz+1.)
      ff=1.254e-9*ane**0.666667
      alp=log10(max(dl/ff,1.04194e-3))
      profe=1.34896/3.*exp(2.3025851*3.0039-5.7565*alp)/ff
      end if
c
c     total profile
c
      prof=profhh+profhp+profh2+profe
      prof=prof*con
      return
      end subroutine lalpdk

C
C     ********************************************************************
C

      subroutine lbetdk(wl,t,ane,anp,anh,prof)
c     ========================================
c
c     Lyman beta profile using DK tables
c
      use accura
      use dktabl
      use hyglin
      use basics, only: igcomb

      implicit none
  
      real(dp), intent(in)  :: wl,t,ane,anp,anh
      real(dp), intent(out) :: prof
      real(dp), parameter   :: con=1025.73**2*88.53*0.0791*1.e-30
      real(dp) :: profhh,profhp,profe,dl,ff,alp

c     broadening by neutral hydrogen
      call dkprof(4,wl,t,anh,profhh)

c     broadening by protons
      call dkprof(5,wl,t,anp,profhp)

c     broadening by electrons (after DK)
      profe=0.
      if(igcomb.eq.0) then
      dl=abs(wl-1025.73)
      ff=1.254e-9*ane**0.666667
      alp=log10(max(dl/ff,1.5258e-3))
      profe=exp(2.3025851*3.25358-5.7565*alp)/ff
      end if
c
c     total profile
c
      prof=profhh+profhp+profe
      prof=prof*con
      return
      end subroutine lbetdk

C
C     ********************************************************************
C

      SUBROUTINE locat(xx,n,x,j,a)
c     ============================
c
      use accura
      implicit none
  
      integer, intent(in)  :: n
      integer, intent(out) :: j
      real(dp), intent(in) :: xx(n),x
      real(dp), intent(out):: a

      integer              :: jl,ju,jm
c
      jl=0
      ju=n+1
      do while (ju-jl.gt.1)
        jm=(ju+jl)/2
        if((xx(n).gt.xx(1)).eqv.(x.ge.xx(jm)))then
          jl=jm
        else
          ju=jm
        endif
      end do
      if(x.le.xx(1)) then
        j=1
        a=0.
       else if(x.ge.xx(n)) then
        j=n-1
        a=1.
       else
        j=jl
        a=(x-xx(j))/(xx(j+1)-xx(j))
      endif
      return
      END SUBROUTINE LOCAT

