C     ****************************************************************
C
C
      SUBROUTINE PZEVAL
C     =================
C     
C     Auxiliary procedure called from RESOLV
C     determination of the total and gas pressures, and logarithmic
C     gradient of pressure
C         
      use accura
      use alipar
      use basics
      use modelq
      
      implicit none
      
      real(dp) :: PTURB,PGSN,PTOTL0,PTOTL1,PGS1,AAA
      integer  :: IPPZEV,ID
C        
C     total pressure, gas pressure, and logarithmic gradient DELTA
C      
      ippzev=1
      IF(IPPZEV.GT.0) WRITE(6,"(/'  ID   PTOT-SUM  PTOT-MG   PGAS-RHO',
     *   '  PGAS-P    PRAD       A'/)")
      DO ID=1,ND
         PTURB=HALF*DENS(ID)*VTURB(ID)*VTURB(ID)
         PGSN=(DENS(ID)/WMM(ID)+ELEC(ID))*BOLK*TEMP(ID)
         PTOTL0=PGSN+PRADT(ID)+PTURB
         PTOTL1=GRAV*DM(ID)+PRADT(1)-PRD0
         PGS1=PTOTL1-PTURB-PRADT(ID)
         AAA=3.0*PRADT(ID)/TEMP(ID)**4/7.5639e-15
         if(idisk.eq.0) then
            PTOTAL(ID)=PTOTL1
            PGS(ID)=PGS1
          else
            PTOTAL(ID)=PTOTL0
            PGS(ID)=PGSN
         end if
         IF(IPPZEV.GT.0) WRITE(6,"(I4,1p6e10.3)") 
     *     ID,PTOTL0,PTOTL1,PGSN,PGS1,PRADT(ID),AAA
      END DO
      IF(HMIX0.LT.0.) RETURN
      IF(IPPZEV.GT.0) THEN
         WRITE(6,"(/'pzev:CONVECTIVE FLUX: RESOLV; GLOBAL ITERATION =',
     *   I2/)") ITER-1
         WRITE(6,"(/'pzev:CONVECTIVE FLUX: RESOLV; GLOBAL ITERATION =',
     *   I2/)") ITER-1
         CALL CONOUT(1,IPCONF)
      END IF
c     if(iconre.gt.0.and.iter.le.iconre.and.iter.ge.iconrs) call conref
      IF(IPPZEV.EQ.0.AND.LFIN) THEN
         WRITE(6,"(/'pzev:CONVECTIVE FLUX: RESOLV; GLOBAL ITERATION =',
     *   I2/)") ITER-1
         CALL CONOUT(1,1)
      END IF
      RETURN
      END SUBROUTINE PZEVAL
